--[[--------------------------------------------------------------------------
	A small mock of the WoW UI API, enough to load AetherUI end to end outside the
	game and drive it through a realistic session.

	This is not a re-implementation of WoW. It exists to catch the class of bug
	you cannot see by reading: nil field access, methods that do not exist on the
	widget type you used, ordering problems between files, anchors referencing
	regions that were not built yet.

	Run:  lua5.1 Tools/harness.lua
----------------------------------------------------------------------------]]

local FAIL = {}

-- Refusals counted separately as well as failed. A blocked call already
-- fails the suite, but a check that wants to say "this path blocks
-- NOTHING" needs a number it can read before and after rather than a
-- line in the log it cannot see.
_G.__blocked = 0

local function fail(msg)
	FAIL[#FAIL + 1] = msg
	if tostring(msg):find("ADDON BLOCKED", 1, true) then
		_G.__blocked = _G.__blocked + 1
	end
	print("  !! " .. msg)
end

-- ---------------------------------------------------------------------------
-- widget mock
-- ---------------------------------------------------------------------------

local time = 1000.0
local cursorX, cursorY = 500, 400

local function widgetBase(kind)
	local o = {
		__kind = kind,
		__points = {},
		__scripts = {},
		__shown = true,
		__alpha = 1,
		__scale = 1,
		__w = 0, __h = 0,
		__children = {},
		__regions = {},
	}

	--- Does anchoring to `rel` mean anchoring to ourselves, round the houses?
	--
	--  THE CLIENT REFUSES THIS AND SAYS SO: "Cannot anchor to a region
	--  dependent on it", a real error with a real stack. The mock accepted it
	--  silently, which is how a loop shipped: the vendor's two repair buttons
	--  were anchored one off the other in OUR direction, and the client's own
	--  MerchantFrame_UpdateRepairButtons - which anchors them the other way
	--  round, on every merchant update - threw the moment a vendor opened.
	--
	--  BOUNDED, because a chain that already loops would hang this walk rather
	--  than report it, and a mock that hangs is worse than one that is kind.
	local function anchorsBackTo(rel, me)
		local seen, hops = {}, 0
		local queue = { rel }
		while #queue > 0 and hops < 64 do
			local f = table.remove(queue)
			hops = hops + 1
			if f == me then return true end
			if type(f) == "table" and not seen[f] then
				seen[f] = true
				for _, pt in ipairs(f.__points or {}) do
					if pt[2] then queue[#queue + 1] = pt[2] end
				end
			end
		end
		return false
	end

	function o:SetPoint(p, rel, relP, x, y)
		if type(p) ~= "string" then fail(kind .. ":SetPoint got non-string point " .. tostring(p)) end
		if rel and rel ~= self and anchorsBackTo(rel, self) then
			fail(("ANCHOR LOOP: %s:SetPoint(%q, %s) - cannot anchor to a"
				.. " region dependent on it"):format(
				tostring(self.__name or self.__kind), p,
				tostring(rel.__name or rel.__kind)))
		end
		if rel == self then
			fail(("ANCHOR LOOP: %s:SetPoint(%q) anchored to itself"):format(
				tostring(self.__name or self.__kind), p))
		end
		self.__points[#self.__points + 1] = { p, rel, relP, x or 0, y or 0 }
	end
	function o:GetPoint(i)
		local pt = self.__points[i or 1]
		if not pt then return nil end
		return pt[1], pt[2], pt[3], pt[4], pt[5]
	end
	-- HOW MANY, which is how you tell a region that was re-anchored from one
	-- that was anchored AGAIN. A FontString keeps whatever anchors it was last
	-- given, so a corner set without clearing the old one leaves the region
	-- spanned between two corners - and every getter still answers about the
	-- first of them, which looks exactly like it worked.
	function o:GetNumPoints() return #self.__points end
	function o:ClearAllPoints() self.__points = {} end
	-- TWO REAL POINTS, which is what the client reports for one of these. A
	-- pseudo-point of its own reads as "no anchors I can reason about", so
	-- anything that walks a frame's points to nudge it - moving a pane in from
	-- the edge of a panel, say - skipped every frame laid out this way.
	function o:SetAllPoints(other)
		self.__points = {
			{ "TOPLEFT", other, "TOPLEFT", 0, 0 },
			{ "BOTTOMRIGHT", other, "BOTTOMRIGHT", 0, 0 },
		}
	end


	-- Resizing FIRES OnSizeChanged, as the client does. Without this a pill
	-- never lays out in a test: Glass.CreatePill hangs its cap arithmetic off
	-- that script and calls it once at creation, when the frame is still 0x0 -
	-- so every pill in the suite was a zero-size shape that no assertion could
	-- see the geometry of. A vertical rail rendering as one enormous circle
	-- went through the whole suite unnoticed for exactly that reason.
	local function sized(self, ow, oh)
		if self.__w == ow and self.__h == oh then return end
		local fn = self.__scripts and self.__scripts.OnSizeChanged
		if fn then fn(self, self.__w or 0, self.__h or 0) end
	end
	function o:SetSize(w, h)
		local ow, oh = self.__w, self.__h
		self.__w, self.__h = w, h
		sized(self, ow, oh)
	end
	function o:SetWidth(w)
		local ow = self.__w
		self.__w = w
		sized(self, ow, self.__h)
	end
	function o:SetHeight(h)
		local oh = self.__h
		self.__h = h
		sized(self, self.__w, oh)
	end
	-- SetAllPoints really does size the frame, so a mock that ignored that would
	-- report 0 for anything that fills its parent. Resolved lazily rather than
	-- copied, so a later resize of the parent still propagates.
	-- TWO POINTS TO THE SAME FRAME, corner to corner, IS filling it - which is
	-- what the client reports for SetAllPoints and what this now records.
	local function allTarget(self)
		local a, b = self.__points[1], self.__points[2]
		if not (a and b) or #self.__points ~= 2 then return nil end
		if a[1] ~= "TOPLEFT" or b[1] ~= "BOTTOMRIGHT" then return nil end
		if a[2] ~= b[2] or a[2] == self then return nil end
		if a[3] ~= "TOPLEFT" or b[3] ~= "BOTTOMRIGHT" then return nil end
		if (a[4] or 0) ~= 0 or (a[5] or 0) ~= 0 then return nil end
		if (b[4] or 0) ~= 0 or (b[5] or 0) ~= 0 then return nil end
		return a[2]
	end

	-- A size the frame was never GIVEN, worked out from its anchors.
	--
	-- A region pinned by two opposing edges - TOPLEFT and BOTTOMRIGHT to a
	-- parent, BOTTOMLEFT and BOTTOMRIGHT to a tile - has a real width in the
	-- client and had none in here: GetWidth returned the zero it was born with.
	-- So "does this text fit its box" was a question the harness could not ask,
	-- and two overflow bugs shipped past checks that read that zero and passed -
	-- the What's new card drawing through its own Notes link, and a settings
	-- tile's label running out of the tile and into the column beside it. Both
	-- had to be re-checked by recomputing the width from the anchors in the test,
	-- which is the mock's job and not the test's.
	--
	-- The SAME-FRAME case only: both anchors relative to one other frame, which
	-- is what a SetPoint pair almost always is. A region pinned between two
	-- DIFFERENT frames needs their absolute positions, and that is a layout
	-- engine rather than a mock - it stays at zero, deliberately, rather than
	-- being guessed at.
	--
	-- An explicit size always wins. Only frames that never got one change
	-- behaviour, which keeps this from quietly rewriting the geometry every
	-- other test in the file is built on.
	local AXES = {
		x = { lo = "LEFT",   hi = "RIGHT", off = 4, get = "GetWidth"  },
		y = { lo = "BOTTOM", hi = "TOP",   off = 5, get = "GetHeight" },
	}

	--- Where an anchor point sits on one axis of a frame `size` across, measured
	--  from its low edge - so LEFT and BOTTOM are 0, RIGHT and TOP are the full
	--  size, and anything else (CENTER, or the other axis's word) is the middle.
	local function edgeOf(point, axis, size)
		if point:find(axis.lo, 1, true) then return 0 end
		if point:find(axis.hi, 1, true) then return size end
		return size / 2
	end

	local function fromAnchors(self, which)
		local axis = AXES[which]
		local lo, hi
		for _, pt in ipairs(self.__points) do
			local p = pt[1]
			if type(p) == "string" then
				if p:find(axis.lo, 1, true) then
					lo = lo or pt
				elseif p:find(axis.hi, 1, true) then
					hi = hi or pt
				end
			end
		end
		if not (lo and hi) then return nil end

		local rel = lo[2]
		if rel == nil or rel ~= hi[2] or type(rel[axis.get]) ~= "function" then
			return nil
		end
		local size = rel[axis.get](rel)
		if not size or size <= 0 then return nil end

		local a = edgeOf(lo[3] or lo[1], axis, size) + (lo[axis.off] or 0)
		local b = edgeOf(hi[3] or hi[1], axis, size) + (hi[axis.off] or 0)
		local span = b - a
		return span > 0 and span or nil
	end

	--- Re-entrancy guard rather than a depth count: a frame anchored to
	--  something that is anchored back to it would otherwise recurse until the
	--  stack ran out, and a stack overflow inside a getter is a miserable thing
	--  to diagnose. Second time round it reports nothing, which fails the
	--  `size > 0` test above and gives up cleanly.
	--
	--  NOT wrapped in a pcall. It was, and the pcall did the guard's job badly:
	--  a cycle still recursed all the way down, the overflow was caught, and the
	--  answer came back zero - so the guard could be deleted with every check
	--  still green. The guard is the mechanism; making it the only one is what
	--  lets a test prove it is there.
	local function derived(self, which, flag)
		if self[flag] then return nil end
		self[flag] = true
		local v = fromAnchors(self, which)
		self[flag] = nil
		return v
	end

	function o:GetWidth()
		local t = allTarget(self)
		if t then return t:GetWidth() end
		if self.__w and self.__w > 0 then return self.__w end
		return derived(self, "x", "__inWidth") or self.__w
	end
	function o:GetHeight()
		local t = allTarget(self)
		if t then return t:GetHeight() end
		if self.__h and self.__h > 0 then return self.__h end
		return derived(self, "y", "__inHeight") or self.__h
	end
	function o:GetSize() return self:GetWidth(), self:GetHeight() end
	-- Geometry getters report in the FRAME's own coordinate space, which is the
	-- whole point of the mover test below; __geom lets a test place a frame.
	function o:SetGeom(g) self.__geom = g end
	function o:GetCenter()
		local g = self.__geom
		return g and g.cx or 500, g and g.cy or 300
	end
	-- The other axis, resolved the same way and for the same reason: a skin
	-- that measures where a window's content starts across needs an answer that
	-- is not the same 100 for the window, a container filling it, and a button
	-- eleven units inside that.
	-- NOT ANYWHERE YET. ShowUIPanel clears a panel's anchors and places it
	-- AFTER its OnShow has run, so a window that has just told you it opened
	-- has no rect at all and every one of these answers nil. A mock that always
	-- had a number for them could not show a window laid out for a measurement
	-- that came back empty - which is what every panel in the deck looked like
	-- until the layout was run a second time.
	function o:GetLeft(depth)
		if self.__unplaced then return nil end
		if self.__geom then return self.__geom.left end
		depth = (depth or 0) + 1
		if depth > 12 then return 100 end

		local pt, rel, relPt, x = self:GetPoint(1)
		if not (pt and rel and rel ~= self and rel.GetLeft) then return 100 end
		-- A POINT WITH NO SIDE IN IT IS THE MIDDLE. TOP, BOTTOM and CENTER all
		-- name the horizontal CENTRE of the frame they are on, and this resolved
		-- them off its LEFT EDGE - so anything the client centres came back half
		-- a window to the left of where it draws. The book reader's page count
		-- reported as being left of its own turn-back button.
		local base
		if relPt and relPt:find("RIGHT") then
			base = rel.GetRight and rel:GetRight()
		elseif relPt and relPt:find("LEFT") then
			base = rel:GetLeft(depth)
		else
			local rl = rel:GetLeft(depth)
			base = rl and (rl + ((rel.GetWidth and rel:GetWidth()) or 0) / 2)
		end
		-- AND IT PROPAGATES. A frame anchored to one that is not anywhere is not
		-- anywhere either, and the client answers nil all the way down the chain.
		-- Falling back to a number here meant the GLASS had a position while the
		-- window it is pinned to did not, so nothing could tell a window that had
		-- not been placed yet from one that had.
		if not base then return nil end

		x = x or 0
		if pt:find("LEFT") then return base + x end
		local w = (self.GetWidth and self:GetWidth()) or 0
		if pt:find("RIGHT") then return base + x - w end
		return base + x - w / 2
	end
	-- The far edges follow from the near ones and the size. Constants here for
	-- a long time, which meant a frame, its parent and everything in it all
	-- reported the same right and the same bottom - so nothing that measures
	-- how wide or how deep a window's content actually runs could be wrong.
	function o:GetRight()
		if self.__unplaced then return nil end
		if self.__geom then return self.__geom.right end
		return (self:GetLeft() or 0) + (self:GetWidth() or 0)
	end
	function o:GetBottom()
		if self.__unplaced then return nil end
		if self.__geom then return self.__geom.bottom end
		return (self:GetTop() or 0) - (self:GetHeight() or 0)
	end

	-- THE ONE PIECE OF LAYOUT THIS MOCK DOES: how far down a frame's top edge
	-- is, resolved through whatever it is anchored to.
	--
	-- It answered a flat 400 for everything, which is the kindest possible lie:
	-- a skin that measures where a window's content begins - to move it clear of
	-- the header, say - got the same answer for the window, for a container
	-- filling it and for a button 74 down inside that, so nothing it worked out
	-- could ever be wrong here. The client resolves anchors; so does this now,
	-- for the top edge, which is the axis panel layout is about.
	function o:GetTop(depth)
		if self.__unplaced then return nil end
		if self.__geom then return self.__geom.top end
		depth = (depth or 0) + 1
		if depth > 12 then return 400 end

		local pt, rel, relPt, _, y = self:GetPoint(1)
		if not (pt and rel and rel ~= self and rel.GetTop) then return 400 end
		-- ...and the same on this axis: LEFT, RIGHT and CENTER all name the
		-- frame's vertical MIDDLE, not its top edge.
		local base
		if relPt and relPt:find("BOTTOM") then
			base = rel.GetBottom and rel:GetBottom()
		elseif relPt and relPt:find("TOP") then
			base = rel:GetTop(depth)
		else
			local rt = rel:GetTop(depth)
			base = rt and (rt - ((rel.GetHeight and rel:GetHeight()) or 0) / 2)
		end
		if not base then return nil end

		y = y or 0
		if pt:find("TOP") then return base + y end
		local h = (self.GetHeight and self:GetHeight()) or 0
		if pt:find("BOTTOM") then return base + y + h end
		return base + y + h / 2
	end

	-- Show and Hide really do run OnShow / OnHide, and a mock that swallows them
	-- cannot see a whole class of bug: anything that keeps external state in step
	-- with a frame's visibility - a micro button's lit state, a fader
	-- registration - hangs off exactly these two scripts, and ESC closing a frame
	-- goes through Hide() rather than through whatever asked for it.
	local function dispatch(self, script)
		local fn = self.__scripts[script]
		if not fn or self.__dispatching then return end
		self.__dispatching = true
		local ok, err = pcall(fn, self)
		self.__dispatching = false
		if not ok then fail(script .. ": " .. tostring(err)) end
	end
	function o:Show()
		local was = self.__shown
		self.__shown = true
		if not was then dispatch(self, "OnShow") end
	end
	function o:Hide()
		local was = self.__shown
		self.__shown = false
		if was then dispatch(self, "OnHide") end
	end
	function o:IsShown() return self.__shown end
	--- IsShown is the frame's OWN flag; IsVisible walks the parent chain.
	--
	--  The two are not the same question and conflating them hides a whole
	--  class of bug: hiding a window leaves every child's IsShown true, so
	--  "the child is still shown" is not evidence the child is on screen, and
	--  "the child is shown" is not evidence it is either. Bounded, because a
	--  parent cycle should fail the run rather than hang it.
	function o:IsVisible()
		local f, depth = self, 0
		while f do
			if not f.__shown then return false end
			f = f.__parent
			depth = depth + 1
			if depth > 64 then fail("IsVisible: parent chain loops") return false end
		end
		return true
	end
	function o:SetShown(v) self.__shown = v and true or false end

	function o:SetAlpha(a) self.__alpha = a end
	function o:GetAlpha() return self.__alpha end
	-- Counted, so a test can tell "set it to the right value" from "wrote to it
	-- again for no reason". SetScale re-lays out everything anchored to a frame.
	function o:SetScale(s)
		-- EVERY call, not every change. The question a caller wants answered is
		-- "did you touch this frame", and a counter that only moves when the
		-- value differs cannot tell a guard that skipped the write from one
		-- that wrote the same number back.
		self.__scaleWrites = (self.__scaleWrites or 0) + 1
		self.__scale = s
	end
	function o:GetScale() return self.__scale end

	--- EFFECTIVE scale walks the parent chain, as the client's does.
	--
	--  It used to return the frame's own scale and nothing more, which quietly
	--  flattened every scaled container in the UI: a badge inside a tooltip at
	--  0.71 reported 1, so anything converting "one physical pixel" into that
	--  badge's units got the same answer whether it converted or not - and a test
	--  asserting that it DID convert could not fail.
	--
	--  Depth-capped rather than trusted to terminate: a mock frame can be given
	--  any parent, including a cycle, and a stack overflow inside a getter is a
	--  miserable thing to diagnose.
	function o:GetEffectiveScale()
		local s, cur, depth = self.__scale or 1, self.__parent, 0
		while cur and depth < 16 do
			s = s * (cur.__scale or 1)
			cur = cur.__parent
			depth = depth + 1
		end
		return s
	end

	function o:SetID(id) self.__id = id end
	function o:GetID() return self.__id or 0 end
	-- PROTECTED IN COMBAT, on every frame - not just secure ones. This is not the
	-- Hide/Show restriction, which only bites a frame with a protected descendant;
	-- the client refuses this one outright and writes "attempted to call a
	-- protected function during combat lockdown" into the player's error log,
	-- naming our frame. The bag window shipped calling it from OnKeyDown and spat
	-- that line at nine consecutive keypresses in a fight, because this mock used
	-- to be a plain setter that never refused anything.
	--
	-- The value PERSISTS between events - it is not reset per keystroke - which is
	-- what makes the combat case survivable: a resting true carries every key we
	-- do not act on, so a handler has nothing to say in a fight.
	-- FALSE, because that is the client's default: a frame with
	-- EnableKeyboard(true) captures every key until it is explicitly told to
	-- pass them on. This mock said `true`, which agreed with a wrong assumption
	-- in A:SetPropagate and let the bag window ship swallowing every keypress -
	-- the suite asserted propagation was on and the mock had simply been born
	-- that way.
	o.__propagate = false
	function o:SetPropagateKeyboardInput(v)
		_G.__propagateCalls = (_G.__propagateCalls or 0) + 1
		if _G.__inCombat then
			fail(("ADDON BLOCKED: SetPropagateKeyboardInput() on %s - protected in"
				.. " combat, on any frame"):format(tostring(self.__name or self.__kind)))
			return
		end
		self.__propagate = v and true or false
	end
	-- Buttons are Frames, which is the check every button collector leans on.
	function o:GetObjectType() return self.__kind end
	function o:IsObjectType(t)
		return t == self.__kind or (t == "Frame" and self.__kind ~= "Texture"
			and self.__kind ~= "FontString")
	end
	function o:SetParent(p)
		local old = self.__parent
		if old and old.__children then
			for i, c in ipairs(old.__children) do
				if c == self then table.remove(old.__children, i) break end
			end
		end
		self.__parent = p
		if p and p.__children then p.__children[#p.__children + 1] = self end
	end
	function o:GetParent() return self.__parent end

	return o
end

-- ---------------------------------------------------------------------------
-- how the client reads a string
--
-- Colour codes and hyperlinks contribute no width and no characters; an inline
-- texture contributes its declared width and no characters. The one that
-- matters is the last case: `|T...|t` takes eleven arguments in every client,
-- and fourteen - the extra three being a vertex colour - in clients that
-- support tinting an inline texture. A client that does *not* fails by drawing
-- the whole escape as literal text, which is the failure Modules/Chat.lua
-- probes for. Flip MOCK_TEXTURE_VERTEX_COLOR to model the other client.
-- ---------------------------------------------------------------------------

MOCK_TEXTURE_VERTEX_COLOR = true

function MEASURE(text)
	local width = 0
	text = text:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
	text = text:gsub("|H.-|h(.-)|h", "%1")
	text = text:gsub("|T(.-)|t", function(body)
		local parts = {}
		for p in (body .. ":"):gmatch("([^:]*):") do parts[#parts + 1] = p end
		-- path + height + width + 8 more is the short form; three beyond that is
		-- the vertex colour. Unparsed markup stays in the string as text.
		if #parts > 11 and not MOCK_TEXTURE_VERTEX_COLOR then return nil end
		width = width + (tonumber(parts[3]) or 0)
		return ""
	end)
	return text, width
end

local function newTexture(owner, layer, sub)
	local t = widgetBase("Texture")
	t.__layer, t.__sub = layer, sub
	-- A REAL TEXTURE KNOWS WHOSE IT IS, and that matters more than it
	-- sounds: a child FRAME draws over every one of its parent's regions
	-- whatever draw layer they claim, so "is this mark above the disc it
	-- rides" is a question about the texture's owner. Without GetParent
	-- here the answer was nil and the check could not be written.
	t.__owner = owner
	function t:GetParent() return self.__owner end
	function t:SetDrawLayer(l, s2) self.__layer, self.__sub = l, s2 end
	function t:GetDrawLayer() return self.__layer, self.__sub end
	function t:SetTexture(path) self.__tex = path end
	function t:GetTexture() return self.__tex end
	--- Real, and missing until now - so every SetDesaturated in this addon was
	--  a pcall onto nothing and the junk drain had never once been checked.
	function t:SetDesaturated(on) self.__desaturated = on and true or false end
	function t:IsDesaturated() return self.__desaturated == true end
	-- A solid of a given colour. Real on this client - Blizzard's own colour
	-- picker and EditMode both call it - and it is how a plain scrim or divider
	-- is drawn without shipping a one-pixel .tga to do it.
	function t:SetColorTexture(r, g, b, a)
		if type(r) ~= "number" or type(g) ~= "number" or type(b) ~= "number" then
			fail("SetColorTexture got non-number (" .. tostring(r) .. ","
				.. tostring(g) .. "," .. tostring(b) .. ")")
		end
		self.__tex = "SOLID"
		self.__color = { r, g, b, a }
	end
	function t:GetTexCoord()
		local c = self.__texcoord or { 0, 1, 0, 1 }
		return c[1], c[2], c[3], c[4]
	end
	function t:SetTexCoord(a, b, c, d)
		self.__texcoord = { a, b, c, d }
		for _, v in ipairs({ a, b, c, d }) do
			if type(v) ~= "number" then fail("SetTexCoord got " .. tostring(v)) end
		end
		self.__coord = { a, b, c, d }
	end
	-- A nine-slice's pieces each round their own edges to the pixel grid unless
	-- this is turned off, which is what puts a bright or dark hairline exactly
	-- where the arc meets the straight edge.
	-- Recorded, not swallowed. Which way a chevron points is a real question
	-- with a real answer, and a no-op SetRotation makes "it rotated the art"
	-- unaskable - the module can record its intent and never reach the texture.
	function t:SetRotation(r) self.__rotation = r end
	function t:GetRotation() return self.__rotation or 0 end
	function t:SetSnapToPixelGrid(v) self.__snap = v end
	function t:SetTexelSnappingBias(v) self.__bias = v end
	function t:SetVertexColor(r, g, b, a)
		if type(r) ~= "number" or type(g) ~= "number" or type(b) ~= "number" then
			fail("SetVertexColor got non-number (" .. tostring(r) .. "," .. tostring(g) .. "," .. tostring(b) .. ")")
		end
		self.__color = { r, g, b, a }
	end
	function t:GetVertexColor()
		local c = self.__color or { 1, 1, 1, 1 }
		return c[1], c[2], c[3], c[4]
	end
	function t:SetBlendMode(m) self.__blend = m end
	-- RECORDED, like the other texture mock. A no-op here meant an action
	-- button could say "grey this out" and be answered by nothing at all,
	-- and no check could tell the difference.
	function t:SetDesaturated(on) self.__desaturated = on and true or false end
	function t:IsDesaturated() return self.__desaturated == true end
	function t:SetGradient(orient, c1, c2)
		if type(orient) ~= "string" then fail("SetGradient orientation " .. tostring(orient)) end
		if type(c1) ~= "table" then fail("SetGradient c1 not a colour object") end
	end
	--- Recorded, not just validated.
	--
	--  Whether a region is cut out with a mask or drawn as ordinary artwork is a
	--  real visual decision - a mask edge is the client's to anti-alias and it
	--  does that poorly, which is why the level badge draws its disc rather than
	--  masking it. A mock that only checked the argument's type could not answer
	--  "is this masked?", so a test asserting it is not was a test that could
	--  never fail.
	t.__masks = {}
	function t:AddMaskTexture(m)
		if not m or m.__kind ~= "MaskTexture" then fail("AddMaskTexture got " .. tostring(m and m.__kind)) end
		self.__masks[#self.__masks + 1] = m
	end
	function t:GetNumMaskTextures() return #self.__masks end
	return t
end

local function newFontString(owner, layer)
	local f = widgetBase("FontString")
	f.__layer = layer
	-- THE OWNER IS THE PARENT. A real FontString answers GetParent with the
	-- frame that created it, and the mock was answering nil - so an assertion
	-- that a string had been reparented could only ever be false, which reads
	-- as the code being wrong rather than the mock being silent.
	f.__parent = owner
	-- Real FontStrings and Textures both carry this. Anything drawn on top of
	-- another region in the same layer needs it, and a mock without it turns a
	-- legitimate call into a nil-index at draw time.
	function f:SetDrawLayer(l, sub) self.__layer, self.__sub = l, sub end
	function f:GetDrawLayer() return self.__layer, self.__sub end
	--- RETURNS NOTHING, deliberately, and neither does the font-object mock.
	--
	--  A real FontString does answer isValid. The mock refuses to, because
	--  Media:SetFont has now been wrong TWICE by trying to learn something from
	--  a return value - once reading a font object's (which is nil) and once
	--  caching a scratch FontString's (which came back false for Outfit on a
	--  real client and took the whole interface to Friz Quadrata). A mock that
	--  answers makes both of those look fine in here.
	--
	--  A face the client cannot load leaves the font UNCHANGED, which is what
	--  the client does and is the only signal that survives read-back.
	function f:SetFont(path, size, flags)
		if type(path) ~= "string" then fail("SetFont path " .. tostring(path)) return end
		if type(size) ~= "number" then fail("SetFont size " .. tostring(size)) return end
		if _G.__badFonts and _G.__badFonts[path] then return end
		-- An explicit font OVERRIDES the object, and keeps overriding it. This
		-- is the half of inheritance that stops a global remap reaching a
		-- string somebody has already styled by hand.
		self.__font = { path, size, flags }
	end
	-- Real FontStrings read back what they were set to. A mock that only
	-- records the write can't answer "and what size did this actually end up?",
	-- which is the only way to catch a role that silently doesn't apply.
	--- READ THROUGH TO THE OBJECT, which is what makes a font object worth
	--  having: change GameFontNormal and every string inheriting it follows,
	--  including ones created afterwards.
	--
	--  The mock used to COPY the object's font at assignment, so a later
	--  change to the object propagated to nothing - and a module that
	--  re-lettered the interface by remapping the client's font objects, the
	--  only way to reach a pooled string the client resets on every use,
	--  would have looked like it did nothing at all.
	function f:GetFont()
		local c = self.__font
		if not c then
			local o = self.__fontObject
			if type(o) == "table" and o.__font then c = o.__font end
		end
		if not c then return nil end
		return c[1], c[2], c[3]
	end
	--- A font OBJECT carries the face, and the string reads back through it -
	--  which is the whole point where SetFont is forbidden. It was on the edit
	--  box only, so a locked string looked like it had no way to be styled at
	--  all and the menu quietly kept Friz.
	function f:SetFontObject(o)
		-- BY NAME TOO. The real API takes a font object OR the name of one,
		-- and the string then reports that object's face and size through
		-- GetFont. The mock took only the object, so a string left the
		-- font unset - and anything reading the size back to preserve it
		-- saw nil and looked correct while having nothing to preserve.
		if type(o) == "string" then o = _G[o] or o end
		self.__fontObject = o
		-- And it CLEARS an explicit font, because assigning an object is how
		-- you give a string back to inheritance.
		self.__font = nil
	end
	function f:GetFontObject() return self.__fontObject end

	function f:SetText(s) self.__text = s end
	function f:GetText() return self.__text end
	function f:GetName() return self.__name end
	-- RECORDED, not swallowed. These were no-ops, so any code that set a
	-- justification could be checked only by reading the anchor beside it and
	-- hoping the two agreed - and the one place they have to agree is a readout
	-- that moves from one corner of the screen to the other.
	function f:SetJustifyH(j) self.__justifyH = j end
	function f:GetJustifyH() return self.__justifyH end
	function f:SetJustifyV(j) self.__justifyV = j end
	function f:GetJustifyV() return self.__justifyV end
	-- Recorded, not swallowed: the shadow under type is skin-dependent (a dark
	-- shadow under dark ink on a white panel is a smudge), and a mock that
	-- forgets it cannot see that.
	function f:SetShadowColor(r, g, b, a) self.__shadow = { r, g, b, a } end
	function f:GetShadowColor()
		local c = self.__shadow or { 0, 0, 0, 0 }
		return c[1], c[2], c[3], c[4]
	end
	function f:SetShadowOffset(x, y) self.__shadowOffset = { x, y } end
	function f:GetShadowOffset()
		local o = self.__shadowOffset or { 0, 0 }
		return o[1], o[2]
	end
	function f:SetTextColor(r, g, b, a)
		if type(r) ~= "number" then fail("SetTextColor got " .. tostring(r)) end
		self.__color = { r, g, b, a }
	end
	function f:GetTextColor()
		local c = self.__color or { 1, 1, 1, 1 }
		return c[1], c[2], c[3], c[4]
	end
	--- RECORDED, not swallowed. Whether a label wraps or is cut at its right
	--  edge is a layout decision with two different right answers in this UI -
	--  a tile laid out as a row wants two lines, the same tile stacked under its
	--  own icon must not have them - and a no-op mock cannot tell them apart.
	function f:SetWordWrap(v) self.__wordWrap = v and true or false end
	function f:GetWordWrap() return self.__wordWrap ~= false end
	function f:SetVertexColor() end
	-- crude but proportional: enough for layout maths to be exercised.
	--
	-- Markup is modelled rather than counted, because Modules/Chat.lua asks this
	-- function a real question: it probes whether this client's inline texture
	-- escape takes the three vertex-colour arguments by rendering the same badge
	-- with and without them and comparing widths. Counting characters would
	-- answer "no" on a client that supports it perfectly well, and a mock that
	-- answers a probe wrongly is worse than no mock at all.
	-- A FONT STRING WITH NO WIDTH OF ITS OWN IS THE WIDTH OF ITS STRING.
	--
	--  SetWidth(0) on one of these is not "zero wide", it is "size yourself to
	--  what you say" - and GetWidth then answers with the string's extent. The
	--  mock answered a literal 0, which is kinder and makes a whole class of
	--  check impossible to write: cutting a 104-wide box down to its words and
	--  having no text at all both came back as nought.
	local baseWidth = f.GetWidth
	function f:GetWidth()
		local w = baseWidth(self)
		if (w or 0) > 0 then return w end
		return self:GetStringWidth()
	end

	function f:GetStringWidth()
		local size = (self.__font and self.__font[2]) or 11
		local text, textures = MEASURE(self.__text or "")
		local full = textures + #text * size * 0.52
		-- CLAMPED by a width that was set, when wrapping is off.
		--
		-- A FontString given a width and told not to wrap draws a truncated
		-- string, and what it then reports is at most that width. Reporting the
		-- untruncated extent regardless is the kinder answer and it hides a real
		-- bug: code that measures a label to decide whether a shorter form is
		-- needed, having clamped that same label last time round, gets the full
		-- width back, decides everything fits, and never uncollapses.
		if self.__wordWrap == false and (self.__w or 0) > 0 then
			return math.min(full, self.__w)
		end
		return full
	end
	--- Wrapped height, not just the font size.
	--
	--  This was the one metric the harness could not answer, and it hid two real
	--  questions: whether a long quest description can be scrolled to its last
	--  line, and whether a confirmation dialog grows to fit its own text instead
	--  of drawing through its buttons. The client reports the WRAPPED height once
	--  the text and a width are both set, so that is what this models: explicit
	--  newlines split lines, and each line wraps at the set width.
	function f:GetStringHeight()
		local size = (self.__font and self.__font[2]) or 11
		local text = self.__text or ""
		-- GetWidth, not __w: a FontString stretched between a left and a right
		-- anchor has a width in the client and wraps against it, and reading the
		-- raw field said "never set, so one line" - which is how the What's new
		-- card's overflow check came to pass against a card it did not fit.
		local width = self:GetWidth()
		-- The client returns 0 for empty text, not a line's worth of height.
		if text == "" then return 0 end
		if not width or width <= 0 then return size end

		local lines = 0
		for segment in (text .. "\n"):gmatch("(.-)\n") do
			local plain, textures = MEASURE(segment)
			local segWidth = textures + #plain * size * 0.52
			lines = lines + math.max(1, math.ceil(segWidth / width))
		end
		-- Line spacing counts. The module sets it via SetSpacing and the client
		-- includes it in the reported height, so a mock that ignores it
		-- under-reports a long block by (lines - 1) * spacing.
		lines = math.max(1, lines)
		return lines * size * 1.2 + (lines - 1) * (self.__spacing or 0)
	end
	function f:SetSpacing(v) self.__spacing = v end
	function f:GetSpacing() return self.__spacing or 0 end
	return f
end


--- A font string owned by the menu compositor.
--
--  Identical to any other except that SetFont is refused, which is what the
--  real one does - the compositor lists it as disallowed so that a skin cannot
--  change a face the pool is about to reset anyway. SetFontObject is allowed,
--  and is the only way in.
local function newFontStringForMenu(owner)
	local fs = newFontString(owner, "ARTWORK")
	fs.SetFont = function()
		fail("SetFont is disallowed on a menu font string - use SetFontObject")
	end
	return fs
end

local frames = {}
function _G.__frameCount() return #frames end

--- Protection, modelled properly enough to catch the class of bug that made
--- losing a target mid-fight throw ADDON BLOCKED.
---
--- A frame built from a secure template is protected, and so is anything under
--- it. `Hide()` on a frame with a protected descendant is refused in combat -
--- hiding it would change that descendant's effective visibility - and that is
--- *not* the same rule as SetPoint/SetHeight, which really are per-object.
local function HasProtectedDescendant(f)
	if f.__protected then return f end
	for _, c in ipairs(f.__children or {}) do
		local hit = HasProtectedDescendant(c)
		if hit then return hit end
	end
	return nil
end

--- A font OBJECT, which is not a font string: it carries a font and nothing
--  else, and is the only way to re-role a string the menu system has locked.
function CreateFont(name)
	local obj = newFontString(nil, nil)
	obj.__name = name
	obj.__isFontObject = true
	if name then _G[name] = obj end
	return obj
end

function CreateFrame(kind, name, parent, template)
	local f = widgetBase(kind)
	f.__parent = parent
	f.__name = name
	f.__template = template
	if template and template:find("Secure") then f.__protected = true end
	if parent and parent.__children then
		parent.__children[#parent.__children + 1] = f
	end
	if name then _G[name] = f end
	frames[#frames + 1] = f

	function f:IsProtected() return HasProtectedDescendant(self) ~= nil end

	-- widgetBase's Show/Hide are the ones that dispatch OnShow/OnHide; these wrap
	-- them with the combat check rather than replacing them, or a protected-frame
	-- guard would silently cost every visibility script in the suite.
	local baseShow, baseHide = f.Show, f.Hide

	function f:Hide()
		if _G.__inCombat then
			local p = HasProtectedDescendant(self)
			if p then
				fail(("ADDON BLOCKED: Hide() on %s, which has a protected"
					.. " descendant (%s) - refused in combat")
					:format(tostring(self.__name or self.__kind),
						tostring(p.__name or p.__template or "?")))
			end
		end
		baseHide(self)
	end
	function f:Show()
		if _G.__inCombat then
			local p = HasProtectedDescendant(self)
			if p and not self.__shown then
				fail(("ADDON BLOCKED: Show() on %s, which has a protected"
					.. " descendant (%s) - refused in combat")
					:format(tostring(self.__name or self.__kind),
						tostring(p.__name or p.__template or "?")))
			end
		end
		baseShow(self)
	end

	--- Both real methods the mock did not have. SetShown is the one most code
	--  reaches for when a thing has two states, and its absence read as "the
	--  panel never showed" rather than as "the mock is missing a method".
	--  SetToplevel is recorded rather than modelled: nothing here draws.
	function f:SetShown(on)
		if on then self:Show() else self:Hide() end
	end
	function f:SetToplevel(on) self.__toplevel = on and true or nil end
	function f:IsToplevel() return self.__toplevel == true end

	-- Raise and Lower shuffle a frame within its own strata on the client.
	-- Recorded rather than modelled, for the reason SetToplevel is: nothing here
	-- draws, so the only thing a caller can get wrong is not calling them - and
	-- their ABSENCE was the failure, a real method missing from the mock reading
	-- as our bug rather than as the mock being short of one.
	function f:Raise() self.__raised = (self.__raised or 0) + 1 end
	function f:Lower() self.__raised = (self.__raised or 0) - 1 end

	-- Geometry is refused in combat for the same reason Hide is, and on the same
	-- frames: the restriction reaches every *ancestor* of a protected frame, not
	-- just the frame itself. This harness modelled Hide and Show and not these,
	-- which is exactly how a tray of secure buff tiles shipped calling SetPoint
	-- on itself four times per aura change in a fight.
	local function blocked(self, method)
		if not _G.__inCombat then return false end
		local p = HasProtectedDescendant(self)
		if not p then return false end
		fail(("ADDON BLOCKED: %s() on %s, which has a protected descendant (%s)"
			.. " - refused in combat")
			:format(method, tostring(self.__name or self.__kind),
				tostring(p.__name or p.__template or "?")))
		return true
	end

	for _, method in ipairs({ "SetPoint", "ClearAllPoints", "SetSize",
		"SetHeight", "SetWidth", "SetScale", "SetParent", "EnableMouse" }) do
		local orig = f[method]
		if orig then
			f[method] = function(self, ...)
				if blocked(self, method) then return end
				return orig(self, ...)
			end
		end
	end

	-- HONOURS THE NAME, like CreateFontString beside it. A named texture is a
	-- global on the real client, and Blizzard's own code reaches for its art
	-- that way constantly - PlayerTalentFrameBackgroundTopLeft, a talent's Slot,
	-- a skill row's Border. Throwing the name away here meant a mock frame whose
	-- art could only be found by walking its regions, which is not how the code
	-- under test finds it.
	function f:CreateTexture(n, layer, tmpl, sub)
		local t = newTexture(self, layer, sub)
		if n then
			t.__name = n
			_G[n] = t
		end
		self.__regions[#self.__regions + 1] = t
		return t
	end
	function f:GetRegions() return unpack(self.__regions or {}) end
	function f:CreateFontString(n, layer)
		local fs = newFontString(self, layer)
		-- Honour the name. Anonymous versus named is a real distinction on an
		-- edit box: the FontString that draws what you are typing has no name,
		-- and everything we want to silence does.
		if n then
			fs.__name = n
			_G[n] = fs
		end
		self.__regions[#self.__regions + 1] = fs
		return fs
	end
	function f:CreateMaskTexture(n, layer)
		local t = newTexture(self, layer)
		t.__kind = "MaskTexture"
		return t
	end

	f.__events = {}
	function f:RegisterEvent(e)
		if type(e) ~= "string" then error("bad event") end
		-- pretend a couple of retail-only events do not exist here
		if e == "UNIT_POWER_FREQUENT" then error("unknown event") end
		self.__events[e] = true
	end
	function f:UnregisterEvent(e) self.__events[e] = nil end
	function f:UnregisterAllEvents() self.__events = {} end
	function f:IsEventRegistered(e) return self.__events[e] end

	--- BACKDROPS. Real on every frame that inherits BackdropTemplate, which is
	--  most of what the Ace libraries build - a settings panel is backdrops all
	--  the way down. Recorded rather than swallowed: "did the stone border come
	--  off" is the whole question a reskin has to answer, and a no-op cannot be
	--  asked it.
	function f:SetBackdrop(bd) self.__backdrop = bd end
	function f:GetBackdrop() return self.__backdrop end
	function f:SetBackdropColor(r, g, b, a) self.__backdropColor = { r, g, b, a } end
	function f:GetBackdropColor()
		local c = self.__backdropColor
		if not c then return nil end
		return c[1], c[2], c[3], c[4]
	end
	function f:SetBackdropBorderColor(r, g, b, a)
		self.__backdropBorder = { r, g, b, a }
	end
	function f:GetBackdropBorderColor()
		local c = self.__backdropBorder
		if not c then return nil end
		return c[1], c[2], c[3], c[4]
	end

	--- LOCKED HIGHLIGHT. How the client says "this row is the chosen one" - the
	--  highlight texture is drawn permanently rather than on hover. Recorded,
	--  because a list whose selection cannot be read is a list where a check for
	--  it can only ever be a check of something else.
	--- A BUTTON'S FONT OBJECTS. Real: a list row uses them to say which line is
	--  the chosen one, swapping normal for highlight rather than recolouring.
	function f:SetNormalFontObject(o) self.__normalFont = o end
	function f:GetNormalFontObject() return self.__normalFont end
	function f:SetHighlightFontObject(o) self.__highlightFont = o end
	function f:GetHighlightFontObject() return self.__highlightFont end
	function f:SetDisabledFontObject(o) self.__disabledFont = o end

	function f:LockHighlight() self.__highlightLocked = true end
	function f:UnlockHighlight() self.__highlightLocked = false end
	function f:IsHighlightLocked() return self.__highlightLocked == true end

	--- A BUTTON'S OWN LABEL. The client makes one for any button given text,
	--  and hands it back through GetFontString. The mock bolted that onto the
	--  handful of Blizzard buttons being skinned by name, so anything building
	--  its own - which is every options library there is - fell through it.
	function f:GetFontString() return self.__fontString end
	function f:SetFontString(fs) self.__fontString = fs end
	local plainSetTextFrame = f.SetText
	function f:SetText(s)
		if plainSetTextFrame then plainSetTextFrame(self, s) else self.__text = s end
		if self.__kind == "Button" or self.__kind == "CheckButton" then
			if not self.__fontString and self.CreateFontString then
				self.__fontString = self:CreateFontString(nil, "OVERLAY")
			end
			if self.__fontString then self.__fontString:SetText(s) end
		end
	end

	--- ONLY THE SCRIPTS THE FRAME TYPE ACTUALLY HAS.
	--
	--  The client throws `Frame:SetScript(): Doesn't have a "OnClick"
	--  script` on a plain Frame, and it throws it for CLEARING one as much
	--  as for setting one - which is how a tidy-up loop that nils OnClick on
	--  everything it is holding went out. The mock took any name at all and
	--  the loop passed every check in here.
	--
	--  OnClick only, because that is the one this addon reaches for on a
	--  frame that has not got it: a Button has it and nothing else does.
	function f:SetScript(s, fn)
		if not self:HasScript(s) then
			error(("%s:SetScript(): Doesn't have a \"%s\" script")
				:format(self.__kind or "Frame", tostring(s)), 2)
		end
		self.__scripts[s] = fn
	end
	function f:GetScript(s) return self.__scripts[s] end

	--- HookScript CHAINS. It does not replace.
	--
	--  The mock replaced for a long time, and that quietly made it blind to the
	--  single most important property of the tooltip module: that AetherUI, and
	--  MobInfo2, and LibExtraTip can all hang off OnTooltipSetUnit at once and
	--  each still run. With a replacing HookScript the last registration wins,
	--  every test passes, and the thing the tests exist to prove is untested.
	--
	--  Order is the real client's: the existing handler runs FIRST, then the
	--  hook. That ordering is load-order-dependent in the game, which is why
	--  Modules/Tooltips.lua has to be correct under both - and why the suite
	--  below drives it both ways round.
	function f:HookScript(s, fn)
		local prev = self.__scripts[s]
		if not prev then
			self.__scripts[s] = fn
			return
		end
		self.__scripts[s] = function(...)
			prev(...)
			return fn(...)
		end
	end

	--- Whether the widget type has this script at all. Real frames answer false
	--  for OnTooltipSetUnit; real GameTooltips answer true. The tooltip module
	--  branches on it before hooking, so a mock without it silently exercises
	--  the wrong path.
	--  AND OnClick BELONGS TO BUTTONS. The client throws
	--  `Frame:SetScript(): Doesn't have a "OnClick" script` on a plain
	--  Frame, for CLEARING one as much as for setting one - which is how a
	--  tidy-up loop that nils OnClick on everything it holds went out.
	function f:HasScript(s)
		if self.__hasScript then return self.__hasScript[s] and true or false end
		if s == "OnClick" then
			-- CASE-INSENSITIVE, and templates count. CreateFrame takes the kind
			-- in whatever case the caller typed it - AceGUI says "BUTTON" - and
			-- a frame built from a ...ButtonTemplate has the script by
			-- inheritance whatever its own type says.
			local kind = tostring(self.__kind or ""):lower()
			if kind == "button" or kind == "checkbutton" then return true end
			local t = tostring(self.__template or "")
			return t:lower():find("button", 1, true) ~= nil
		end
		return true
	end

	f.__attrs = {}
	function f:SetAttribute(k, v) self.__attrs[k] = v end
	-- WITHOUT FIRING OnAttributeChanged, which is what the panel manager
	-- writes its layout values through: those are read back when a window is
	-- placed rather than acted on when they change.
	function f:SetAttributeNoHandler(k, v) self.__attrs[k] = v end
	-- WHETHER A CLICK CARRIES ON PAST THIS FRAME. Recorded rather than
	-- modelled - nothing here dispatches a real click - because its ABSENCE
	-- was the failure: a full-screen catcher that swallows what it catches is
	-- a transient that costs the player the click they meant to make.
	function f:SetPropagateMouseClicks(on) self.__passClicks = on and true or false end
	function f:GetPropagateMouseClicks() return self.__passClicks == true end
	function f:GetAttribute(k) return self.__attrs[k] end
	function f:GetName() return self.__name end

	function f:RegisterForClicks(...) self.__clicks = { ... } end
	function f:SetChecked(v) self.__checked = v and true or false end
	function f:GetChecked() return self.__checked end
	-- A disabled Button does not fire OnClick on the live client. Modelled, so a
	-- test that drives OnClick directly still has to respect the button's state
	-- rather than reaching past it.
	f.__enabled = true
	function f:Enable() self.__enabled = true end
	function f:Disable() self.__enabled = false end
	function f:IsEnabled() return self.__enabled end
	function f:SetEnabled(v) self.__enabled = v and true or false end

	-- A button's four state textures are REAL REGIONS, and three of them are
	-- hidden at rest. That matters: a skin that hides "every texture currently
	-- shown" leaves the pushed art untouched, and Blizzard's button flashes
	-- back the moment the player presses it. These were no-ops, so none of that
	-- was visible from here.
	f.__btnTex = {}
	for _, kind in ipairs({ "Normal", "Pushed", "Highlight", "Disabled", "Checked" }) do
		f["Set" .. kind .. "Texture"] = function(self, tex)
			local t = self.__btnTex[kind]
			if not t then
				t = self:CreateTexture(nil, "ARTWORK")
				self.__btnTex[kind] = t
			end
			t:SetTexture(tex)
			-- Only the normal state is up when nothing is happening.
			if kind == "Normal" then t:Show() else t:Hide() end
		end
		f["Get" .. kind .. "Texture"] = function(self) return self.__btnTex[kind] end
	end
	function f:SetButtonState() end

	-- Recorded rather than swallowed. "Is this row inert?" is a real question
	-- with a real answer, and a no-op EnableMouse makes it unaskable - a control
	-- that takes no mouse and one that takes a click and does nothing look
	-- identical from a test that cannot read the flag back.
	function f:EnableMouse(v) self.__mouse = (v ~= false) end
	function f:IsMouseEnabled() return self.__mouse ~= false end
	function f:EnableMouseWheel() end
	function f:EnableKeyboard(v) self.__keyboard = v and true or false end
	function f:IsKeyboardEnabled() return self.__keyboard or false end
	function f:SetMovable() end
	function f:SetResizable() end
	function f:RegisterForDrag() end
	function f:StartMoving() end
	-- Sizing, recorded. A grip that calls StartSizing and never StopSizing is a
	-- frame the cursor keeps for the rest of the session, and a grip that calls
	-- neither is a decoration - both look identical from outside.
	function f:StartSizing(point) self.__sizing = point or true end
	function f:StopMovingOrSizing() self.__sizing = nil end
	function f:SetResizable(v) self.__resizable = v and true or false end
	function f:IsResizable() return self.__resizable and true or false end
	function f:SetResizeBounds(minW, minH, maxW, maxH)
		self.__bounds = { minW, minH, maxW, maxH }
	end
	function f:SetClampedToScreen() end
	-- RECORDED, not swallowed. Clipping is the only thing that stops a drawer
	-- parked behind a TRANSLUCENT panel from reading straight through it, and
	-- a no-op here would agree with a drawer that was merely put on a lower
	-- frame level - which is the bug, drawn at the same coordinates.
	function f:SetClipsChildren(v) self.__clips = v and true or false end
	function f:DoesClipChildren() return self.__clips or false end
	-- Strata and level are modelled rather than swallowed: the last minimap bug
	-- was purely an ordering one, and a mock that forgets both cannot see it.
	function f:SetFrameStrata(v)
		if self.__fixedStrata then return end
		self.__strata = v
	end
	function f:GetFrameStrata() return self.__strata or "MEDIUM" end
	function f:SetFixedFrameStrata(v) self.__fixedStrata = v and true or false end
	function f:SetFrameLevel(v)
		if self.__fixedLevel then return end
		self.__level = v
	end
	function f:SetFixedFrameLevel(v) self.__fixedLevel = v and true or false end
	--- A CHILD SITS ONE LEVEL ABOVE ITS PARENT, which is how the client
	--  decides what draws over what. A flat default made every frame level 1,
	--  so "is this glass behind the controls or over them" was a question the
	--  harness answered yes to either way.
	function f:GetFrameLevel()
		if self.__level then return self.__level end
		local p = self.__parent
		if p and p.GetFrameLevel then return (p:GetFrameLevel() or 0) + 1 end
		return 1
	end
	function f:IsMouseOver() return self.__mouseOver or false end
	-- RECORDED, not swallowed. A hit rect is the only part of a button that can
	-- be wrong while everything you can see is right: the spellbook's tabs are
	-- 128x64 of art with the clicks kept 13 in from the top and 15 up from the
	-- bottom, and resizing one to 26 high makes the two insets meet. The tab
	-- draws, highlights, reads correctly - and cannot be clicked. A no-op here
	-- agrees with any amount of that.
	f.__hit = { 0, 0, 0, 0 }
	function f:SetHitRectInsets(l, r, t, b) self.__hit = { l or 0, r or 0, t or 0, b or 0 } end
	function f:GetHitRectInsets() return unpack(self.__hit) end
	function f:IsForbidden() return self.__forbidden or false end
	-- __kids is a curated list a test has pinned on (the UIParent dump); every
	-- other frame reports its real children, which is what the minimap's button
	-- scan walks.
	function f:GetChildren() return unpack(self.__kids or self.__children or {}) end
	function f:RegisterUnitEvent(e) self:RegisterEvent(e) end

	if kind == "Cooldown" then
		function f:SetCooldown(start, duration) self.__cd = { start, duration } end
		function f:GetCooldownTimes() return 0, 0 end
		function f:SetSwipeTexture(t) self.__swipe = t end
		function f:SetSwipeColor() end
		function f:SetDrawEdge() end
		function f:SetDrawBling() end
		function f:SetEdgeTexture() end
		function f:SetHideCountdownNumbers() end
		function f:SetReverse() end
	end

	-- A slider owns a thumb, and the client always gives it one. Leaving this
	-- out let a skin "handle" a scroll bar by quietly doing nothing to the only
	-- part of it anybody sees - green suite, stone thumb in the game.
	if kind == "Slider" then
		f.__thumb = newTexture(f, "ARTWORK")
		function f:GetThumbTexture() return self.__thumb end
		function f:SetThumbTexture(t)
			if type(t) == "string" then self.__thumb.__tex = t else self.__thumb = t end
		end
		function f:SetOrientation() end
		function f:SetValueStep(v) self.__step = v end
		-- A SLIDER HAS A VALUE, and a range. Obvious, and missing: the
		-- only sliders here were scroll bars, which are driven through
		-- their parent scroll frame - so nothing had ever asked one what
		-- it was set to, and a settings panel is mostly sliders.
		function f:SetMinMaxValues(a, b) self.__min, self.__max = a, b end
		function f:GetMinMaxValues() return self.__min, self.__max end
		function f:SetValue(v)
			self.__value = v
			local fn = self.__scripts and self.__scripts.OnValueChanged
			if fn then fn(self, v) end
		end
		function f:GetValue() return self.__value or 0 end
		function f:SetObeyStepOnDrag(v) self.__obeyStep = v end
	end

	-- Same for a check button's tick. It exists whether or not the box is
	-- checked, so a handler that only tints it when checked is a handler that
	-- has never been run.
	if kind == "CheckButton" then
		-- A REGION of the button, the way the client builds it. Held off to one
		-- side it can never be caught by a sweep over the button's regions - so
		-- a skin that blanks every texture it finds would take the tick with the
		-- stone and still look correct from here.
		f.__checked = f:CreateTexture(nil, "OVERLAY")
		f.__isChecked = false
		function f:GetCheckedTexture() return self.__checked end
		function f:SetCheckedTexture(t)
			if type(t) == "string" then self.__checked.__tex = t else self.__checked = t end
		end
		function f:SetChecked(v) self.__isChecked = v and true or false end
		function f:GetChecked() return self.__isChecked end
	end

	if kind == "StatusBar" then
		f.__min, f.__max, f.__value = 0, 1, 1
		f.__barTex = newTexture(f, "ARTWORK")
		function f:SetStatusBarTexture(t)
			if type(t) == "string" then self.__barTex.__tex = t else self.__barTex = t end
		end
		function f:GetStatusBarTexture() return self.__barTex end
		function f:SetStatusBarColor(r, g, b, a) self.__barTex:SetVertexColor(r, g, b, a) end
		function f:SetMinMaxValues(a, b) self.__min, self.__max = a, b end
		function f:GetMinMaxValues() return self.__min, self.__max end
		--- SetValue fires OnValueChanged, exactly as the client does.
		--
		--  Modelled rather than swallowed because that script is the ONLY hook a
		--  tooltip health bar has: nothing in Lua shows or fills GameTooltipStatusBar
		--  - the C tooltip code drives it when SetUnit runs - so a readout that
		--  updates from anywhere else is updating from nowhere.
		function f:SetValue(v)
			if type(v) ~= "number" then fail("StatusBar:SetValue got " .. tostring(v)) return end
			self.__value = v
			local fn = self.__scripts and self.__scripts.OnValueChanged
			if fn then fn(self, v) end
		end
		function f:GetValue() return self.__value end
		function f:SetReverseFill() end
		function f:SetOrientation() end
	end

	-- SetText fires OnTextChanged, exactly as the client does. Modelled rather
	-- than swallowed because the quest log's search box drives its filter from
	-- that script and nothing else - a mock that stays quiet here would let a
	-- broken filter pass.
	if kind == "EditBox" then
		f.__text = ""
		-- An edit box is a FontInstance: it justifies its own text, and the
		-- client gives it these. Missing here because nothing had ever styled
		-- one that was not ours - a settings panel is full of them.
		function f:SetJustifyH(j) self.__justifyH = j end
		function f:GetJustifyH() return self.__justifyH end
		function f:SetJustifyV(j) self.__justifyV = j end
		function f:GetJustifyV() return self.__justifyV end
		function f:SetText(s)
			self.__text = s or ""
			local fn = self.__scripts.OnTextChanged
			if fn then fn(self, true) end
		end
		function f:GetText() return self.__text end
		function f:SetFont(p, s, fl) self.__font = { p, s, fl } return true end
		function f:GetFont() return unpack(self.__font or {}) end
		function f:SetTextColor(r, g, b, a) self.__color = { r, g, b, a } end
		-- AND IT CAN BE ASKED. The setter was here and the getter was not, so
		-- anything that coloured an edit box could be checked only by whether it
		-- errored - and the letter you write in the postbox is one.
		function f:GetTextColor()
			local c = self.__color
			if not c then return 1, 1, 1, 1 end
			return c[1], c[2], c[3], c[4] or 1
		end
		function f:SetAutoFocus(v) self.__autoFocus = v and true or false end
		function f:SetFocus() self.__focus = true end
		function f:ClearFocus() self.__focus = false end
		function f:HasFocus() return self.__focus or false end
		-- RECORDED, not swallowed. An edit box draws its text from its own edge
		-- and the well we put round it has a rim there, so the inset is the only
		-- thing keeping the first character off it - and a mock that accepted the
		-- call and forgot it could not tell an inset box from a bare one.
		function f:SetTextInsets(l, r, t, b)
			self.__insets = { l or 0, r or 0, t or 0, b or 0 }
		end
		function f:GetTextInsets()
			local i = self.__insets or { 0, 0, 0, 0 }
			return i[1], i[2], i[3], i[4]
		end
		function f:SetMaxLetters() end
		function f:HighlightText() self.__highlighted = true end
		function f:SetCursorPosition() end
		-- The client has these and a copy box needs every one of them: a box
		-- that cannot go multi-line holds a stack trace on one line.
		function f:SetMultiLine(v) self.__multiline = v and true or false end
		function f:IsMultiLine() return self.__multiline or false end

		-- A MULTILINE BOX GROWS WITH ITS TEXT, which is the whole reason one
		-- goes in a scroll frame. A mock whose height never changed made a
		-- report of five lines and a report of eighty the same size, so nothing
		-- could tell whether the box needed scrolling - and eighty lines were
		-- being drawn outside the dialog, copied correctly and invisible.
		local plainSetText, plainGetHeight = f.SetText, f.GetHeight
		function f:SetText(s)
			plainSetText(self, s)
			if not self.__multiline then return end
			local lines = 1
			for _ in tostring(s or ""):gmatch("\n") do lines = lines + 1 end
			self.__textH = lines * 14
			-- The client works the height out while laying the text out and
			-- tells the scroll frame afterwards, which is why nothing can just
			-- measure it straight after SetText.
			local p = self:GetParent()
			if p and p.__scrollChild == self then
				local fn = p.__scripts and p.__scripts.OnScrollRangeChanged
				if fn then fn(p) end
			end
		end
		function f:GetHeight()
			if self.__multiline and self.__textH then return self.__textH end
			return plainGetHeight(self)
		end
		function f:SetFontObject(o) self.__fontObject = o end
		function f:GetFontObject() return self.__fontObject end
		function f:Insert(s) self:SetText((self.__text or "") .. tostring(s or "")) end
	end

	if kind == "ScrollFrame" then
		f.__vscroll = 0
		function f:SetScrollChild(c)
			self.__scrollChild = c
			local fn = self.__scripts and self.__scripts.OnScrollRangeChanged
			if fn then fn(self) end
		end
		function f:GetScrollChild() return self.__scrollChild end
		function f:SetVerticalScroll(v)
			self.__vscroll = v
			local fn = self.__scripts and self.__scripts.OnVerticalScroll
			if fn then fn(self, v) end
		end
		function f:GetVerticalScroll() return self.__vscroll end
		function f:SetHorizontalScroll(v) self.__hscroll = v end
		function f:GetHorizontalScroll() return self.__hscroll or 0 end
		function f:GetVerticalScrollRange()
			local c = self.__scrollChild
			return math.max(0, ((c and c:GetHeight()) or 0) - (self:GetHeight() or 0))
		end
		function f:UpdateScrollChildRect() end
	end

	-- Blizzard's ContainerFrameItemButtonTemplate does real work in its OnLoad
	-- and its XML scripts, and a mock that skips it cannot catch anything about
	-- what a module inherits from it. The two that matter here:
	--
	--   OnEnter      -> ContainerFrameItemButton_OnEnter
	--   UpdateTooltip -> the same function, which is what GameTooltip's OnUpdate
	--                    calls every 0.2s for as long as the cursor sits there
	--
	-- The second one is the trap. Replacing OnEnter and leaving UpdateTooltip
	-- alone gives a tooltip that appears and then vanishes.
	if template == "ContainerFrameItemButtonTemplate" then
		f.UpdateTooltip = function(self) ContainerFrameItemButton_OnEnter(self) end
		f:SetScript("OnEnter", function(self) ContainerFrameItemButton_OnEnter(self) end)
		f:SetScript("OnLeave", function() ContainerFrameItemButton_OnLeave() end)
	end

	-- OptionsListButtonTemplate arrives with a TOGGLE and a TEXT hung on it by
	-- parentKey. It is what every category list in the game is built from, and
	-- what AceGUI's tree group uses - which reaches for both the line after it
	-- creates one, so a bare frame here made the whole widget unreachable.
	if type(template) == "string" and template:find("OptionsListButton") then
		f.toggle = CreateFrame("Button", nil, f)
		f.toggle:SetNormalTexture("Interface\\Buttons\\UI-PlusButton-UP")
		f.text = f:CreateFontString(nil, "ARTWORK")
		f:SetHighlightTexture("Interface\\QuestFrame\\UI-QuestTitleHighlight")
	end

	-- UIDropDownMenuTemplate ARRIVES IN PIECES, and they are named globals:
	-- $parentLeft, $parentMiddle and $parentRight for the art, $parentText
	-- for the line it shows and $parentButton for the arrow. Everything that
	-- builds a dropdown reaches for those by name - the library does it three
	-- lines after creating one - so a template that came back as a bare frame
	-- made a dropdown untestable and every check of one a check of nothing.
	if type(template) == "string" and template:find("UIDropDownMenuTemplate")
		and name then
		for _, part in ipairs({ "Left", "Middle", "Right" }) do
			local tex = f:CreateTexture(name .. part, "ARTWORK")
			tex:SetTexture("Interface\\Glues\\CharacterCreate\\CharacterCreate-LabelFrame")
		end
		f:CreateFontString(name .. "Text", "ARTWORK")
		local arrow = CreateFrame("Button", name .. "Button", f)
		arrow:SetNormalTexture("Interface\\ChatFrame\\UI-ChatIcon-ScrollDown-Up")
	end

	-- A TEMPLATED BUTTON ARRIVES WITH ITS LABEL. UIPanelButtonTemplate and
	-- its relatives define a ButtonText, so the client hands back a button
	-- whose GetFontString already answers - before anybody calls SetText.
	-- Every options library builds buttons that way and reaches straight
	-- for the string, which the mock answered with nil.
	if type(template) == "string" and template:find("Button")
		and (kind == "Button" or kind == "CheckButton") then
		f.__fontString = f:CreateFontString(nil, "OVERLAY")
		-- AND ITS THREE PIECES OF ART. UIPanelButtonTemplate draws itself with
		-- Left, Middle and Right textures in the BACKGROUND layer rather than
		-- with normal/pushed/highlight - so a reskin that only cleared the
		-- state textures left the red on, and a mock with no art at all could
		-- not tell the difference.
		if template:find("UIPanelButton") then
			for _, part in ipairs({ "Left", "Middle", "Right" }) do
				local tex = f:CreateTexture(nil, "BACKGROUND")
				tex:SetTexture("Interface\\Buttons\\UI-Panel-Button-Up")
				f["__art" .. part] = tex
			end
		end
	end

	return f
end

-- ---------------------------------------------------------------------------
-- globals
-- ---------------------------------------------------------------------------

_G = _G or getfenv(0)

UIParent = CreateFrame("Frame", "UIParent")
UIParent:SetSize(1024, 768)

-- Sized, because zen's frosted pane anchors to it rather than to UIParent: it is
-- the physical screen at scale 1, which is the whole reason the pane uses it.
WorldFrame = CreateFrame("Frame", "WorldFrame")
WorldFrame:SetSize(1024, 768)

DEFAULT_CHAT_FRAME = { AddMessage = function(_, msg) print("    | " .. tostring(msg)) end }

STANDARD_TEXT_FONT = [[Fonts\FRIZQT__.TTF]]

--- THE CLIENT'S OWN CLIPBOARD CALL, WHICH ADDONS MAY NOT USE.
--
--  CopyToClipboard is in this client - Blizzard_Console, the API browser and
--  the Edit Mode layout export all call it, and OsDocumentation declares it
--  with HasRestrictions = true. That flag is the whole story: called from an
--  addon it raises "attempted to call a forbidden function (UNKNOWN()) from a
--  tainted execution path", and it is raised whether or not you pcall it, so
--  the error is REPORTED either way. There is no quiet attempt.
--
--  Modelled as the refusal rather than left out, because a mock that simply
--  has no CopyToClipboard makes the addon's pcall fall through to its own
--  fallback and pass - which is exactly how this shipped, and the first thing
--  that came back was the in-game error report.
function CopyToClipboard()
	error("AddOn AetherUI attempted to call a forbidden function (UNKNOWN()) "
		.. "from a tainted execution path.")
end
function GetTime() return time end
function GetCursorPosition() return cursorX, cursorY end
--- Move it. Tests that drag things were setting the upvalue directly, which
--  only works from the one file scope that can see it.
function __setCursor(x, y) cursorX, cursorY = x, y end

--- What the client keeps a chat window's SIZE in - separate from its position,
--  which a docked window has not got. FCF_SavePositionAndDimensions is the call
--  that errors on one; this is the half that does not.
_G.__savedDims = nil
function SetChatWindowSavedDimensions(id, w, h)
	_G.__savedDims = { id = id, w = w, h = h }
end

function FCF_DockUpdate() _G.__dockUpdated = (_G.__dockUpdated or 0) + 1 end

--- Locking a chat window is also what SHOWS or hides its resize button, and
--  that is the whole mechanism behind the crash: unlocking every frame - which
--  Chat:SetUnlocked does - puts Blizzard's grip on a docked window, where its
--  own OnMouseUp errors. This mock did not exist at all, so Chat:SetUnlocked
--  returned at its first line and none of that code had ever run in here.
function FCF_SetLocked(f, locked)
	if not f then return end
	f.isLocked = locked and true or false
	local bz = f.ResizeButton or _G[(f:GetName() or "") .. "ResizeButton"]
	if bz then
		if locked then bz:Hide() else bz:Show(); bz:EnableMouse(true) end
	end
end
function GetPhysicalScreenSize() return 2560, 1440 end
function InCombatLockdown() return _G.__inCombat or false end
function IsShiftKeyDown() return _G.__shift or false end
_G.__pageBindings = {}
function GetQuestDifficultyColor(level)
    local d = (level or 1) - (_G.__units.player.level or 1)
    if d >= 5 then return { r = 1.00, g = 0.24, b = 0.24 } end
    if d >= 3 then return { r = 1.00, g = 0.60, b = 0.30 } end
    if d >= -2 then return { r = 1.00, g = 0.94, b = 0.45 } end
    if d >= -8 then return { r = 0.51, g = 0.86, b = 0.51 } end
    return { r = 0.62, g = 0.62, b = 0.62 }
end
function GetQuestGreenRange() return 8 end
function wipe(t) for k in pairs(t) do t[k] = nil end return t end
function CreateColor(r, g, b, a) return { r = r, g = g, b = b, a = a, GetRGBA = function(s) return s.r, s.g, s.b, s.a end } end
function SetPortraitTexture() end

SlashCmdList = {}

-- action bar / binding / secure mocks ---------------------------------------

local actions = {}          -- slot -> {texture, count, cd={start,duration}, ...}
for i = 1, 12 do
	actions[i] = { texture = 130000 + i, count = (i == 8) and 20 or 0 }
end
actions[3].cd = { start = 990, duration = 30 }     -- a real cooldown
actions[5].cd = { start = 999, duration = 1.5 }    -- a global; must NOT get text
actions[2].usable, actions[2].noMana = false, true
actions[9].usable = false                           -- unusable, but affordable
actions[4].inRange = false
actions[6].current = true
actions[7].equipped = true
actions[11] = nil                                   -- an empty slot
-- A couple of slots on page 2 (13-24), so "is this page empty" is a question
-- with two different answers to test against.
actions[13] = { texture = "Icons\\Page2A", count = 0, usable = true, inRange = true }
actions[14] = { texture = "Icons\\Page2B", count = 0, usable = true, inRange = true }
_G.__actions = actions

function HasAction(s) return actions[s] ~= nil end
function GetActionTexture(s) return actions[s] and actions[s].texture end

-- The game answers GetActionCount for a slot that no longer holds anything with
-- whatever the departed stack last counted. Slot 11 is empty and models exactly
-- that, which is the whole reason the button reads HasAction first.
_G.__staleCounts = { [11] = 20 }
function GetActionCount(s)
	if actions[s] then return actions[s].count or 0 end
	return _G.__staleCounts[s] or 0
end
function GetActionCooldown(s)
	local a = actions[s]
	if a and a.cd then return a.cd[1], a.cd[2], 1 end
	return 0, 0, 0
end
function IsUsableAction(s)
	local a = actions[s]
	if not a then return false, false end
	if a.usable == false then return false, a.noMana and true or false end
	return true, false
end
function IsActionInRange(s)
	local a = actions[s]
	if a and a.inRange == false then return false end
	return true
end
function IsCurrentAction(s) return actions[s] and actions[s].current or false end
function IsAutoRepeatAction(s) return false end
function IsEquippedAction(s) return actions[s] and actions[s].equipped or false end
function PickupAction(s) _G.__picked = s end
function PlaceAction(s) _G.__placed = s end
function GetActionBarPage() return _G.__actionPage or 1 end

-- stance and pet -------------------------------------------------------------
-- Two forms and a three-slot pet, so the bars that size themselves have
-- something to size themselves to.
_G.__forms = {
	{ texture = "Icons\\Bear",   active = false, castable = true },
	{ texture = "Icons\\Cat",    active = true,  castable = true },
}
function GetNumShapeshiftForms() return #_G.__forms end
function GetShapeshiftFormInfo(i)
	local f = _G.__forms[i]
	if not f then return nil end
	return f.texture, f.active, f.castable
end
function GetShapeshiftFormCooldown() return 0, 0, 0 end

_G.__petActions = {
	{ name = "Attack",  texture = "Icons\\PetAttack", token = false, active = true },
	{ name = "Follow",  texture = "Icons\\PetFollow", token = false, active = false },
	-- A TOKEN ACTION REPORTS THE NAME OF A GLOBAL for its name as well as for its
	-- texture, which is the trap in this API: read the name straight through and
	-- the tooltip on a hunter's Growl says "PET_TOKEN_GROWL_NAME".
	{ name = "PET_TOKEN_GROWL_NAME", texture = "PET_TOKEN_GROWL", token = true,
	  active = false, autoAllowed = true, autoEnabled = true, spellID = 2649 },
}
_G.PET_TOKEN_GROWL      = "Icons\\PetGrowl"
_G.PET_TOKEN_GROWL_NAME = "Growl"

-- SEVEN RETURNS, not six. The seventh is the spellID, and it is what the
-- tooltip's second line is looked up from - a mock one short made that path
-- unreachable, so a console that never asked for it could not be caught.
function GetPetActionInfo(i)
	local a = _G.__petActions[i]
	if not a then return nil end
	return a.name, a.texture, a.token, a.active, a.autoAllowed, a.autoEnabled,
		a.spellID
end
function GetPetActionsUsable() return true end
function GetPetActionCooldown() return 0, 0, 0 end
_G.__pageHooks = {}
function ChangeActionBarPage(page)
    _G.__actionPage = page
    for _, fn in ipairs(_G.__pageHooks) do fn(page) end
end
-- Both shapes. The object form - hooksecurefunc(obj, "Method", fn) - is what
-- takes ownership of a widget method away from whatever else is setting it, and
-- the chat tabs depend on it: Blizzard fades docked tabs out and the only way to
-- keep them on screen is to be called after every SetAlpha.
function hooksecurefunc(a, b, c)
    if type(a) == "table" then
        local obj, name, fn = a, b, c
        local orig = obj[name]
        if type(orig) ~= "function" then return end
        obj[name] = function(self, ...)
            local r = { orig(self, ...) }
            fn(self, ...)
            return unpack(r)
        end
        return
    end
    local name, fn = a, b
    if name == "ChangeActionBarPage" then
        _G.__pageHooks[#_G.__pageHooks + 1] = fn
        return
    end
    -- Genuinely wrap the global. Swallowing these made the harness agree with any
    -- amount of "we hooked the function that puts Blizzard's look back", which is
    -- exactly the claim that most needs testing.
    local orig = _G[name]
    if type(orig) ~= "function" then return end
    _G[name] = function(...)
        local r = { orig(...) }
        fn(...)
        return unpack(r)
    end
end
function debugstack() return "Blizzard_ActionBar/ActionBar.lua:412\nFrameXML/MainMenuBar.lua:88" end
-- Steerable: the reward cards branch on CHATLINK versus DRESSUP, and a mock that
-- answers true to both makes those two branches indistinguishable.
-- NOTE the name: `__modifiedClick` is already taken further down by the
-- GetModifiedClick table, and clobbering it silently broke action-bar dragging.
_G.__clickAnswer = nil
function IsModifiedClick(what)
	if _G.__clickAnswer == nil then return true end
	return _G.__clickAnswer == what
end
-- Reads the SAME table SetCVar writes. It used to answer a constant false,
-- which made every CVar-driven branch in the addon untestable: a feature gated
-- on one could never be seen to turn on, and a test that flipped the CVar was
-- testing nothing at all.
function GetCVarBool(name)
	local v = _G.__cvars[name]
	return v == "1" or v == 1 or v == true
end

-- SOCIAL AND GUILD, the client's own two, because which of them is up is the
-- CLIENT's answer and not a CVar anybody reads for themselves. Both mixins run
-- UpdateVisibility off `useClassicGuildUI` at load - and they read it through
-- CVarCallbackRegistry, which is not the getter an addon reaches for, so the
-- two can disagree. They did in the game: the toolbox row carried Guild where
-- the menu carried Social.
--
-- Mocked as real buttons with a real shown flag so that disagreement can be
-- set up, which is the whole point of them.
-- AND THE GETTER THE CLIENT ITSELF USES. Both mixins read the CVar through
-- CVarCallbackRegistry:GetCVarValueBool, not through GetCVarBool - a real
-- global on this build, and one an addon does not normally reach for. Mocked
-- with a store of its own so it can be made to disagree with the plain getter,
-- which is the only way to show which of the two is being believed.
_G.__registryCVars = {}
CVarCallbackRegistry = {
	GetCVarValueBool = function(_, name)
		local v = _G.__registryCVars[name]
		if v == nil then return nil end
		return v == "1" or v == 1 or v == true
	end,
}

_G.__microPair = function(which)
	for _, spec in ipairs({ { "SocialsMicroButton", "social" },
		{ "GuildMicroButton", "guild" } }) do
		if which == nil then
			_G[spec[1]] = nil
		else
			local btn = _G[spec[1]]
			if not btn then
				btn = CreateFrame("Button", spec[1], _G.UIParent)
				_G[spec[1]] = btn
			end
			-- "down" is BOTH hidden, which is what our own action bar sweep
			-- leaves behind - a state the client never puts them in, and one
			-- that has to be told apart from an answer.
			btn:SetShown(which == spec[2])
		end
	end
end

-- ---------------------------------------------------------------------------
-- CVars
--
-- A real store rather than a stub, because zen now BORROWS several of these and
-- the interesting question is whether it gives them back. The client keeps them
-- as strings and normalises numbers on the way in, which is modelled here on
-- purpose: an addon that compares GetCVar's answer to the number it wrote is a
-- restore that silently never fires, and a mock returning the number back would
-- hide exactly that.
--
-- An unknown name throws, as it does in the client. That is what makes probing
-- with GetCVar the only safe way to write one.
-- ---------------------------------------------------------------------------

_G.__cvars = {
	-- The client reads this itself every time it opens a quest page: "1"
	-- shows the text at once, "0" types it out. Present here because a
	-- SetCVar to a name the client does not have is an error, which is how
	-- this mock catches an addon writing a setting that does not exist.
	instantQuestText = "0",
	Sound_EnableAllSound  = "1",
	Sound_MasterVolume    = "1",
	Sound_MusicVolume     = "0.2",
	Sound_SFXVolume       = "0.8",
	Sound_AmbienceVolume  = "0.6",
	Sound_DialogVolume    = "0.7",
	Sound_EnableMusic     = "1",
	Sound_EnableSFX       = "1",
	Sound_EnableAmbience  = "1",
	Sound_EnableDialog    = "1",
	-- Off, because that is the interesting case: with this off the client kills
	-- every sounding handle when the window loses focus and starts none of them
	-- again, which is a programme that goes quiet on an alt-tab and never comes
	-- back. Checked against Blizzard's own Audio.lua for the spelling - the
	-- unknown-name error above is what makes getting it wrong a failed test
	-- rather than a setting nobody ever wrote.
	Sound_EnableSoundWhenGameIsInBG = "0",

	-- How fast MoveViewUpStart/MoveViewDownStart actually turn the camera, in
	-- degrees a second. NOT a constant on a real client: Blizzard's own Mouse
	-- Look Speed slider writes cameraYawMoveSpeed and then this at half of it,
	-- over a 90-to-270 range - so it is 45 to 135 depending on a setting in the
	-- player's own options, and a zen tilt expressed as a DURATION was a
	-- different angle for every player. 90 is the client's own default.
	cameraPitchMoveSpeed               = "90",
	cameraYawMoveSpeed                 = "180",

	colorblindMode                     = "0",
	nameplateMaxDistance               = "20",
	nameplateShowAll                   = "0",
	nameplateShowEnemies               = "1",
	nameplateShowEnemyMinions          = "1",
	nameplateShowEnemyMinus            = "1",
	nameplateShowFriendlyPlayers       = "1",
	nameplateShowFriendlyPlayerMinions = "1",
	nameplateShowFriendlyNpcs          = "1",

	-- The floating text, which is a SEPARATE system from the bars above and has
	-- to be modelled separately or the test cannot tell them apart. Note
	-- UnitNameHostleNPC: that is Blizzard's spelling, in their own source, and
	-- has been for twenty years.
	UnitNameOwn                    = "1",
	UnitNameNPC                    = "1",
	UnitNameFriendlySpecialNPCName = "1",
	UnitNameHostleNPC              = "1",
	UnitNameInteractiveNPC         = "1",
	UnitNameNonCombatCreatureName  = "1",
	UnitNameFriendlyPlayerName     = "1",
	UnitNameFriendlyMinionName     = "1",
	UnitNameEnemyPlayerName        = "1",
	UnitNameEnemyMinionName        = "1",

	-- The over-the-shoulder offset. Present here, but the module must not
	-- REQUIRE it: it appears nowhere in the Classic Era interface source and may
	-- genuinely not exist on a live 1.15 client.
	test_cameraOverShoulder = "0",

	-- Socials and Guild are mutually exclusive on this one.
	useClassicGuildUI              = "1",

	-- The two that decide whether the shoulder offset does anything. Writing the
	-- offset without these is what shipped, and the camera did not move - so the
	-- mock carries them purely so a test can assert they were written.
	CameraKeepCharacterCentered    = "1",
	CameraReduceUnexpectedMovement = "1",

	-- Deliberately ABSENT: nameplateShowFriends, and the four pet/guardian name
	-- CVars the module lists from DialogueUI. Between them they cover both
	-- halves of the probe: a name that is gone from this flavour, and names that
	-- may only exist on another one. It is the name older clients
	-- use and the module lists it, so its absence here is the test that the
	-- module probes before it writes rather than assuming.
}

function GetCVar(name)
	if type(name) ~= "string" then fail("GetCVar got " .. tostring(name)) end
	return _G.__cvars[name]
end

-- Counted, not just thrown. An addon that wraps every SetCVar in a pcall looks
-- identical from the outside whether it probes first or fires blind, and the
-- client logs the blind one. This is what makes "it probed" testable.
_G.__badCVarWrites = 0

-- Every write, not just the bad ones. An idempotent writer and a spendthrift
-- one are indistinguishable through __badCVarWrites, which only counts writes
-- to names the client does not have.
_G.__cvarWrites = 0

function SetCVar(name, value)
	_G.__cvarWrites = _G.__cvarWrites + 1
	if _G.__cvars[name] == nil then
		_G.__badCVarWrites = _G.__badCVarWrites + 1
		error("SetCVar: unknown console variable '" .. tostring(name) .. "'", 2)
	end
	-- Six decimal places for a FLOAT, the way the client writes one back - but
	-- an integer comes back as an integer. Formatting everything to 6dp meant
	-- SetCVar("Sound_EnableMusic", 0) read back as "0.000000", which is not
	-- what the client stores and not what anything comparing it expects.
	if type(value) == "number" then
		_G.__cvars[name] = (value % 1 == 0)
			and string.format("%d", value)
			or string.format("%.6f", value)
	else
		_G.__cvars[name] = tostring(value)
	end

	-- SWITCHING A CHANNEL OFF STOPS WHAT IS ON IT. That is what the sound
	-- options do and it is the only lever an addon has over a sound whose handle
	-- it has lost - a reload throws the handle away and leaves the audio
	-- running. Modelled here because a mock that only consulted the CVar when a
	-- sound STARTED made "switch it off and on to clear the ghost" a line that
	-- could not be tested and could not fail.
	local channel = name:match("^Sound_Enable(%a+)$")
	if channel and _G.__cvars[name] == "0" then
		for handle, ch in pairs(_G.__channel) do
			if ch == channel then
				_G.__playing[handle] = nil
				_G.__channel[handle] = nil
			end
		end
	end
	return true
end

_G.__music = nil
function PlayMusic(file)
	if type(file) ~= "string" then fail("PlayMusic got " .. tostring(file)) end
	_G.__music = file
end
function StopMusic() _G.__music = nil end

-- PlaySoundFile, which is what a PROGRAMME uses. PlayMusic loops, which is
-- right for zen and wrong for an episode.
--
-- IT ANSWERS nil WHEN THE CHANNEL IS MUTED, and that is the whole reason this
-- is modelled rather than stubbed to true: the brief calls the muted case out
-- specifically, and a mock that always plays would let a console that shows
-- silence and looks broken pass every check.
_G.__musicMuted = false
_G.__sounds     = {}          -- handle -> file, everything ever started
_G.__playing    = {}          -- handle -> file, still going
_G.__channel    = {}          -- handle -> which channel it went out on
local nextHandle = 0

function PlaySoundFile(file, channel)
	if type(file) ~= "string" then fail("PlaySoundFile got " .. tostring(file)) end
	-- The console plays on Ambience, not Music: it silences the game's own
	-- music for the flight, and sharing that channel would silence itself too.
	-- "the music is off" therefore means whichever channel it is using.
	if _G.__musicMuted and (channel == "Music" or channel == "Ambience") then
		return nil
	end
	if channel and _G.__cvars["Sound_Enable" .. channel] == "0" then return nil end

	nextHandle = nextHandle + 1
	_G.__sounds[nextHandle]  = file
	_G.__playing[nextHandle] = file
	_G.__channel[nextHandle] = channel
	_G.__lastSound = file
	return true, nextHandle
end

function StopSound(handle)
	if handle == nil then return end
	_G.__playing[handle] = nil
	_G.__channel[handle] = nil
end

--- How many are still going. More than one means a segment was started over
--  the top of another, which on a real client is two tracks at once.
function _G.__soundsPlaying()
	local n = 0
	for _ in pairs(_G.__playing) do n = n + 1 end
	return n
end

-- ---------------------------------------------------------------------------
-- the body and the camera
--
-- The camera mock keeps a real zoom NUMBER, because the interesting property is
-- that the player's own distance comes back exactly - a mock that only recorded
-- "zoom was called" could not tell an exact restore from an approximate one.
--
-- Pitch is modelled as what it really is: a movement with a start and a stop,
-- and a running total of how long it has been moving. That is the only way to
-- catch the failure that actually matters here, which is a nudge that gets
-- started and never stopped.
-- ---------------------------------------------------------------------------

_G.__camera = { zoom = 12, pitchMoving = nil, pitchUp = 0, pitchDown = 0 }
_G.__mounted = false
_G.__emotes = {}

function IsMounted() return _G.__mounted end

function GetCameraZoom() return _G.__camera.zoom end

function CameraZoomIn(d)
	if type(d) ~= "number" then fail("CameraZoomIn got " .. tostring(d)) end
	_G.__camera.zoom = math.max(0, _G.__camera.zoom - d)
end

function CameraZoomOut(d)
	if type(d) ~= "number" then fail("CameraZoomOut got " .. tostring(d)) end
	_G.__camera.zoom = _G.__camera.zoom + d
end

local function bankPitch()
	local c = _G.__camera
	if not c.pitchMoving then return end
	c["pitch" .. c.pitchMoving] = c["pitch" .. c.pitchMoving]
		+ (time - (c.startedAt or time))
	c.pitchMoving = nil
end

--- Starting a movement while another is running is NOT an error.
--
--  It was, in the first version of this mock, and the rule was invented: the
--  client simply changes direction, and asserting otherwise produced twenty
--  failures describing a bug that did not exist. Worse, it cascaded - the failed
--  start left the mock's idea of the current direction wrong, so the stop that
--  arrived later matched nothing and every subsequent start failed too.
--
--  The property that actually matters is not "one at a time". It is "nothing is
--  left moving when zen is over", and that is `pitchMoving == nil`, asserted
--  where the test controls the timers rather than globally. A pitch movement
--  left running rotates the camera through the floor until the player reloads.
local function moveStart(dir)
	return function()
		local c = _G.__camera
		if c.pitchMoving then
			c.restarts = (c.restarts or 0) + 1
			bankPitch()
		end
		c.pitchMoving = dir
		c.startedAt = time
		-- The reversal is a movement followed immediately by a C_Timer stop.
		-- Flagging it here lets that stop's delay be captured as THIS movement's
		-- duration rather than as whatever timer happened to be scheduled last.
		--
		-- "Up" because the shot drops the camera DOWN and the reversal is
		-- therefore the upward one. It was "Down" while the shot tilted up, and
		-- flipping the module without flipping this measures the wrong movement.
		if dir == "Up" then c.awaitingDelay = true end
	end
end

local function moveStop(dir)
	return function()
		if _G.__camera.pitchMoving ~= dir then return end
		bankPitch()
	end
end

MoveViewUpStart, MoveViewUpStop     = moveStart("Up"), moveStop("Up")
MoveViewDownStart, MoveViewDownStop = moveStart("Down"), moveStop("Down")

C_ChatInfo = C_ChatInfo or {}
function C_ChatInfo.PerformEmote(token)
	_G.__emotes[#_G.__emotes + 1] = token
	_G.__emote = token
	return true
end

local bindings = { ACTIONBUTTON1 = "1", ACTIONBUTTON2 = "SHIFT-BUTTON4", ACTIONBUTTON3 = "NUMPAD7" }
_G.__bindingSet = bindings
function GetBindingKey(name) return bindings[name] end
function GetBindingText(k) return k end

-- SetBinding writes into the *account* binding set, which is why keys assigned
-- in our bind mode survive the addon being turned off. A key can only mean one
-- thing, so assigning it moves it off whatever had it before - the same
-- behaviour Blizzard's own keybinding panel has.
_G.__savedBindingSet = nil
function SetBinding(key, action)
	for name, k in pairs(bindings) do
		if k == key then bindings[name] = nil end
	end
	if action then bindings[action] = key end
	return true
end
function GetCurrentBindingSet() return 1 end
function SaveBindings(which) _G.__savedBindingSet = which end

_G.__modifiedClick = { PICKUPACTION = "SHIFT", SELFCAST = "ALT" }
function GetModifiedClick(name) return _G.__modifiedClick[name] end
function IsAltKeyDown() return _G.__alt or false end
function IsControlKeyDown() return _G.__ctrl or false end

-- Override bindings belong to an *owner*; ClearOverrideBindings(owner) drops
-- only that owner's. Modelling that matters here, because the fix for the dock
-- firing the wrong page is precisely "clear Blizzard's, then set ours".
_G.__overrides = {}
_G.__overrideOwner = {}
_G.__clearedOverrides = {}

function SetOverrideBindingClick(owner, priority, key, button, mouse)
    _G.__overrides[key] = button
    _G.__overrideOwner[key] = owner
end

function ClearOverrideBindings(owner)
    if owner and owner.GetName and owner:GetName() then
        _G.__clearedOverrides[owner:GetName()] = true
    end
    for key, o in pairs(_G.__overrideOwner) do
        if o == owner then
            _G.__overrides[key] = nil
            _G.__overrideOwner[key] = nil
        end
    end
end

function GetBindingAction(key, checkOverride)
    if checkOverride and _G.__overrides[key] then
        return "CLICK " .. _G.__overrides[key] .. ":LeftButton"
    end
    return _G.__bindings and _G.__bindings[key] or ""
end
_G.__stateDrivers = {}
function RegisterStateDriver(frame, state, values) _G.__stateDrivers[state] = values end
function UnregisterStateDriver(frame, state) _G.__stateDrivers[state] = nil end

-- THE CLIENT'S OWN PARTY FRAMES, in the shape this client actually has.
--
-- There are NO PartyMemberFrame1..4 globals. PartyFrame.lua builds the member
-- buttons from a frame pool - CreateFramePool("BUTTON", self,
-- "PartyMemberFrameTemplate", ...) - and a pooled frame gets no name. The
-- container is the only thing with one.
--
-- The first version of this mock invented the four globals, so the suite was
-- green about hiding frames that do not exist while the real ones sat on
-- screen next to ours. A mock must never be kinder than the client, and
-- inventing a global it does not have is the kindest thing a mock can do.
PartyFrame = CreateFrame("Frame", "PartyFrame", UIParent)
PartyFrame.__protected = true
for i = 1, 4 do
	-- Nameless, and children of the container, which is why banishing the
	-- container is enough.
	local b = CreateFrame("Button", nil, PartyFrame)
	b.__protected = true
end

-- The raid-style version of the same four people, drawn instead when the
-- player has that setting on.
CompactPartyFrame = CreateFrame("Frame", "CompactPartyFrame", UIParent)
CompactPartyFrame.__protected = true

-- The tab down the left-hand side and the Party Members flyout behind it -
-- the marker grid, Ready Check, Countdown, Convert to Raid. Our controls
-- panel is what replaces it.
CompactRaidFrameManager = CreateFrame("Frame", "CompactRaidFrameManager", UIParent)
CompactRaidFrameManager.__protected = true

_G.__unitWatched = {}
function RegisterUnitWatch(f)
	_G.__unitWatched[f] = true
	f.__unitWatch = true
	f.__protected = true          -- the state driver owns its visibility now
end
function UnregisterUnitWatch(f) _G.__unitWatched[f] = nil; f.__unitWatch = nil end

-- The tooltip, modelled far enough to catch the class of bug where something
-- SHOWS a tooltip correctly and something else empties it a moment later.
--
-- Two behaviours matter and both are the client's, not ours:
--
--   * SetOwner CLEARS the tooltip. Blizzard's own handlers open with it, so a
--     refresh that then fails to fill the tooltip leaves it empty.
--   * an EMPTY tooltip does not draw. Show() on one is a hide.
--
-- and the driver: GameTooltip's OnUpdate re-runs `owner:UpdateTooltip()` every
-- TOOLTIP_UPDATE_TIME (Blizzard_GameTooltip/Classic/GameTooltip.lua:461). That
-- is modelled as __tooltipTick() rather than a real timer.
GameTooltip = CreateFrame("Frame", "GameTooltip")
GameTooltip:Hide()

--- The ANCHOR KIND is recorded, not dropped.
--
--  It was thrown away here while the addon-made tooltip mock beside this one
--  kept it - so "where does this tooltip go" was a question the harness could
--  ask of a scanning tooltip and not of the one every button in the game uses.
--  A bar whose tooltips went to the wrong side of the screen was invisible.
function GameTooltip:SetOwner(o, anchor)
	self.__owner, self.__anchor = o, anchor
	self.__shows = nil          -- SetOwner clears. This is the whole point.
end
function GameTooltip:GetOwner() return self.__owner end
function GameTooltip:IsOwned(f) return self.__owner == f end

function GameTooltip:SetQuestLogItem(kind, i)
	self.__shows = { "item", kind, i, _G.__questSelected }
end
function GameTooltip:SetSpellByID(id) self.__shows = { "spell", id } end

--- The container path. Correct for a real bag and for a bank BAG; it answers
--  nothing for the generic bank container, which is why Blizzard's own bank
--  frame uses SetInventoryItem instead and never calls this for bag -1.
function GameTooltip:SetBagItem(bag, slot)
	if bag == BANK_CONTAINER then
		self.__shows = nil
		return nil
	end
	local info = C_Container.GetContainerItemInfo(bag, slot)
	self.__shows = info and { "bagitem", bag, slot } or nil
	return info and true or nil
end

function GameTooltip:SetInventoryItem(unit, slot)
	self.__shows = slot and { "invitem", unit, slot } or nil
	return slot and true or nil
end
function GameTooltip:SetHyperlink(link) self.__shows = link and { "link", link } or nil end

function GameTooltip:SetAction() end

local rawTooltipShow, rawTooltipHide = GameTooltip.Show, GameTooltip.Hide
function GameTooltip:Show()
	-- An empty tooltip is a hidden tooltip.
	if self.__shows or (self.__lines and #self.__lines > 0) then
		rawTooltipShow(self)
	else
		rawTooltipHide(self)
	end
end

-- ---------------------------------------------------------------------------
-- the tooltip's LINES
--
-- Everything above models the tooltip as an opaque box that is either full or
-- empty, which was enough while the only question was "did something empty it".
-- Modules/Tooltips.lua asks a different question - what does line 2 SAY, and is
-- it still saying it after another addon has been at it - so the lines have to
-- be real FontStrings under their real global names.
--
-- Faithful in the details that decide the module's correctness:
--
--   * both GameTooltipTextLeft1 (global) and GameTooltip.TextLeft1 (parentKey)
--     resolve, because both are declared in GameTooltipTemplate.xml:25
--   * SetUnit CLEARS first, fires OnTooltipCleared, then fills, then fires
--     OnTooltipSetUnit - which is the cycle Tooltips.lua's ResetCard and OnUnit
--     are two halves of
--   * the level line is written in the client's own shape, "Level 18 Humanoid"
--     for a plain mob and "Level 20 Elite Humanoid" for an elite, so the strip
--     is tested against the string it will actually meet
--   * NineSlice exists and is a child FRAME, not a backdrop
-- ---------------------------------------------------------------------------

local function tooltipLines(tip)
	tip.__lines = {}
	tip.__hasScript = {
		OnTooltipSetUnit = true, OnTooltipSetItem = true,
		OnTooltipSetSpell = true, OnTooltipCleared = true,
		OnShow = true, OnHide = true, OnSizeChanged = true, OnUpdate = true,
	}

	-- The NineSlice border. A child frame with a Center texture, exactly as
	-- TooltipBackdropTemplate builds it - NOT a backdrop, which GameTooltip has
	-- never had on this branch.
	local ns = CreateFrame("Frame", nil, tip)
	ns.Center = ns:CreateTexture(nil, "BACKGROUND")
	tip.NineSlice = ns
	tip.layoutType = "TooltipDefaultLayout"

	function tip:SetBackdropColor(r, g, b, a) self.__bdColor = { r, g, b, a } end
	function tip:SetBackdropBorderColor(r, g, b, a) self.__bdBorder = { r, g, b, a } end

	local function lineFor(self, i, side)
		local name = self:GetName()
		local key = (side or "Left") .. i
		self.__strings = self.__strings or {}
		if not self.__strings[key] then
			local fs = self:CreateFontString(name and (name .. "Text" .. key) or nil, "ARTWORK")
			self.__strings[key] = fs
			self["Text" .. key] = fs
		end
		return self.__strings[key]
	end
	tip.__lineFor = lineFor

	function tip:ClearLines()
		self.__lines = {}
		self.__shows = nil
		self.__unit = nil
		self.__item = nil
		for _, fs in pairs(self.__strings or {}) do fs:SetText(nil) end
		local h = self.__scripts and self.__scripts.OnTooltipCleared
		if h then h(self) end
	end

	function tip:AddLine(text, r, g, b)
		self.__lines[#self.__lines + 1] = text
		local fs = lineFor(self, #self.__lines, "Left")
		fs:SetText(text)
		fs:SetTextColor(r or 1, g or 1, b or 1, 1)
		self.__shows = self.__shows or { "text" }
		-- Adding a line resizes the tooltip. Firing OnSizeChanged here is what
		-- makes the Pawn case - lines appended after the tooltip is already up -
		-- reachable from a test at all.
		local h = self.__scripts and self.__scripts.OnSizeChanged
		if h then h(self) end
	end

	function tip:AddDoubleLine(l, r)
		self:AddLine(l)
		lineFor(self, #self.__lines, "Right"):SetText(r)
	end

	function tip:SetText(text, r, g, b)
		self:ClearLines()
		self:AddLine(text, r, g, b)
	end

	function tip:NumLines()
		if self.__lines and #self.__lines > 0 then return #self.__lines end
		return self.__shows and 1 or 0
	end
	--- The first line, which is what a real tooltip's GetText answers. A real
	--  method the mock did not have, so a caller asking what a tooltip says got
	--  a nil-index rather than an answer.
	function tip:GetText()
		local first = self.__lines and self.__lines[1]
		return first and lineFor(self, 1, "Left"):GetText() or nil
	end
	function tip:GetLeftLine(i) return lineFor(self, i, "Left") end

	function tip:SetPadding(w, h) self.__padding = { w, h } end
	function tip:GetPadding() return (self.__padding or { 0, 0 })[1] end
	function tip:SetMinimumWidth(w) self.__minWidth = w end
	function tip:GetMinimumWidth() return self.__minWidth or 0 end

	function tip:GetUnit() return self.__unit and UnitName(self.__unit), self.__unit end
	function tip:IsUnit(token) return self.__unit == token end
	function tip:GetItem() return self.__itemName, self.__item end
	function tip:GetSpell() return self.__spellName, self.__spellID end

	--- Driven by GUID rather than by token. This is how a SCANNING tooltip is
	--  filled - SetUnit on one that is not the cursor's does not reliably lay
	--  its lines out, which is why every addon that reads a title uses this.
		function tip:SetHyperlink(link)
		local guid = type(link) == "string" and link:match("^unit:(.+)$")
		if not guid then return end
		-- COUNTED. The title cache exists so that every Beverage Merchant
		-- in the world is scanned once rather than once per plate, and a
		-- cache that never hits looks identical on screen to one that
		-- does. This is the only way to tell them apart.
		_G.__titleScans = (_G.__titleScans or 0) + 1
		local d = _G.__unitForGUID(guid)
		if not d then return end
		-- The route that actually fills a scanner, so it goes round the guard.
		local was = self.__addonMade
		self.__addonMade = nil
		for token, other in pairs(_G.__units) do
			if other == d then self:SetUnit(token) break end
		end
		self.__addonMade = was
	end

	--- The client's own SetUnit, in the order the client does it.
	--
	--  On a tooltip an ADDON made, this fills nothing. That is not a guess: the
	--  first nameplate title reader used SetUnit, passed every check here, and
	--  returned an empty line for every NPC in the game - and Plater, which has
	--  read titles on this flavour for years, drives its scanner with
	--  SetHyperlink("unit:"..guid) instead. A mock that filled the lines anyway
	--  is what let that ship.
	function tip:SetUnit(unit)
		self:ClearLines()
		if self.__addonMade then return end
		self.__unit = unit
		local d = _G.__units[unit]
		if not d then return end

		self:AddLine(d.name or "Unknown")
		-- Line two is a player's guild or an NPC's title, in angle brackets
		-- either way. It is the only place the client writes "<Innkeeper>" -
		-- nothing on a nameplate carries it - which is why reading it needs a
		-- tooltip at all.
		-- A player's guild is bracketed; an NPC's title is NOT. Plater puts its
		-- own angle brackets on a title before drawing it, which is how we know
		-- - and this mock used to bracket both, so a parser that only accepted
		-- bracketed lines passed here and read nothing whatever in game.
		--
		-- Colourblind mode inserts a line before it, so the title is not always
		-- on line two.
		if d.guild then self:AddLine("<" .. d.guild .. ">") end
		if (_G.__cvars.colorblindMode or "0") ~= "0" then
			self:AddLine(d.isPlayer and (d.class or "Warrior") or "Humanoid")
		end
		if d.title then self:AddLine(d.title) end

		local lvl = (d.level == -1) and "??" or tostring(d.level or 1)
		local words = {}
		local cls = d.classification
		if cls == "elite" then words[#words + 1] = ELITE
		elseif cls == "rareelite" then
			-- TWO words, spaced, as the client writes them. Jammed together as
			-- "RareElite" this quietly stopped exercising the case it exists for:
			-- a strip that only removes one classification word.
			words[#words + 1] = RARE
			words[#words + 1] = ELITE
		elseif cls == "rare" then words[#words + 1] = RARE end
		words[#words + 1] = d.isPlayer and (d.class or "Warrior") or (d.creature or "Humanoid")
		-- string.format, not the `format` alias: that is assigned further down the
		-- file than this, and while it happens to be in place by the time a test
		-- runs, depending on it is depending on an ordering nobody wrote down.
		self:AddLine(string.format(UNIT_LEVEL_TEMPLATE, lvl) .. " " .. table.concat(words, " "))

		local sb = _G[(self:GetName() or "") .. "StatusBar"]
		if sb then
			sb:SetMinMaxValues(0, d.hpMax or 100)
			sb:SetValue(d.hp or d.hpMax or 100)
			sb:Show()
		end

		local h = self.__scripts and self.__scripts.OnTooltipSetUnit
		if h then h(self) end
	end

	function tip:SetItemByID(id, name, quality)
		self:ClearLines()
		self.__item = "|Hitem:" .. tostring(id) .. "|h"
		self.__itemName = name or "Test Item"
		self.__itemQuality = quality or 3
		local qc = ITEM_QUALITY_COLORS[self.__itemQuality] or { r = 1, g = 1, b = 1 }
		self:AddLine(self.__itemName, qc.r, qc.g, qc.b)
		local h = self.__scripts and self.__scripts.OnTooltipSetItem
		if h then h(self) end
	end

	function tip:SetSpell(id, name, body)
		self:ClearLines()
		self.__spellID, self.__spellName = id, name or "Conjure Water"
		self:AddLine(self.__spellName)
		self:AddLine(body or "Conjures 14 bottles of fresh water.")
		local h = self.__scripts and self.__scripts.OnTooltipSetSpell
		if h then h(self) end
	end

	return tip
end

tooltipLines(GameTooltip)

--- The tooltip's own status bar. Note the NAME: the XML declares
--  $parentStatusBar with NO parentKey, so GameTooltip.StatusBar is nil on this
--  branch and only the global exists. A mock that offered the parentKey would
--  hide a real nil-index.
do
	local sb = CreateFrame("StatusBar", "GameTooltipStatusBar", GameTooltip)
	sb:SetHeight(8)
	sb:Hide()
end

--- The other tooltips a skin has to cover.
--
--  Exposed as a global as well, so the suite can stand up a tooltip that another
--  addon hooked BEFORE we did. Both hook orders are reachable in the game and
--  the module has to be right under either.
function _G.__makeTooltip(name)
	return tooltipLines(CreateFrame("Frame", name, UIParent))
end

-- An addon that needs to READ a tooltip makes its own rather than borrowing
-- GameTooltip, which belongs to whatever the cursor is over. CreateFrame with
-- the GameTooltip type (or template) has to hand back something that behaves
-- like one, or a scanning tooltip is untestable and every test of it is really
-- a test of a bare frame.
do
	local plain = CreateFrame
	function CreateFrame(kind, name, parent, template)
		local f = plain(kind, name, parent, template)
		if kind == "GameTooltip"
			or (type(template) == "string" and template:find("GameTooltip")) then
			tooltipLines(f)
			-- Made by an ADDON, and that matters: see SetUnit below.
			f.__addonMade = true
			-- SetOwner CLEARS, exactly as it does on GameTooltip. A scanner that
			-- forgets to call it reads the LAST unit it looked at, which is a
			-- bug that only shows up on the second thing you point at.
			function f:SetOwner(owner, anchor)
				self.__owner, self.__anchor = owner, anchor
				self:ClearLines()
			end
		end
		return f
	end
end

for _, n in ipairs({ "ItemRefTooltip", "ShoppingTooltip1", "ShoppingTooltip2",
	"EmbeddedItemTooltip", "WorldMapTooltip" }) do
	_G.__makeTooltip(n)
end

--- The font OBJECTS. Not FontStrings - a font object has SetFont and nothing
--  else we use, and Tooltips.lua restyling these is what silently carries the
--  typeface into every line another addon adds.
for _, n in ipairs({ "GameTooltipHeaderText", "GameTooltipText", "GameTooltipTextSmall" }) do
	_G[n] = {
		-- Starts with the client's real face, at the sizes FontStyles.xml gives
		-- these three. A mock that started blank would let a module capture nil as
		-- "the original" and call putting nothing back a successful restore.
		__font = { [[Fonts\FRIZQT__.TTF]], n:find("Small") and 10 or 12, "" },
		-- RETURNS NOTHING, because the client's does not. A FontString answers
		-- isValid; a font object answers nothing at all, and a mock that is
		-- kinder than the client hides exactly the bug that made every tooltip
		-- in the game come out in Friz Quadrata - the fallback in
		-- Media:SetFont read this return and fell through on every call.
		SetFont = function(self, path, size, flags)
			if type(path) ~= "string" then fail(n .. ":SetFont path " .. tostring(path)) return end
			-- Refusing a face leaves the object on the one it already had -
			-- the client's own - which is why a font OBJECT needs no fallback:
			-- what it keeps is what the fallback would have set.
			if _G.__badFonts and _G.__badFonts[path] then return end
			self.__font = { path, size, flags }
		end,
		GetFont = function(self)
			local c = self.__font
			if not c then return nil end
			return c[1], c[2], c[3]
		end,
	}
end

--- The globals Tooltips.lua hooksecurefuncs. Each one has to EXIST, and each
--  one has to do the thing the hook is compensating for - in particular
--  SharedTooltip_SetBackdropStyle really does put the border back, which is the
--  whole reason StripArt is called from four places.
--- The inbox, which the client will ONLY answer at a mailbox.
--
--  GetLatestThreeSenders knows about mail that arrived while you were logged
--  in and nothing else, so mail waiting from before login has no names on it
--  at all. This is where the names and the true unread count live, and it is
--  behind a mailbox - which is why the Toolbox reads it when it can and
--  remembers what it said.
_G.__inbox = nil            -- nil models "not at a mailbox / nothing loaded"
function GetInboxNumItems()
	return _G.__inbox and #_G.__inbox or 0
end

--- packageIcon, stationeryIcon, sender, subject, money, COD, daysLeft,
--  itemCount, wasRead, ... - wasRead is the NINTH, and it is the one that
--  matters: an inbox is a list of mail, not a list of unread mail.
function GetInboxHeaderInfo(i)
	local m = _G.__inbox and _G.__inbox[i]
	if not m then return nil end
	return nil, nil, m.sender, m.subject or "", 0, 0, 30, 0, m.read or false
end

--- Blizzard's FCF dock keeps its OWN record of where a chat frame goes, per
--  character, and re-applies it on events an addon does not all hear. Moving
--  the frame without telling it leaves two records disagreeing.
_G.__fcfSaved = {}
function FCF_SavePositionAndDimensions(f)
	if not f or not f.GetID then error("FCF_SavePositionAndDimensions: not a chat frame") end
	local point, _, _, x, y = f:GetPoint(1)
	_G.__fcfSaved[f:GetID()] = { point = point, x = x, y = y }
end

--- ...and what it does with that record later. This is the "few seconds later"
--  in the report: an event fires, Blizzard restores ITS answer, and a position
--  we saved correctly is undone by one we never updated.
function FCF_RestorePositionAndDimensions(f)
	local rec = f and f.GetID and _G.__fcfSaved[f:GetID()]
	if not rec or not rec.point then
		-- A NEW CHARACTER has no record, which is the case that made this
		-- visible: Blizzard falls back to its default corner.
		f:ClearAllPoints()
		f:SetPoint("BOTTOMLEFT", UIParent, "BOTTOMLEFT", 32, 32)
		return
	end
	f:ClearAllPoints()
	f:SetPoint(rec.point, UIParent, rec.point, rec.x, rec.y)
end

function SharedTooltip_SetBackdropStyle(tip)
	if not tip or not tip.NineSlice then return end
	tip.NineSlice:Show()
	tip.NineSlice:SetAlpha(1)
end

function GameTooltip_SetDefaultAnchor(tip, parent)
	tip:SetOwner(parent, "ANCHOR_NONE")
	tip:ClearAllPoints()
	tip:SetPoint("BOTTOMRIGHT", UIParent, "BOTTOMRIGHT", -13, 70)
	tip.default = 1
end

function GameTooltip_ShowStatusBar() end
function GameTooltip_ClearStatusBars() end

-- %s rather than the client's %d, so a "??" level can go through the same
-- format call. Anything matching ON this template has to cope with both, which
-- is a real divergence and is called out where it matters.
UNIT_LEVEL_TEMPLATE = "Level %s"
LEVEL = "Level"
ELITE = "Elite"
RARE = "Rare"
BOSS = "Boss"
HEALTH = "Health"
FACTION_STANDING_LABEL2 = "Hostile"
FACTION_STANDING_LABEL4 = "Neutral"
FACTION_STANDING_LABEL5 = "Friendly"

function UnitClassification(u)
	local d = _G.__units and _G.__units[u]
	return d and d.classification or "normal"
end

function BreakUpLargeNumbers(n)
	local s = tostring(math.floor(tonumber(n) or 0))
	local out = (s:reverse():gsub("(%d%d%d)", "%1,"):reverse())
	return (out:gsub("^,", ""))
end

function GameTooltip_Hide() GameTooltip.__shows = nil GameTooltip:Hide() end
function ResetCursor() end
function CursorUpdate() end
-- WHICH WINDOW GETS SPOKEN TO. The handoff reserves the gold dot for
-- something addressed to you and leaves the accent for ordinary traffic, and
-- Blizzard's flash says only that something arrived - so the window has to be
-- asked what it is registered to carry. ChatFrame2 is the whispers window.
function ChatFrame_ContainsMessageGroup(frame, group)
	local want = frame and frame.__groups
	return want ~= nil and want[group] == true
end

function ShowInspectCursor() end
