		sendm:SetPoint("BOTTOMRIGHT", ff, "BOTTOMRIGHT", -6, 4)
		sendm:SetNormalTexture("panel-button-up")
		local sendms = sendm:CreateFontString("FriendsFrameSendMessageButtonText", "OVERLAY")
		sendms:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
		sendms:SetText("Send Message")
		sendm:SetFontString(sendms)

		-- THE IGNORE LIST is a FAUX scroll - a scroll BAR and nothing else.
		-- Its nineteen rows are hung off the WINDOW and scrolled by refilling,
		-- so moving the list leaves every one of them where it was.
		local isf = CreateFrame("ScrollFrame", "FriendsFrameIgnoreScrollFrame",
			panes.IgnoreListFrame)
		isf:SetSize(298, 309)
		isf:SetPoint("TOPRIGHT", ff, "TOPRIGHT", -32, -87)
		for _, part in ipairs({ "Top", "Bottom", "Middle" }) do
			local t = isf:CreateTexture("FriendsFrameIgnoreScrollFrame" .. part, "ARTWORK")
			t:SetTexture("Interface\\PaperDollInfoFrame\\UI-Character-ScrollBar")
			_G["FriendsFrameIgnoreScrollFrame" .. part] = t
		end
		isf.ScrollBar = CreateFrame("Slider", nil, isf)
		for i = 1, 19 do
			local n = "FriendsFrameIgnoreButton" .. i
			local b = CreateFrame("Button", n, panes.IgnoreListFrame)
			b:SetSize(298, 16)
			if i == 1 then
				b:SetPoint("TOPLEFT", ff, "TOPLEFT", 8, -89)
			else
				b:SetPoint("TOPLEFT", _G["FriendsFrameIgnoreButton" .. (i - 1)],
					"BOTTOMLEFT", 0, 0)
			end
			b:SetHighlightTexture("Interface\\QuestFrame\\UI-QuestTitleHighlight")
			local fs = b:CreateFontString(n .. "Name", "BORDER")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetText("Nuisance")
			_G[n .. "Name"] = fs
		end
		for _, n in ipairs({ "FriendsFrameIgnoredHeader",
			"FriendsFrameBlockedInviteHeader", "FriendsFrameMutedHeader" }) do
			local h = CreateFrame("Frame", n, panes.IgnoreListFrame)
			h:SetSize(298, 16)
			h:CreateTexture(nil, "BACKGROUND"):SetTexture("friends-header-stone")
			local fs = h:CreateFontString(n .. "Title", "ARTWORK")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetText("Ignored")
			_G[n .. "Title"] = fs
		end
		for _, spec in ipairs({ { "FriendsFrameIgnorePlayerButton", 131,
			"BOTTOMLEFT", 4 }, { "FriendsFrameUnsquelchButton", 134,
			"BOTTOMRIGHT", -6 } }) do
			local b = CreateFrame("Button", spec[1], panes.IgnoreListFrame)
			b:SetSize(spec[2], 21)
			b:SetPoint(spec[3], ff, spec[3], spec[4], 4)
			b:SetNormalTexture("panel-button-up")
			local fs = b:CreateFontString(spec[1] .. "Text", "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetText(spec[1])
			b:SetFontString(fs)
		end

		-- WHO: a query field hung off the window's BOTTOM edge, a stone recess
		-- round the list, five column heads 30 above it, and another faux
		-- scroll.
		local wsearch = CreateFrame("EditBox", "WhoFrameEditBox", panes.WhoFrame)
		wsearch:SetSize(296, 32)
		wsearch:SetPoint("BOTTOMLEFT", panes.WhoFrame, "BOTTOMLEFT", 18, 26)
		for _, part in ipairs({ "Left", "Middle", "Right" }) do
			local t = wsearch:CreateTexture("WhoFrameEditBox" .. part, "BACKGROUND")
			t:SetTexture("Interface\\Common\\Common-Input-Border")
			_G["WhoFrameEditBox" .. part] = t
		end
		-- The magnifying glass is in the same layer as the border, so a plain
		-- sweep takes it and the field says nothing about what it is for.
		wsearch.searchIcon = wsearch:CreateTexture(nil, "BACKGROUND")
		wsearch.searchIcon:SetTexture("common-search-magnifyingglass")

		local winset = CreateFrame("Frame", "WhoFrameListInset", panes.WhoFrame)
		winset:SetPoint("TOPLEFT", panes.WhoFrame, "TOPLEFT", 5, -83)
		winset:SetPoint("BOTTOMRIGHT", panes.WhoFrame, "BOTTOMRIGHT", -5, 26)
		winset:CreateTexture(nil, "BACKGROUND"):SetTexture("Interface\\FrameGeneral\\UI-Frame-InnerTopLeft")
		local wtot = winset:CreateFontString("WhoFrameTotals", "ARTWORK")
		wtot:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
		wtot:SetText("12 players found")
		wtot:SetPoint("BOTTOM", wsearch, "TOP", 0, -6)
		_G.WhoFrameTotals = wtot

		local prevCol
		for i, word in ipairs({ "Name", "Level", "Class", "Zone", "Guild" }) do
			local n = "WhoFrameColumnHeader" .. i
			local b = CreateFrame("Button", n, panes.WhoFrame)
			b:SetSize(83, 24)
			if prevCol then
				b:SetPoint("LEFT", prevCol, "RIGHT", -2, 0)
			else
				b:SetPoint("TOPLEFT", panes.WhoFrame, "TOPLEFT", 7, -57)
			end
			for _, part in ipairs({ "Left", "Middle", "Right" }) do
				local t = b:CreateTexture(n .. part, "BACKGROUND")
				t:SetTexture("Interface\\FriendsFrame\\WhoFrame-ColumnTabs")
				_G[n .. part] = t
			end
			local fs = b:CreateFontString(n .. "Text", "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
			fs:SetText(word)
			b:SetFontString(fs)
			b:SetHighlightTexture("Interface\\PaperDollInfoFrame\\UI-Character-Tab-Highlight")
			prevCol = b
		end

		local wsf = CreateFrame("ScrollFrame", "WhoListScrollFrame", panes.WhoFrame)
		wsf:SetSize(296, 287)
		wsf:SetPoint("TOPRIGHT", panes.WhoFrame, "TOPRIGHT", -33, -87)
		for _, part in ipairs({ "Top", "Bottom", "Middle" }) do
			local t = wsf:CreateTexture("WhoListScrollFrame" .. part, "ARTWORK")
			t:SetTexture("Interface\\PaperDollInfoFrame\\UI-Character-ScrollBar")
			_G["WhoListScrollFrame" .. part] = t
		end
		wsf.ScrollBar = CreateFrame("Slider", nil, wsf)
		for i = 1, 17 do
			local n = "WhoFrameButton" .. i
			local b = CreateFrame("Button", n, panes.WhoFrame)
			b:SetSize(296, 16)
			if i == 1 then
				b:SetPoint("TOPLEFT", panes.WhoFrame, "TOPLEFT", 8, -89)
			else
				b:SetPoint("TOPLEFT", _G["WhoFrameButton" .. (i - 1)],
					"BOTTOMLEFT", 0, 0)
			end
			-- FIVE STRINGS, not one: this row is a table row.
			for _, col in ipairs({ "Name", "Level", "Class", "Zone" }) do
				local fs = b:CreateFontString(n .. col, "BORDER")
				fs:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
				fs:SetText(col)
				_G[n .. col] = fs
			end
		end
		for _, spec in ipairs({ { "WhoFrameGroupInviteButton", 120 },
			{ "WhoFrameAddFriendButton", 120 }, { "WhoFrameWhoButton", 85 } }) do
			local b = CreateFrame("Button", spec[1], panes.WhoFrame)
			b:SetSize(spec[2], 22)
			b:SetPoint("BOTTOMRIGHT", panes.WhoFrame, "BOTTOMRIGHT", -6, 4)
			b:SetNormalTexture("panel-button-up")
			local fs = b:CreateFontString(spec[1] .. "Text", "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetText(spec[1])
			b:SetFontString(fs)
		end

		-- RAID: a switch and a button in the band, a paragraph below them, and
		-- one button on the bottom edge.
		local assist = CreateFrame("CheckButton", "RaidFrameAllAssistCheckButton",
			panes.RaidFrame)
		assist:SetSize(24, 24)
		assist:SetPoint("TOPLEFT", panes.RaidFrame, "TOPLEFT", 58, -23)
		assist:SetNormalTexture("Interface\\Buttons\\UI-CheckBox-Up")
		assist:SetCheckedTexture("Interface\\Buttons\\UI-CheckBox-Check")
		local notin = CreateFrame("Frame", "RaidFrameNotInRaid", panes.RaidFrame)
		notin:SetAllPoints(panes.RaidFrame)
		local blurb = notin:CreateFontString("RaidFrameRaidDescription", "ARTWORK")
		blurb:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
		blurb:SetText("You are not in a raid group.")
		blurb:SetSize(300, 40)
		blurb:SetPoint("TOPLEFT", panes.RaidFrame, "TOPLEFT", 15, -73)
		_G.RaidFrameRaidDescription = blurb
		for _, spec in ipairs({ { "RaidFrameRaidInfoButton", 100, "TOPRIGHT", -7, -24 },
			{ "RaidFrameConvertToRaidButton", 130, "BOTTOMRIGHT", -7, 5 } }) do
			local b = CreateFrame("Button", spec[1], panes.RaidFrame)
			b:SetSize(spec[2], 22)
			b:SetPoint(spec[3], panes.RaidFrame, spec[3], spec[4], spec[5])
			b:SetNormalTexture("panel-button-up")
			local fs = b:CreateFontString(spec[1] .. "Text", "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetText(spec[1])
			b:SetFontString(fs)
		end

		-- AND THE RAID PANE BELONGS TO NOBODY UNTIL IT IS CLAIMED. Its XML
		-- carries no parent - "Parent set dynamically. See ClaimRaidFrame()" -
		-- and no hidden attribute either, so from load it is a shown frame with
		-- nothing above it: never drawn, and every child of it answers yes to
		-- IsVisible, because a parent chain that simply ends has no hidden link.
		panes.RaidFrame:SetParent(nil)
		panes.RaidFrame:Show()
		function _G.ClaimRaidFrame(parent)
			if panes.RaidFrame:GetParent() == parent then return end
			panes.RaidFrame:SetParent(parent)
		end

		-- THE SWAP IS NOT ATOMIC, and that is the client's own doing: it loops
		-- the five panes with `pairs`, so the one going UP can be shown before
		-- the one coming DOWN is hidden. Anything hooked to a pane's OnShow
		-- fires in that gap and sees a window with two panes up. Modelled in the
		-- worst order on purpose - show first, hide after - because the point of
		-- a mock is to be no kinder than the thing it stands for.
		--
		-- AND RaidFrame IS ONLY HIDDEN IF THIS WINDOW OWNS IT, which is the
		-- client's test verbatim.
		local SUBFRAMES = { "FriendsListFrame", "IgnoreListFrame", "WhoFrame",
			"GuildFrame", "RaidFrame" }
		function _G.FriendsFrame_ShowSubFrame(name)
			_G[name]:Show()
			for _, other in ipairs(SUBFRAMES) do
				if other ~= name then
					if other == "RaidFrame" then
						if panes.RaidFrame:GetParent() == ff then
							panes.RaidFrame:Hide()
						end
					else
						_G[other]:Hide()
					end
				end
			end
		end

		-- WHICH PANE IS UP, AND THE HEADER ONLY ON THE FRIENDS TAB. The client
		-- claims the raid pane BEFORE it shows it, so a post-hook on this sees a
		-- settled window whichever tab you are on - which is what the dresser
		-- hooks, the pane's own OnShow being unable to see the end of a swap it
		-- is in the middle of.
		function _G.FriendsFrame_Update()
			local tab = ff.selectedTab or 1
			hdr:SetShown(tab == 1)
			if tab == 1 then
				_G.FriendsFrame_ShowSubFrame(hdr.selectedTab == 2
					and "IgnoreListFrame" or "FriendsListFrame")
			elseif tab == 2 then
				_G.FriendsFrame_ShowSubFrame("WhoFrame")
			elseif tab == 3 then
				_G.FriendsFrame_ShowSubFrame("GuildFrame")
			else
				_G.ClaimRaidFrame(ff)
				_G.FriendsFrame_ShowSubFrame("RaidFrame")
			end
		end

		-- THE CLIENT'S OWN THREE REFRESHES, which is what the dresser hooks:
		-- every one of these lists is refilled rather than rebuilt, so a row
		-- dressed once is undressed by the next update.
		function _G.FriendsList_Update()
			for _, row in ipairs(fsf.buttons) do
				row.background:SetColorTexture(0.3, 0.3, 0.6, 0.35)
			end
			-- ...AND ONE MORE ROW, which is what a hybrid scroll does when the
			-- box it fills has grown. A mock that only ever refilled the ten it
			-- started with could not show a row arriving after the dresser had
			-- been past, which is the whole reason the hook exists.
			friendRow()
		end
		function _G.IgnoreList_Update() end
		function _G.WhoList_Update() end
	end

	-- THE POSTBOX, THE BOOK READER AND THE TRADE SKILLS. Three windows a
	-- player opens constantly and none of them was in this mock, so none of
	-- them could be checked - which is how all three shipped in stone.
	do
		-- SHORTER THAN ITS OWN PANES, which is not a mistake. The postbox is 424
		-- tall and the two pages inside it are 512, because the client anchors
		-- Send Mail's attachment row a fixed distance ABOVE its pane's bottom and
		-- places it from Lua on every update - so that 512 is part of the client's
		-- arithmetic and not a size to be tidied. A mock with the two the same
		-- could not show a page being shortened to fit and dragging the row
		-- eighty-eight units up into the middle of the letter.
		local mail = buildPanel("MailFrame")
		mail:SetHeight(424)
		-- TWO PANES FILLING THE WINDOW, and the letter you open is NOT one of
		-- them: the client builds that as a window of its own, parented to
		-- UIParent and hung off the postbox's top right corner, with a height all
		-- its own. A mock that made it a child of the postbox could not show the
		-- pair coming up as two different sizes side by side.
		-- PINNED BY ONE CORNER WITH A SIZE OF THEIR OWN, which is how the client
		-- declares them - 384 by 512 at the top left of a window exactly that
		-- size. NOT setAllPoints: with both corners pinned the foot is held by
		-- the window and nothing can go wrong, and a mock built that way could
		-- not show Send Mail's money block travelling down the window with the
		-- rest of its pane and landing on top of Send and Cancel.
		for _, n in ipairs({ "InboxFrame", "SendMailFrame" }) do
			local pane = CreateFrame("Frame", n, mail)
			pane:SetSize(384, 512)
			pane:SetPoint("TOPLEFT", mail, "TOPLEFT", 0, 0)
			-- Near-black, because it is printed on paper.
			local fs = pane:CreateFontString(nil, "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetTextColor(0.1, 0.1, 0.1, 1)
			pane:CreateTexture(nil, "BACKGROUND"):SetTexture("Interface\\Stationery\\Stationery")
			local b = CreateFrame("Button", nil, pane, "UIPanelButtonTemplate")
			b:SetText("Send")
		end
		local letter = CreateFrame("Frame", "OpenMailFrame", UIParent)
		letter:SetSize(360, 420)
		letter:SetPoint("TOPLEFT", _G.InboxFrame, "TOPRIGHT", 0, 0)
		letter:CreateTexture(nil, "BACKGROUND"):SetTexture("Interface\\Stationery\\Stationery")

		-- THE RECEIPT AN AUCTION LEAVES, printed in a dark brown that reads on
		-- parchment and all but vanishes on glass - and NOT black enough for the
		-- sweep to lift, which catches ink under 0.35 and this sits just over it.
		-- WHO IT IS FROM AND WHAT IT IS ABOUT, hung off the window's own TOPLEFT
		-- 33 and 55 down - which is inside our band, so both were printed across
		-- the window's title.
		for _, spec in ipairs({ { "OpenMailSenderLabel", -33 },
			{ "OpenMailSubjectLabel", -55 } }) do
			local fs = letter:CreateFontString(spec[1], "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetSize(80, 14)
			fs:SetText(spec[1])
			fs:SetPoint("TOPRIGHT", letter, "TOPLEFT", 105, spec[2])
			_G[spec[1]] = fs
		end

		-- THE FONT OBJECTS THE RECEIPT INHERITS. Every line of it takes its ink
		-- from one of these rather than from its own string - 0.18, 0.12, 0.06,
		-- near black, chosen for the parchment the letter used to be printed on -
		-- so a skin that paints the strings one at a time achieves nothing, which
		-- is a thing a mock without them could not show.
		for _, n in ipairs({ "InvoiceTextFontNormal", "InvoiceTextFontSmall" }) do
			local font = CreateFrame("Frame", nil, UIParent):CreateFontString(nil)
			font:SetTextColor(0.18, 0.12, 0.06, 1)
			_G[n] = font
		end

		-- THE REPORT BUTTON, AND IT IS HIDDEN - there is no reporting on this
		-- build. It matters because the sender's name lives in a frame pinned by
		-- TWO corners, its label on one side and THIS on the other: a box pinned
		-- to something the client never lays out comes back with its bottom above
		-- its top, and the name is drawn beside the window's title instead of
		-- beside From.
		local spam = CreateFrame("Button", "OpenMailReportSpamButton", letter)
		spam:SetSize(110, 22)
		spam:SetPoint("TOPRIGHT", letter, "TOPRIGHT", 0, -32)
		spam:Hide()

		local who = CreateFrame("Frame", "OpenMailSender", letter)
		who:SetPoint("TOPLEFT", _G.OpenMailSenderLabel, "TOPRIGHT", 5, 0)
		who:SetPoint("BOTTOMRIGHT", spam, "BOTTOMLEFT", -5, 0)
		who.Name = who:CreateFontString(nil, "ARTWORK")
		who.Name:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
		who.Name:SetText("Horde Auction House")
		who.Name:SetPoint("LEFT", who, "LEFT", 0, 0)

		-- THE LETTER ITSELF IS A SimpleHTML, not a font string. Its SetFont AND
		-- its SetTextColor both take a TEXT TYPE first - P, H1, H2, H3 - and
		-- calling either the font-string way is an outright error rather than a
		-- no-op. The book reader's page was already modelled this way and this one
		-- was not, so a line naming it alongside the ordinary strings passed in
		-- here and took the whole mail dresser down in the game.
		do
			local html = letter:CreateFontString("OpenMailBodyText", "ARTWORK")
			function html:GetObjectType() return "SimpleHTML" end
			html.__fonts, html.__colors = {}, {}
			function html:GetFont(kind)
				if type(kind) ~= "string" then
					fail("bad argument #1 to GetFont on the letter - it takes a text type")
					return nil
				end
				local f = self.__fonts[kind]
				if not f then return "Fonts\\MORPHEUS.TTF", 14, "" end
				return f[1], f[2], f[3]
			end
			function html:SetFont(kind, file, size, flags)
				if type(kind) ~= "string" then
					fail("bad argument #1 to SetFont on the letter - it takes a text type")
					return
				end
				self.__fonts[kind] = { file, size, flags }
			end
			function html:SetTextColor(kind, r, g, b, a)
				if type(kind) ~= "string" then
					fail("bad argument #1 to SetTextColor on the letter - it takes a"
						.. " text type")
					return
				end
				self.__colors[kind] = { r, g, b, a }
			end
			function html:GetTextColor(kind)
				local c = self.__colors[kind or "P"]
				if not c then return 0.42, 0.34, 0.18, 1 end
				return c[1], c[2], c[3], c[4]
			end
			_G.OpenMailBodyText = html
		end

		for _, n in ipairs({
			"OpenMailInvoiceItemLabel", "OpenMailInvoiceBuyMode",
			"OpenMailInvoicePurchaser",
		}) do
			local fs = letter:CreateFontString(n, "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetText(n)
			fs:SetTextColor(0.42, 0.34, 0.18, 1)
			_G[n] = fs
		end

		-- AND FOUR OF THE LINES ARE NOT TEXT AT ALL. Sale price, deposit, the
		-- house's cut and what you got are MONEY FRAMES - gold, silver and copper
		-- each in their own string with a coin beside it. They answer GetFont and
		-- SetFont like anything else does, and calling either on a frame THROWS -
		-- so a mock that made them font strings let a dresser be written that took
		-- the whole postbox down in the game and passed in here.
		for _, n in ipairs({ "OpenMailInvoiceSalePrice", "OpenMailInvoiceDeposit",
			"OpenMailInvoiceHouseCut", "OpenMailInvoiceAmountReceived" }) do
			local money = CreateFrame("Frame", n, letter)
			money:SetSize(120, 14)
			local coin = money:CreateFontString(n .. "GoldButtonText", "OVERLAY")
			coin:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			coin:SetText("67")
			coin:SetTextColor(0.42, 0.34, 0.18, 1)
			_G[n] = money
		end
		for i = 1, 2 do
			local tab = CreateFrame("Button", "MailFrameTab" .. i, mail)
			tab:SetNormalTexture("Interface\\ChatFrame\\UI-ChatFrame-Tab-Up")
			tab:CreateFontString(nil, "OVERLAY")
		end
		local sf = CreateFrame("ScrollFrame", "SendMailScrollFrame", _G.SendMailFrame)
		for _ = 1, 3 do
			sf:CreateTexture(nil, "ARTWORK"):SetTexture("UI-Character-ScrollBar")
		end
		sf.ScrollBar = CreateFrame("Slider", nil, sf)

		-- THE LETTER YOU ARE WRITING is a ScrollingEditBox with its parchment in
		-- its OWN background layer and its bar as a frame beside it. Neither is a
		-- region of SendMailFrame, so a sweep of the pane reaches neither - which
		-- is why the page stayed gold behind our glass.
		_G.MailEditBox = CreateFrame("Frame", "MailEditBox", _G.SendMailFrame)
		local paper = _G.MailEditBox:CreateTexture(nil, "BACKGROUND")
		paper:SetTexture("Interface\\Stationery\\Stationery")
		local inner = CreateFrame("EditBox", nil, _G.MailEditBox)
		inner:SetTextColor(0.20, 0.14, 0.08, 1)
		function _G.MailEditBox:GetEditBox() return inner end
		_G.MailEditBoxScrollBar = CreateFrame("Slider", "MailEditBoxScrollBar",
			_G.SendMailFrame)
		_G.MailEditBoxScrollBar.Track = CreateFrame("Frame", nil, _G.MailEditBoxScrollBar)
		_G.MailEditBoxScrollBar.Track:CreateTexture(nil, "ARTWORK"):SetTexture("minimal-scrollbar-track-top")

		-- EVERY TEXT FIELD IN THE GAME is the same three slices of
		-- Common-Input-Border, drawn as BACKGROUND regions of the box itself.
		-- Nothing to swap and nothing a sweep of the pane reaches, which is why
		-- five of them kept their stone with our glass behind.
		local function inputBox(name, parent, coin)
			local box = CreateFrame("EditBox", name, parent)
			for _, part in ipairs({ "Left", "Middle", "Right" }) do
				local tex = box:CreateTexture(name .. part, "BACKGROUND")
				tex:SetTexture("Interface\\Common\\Common-Input-Border")
				_G[name .. part] = tex
			end
			if coin then
				-- IN THE SAME LAYER as the border, so a plain sweep takes it and the
				-- player is typing gold into a nameless box.
				box.texture = box:CreateTexture(nil, "BACKGROUND")
				box.texture:SetTexture("Interface\\MoneyFrame\\UI-MoneyIcons")
				box.texture:SetSize(13, 13)
			end
			_G[name] = box
			return box
		end
		inputBox("SendMailNameEditBox", _G.SendMailFrame)
		inputBox("SendMailSubjectEditBox", _G.SendMailFrame)

		-- THE MONEY ROW, at the client's own widths and its own coin offsets -
		-- and they are NOT the same offset. Gold's coin hangs 2 outside the box
		-- and the other two sit 8 INSIDE, because the narrow pair's border art
		-- stops ten short of the box and the overhang had to be filled. Mocked
		-- with the coins unanchored, every one of them was wherever the last
		-- SetPoint left it and a row that dressed three coins three different
		-- distances from three identical wells could not be wrong here.
		local prev
		for _, spec in ipairs({ { "Gold", 58, 2 }, { "Silver", 30, -8, 26 },
			{ "Copper", 30, -8, 16 } }) do
			local box = inputBox("SendMailMoney" .. spec[1], _G.SendMailFrame, true)
			box:SetSize(spec[2], 20)
			if prev then
				box:SetPoint("LEFT", prev, "RIGHT", spec[4], 0)
			else
				box:SetPoint("TOPLEFT", _G.SendMailFrame, "TOPLEFT", 90, -120)
			end
			box.texture:SetPoint("LEFT", box, "RIGHT", spec[3], 0)
			prev = box
		end

		-- The total, wrapped twice: a black inset and a thin gold edge.
		for _, n in ipairs({ "SendMailMoneyInset", "SendMailMoneyBg" }) do
			local f = CreateFrame("Frame", n, _G.SendMailFrame)
			f:CreateTexture(nil, "BACKGROUND"):SetTexture("Interface\\Common\\Common-Input-Border")
			f:CreateTexture(nil, "BORDER"):SetTexture("Interface\\Common\\ThinGoldEdge")
			_G[n] = f
		end

		-- THE ATTACHMENT SLOTS, whose plate is a BACKGROUND region rather than
		-- the normal texture - so ClearButton alone leaves every one of them
		-- stone, and a plain sweep would take the item's picture with it.
		local function slot(name, parent)
			local b = CreateFrame("Button", name, parent)
			b:SetWidth(37) b:SetHeight(37)
			b:CreateTexture(nil, "BACKGROUND"):SetTexture("Interface\\Buttons\\UI-Slot-Background")
			b.Icon = b:CreateTexture(nil, "BACKGROUND")
			b.Icon:SetTexture("Interface\\Icons\\INV_Misc_Note_01")
			_G[name] = b
			return b
		end
		for i = 1, 16 do
			slot("SendMailAttachment" .. i, _G.SendMailFrame)
			slot("OpenMailAttachmentButton" .. i, _G.OpenMailFrame)
		end
		slot("OpenMailLetterButton", _G.OpenMailFrame)

		-- THE PANE'S OWN TITLE, on the PANE and not on the window. The words on
		-- this frame are INBOX and SEND MAIL, one per tab, and the frame's own
		-- $parentTitleText is never filled in - so the title here changes with
		-- the tab, and a mock that hangs both off the window cannot show it.
		for _, pair in ipairs({ { "InboxTitleText", "InboxFrame", "Inbox" },
			{ "SendMailTitleText", "SendMailFrame", "Send Mail" } }) do
			local fs = _G[pair[2]]:CreateFontString(pair[1], "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 14, "")
			fs:SetTextColor(1, 0.82, 0, 1)
			fs:SetText(pair[3])
			-- NEAR THE TOP OF ITS PANE, which is where the client puts it - and the
			-- reason it matters is the pane that is DOWN. Its title is still a string
			-- four units below the glass, so a walk measuring the other pane counts
			-- it as that pane's first content and pushes the whole form down to clear
			-- a band it was already clear of.
			fs:SetPoint("TOP", _G[pair[2]], "TOP", 0, -4)
			_G[pair[1]] = fs
		end

		-- THE FORM ITSELF: who it goes to and what it is about at the TOP, and the
		-- money block hung off the pane's BOTTOM - which is the pairing that
		-- matters. Move the pane down and the block goes down with it, into the
		-- strip and on top of Send and Cancel.
		local to, subj = _G.SendMailNameEditBox, _G.SendMailSubjectEditBox
		to:SetSize(140, 20)
		to:SetPoint("TOPLEFT", _G.SendMailFrame, "TOPLEFT", 90, -30)
		subj:SetSize(140, 20)
		subj:SetPoint("TOPLEFT", to, "BOTTOMLEFT", 0, 0)

		-- SEND MONEY OR C.O.D. Two CheckButtons off UIRadioButtonTemplate, each
		-- with its label as a $parentText string - and CheckButtons, not
		-- Buttons: mocked as plain buttons they answered neither GetChecked nor
		-- SetChecked, so a mark that has to follow the client's own state had
		-- nothing to follow and could not come out wrong.
		local money = CreateFrame("Button", "SendMailMoneyButton", _G.SendMailFrame)
		money:SetSize(20, 20)
		money:SetPoint("BOTTOMLEFT", _G.SendMailFrame, "BOTTOMLEFT", 15, 125)
		local send = CreateFrame("CheckButton", "SendMailSendMoneyButton",
			_G.SendMailFrame)
		-- 16, WHICH IS UIRadioButtonTemplate'S OWN SIZE, and the pair is
		-- stacked with the second at the first's BOTTOMLEFT plus one - so
		-- fifteen between their centres and no more. Mocked at 20 they had
		-- four units of slack the client never gives them, and a chip too big
		-- for the group could not overlap in here.
		send:SetSize(16, 16)
		send:SetPoint("BOTTOMLEFT", _G.SendMailFrame, "BOTTOMLEFT", 15, 125)
		send:SetNormalTexture("Interface\\Buttons\\UI-RadioButton")
		send:SetCheckedTexture("Interface\\Buttons\\UI-RadioButton")
		send:SetChecked(true)
		local cod = CreateFrame("CheckButton", "SendMailCODButton", _G.SendMailFrame)
		cod:SetSize(16, 16)
		cod:SetPoint("TOPLEFT", send, "BOTTOMLEFT", 0, 1)
		cod:SetNormalTexture("Interface\\Buttons\\UI-RadioButton")
		cod:SetCheckedTexture("Interface\\Buttons\\UI-RadioButton")
		for _, pair in ipairs({ { send, "Send Money" }, { cod, "C.O.D." } }) do
			local fs = pair[1]:CreateFontString(pair[1]:GetName() .. "Text", "OVERLAY")
			fs:SetText(pair[2])
			fs:SetPoint("LEFT", pair[1], "RIGHT", 0, 0)
			pair[1].Text = fs
		end

		-- AND THE ONE GLOBAL BOTH PATHS GO THROUGH. The template's OnClick calls
		-- it, and so does the client's own update when an attachment rules
		-- C.O.D. out - which is the case no button ever hears about.
		function _G.SendMailRadioButton_OnClick(index)
			send:SetChecked(index == 1)
			cod:SetChecked(index ~= 1)
		end

		-- AND THE TOTAL, which is the LOWEST thing the client hangs off this
		-- pane - 96 above its foot against the radio's 125. Clearing the radio
		-- and not this one is how the strip came back with your purse printed
		-- across Send and Cancel.
		local total = CreateFrame("Frame", "SendMailMoneyFrame", _G.SendMailFrame)
		total:SetSize(120, 14)
		total:SetPoint("BOTTOMRIGHT", _G.SendMailFrame, "BOTTOMLEFT", 175, 96)

		for _, spec in ipairs({ { "SendMailCancelButton", -53, 92 } }) do
			local b = CreateFrame("Button", spec[1], _G.SendMailFrame)
			b:SetSize(80, 22)
			b:SetPoint("BOTTOMRIGHT", _G.SendMailFrame, "BOTTOMRIGHT", spec[2],
				spec[3])
			b:SetNormalTexture("panel-button-up")
			local fs = b:CreateFontString(nil, "OVERLAY")
			fs:SetText("Cancel")
			b.__fs = fs
			function b:GetFontString() return self.__fs end
		end
		local send = CreateFrame("Button", "SendMailMailButton", _G.SendMailFrame)
		send:SetSize(80, 22)
		send:SetPoint("RIGHT", _G.SendMailCancelButton, "LEFT", 0, 0)
		send:SetNormalTexture("panel-button-up")
		do
			local fs = send:CreateFontString(nil, "OVERLAY")
			fs:SetText("Send")
			send.__fs = fs
			function send:GetFontString() return self.__fs end
		end

		-- AND ONE PANE UP AT A TIME, as the window shows them.
		_G.SendMailFrame:Hide()
		_G.OpenMailFrame:Hide()

		-- THE LETTERS THEMSELVES: seven rows, each a Button with a label on it and
		-- a child of the pane. Which is exactly the shape a sweep for Send and
		-- Reply looks for, so all seven used to come back wearing a pressable
		-- surface - the panel behind every line in the list.
		for i = 1, 7 do
			local row = CreateFrame("Button", "MailItem" .. i, _G.InboxFrame)
			row:SetSize(300, 41)
			if i == 1 then
				row:SetPoint("TOPLEFT", _G.InboxFrame, "TOPLEFT", 12, -80)
			else
				row:SetPoint("TOPLEFT", _G["MailItem" .. (i - 1)], "BOTTOMLEFT", 0, -2)
			end
			-- ITS OWN ART: two slices of MailItemBorder and a rule under them, all
			-- BACKGROUND regions of the ROW - so a sweep over the pane reaches none
			-- of them and seven stone plaques sat in the recess.
			row:CreateTexture(nil, "BACKGROUND")
				:SetTexture("Interface\\MailFrame\\MailItemBorder")
			-- ...and the letter's picture is a BUTTON inside it, the way a vendor's
			-- goods are, which is what makes stripping the row safe.
			local icon = CreateFrame("Button", "MailItem" .. i .. "Button", row)
			icon:SetSize(37, 37)
			icon:SetPoint("TOPLEFT", row, "TOPLEFT", 4, -4)
			icon:SetNormalTexture("slot-border")
			local fs = row:CreateFontString("MailItem" .. i .. "Subject", "OVERLAY")
			fs:SetText("Auction successful: Rough Stone")
			row.__fs = fs
			function row:GetFontString() return self.__fs end
		end

		-- The page turners and Open All, which the client hangs 114 up from the
		-- window's bottom edge - inside the recess in a window this shape, hard
		-- against the last letter in the list.
		for _, spec in ipairs({ { "InboxPrevPageButton", 32, 30 },
			{ "InboxNextPageButton", 32, 305 } }) do
			local b = CreateFrame("Button", spec[1], _G.InboxFrame)
			b:SetSize(spec[2], spec[2])
			b:SetPoint("CENTER", _G.MailFrame, "BOTTOMLEFT", spec[3], 114)
			b:SetNormalTexture("Interface\\Buttons\\UI-SpellbookIcon-PrevPage-Up")
			-- WITH THE WORD ON IT, and the word is an UNNAMED REGION of the button
			-- anchored OUTSIDE it - Prev's to the right of its button, Next's to the
			-- left - so two turns a chevron apart print one word over the other.
			--
			-- NOT the button's own label: GetFontString never sees one of these, so a
			-- mock that hung the word off that instead let a fix be written which
			-- cleared nothing at all and still passed in here.
			local fs = b:CreateFontString(nil, "ARTWORK")
			fs:SetTextColor(1, 0.82, 0, 1)
			fs:SetText(spec[1]:find("Prev") and "Prev" or "Next")
			if spec[1]:find("Prev") then
				fs:SetPoint("LEFT", b, "RIGHT", 0, 0)
			else
				fs:SetPoint("RIGHT", b, "LEFT", 0, 0)
			end
			_G[spec[1]] = b
		end
		local openAll = CreateFrame("Button", "OpenAllMail", _G.InboxFrame)
		openAll:SetSize(120, 24)
		openAll:SetPoint("CENTER", _G.MailFrame, "BOTTOM", -21, 114)
		openAll:SetNormalTexture("panel-button-up")
		do
			local fs = openAll:CreateFontString(nil, "OVERLAY")
			fs:SetText("Open All")
			openAll.__fs = fs
			function openAll:GetFontString() return self.__fs end
		end
		
		local it = buildPanel("ItemTextFrame")
		-- ITS PAGE IS FOUR NAMED TEXTURES, not one and not regions of anything
		-- the sweep walks - miss them and the parchment stays with glass behind.
		for _, n in ipairs({ "ItemTextMaterialTopLeft", "ItemTextMaterialTopRight",
			"ItemTextMaterialBotLeft", "ItemTextMaterialBotRight" }) do
			local tex = it:CreateTexture(nil, "BACKGROUND")
			tex:SetTexture("Interface\\ItemTextFrame\\Parchment")
			_G[n] = tex
		end
		-- THE PAGE IS A SimpleHTML, NOT A FontString, and that distinction is
		-- the whole of why the book reader's dresser threw. It holds a font PER
		-- TEXT TYPE - P, H1, H2, H3 - so GetFont, SetFont and SetTextColor all
		-- take the type as their first argument, and calling them the
		-- FontString way is an outright error rather than a no-op.
		--
		-- The mock had it as a FontString, so every version of the dresser
		-- looked correct in here while throwing in the game.
		do
			local html = it:CreateFontString(nil, "ARTWORK")
			html.__objectType = "SimpleHTML"
			function html:GetObjectType() return "SimpleHTML" end
			html.__fonts, html.__colors = {}, {}
			function html:GetFont(kind)
				if type(kind) ~= "string" then
					fail("bad argument #1 to GetFont on a SimpleHTML - it takes a"
						.. " text type")
					return nil
				end
				local f = self.__fonts[kind]
				if not f then return "Fonts\\MORPHEUS.TTF", 14, "" end
				return f[1], f[2], f[3]
			end
			function html:SetFont(kind, file, size, flags)
				if type(kind) ~= "string" then
					fail("bad argument #1 to SetFont on a SimpleHTML")
					return
				end
				self.__fonts[kind] = { file, size, flags }
			end
			function html:SetTextColor(kind, r, g, b, a)
				if type(kind) ~= "string" then
					fail("bad argument #1 to SetTextColor on a SimpleHTML")
					return
				end
				self.__colors[kind] = { r, g, b, a }
			end
			function html:GetTextColor(kind)
				local c = self.__colors[kind or "P"]
				if not c then return 0.13, 0.09, 0.05, 1 end
				return c[1], c[2], c[3], c[4]
			end
			_G.ItemTextPageText = html
		end
		_G.ItemTextTitleText = it:CreateFontString(nil, "OVERLAY")
		-- AND THE COUNT BETWEEN THEM, in a box 192 wide that says "Page 1": the
		-- room the client reserved, not the words in it.
		_G.ItemTextCurrentPage = it:CreateFontString(nil, "OVERLAY")
		_G.ItemTextCurrentPage:SetSize(192, 0)
		_G.ItemTextCurrentPage:SetText("Page 1")
		_G.ItemTextCurrentPage:SetPoint("TOP", it, "TOP", 20, -35)
		-- THE TROUGH IS DRAWN ON THE SCROLL FRAME, not on the bar.
		-- UIPanelScrollBarTemplate carries only two arrows and a thumb; $parentTop,
		-- $parentBottom and $parentMiddle are declared in the SCROLL FRAME's own
		-- layers - so a sweep that reskins the bar leaves a black rail with stone
		-- caps, which is most of what a scroll bar looks like.
		-- WHERE THE CLIENT PUTS IT: 33 in from the right and 63 down, which is
		-- the strip the stone title plate used to need.
		_G.ItemTextScrollFrame = CreateFrame("ScrollFrame", "ItemTextScrollFrame", it)
		_G.ItemTextScrollFrame:SetSize(280, 355)
		_G.ItemTextScrollFrame:SetPoint("TOPRIGHT", it, "TOPRIGHT", -33, -63)
		do
			local sf = _G.ItemTextScrollFrame
			for _, part in ipairs({ "Top", "Bottom", "Middle" }) do
				local tex = sf:CreateTexture(nil, "ARTWORK")
				tex:SetTexture("Interface\\PaperDollInfoFrame\\UI-Character-ScrollBar")
			end
			sf.ScrollBar = CreateFrame("Slider", nil, sf)
			sf.ScrollBar.ScrollUpButton = CreateFrame("Button", nil, sf.ScrollBar)
			sf.ScrollBar.ScrollUpButton:SetNormalTexture("scroll-up")
		end
		-- ITS PAGE TURNS ARE IN THE HEADER BAND, 41 down from the top corners -
		-- one at each end of a window 384 across, with the book's title between
		-- them. 15c puts a page turn in the footer.
		for _, spec in ipairs({ { "ItemTextPrevPageButton", "TOPLEFT", 75 },
			{ "ItemTextNextPageButton", "TOPRIGHT", -23 } }) do
			local b = CreateFrame("Button", spec[1], it)
			b:SetSize(32, 32)
			b:SetPoint("CENTER", it, spec[2], spec[3], -41)
			b:SetNormalTexture("Interface\\Buttons\\UI-SpellbookIcon-PrevPage-Up")
			_G[spec[1]] = b
		end
		
		-- THE GROUP FINDER, which is two windows behind two tabs on one parchment
		-- frame. LFGParentFrame is the OLD build - 384 by 512, an eye where a
		-- portrait goes, tabs INSIDE its bottom margin rather than below it - and
		-- both of its panes are setAllPoints, so neither has a point to move by.
		--
		-- TAB ONE IS THE LISTING AND TAB TWO IS THE BROWSE, which reads backwards
		-- until you look at LFGParentFrameTab1_OnClick.
		do
			local lfg = buildPanel("LFGParentFrame")
			lfg:SetSize(384, 512)
			lfg.selectedTab = 1

			-- THE EYE, which is this window's portrait: a frame with the picture in
			-- it rather than a texture of the window.
			local eye = CreateFrame("Frame", "LFGParentFramePortrait", lfg)
			eye:SetSize(64, 64)
			eye:SetPoint("TOPLEFT", lfg, "TOPLEFT", 9, -5)
			local eyeIcon = eye:CreateTexture("LFGParentFramePortraitIcon", "BACKGROUND")
			eyeIcon:SetTexture("Interface\\LFGFrame\\UI-LFG-PORTRAIT")
			eyeIcon:SetSize(64, 64)

			-- ITS X HAS NO NAME AND NO PARENT KEY. The client declares an
			-- anonymous <Button inherits="UIPanelCloseButton"> and nothing can ask
			-- for it - so a window built with a named one could not show that the
			-- generic dresser misses it, and it kept the client's red X.
			local shut = CreateFrame("Button", nil, lfg)
			shut:SetSize(32, 32)
			shut:SetPoint("TOPRIGHT", lfg, "TOPRIGHT", -26, -8)
			shut:SetNormalTexture("RedButton-Exit")
			shut:SetPushedTexture("RedButton-Exit-Pressed")
			lfg.__shut = shut

			-- ITS TWO TABS, on CharacterFrameTabButtonTemplate like the character
			-- sheet's - three slices of stone and a word.
			for i, word in ipairs({ "Group", "Browse" }) do
				local tab = CreateFrame("Button", "LFGParentFrameTab" .. i, lfg)
				tab:SetSize(80, 32)
				for _, part in ipairs({ "Left", "Middle", "Right" }) do
					local t = tab:CreateTexture("LFGParentFrameTab" .. i .. part, "BACKGROUND")
					t:SetTexture("Interface\\ChatFrame\\UI-ChatFrame-Tab-Up")
					_G["LFGParentFrameTab" .. i .. part] = t
				end
				local fs = tab:CreateFontString("LFGParentFrameTab" .. i .. "Text", "OVERLAY")
				fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
				fs:SetText(word)
				tab:SetFontString(fs)
				if i == 1 then
					tab:SetPoint("BOTTOMLEFT", lfg, "BOTTOMLEFT", 16, 45)
				else
					tab:SetPoint("LEFT", _G.LFGParentFrameTab1, "RIGHT", -14, 0)
				end
				lfg["Tab" .. i] = tab
			end

			--- One of the two panes: setAllPoints, its own parchment, its own title.
			local function pane(name, hidden)
				local f = CreateFrame("Frame", name, lfg)
				f:SetAllPoints(lfg)
				for _, art in ipairs({ "FrameBackgroundTop", "FrameBackgroundBottom" }) do
					local t = f:CreateTexture(name .. art, "BACKGROUND")
					t:SetTexture("Interface\\LFGFrame\\UI-LFG-FRAME")
					_G[name .. art] = t
				end
				f.BackgroundArt = f:CreateTexture(name .. "BackgroundArt", "BACKGROUND")
				f.BackgroundArt:SetTexture("groupfinder-background-classic")
				f.BackgroundArt:SetSize(324, 282)
				f.BackgroundArt:SetPoint("TOPLEFT", f, "TOPLEFT", 22, -129)
				local fs = f:CreateFontString(name .. "FrameTitle", "BACKGROUND")
				fs:SetFont("Fonts\\FRIZQT__.TTF", 14, "")
				fs:SetText("Group Finder")
				fs:SetPoint("TOP", f, "TOP", 0, -18)
				fs:SetTextColor(1, 0.82, 0)
				_G[name .. "FrameTitle"] = fs
				if hidden then f:Hide() end
				return f
			end

			--- A WowStyle1 dropdown, which is what both filters are.
			local function drop(name, parent, width)
				local d = CreateFrame("Button", name, parent)
				d:SetSize(width, 24)
				d.Background = d:CreateTexture(nil, "BACKGROUND")
				d.Background:SetTexture("common-dropdown-classic-textholder")
				d.Arrow = d:CreateTexture(nil, "OVERLAY")
				d.Arrow:SetTexture("common-dropdown-classic-a-buttonDown")
				d.Text = d:CreateFontString(nil, "OVERLAY")
				d.Text:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
				d.Text:SetText(name)
				return d
			end

			--- The gear, one per pane: a 16x16 dropdown with an atlas for a face and
			--  no label at all.
			local function gear(name, parent)
				local g = CreateFrame("Button", name, parent)
				g:SetSize(16, 16)
				g:SetPoint("TOPRIGHT", parent, "TOPRIGHT", -40, -44)
				g.Icon = g:CreateTexture(nil, "ARTWORK")
				g.Icon:SetTexture("OptionsIcon-Brown")
				return g
			end

			--- One of the four buttons on a pane's bottom edge.
			local function foot(pfx, parent, key, width, corner, x)
				local b = CreateFrame("Button", pfx .. key, parent)
				b:SetSize(width, 22)
				b:SetPoint(corner, parent, corner, x, 79)
				b:SetNormalTexture("panel-button-up")
				local fs = b:CreateFontString(nil, "OVERLAY")
				fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
				fs:SetText(key)
				b:SetFontString(fs)
				parent[key] = b
			end

			-- BROWSE: two filters and a refresh across the top, a modern scroll box
			-- under them, and two buttons on the bottom edge.
			local browse = pane("LFGBrowseFrame", false)
			browse.CategoryDropdown = drop("LFGBrowseFrameCategoryDropdown", browse, 115)
			browse.CategoryDropdown:SetPoint("TOPLEFT", browse, "TOPLEFT", 26, -94)
			browse.ActivityDropdown = drop("LFGBrowseFrameActivityDropdown", browse, 115)
			browse.ActivityDropdown:SetPoint("LEFT", browse.CategoryDropdown, "RIGHT",
				5, 0)
			local refresh = CreateFrame("Button", "LFGBrowseFrameRefreshButton", browse)
			refresh:SetSize(32, 32)
			refresh:SetPoint("LEFT", browse.ActivityDropdown, "RIGHT", -1, 0)
			refresh.Icon = refresh:CreateTexture(nil, "ARTWORK")
			refresh.Icon:SetTexture("Interface\\Buttons\\UI-RefreshButton")
			refresh:SetNormalTexture("Interface\\Buttons\\UI-SquareButton-Up")
			refresh:SetPushedTexture("Interface\\Buttons\\UI-SquareButton-Down")
			browse.RefreshButton = refresh
			browse.OptionsButton = gear("LFGBrowseFrameOptionsButton", browse)

			-- A MODERN SCROLL BOX, which does not own its rows: it acquires them from
			-- a pool during its OWN layout, after the window's update has returned.
			local box = CreateFrame("Frame", "LFGBrowseFrameScrollBox", browse)
			box:SetSize(324, 282)
			box:SetPoint("TOPLEFT", browse, "TOPLEFT", 22, -128)
			box.__rows = {}
			local function mintRow()
				local row = CreateFrame("Button", nil, box)
				row:SetSize(312, 36)
				row.ResultBG = row:CreateTexture(nil, "BACKGROUND")
				row.ResultBG:SetColorTexture(1, 1, 1, 0.04)
				row.PartyIcon = row:CreateTexture(nil, "ARTWORK")
				row.PartyIcon:SetTexture("Interface\\GroupFrame\\UI-Group-LeaderIcon")
				row.ClassIcon = row:CreateTexture(nil, "ARTWORK")
				row.ClassIcon:SetTexture("groupfinder-icon-class-warrior")
				row.Selected = row:CreateTexture(nil, "OVERLAY")
				row.Selected:SetTexture("groupfinder-highlightbar-yellow")
				row.Highlight = row:CreateTexture(nil, "HIGHLIGHT")
				row.Highlight:SetTexture("groupfinder-highlightbar-blue")
				for _, key in ipairs({ "Name", "Level", "ActivityName" }) do
					local fs = row:CreateFontString(nil, "ARTWORK")
					fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
					fs:SetText(key)
					fs:SetTextColor(1, 0.82, 0)
					row[key] = fs
				end
				row.__fs = row.Name
				function row:GetFontString() return self.__fs end
				box.__rows[#box.__rows + 1] = row
				return row
			end
			for _ = 1, 6 do mintRow() end
			function box:GetFrames() return self.__rows end
			function box:ForEachFrame(fn)
				for _, row in ipairs(self.__rows) do fn(row) end
			end
			-- ...AND ONE MINTED LATE, during the box's own layout, which is the whole
			-- shape of the pooled-row trap: anything asked from inside the WINDOW's
			-- update is answered with the set that was there before.
			-- A ROW MINTED DURING LAYOUT, AND ANOTHER ON EVERY LAYOUT AFTER IT.
			-- One is enough to show that a sweep from inside the WINDOW's update
			-- reads the set that was there before; it takes a SECOND, minted
			-- after the dresser has been past, to show that the hook on the box's
			-- own Update is doing anything. Scrolling a real list does exactly
			-- this, over and over.
			-- A ROW ACQUIRED DURING LAYOUT, which is after the WINDOW's update has
			-- returned. That is the whole shape of the pooled-row trap: anything
			-- that asks the box what it is holding from inside a window hook is
			-- answered with the set that was there before.
			--
			-- ASKED FOR, rather than minted on a count: the dresser lays this
			-- window out several times over a run, and a box that grew on each of
			-- them ran out of pool before the check that needs one.
			function box:Update()
				if self.__wantRow then
					self.__wantRow = nil
					self.__grew = mintRow()
				end
			end
			-- AND THE WAY YOU ASK IT TO. ScrollBoxListMixin carries both: Update
			-- is what it runs for itself, FullUpdate is what anything that has
			-- changed its shape calls to make it run one now - and a box whose
			-- shape has changed acquires whatever the new height has room for.
			function box:FullUpdate()
				self.__wantRow = true
				self:Update()
			end
			browse.ScrollBox = box
			local bbar = CreateFrame("Slider", "LFGBrowseFrameScrollBar", browse)
			bbar:SetSize(16, 282)
			bbar:SetPoint("TOPLEFT", box, "TOPRIGHT", 0, 4)
			browse.ScrollBar = bbar
			foot("LFGBrowseFrame", browse, "SendMessageButton", 111, "BOTTOMLEFT", 19)
			foot("LFGBrowseFrame", browse, "GroupInviteButton", 109, "BOTTOMRIGHT", -40)

			-- THE LISTING: three views of the same size and place, a strip of role
			-- buttons above them, and two buttons on the bottom edge.
			local listing = pane("LFGListingFrame", true)
			listing.OptionsButton = gear("LFGListingFrameOptionsButton", listing)
			for _, key in ipairs({ "CategoryView", "ActivityView", "LockedView" }) do
				local v = CreateFrame("Frame", "LFGListingFrame" .. key, listing)
				v:SetSize(324, 282)
				v:SetPoint("TOPLEFT", listing, "TOPLEFT", 22, -128)
				if key ~= "CategoryView" then v:Hide() end
				listing[key] = v
			end
			for _, spec in ipairs({ { "SoloRoleButtons", 194, "TOPLEFT", 67, -60 },
				{ "GroupRoleButtons", 192, "TOPLEFT", 67, -60 },
				{ "NewPlayerFriendlyButton", 48, "TOPRIGHT", -47, -60 } }) do
				local f = CreateFrame("Button", "LFGListingFrame" .. spec[1], listing)
				f:SetSize(spec[2], 48)
				f:SetPoint(spec[3], listing, spec[3], spec[4], spec[5])
				if spec[1] == "GroupRoleButtons" then f:Hide() end
				listing[spec[1]] = f
			end
			foot("LFGListingFrame", listing, "BackButton", 111, "BOTTOMLEFT", 19)
			foot("LFGListingFrame", listing, "PostButton", 109, "BOTTOMRIGHT", -40)

			-- THE BABY HACK, which is the client's own word for it: each pane
			-- re-anchors BOTH tabs from its OnShow, with a hard SetPoint and the
			-- comment "the selected tab texture doesn't blend well with the LFG
			-- texture, so move it down a hair when it's selected". Two hairs: 45
			-- up from the frame on browse and 43 on the listing.
			--
			-- Nothing calls PanelTemplates_TabResize on that path, so the hook on
			-- that never fires for it and the row simply left the rail.
			for _, pair in ipairs({ { browse, 45 }, { listing, 43 } }) do
				local up = pair[2]
				pair[1]:SetScript("OnShow", function()
					_G.LFGParentFrameTab1:ClearAllPoints()
					_G.LFGParentFrameTab1:SetPoint("BOTTOMLEFT", lfg, "BOTTOMLEFT",
						16, up)
				end)
			end

			-- THE CLIENT'S OWN TAB CLICKS, which is how a check should change tabs:
			-- doing it by hand is a tidier swap than the client performs, and that is
			-- exactly what hid two faults in the social window.
			-- IN THE CLIENT'S OWN ORDER: the tab is SET first, then the pane going
			-- up is SHOWN, and only then is the one coming down hidden. Anything
			-- hooked to the first of those sees a window with two panes up.
			function _G.LFGParentFrameTab1_OnClick()
				lfg.selectedTab = 1
				_G.PanelTemplates_UpdateTabs(lfg)
				listing:Show()
				browse:Hide()
			end
			function _G.LFGParentFrameTab2_OnClick()
				lfg.selectedTab = 2
				_G.PanelTemplates_UpdateTabs(lfg)
				browse:Show()
				listing:Hide()
			end
			-- AND ONE PATH THAT SWAPS PANES WITHOUT GOING THROUGH EITHER OF THEM.
			-- LFGParentFrame_SearchActiveEntry - what the listing's own "find my
			-- group" does - hides one pane and shows the other by hand. No click
			-- function runs, so nothing hooked to those fires, and the only thing
			-- left to answer the tabs being moved by the pane's OnShow is the pane
			-- watch itself.
			function _G.LFGParentFrame_SearchActiveEntry()
				lfg.selectedTab = 2
				_G.PanelTemplates_UpdateTabs(lfg)
				listing:Hide()
				browse:Show()
			end
		end
		-- THE TRADE WINDOW, which was not in this mock at all - so nothing about
		-- it could be checked. Hand-built, with a dozen pieces hung off the frame
		-- at their own fixed offsets: two names five units down, two purses at
		-- sixty, two columns of slots at eighty-nine, and Trade and Cancel in the
		-- bottom right corner five up from the glass.
		do
			local tr = buildPanel("TradeFrame")
			tr:SetSize(344, 446)

			local function txt(n, x, y, w)
				local fs = tr:CreateFontString(n, "OVERLAY")
				fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
				fs:SetSize(w, 12)
				fs:SetText(n)
				fs:SetPoint("TOPLEFT", tr, "TOPLEFT", x, y)
				_G[n] = fs
			end
			txt("TradeFramePlayerNameText", 65, -5, 100)
			txt("TradeFrameRecipientNameText", 230, -5, 80)

			-- WHAT THE OTHER PERSON IS PUTTING IN goes under a heading of its
			-- own, and the client draws that heading as a SECOND WINDOW stitched
			-- onto the right half: its own portrait ring, its own left border,
			-- its own bottom corner and a pale wash behind the lot. Every one is
			-- a region of the frame, so the shell strip already takes them - and
			-- a mock without them cannot show that it does.
			for _, n in ipairs({ "TradeFramePlayerPortrait",
				"TradeFrameRecipientPortrait", "TradeRecipientPortraitFrame",
				"TradeRecipientBotLeftCorner", "TradeRecipientLeftBorder",
				"TradeRecipientBG" }) do
				local t = tr:CreateTexture(n, "OVERLAY")
				t:SetTexture("Interface\\DialogFrame\\UI-DialogBox-Border")
				_G[n] = t
			end

			-- SIX STONE RECESSES, each pinned by TWO corners - one to the panel
			-- it is in and one to the window's TOPLEFT - so a mover that rewrote
			-- a single point would stretch them.
			--
			-- The two ENCHANT recesses are down at -354, below the columns, and
			-- they are anchored to the WINDOW rather than chained off anything
			-- above them: left out of the body list they stay where the client
			-- put them while the rest of the window moves down past them.
			for _, spec in ipairs({
				{ "TradePlayerItemsInset", 4, -83, 166, -352 },
				{ "TradeRecipientItemsInset", 175, -83, 338, -352 },
				{ "TradePlayerEnchantInset", 4, -354, 166, -418 },
				{ "TradeRecipientEnchantInset", 175, -354, 338, -418 },
				{ "TradePlayerInputMoneyInset", 4, -58, 166, -82 },
				{ "TradeRecipientMoneyInset", 175, -58, 338, -81 },
			}) do
				local ins = CreateFrame("Frame", spec[1], tr)
				ins:SetPoint("TOPLEFT", tr, "TOPLEFT", spec[2], spec[3])
				ins:SetPoint("BOTTOMRIGHT", tr, "TOPLEFT", spec[4], spec[5])
				ins:CreateTexture(nil, "BACKGROUND"):SetTexture("trade-inset-stone")
			end

			-- AND THE OTHER PERSON'S PURSE IS WRAPPED TWICE - the recess above
			-- and a thin gold edge inside it, two surrounds for one number. The
			-- same double wrap the postbox's total has.
			local rbg = CreateFrame("Frame", "TradeRecipientMoneyBg", tr)
			rbg:SetSize(120, 30)
			rbg:SetPoint("TOPRIGHT", tr, "TOPRIGHT", -7, -60)
			rbg:CreateTexture(nil, "BORDER"):SetTexture("Interface\\Common\\ThinGoldEdge")

			-- FOURTEEN ITEM ROWS, AND A ROW IS NOT A BUTTON. Each is a FRAME
			-- carrying three pieces of art in its own background layer - the
			-- empty-slot plate, the quest giver's parchment name strip, and the
			-- item's name printed on that parchment - with the pressable
			-- ItemButton laid on top. Mocked as a bare Button the whole row read
			-- as one control and none of that art existed to be taken.
			for _, spec in ipairs({ { "TradePlayerItem", 14 },
				{ "TradeRecipientItem", 182 } }) do
				for i = 1, 7 do
					local n = spec[1] .. i
					local row = CreateFrame("Frame", n, tr)
					row:SetSize(153, 37)
					if i == 1 then
						row:SetPoint("TOPLEFT", tr, "TOPLEFT", spec[2], -89)
					else
						-- The seventh is the ENCHANT slot and sits in a recess of its
						-- own, so it drops 28 rather than the 7 between the other six.
						row:SetPoint("TOPLEFT", _G[spec[1] .. (i - 1)], "BOTTOMLEFT",
							0, i == 7 and -28 or -7)
					end
					local plate = row:CreateTexture(n .. "SlotTexture", "BACKGROUND")
					plate:SetTexture("Interface\\Buttons\\UI-EmptySlot")
					row.SlotTexture = plate
					_G[n .. "SlotTexture"] = plate
					local strip = row:CreateTexture(n .. "NameFrame", "BACKGROUND")
					strip:SetTexture("Interface\\QuestFrame\\UI-QuestItemNameFrame")
					_G[n .. "NameFrame"] = strip
					local fs = row:CreateFontString(n .. "Name", "BACKGROUND")
					fs:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
					fs:SetTextColor(1, 0.82, 0, 1)
					fs:SetText("Item Name")
					_G[n .. "Name"] = fs
					-- The enchant slot wears a glyph of its own, one layer up.
					if i == 7 then
						row:CreateTexture(nil, "ARTWORK")
							:SetTexture("Interface\\TradeFrame\\UI-TradeFrame-EnchantIcon")
					end
					local btn = CreateFrame("Button", n .. "ItemButton", row)
					btn:SetSize(37, 37)
					btn:SetPoint("TOPLEFT", row, "TOPLEFT")
					btn:SetNormalTexture("Interface\\Buttons\\UI-Quickslot2")
					local icon = btn:CreateTexture(n .. "ItemButtonIconTexture", "BACKGROUND")
					icon:SetTexture("Interface\\Icons\\INV_Misc_Note_01")
					_G[n .. "ItemButtonIconTexture"] = icon
					_G[n .. "ItemButton"] = btn
				end
			end

			-- WILL NOT BE TRADED, twice - one label over each enchant recess,
			-- both hung off the WINDOW at -360 like the recesses they head.
			local pench = tr:CreateFontString("TradeFramePlayerEnchantText", "ARTWORK")
			pench:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
			pench:SetText("Will not be traded")
			pench:SetSize(120, 10)
			pench:SetPoint("TOPLEFT", tr, "TOPLEFT", 15, -360)
			_G.TradeFramePlayerEnchantText = pench
			local rench = tr:CreateFontString("TradeFrameRecipientEnchantText", "ARTWORK")
			rench:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
			rench:SetText("Will not be traded")
			rench:SetSize(120, 10)
			rench:SetPoint("LEFT", pench, "LEFT", 166, 0)
			_G.TradeFrameRecipientEnchantText = rench

			-- FOUR HIGHLIGHTS MARKING THE LIVE SIDE, each three slices of
			-- UI-TradeFrame-Highlight in a frame of its own.
			for _, spec in ipairs({
				{ "TradeHighlightPlayer", 150, 266, nil, 6, -85 },
				{ "TradeHighlightRecipient", 150, 266, nil, 176, -85 },
				{ "TradeHighlightPlayerEnchant", 150, 61, "TradeHighlightPlayer", 0, -4 },
				{ "TradeHighlightRecipientEnchant", 150, 61, "TradeHighlightRecipient", 0, -4 },
			}) do
				local h = CreateFrame("Frame", spec[1], tr)
				h:SetSize(spec[2], spec[3])
				if spec[4] then
					h:SetPoint("TOPLEFT", _G[spec[4]], "BOTTOMLEFT", spec[5], spec[6])
				else
					h:SetPoint("TOPLEFT", tr, "TOPLEFT", spec[5], spec[6])
				end
				for _, part in ipairs({ "Top", "Bottom", "Middle" }) do
					local t = h:CreateTexture(spec[1] .. part, "ARTWORK")
					t:SetTexture("Interface\\TradeFrame\\UI-TradeFrame-Highlight")
					_G[spec[1] .. part] = t
				end
			end

			-- YOUR OWN PURSE IS THREE FIELDS, not a readout: the same
			-- MoneyInputFrameTemplate Send Mail uses, with the same three coins
			-- at three different distances from three identical boxes.
			local pm = CreateFrame("Frame", "TradePlayerInputMoneyFrame", tr)
			pm:SetSize(120, 24)
			pm:SetPoint("TOPLEFT", tr, "TOPLEFT", 11, -61)
			local prev
			for _, spec in ipairs({ { "Gold", 56, 2, 0 }, { "Silver", 30, -8, 22 },
				{ "Copper", 30, -8, 11 } }) do
				local n = "TradePlayerInputMoneyFrame" .. spec[1]
				local box = CreateFrame("EditBox", n, pm)
				box:SetSize(spec[2], 20)
				for _, part in ipairs({ "Left", "Middle", "Right" }) do
					local t = box:CreateTexture(n .. part, "BACKGROUND")
					t:SetTexture("Interface\\Common\\Common-Input-Border")
					_G[n .. part] = t
				end
				box.texture = box:CreateTexture(nil, "BACKGROUND")
				box.texture:SetTexture("Interface\\MoneyFrame\\UI-MoneyIcons")
				box.texture:SetSize(13, 13)
				if prev then
					box:SetPoint("LEFT", prev, "RIGHT", spec[4], 0)
				else
					box:SetPoint("TOPLEFT", pm, "TOPLEFT", 0, 0)
				end
				box.texture:SetPoint("LEFT", box, "RIGHT", spec[3], 0)
				pm[spec[1]:lower()] = box
				_G[n] = box
				prev = box
			end

			-- AND THE CLIENT PUTS IT OUT OF REACH. TradeFrame_OnLoad calls
			-- TradePlayerInputMoneyFrame:SetForbidden() - a real call on an
			-- ordinary window, not something reserved for the shop - so every
			-- method on it and on its three fields throws from our side.
			--
			-- It is still a CHILD OF THE WINDOW, which is the trap: any sweep
			-- that walks TradeFrame's children and asks each one a question
			-- dies on this one.
			_G.__forbid(pm)

			-- AND THEIRS IS A READOUT, three coins and three numbers on three
			-- BUTTONS - which is the trap in sweeping this window for buttons
			-- with labels on them.
			local rm = CreateFrame("Frame", "TradeRecipientMoneyFrame", tr)
			rm:SetSize(120, 24)
			rm:SetPoint("TOPRIGHT", tr, "TOPRIGHT", -5, -64)
			for _, part in ipairs({ "Gold", "Silver", "Copper" }) do
				local n = "TradeRecipientMoneyFrame" .. part .. "Button"
				local b = CreateFrame("Button", n, rm)
				b:SetSize(30, 14)
				local fs = b:CreateFontString(n .. "Text", "OVERLAY")
				fs:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
				fs:SetTextColor(1, 1, 1, 1)
				fs:SetText("12")
				b:SetFontString(fs)
				b:CreateTexture(nil, "OVERLAY")
					:SetTexture("Interface\\MoneyFrame\\UI-MoneyIcons")
				_G[n .. "Text"] = fs
				_G[n] = b
			end

			-- TRADE AND CANCEL, in the corner, five up from the glass and under the
			-- recess. 15a puts them in a strip of their own.
			-- ...AND EACH WITH THE WORD ON IT. Both are UIPanelButtonTemplate,
			-- which means a ButtonText - and a button with no label is not a
			-- button the sweep for buttons-with-labels can find, so a mock
			-- without one cannot show whether either was ever dressed.
			local function action(name, w, place)
				local b = CreateFrame("Button", name, tr)
				b:SetSize(w, 22)
				b:SetNormalTexture("panel-button-up")
				local fs = b:CreateFontString(name .. "Text", "OVERLAY")
				fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
				fs:SetText(name)
				b:SetFontString(fs)
				place(b)
				_G[name] = b
				return b
			end
			local trade = action("TradeFrameTradeButton", 85, function(b)
				b:SetPoint("BOTTOMRIGHT", tr, "BOTTOMRIGHT", -85, 5)
			end)
			action("TradeFrameCancelButton", 77, function(b)
				b:SetPoint("TOPLEFT", trade, "TOPRIGHT", 3, 0)
			end)
		end

		-- Two of them: TradeSkillFrame is First Aid and cooking, CraftFrame is
		-- enchanting and a hunter's beast training.
		for _, prefix in ipairs({ "TradeSkill", "Craft" }) do
			local f = buildPanel(prefix .. "Frame")
			-- WHERE THIS CLIENT PUTS THEM, read off the window itself rather than off
			-- the source Blizzard published: 1.15.9 sets the two SIDE BY SIDE in a
			-- window far wider than the 384 that source declares, and the published
			-- version stacks them in a narrow one. Both start inside our header band,
			-- which is the whole question - but a mock built to the stacked shape
			-- could not show room reserved over the RIGHT-hand pane doing anything,
			-- because in that shape the right-hand pane is already far enough down.
			for _, spec in ipairs({
				{ "ListScrollFrame", 295, 409, "TOPLEFT", 25, -75 },
				{ "DetailScrollFrame", 298, 409, "TOPLEFT", 343, -74 },
			}) do
				local sc = CreateFrame("ScrollFrame", prefix .. spec[1], f)
				sc:SetSize(spec[2], spec[3])
				sc:SetPoint(spec[4], f, spec[4], spec[5], spec[6])
				sc:CreateTexture(nil, "BACKGROUND"):SetTexture("Interface\\Craft\\Parchment")
				sc.ScrollBar = CreateFrame("Slider", nil, sc)
				sc.ScrollBar:CreateTexture(nil, "ARTWORK"):SetTexture("scrollbar-art")
			end
			-- THE RANK BAR, printed across the top left - straight through the
			-- window's own title. It is a frame, not lettering, and what it says is
			-- exactly what a subtitle says: how far along this window's subject you
			-- are.
			local hl = CreateFrame("Frame", prefix .. "HighlightFrame", f)
			hl:SetSize(293, 16)
			hl:SetPoint("TOPLEFT", f, "TOPLEFT", 22, -96)
			hl:CreateTexture(prefix .. "Highlight", "ARTWORK")
				:SetTexture("Interface\\Buttons\\UI-Listbox-Highlight2")

			local rank = CreateFrame("StatusBar", prefix .. "RankFrame", f)
			rank:SetSize(268, 15)
			rank:SetPoint("TOPLEFT", f, "TOPLEFT", 73, -37)

			-- The filters are built further down, ONCE, under the name and the
			-- parentKey the client really uses. This block used to build a second
			-- pair under a second spelling - TradeSkillSubClassDropDown against
			-- TradeSkillFrame.SubClassDropdown - so the window had two of every
			-- filter and a skin could move one while a check read the other.

			local d = CreateFrame("Frame", prefix .. "DetailScrollChildFrame", f)
			local dfs = d:CreateFontString(nil, "ARTWORK")
			dfs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			dfs:SetTextColor(0.1, 0.08, 0.05, 1)
			-- CREATE ALL, CREATE AND CLOSE, at the fixed offsets the client uses:
			-- 422 down from the window's TOPLEFT, in a frame that is not that tall
			-- any more. NAMED, because the client names these - unlike the trainer's,
			-- which is why that window's three are found by shape instead.
			-- ...and only the trade skill window has a Create All. Enchanting makes
			-- one thing at a time, so the craft window's strip is a pair.
			local acts = { { "CreateButton", 224 }, { "CancelButton", 305 } }
			if prefix == "TradeSkill" then
				table.insert(acts, 1, { "CreateAllButton", 138 })
			end
			for _, spec in ipairs(acts) do
				local b = CreateFrame("Button", prefix .. spec[1], f,
					"UIPanelButtonTemplate")
				b:SetSize(80, 22)
				b:SetPoint("CENTER", f, "TOPLEFT", spec[2], -422)
				b:SetText(spec[1])
			end

			-- THE LIST. Eight row buttons reused down the page, a heading among
			-- them wearing the client's plus or minus as its NORMAL texture, and
			-- an All control above them. Two windows, and not one name shared.
			local rowName = (prefix == "TradeSkill") and "TradeSkillSkill" or "Craft"
			for i = 1, 8 do
				local b = CreateFrame("Button", rowName .. i, f)
				b:SetSize(293, 16)
				b:SetID(i)

				-- OFF THE WINDOW, NOT OFF THE LIST, the way the trainer's are: the
				-- scroll frame here is the BAR and nothing else.
				if i == 1 then
					b:SetPoint("TOPLEFT", f, "TOPLEFT", 22, -96)
				else
					b:SetPoint("TOPLEFT", _G[rowName .. (i - 1)], "BOTTOMLEFT", 0, 0)
				end
				local fs = b:CreateFontString(rowName .. i .. "Text", "OVERLAY")
				fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
				fs:SetText("Linen Bandage")
				b.__fs = fs
				function b:GetFontString() return self.__fs end

				-- THE CLIENT ANSWERS GetTexture WITH A FILE ID rather than the
				-- path it was handed, so the mark cannot be read off the art. The
				-- mock has to be as unhelpful about it as the client is.
				local realGet = b.GetNormalTexture
				function b:GetNormalTexture()
					local tex = realGet(self)
					if tex and not tex.__fileID then
						tex.__fileID = true
						local raw = tex.GetTexture
						function tex:GetTexture()
							local v = raw(self)
							if type(v) == "string" then return 137057 end
							return v
						end
					end
					return tex
				end

				-- Odd rows are headings this round, even ones are recipes.
				if i % 2 == 1 then b:SetNormalTexture("Interface\\Buttons\\UI-MinusButton-Up") end
			end

			-- THE LITTLE STONE TAB the All control hangs off, on a frame of its
			-- own that nothing else walks - which is how it survived a window
			-- otherwise entirely ours and sat there behind the word All.
			local tab = CreateFrame("Frame", prefix .. "ExpandButtonFrame", f)
			for _, part in ipairs({ "Left", "Middle", "Right" }) do
				local tex = tab:CreateTexture(prefix .. "ExpandTab" .. part, "BACKGROUND")
				tex:SetTexture("Interface\\QuestFrame\\UI-QuestLogSortTab-Middle")
				_G[prefix .. "ExpandTab" .. part] = tex
			end

			local all = CreateFrame("Button", prefix .. "CollapseAllButton", tab)
			all:SetNormalTexture("Interface\\Buttons\\UI-MinusButton-Up")
			all:SetID(0)

			-- THE FILTERS: the modern dropdown, a stone holder and an arrow and a
			-- label, all regions of the button. Trade skills carry two of these;
			-- Era's crafting carries none, which is why they are asked for by key
			-- rather than counted.
			if prefix == "TradeSkill" then
				for _, key in ipairs({ "SubClassDropdown", "InvSlotDropdown" }) do
					local dd = CreateFrame("Button", prefix .. key, f)
					dd:SetSize(120, 24)
					dd.Background = dd:CreateTexture(nil, "BACKGROUND")
					dd.Background:SetTexture("common-dropdown-classic-textholder")
					dd.Arrow = dd:CreateTexture(nil, "OVERLAY")
					dd.Arrow:SetTexture("common-dropdown-classic-a-buttonDown")
					dd.Text = dd:CreateFontString(nil, "OVERLAY")
					dd.Text:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
					dd.Text:SetText("All Slots")
					function dd:OnButtonStateChanged()
						self.Arrow:SetTexture("common-dropdown-classic-a-buttonDown-pressed")
						self.Arrow:SetSize(24, 24)
					end
					f[key] = dd
				end

				-- THE COUNT SPINNER, and the box between the two. Neither button
				-- carries a word, so a sweep that finds buttons by their label goes
				-- past all three of them.
				for _, way in ipairs({ "Decrement", "Increment" }) do
					local b = CreateFrame("Button", prefix .. way .. "Button", f)
					b:SetSize(23, 22)
					b:SetNormalTexture("Interface\\Buttons\\UI-SpellbookIcon-PrevPage-Up")
				end
				local box = CreateFrame("EditBox", prefix .. "InputBox", f)
				for _, part in ipairs({ "Left", "Middle", "Right" }) do
					local tex = box:CreateTexture(prefix .. "InputBox" .. part, "BACKGROUND")
					tex:SetTexture("Interface\\Common\\Common-Input-Border")
					_G[prefix .. "InputBox" .. part] = tex
				end
			end

			-- THE CLIENT REFILLING THE LIST, which it does on every expand, every
			-- pick and every craft - putting its own marks back and handing rows
			-- from one kind to the other.
			-- THE EIGHT BUTTONS ARE REUSED down the page, so a row that is a
			-- heading now is a recipe after the next scroll or collapse. A mock
			-- where the odd rows are headings for ever cannot see a mark left
			-- behind on a recipe, which is the whole reason ours is hidden.
			local updater = prefix .. "Frame_Update"
			f.__collapsedRound = false
			f.__rowShift = 0
			_G[updater] = function()
				f.__collapsedRound = true
				for i = 1, 8 do
					local b = _G[rowName .. i]
					if (i + f.__rowShift) % 2 == 1 then
						b:SetNormalTexture("Interface\\Buttons\\UI-PlusButton-Up")
					else
						b:SetNormalTexture(0)
					end
				end
			end

			--- The list scrolled, which hands every row to the other kind.
			if prefix == "TradeSkill" then
				function _G.__shiftSkillRows()
					f.__rowShift = 1 - f.__rowShift
					_G[updater]()
				end
			end
		end

		--- What the client says a row is, which is the only reliable answer.
		function _G.GetTradeSkillInfo(id)
			if type(id) ~= "number" or id < 1 or id > 8 then return nil end
			if (id + _G.TradeSkillFrame.__rowShift) % 2 == 1 then
				return "Consumable", "header", 0,
					not _G.TradeSkillFrame.__collapsedRound
			end
			return "Linen Bandage", "trivial", 1, nil
		end

		function _G.GetCraftInfo(id)
			if type(id) ~= "number" or id < 1 or id > 8 then return nil end
			if id % 2 == 1 then
				return "Enchant Bracer", nil, "header", 0,
					not _G.CraftFrame.__collapsedRound
			end
			return "Runed Copper Rod", nil, "trivial", 1, nil
		end
	end

	-- THE MAIN MENU IS A VerticalLayoutFrame, and that is the whole of why its
	-- buttons came out as one solid column of glass with lines of text in it.
	--
	-- MainMenuFrameTemplate sets `spacing` to ZERO and gets away with it,
	-- because Blizzard's button art carries a transparent margin - the rows
	-- look separated while the frames touch. Ours is a drawn rectangle with no
	-- margin, so at zero they meet. A mock with no layout at all cannot see
	-- that, and did not.
	--
	-- The frame reads spacing and topPadding off ITSELF on every layout, and
	-- Reset clears neither, which is what makes setting them once enough.
	do
		local gm = _G.GameMenuFrame
		gm.spacing = 0
		gm.topPadding = 32
		gm.__menuButtons = {}
		gm.__layoutRuns = 0

		for i, label in ipairs({ "Options", "AddOns", "Macros", "Logout" }) do
			local b = CreateFrame("Button", nil, gm)
			b:SetSize(180, 26)
			b.layoutIndex = i
			b:SetText(label)
			gm.__menuButtons[i] = b
		end

		function gm:MarkDirty() self.__dirty = true end
		-- ITS BUTTONS COME OUT OF A POOL and InitButtons is what fills it -
		-- called on OnShow and again on the client's own events, after
		-- anything hooked to OnShow has already run.
		function gm:InitButtons() self:Layout() end
		function gm:Layout()
			self.__dirty = nil
			self.__layoutRuns = self.__layoutRuns + 1
			local y = -(self.topPadding or 0)
			for _, b in ipairs(self.__menuButtons) do
				b:ClearAllPoints()
				b:SetPoint("TOP", self, "TOP", 0, y)
				b.__layoutY = y
				y = y - (b:GetHeight() or 26) - (self.spacing or 0)
			end
		end
		gm:Layout()
	end


	-- THE FLIGHT MAP IS A REGION OF THE FRAME, which makes this window the one
	-- where a full sweep takes the thing the player came to look at. It went
	-- black in game with the suite green, because the mock had no map to lose.
	do
		local tx = _G.TaxiFrame

		-- Its close button is TaxiCloseButton, not TaxiFrameCloseButton.
		-- buildPanel's generous spelling is why the red X survived.
		_G.TaxiFrameCloseButton = nil
		local close = CreateFrame("Button", "TaxiCloseButton", tx)
		close:SetNormalTexture("close-up")

		-- THE MAP IS A TEXTURE ON THE FRAME, anchored 75 down from the middle of
		-- the top edge - so it starts inside our band. And the flight points are
		-- anchored to the MAP's bottom left corner by the client, which is what
		-- makes moving the map safe: every node comes with it.
		local map = tx:CreateTexture("TaxiMap", "OVERLAY")
		map:SetTexture("Interface\\TaxiFrame\\TAXIMAP_EASTERNKINGDOMS")
		map:SetSize(316, 352)
		map:SetPoint("TOP", tx, "TOP", -13, -75)

		local route = CreateFrame("Frame", "TaxiRouteMap", tx)
		route:SetSize(316, 352)
		route:SetPoint("TOP", tx, "TOP", -13, -75)

		-- One flight point, hung off the map the way the client hangs them.
		local node = CreateFrame("Button", "TaxiButton1", tx)
		node:SetSize(10, 10)
		node:SetPoint("CENTER", map, "BOTTOMLEFT", 120, 200)

		local portrait = tx:CreateTexture("TaxiPortrait", "BACKGROUND")
		portrait:SetTexture("flight-master-face")

		local who = tx:CreateFontString("TaxiMerchant", "ARTWORK")
		who:SetFont("Fonts\\FRIZQT__.TTF", 14, "")
		who:SetText("Thor Stormcrown")
		who:SetTextColor(0.10, 0.10, 0.10)
	end

	-- The main menu is a stack of buttons and nothing else, and the client's set
	-- of them changes with the build - which is why the skin asks the frame what
	-- it has rather than naming them.
	do
		local gm = _G.GameMenuFrame

		-- ITS TITLE LIVES SOMEWHERE ELSE. Anything built on the shared dialog
		-- template keeps the title inside a Header child, with the ornate stone
		-- plate as that header's BG - not in a global $parentTitleText the way
		-- the older frames do. A mock that gives every window the older shape
		-- lets a skin claim a title it never found and leave the bar standing.
		_G.GameMenuFrameTitleText = nil
		gm.Header = CreateFrame("Frame", nil, gm)
		gm.Header.BG = gm.Header:CreateTexture(nil, "BACKGROUND")
		gm.Header.BG:SetTexture("Interface\\DialogFrame\\UI-DialogBox-Header")
		gm.Header.Text = gm.Header:CreateFontString(nil, "ARTWORK")
		gm.Header.Text:SetFont("Fonts\\FRIZQT__.TTF", 14, "")
		gm.Header.Text:SetText("Main Menu")

		for _, n in ipairs({ "Options", "AddOns", "Macros", "Logout", "Quit", "Continue" }) do
			local b = CreateFrame("Button", "GameMenuButton" .. n, gm)
			b:SetNormalTexture("menu-button-up")
			b:SetPushedTexture("menu-button-down")
			local fs = b:CreateFontString(nil, "OVERLAY")
			fs:SetText(n)
			b.__fs = fs
			function b:GetFontString() return self.__fs end
		end
	end

	-- The character sheet's insides.
	--
	-- Without these every loop in the interior skin iterates an empty list and
	-- the suite reports success over code that has never run once. The shapes
	-- are Blizzard's: a slot carries its item icon as a REGION of the button,
	-- which is why stripping a slot would blank the item and leave the border
	-- correctly gone.
	do
		local cf = _G.CharacterFrame

		_G.NUM_FACTIONS_DISPLAYED = 3
		-- Twelve, as the client ships: SkillFrame.xml builds twelve rows and
		-- reuses them as you scroll, which is why the list ends halfway down a
		-- window of ours with empty glass underneath it.
		_G.SKILLS_TO_DISPLAY = 12
		_G.SKILLFRAME_SKILL_HEIGHT = 15
		_G.ITEM_QUALITY_COLORS = {
			[0] = { r = 0.62, g = 0.62, b = 0.62 },
			[1] = { r = 1.00, g = 1.00, b = 1.00 },
			[2] = { r = 0.12, g = 1.00, b = 0.00 },
			[3] = { r = 0.00, g = 0.44, b = 0.87 },
			[4] = { r = 0.64, g = 0.21, b = 0.93 },
		}

		-- One epic, one uncommon, two empty. A single quality would exercise one
		-- branch of the rim and look like coverage.
		-- ONE PANE UP AT A TIME. These are the character sheet's five tabs and
		-- the window shows exactly one of them; a mock with all five up is a
		-- window that is on every tab at once, and anything that asks WHICH TAB
		-- AM I ON gets an answer the client would never give.
		for _, n in ipairs({ "PaperDollFrame", "PetPaperDollFrame",
			"ReputationFrame", "SkillFrame", "HonorFrame",
			"CharacterAttributesFrame", "PetAttributesFrame" }) do
			local pane = CreateFrame("Frame", n, cf)
			pane:CreateTexture(nil, "BORDER"):SetTexture("pane-stone")
			-- SET ALL POINTS TO THE WINDOW, which is how the client anchors
			-- every one of these: the pane is the whole frame and the slots
			-- and models inside it are placed from its top left corner. So
			-- moving the PANE is what moves a tab's entire contents, and a
			-- mock whose panes have no anchors at all cannot show that.
			pane:SetAllPoints(cf)
			if n ~= "PaperDollFrame" and n ~= "CharacterAttributesFrame" then
				pane:Hide()
			end
		end

		local QUALITY = { CharacterHeadSlot = 4, CharacterChestSlot = 2,
			CharacterMainHandSlot = 4 }
		local qualityByID = {}
		local lastSlot

		-- INSIDE THE PAPER DOLL PANE, and setAllPoints to it, exactly as the
		-- client nests it. Hung off the WINDOW instead, the slots do not travel
		-- when the pane moves - so a mock built that way says a skin which moves
		-- the pane moved the gear, and on screen the gear stayed where it was.
		local items = CreateFrame("Frame", "PaperDollItemsFrame",
			_G.PaperDollFrame)
		items:SetAllPoints(_G.PaperDollFrame)
		for id, slotName in ipairs({ "CharacterHeadSlot", "CharacterNeckSlot",
			"CharacterChestSlot", "CharacterMainHandSlot" }) do
			local b = CreateFrame("Button", slotName, items)
			b:SetSize(37, 37)
			-- 21 in and 74 down, then four apart, which is the client's own
			-- column. The 74 is the strip the stone title plate used to fill.
			-- ...AND THE WEAPON ROW HANGS OFF THE BOTTOM. The client anchors it 127
			-- UP from the pane's bottom edge rather than down from its top, which is
			-- what makes a pane that fills the window two things at once: a page that
			-- reads downward and a row that sits along the foot. A mock where every
			-- slot hangs off the top cannot show the foot row travelling twice.
			if id == 1 then
				b:SetPoint("TOPLEFT", items, "TOPLEFT", 21, -74)
			elseif slotName == "CharacterMainHandSlot" then
				b:SetPoint("TOPLEFT", items, "BOTTOMLEFT", 122, 127)
			else
				b:SetPoint("TOPLEFT", _G[lastSlot], "BOTTOMLEFT", 0, -4)
			end
			lastSlot = slotName
			b.__id = id
			function b:GetID() return self.__id end

			local icon = b:CreateTexture(nil, "BACKGROUND")
			icon:SetTexture("item-icon-" .. slotName)
			_G[slotName .. "IconTexture"] = icon

			b.Count = b:CreateFontString(nil, "OVERLAY")
			_G[slotName .. "Count"] = b.Count

			b:SetNormalTexture("slot-border")
			qualityByID[id] = QUALITY[slotName]
		end

		-- ASKED BY UNIT, because the same slots and the same rim serve the
		-- inspect window. A mock that answers out of one table whatever unit it
		-- is handed agrees that your own gear may colour somebody else's, which
		-- is a green suite over a window showing the wrong qualities.
		local qualityByUnit = { player = qualityByID }
		_G.__slotQualityByUnit = qualityByUnit

		function _G.GetInventoryItemQuality(unit, slotID)
			local byID = qualityByUnit[unit]
			return byID and byID[slotID]
		end

		-- Exists so the skin has something to hook. The client calls it whenever
		-- a slot's item changes, which is when our rim has to answer.
		function _G.PaperDollItemSlotButton_Update(btn) end

		-- Equip and unequip, so the hook can be shown to do something. A rim
		-- that is only ever set once at dress time passes every static check.
		function _G.__setSlotQuality(id, q) qualityByID[id] = q end

		-- The client's own labels, because their LENGTH is the thing under test:
		-- four tabs each measured generously to a word like "Reputation" is what
		-- ran the row out past the right edge. "Tab1".."Tab4" always fits and
		-- would have proved nothing.
		-- THE PET TAB IS HIDDEN on a character without a pet, and it sits
		-- SECOND - between Character and Reputation. A layout that walks every
		-- tab the client defined gives it a slot of its own, and the row ends up
		-- with a hole in it exactly one tab wide. Four visible tabs in a row
		-- cannot show that; this can.
		for i, label in ipairs({ "Character", "Pet", "Reputation", "Skills", "Honor" }) do
			local t = CreateFrame("Button", "CharacterFrameTab" .. i, cf)
			t:SetNormalTexture("tab-up")
			t:SetDisabledTexture("tab-disabled")

			-- Anchored by its CENTRE, not its corner. Blizzard's anchor shape is
			-- not ours to assume, and a skin that keeps the client's point but
			-- overwrites its x reads "18" as "put the middle here" and hangs
			-- half the tab off the side of the screen. A mock that only ever
			-- uses TOPLEFT cannot show that.
			t:SetPoint("CENTER", cf, "BOTTOMLEFT", 60 + (i - 1) * 60, 90)

			local fs = t:CreateFontString(nil, "OVERLAY")
			fs:SetText(label)
			_G["CharacterFrameTab" .. i .. "Text"] = fs

			-- A PLAIN STRING UNDER THE SAME NAME. Some of Blizzard's templates
			-- keep the label as a value beside the region that draws it - a
			-- FriendsFrame tab has `text = "FRIENDS"` next to its Text
			-- fontstring - and anything looking up "Text" by field name finds
			-- whichever it happens to check first. Handing that back is a
			-- caller setting a field on a string, which is the social window
			-- refusing to open.
			t.text = label

			-- Reachable as the button's own font string, which is how
			-- PanelTemplates_TabResize finds it. Without this the client's own
			-- resize returns early and the mock quietly agrees that a width set
			-- once at dress time is a width that lasts.
			t.__fs = fs
			function t:GetFontString() return self.__fs end

			if label == "Pet" then t:Hide() end
		end

		-- TWO DOLLS, and the pet's is on its own tab with its own model box
		-- and its own pair of turn buttons. A mock with only the player's
		-- agrees that dressing one dresses both, which is exactly what it
		-- did not: the pet kept Blizzard's stone discs beside a sheet that
		-- was otherwise ours.
		for _, doll in ipairs({ "Character", "Pet" }) do
			local model = CreateFrame("Frame", doll .. "ModelFrame", cf)
			model:CreateTexture(nil, "BORDER"):SetTexture("model-stone")
			for _, key in ipairs({ "RotateLeftButton", "RotateRightButton" }) do
				CreateFrame("Button", doll .. "ModelFrame" .. key, model)
					:SetNormalTexture("rotate-art")
			end
		end

		-- AND EACH TAB'S CONTENT STARTS AT ITS OWN HEIGHT. This is the thing one
		-- number per window cannot express: the reputation columns are headed 57
		-- below the frame and the skill list's ALL tab sits at 49, against the
		-- paper doll's 74. A mock whose panes are empty agrees with any answer.
		local faction = _G.ReputationFrame:CreateFontString(
			"ReputationFrameFactionLabel", "OVERLAY")
		faction:SetText("Faction")
		faction:SetPoint("TOPLEFT", _G.ReputationFrame, "TOPLEFT", 70, -57)

		-- AND THE FIRST THING IN A PANE IS NOT THE TOPMOST THING IN IT. The skill
		-- list's rows are built before its ALL tab, and they sit well below it -
		-- so a walk that reads only a frame's first child gets 200 here instead
		-- of 49 and still looks right on a pane whose content happens to be
		-- declared in order.
		local firstRow = CreateFrame("Frame", "SkillRankFrame1", _G.SkillFrame)
		firstRow:SetSize(200, 16)
		firstRow:SetPoint("TOPLEFT", _G.SkillFrame, "TOPLEFT", 38, -200)

		local allTab = CreateFrame("Button", "SkillFrameCollapseAllButton",
			_G.SkillFrame)
		allTab:SetSize(54, 32)
		allTab:SetPoint("TOPLEFT", _G.SkillFrame, "TOPLEFT", 70, -49)

		-- THE RANK BADGE IS A REGION OF THE HONOUR PANE, exactly as the
		-- parchment behind it is - so a sweep that takes the pane's art takes
		-- the picture of the rank with it and leaves the words beside nothing.
		_G.HonorFramePvPIcon = _G.HonorFrame:CreateTexture("HonorFramePvPIcon",
			"OVERLAY")
		_G.HonorFramePvPIcon:SetTexture("Interface\\PvPRankBadges\\PvPRank09")

		-- The stat rows, in the client's own lettering at the client's own
		-- sizes. A pane with no strings in it lets a skin claim to have re-roled
		-- an interior it never touched - and the SIZE matters as much as the
		-- family: these sit in rows the client measured, so handing them a size
		-- of ours reflows somebody else's window.
		do
			local attrs = _G.CharacterAttributesFrame
			local label = attrs:CreateFontString("CharacterStatFrame1Label", "OVERLAY")
			label:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
			label:SetText("Strength:")

			-- One level down, because the client nests these.
			local row = CreateFrame("Frame", "CharacterStatFrame1", attrs)
			local value = row:CreateFontString("CharacterStatFrame1StatText", "OVERLAY")
			value:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			value:SetText("21")
		end

		for _, prefix in ipairs({ "MagicResFrame", "PetMagicResFrame" }) do
			for i = 1, 5 do
				local rf = CreateFrame("Frame", prefix .. i, cf)
				-- THE SCHOOL'S OWN ICON: the frame's only texture, and unnamed - so a
				-- sweep that takes every texture takes the one thing saying which of
				-- the five this number is. Arcane, fire, nature, frost, shadow, and
				-- five bare numbers down the side of the sheet saying none of it.
				rf.__icon = rf:CreateTexture(nil, "BACKGROUND")
				rf.__icon:SetTexture(
					"Interface\\PaperDollInfoFrame\\UI-Character-ResistanceIcons")
			end
		end

		for i = 1, _G.NUM_FACTIONS_DISPLAYED do
			local bar = CreateFrame("StatusBar", "ReputationBar" .. i, cf)
			CreateFrame("CheckButton", "ReputationBar" .. i .. "AtWarCheck", bar)
				:SetNormalTexture("checkbox-up")
		end

		for i = 1, _G.SKILLS_TO_DISPLAY do
			local bar = CreateFrame("StatusBar", "SkillRankFrame" .. i, cf)
			_G["SkillRankFrame" .. i .. "Border"] = bar:CreateTexture(nil, "OVERLAY")
			_G["SkillRankFrame" .. i .. "Border"]:SetTexture("skill-border")
			_G["SkillRankFrame" .. i .. "Background"] = bar:CreateTexture(nil, "BACKGROUND")
			_G["SkillRankFrame" .. i .. "Background"]:SetTexture("skill-backing")

			-- The collapse header is a BUTTON carrying a string, not a string.
			-- It answers SetText like a FontString and has no SetFont at all,
			-- which is exactly how a "label" reached the font setter and took
			-- the whole module down with it.
			local label = CreateFrame("Button", "SkillTypeLabel" .. i, cf)
			local fs = label:CreateFontString(nil, "OVERLAY")
			fs:SetText("Class Skills")
			label.__fs = fs
			function label:GetFontString() return self.__fs end
			function label:SetText(t) self.__fs:SetText(t) end

			-- The disclosure mark is the button's NORMAL TEXTURE, sitting at
			-- the far left of a 285px row with the group's name beside it. A
			-- glyph centred on the button lands in the middle of the words.
			label:SetNormalTexture("Interface\\Buttons\\UI-PlusButton-Up")
			label.isExpanded = (i == 1) or nil
		end

		for i = 1, _G.NUM_FACTIONS_DISPLAYED do
			CreateFrame("Button", "ReputationHeader" .. i, cf)
				:SetNormalTexture("Interface\\Buttons\\UI-PlusButton-Up")
		end

		-- The client repaints every mark whenever the list changes - which is
		-- every expand, every collapse and every scroll. A skin that clears
		-- them once at dress time is a skin you see until the first click.
		function _G.SkillFrame_UpdateSkills()
			for i = 1, (_G.SKILLS_TO_DISPLAY or 0) do
				local l = _G["SkillTypeLabel" .. i]
				if l and l.SetNormalTexture then
					l:SetNormalTexture(l.isExpanded
						and "Interface\\Buttons\\UI-MinusButton-Up"
						or "Interface\\Buttons\\UI-PlusButton-Up")
				end
			end
		end

		for _, n in ipairs({ "ReputationListScrollFrame", "SkillListScrollFrame",
			"SkillDetailScrollFrame" }) do
			local sf = CreateFrame("Frame", n, cf)
			sf:CreateTexture(nil, "BORDER"):SetTexture("scroll-stone")

			local sb = CreateFrame("Slider", n .. "ScrollBar", sf)
			CreateFrame("Button", n .. "ScrollBarScrollUpButton", sb)
				:SetNormalTexture("arrow-up")
			CreateFrame("Button", n .. "ScrollBarScrollDownButton", sb)
				:SetNormalTexture("arrow-down")
		end

		for _, n in ipairs({ "ReputationDetailAtWarCheckbox",
			"ReputationDetailInactiveCheckbox",
			"ReputationDetailMainScreenCheckbox" }) do
			CreateFrame("CheckButton", n, cf):SetNormalTexture("checkbox-up")
		end

		for _, n in ipairs({ "SkillDetailStatusBar", "HonorFrameProgressBar",
			"PetPaperDollFrameExpBar" }) do
			CreateFrame("StatusBar", n, cf)
		end

		function _G.PanelTemplates_UpdateTabs(frame) end

		-- SELECTING A TAB MOVES ITS TEXT. The client nudges the label up into
		-- the raised part of its own stone art - right for that art, wrong for
		-- a flat pill - and it does it on every selection, not once at setup.
		function _G.PanelTemplates_SelectTab(tab)
			local fs = tab:GetFontString()
			if fs then
				fs:ClearAllPoints()
				fs:SetPoint("CENTER", tab, "CENTER", 0, 3)
			end
			tab:Disable()
		end

		-- "All" collapses and expands the whole tree, and the client hangs it
		-- off a little stone tab out to the RIGHT of the groups it governs.
		do
			local all = CreateFrame("Button", "SkillFrameCollapseAllButton", cf)
			local fs = all:CreateFontString(nil, "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetText("All")
			all.__fs = fs
			function all:GetFontString() return self.__fs end
			all:SetPoint("BOTTOMLEFT", cf, "TOPLEFT", 120, -40)

			for _, part in ipairs({ "Left", "Middle", "Right" }) do
				local t = cf:CreateTexture(nil, "ARTWORK")
				t:SetTexture("expand-tab-" .. part)
				_G["SkillFrameExpandTab" .. part] = t
			end
		end

		-- SPARE CLOSE BUTTONS, one per tab that has one: the skills list keeps
		-- one in the middle of itself and the pet tab one under the doll. Both
		-- do exactly what the X in the corner already does.
		for _, n in ipairs({ "SkillFrameCancelButton", "PetPaperDollCloseButton" }) do
			local spare = CreateFrame("Button", n, cf)
			spare:SetNormalTexture("cancel-up")
			spare:Show()
		end

		local who = cf:CreateFontString(nil, "OVERLAY")
		who:SetText("Palabras")
		_G.CharacterNameText = who

		local rank = cf:CreateFontString(nil, "OVERLAY")
		rank:SetText("Level 18 Undead Mage")
		_G.CharacterLevelText = rank

		-- AND THE PET'S OWN PAIR, which is what the window's header says on
		-- the pet tab. They are children of that PANE and not of the window,
		-- so they are only up when it is.
		local pet = _G.PetPaperDollFrame
		local petName = pet:CreateFontString(nil, "OVERLAY")
		petName:SetText("Gakrin")
		_G.PetNameText = petName
		local petRank = pet:CreateFontString(nil, "OVERLAY")
		petRank:SetText("Level 18 Imp")
		_G.PetLevelText = petRank
	end

	-- SOMEBODY ELSE'S CHARACTER SHEET, which shares the shape and not one of
	-- the names. Everything here is spelled Inspect-something, its slots keep
	-- their stone plate in a BACKGROUND region rather than in the normal
	-- texture, and every item in it belongs to a different unit.
	do
		local inf = buildPanel("InspectFrame")
		inf.unit = "target"

		-- The portrait is a region of the frame itself, so the shell sweep
		-- takes it with the rest of the stone.
		_G.InspectFramePortrait = inf:CreateTexture("InspectFramePortrait",
			"BACKGROUND")
		_G.InspectFramePortrait:SetTexture("portrait-target")

		-- THE NAME IS NOT THE TITLE BAND. This window never fills its own
		-- TitleText in: the client hangs the name off a little frame of its
		-- own, measured 109 wide for twelve-point type. A skin that only
		-- re-roles $parentTitleText re-roles an empty string and leaves the
		-- one word on screen in Blizzard's lettering.
		_G.InspectFrameTitleText:SetText("")
		local nameFrame = CreateFrame("Frame", "InspectNameFrame", inf)
		local who = nameFrame:CreateFontString("InspectNameText", "OVERLAY")
		who:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
		who:SetText("Dudeo-Firemaw")
		who:SetWidth(109)
		_G.InspectNameText = who

		-- The panes. The honour one carries the rank badge among its
		-- parchment, and the doll one carries the faction crest it shows in
		-- place of a model you are too far off to draw - both pictures, both
		-- regions of a frame whose art is coming off.
		-- THE DOLL PANE FILLS THE WINDOW, the honour one is hung off its top left
		-- corner 62 down, and the slots inside the doll start at 74 - the strip
		-- the stone title plate used to need, which is not our band.
		for _, spec in ipairs({ { "InspectPaperDollFrame", nil },
			{ "InspectHonorFrame", 9, -62 },
			{ "InspectPaperDollItemsFrame", nil } }) do
			-- PARENTED, not just anchored. The slots are nested two deep inside the
			-- doll pane, and a mock that hung the items frame off the WINDOW put
			-- every slot outside the pane being measured - so the pane measured as
			-- empty, never moved, and looked laid out.
			local host = (spec[1] == "InspectPaperDollItemsFrame")
				and _G.InspectPaperDollFrame or inf
			local pane = CreateFrame("Frame", spec[1], host)
			if spec[2] then
				pane:SetSize(366, 400)
				pane:SetPoint("TOPLEFT", inf, "TOPLEFT", spec[2], spec[3])
			elseif spec[1] == "InspectPaperDollItemsFrame" then
				-- INSIDE THE DOLL PANE, not beside it. The slots are nested two
				-- deep, and a mock that hung them off the WINDOW put them outside
				-- the pane being measured - so the pane measured as empty and
				-- never moved.
				pane:SetAllPoints(_G.InspectPaperDollFrame)
			else
				pane:SetAllPoints(inf)
			end
			pane:CreateTexture(nil, "ARTWORK"):SetTexture("pane-stone")
		end

		_G.InspectHonorFramePvPIcon = _G.InspectHonorFrame:CreateTexture(
			"InspectHonorFramePvPIcon", "OVERLAY")
		_G.InspectHonorFramePvPIcon:SetTexture("Interface\\PvPRankBadges\\PvPRank11")
		_G.InspectFaction = _G.InspectPaperDollFrame:CreateTexture(
			"InspectFaction", "ARTWORK")
		_G.InspectFaction:SetTexture("Interface\\Timer\\Horde-Logo")

		-- The class line under the name, and the two strings the client
		-- leaves hidden until it has something to put in them.
		for _, n in ipairs({ "InspectLevelText", "InspectTitleText",
			"InspectGuildText" }) do
			local fs = _G.InspectPaperDollFrame:CreateFontString(n, "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
			fs:SetText("Level 60 Orc Warrior")
			fs:SetTextColor(1, 0.82, 0, 1)
			_G[n] = fs
		end

		-- THE MODEL BOX AND THE TWO BUTTONS THAT TURN IT. Each of those is a
		-- PICTURE OF A BUTTON - the curved arrow and the disc it stands on are
		-- one texture - so clearing the plate takes the arrow with it and
		-- leaves a live control with nothing drawn on it at all.
		local model = CreateFrame("Frame", "InspectModelFrame", inf)
		model:CreateTexture(nil, "OVERLAY"):SetTexture("Char-Inner-Left")
		for _, key in ipairs({ "RotateLeftButton", "RotateRightButton" }) do
			local b = CreateFrame("Button", "InspectModelFrame" .. key, model)
			b:SetNormalTexture("Interface\\Buttons\\UI-RotationLeft-Button-Up")
		end

		-- THE SLOTS. Nineteen in the client; four here, one of each shape the
		-- rim has to answer for. Their plate is a BACKGROUND region and the
		-- item's picture is in the same layer, so a sweep that takes one takes
		-- the other and a clear that takes neither leaves them all in stone.
		--
		-- DIFFERENT QUALITIES IN THE SAME SLOT IDS as the player's, on purpose.
		-- A mock where both units happen to be wearing the same thing agrees
		-- that a rim asking for "player" is a rim reading the unit you are
		-- looking at, and the whole point of the unit is that it is not you.
		-- Head is rare here and epic on the player; the weapon is empty here
		-- and epic on the player.
		local QUALITY = { InspectHeadSlot = 3, InspectChestSlot = 4 }
		local inspectQuality = {}
		_G.__slotQualityByUnit.target = inspectQuality

		for id, slotName in ipairs({ "InspectHeadSlot", "InspectNeckSlot",
			"InspectChestSlot", "InspectMainHandSlot" }) do
			local b = CreateFrame("Button", slotName, _G.InspectPaperDollItemsFrame)
			b:SetWidth(37) b:SetHeight(37)
			-- 65 DOWN, which is the strip the stone title plate used to need -
			-- neither our band nor our padding. Unanchored slots measure as
			-- nothing and a pane that never moved looked laid out.
			if id == 1 then
				b:SetPoint("TOPLEFT", _G.InspectPaperDollItemsFrame, "TOPLEFT", 13, -65)
			else
				b:SetPoint("TOPLEFT", _G[({ "InspectHeadSlot", "InspectNeckSlot",
					"InspectChestSlot" })[id - 1]], "BOTTOMLEFT", 0, -4)
			end
			b.__id = id
			function b:GetID() return self.__id end

			-- The stone plate the slot sits in, which is NOT the normal
			-- texture: it is $parentFrame, a background region of the button.
			local plate = b:CreateTexture(slotName .. "Frame", "BACKGROUND")
			plate:SetTexture("Char-LeftSlot")
			_G[slotName .. "Frame"] = plate

			local icon = b:CreateTexture(slotName .. "IconTexture", "BORDER")
			icon:SetTexture("item-icon-" .. slotName)
			_G[slotName .. "IconTexture"] = icon

			b.Count = b:CreateFontString(nil, "OVERLAY")
			b:SetNormalTexture("Interface\\Buttons\\UI-Quickslot2")
			inspectQuality[id] = QUALITY[slotName]
		end

		-- The client calls this whenever it is told what is in a slot, which
		-- on this window is not only an item changing: the whole set arrives
		-- late, on INSPECT_READY, after any skin has already been past.
		function _G.InspectPaperDollItemSlotButton_Update(btn) end
		function _G.__setInspectQuality(id, q) inspectQuality[id] = q end

		CreateFrame("StatusBar", "InspectHonorFrameProgressBar", _G.InspectHonorFrame)

		-- Two tabs, anchored by their CENTRE below the bottom edge, which is
		-- where this template hangs them - outside the window's own art.
		for i, label in ipairs({ "Character", "Honor" }) do
			local t = CreateFrame("Button", "InspectFrameTab" .. i, inf)
			t:SetNormalTexture("tab-up")
			t:SetDisabledTexture("tab-disabled")
			t:SetPoint("CENTER", inf, "BOTTOMLEFT", 60 + (i - 1) * 100, -12)
			local fs = t:CreateFontString(nil, "OVERLAY")
			fs:SetText(label)
			_G["InspectFrameTab" .. i .. "Text"] = fs
			t.__fs = fs
			function t:GetFontString() return self.__fs end
		end
	end
	-- The spellbook's insides.
	--
	-- IT SPELLS NOTHING THE WAY THE OTHERS DO. Its title is SpellBookTitleText
	-- and not $parentTitleText, its close button is SpellBookCloseButton and not
	-- $parentCloseButton, its tabs are SpellBookFrameTabButton1..3 and not
	-- $parentTab1..3 - so a skin that only knows the usual names finds a title
	-- it never re-roled, a close button it never marked and a tab strip it never
	-- laid out, and reports success on all three.
	--
	-- And two of its parts keep their PICTURE in a region: a spell button holds
	-- its icon beside the ring, a school tab holds its icon AS the normal
	-- texture. Either sweep that works elsewhere blanks the thing the player is
	-- looking for.
	do
		local sb = _G.SpellBookFrame
		sb:SetSize(384, 512)

		-- buildPanel gave every window the usual shape. Take back the two this
		-- one does not have, or the skin passes by finding them.
		_G.SpellBookFrameTitleText = nil
		_G.SpellBookFrameCloseButton = nil

		local title = sb:CreateFontString("SpellBookTitleText", "ARTWORK")
		title:SetFont("Fonts\\FRIZQT__.TTF", 14, "")
		title:SetText("Spellbook")
		-- Placed for the art, not for the frame: six pixels right of centre,
		-- because the page it was printed on is not centred in the frame either.
		title:SetPoint("CENTER", sb, "CENTER", 6, 230)

		local close = CreateFrame("Button", "SpellBookCloseButton", sb)
		close:SetNormalTexture("close-up")
		-- Well inside the frame, in the middle of a stone rim that is about to
		-- stop existing.
		close:SetPoint("CENTER", sb, "TOPRIGHT", -44, -25)

		-- Three tabs, and the client HIDES ALL THREE and then shows the ones
		-- that apply from its own update - so the first dress sees an empty row.
		-- A skin that gives up on an empty row without asking to be told when a
		-- tab appears never lays the strip out at all.
		for i, label in ipairs({ "Spellbook", "Pet", "Companions" }) do
			local t = CreateFrame("Button", "SpellBookFrameTabButton" .. i, sb)
			t:SetSize(128, 64)
			t:SetNormalTexture("Interface\\SpellBook\\UI-SpellBook-Tab-Unselected")
			t:SetHighlightTexture("tab-highlight")

			-- THE CLICKS ARE KEPT OFF THE TRANSPARENT MARGIN. 13 down from the
			-- top and 15 up from the bottom of a 64px tab. Re-size that tab to 26
			-- and the two insets meet in the middle: it draws, it highlights, and
			-- it cannot be clicked.
			t:SetHitRectInsets(15, 14, 13, 15)

			local fs = t:CreateFontString(nil, "OVERLAY")
			fs:SetText(label)
			fs:SetPoint("CENTER", t, "CENTER", 0, 3)
			t.Text = fs
			t.__fs = fs
			function t:GetFontString() return self.__fs end

			-- ENABLING A TAB MOVES ITS LABEL. The template does it from OnEnable
			-- and OnDisable - up into the raised part of its stone art, which is
			-- right for that art and wrong for a flat pill - and the client
			-- enables and disables these from its own update, with no click
			-- involved. A mock whose Enable only sets a flag cannot show that.
			local baseEnable, baseDisable = t.Enable, t.Disable
			function t:Enable()
				baseEnable(self)
				self.__fs:ClearAllPoints()
				self.__fs:SetPoint("CENTER", self, "CENTER", 0, 3)
			end
			function t:Disable()
				baseDisable(self)
				self.__fs:ClearAllPoints()
				self.__fs:SetPoint("CENTER", self, "CENTER", 0, 5)
			end

			t:Hide()
		end

		-- Twelve spell buttons in two columns. The icon is a REGION and the ring
		-- is the normal texture, with the parchment disc a third region behind
		-- both - so Strip takes the icon, ClearButton leaves the disc, and only
		-- knowing which is which gets it right.
		local icons = CreateFrame("Frame", "SpellBookSpellIconsFrame", sb)
		-- TOP LEFT TO BOTTOM RIGHT OF THE WINDOW, as the client anchors it -
		-- this frame IS the page, and the twelve buttons are placed from its
		-- corner. So moving it is what moves the spells, and a mock whose page
		-- has no anchors cannot show that it moved.
		icons:SetAllPoints(sb)
		for i = 1, 12 do
			local b = CreateFrame("CheckButton", "SpellButton" .. i, icons)
			b:SetSize(37, 37)
			-- 34 IN AND 85 DOWN for the first, which is where the client starts
			-- the page. Buttons with no anchors at all cannot say where a page
			-- begins, and a skin measuring that gets no answer.
			if i == 1 then
				b:SetPoint("TOPLEFT", icons, "TOPLEFT", 34, -85)
			else
				b:SetPoint("TOPLEFT", _G["SpellButton" .. (i - 1)],
					"BOTTOMLEFT", 0, -6)
			end

			b.EmptySlot = b:CreateTexture(nil, "BACKGROUND")
			b.EmptySlot:SetTexture("Interface\\Spellbook\\UI-Spellbook-SpellBackground")

			local icon = b:CreateTexture(nil, "BORDER")
			icon:SetTexture("spell-icon-" .. i)
			_G["SpellButton" .. i .. "IconTexture"] = icon

			-- BESIDE THE ICON, IN A BOX THE CLIENT SIZED FOR ITS OWN LETTERING. Ours
			-- is wider, so the box is what the page has to be measured by - and a
			-- name with no anchors at all measures as nothing.
			b.SpellName = b:CreateFontString("SpellButton" .. i .. "SpellName", "BORDER")
			b.SpellName:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			b.SpellName:SetSize(120, 12)
			b.SpellName:SetPoint("LEFT", b, "RIGHT", 4, 6)
			b.SpellName:SetText("Frostbolt")

			b.SpellSubName = b:CreateFontString("SpellButton" .. i .. "SubSpellName", "BORDER")
			b.SpellSubName:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
			b.SpellSubName:SetText("Rank 3")

			b:SetNormalTexture("Interface\\Buttons\\UI-Quickslot2")
			b:SetHighlightTexture("Interface\\Buttons\\ButtonHilight-Square")

			-- Every refresh sets the name's colour and puts the client's own
			-- white highlight square back. Our type survives that; our colours
			-- and our cell do not, which is why there is something to hook.
			b.isPassive = (i == 5) or nil
			function b:UpdateButton()
				self.SpellName:SetTextColor(1, 0.82, 0)
				self:SetHighlightTexture("Interface\\Buttons\\ButtonHilight-Square")
			end
		end

		-- The school tabs down the right. Eight defined, the ones past the
		-- player's spell tabs hidden, and the icon set through SetNormalTexture
		-- on every refresh - so the icon is the one texture that must survive.
		local side = CreateFrame("Frame", "SpellBookSideTabsFrame", sb)
		for i = 1, 8 do
			local t = CreateFrame("CheckButton", "SpellBookSkillLineTab" .. i, side)
			t:SetSize(32, 32)

			-- The stone plate: 64px of art behind a 32px button, which is why
			-- the client has to space these 17 apart.
			t.__plate = t:CreateTexture(nil, "BACKGROUND")
			t.__plate:SetTexture("Interface\\SpellBook\\SpellBook-SkillLineTab")

			t:SetNormalTexture("")     -- empty until the client fills it in
			-- Which school you are looking at. It has to outlive the dressing for
			-- the same reason the icon does.
			t:SetCheckedTexture("Interface\\Buttons\\CheckButtonHilight")
			t:SetPoint("TOPLEFT", side, "TOPRIGHT", -32, -65 - (i - 1) * 49)
			if i > 3 then t:Hide() end

			CreateFrame("Frame", "SpellBookSkillLineTab" .. i .. "Flash", side)
		end

		local nav = CreateFrame("Frame", "SpellBookPageNavigationFrame", sb)
		local pageText = nav:CreateFontString("SpellBookPageText", "OVERLAY")
		pageText:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
		pageText:SetText("Page 1")
		-- PRINTED IN NEAR-BLACK, because the client is printing it on parchment.
		-- On glass that is a page number nobody can read, and a mock that leaves
		-- every string white cannot show it.
		pageText:SetTextColor(0.25, 0.12, 0)
		pageText:SetPoint("BOTTOMRIGHT", sb, "BOTTOMRIGHT", -110, 38)

		for _, n in ipairs({ "SpellBookPrevPageButton", "SpellBookNextPageButton" }) do
			local b = CreateFrame("Button", n, nav)
			b:SetSize(32, 32)
			-- The arrow is engraved in the art. Take the art off without putting
			-- something there and the page turner is two invisible squares.
			b:SetNormalTexture("Interface\\Buttons\\UI-SpellbookIcon-PrevPage-Up")
			b:SetDisabledTexture("Interface\\Buttons\\UI-SpellbookIcon-PrevPage-Disabled")
		end

		local ranks = CreateFrame("CheckButton", "ShowAllSpellRanksCheckbox", sb)
		ranks:SetSize(26, 26)
		-- 38 BELOW THE FRAME, which is where the client puts it: up beside the
		-- title, on the parchment's own top margin. Under our header band that
		-- is inside the band, and the switch sat across the hairline.
		ranks:SetPoint("TOPLEFT", sb, "TOPLEFT", 74, -38)
		ranks:SetNormalTexture("checkbox-up")
		ranks:SetCheckedTexture("checkbox-tick")
		local ranksText = ranks:CreateFontString("ShowAllSpellRanksCheckboxText", "OVERLAY")
		ranksText:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
		ranksText:SetText("Show All Spell Ranks")
		-- FLUSH TO THE BUTTON'S EDGE, as the client anchors it. That reads fine
		-- against Blizzard's art, which is a small square inside a larger
		-- transparent button - the words clear the box by several pixels of
		-- nothing. Ours fills the button, so flush means touching.
		ranks.Text = ranksText
		ranksText:SetPoint("LEFT", ranks, "RIGHT", 0, 1)

		-- The client's own rebuild, as a mixin method copied onto the frame -
		-- which is why it has to be hooked on the frame and not by name. It
		-- shows the tabs that apply and re-anchors the school column, both of
		-- which undo a layout done once at dress time.
		function sb:Update()
			-- All three down, then the ones that apply back up, which is what
			-- makes the first dress see an empty row.
			for i = 1, 3 do _G["SpellBookFrameTabButton" .. i]:Hide() end

			_G.SpellBookFrameTabButton1:Show()
			_G.SpellBookFrameTabButton1:Disable()      -- selected IS disabled
			_G.SpellBookFrameTabButton2:Show()
			_G.SpellBookFrameTabButton2:Enable()
			self:UpdateSkillLineTabs()
		end

		-- Sets the school's icon through SetNormalTexture on every refresh, and
		-- marks the one you are on. It does NOT re-anchor: the client's only
		-- SetPoint in here is behind an off-spec test that no character on this
		-- flavour ever passes.
		function sb:UpdateSkillLineTabs()
			for i = 1, 3 do
				local t = _G["SpellBookSkillLineTab" .. i]
				t:SetNormalTexture("Interface\\Icons\\Spell_Frost_FrostBolt02")
				t:SetChecked(i == 1)
			end
		end
	end

	-- The talent tree's insides, built when its addon turns up.
	--
	-- THE BRANCHES AND ARROWS ARE THE POINT. They are regions of the scroll
	-- child and of the arrow frame, and they are the only thing saying which
	-- talent depends on which - so a strip of either frame leaves forty
	-- unconnected icons and a suite that never noticed.
	--
	-- The Slot texture is the other one to get right: the client uses it to say
	-- what state a talent is in, in colour - green for a point you can spend,
	-- gold for finished, grey for neither - and it re-says it on every update.
	function _G.__buildTalentInsides()
		local tf = _G.PlayerTalentFrame
		if not tf or tf.__insides then return end
		tf.__insides = true
		tf:SetSize(384, 512)

		local scroll = CreateFrame("ScrollFrame", "PlayerTalentFrameScrollFrame", tf)
		for _, part in ipairs({ "TopLeft", "TopRight", "BottomLeft", "BottomRight" }) do
			local t = scroll:CreateTexture("PlayerTalentFrameBackground" .. part, "BORDER")
			t:SetTexture("Interface\\TalentFrame\\HunterBeastMastery-" .. part)
		end

		local sb = CreateFrame("Slider", "PlayerTalentFrameScrollFrameScrollBar", scroll)
		CreateFrame("Button", "PlayerTalentFrameScrollFrameScrollBarScrollUpButton", sb)
			:SetNormalTexture("arrow-up")
		CreateFrame("Button", "PlayerTalentFrameScrollFrameScrollBarScrollDownButton", sb)
			:SetNormalTexture("arrow-down")

		local child = CreateFrame("Frame", "PlayerTalentFrameScrollChildFrame", scroll)
		for i = 1, 30 do
			local t = child:CreateTexture("PlayerTalentFrameBranch" .. i, "BACKGROUND")
			t:SetTexture("Interface\\TalentFrame\\UI-TalentBranches")
		end

		local arrows = CreateFrame("Frame", "PlayerTalentFrameArrowFrame", child)
		for i = 1, 30 do
			local t = arrows:CreateTexture("PlayerTalentFrameArrow" .. i, "OVERLAY")
			t:SetTexture("Interface\\TalentFrame\\UI-TalentArrows")
		end

		-- Three talents, one per state, because a tree in one state proves one
		-- branch of the rim and looks like coverage.
		local STATE = {
			[1] = { 0.1, 1.0, 0.1 },       -- a point can go here
			[2] = { 1.0, 0.82, 0.0 },      -- finished
			[3] = { 0.5, 0.5, 0.5 },       -- not yet
		}
		for i = 1, 40 do
			local b = CreateFrame("Button", "PlayerTalentFrameTalent" .. i, child)
			b:SetSize(32, 32)

			local icon = b:CreateTexture(nil, "BORDER")
			icon:SetTexture("talent-icon-" .. i)
			_G["PlayerTalentFrameTalent" .. i .. "IconTexture"] = icon

			-- The stone ring behind the icon, and the state the client says in
			-- its vertex colour.
			local slot = b:CreateTexture("PlayerTalentFrameTalent" .. i .. "Slot", "BACKGROUND")
			slot:SetTexture("Interface\\Buttons\\UI-EmptySlot-White")
			local s = STATE[i] or STATE[3]
			slot:SetVertexColor(s[1], s[2], s[3])

			local border = b:CreateTexture("PlayerTalentFrameTalent" .. i .. "RankBorder", "OVERLAY")
			border:SetTexture("Interface\\TalentFrame\\TalentFrame-RankBorder")
			if i == 3 then border:Hide() end

			local rank = b:CreateFontString("PlayerTalentFrameTalent" .. i .. "Rank", "OVERLAY")
			rank:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
			rank:SetText(tostring((i == 2) and 5 or 2))

			b:SetNormalTexture("Interface\\Buttons\\UI-Quickslot2")
		end

		for _, n in ipairs({ "PlayerTalentFrameStatusFrame", "PlayerTalentFramePointsBar",
			"PlayerTalentFramePreviewBar", "PlayerTalentFramePreviewBarFiller" }) do
			CreateFrame("Frame", n, tf):CreateTexture(nil, "BORDER")
				:SetTexture("Interface\\Buttons\\UI-Button-Borders2")
		end

		local spent = _G.PlayerTalentFrameStatusFrame:CreateFontString(
			"PlayerTalentFrameSpentPointsText", "OVERLAY")
		spent:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
		spent:SetText("5 points spent in Beast Mastery")

		local points = _G.PlayerTalentFramePointsBar:CreateFontString(
			"PlayerTalentFrameTalentPointsText", "OVERLAY")
		points:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
		points:SetText("3")

		for _, n in ipairs({ "PlayerTalentFrameActivateButton", "PlayerTalentFrameResetButton",
			"PlayerTalentFrameLearnButton" }) do
			local b = CreateFrame("Button", n, tf)
			b:SetNormalTexture("panel-button-up")
			local fs = b:CreateFontString(nil, "OVERLAY")
			fs:SetText(n)
			b.__fs = fs
			function b:GetFontString() return self.__fs end
		end

		-- A second Close, down in the corner of the tree, doing what the one in
		-- the window's corner already does.
		local spare = CreateFrame("Button", "PlayerTalentFrameCancelButton", tf)
		spare:SetNormalTexture("cancel-up")
		spare:Show()

		-- Its close button sits 44 in and 25 down, in the middle of a stone rim.
		_G.PlayerTalentFrameCloseButton:SetPoint("CENTER", tf, "TOPRIGHT", -44, -25)

		for i, label in ipairs({ "Beast Mastery", "Marksmanship", "Survival", "Glyphs" }) do
			local t = CreateFrame("Button", "PlayerTalentFrameTab" .. i, tf)
			t:SetPoint("BOTTOMLEFT", tf, "BOTTOMLEFT", 15 + (i - 1) * 90, 46)
			t:SetNormalTexture("tab-up")
			local fs = t:CreateFontString(nil, "OVERLAY")
			fs:SetText(label)
			t.__fs = fs
			function t:GetFontString() return self.__fs end
			_G["PlayerTalentFrameTab" .. i .. "Text"] = fs
			if i == 4 then t:Hide() end          -- no glyphs on this flavour
		end

		for i = 1, 3 do
			local t = CreateFrame("CheckButton", "PlayerSpecTab" .. i, tf)
			t:SetSize(32, 32)
			t.__plate = t:CreateTexture(nil, "BACKGROUND")
			t.__plate:SetTexture("Interface\\SpellBook\\SpellBook-SkillLineTab")
			t:SetNormalTexture("")
			t:Hide()                              -- no dual spec on this flavour
		end

		-- The client's own repaint. It re-sets the four background pieces from
		-- the spec's art and re-colours every Slot, so anything we did once at
		-- dress time is undone on the first tab click.
		function _G.TalentFrame_Update()
			for _, part in ipairs({ "TopLeft", "TopRight", "BottomLeft", "BottomRight" }) do
				_G["PlayerTalentFrameBackground" .. part]
					:SetTexture("Interface\\TalentFrame\\HunterSurvival-" .. part)
			end
			for i = 1, 40 do
				local b = _G["PlayerTalentFrameTalent" .. i]
				b:SetNormalTexture("Interface\\Buttons\\UI-Quickslot2")
				local s = STATE[i] or STATE[3]
				_G["PlayerTalentFrameTalent" .. i .. "Slot"]
					:SetVertexColor(s[1], s[2], s[3])
			end
		end
	end

	-- The guild window, which on this client is Communities.
	--
	-- READ OFF THE LIVE CLIENT, not out of Blizzard's source: the reference tree
	-- has no Blizzard_Communities, which is what `/aether panels dump` exists
	-- for. So this is shaped by what that command reported, and the two things
	-- it settled are the two a guess would have got wrong.
	--
	-- A side tab keeps its picture in an ICON REGION - not as the normal
	-- texture, the way the spellbook's school tabs do - with a stone ring behind
	-- it. And every push button is three slices, Left/Right/Middle, so there is
	-- no normal texture for ClearButton to clear and the plate outlives it.
	function _G.__buildCommunities()
		local cf = _G.CommunitiesFrame
		if not cf or cf.__insides then return end
		cf.__insides = true
		cf:SetSize(814, 426)

		local function WideButton(parent, key, label)
			local b = CreateFrame("Button", nil, parent)
			b:SetSize(130, 20)
			for _, part in ipairs({ "Left", "Right", "Middle" }) do
				b[part] = b:CreateTexture(nil, "BACKGROUND")
				b[part]:SetTexture("Interface\\Buttons\\UI-Panel-Button-Up")
			end
			local fs = b:CreateFontString(nil, "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetText(label)
			b.__fs = fs
			function b:GetFontString() return self.__fs end
			parent[key] = b
			return b
		end

		local function Dropdown(parent, key)
			local d = CreateFrame("Button", nil, parent)
			d:SetSize(160, 24)
			d.Background = d:CreateTexture(nil, "BACKGROUND")
			d.Background:SetTexture("common-dropdown-classic-textholder")
			-- KEPT. The arrow is what says the control opens, and nothing of
			-- ours would say it better at this size.
			d.Arrow = d:CreateTexture(nil, "OVERLAY")
			d.Arrow:SetTexture("common-dropdown-classic-a-buttonDown")
			d.Text = d:CreateFontString(nil, "OVERLAY")
			d.Text:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			d.Text:SetText("Guild Chat")
			parent[key] = d
			return d
		end

		for _, key in ipairs({ "ChatTab", "RosterTab", "GuildBenefitsTab",
			"GuildInfoTab" }) do
			local t = CreateFrame("CheckButton", nil, cf)
			t:SetSize(32, 32)
			-- The stone ring, and the picture beside it.
			t.__ring = t:CreateTexture(nil, "BORDER")
			t.__ring:SetTexture("Interface\\Buttons\\UI-Quickslot2")
			t.Icon = t:CreateTexture(nil, "ARTWORK")
			t.Icon:SetTexture("communities-icon-" .. key)
			cf[key] = t
		end

		for _, key in ipairs({ "CommunitiesList", "MemberList", "ApplicantList",
			"Chat", "GuildBenefitsFrame", "GuildDetailsFrame",
			"GuildMemberDetailFrame" }) do
			local pane = CreateFrame("Frame", nil, cf)
			pane:CreateTexture(nil, "ARTWORK"):SetTexture("communities-pane-art")

			-- A FRAME OF FRAMES, which is what a modern scroll bar is: a track,
			-- a thumb and two arrows, each a child. A mock that put regions on
			-- the bar itself would let a strip of the bar look like it worked,
			-- and the stone would still be down the side of the list.
			pane.ScrollBar = CreateFrame("Frame", nil, pane)
			pane.ScrollBar.Track = CreateFrame("Frame", nil, pane.ScrollBar)
			pane.ScrollBar.Track:CreateTexture(nil, "BACKGROUND"):SetTexture("scroll-track-stone")
			pane.ScrollBar.Back = CreateFrame("Button", nil, pane.ScrollBar)
			pane.ScrollBar.Back:SetNormalTexture("scroll-arrow-up")
			pane.ScrollBar.Forward = CreateFrame("Button", nil, pane.ScrollBar)
			pane.ScrollBar.Forward:SetNormalTexture("scroll-arrow-down")
			pane.ColumnDisplay = CreateFrame("Frame", nil, pane)
			pane.ColumnDisplay:CreateTexture(nil, "BACKGROUND"):SetTexture("column-stone")
			pane.InsetFrame = CreateFrame("Frame", nil, pane)
			pane.InsetFrame:CreateTexture(nil, "BACKGROUND"):SetTexture("inset-stone")

			local fs = pane:CreateFontString(nil, "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 11, "")
			fs:SetText("0/0 Online")

			cf[key] = pane
			pane:Hide()          -- panes arrive when their tab is picked
		end

		-- THE ROSTER'S ROWS, WHICH ARE NOT THE PANE'S. A modern ScrollBox does
		-- not own them: it takes them from a pool during its OWN layout and
		-- hands them back when they scroll out - so what the list holds when
		-- the window is dressed is not what it holds a moment later.
		--
		-- And a row's plaque is its own NORMAL TEXTURE, setAllPoints, out of
		-- Interface\\GuildFrame\\GuildFrame. Stripping the PANE reaches none of
		-- it, which a mock with no rows in it could not show.
		for _, key in ipairs({ "MemberList", "CommunitiesList", "ApplicantList" }) do
			local pane = cf[key]
			local box = CreateFrame("Frame", nil, pane)
			box.__rows = {}
			local function commRow()
				local row = CreateFrame("Button", nil, box)
				row:SetSize(280, 20)
				row:SetNormalTexture("Interface\\GuildFrame\\GuildFrame")
				-- The class glyph and the voice lamp are regions of the row in
				-- the same layer, so a plain strip takes both.
				row.Class = row:CreateTexture(nil, "OVERLAY")
				row.Class:SetTexture("Interface\\Glues\\CharacterCreate\\UI-CharacterCreate-Classes")
				row.VoiceChatStatusIcon = row:CreateTexture(nil, "OVERLAY")
				row.VoiceChatStatusIcon:SetTexture("voice-chat-lamp")
				row.Name = row:CreateFontString(nil, "OVERLAY")
				row.Name:SetFont("Fonts\\FRIZQT__.TTF", 11, "")
				row.Name:SetText("Guildmate")
				box.__rows[#box.__rows + 1] = row
				return row
			end
			for _ = 1, 6 do commRow() end
			-- ITS OWN ITERATOR, which is what the addon reaches for first: a
			-- list handed back a moment too early is the set that was there
			-- before the rebuild.
			function box:ForEachFrame(fn)
				for _, row in ipairs(self.__rows) do fn(row) end
			end
			-- AND ROWS ACQUIRED DURING ITS OWN LAYOUT. Update is where a
			-- scroll box takes them from the pool, which is why it is the hook
			-- point and the window's Update is not.
			function box:Update() commRow() end
			pane.ScrollBox = box
		end

		-- The ornate frame around the community list: corners and bars in an
		-- overlay child of its own.
		cf.CommunitiesList.FilligreeOverlay = CreateFrame("Frame", nil, cf.CommunitiesList)
		cf.CommunitiesList.FilligreeOverlay:CreateTexture(nil, "OVERLAY")
			:SetTexture("communities-filigree")

		cf.MemberList.ShowOfflineButton = CreateFrame("CheckButton", nil, cf.MemberList)
		cf.MemberList.ShowOfflineButton:SetNormalTexture("checkbox-up")
		cf.MemberList.ShowOfflineButton:SetCheckedTexture("checkbox-tick")

		cf.CommunitiesControlFrame = CreateFrame("Frame", nil, cf)
		WideButton(cf.CommunitiesControlFrame, "GuildControlButton", "Guild Settings")
		WideButton(cf, "InviteButton", "Invite Member")
		WideButton(cf, "GuildLogButton", "View Log")
		WideButton(cf.GuildMemberDetailFrame, "RemoveButton", "Remove")

		Dropdown(cf, "StreamDropdown")
		Dropdown(cf.GuildMemberDetailFrame, "RankDropdown")

		cf.MaximizeMinimizeFrame = CreateFrame("Frame", nil, cf)
		for _, key in ipairs({ "MaximizeButton", "MinimizeButton" }) do
			local b = CreateFrame("Button", nil, cf.MaximizeMinimizeFrame)
			b:SetNormalTexture("maximize-art")
			cf.MaximizeMinimizeFrame[key] = b
		end

		cf.ChatEditBox = CreateFrame("EditBox", nil, cf)
		for _, part in ipairs({ "Left", "Right", "Mid" }) do
			cf.ChatEditBox[part] = cf.ChatEditBox:CreateTexture(nil, "BACKGROUND")
			cf.ChatEditBox[part]:SetTexture("editbox-stone")
		end

		-- THE CREST HANGS OFF THE CORNER, which is what the portrait template
		-- does on purpose: it overlaps a stone ring that framed it, the same
		-- trick the main menu's title plate plays. Take the ring away and it is
		-- a disc floating outside the window.
		cf.PortraitOverlay = CreateFrame("Frame", nil, cf)
		cf.PortraitOverlay.Portrait = cf.PortraitOverlay:CreateTexture(nil, "BACKGROUND")
		cf.PortraitOverlay.Portrait:SetTexture("guild-tabard")
		cf.PortraitOverlay.Portrait:SetSize(61, 61)
		cf.PortraitOverlay.Portrait:SetPoint("TOPLEFT", cf, "TOPLEFT", -6, 8)
		-- Three textures stacked, not one, and a mask that has to follow them.
		for _, key in ipairs({ "CircleMask", "TabardBackground", "TabardEmblem",
			"TabardBorder" }) do
			cf.PortraitOverlay[key] = cf.PortraitOverlay:CreateTexture(nil, "BACKGROUND")
		end

		-- What you get when you are in no guild at all: a dark plate with the
		-- client's own art on it and two paragraphs telling you what a guild is.
		local finder = CreateFrame("Frame", "ClubFinderGuildFinderFrame", cf)
		finder:CreateTexture(nil, "BACKGROUND"):SetTexture("communities-widebackground")
		finder.DisabledFrame = CreateFrame("Frame", nil, finder)
		finder.DisabledFrame:CreateTexture(nil, "BACKGROUND"):SetTexture("clubfinder-bg")
		finder.DisabledFrame.Title = finder.DisabledFrame:CreateFontString(nil, "OVERLAY")
		finder.DisabledFrame.Title:SetFont("Fonts\\FRIZQT__.TTF", 24, "")
		finder.DisabledFrame.Title:SetText("Guild")
		finder.DisabledFrame.Description = finder.DisabledFrame:CreateFontString(nil, "OVERLAY")
		finder.DisabledFrame.Description:SetFont("Fonts\\FRIZQT__.TTF", 13, "")
		finder.DisabledFrame.Description:SetText("A guild is a tight-knit group of players")
		finder.InsetFrame = CreateFrame("Frame", nil, finder)
		finder.InsetFrame:CreateTexture(nil, "BACKGROUND"):SetTexture("inset-stone")
	end

	-- The windows an NPC opens, at the shapes their own templates give them.
	--
	-- The rows are the part worth modelling. A merchant row keeps the item's
	-- picture on a BUTTON INSIDE IT while its own regions are the empty-slot
	-- disc and the stone label plate - which is what makes stripping the row
	-- safe and stripping the button fatal. Getting that backwards blanks the
	-- shop and leaves the furniture.
	do
		local merchant = _G.MerchantFrame
		merchant:SetSize(336, 442)

		for i = 1, 12 do
			local row = CreateFrame("Frame", "MerchantItem" .. i, merchant)
			row:SetSize(153, 44)
			-- ONLY THE FIRST IS ANCHORED TO THE WINDOW; the other nine chain off
			-- it, two to a line. That is the client's own arrangement and the
			-- reason this window can be moved at all: it has no pane, so the
			-- first row is the handle for the whole grid.
			if i == 1 then
				row:SetPoint("TOPLEFT", merchant, "TOPLEFT", 11, -69)
			elseif i % 2 == 0 then
				row:SetPoint("TOPLEFT", _G["MerchantItem" .. (i - 1)],
					"TOPRIGHT", 12, 0)
			else
				row:SetPoint("TOPLEFT", _G["MerchantItem" .. (i - 2)],
					"BOTTOMLEFT", 0, -6)
			end
			row.__slot = row:CreateTexture(nil, "BACKGROUND")
			row.__slot:SetTexture("Interface\\Buttons\\UI-EmptySlot")
			row.__plate = row:CreateTexture(nil, "BACKGROUND")
			row.__plate:SetTexture("Interface\\MerchantFrame\\UI-Merchant-LabelSlots")

			-- THE ROW IS WIDER THAN WHAT IS PRINTED IN IT. Blizzard's template is
			-- 153 across and the name and price together use about ninety of it, so
			-- a skin that measures the ROW is measuring a box with air on the right
			-- and pads the window out to fit the air.
			row.Name = row:CreateFontString("MerchantItem" .. i .. "Name", "BACKGROUND")
			row.Name:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
			row.Name:SetText("Crusty Loaf")
			row.Name:SetSize(70, 12)
			row.Name:SetPoint("TOPLEFT", row, "TOPLEFT", 42, -4)

			-- The item, on a button of its own. Its icon is a region of THAT.
			local b = CreateFrame("Button", "MerchantItem" .. i .. "ItemButton", row)
			b:SetSize(37, 37)
			b:SetPoint("TOPLEFT", row, "TOPLEFT", 2, -2)
			local icon = b:CreateTexture(nil, "BACKGROUND")
			icon:SetTexture("merchant-icon-" .. i)
			_G["MerchantItem" .. i .. "ItemButtonIconTexture"] = icon
			b:SetNormalTexture("slot-border")
			row.ItemButton = b

			row.MoneyFrame = CreateFrame("Frame", "MerchantItem" .. i .. "MoneyFrame", row)
			row.MoneyFrame:SetSize(50, 12)
			row.MoneyFrame:SetPoint("TOPLEFT", row, "TOPLEFT", 42, -24)
			local coin = row.MoneyFrame:CreateFontString(nil, "OVERLAY")
			coin:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
			coin:SetText("5s 12c")
		end

		for _, n in ipairs({ "MerchantMoneyInset", "MerchantMoneyBg",
			"MerchantMoneyFrame" }) do
			CreateFrame("Frame", n, merchant):CreateTexture(nil, "BACKGROUND")
				:SetTexture("merchant-money-stone")
		end

		-- THE ANVIL IS A REGION, not the normal texture - and it is named after
		-- the button's stem rather than after the button, and it is cropped out
		-- of a shared sheet by texcoords. A mock that hung it off the normal
		-- texture would let a cell look like the right treatment; it clears the
		-- anvil and leaves an empty square.
		for _, n in ipairs({ "MerchantRepairAllButton", "MerchantRepairItemButton",
			"MerchantGuildBankRepairButton" }) do
			local b = CreateFrame("Button", n, merchant)
			b:SetSize(36, 36)
			local icon = b:CreateTexture(
				n == "MerchantRepairAllButton" and "MerchantRepairAllIcon" or nil, "BORDER")
			icon:SetTexture("Interface\\MerchantFrame\\UI-Merchant-RepairIcons")
			icon:SetTexCoord(0.28125, 0.5625, 0, 0.5625)
		end

		-- WHERE THE CLIENT PUTS THEM: hard against the window's bottom-left,
		-- and TWO UNITS APART - close enough that a surface with a rim on it
		-- has the two overlapping. Both facts matter, and a mock that left
		-- them unplaced could show neither.
		_G.MerchantRepairAllButton:SetPoint("BOTTOMRIGHT", merchant,
			"BOTTOMLEFT", 172, 11)
		_G.MerchantRepairItemButton:SetPoint("RIGHT",
			_G.MerchantRepairAllButton, "LEFT", -2, 0)

		-- THE LAST THING YOU SOLD, which the client hangs 53 below the tenth
		-- item - so it is the final row of the grid, in the RIGHT column, with
		-- the left half of that row empty.
		local buy = CreateFrame("Frame", "MerchantBuyBackItem", merchant)
		buy:SetSize(153, 37)
		buy:SetPoint("TOPLEFT", _G.MerchantItem10, "BOTTOMLEFT", 0, -53)
		local buyBtn = CreateFrame("Button", "MerchantBuyBackItemItemButton", buy)
		buyBtn:SetSize(37, 37)
		buyBtn:SetPoint("TOPLEFT", buy, "TOPLEFT", 2, -2)
		buyBtn:CreateTexture(nil, "BACKGROUND"):SetTexture("buyback-icon")
		buy.ItemButton = buyBtn

		-- AND THE CLIENT RE-PLACES ALL THREE ON EVERY MERCHANT UPDATE, WITHOUT
		-- CLEARING THEIR POINTS FIRST. Both halves of that matter.
		--
		-- It anchors RepairItem OFF RepairAll, so anything of ours hanging
		-- RepairAll off RepairItem closes a loop and this SetPoint is the one
		-- that throws. And its own corners are ADDED to whatever is already
		-- there, so a placement made once is a button stretched between two
		-- anchors the next time a vendor updates.
		function _G.MerchantFrame_UpdateRepairButtons()
			_G.MerchantRepairAllButton:SetSize(36, 36)
			_G.MerchantRepairItemButton:SetSize(36, 36)
			_G.MerchantRepairItemButton:SetPoint("RIGHT",
				_G.MerchantRepairAllButton, "LEFT", -2, 0)
			_G.MerchantRepairAllButton:SetPoint("BOTTOMRIGHT", merchant,
				"BOTTOMLEFT", 160, 32)
			_G.MerchantRepairText:ClearAllPoints()
			_G.MerchantRepairText:SetPoint("BOTTOMLEFT", merchant,
				"BOTTOMLEFT", 14, 45)
		end

		local repairText = merchant:CreateFontString("MerchantRepairText", "BACKGROUND")
		repairText:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
		repairText:SetText("Repair Items")

		-- It says "Prev" and "Next" in words of its own, so it wants a pill
		-- rather than one of our marks - a glyph as well is a chevron sitting
		-- beside a word that already says the same thing.
		for i, n in ipairs({ "MerchantPrevPageButton", "MerchantNextPageButton" }) do
			local b = CreateFrame("Button", n, merchant)
			b:SetNormalTexture("merchant-arrow")
			local fs = b:CreateFontString(n .. "Text", "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
			fs:SetText(i == 1 and "Prev" or "Next")
			fs:SetTextColor(1, 0.82, 0)
			b.__fs = fs
			function b:GetFontString() return self.__fs end
		end

		local page = merchant:CreateFontString("MerchantPageText", "OVERLAY")
		page:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
		page:SetText("Page 1")
		-- A BOX FAR WIDER THAN WHAT IS IN IT, which is the client's own number:
		-- 104 for the words "Page 1". A string draws CENTRED in its box however
		-- little it says, so the ends of that box slide under whatever is beside
		-- it - which on this window is the two page turns. Without the width
		-- here the mock could not tell a box cut to its words from one that was
		-- never wide in the first place.
		page:SetWidth(104)

		-- WHO YOU ARE BUYING FROM, which is the thing worth putting in this
		-- window's header - the frame's own title says "MerchantFrame", which
		-- is a description of the window rather than a name. The client hangs
		-- it beside the portrait in its own small type, so a skin that only
		-- looks for $parentTitleText finds the wrong string and reports success.
		local vendor = merchant:CreateFontString("MerchantNameText", "OVERLAY")
		vendor:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
		vendor:SetText("Gakin the Darkbinder")

		for i, label in ipairs({ "Merchant", "Buyback" }) do
			local t = CreateFrame("Button", "MerchantFrameTab" .. i, merchant)
			t:SetNormalTexture("tab-up")
			local fs = t:CreateFontString(nil, "OVERLAY")
			fs:SetText(label)
			t.__fs = fs
			function t:GetFontString() return self.__fs end
			_G["MerchantFrameTab" .. i .. "Text"] = fs
			t:SetPoint("BOTTOMLEFT", merchant, "BOTTOMLEFT", 10 + (i - 1) * 90, 40)
		end
	end

	-- The quest giver: four panels of one window, one shown at a time.
	do
		local quest = _G.QuestFrame
		quest:SetSize(384, 512)

		-- FOUR PANELS, EACH FILLING THE WINDOW, one up at a time - and the quest
		-- itself printed in a scroll frame anchored to the WINDOW rather than to
		-- the panel, 23 in and 81 down. Unanchored mock panes measure as nothing,
		-- so a window whose content never moved looked laid out.
		for _, n in ipairs({ "QuestFrameDetailPanel", "QuestFrameProgressPanel",
			"QuestFrameRewardPanel", "QuestFrameGreetingPanel",
			"QuestDetailScrollFrame", "QuestProgressScrollFrame",
			"QuestRewardScrollFrame", "QuestGreetingScrollFrame" }) do
			-- THE FOUR PAGES ARE SCROLL FRAMES, and that is not a detail: one CLIPS
			-- at its own bounds and nowhere else, so a page moved down the window
			-- without being shortened moves where the clipping happens too - the
			-- quest's text carried on past the foot of the recess and under Accept.
			-- A mock that made them plain frames could not show it.
			local kind = n:find("Panel", 1, true) and "Frame" or "ScrollFrame"
			local p = CreateFrame(kind, n, quest)
			if n:find("Panel", 1, true) then
				p:SetSize(384, 512)
				p:SetPoint("TOPLEFT", quest, "TOPLEFT", 0, 0)
				if n ~= "QuestFrameDetailPanel" then p:Hide() end
			else
				p:SetSize(300, 334)
				p:SetPoint("TOPLEFT", quest, "TOPLEFT", 23, -81)
				local page = CreateFrame("Frame", n .. "ChildFrame", p)
				page:SetSize(300, 900)
				p:SetScrollChild(page)
			end
			p:CreateTexture(nil, "BACKGROUND"):SetTexture("quest-parchment")

			-- PRINTED ON PAPER. The client's quest text is near black because
			-- that is what reads on parchment, and on glass it is a dark
			-- smudge. A mock that left every string white could not show it,
			-- and the whole window came back looking correct.
			local fs = p:CreateFontString(n .. "Ink", "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetText("Kill six boars.")
			fs:SetTextColor(0.10, 0.10, 0.10)

			-- And one that is NOT dark, because it was chosen to mean
			-- something. Gold headings and reward names have to come through.
			local gold = p:CreateFontString(n .. "Gold", "OVERLAY")
			gold:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			gold:SetText("Rewards")
			gold:SetTextColor(1, 0.82, 0)
		end

		-- WHO IS TALKING, under the name the CLIENT gives it. The string is
		-- QuestFrameNpcNameText and the frame it hangs off is QuestNpcNameFrame,
		-- so anything looking up "frame name + Text" asks for a global this game
		-- does not have. A mock that answered to the convenient name hid the fact
		-- that the quest giver had no title of ours on it at all.
		local who = CreateFrame("Frame", "QuestNpcNameFrame", quest)
		who:SetSize(300, 14)
		who:SetPoint("TOP", quest, "TOP", 0, -23)
		who:CreateTexture(nil, "BACKGROUND"):SetTexture("quest-name-stone")
		local whoText = who:CreateFontString("QuestFrameNpcNameText", "BACKGROUND")
		whoText:SetFont("Fonts\\FRIZQT__.TTF", 14, "")
		whoText:SetText("Gornek")

		-- ITS BUTTONS, IN PAIRS, one pair per panel - and each anchored to a
		-- bottom CORNER of the window with the whole quest between them. They are
		-- children of their panel and every one of them is shown the whole time:
		-- THE GREETING: AN NPC WITH MORE THAN ONE QUEST, listed under Current
		-- Quests and Available Quests with a gold swirl between them. Its own
		-- block because it is the one page in this window the client REDRAWS
		-- under us - QuestFrame re-runs QuestFrameGreetingPanel_OnShow on
		-- QUEST_LOG_UPDATE, which is what accepting one of the quests on it
		-- does - and none of that was mocked, so a skin that dressed the page
		-- once looked permanent in here and was overwritten in the game.
		do
			-- ITS REAL NAME. The loop above makes QuestGreetingScrollFrameChildFrame
			-- out of the scroll frame's name; the client calls this one
			-- QuestGreetingScrollChildFrame, with no Frame in the middle, and
			-- code reaching for the client's spelling found nothing here.
			local page = CreateFrame("Frame", "QuestGreetingScrollChildFrame",
				_G.QuestGreetingScrollFrame)
			page:SetSize(300, 900)
			page:CreateTexture(nil, "BACKGROUND"):SetTexture("quest-parchment")

			for _, n in ipairs({ "GreetingText", "CurrentQuestsText",
				"AvailableQuestsText" }) do
				local fs = page:CreateFontString(n, "OVERLAY")
				fs:SetFont([[Fonts\FRIZQT__.TTF]], 12, "")
				fs:SetText(n)
				-- PRINTED ON PARCHMENT, from the moment the page is built. The
				-- mock left these at the default white, so a dresser that lifts
				-- only DARK text - which is the rule, because a gold heading
				-- means what it says - had nothing to do and looked correct.
				fs:SetTextColor(0.10, 0.10, 0.10)
				_G[n] = fs
			end

			-- THE SWIRL. A REGION of the scroll child rather than a row of
			-- anything, so a sweep of the PANEL never reaches it - and the
			-- client shows it again whenever there is an active quest.
			local brk = page:CreateTexture("QuestGreetingFrameHorizontalBreak",
				"ARTWORK")
			brk:SetTexture([[Interface\QuestFrame\UI-HorizontalBreak]])
			_G.QuestGreetingFrameHorizontalBreak = brk

			for i = 1, 6 do
				local b = CreateFrame("Button", "QuestTitleButton" .. i, page)
				b:SetSize(300, 16)
				local icon = b:CreateTexture("QuestTitleButton" .. i .. "QuestIcon",
					"BACKGROUND")
				icon:SetTexture([[Interface\GossipFrame\AvailableQuestIcon]])
				_G["QuestTitleButton" .. i .. "QuestIcon"] = icon
				b:SetHighlightTexture([[Interface\QuestFrame\UI-QuestTitleHighlight]])
				local fs = b:CreateFontString(nil, "OVERLAY")
				fs:SetFont([[Fonts\FRIZQT__.TTF]], 12, "")
				-- WITH THE BLACK INSIDE THE STRING, as the display format puts
				-- it there: |cff000000%s|r. GetTextColor answers the font
				-- object and never sees the escape that is actually drawn.
				fs:SetText("|cff000000Minshina's Skull|r")
				fs:SetTextColor(1, 1, 1)
				b.__fs = fs
				function b:GetFontString() return self.__fs end
				if i > 3 then b:Hide() end
			end

			--- The client's own redraw, exactly as QuestFrame runs it.
			--
			--  Not only an OnShow: QuestFrame:OnEvent re-runs this on
			--  QUEST_LOG_UPDATE while the panel is up. Everything it touches is
			--  something a skin has already done and is about to lose.
			function _G.QuestFrameGreetingPanel_OnShow()
				page:CreateTexture(nil, "BACKGROUND"):SetTexture("quest-parchment")
				_G.GreetingText:SetTextColor(0.10, 0.10, 0.10)
				_G.CurrentQuestsText:SetTextColor(0.20, 0.17, 0.09)
				_G.AvailableQuestsText:SetTextColor(0.20, 0.17, 0.09)
				brk:Show()
				for i = 1, 6 do
					local b = _G["QuestTitleButton" .. i]
					-- THROUGH THE DISPLAY FORMAT, which is |cff000000%s|r - so
					-- the black is INSIDE the string and SetTextColor cannot
					-- reach it. Same fault as the gossip list, one window along.
					b.__fs:SetText("|cff000000Minshina's Skull|r")
					b.__fs:SetTextColor(1, 1, 1)
					b:SetNormalTexture("quest-title-plate")
				end
			end
		end

		-- what the client hides is the panel.
		for _, spec in ipairs({
			{ "QuestFrameAcceptButton", "QuestFrameDetailPanel", 77, "LEFT", 23, 72 },
			{ "QuestFrameDeclineButton", "QuestFrameDetailPanel", 78, "RIGHT", -39, 72 },
			{ "QuestFrameCompleteButton", "QuestFrameProgressPanel", 120, "LEFT", 22, 72 },
			{ "QuestFrameGoodbyeButton", "QuestFrameProgressPanel", 78, "RIGHT", -39, 73 },
			{ "QuestFrameCompleteQuestButton", "QuestFrameRewardPanel", 120, "LEFT", 22, 72 },
			{ "QuestFrameCancelButton", "QuestFrameRewardPanel", 78, "RIGHT", -39, 73 },
			{ "QuestFrameGreetingGoodbyeButton", "QuestFrameGreetingPanel", 78,
				"RIGHT", -39, 73 },
		}) do
			local n, host, w, corner = spec[1], spec[2], spec[3], spec[4]
			local b = CreateFrame("Button", n, _G[host])
			b:SetSize(w, 22)
			b:SetPoint("BOTTOM" .. corner, quest, "BOTTOM" .. corner, spec[5], spec[6])
			b:SetNormalTexture("panel-button-up")
			local fs = b:CreateFontString(nil, "OVERLAY")
			fs:SetText(n)
			b.__fs = fs
			function b:GetFontString() return self.__fs end
		end

		-- What the quest wants from you: item buttons carrying an icon.
		for i = 1, 6 do
			local b = CreateFrame("Button", "QuestProgressItem" .. i, quest)
			local icon = b:CreateTexture(nil, "BACKGROUND")
			icon:SetTexture("quest-item-" .. i)
			_G["QuestProgressItem" .. i .. "IconTexture"] = icon
			b:SetNormalTexture("slot-border")
		end

		for _, n in ipairs({ "QuestDetailScrollFrameScrollBar",
			"QuestProgressScrollFrameScrollBar" }) do
			local sb = CreateFrame("Slider", n, quest)
			CreateFrame("Button", n .. "ScrollUpButton", sb):SetNormalTexture("arrow-up")
			CreateFrame("Button", n .. "ScrollDownButton", sb):SetNormalTexture("arrow-down")
		end
	end

	-- Gossip, on the modern portrait template - so its shell is already the
	-- shared one, and what is left is the parchment and the list.
	do
		local gossip = _G.GossipFrame

		-- THE PANEL FILLS THE WINDOW, and the list inside it does not: the client
		-- hangs the scroll box off the WINDOW at 8 in and 65 down, which is the
		-- strip its stone title plate used to need and neither our band nor our
		-- padding.
		gossip.GreetingPanel = CreateFrame("Frame", nil, gossip)
		gossip.GreetingPanel:SetSize(384, 512)
		gossip.GreetingPanel:SetPoint("TOPLEFT", gossip, "TOPLEFT", 0, 0)
		gossip.GreetingPanel:CreateTexture(nil, "BACKGROUND")
			:SetTexture("Interface\\QuestFrame\\QuestBG")
		local fs = gossip.GreetingPanel:CreateFontString(nil, "OVERLAY")
		fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
		fs:SetText("What can I do for you?")
		fs:SetTextColor(0.10, 0.10, 0.10)          -- printed on the same paper

		-- THE LIST IS A SCROLL BOX, and its rows are POOLED: acquired when the
		-- data provider changes, which is on open AND on every option you pick.
		-- A mock that hung the rows off the panel as ordinary children would let
		-- a skin that dresses them once look permanent.
		local box = CreateFrame("Frame", nil, gossip.GreetingPanel)
		box:SetSize(300, 334)
		box:SetPoint("TOPLEFT", gossip, "TOPLEFT", 8, -65)
		box.__rows = {}
		for i = 1, 4 do
			-- An option is a Button with its bullet in an Icon region.
			local row = CreateFrame("Button", nil, box)
			row.Icon = row:CreateTexture(nil, "BACKGROUND")
			row.Icon:SetTexture("Interface\\QuestFrame\\UI-Quest-BulletPoint")
			local rf = row:CreateFontString(nil, "OVERLAY")
			rf:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			rf:SetText("The bank")
			rf:SetTextColor(0.10, 0.10, 0.10)
			row.__fs = rf
			function row:GetFontString() return self.__fs end
			box.__rows[i] = row
		end
		-- A QUEST ROW IS NOT AN OPTION ROW. It keeps its title in a region of
		-- its own and answers GetFontString with nothing, so a sweep that named
		-- the string on each shape found no string here at all - which is the
		-- quest title that stayed in parchment ink on a gossip window.
		do
			local quest = CreateFrame("Button", nil, box)
			quest.Icon = quest:CreateTexture(nil, "BACKGROUND")
			quest.Icon:SetTexture("Interface\\GossipFrame\\AvailableQuestIcon")
			-- ITS INK IS INSIDE THE STRING. UpdateTitleForQuest formats the
			-- title through NORMAL_QUEST_DISPLAY, which is |cff000000%s|r - so
			-- the font string reports the font object's colour, not the black
			-- you can see, and SetTextColor cannot reach it.
			local qf = quest:CreateFontString(nil, "OVERLAY")
			qf:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			qf:SetText("|cff000000Verog the Dervish|r")
			qf:SetTextColor(1, 1, 1)
			quest.__fs = qf
			box.__rows[#box.__rows + 1] = quest
			box.__quest = quest
		end

		function box:GetFrames() return self.__rows end
		-- THE BOX'S OWN ITERATOR, which walks what it is SHOWING rather than a
		-- list somebody took a copy of. ScrollBoxListMixin carries both.
		function box:ForEachFrame(fn)
			for _, row in ipairs(self.__rows) do fn(row) end
		end
		gossip.GreetingPanel.ScrollBox = box

		--- Rebuilding the list, which is what happens on every option you pick.
		--  The rows come back with the client's own ink on them.
		--- A ROW MINTED DURING LAYOUT, which is after Update has returned.
		--
		--  This is the whole shape of the bug. The greeting and every option
		--  are POOLED ELEMENTS of a scroll box, and a scroll box acquires its
		--  frames during layout - so anything that asks GetFrames from inside
		--  an Update hook is answered with the set that was there BEFORE.
		--
		--  The mock used to rebuild the same rows in place, which every
		--  version of the lift survives. It mints one late now.
		function box:MintLate()
			local row = CreateFrame("Button", nil, box)
			row.__fs = row:CreateFontString(nil, "OVERLAY")
			row.__fs:SetTextColor(0.10, 0.10, 0.10)
			function row:GetFontString() return self.__fs end
			box.__rows[#box.__rows + 1] = row
			box.__late = row
		end

		--- THE BOX'S OWN Update, which is where the rows come from.
		--
		--  This is the entry point that matters and the mock did not have it.
		--  GossipFrameSharedMixin:Update builds a data provider and hands it to
		--  SetDataProvider, which assigns it to the view and returns - it
		--  acquires NOTHING. The box takes its frames out of the pool during
		--  its OWN Update, at layout, and that is the only moment a walk of the
		--  rows can be right.
		--
		--  Mocked with the window's Update as the only entry point, a skin
		--  hooked there and re-swept from a zero-length timer passed in here
		--  and was a coin toss in the game.
		function box:Update()
			box:MintLate()
			for _, row in ipairs(box.__rows) do
				row.__fs:SetTextColor(0.10, 0.10, 0.10)
			end
			-- The quest row is refilled through the display format, which puts
			-- the black back INSIDE the text every time.
			box.__quest.__fs:SetText("|cff000000Verog the Dervish|r")
			box.__quest.__fs:SetTextColor(1, 1, 1)
		end

		--- The window's rebuild: new data, and the box left dirty behind it.
		local function reprovide()
			for _, row in ipairs(box.__rows) do
				row.__fs:SetTextColor(0.10, 0.10, 0.10)
			end
			-- LAYOUT IS LATER. The rows are acquired then, not now.
			if C_Timer and C_Timer.After then
				C_Timer.After(0, function() box:Update() end)
			end
		end
		function gossip:UpdateScrollBox() reprovide() end
		function gossip:Update() reprovide() end

		-- GOODBYE, IN THE WINDOW'S BOTTOM RIGHT CORNER, four up from the edge -
		-- which is under the recess and hard against the glass.
		local bye = CreateFrame("Button", nil, gossip.GreetingPanel)
		bye:SetSize(78, 22)
		bye:SetPoint("BOTTOMRIGHT", gossip, "BOTTOMRIGHT", -6, 4)
		bye:SetNormalTexture("panel-button-up")
		local byeText = bye:CreateFontString(nil, "OVERLAY")
		byeText:SetText("Goodbye")
		bye.__fs = byeText
		function bye:GetFontString() return self.__fs end
		gossip.GreetingPanel.GoodbyeButton = bye

		-- A frame of frames, like the community list's.
		local sb = CreateFrame("Frame", nil, gossip.GreetingPanel)
		sb.Track = CreateFrame("Frame", nil, sb)
		sb.Track:CreateTexture(nil, "BACKGROUND"):SetTexture("scroll-track-stone")
		sb.Back = CreateFrame("Button", nil, sb)
		sb.Back:SetNormalTexture("scroll-arrow-up")
		gossip.GreetingPanel.ScrollBar = sb

		-- HOW WELL THIS ONE KNOWS YOU - and DOWN, because almost nobody in the
		-- game keeps track. The client shows it for a handful of NPCs and hides
		-- it for everyone else; a mock that left it up could not tell a row that
		-- costs the body forty-two units from one that costs nothing.
		gossip.FriendshipStatusBar = CreateFrame("StatusBar", nil, gossip)
		gossip.FriendshipStatusBar:SetSize(200, 16)
		gossip.FriendshipStatusBar:SetPoint("TOPLEFT", gossip, "TOPLEFT", 73, -41)
		gossip.FriendshipStatusBar:Hide()
	end

	-- Load on demand: absent until something asks for it.
	-- Builds it only. Firing ADDON_LOADED is the caller's, because `fire` is
	-- declared further down this file than this block runs.
	-- The trainer's insides.
	--
	-- THE SAME ELEVEN BUTTONS ARE BOTH KINDS. The client fills them from one
	-- list: a heading gets a plus or a minus as its NORMAL TEXTURE, a spell
	-- gets ClearNormalTexture and an indented name. So a row that was a heading
	-- a moment ago is a spell after the next refresh, and which it is has to be
	-- read every time rather than remembered - a mock with eleven fixed
	-- headings would let "decide it once" look correct.
	local TRAINER_MOCK_ROWS = 26

	function _G.__buildTrainer()
		local tf = _G.ClassTrainerFrame
		if not tf or tf.__insides then return end
		tf.__insides = true
		tf:SetSize(384, 512)

		-- MORE THAN THE ELEVEN Blizzard's own source declares. This build draws
		-- as many rows as fit, and a sweep that stopped at eleven left every
		-- row below it in Friz - which is what the trainer looked like in game
		-- while this mock was green.
		for i = 1, TRAINER_MOCK_ROWS do
			local b = CreateFrame("Button", "ClassTrainerSkill" .. i, tf)
			b:SetSize(293, 16)
			b:SetID(i)

			-- OFF THE WINDOW, NOT OFF THE LIST. This is a faux scroll frame: the
			-- scroll frame is the BAR and nothing else, and the rows are children
			-- of the window anchored 22 in and 100 down, each chained off the one
			-- above. So moving the list into the recess moves an empty box and
			-- leaves every skill printed on the glass above it - which is what the
			-- trainer looked like while a mock with unanchored rows was green.
			if i == 1 then
				b:SetPoint("TOPLEFT", tf, "TOPLEFT", 22, -100)
			else
				b:SetPoint("TOPLEFT", _G["ClassTrainerSkill" .. (i - 1)],
					"BOTTOMLEFT", 0, 0)
			end

			local fs = b:CreateFontString("ClassTrainerSkill" .. i .. "Text", "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetText("Frostbolt")
			fs:SetTextColor(0.10, 0.10, 0.10)
			b.__fs = fs
			function b:GetFontString() return self.__fs end

			local sub = b:CreateFontString("ClassTrainerSkill" .. i .. "SubText", "BACKGROUND")
			sub:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
			sub:SetText("(Rank 2)")

			-- THE CLIENT ANSWERS GetTexture WITH A FILE ID, not the path it was
			-- handed. Reading the mark off the path passed here and did nothing
			-- in the game, so the mock has to be as unhelpful as the client is.
			local realGet = b.GetNormalTexture
			function b:GetNormalTexture()
				local tex = realGet(self)
				if tex and not tex.__fileID then
					tex.__fileID = true
					local raw = tex.GetTexture
					function tex:GetTexture()
						local v = raw(self)
						if type(v) == "string" then return 137057 end
						return v
					end
				end
				return tex
			end

			-- THE TEMPLATE'S OTHER THREE STATES, which every row carries whether it
			-- is a heading or not - the client only ever clears the NORMAL one. A
			-- mock with a normal texture and nothing else could not show a spell row
			-- lighting up with Blizzard's plus button when you hovered it.
			b:SetHighlightTexture("Interface\\Buttons\\UI-PlusButton-Hilight")
			b:SetDisabledTexture("Interface\\Buttons\\UI-PlusButton-Disabled")

			-- Odd rows are headings this time round, even ones are spells.
			if i % 2 == 1 then
				b:SetNormalTexture("Interface\\Buttons\\UI-MinusButton-Up")
			end
		end

		--- What the client says a row is, which is the only reliable answer.
		function _G.GetTrainerServiceInfo(id)
			if type(id) ~= "number" or id < 1 or id > TRAINER_MOCK_ROWS then return nil end
			if id % 2 == 1 then
				return "Frost", nil, "header", not tf.__collapsedRound
			end
			return "Frostbolt", "Rank 2", "available", nil
		end

		-- THE FILTER, which is the modern dropdown: a stone holder, an arrow and
		-- a label, all regions of the button rather than a normal texture. The
		-- client hangs it 44 in from the frame's right edge, which is inside its
		-- parchment margin and outside our glass.
		local filter = CreateFrame("Button", nil, tf)
		filter:SetSize(130, 24)
		filter:SetPoint("TOPRIGHT", tf, "TOPRIGHT", -44, -67)
		filter.Background = filter:CreateTexture(nil, "BACKGROUND")
		filter.Background:SetTexture("common-dropdown-classic-textholder")
		filter.Arrow = filter:CreateTexture(nil, "OVERLAY")
		filter.Arrow:SetTexture("common-dropdown-classic-a-buttonDown")
		filter.Text = filter:CreateFontString(nil, "OVERLAY")
		filter.Text:SetFont("Fonts\\FRIZQT__.TTF", 10, "")
		filter.Text:SetText("Filter")
		tf.FilterDropdown = filter

		-- THE MENU IS NOT A CHILD OF THE DROPDOWN and does not exist until the
		-- first click. MenuStyle1Mixin:Generate attaches its art to the frame -
		-- an ornate atlas and a black fill beneath it - and the manager pools
		-- the frame, so it comes back later under some other dropdown.
		-- THE CLIENT REDRAWS THE ARROW AND THE TEXT COLOUR on every hover, press
		-- and enable. Dressing them once looked right until the control was
		-- touched, and then the stone arrow was back.
		function filter:OnButtonStateChanged()
			self.Arrow:SetTexture("common-dropdown-classic-a-buttonDown-pressed")
			self.Arrow:SetSize(24, 24)
			self.Text:SetTextColor(1, 1, 1)
		end

		function filter:OpenMenu()
			if not self.menu then
				local menu = CreateFrame("Frame", nil, UIParent)
				menu:SetSize(180, 90)
				menu.__bg = menu:CreateTexture(nil, "BACKGROUND")
				menu.__bg:SetTexture("common-dropdown-classic-bg")
				menu.__fill = menu:CreateTexture(nil, "BACKGROUND")
				menu.__fill:SetTexture("menu-black-fill")

				for _, row in ipairs({ "Available", "Unavailable", "Already Known" }) do
					local fs = menu:CreateFontString(nil, "OVERLAY")
					fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
					fs:SetText(row)

					-- SetFont IS DISALLOWED ON THESE. The menu wraps its own
					-- font strings, and its metatable trips an assert on the
					-- key being READ, never mind called - so a mock that
					-- quietly accepts SetFont here is the one that let twelve
					-- errors a click reach the game.
					fs.SetFont = function()
						error("SetFont is disallowed on a menu font string")
					end
				end
				menu.__firstRow = ({ menu:GetRegions() })[3]
				self.menu = menu
			end
			self.menu:Show()
		end

		-- "All" keeps a flag of its own rather than a service index: 1 when
		-- collapsed, nil when not. Reading its texture instead gave every
		-- trainer a plus on All whatever the tree was doing.
		local all = CreateFrame("Button", "ClassTrainerCollapseAllButton", tf)
		all.collapsed = nil
		all:SetNormalTexture("Interface\\Buttons\\UI-MinusButton-Up")
		local allText = all:CreateFontString(nil, "OVERLAY")
		allText:SetText("All")
		all.__fs = allText
		function all:GetFontString() return self.__fs end

		for _, part in ipairs({ "Left", "Middle", "Right" }) do
			local t = tf:CreateTexture("ClassTrainerExpandTab" .. part, "ARTWORK")
			t:SetTexture("expand-tab-" .. part)
		end

		-- WHICH ROW YOU ARE ON. One frame, slid onto whatever you picked, with
		-- Blizzard's blue listbox slice on it. Absent from this mock entirely, so
		-- nothing could tell a window that marks the selected row from one that
		-- had had the mark stripped off it.
		local hl = CreateFrame("Frame", "ClassTrainerSkillHighlightFrame", tf)
		hl:SetSize(293, 16)
		hl:SetPoint("TOPLEFT", tf, "TOPLEFT", 22, -100)
		hl:CreateTexture("ClassTrainerSkillHighlight", "ARTWORK")
			:SetTexture("Interface\\Buttons\\UI-Listbox-Highlight2")

		-- WHERE THE CLIENT PUTS THEM. The list hangs off the window's TOPRIGHT,
		-- the detail off the list, and your purse off the BOTTOMLEFT corner -
		-- three different corners of a window whose shape we change.
		local tlist = CreateFrame("Frame", "ClassTrainerListScrollFrame", tf)
		tlist:SetSize(296, 184)
		tlist:SetPoint("TOPRIGHT", tf, "TOPRIGHT", -67, -96)
		tlist:CreateTexture(nil, "BACKGROUND"):SetTexture("trainer-stone")

		local tdet = CreateFrame("Frame", "ClassTrainerDetailScrollFrame", tf)
		tdet:SetSize(296, 135)
		tdet:SetPoint("TOPLEFT", tlist, "BOTTOMLEFT", 0, -8)
		tdet:CreateTexture(nil, "BACKGROUND"):SetTexture("trainer-stone")

		local tpurse = CreateFrame("Frame", "ClassTrainerMoneyFrame", tf)
		tpurse:SetSize(120, 14)
		tpurse:SetPoint("BOTTOMRIGHT", tf, "BOTTOMLEFT", 180, 86)
		tpurse:CreateTexture(nil, "BACKGROUND"):SetTexture("trainer-stone")

		local tcost = CreateFrame("Frame", "ClassTrainerDetailMoneyFrame", tf)
		tcost:SetSize(120, 14)
		tcost:SetPoint("TOPLEFT", tdet, "TOPLEFT", 8, -40)
		tcost:CreateTexture(nil, "BACKGROUND"):SetTexture("trainer-stone")

		for _, n in ipairs({ "ClassTrainerListScrollFrameScrollBar",
			"ClassTrainerDetailScrollFrameScrollBar" }) do
			local sb = CreateFrame("Slider", n, tf)
			CreateFrame("Button", n .. "ScrollUpButton", sb):SetNormalTexture("arrow-up")
			CreateFrame("Button", n .. "ScrollDownButton", sb):SetNormalTexture("arrow-down")
		end

		-- Square, 37 by 37, unlike the quest giver's wide rows - so this one
		-- really does want a cell.
		local icon = CreateFrame("Button", "ClassTrainerSkillIcon", tf)
		icon:SetSize(37, 37)
		local iconTex = icon:CreateTexture(nil, "BACKGROUND")
		iconTex:SetTexture("trainer-spell-icon")
		_G.ClassTrainerSkillIconIconTexture = iconTex
		icon:SetNormalTexture("slot-border")

		for _, n in ipairs({ "ClassTrainerNameText", "ClassTrainerGreetingText",
			"ClassTrainerSkillName", "ClassTrainerSkillDescription" }) do
			local fs = tf:CreateFontString(n, "OVERLAY")
			fs:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
			fs:SetText(n)
			fs:SetTextColor(0.10, 0.10, 0.10)     -- printed for parchment
		end

		-- THREE SLICES, NOT A NORMAL TEXTURE. Left, Middle and Right regions, so
		-- ClearButton has nothing to clear and the plate survives it.
		local function pushButton(n, x)
			local b = CreateFrame("Button", n, tf)
			-- 420 DOWN FROM THE WINDOW'S TOPLEFT, which is a fixed offset into a
			-- frame whose height we change - so all three land wherever that
			-- happens to be, which was across the foot of both recesses.
			b:SetSize(80, 22)
			b:SetPoint("CENTER", tf, "TOPLEFT", x, -420)
			for _, slice in ipairs({ "Left", "Middle", "Right" }) do
				b[slice] = b:CreateTexture(nil, "BACKGROUND")
				b[slice]:SetTexture("panel-button-" .. slice:lower())
			end
			local fs = b:CreateFontString(nil, "OVERLAY")
			fs:SetText(n or "Train All")
			b.__fs = fs
			function b:GetFontString() return self.__fs end
			return b
		end

		pushButton("ClassTrainerTrainButton", 224)
		pushButton("ClassTrainerCancelButton", 305)

		-- TRAIN ALL HAS NO NAME. An anonymous child of the window whose label is
		-- ClassTrainerFrameText, so a list of button names never reaches it and
		-- it stayed the client's grey stone on a skinned window.
		local trainAll = pushButton(nil, 138)
		trainAll.__fs.__name = "ClassTrainerFrameText"
		_G.ClassTrainerFrameText = trainAll.__fs
		tf.__trainAll = trainAll

		--- The client refilling the list, which it does on every expand, every
		--  selection and every skill learned - putting its own marks back, and
		--  handing rows from one kind to the other.
		function _G.ClassTrainerFrame_Update()
			tf.__collapsedRound = true
			for i = 1, TRAINER_MOCK_ROWS do
				local b = _G["ClassTrainerSkill" .. i]
				if i % 2 == 1 then
					b:SetNormalTexture("Interface\\Buttons\\UI-PlusButton-Up")
				else
					b:SetNormalTexture(0)
				end
			end
		end
	end

	function _G.__loadPanelAddon(name)
		buildPanel(name)
		if name == "PlayerTalentFrame" then _G.__buildTalentInsides() end
		if name == "CommunitiesFrame" then _G.__buildCommunities() end
		if name == "ClassTrainerFrame" then _G.__buildTrainer() end
	end
end

-- The client's four dialogs.
--
-- TWO NAMING CONVENTIONS, on purpose. The reworked dialog carries its parts as
-- fields and the older one names them globally, and BOTH are live on this
-- client depending which dialog you get - so half of these are built one way
-- and half the other. Anything that knows only one convention skins half the
-- dialogs in the game and looks perfectly correct on the ones it tested.
do
	for i = 1, 4 do
		local p = CreateFrame("Frame", "StaticPopup" .. i, UIParent)
		p:SetSize(320, 90)
		p:Hide()

		-- The stone frame, and the warning triangle.
		p.__border = p:CreateTexture(nil, "BORDER")
		p.__bg = p:CreateTexture(nil, "BACKGROUND")
		-- Art the client keeps hidden and reveals later - a highlight, a glow,
		-- the flash on a timed button. Hidden when a skin first looks at it.
		p.__later = p:CreateTexture(nil, "OVERLAY")
		p.__later:Hide()

		-- THE OPAQUE BACKGROUND. A dialog's backdrop does not live in its own
		-- regions - it hangs off it as a child FRAME, and GetRegions() never
		-- returns one. So a skin can strip every texture the dialog owns, look
		-- entirely correct from a test, and still be solid black on screen.
		local nine = CreateFrame("Frame", (i == 2) and ("StaticPopup" .. i .. "Border") or nil, p)
		nine.__fill = nine:CreateTexture(nil, "BACKGROUND")
		nine.__fill:SetTexture("dialog-background")
		nine.__fill:Show()
		-- Half of them found by field, half by global name, like everything else
		-- about these dialogs.
		if i ~= 2 then p.NineSlice = nine end
		p.__nine = nine
		local alert = p:CreateTexture(nil, "ARTWORK")

		local text = p:CreateFontString(nil, "OVERLAY")
		text:SetText("Do you want to destroy Sunscale Feather?")

		local b1 = CreateFrame("Button", "StaticPopup" .. i .. "Button1", p)
		local b2 = CreateFrame("Button", "StaticPopup" .. i .. "Button2", p)
		for _, b in ipairs({ b1, b2 }) do
			b:SetSize(100, 22)
			-- Through the setters, as the client does: normal art up, pushed and
			-- highlight art present but hidden until you touch it.
			b:SetNormalTexture("dialog-button-up")
			b:SetPushedTexture("dialog-button-down")
			b:SetHighlightTexture("dialog-button-highlight")
			local fs = b:CreateFontString(nil, "OVERLAY")
			fs:SetText("Yes")
			b.__fs = fs
			function b:GetFontString() return self.__fs end
		end

		if i % 2 == 1 then
			-- Fields, the reworked way - and reached through a METATABLE, because
			-- the reworked dialog is a mixin object. Anything using rawget to
			-- find its parts answers nil for every one of them and skins a
			-- dialog with none of its buttons, which is exactly what shipped.
			local parts = { text = text, AlertIcon = alert, Button1 = b1, Button2 = b2 }
			setmetatable(p, { __index = function(_, k) return parts[k] end })
		else
			-- Globals only, the older way.
			_G["StaticPopup" .. i .. "Text"] = text
			_G["StaticPopup" .. i .. "AlertIcon"] = alert
		end
	end
end
--- The panel system putting a window up.
--
--  THE ORDER IS THE WHOLE BUG. This shows the frame - which fires its OnShow -
--  and only THEN places it. So anything told about a window by its OnShow is
--  being told about a frame that is not anywhere yet, and everything measured
--  off it comes back nil. An empty stub could not show that at all.
function ShowUIPanel(frame)
	if type(frame) ~= "table" then return end
	frame.__unplaced = true
	if frame.Show then frame:Show() end
	frame.__unplaced = nil
end

--- BOTH HALVES OF THE PAIR. This one was simply absent, and the client has it:
--  a panel that can be shown and not hidden is a window nobody can close. It
--  hid nothing rather than erroring, because the caller guards with
--  `if HideUIPanel then` - which is the right guard for a global that some
--  flavour might not have, and turns a missing mock into a silent no-op.
function HideUIPanel(frame)
	if type(frame) ~= "table" then return end
	if frame.Hide then frame:Hide() end
end

-- rewards, all selection-scoped: none of these takes an index, which is the
-- whole reason the module moves the cursor once and reads them in one pass.
local function selectedQuest()
	return _G.__visibleLog()[_G.__questSelected or 0]
end

function GetNumQuestLogChoices()
	local q = selectedQuest()
	return (q and q.choices) and #q.choices or 0
end
function GetQuestLogChoiceInfo(i)
	local q = selectedQuest()
	local r = q and q.choices and q.choices[i]
	if not r then return nil end
	-- name, texture, numItems, quality, isUsable
	return r[1], r[2], r[3] or 1, r[4] or 1, r[5] ~= false
end
function GetNumQuestLogRewards()
	local q = selectedQuest()
	return (q and q.rewards) and #q.rewards or 0
end
function GetQuestLogRewardInfo(i)
	local q = selectedQuest()
	local r = q and q.rewards and q.rewards[i]
	if not r then return nil end
	return r[1], r[2], r[3] or 1, r[4] or 1, r[5] ~= false
end
function GetQuestLogRewardMoney()
	local q = selectedQuest()
	return (q and q.money) or 0
end
function GetQuestLogRequiredMoney()
	local q = selectedQuest()
	return (q and q.required) or 0
end

--- Returns nil for an item the client has not cached, which is a real and
--- frequently-hit case on this client rather than a theoretical one.
_G.__uncachedRewards = false
function GetQuestLogItemLink(kind, i)
	if _G.__uncachedRewards then return nil end
	local q = selectedQuest()
	local list = q and ((kind == "choice") and q.choices or q.rewards)
	local r = list and list[i]
	if not r then return nil end
	return "|cffffffff|Hitem:" .. (r[6] or 1) .. "::::::::1:::|h[" .. r[1] .. "]|h|r"
end

