_G.__raidTargets = {}
function GetRaidTargetIndex(u) return _G.__raidTargets[u] end

--- Marking acts on a UNIT, and ZERO is how a mark is taken off.
--
--  The index is REQUIRED. The client's own usage is SetRaidTarget(unit,
--  index) and leaving it out is an error, not a clear - so a Clear button
--  that passed nothing would raise rather than quietly leaving the mark, and
--  a mock that folded nil into 0 would call that correct.
function SetRaidTarget(u, index)
	_G.__partyCalls.marks = _G.__partyCalls.marks + 1
	if type(index) ~= "number" then
		fail("SetRaidTarget(unit, index) needs an index - got " .. tostring(index))
		return
	end
	if index == 0 then
		_G.__raidTargets[u] = nil
	else
		_G.__raidTargets[u] = index
	end
end

--- The game's own icon sheet. Sets a texture AND a texcoord, both of which
--  an addon that drew its own marker would get wrong - so the mock records
--  them and the checks can say the skull is still Blizzard's skull.
function SetRaidTargetIconTexture(tex, index)
	if not tex or not index then return end
	tex:SetTexture("Interface\\TargetingFrame\\UI-RaidTargetingIcons")
	local c, r = (index - 1) % 4, math.floor((index - 1) / 4)
	tex:SetTexCoord(c * 0.25, (c + 1) * 0.25, r * 0.25, (r + 1) * 0.25)
end

function GetNumGroupMembers()
	local n = 0
	for _, u in ipairs({ "party1", "party2", "party3", "party4" }) do
		if units[u] and units[u].exists then n = n + 1 end
	end
	return n > 0 and n + 1 or 0
end
function GetNumSubgroupMembers() return math.max(0, GetNumGroupMembers() - 1) end
function UnitInParty(u) return units[u] ~= nil and units[u].exists or false end

function UnitIsDND(u) return units[u] and units[u].dnd or false end

local castState
function UnitCastingInfo(u)
	if u ~= "player" or not castState or castState.channel then return nil end
	return castState.name, castState.name, castState.icon, castState.startTime, castState.endTime
end
function UnitChannelInfo(u)
	if u ~= "player" or not castState or not castState.channel then return nil end
	return castState.name, castState.name, castState.icon, castState.startTime, castState.endTime
end

-- The addon list is a SUPERSET of the actionable one: most addons offer neither
-- an LDB launcher nor a minimap button. Only about half declare ## IconTexture
-- either - 13 of the 24 installed on the machine this was written against - so
-- the mock deliberately gives some an icon and some none.
_G.__addons = {
	{ name = "Questie",     title = "Questie",        icon = "Interface\\Icons\\INV_Misc_Map01" },
	{ name = "TomTom",      title = "TomTom" },
	{ name = "PlainAddon",  title = "Plain Addon" },
	{ name = "OtherPlain",  title = "Other Plain" },
}

--- The version, read from the REAL AetherUI.toc.
--
--  This was the literal "0.1.0", and it was a mock telling a different story
--  from the client: A.version is what GetAddOnMetadata hands back, everything
--  downstream of it - the What's new card, the version chip, which changelog
--  entry is current, what the unread dot is remembered against - is keyed on
--  that, and every one of those was being checked against a number the harness
--  had chosen for itself. Bump the .toc and the suite would have carried on
--  agreeing with itself about a version nobody was running.
local TOC_VERSION = (function()
	local f = io.open("AetherUI.toc", "r")
	if not f then return "0.0.0" end
	for line in f:lines() do
		local v = line:match("^##%s*Version:%s*(%S+)")
		if v then f:close() return v end
	end
	f:close()
	return "0.0.0"
end)()

C_AddOns = {
	GetAddOnMetadata = function(which, field)
		if field == "IconTexture" then
			for _, a in ipairs(_G.__addons) do
				if a.name == which then return a.icon end
			end
			return nil
		end
		return TOC_VERSION
	end,
	GetNumAddOns  = function() return #_G.__addons end,
	GetAddOnInfo  = function(i)
		local a = _G.__addons[i]
		if not a then return nil end
		return a.name, a.title
	end,
	IsAddOnLoaded = function(i) return _G.__addons[i] ~= nil end,
}

-- ---------------------------------------------------------------------------
-- loading
-- ---------------------------------------------------------------------------

local ADDON = "AetherUI"
local A = {}

--- FATAL, not counted.
--
--  A file that does not parse means the addon does not load AT ALL in game -
--  the client stops at the .toc line and nothing after it exists. Recording that
--  as one failure among many and carrying on is worse than useless: the rest of
--  the suite then interrogates a half-built addon and dies somewhere unrelated
--  on a nil index, which is the thing you end up debugging instead of the typo.
--
--  Both halves are fatal. A file that parses but raises while loading leaves the
--  same hole.
local function load(path)
	local function dead(what, err)
		print("")
		print("!! " .. path .. " " .. what)
		print("   " .. tostring(err))
		print("")
		print("   The addon would not load in game. Nothing after this point is")
		print("   meaningful, so the run stops here.")
		os.exit(1)
	end

	local chunk, err = loadfile(path)
	if not chunk then dead("DOES NOT PARSE", err) end
	local ok, e = pcall(chunk, ADDON, A)
	if not ok then dead("RAISED WHILE LOADING", e) end
end

-- real libs, so the AceDB defaults merge is exercised for real
load("Libs/LibStub/LibStub.lua")
load("Libs/CallbackHandler-1.0/CallbackHandler-1.0.lua")
load("Libs/AceDB-3.0/AceDB-3.0.lua")
-- The REAL LibDataBroker, not a stand-in, and deliberately so: its whole
-- character is the metatable that puts every field in `attributestorage` behind
-- an __index and declares the metatable "access denied". A mock that stored
-- fields on the table would be the one shape in which `pairs(dataobj)` works -
-- and that bug, which is the easiest one to write against this library, could
-- then never be caught here. Ninety lines; loading it costs nothing.
load("Libs/LibDataBroker-1.1/LibDataBroker-1.1.lua")

-- The REAL AceGUI core, for the same reason: the skin picker is registered as
-- an AceGUI widget, and a stand-in would let it meet an interface we invented
-- rather than the one AceConfigDialog actually calls. Only the core file - the
-- shipped widgets are AceConfigDialog's business, not ours.
load("Libs/AceGUI-3.0/AceGUI-3.0.lua")
-- And the widgets our options panel is actually built from. Real ones, so the
-- skinning module meets the frames and field names the library really makes
-- rather than a set invented to match it.
for _, w in ipairs({
	"Widget-Button", "Widget-CheckBox", "Widget-Slider", "Widget-EditBox",
	"Widget-Heading", "Widget-Label", "Widget-DropDown-Items", "Widget-DropDown",
	"Container-SimpleGroup", "Container-InlineGroup", "Container-TreeGroup",
	"Container-Frame", "Container-ScrollFrame",
}) do
	load("Libs/AceGUI-3.0/widgets/AceGUI" .. w .. ".lua")
end

-- LibClassicCasterino bails on any non-Classic client, and the mock is not one,
-- so stand in for it. The point under test is our wiring, not the library.
WOW_PROJECT_ID, WOW_PROJECT_CLASSIC = 2, 2
do
	local lib = LibStub:NewLibrary("LibClassicCasterino", 37)
	lib.callbacks = LibStub("CallbackHandler-1.0"):New(lib)
	_G.__ccCasts = {}
	function lib:UnitCastingInfo(unit)
		local c = _G.__ccCasts[unit]
		if c and not c.channel then return c.name, nil, c.icon, c.start, c.finish end
	end
	function lib:UnitChannelInfo(unit)
		local c = _G.__ccCasts[unit]
		if c and c.channel then return c.name, nil, c.icon, c.start, c.finish end
	end
    _G.__ccFire = function(event, unit) lib.callbacks:Fire(event, unit) end
end

-- A stand-in LibDBIcon, because the real one belongs to whichever addon on the
-- machine shipped a copy. Only the surface the module actually uses.
do
	local ldbi = LibStub:NewLibrary("LibDBIcon-1.0", 56)
	ldbi.objects = {}
	ldbi.callbacks = LibStub("CallbackHandler-1.0"):New(ldbi)
	function ldbi:GetButtonList()
		local out = {}
		for name in pairs(self.objects) do out[#out + 1] = name end
		table.sort(out)
		return out
	end
	function ldbi:GetMinimapButton(name) return self.objects[name] end
	function ldbi:IsRegistered(name) return self.objects[name] ~= nil end
	function ldbi:Lock(name)
		local b = self.objects[name]
		if b then b.__locked = true end
	end
	--- Register an LDB object the way an addon would.
	--
	--  `kind` is "launcher" or "data source"; only the first is an addon entry.
	--  Returns the dataobj, whose fields are NOT on the table - see the note on
	--  the load above.
	function _G.__makeLDB(name, kind, fields)
		local ldb = LibStub("LibDataBroker-1.1")
		local t = { type = kind or "launcher", icon = [[Interface\Icons\INV_Misc_Gear_01]] }
		for k, v in pairs(fields or {}) do t[k] = v end
		return ldb:NewDataObject(name, t)
	end

	--- Make one the way an addon would, and announce it.
	--- What Leatrix Plus (and anything else with a "hide addon buttons" option)
	--  calls. Setting the flag is not enough on its own - the library also drops
	--  the button to alpha 0 there and then, which is what makes it look like
	--  the button was never laid out.
	function ldbi:ShowOnEnter(n, value)
		local b = ldbi.objects[n]
		if not b then return end
		b.showOnMouseover = value and true or false
		b.fadeOut:Stop()
		b:SetAlpha(value and 0 or 1)
	end

	--- ...and what its handlers do on the way out: every button, not just this
	--  one, which is why hovering anything at all took ours away again.
	function ldbi:__mouseLeftEverything()
		for _, b in pairs(ldbi.objects) do
			if b.showOnMouseover then b.fadeOut:Play() end
		end
	end

	function _G.__makeDBIcon(name)
		local b = CreateFrame("Button", "LibDBIcon10_" .. name, Minimap)
		b:SetSize(31, 31)
		-- The real library pins both, so that reparenting cannot shuffle its
		-- buttons behind something. It also means an outside SetFrameStrata is
		-- quietly refused until the pin is released.
		b:SetFrameStrata("MEDIUM")
		b:SetFrameLevel(8)
		b.__fixedStrata, b.__fixedLevel = true, true
		-- the real library gives every button these three, by name
		b.icon = b:CreateTexture(nil, "ARTWORK")
		b.border = b:CreateTexture(nil, "OVERLAY")
		b.background = b:CreateTexture(nil, "BACKGROUND")
		b:SetScript("OnDragStart", function() end)
		b:SetScript("OnDragStop", function() end)
		-- The fade the library gives every button, and the flag that gates it.
		-- Any addon can turn the flag on for the whole registry - Leatrix Plus's
		-- "Hide addon buttons" does - and the library's own handlers then walk
		-- EVERY button in lib.objects rather than the one under the cursor.
		b.showOnMouseover = false
		b.fadeOut = {
			Play = function(self) self.__playing = true; b:SetAlpha(0) end,
			Stop = function(self) self.__playing = false end,
		}
		ldbi.objects[name] = b
		ldbi.callbacks:Fire("LibDBIcon_IconCreated", b, name)
		return b
	end
end



-- chat -----------------------------------------------------------------------
--
-- Enough of Blizzard's chat furniture to skin. The names matter: CHAT_FRAMES
-- holds name *strings*, the backdrop regions are `<frame><suffix>` globals, and
-- the tab art has global names that do not match its parentKeys - all three are
-- things Modules/Chat.lua has to get right and all three are silent when wrong.
--- THE REAL LIST, not the nine textures this mock used to carry.
--
--  Blizzard's own CHAT_FRAME_TEXTURES reaches past the backdrop into the button
--  frame's furniture, and Modules/Chat.lua walks it with Kill() - which is Hide
--  plus SetTexture(nil) plus SetAlpha(0). A mock holding only the nine obvious
--  ones meant the resize grip was never killed in here, so the suite could not
--  see a grip that came back Shown and transparent.
CHAT_FRAME_TEXTURES = {
	"Background",
	"TopLeftTexture", "BottomLeftTexture", "TopRightTexture", "BottomRightTexture",
	"LeftTexture", "RightTexture", "BottomTexture", "TopTexture",
	"ButtonFrameBackground",
	"ButtonFrameTopLeftTexture", "ButtonFrameBottomLeftTexture",
	"ButtonFrameTopRightTexture", "ButtonFrameBottomRightTexture",
	"ButtonFrameLeftTexture", "ButtonFrameRightTexture",
	"ButtonFrameBottomTexture", "ButtonFrameTopTexture",
	"ResizeButton",
}
CHAT_FRAMES = {}

GeneralDockManager = CreateFrame("Frame", "GeneralDockManager")
-- 26, from DockManagerTemplate `<Size x="0" y="26"/>`. The tabs inside it are
-- TALLER than it is - see MakeChatFrame - and the difference is exactly what
-- the pill geometry has to survive.
GeneralDockManager:SetSize(400, 26)
-- A FRAME, not an index. Blizzard's FCFDock_SelectWindow ends with
-- `dock.selected = chatFrame` and FCFDock_GetSelectedWindow hands it straight
-- back. Modelling it as a number let `dock.selected == tab:GetID()` pass here
-- and be false in the game for weeks - the selected chat tab simply never lit
-- up, and nothing offline could see it. Assigned below, once ChatFrame1 exists.
GeneralDockManager.selected = nil
GeneralDockManager.DOCKED_CHAT_FRAMES = {}

-- Modelled the way Blizzard actually ships it on Classic Era, because the shape
-- of it is the bug. The real function is a *mixin method*, copied onto every edit
-- box when the frame is created; the familiar `ChatEdit_UpdateHeader` global is a
-- dead snapshot taken once at load in Blizzard_DeprecatedChatInfo and is never
-- called by anything. Hooking that global installs cleanly, fires never, and
-- reports nothing - which is exactly how two attempts at this silently did
-- nothing at all.
ChatFrameEditBoxMixin = {}
function ChatFrameEditBoxMixin:UpdateHeader()
	self.header:SetText("Say:")
	self.header:SetAlpha(1)
	self:SetTextInsets(46, 0, 0, 0)
end
ChatEdit_UpdateHeader = ChatFrameEditBoxMixin.UpdateHeader

local function MakeChatFrame(id)
	local name = "ChatFrame" .. id
	local f = CreateFrame("Frame", name, UIParent)
	f:SetSize(430, 180)
	f.__id = id
	function f:GetID() return self.__id end
	function f:SetFading(v) self.__fading = v end
	function f:SetTimeVisible(v) self.__timeVisible = v end
	function f:SetFont(path, size, flags)
		self.__font = { path, size, flags }
	end
	function f:GetFont() return (self.__font or {})[1], (self.__font or {})[2] or 13 end
	function f:SetShadowColor() end
	function f:SetShadowOffset() end

	for _, suffix in ipairs(CHAT_FRAME_TEXTURES) do
		local t = f:CreateTexture(name .. suffix)
		_G[name .. suffix] = t
	end

	f.ScrollToBottomButton = CreateFrame("Button", nil, f)
	f.buttonFrame = CreateFrame("Frame", name .. "ButtonFrame", f)
	_G[name .. "ButtonFrame"] = f.buttonFrame
	-- WHERE THE GRIP LIVES IS NOT THE SAME ON EVERY CLIENT, and this mock only
	-- ever modelled the easy layout - a child of the chat frame, with the
	-- obvious global. The other one hangs it off the button frame, which is the
	-- frame ParkButtons moves to -10000 and clips, so the grip goes with it and
	-- there is no way to resize the window at all.
	--
	-- __gripInButtonFrame switches between them, so the awkward layout is a
	-- thing the suite can actually run rather than a thing to reason about.
	if _G.__gripInButtonFrame then
		f.ResizeButton = nil
		local g = CreateFrame("Button", name .. "ButtonFrameResizeButton", f.buttonFrame)
		f.buttonFrame.ResizeButton = g
		_G[name .. "ButtonFrameResizeButton"] = g
		_G[name .. "ResizeButton"] = nil
	else
		f.ResizeButton = CreateFrame("Button", name .. "ResizeButton", f)
		_G[name .. "ResizeButton"] = f.ResizeButton
	end

	local tab = CreateFrame("Button", name .. "Tab", GeneralDockManager)
	-- 32, from ChatTabArtTemplate `<Size x="64" y="32"/>`; nothing in the client
	-- ever changes it (PanelTemplates_TabResize sets width only). The mock left
	-- it at 0, so a pill anchored to the tab's corners measured 0 - 4 here and
	-- 32 - 4 in game, and the harness could not see the slab that produced.
	tab:SetHeight(32)
	tab.__id = id
	function tab:GetID() return self.__id end
	for _, set in ipairs({ "", "Selected", "Highlight" }) do
		for _, piece in ipairs({ "Left", "Middle", "Right" }) do
			_G[name .. "Tab" .. set .. piece] = tab:CreateTexture()
		end
	end
	_G[name .. "TabGlow"] = tab:CreateTexture()
	_G[name .. "TabFlash"] = tab:CreateTexture()
	local txt = tab:CreateFontString(name .. "TabText")
	-- `<ButtonText name="$parentText"><Size x="50" y="8"/>` - the template gives
	-- the label a fixed rect, and nothing in the client ever clears the height.
	-- The mock started it at 0 (auto), which is the one state where "is the
	-- label's rect the size of its own text?" answers yes for free.
	txt:SetSize(50, 8)
	txt:SetText("Chat " .. id)
	-- AND IT ARRIVES WITH A SHADOW ON IT. ChatTabArtTemplate's label inherits
	-- GameFontNormalSmall, which inherits SystemFont_Shadow_Small - a hard
	-- black shadow that SetFont does not clear. A mock whose labels start
	-- with none agrees that any amount of not clearing it is fine, which is
	-- how a black halo under pale type on glass would ship.
	txt:SetShadowColor(0, 0, 0, 1)
	txt:SetShadowOffset(1, -1)
	_G[name .. "TabText"] = txt
	function tab:GetFontString() return txt end

	-- The real one is a ScrollingMessageFrame method that Modules/Chat.lua wraps
	-- to take Blizzard's channel bracket off the front of a finished line, so it
	-- has to exist before the addon loads.
	f.__lines = {}
	-- The signature matters: the handler calls
	-- `self:AddMessage(outMsg, info.r, info.g, info.b, info.id, ...)`, and that
	-- id is the only thing that says what a finished line *is*. Modules/Chat.lua
	-- reads it to dim system lines without touching a single event argument.
	function f:AddMessage(text, r, g, b, id)
		-- The body colour arrives as arguments, not in the string. Recorded so a
		-- test can see what the skin did to it.
		self.__lastColor = { r, g, b }
		self.__last = text
		self.__lastID = id
		self.__lines[#self.__lines + 1] = text
	end
	function f:Clear() self.__lines = {} end

	-- Message groups are *methods* on Classic Era; the familiar
	-- ChatFrame_AddMessageGroup globals are aliases in
	-- Blizzard_DeprecatedChatInfo, behind a cvar, and are deliberately not
	-- defined anywhere in this harness for exactly that reason.
	f.__groups = {}
	function f:AddMessageGroup(g) self.__groups[g] = true end
	function f:RemoveMessageGroup(g) self.__groups[g] = nil end
	function f:ContainsMessageGroup(g) return self.__groups[g] == true end
	function f:RemoveAllMessageGroups() self.__groups = {} end
	function f:RemoveAllChannels() end
	function f:ReceiveAllPrivateMessages() end

	local eb = CreateFrame("EditBox", name .. "EditBox", f)
	eb.__attrs = {}
	function eb:GetAttribute(k) return self.__attrs[k] end
	function eb:SetAttribute(k, v) self.__attrs[k] = v end
	function eb:GetText() return self.__text or "" end
	function eb:SetTextInsets() end
	function eb:SetFont(path, size, flags) self.__font = { path, size, flags } end
	eb:SetAttribute("chatType", "CHANNEL")
	-- Hidden until you press Enter, as the client's are: ChatEdit_ActivateChat
	-- shows one and ChatEdit_DeactivateChat hides it again. Shown-by-default
	-- meant every edit box in the harness claimed to be the focused one, so the
	-- composer's "which window is this for?" question was never actually asked.
	eb:Hide()
	for _, suffix in ipairs({ "Left", "Right", "Mid",
		"FocusLeft", "FocusRight", "FocusMid" }) do
		_G[name .. "EditBox" .. suffix] = eb:CreateTexture()
	end
	for k, v in pairs(ChatFrameEditBoxMixin) do eb[k] = v end   -- XML mixin= copy
	function eb:ClearHistory() end
	eb.header = eb:CreateFontString(name .. "EditBoxHeader")
	eb.prompt = eb:CreateFontString(name .. "EditBoxPrompt")
	eb.header:SetText("Say:")
	function eb:SetTextInsets(l) self.__insetL = l end
	f.editBox = eb

	-- Docked is the default, and it is what decides whether this window's edit
	-- box capsule belongs on the shared panel or on the window itself.
	f.isDocked = true

	-- PrimaryChatFrameMixin:OnLoad sets this on ChatFrame1 and nothing ever
	-- clears it, so ChatFrame1's tab is parented to the dock for the life of the
	-- session and every other tab lives in the dock's scroll child. It also
	-- decides which PanelTemplates_TabResize call a tab gets - and therefore
	-- whether its label ends up pinned to a hard width.
	f.isStaticDocked = (id == 1) or nil

	-- The general window subscribes to whispers by default, which is the thing
	-- the whispers tab moves off it.
	if id == 1 then
		for _, g in ipairs({ "SAY", "YELL", "GUILD", "PARTY", "CHANNEL",
			"WHISPER", "BN_WHISPER" }) do
			f.__groups[g] = true
		end
	end

	CHAT_FRAMES[#CHAT_FRAMES + 1] = name
	GeneralDockManager.DOCKED_CHAT_FRAMES[#GeneralDockManager.DOCKED_CHAT_FRAMES + 1] = f
	return f
end

-- The mirror timers: breath underwater, fatigue at sea, feigning death.
--
-- Three frames the client reuses, and it picks whichever is FREE when a timer
-- starts - so the one that appears is not necessarily the one that appeared
-- last time, and all three have to be dressed.
--
-- MirrorTimer_Show re-colours the bar from MirrorTimerColors on every single
-- start, which is what makes a colour set once at login a colour you see until
-- the first time you go underwater.
_G.MIRRORTIMER_NUMTIMERS = 3
MirrorTimerColors = {
	EXHAUSTION = { r = 1.00, g = 0.90, b = 0.00 },
	BREATH     = { r = 0.00, g = 0.50, b = 1.00 },
	DEATH      = { r = 1.00, g = 0.70, b = 0.00 },
	FEIGNDEATH = { r = 1.00, g = 0.70, b = 0.00 },
}

for i = 1, 3 do
	local f = CreateFrame("Frame", "MirrorTimer" .. i, UIParent)
	f:SetSize(206, 26)
	f:Hide()

	-- A flat black plate behind the fill, and the casting bar's border laid
	-- over the top. Both are regions of the frame itself.
	f.__plate = f:CreateTexture(nil, "BACKGROUND")
	f.__plate:SetTexture("mirror-plate")
	f.__border = f:CreateTexture("MirrorTimer" .. i .. "Border", "OVERLAY")
	f.__border:SetTexture("Interface\\CastingBar\\UI-CastingBar-Border")

	local text = f:CreateFontString("MirrorTimer" .. i .. "Text", "OVERLAY")
	text:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
	text:SetText("Breath")
	-- ANCHORED TO THE TOP OF THE FRAME, which puts it half above the fill: it
	-- sat on a stone border that framed the words, and once that has gone the
	-- top half of them is over open water.
	text:SetPoint("TOP", f, "TOP", 0, 0)

	local bar = CreateFrame("StatusBar", "MirrorTimer" .. i .. "StatusBar", f)
	bar:SetSize(195, 13)
	bar:SetPoint("TOP", f, "TOP", 0, -2)
	bar:SetStatusBarTexture("Interface\\TargetingFrame\\UI-StatusBar")
	-- LowerFrameLevel(self), which the template really does call in this bar's
	-- OnLoad. It is why glass put behind the frame is drawn over the top of the
	-- fill, and a mock that left every frame on the same level could not show
	-- it - the bar would come out above the capsule by accident.
	bar:SetFrameLevel(0)
end

--- The client starting a timer: pick a free frame, colour it, show it.
function MirrorTimer_Show(timer, value, maxvalue, scale, paused, label)
	local dialog
	for i = 1, _G.MIRRORTIMER_NUMTIMERS do
		local f = _G["MirrorTimer" .. i]
		if not f:IsShown() then dialog = f break end
	end
	if not dialog then return nil end

	dialog.timer = timer
	_G[dialog:GetName() .. "Text"]:SetText(label)

	local bar = _G[dialog:GetName() .. "StatusBar"]
	bar:SetMinMaxValues(0, (maxvalue or 1000) / 1000)
	bar:SetValue((value or 0) / 1000)

	-- THE COLOUR, BLIZZARD'S, every time. This is the line that undoes us.
	local c = MirrorTimerColors[timer]
	if c then bar:SetStatusBarColor(c.r, c.g, c.b) end

	dialog:Show()
	return dialog
end

MakeChatFrame(1)
MakeChatFrame(2)

GeneralDockManager.selected = _G.ChatFrame1

-- CHATFRAME1 IS AN EDIT MODE SYSTEM, and Edit Mode is what has been moving it.
--
-- Four fixes went at the FCF dock before a stack trace named the real owner:
-- EditModeSystemTemplates.lua:375, ApplySystemAnchor. Edit Mode registers the
-- chat window as Enum.EditModeSystem.ChatFrame, swaps its SetPoint for
-- SetPointOverride, and re-applies its own saved anchor at login - first
-- resetting every system to TOPLEFT 0,0, then placing this one at its preset
-- BOTTOMLEFT 35,110. Both of those numbers came back in the report.
--
-- The override matters as much as the anchor: anything else calling SetPoint on
-- a managed frame tells the manager its layout has unsaved changes. Restoring
-- our own position through it marks somebody else's saved layout dirty every
-- time. SetPointBase is the widget's own method, which Edit Mode keeps for
-- exactly this reason.
do
	local cf = _G.ChatFrame1
	cf.SetPointBase = cf.SetPoint
	cf.ClearAllPointsBase = cf.ClearAllPoints

	_G.__editModeDirty = 0
	function cf:SetPoint(...)
		_G.__editModeDirty = _G.__editModeDirty + 1
		return self.SetPointBase(self, ...)
	end
	function cf:ClearAllPoints(...)
		_G.__editModeDirty = _G.__editModeDirty + 1
		return self.ClearAllPointsBase(self, ...)
	end

	--- What Edit Mode does at login, in the order the report caught it doing it.
	function _G.__editModeApplyLayout()
		cf:ClearAllPoints()
		cf:SetPoint("TOPLEFT", UIParent, "TOPLEFT", 0, 0)
		cf:ClearAllPoints()
		cf:SetPoint("BOTTOMLEFT", UIParent, "BOTTOMLEFT", 35, 110)
	end
end

--- id, name, instanceID. ChannelLabel takes the second return.
function GetChannelName(target)
	return 1, "General", 0
end

function FCF_GetChatWindowInfo(id)
	return "Chat " .. tostring(id), 14, 1, 1, 1, 1, true, false, true, false
end
-- The second argument is not decoration. The real one is how the client says
-- "this tab is the selected one", and it is correct for undocked windows that
-- are not in the dock at all. A stub that dropped it meant the module's hook
-- could take it or ignore it with no test able to tell the difference.
function FCFTab_UpdateColors(tab, selected)
	if tab then tab.__blizzSelected = selected end
end

-- NOT a no-op. It was one, defined below the real implementation and quietly
-- overwriting it, so the dock's selection never moved in the harness and the
-- selected-tab highlight could not be tested at all. A stub that shadows a real
-- mock is worse than no stub.
--
-- Like the client's, this walks the docked tabs and colours each one, so the
-- module's per-tab hook actually runs.
-- Blizzard's own tab sizer, SharedUIPanelTemplates.lua:357. The parts that
-- matter to an addon, and they are the parts the harness was missing entirely:
-- it OVERWRITES the tab's width, and for any tab given an absoluteSize it pins
-- the label to a hard width of `absoluteSize - sideWidths`. A FontString with a
-- hard width narrower than its text wraps, and its rect stops being the size of
-- the words in it - which is how a label anchored CENTER ends up off-centre.
--
-- FCFDock_CalculateTabSize clamps absoluteSize to 60..90 (MIN_SIZE, MAX_SIZE),
-- so the pinned label width is 28..58.
local TAB_SIDE_WIDTHS = 32
function PanelTemplates_TabResize(tab, padding, absoluteSize)
	local text = tab.GetFontString and tab:GetFontString()
	if not text then return end

	local width, tabWidth
	if absoluteSize then
		width = math.max(1, absoluteSize - TAB_SIDE_WIDTHS)
		tabWidth = math.max(absoluteSize, TAB_SIDE_WIDTHS)
		text:SetWidth(width)
	else
		text:SetWidth(0)
		width = text:GetStringWidth() + (padding or 24)
		tabWidth = width + TAB_SIDE_WIDTHS
		text:SetWidth(0)
	end
	tab:SetWidth(tabWidth)
end

function FCFDock_UpdateTabs(dock)
	dock = dock or _G.GeneralDockManager
	for _, id in ipairs(_G.CHAT_FRAMES or {}) do
		local f = type(id) == "string" and _G[id] or id
		local tab = f and f.GetName and _G[f:GetName() .. "Tab"]
		-- The client walks dock.DOCKED_CHAT_FRAMES, so undocked windows are
		-- simply absent - it does not test a field. `isDocked` truthiness is the
		-- closest this mock gets, and it has to be truthiness: the client writes
		-- `1` or `nil` and never `false`.
		if tab and f.isDocked then
			-- Order matters and it is the client's: ClearAllPoints, colour (which
			-- is where our hook runs), THEN resize. So Blizzard's width is
			-- written after the module has already styled the tab, and only the
			-- SkinAllTabs at the end of this function gets the last word.
			tab:ClearAllPoints()
			FCFTab_UpdateColors(tab, dock.selected == f)
			if f.isStaticDocked then
				-- ChatFrame1's tab: no absoluteSize, so the label keeps auto-width.
				PanelTemplates_TabResize(tab, tab.sizePadding or 0)
			else
				-- Everything else: FCFDock_CalculateTabSize's answer, which pins
				-- the label's width.
				PanelTemplates_TabResize(tab, tab.sizePadding or 0, 60)
			end
			tab:SetPoint("LEFT", dock, "LEFT", 0, 0)
		end
	end
end
-- The selection really moves, because the whole point is that `dock.selected`
-- is a frame and the module has to resolve it to an id. The trailing
-- UpdateTabs is the client's (FloatingChatFrame.lua) and it matters: it is what
-- makes the per-tab colour hook run, and therefore what decides whether the
-- module's own SkinAllTabs wipes the flags that hook just set.
function FCFDock_SelectWindow(dock, chatFrame)
	dock.selected = chatFrame
	FCFDock_UpdateTabs(dock)
end
function FCFDock_GetSelectedWindow(dock) return dock.selected end
function FloatingChatFrame_Update() end
function FCF_SetChatWindowFontSize() end
function FCF_OpenTemporaryWindow() end
function FCF_SetButtonSide() end
function FCF_FadeInChatFrame() end

-- ---------------------------------------------------------------------------
-- the message lines
--
-- Modelled on Blizzard_ChatFrameBase, not invented, because the whole point of
-- the line work is *where* each piece of a line is assembled - and a mock that
-- puts the pieces together in a different order would prove nothing about the
-- addon that runs against the real one.
--
--   Shared/ChatFrameFilters.lua   the two filter registries
--   Shared/ChatFrameUtil.lua      GetDecoratedSenderName, GetOutMessageFormatKey
--   Classic/ChatFrameOverrides.lua  the handler that puts a line together
-- ---------------------------------------------------------------------------

ChatFrameUtil = {}

do
	local senderFilters, eventFilters = {}, {}

	function ChatFrameUtil.AddSenderNameFilter(cb)
		for _, f in ipairs(senderFilters) do if f == cb then return end end
		senderFilters[#senderFilters + 1] = cb
	end

	function ChatFrameUtil.RemoveSenderNameFilter(cb)
		for i, f in ipairs(senderFilters) do
			if f == cb then table.remove(senderFilters, i) return end
		end
	end

	--- Faithful to the real one in the way that matters: a callback returning
	--  nil leaves the name alone rather than blanking it, and the chain carries
	--  the running value forward.
	function ChatFrameUtil.ProcessSenderNameFilters(event, name, ...)
		for _, cb in ipairs(senderFilters) do
			local ok, replacement = pcall(cb, event, name, ...)
			if ok and replacement ~= nil then name = replacement end
		end
		return name
	end

	function ChatFrameUtil.AddMessageEventFilter(event, cb)
		eventFilters[event] = eventFilters[event] or {}
		local list = eventFilters[event]
		for _, f in ipairs(list) do if f == cb then return end end
		list[#list + 1] = cb
	end

	function ChatFrameUtil.RemoveMessageEventFilter(event, cb)
		local list = eventFilters[event]
		if not list then return end
		for i, f in ipairs(list) do if f == cb then table.remove(list, i) return end end
	end

	function ChatFrameUtil.ProcessMessageEventFilters(frame, event, ...)
		local args = { ... }
		local n = select("#", ...)
		for _, cb in ipairs(eventFilters[event] or {}) do
			local out = { pcall(cb, frame, event, unpack(args, 1, n)) }
			if out[1] then
				if out[2] then return true end            -- discard, stop the chain
				if out[3] ~= nil then
					for i = 1, n do args[i] = out[i + 2] end
				end
			end
		end
		return false, unpack(args, 1, n)
	end

	function ChatFrameUtil.GetSenderNameFilters() return senderFilters end
end

--- Reads _G["CHAT_"..subtype.."_GET"] and asserts the key exists, which is why
--  Modules/Chat.lua reshapes these strings rather than clearing them.
function ChatFrameUtil.GetOutMessageFormatKey(subtype)
	local key = _G["CHAT_" .. subtype .. "_GET"]
	if key == nil then fail("no CHAT_" .. subtype .. "_GET") end
	return key or ""
end

function ChatFrameUtil.ResolvePrefixedChannelName(name) return name end

--- The order here is the fact the whole module leans on: Blizzard class-colours
--  the name, *then* runs the sender-name filters, and only afterwards does the
--  caller wrap the result in a player link. So a filter's return value becomes
--  link display text and never the link target.
function ChatFrameUtil.GetDecoratedSenderName(event, ...)
	local _, senderName, _, _, _, _, _, _, _, _, _, senderGUID = ...
	local chatType = event:sub(10)
	local name = senderName

	local info = ChatTypeInfo[chatType]
	if senderGUID and info and info.colorNameByClass then
		local _, class = GetPlayerInfoByGUID(senderGUID)
		local c = class and RAID_CLASS_COLORS[class]
		if c then
			name = string.format("|cff%02x%02x%02x%s|r",
				c.r * 255, c.g * 255, c.b * 255, name)
		end
	end

	return ChatFrameUtil.ProcessSenderNameFilters(event, name, ...)
end

CHAT_SAY_GET             = "%s says: "
CHAT_YELL_GET            = "%s yells: "
CHAT_WHISPER_GET         = "%s whispers: "
CHAT_WHISPER_INFORM_GET  = "To %s: "
CHAT_BN_WHISPER_GET      = "%s whispers: "
CHAT_BN_WHISPER_INFORM_GET = "To %s: "
CHAT_PARTY_GET           = "%s: "
CHAT_PARTY_LEADER_GET    = "%s: "
CHAT_RAID_GET            = "%s: "
CHAT_RAID_LEADER_GET     = "%s: "
CHAT_RAID_WARNING_GET    = "%s: "
CHAT_GUILD_GET           = "%s: "
CHAT_OFFICER_GET         = "%s: "
CHAT_CHANNEL_GET         = "%s: "
-- Two format arguments, so it must be left exactly as it is. If the reshaping
-- in Modules/Chat.lua ever stops checking, this is what breaks first.
CHAT_CHANNEL_NOTICE_GET  = "[%d. %s] "

-- `id` is the chat type index the handler hands to AddMessage alongside the
-- text. Real entries carry one; it is what makes a finished line identifiable.
ChatTypeInfo = setmetatable({
	SAY     = { id = 1,  r = 1.00, g = 1.00, b = 1.00, colorNameByClass = true },
	YELL    = { id = 2,  r = 1.00, g = 0.25, b = 0.25, colorNameByClass = true },
	PARTY   = { id = 3,  r = 0.66, g = 0.66, b = 1.00, colorNameByClass = true },
	GUILD   = { id = 4,  r = 0.25, g = 1.00, b = 0.25, colorNameByClass = true },
	OFFICER = { id = 5,  r = 0.25, g = 0.75, b = 0.25, colorNameByClass = true },
	WHISPER = { id = 6,  r = 1.00, g = 0.50, b = 1.00, colorNameByClass = true },
	WHISPER_INFORM = { id = 7, r = 1.00, g = 0.50, b = 1.00 },
	CHANNEL = { id = 8,  r = 1.00, g = 0.75, b = 0.75 },
	SYSTEM  = { id = 9,  r = 1.00, g = 1.00, b = 0.00 },
	CHANNEL_NOTICE      = { id = 10, r = 1.00, g = 0.75, b = 0.75 },
	CHANNEL_NOTICE_USER = { id = 11, r = 1.00, g = 0.75, b = 0.75 },
}, { __index = function(t, k)
	-- CHANNEL1..10 are real keys on a live client and the module asks for them
	-- by index, so a missing one is a nil access rather than a fallback.
	if type(k) == "string" and k:match("^CHANNEL%d+$") then return t.CHANNEL end
	return nil
end })

-- WARLOCK used to be added here, because the table above only had three classes
-- in it. It carried RETAIL's purple rather than Vanilla's periwinkle, which is
-- the sort of thing that goes unnoticed until something compares our palette to
-- the client's. The table above is Blizzard's own Vanilla file now, in full.
RAID_CLASS_COLORS.WARRIOR = { r = 0.78, g = 0.61, b = 0.43 }

local GUID_CLASS = {
	["Player-4700-0000A1"] = "MAGE",
	["Player-4700-0000B2"] = "WARLOCK",
}

function GetPlayerInfoByGUID(guid)
	local class = GUID_CLASS[guid]
	if not class then return nil end
	return class:sub(1, 1) .. class:sub(2):lower(), class
end

function Ambiguate(name) return name end

--- The link is built *around* the display text, from the raw sender name. That
--  is the whole safety argument for the sender-name filter, so the harness
--  builds it the same way and the assertions read the target back out.
function GetPlayerLink(name, displayText, lineID)
	return "|Hplayer:" .. name .. ":" .. tostring(lineID or 0) .. "|h"
		.. tostring(displayText) .. "|h"
end

GENERAL, TRADE, LOOKING_FOR_GROUP = "General", "Trade", "LookingForGroup"
LOCAL_DEFENSE, WORLD_DEFENSE = "LocalDefense", "WorldDefense"

--- One chat message, assembled the way Classic/ChatFrameOverrides.lua does it.
function DeliverChatMessage(frame, event, ...)
	local discard, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12 =
		ChatFrameUtil.ProcessMessageEventFilters(frame, event, ...)
	if discard then return nil end

	local kind = event:sub(10)
	local info = ChatTypeInfo[kind] or ChatTypeInfo.SYSTEM

	-- The reassignment that decides what a channel *notice* is tagged with. The
	-- handler tests `strsub(type, 1, 7) == "CHANNEL"`, which catches
	-- CHANNEL_NOTICE and CHANNEL_NOTICE_USER as well as chat, and swaps in the
	-- channel's own info - so a notice reaches AddMessage carrying the
	-- channel's id, never the notice type's. Modelled here because without it
	-- the harness would happily pass a DIM_TYPES list that dims nothing in game.
	if kind:sub(1, 7) == "CHANNEL" and kind ~= "CHANNEL_LIST" and a8 and a8 ~= 0 then
		info = ChatTypeInfo["CHANNEL" .. a8] or info
	end

	local out

	if kind == "SYSTEM" then
		out = a1
	elseif kind == "CHANNEL_NOTICE" or kind == "CHANNEL_NOTICE_USER" then
		-- arg1 here is a *token*, not a message: the handler turns it into a
		-- global-string key. Anything that colours or otherwise rewrites it
		-- produces a nil lookup and a Lua error on every login, which is what
		-- an earlier version of the system-line dimming did.
		local globalstring = _G["CHAT_" .. tostring(a1) .. "_NOTICE"]
		if type(globalstring) ~= "string" then
			fail("CHAT_" .. tostring(a1) .. "_NOTICE is nil - arg1 was rewritten")
			return nil
		end
		out = string.format(globalstring, ChatFrameUtil.ResolvePrefixedChannelName(a4))
	else
		local coloredName = ChatFrameUtil.GetDecoratedSenderName(event,
			a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12)
		-- `playerLinkDisplayText = ("[%s]"):format(coloredName)` for everything
		-- that is not an emote. The brackets are added after the sender-name
		-- filter has run, so the badge lands inside them.
		local display = kind == "EMOTE" and coloredName or ("[" .. coloredName .. "]")
		local playerLink = GetPlayerLink(a2, display, a11)
		out = string.format(ChatFrameUtil.GetOutMessageFormatKey(kind) .. a1, playerLink)
		if a4 and a4 ~= "" then
			out = "|Hchannel:channel:" .. tostring(a8) .. "|h["
				.. ChatFrameUtil.ResolvePrefixedChannelName(a4) .. "]|h " .. out
		end
	end

	frame:AddMessage(out, info.r, info.g, info.b, info.id)
	return frame.__last
end

CHAT_YOU_CHANGED_NOTICE = "Changed Channel: %s"
CHAT_YOU_JOINED_NOTICE  = "Joined Channel: %s"

--- Opens a window, docks it, names it. `noDefaultChannels` is the argument that
--  makes the difference between a whispers tab and a second general window.
function FCF_OpenNewWindow(name, noDefaultChannels)
	local f = MakeChatFrame(#CHAT_FRAMES + 1)
	f.name = name
	f.isDocked = true
	if not noDefaultChannels then
		for _, g in ipairs({ "SAY", "YELL", "GUILD", "PARTY", "CHANNEL" }) do
			f:AddMessageGroup(g)
		end
	end
	return f, f:GetID()
end
-- Blizzard rewrites the header every time the box is focused or the channel
-- changes. Blanking it once at skin time was only ever going to hold until the
-- next keystroke, which is what put the grey text back on screen.


local fire   -- assigned once A.pump exists, below

-- ---------------------------------------------------------------------------
-- nameplates
-- ---------------------------------------------------------------------------
--
-- Modelled off Blizzard_NamePlateBase.lua, and deliberately unkind in the three
-- places nameplate addons actually break:
--
--   * Base frames are RECYCLED. The plate that was on a kodo is handed back out
--     for the next mob that walks up, with whatever the last module left on it
--     still attached. A mock that minted a fresh frame per unit would let a
--     module get away with never clearing anything.
--
--   * The Blizzard plate on top is pooled SEPARATELY, and re-acquired on every
--     UNIT_ADDED. ReleaseUnitFrame nils it, so the next unit does not
--     necessarily get the same object back, and it comes back SHOWN. Hide it
--     once when the plate is created and it is visible again on the next mob -
--     which is the single most common way a nameplate skin ships with
--     Blizzard's own plate flickering underneath it.
--
--   * FORBIDDEN plates exist, on their own event pair, and the C_NamePlate
--     getters do not return them to insecure callers - which is what the
--     issecure() argument in Blizzard's own GetNamePlateForUnit is for. Touching
--     one taints. Here they are simply invisible to the getters, so a module
--     that handles the forbidden events gets nil and has to cope.
--
-- Not modelled: whether C_NamePlate.SetNamePlateSize is refused in combat. The
-- retail SetNamePlateEnemySize is, but nothing on this machine calls the Classic
-- one and Blizzard calling it from secure code proves nothing about us. It is a
-- recorded no-op here, and the module does not call it - our plate is
-- decoration anchored to the base, and the base stays the click target at
-- whatever size the client chose.
local plateSeq = 0
local platePool, unitFramePool = {}, {}
local activePlates, activeOrder = {}, {}

_G.C_NamePlate = {}
_G.__plateSize = nil

function C_NamePlate.GetNamePlateForUnit(token)
	return activePlates[token]
end

function C_NamePlate.GetNamePlates()
	local out = {}
	for i = 1, #activeOrder do out[i] = activeOrder[i] end
	return out
end

function C_NamePlate.SetNamePlateSize(w, h)
	_G.__plateSize = { w, h }
end

local function acquireUnitFrame(base)
	-- Pooled, and it comes back SHOWN. This is the trap.
	local uf = table.remove(unitFramePool)
	if not uf then uf = CreateFrame("Frame", nil, base) end
	uf:SetParent(base)
	uf:SetAllPoints(base)
	uf:Show()
	base.UnitFrame = uf
	return uf
end

local function releaseUnitFrame(base)
	local uf = base.UnitFrame
	if uf then
		uf:Hide()
		unitFramePool[#unitFramePool + 1] = uf
	end
	base.UnitFrame = nil
end

--- Bring a nameplate up, exactly as the client does: create (once per frame),
--- then add the unit.
function _G.__spawnPlate(token, data)
	units[token] = data

	local base, fresh = table.remove(platePool), false
	if not base then
		plateSeq = plateSeq + 1
		base = CreateFrame("Frame", "NamePlate" .. plateSeq, UIParent)
		-- C++ builds these and they are the click target, so they are protected:
		-- Hide() or a re-anchor on the BASE is refused in combat. Our own child
		-- of it is not, which is the whole reason the plate is decoration hung on
		-- the base rather than a replacement for it.
		base.__protected = true
		base:SetSize(110, 45)
		fresh = true
	end

	base.unitToken = token
	activePlates[token] = base
	activeOrder[#activeOrder + 1] = base
	base:Show()

	if fresh then fire("NAME_PLATE_CREATED", base) end
	acquireUnitFrame(base)
	fire("NAME_PLATE_UNIT_ADDED", token)
	return base
end

--- And take it away. The token stops being a unit at all - a module holding on
--- to "nameplate3" after this gets nothing back, which is the client's answer.
function _G.__despawnPlate(token)
	local base = activePlates[token]
	if not base then return end

	fire("NAME_PLATE_UNIT_REMOVED", token)
	releaseUnitFrame(base)
	base.unitToken = nil
	activePlates[token] = nil
	for i = #activeOrder, 1, -1 do
		if activeOrder[i] == base then table.remove(activeOrder, i) end
	end
	base:Hide()
	platePool[#platePool + 1] = base
	units[token] = nil
end

--- A forbidden plate: its own event pair, and invisible to the getters.
function _G.__spawnForbiddenPlate(token)
	fire("FORBIDDEN_NAME_PLATE_UNIT_ADDED", token)
end

function _G.__plateCount()
	return #activeOrder
end

function UnitIsUnit(a, b)
	if not a or not b then return false end
	if a == b then return true end
	local ua, ub = units[a], units[b]
	return ua ~= nil and ua == ub
end

function UnitAffectingCombat(u) return units[u] and units[u].inCombat or false end
function UnitInParty(u) return units[u] and units[u].inParty or false end

function UnitIsFriend(a, b)
	local ub = units[b]
	return (ub and ub.reaction and ub.reaction >= 4) or false
end
function UnitIsDead(u) return (units[u] and units[u].hp == 0) or false end
function IsInRaid() return false end
function GetShapeshiftForm() return _G.__shapeshiftForm or 0 end

-- THE THREAT TABLE, and it is EMPTY unless something puts a unit on it.
--
--  UnitDetailedThreatSituation is declared MayReturnNothing, and the case it
--  returns nothing for is the common one: out of combat, or a unit that is not
--  on that mob's table at all. A mock answering 0 for everything would let a
--  module coerce nil to zero and never notice - and "nothing" and "zero" are
--  opposite answers here. Zero threat is a ring at the bottom of its travel;
--  nothing is no ring at all, which is the design's whole quiet-by-default
--  rule. So: no entry, no return values, exactly as the client does it.
--
--  Keyed mob -> unit -> { isTanking, status, scaledPct, rawPct, rawThreat }.
_G.__threat = {}

--- The table belongs to the MOB, not to the token you asked through.
--
--  "target", "pettarget" and "party1target" on the same boar must answer the
--  same list. Keyed on the token, they did not: a party member measured against
--  `party1target` found no table at all and every unit but the player read as
--  not on it, which is a whole group of empty rings that looks like the design
--  being quiet.
local function ThreatRows(mob)
	return _G.__threat[mob]
		or (UnitGUID(mob) and _G.__threat[UnitGUID(mob)])
		or nil
end

function UnitDetailedThreatSituation(unit, mob)
	if not (unit and mob) then return end
	if not UnitAffectingCombat("player") then return end
	local row = ThreatRows(mob)
	row = row and row[unit]
	if not row then return end
	return row[1], row[2], row[3], row[4], row[5]
end

function UnitThreatSituation(unit, mob)
	local _, status = UnitDetailedThreatSituation(unit, mob or "target")
	return status
end

--- THE HOLDER'S MARGIN OVER THE RUNNER-UP, as a percentage.
--
--  Computed from the table rather than handed back one of the other returns.
--  A live probe: a voidwalker on 4700 against a warlock on 400 reports
--  1175%, which is 4700/400 - so this is what the number means, and it is the
--  only thing in the API that answers 16a's "someone is past 90% of YOUR
--  threat". `status` turns 2 at a hundred per cent, by which time the tank's
--  act-now window has already closed.
function UnitThreatPercentageOfLead(unit, mob)
	local tanking = UnitDetailedThreatSituation(unit, mob)
	if not tanking then return end
	local rows = ThreatRows(mob)
	if not rows then return end
	local mine, best = 0, 0
	for u, row in pairs(rows) do
		local v = row[5] or 0
		if u == unit then mine = v elseif v > best then best = v end
	end
	-- NOBODY BEHIND YOU IS NOT A DEAD HEAT, and this is where that gets
	-- decided. With no runner-up the figure is not a lead at all; returning
	-- nothing would let a module that treats a small value as "they are right
	-- behind me" look correct in here. Zero is the value that breaks things, so
	-- zero is what this hands back - the mock's job is to be no kinder than the
	-- client, and something at or below the threshold is what a pet warned of
	-- losing aggro at the pull was reading.
	if best <= 0 then return 0 end
	return mine / best * 100
end

-- A GUID per unit, and a way back. Anything that reads a tooltip by hyperlink
-- goes through one of these rather than through the token.
--- A GUID IN THE CLIENT'S OWN SHAPE.
--
--  Creature-0-serverID-instanceID-zoneUID-ID-spawnUID. Two things matter
--  in it and this mock used to carry neither: a TYPE, which is Pet for a
--  hunter's companion and Creature for everything else, and an ID which is
--  per CREATURE KIND and shared by every one of them.
--
--  It was Creature-0-0-0-0-<name>. With no type and no id, code that keyed
--  a cache off the NAME looked exactly as correct as code that keyed off
--  the creature - and a tamed Dire Mottled Boar put its owner's name under
--  every wild one in the zone.
local guidSeq = 0
local npcIDs, nextNpcID = {}, 400

local function NpcIdFor(name)
	name = tostring(name or "?")
	if not npcIDs[name] then
		nextNpcID = nextNpcID + 1
		npcIDs[name] = nextNpcID
	end
	return npcIDs[name]
end

function UnitGUID(u)
	local d = units[u]
	if not d then return nil end
	if not d.__guid then
		guidSeq = guidSeq + 1
		-- A tamed boar and a wild one share the ID and differ in type,
		-- which is the whole of the case that broke.
		d.__guid = string.format("%s-0-970-0-11-%d-%08X",
			d.guidType or "Creature", d.npcID or NpcIdFor(d.name), guidSeq)
	end
	return d.__guid
end

local function UnitForGUID(guid)
	for _, d in pairs(units) do
		if d.__guid == guid then return d end
	end
end
_G.__unitForGUID = UnitForGUID

-- Whether you can hit it, which is how the client separates somebody who lives
-- here from something you fight. A flight master and a wandering kodo can both
-- be non-hostile; only one of them is a mob.
--
-- Declared per unit, with a MOB as the default: reaction alone cannot answer
-- this, so a fixture that means "NPC" has to say so. Defaulting the other way
-- would let a module that never asks the question look correct.
function UnitCanAttack(a, b)
	local d = units[b]
	if not d then return false end
	if d.canAttack ~= nil then return d.canAttack end
	return (d.reaction or 4) <= 4
end
-- SPELL NAMES BY ID. Only the handful anything here looks up, and the point of
-- them is that the lookup has to go through the client at all: an addon that
-- hard-coded "Defensive Stance" would work in English and nowhere else, and a
-- mock with no GetSpellInfo lets that pass by making every id resolve to
-- nothing - which reads as "nobody is a tank" rather than as a missing API.
--
-- Classic Era has the flat GetSpellInfo. C_Spell.GetSpellInfo is deliberately
-- absent so the fallback branch is the one exercised here, as it is in game.
local SPELL_NAMES = {
	[71]    = "Defensive Stance",
	[5487]  = "Bear Form",
	[9634]  = "Dire Bear Form",
	[25780] = "Righteous Fury",
}
function GetSpellInfo(id)
	local name = SPELL_NAMES[id]
	if not name then return nil end
	return name, nil, [[Interface\Icons\Spell_Nature_Spirit]], 0, 0, 0, id
end

function GetGuildInfo(u) local d = units[u]; return d and d.guild end

print("== loading addon files ==")

-- THE SAME LIST THE CLIENT LOADS, and checked against the .toc further down.
--
-- It is written out again here rather than parsed, because the order matters
-- and a parser is one more thing to be wrong. What must not happen is the two
-- drifting: a module added to the .toc and not to this list ships to players
-- while being invisible to every check in this file, which is the most
-- flattering kind of untested there is.
-- ---------------------------------------------------------------------------
-- the taxi
-- ---------------------------------------------------------------------------
--
-- Nodes are the flight map's slots while it is open. `routes` maps a
-- destination slot to the destination slot of each of its legs, which is what
-- TaxiGetNodeSlot answers - a two-leg trip has two entries.
--
-- Whether the player is ON one stays `_G.__onTaxi`, which already existed for
-- Zen and the fader. Being on a taxi is one fact and wants one flag - a second
-- one here would let the two halves of the suite disagree about it.
--
-- It is a flag the test sets, NOT something the mock infers from TakeTaxiNode:
-- the client does not put you on the griffin the instant you click, and code
-- that assumed it would never meet the delay that makes PLAYER_CONTROL_LOST
-- unreliable.
_G.__taxi = {
	nodes  = {},
	routes = {},
	earlyLandings = 0,
}

function NumTaxiNodes() return #_G.__taxi.nodes end

function TaxiNodeGetType(i)
	local n = _G.__taxi.nodes[i]
	return n and n.kind or "NONE"
end

function TaxiNodeName(i)
	local n = _G.__taxi.nodes[i]
	return n and n.name or nil
end

function GetNumRoutes(i)
	local r = _G.__taxi.routes[i]
	return r and #r or 1
end

function TaxiGetNodeSlot(i, leg, isSource)
	local r = _G.__taxi.routes[i]
	if not r then return isSource and 1 or i end
	if isSource then return leg == 1 and 1 or r[leg - 1] end
	return r[leg]
end

function TakeTaxiNode(i) end            -- hooked, does nothing itself
function TaxiRequestEarlyLanding()
	_G.__taxi.earlyLandings = _G.__taxi.earlyLandings + 1
end


local FRIZ = "Fonts\\FRIZQT__.TTF"

--- The client's own font objects, as far as anything here needs them.
--
--  Real ones, with a real face and size on them: a menu line is given
--  GameFontHighlight by the compositor on every acquire, and a module that
--  re-roles the face has to read the size back off it.
local function BlizzFontObject(name, size, flags)
	local o = { __font = { FRIZ, size, flags } }
	function o:GetFont() local c = self.__font return c[1], c[2], c[3] end
	-- REFUSES A FACE IT CANNOT LOAD, like the real one and like the
	-- FontString mock above: the font is left UNCHANGED and nothing is
	-- said about it. An object that accepted anything would make the
	-- read-back in a remap unfalsifiable.
	function o:SetFont(p, s, fl)
		if _G.__badFonts and _G.__badFonts[p] then return end
		self.__font = { p, s, fl }
	end
	_G[name] = o
	return o
end

BlizzFontObject("GameFontHighlight", 12)
BlizzFontObject("GameFontNormal", 12)

-- The message frames' own, at the sizes and outlines the client has them:
-- ErrorFont comes from GameFontNormalLarge at 16, the zone banner is 32
-- thick-outlined, the subzone 26, a raid warning 20.
BlizzFontObject("ErrorFont", 16)
BlizzFontObject("ZoneTextFont", 32, "THICKOUTLINE")
BlizzFontObject("SubZoneTextFont", 26, "THICKOUTLINE")
BlizzFontObject("GameFontNormalHuge", 20)

-- ---------------------------------------------------------------------------
-- the game's own transient messages
--
-- Real shapes, taken from the client's own XML rather than invented:
--
--   UIErrorsFrame is a MessageFrame. Its font lives on the FRAME - it builds
--   a FontString per message from that - so a mock that gave it a child
--   string to style would let a module pass here and change nothing in game.
--
--   Every one of them starts in Friz Quadrata at the size its font object
--   actually uses (ErrorFont 16, ZoneTextFont 32 thick, SubZoneTextFont 26
--   thick, GameFontNormalHuge 20). A mock starting at nil would make a
--   module that never read the size look identical to one that did.
-- ---------------------------------------------------------------------------


_G.UIErrorsFrame = CreateFrame("Frame", "UIErrorsFrame", UIParent)
-- ON THE FRAME, not inherited. A MessageFrame carries its own font
-- instance; whether it follows ErrorFont after a remap is not something
-- this harness can answer, so it is modelled as the pessimistic case.
_G.UIErrorsFrame.__font = { FRIZ, 16, nil }
function _G.UIErrorsFrame:SetFont(path, size, flags)
	if type(path) ~= "string" then fail("UIErrorsFrame:SetFont path " .. tostring(path)) return end
	if type(size) ~= "number" then fail("UIErrorsFrame:SetFont size " .. tostring(size)) return end
	-- A FACE IT CANNOT LOAD IS REFUSED, silently, like every other font
	-- instance. This mock accepted anything, so a frame was the one thing
	-- in the interface where a missing face could not be caught.
	if _G.__badFonts and _G.__badFonts[path] then return end
	self.__font = { path, size, flags }
end
function _G.UIErrorsFrame:GetFont()
	local c = self.__font
	if not c then return nil end
	return c[1], c[2], c[3]
end
_G.UIErrorsFrame.__messages = {}
function _G.UIErrorsFrame:AddMessage(text, r, g, b)
	self.__messages[#self.__messages + 1] = { text = text, r = r, g = g, b = b,
		font = { self:GetFont() } }
end

--- INHERITED, not set. The client's XML gives each of these a font
--  OBJECT - ZoneTextFont, SubZoneTextFont, GameFontNormalHuge - and the
--  string follows that object for as long as it lives. A mock that wrote
--  the face straight onto the string would make a global remap of the
--  objects look like it reached nothing.
local function BlizzMessageString(parent, name, fontObjectName)
	local fs = parent:CreateFontString(name)
	fs:SetFontObject(fontObjectName)
	return fs
end

_G.ZoneTextFrame = CreateFrame("Frame", "ZoneTextFrame", UIParent)
BlizzMessageString(_G.ZoneTextFrame, "ZoneTextString", "ZoneTextFont")
BlizzMessageString(_G.ZoneTextFrame, "PVPInfoTextString", "SubZoneTextFont")

_G.SubZoneTextFrame = CreateFrame("Frame", "SubZoneTextFrame", UIParent)
BlizzMessageString(_G.SubZoneTextFrame, "SubZoneTextString", "SubZoneTextFont")
BlizzMessageString(_G.SubZoneTextFrame, "PVPArenaTextString", "SubZoneTextFont")

_G.RaidWarningFrame = CreateFrame("Frame", "RaidWarningFrame", UIParent)
BlizzMessageString(_G.RaidWarningFrame, "RaidWarningFrameSlot1", "GameFontNormalHuge")
BlizzMessageString(_G.RaidWarningFrame, "RaidWarningFrameSlot2", "GameFontNormalHuge")

-- Present on this client, absent on some others - which is why the module
-- looks each name up rather than assuming the set.
_G.RaidBossEmoteFrame = CreateFrame("Frame", "RaidBossEmoteFrame", UIParent)
BlizzMessageString(_G.RaidBossEmoteFrame, "RaidBossEmoteFrameSlot1", "GameFontNormalHuge")
BlizzMessageString(_G.RaidBossEmoteFrame, "RaidBossEmoteFrameSlot2", "GameFontNormalHuge")



-- ---------------------------------------------------------------------------
-- Blizzard_Menu
--
-- The client's own right-click menus, and the parts of them a skin can reach.
-- Modelled on the real thing rather than on what is convenient, because the
-- restrictions ARE the interesting part:
--
--   * the menu frames are POOLED, and the style mixin is copied in on every
--     acquire rather than once at creation. That is what makes replacing one
--     function reach every menu opened afterwards, and a mock that mixed in
--     once would let a module that hooked too late still pass.
--   * SetFont is DISALLOWED on a menu's font strings - the compositor owns
--     them. A mock that allowed it would let this module be written with
--     Reskin.Font, which would silently do nothing in game.
--   * CreateTexture and CreateFontString are disallowed on the menu FRAME,
--     for the same reason. Anything a skin adds has to be a child frame.
--   * every acquire re-applies GameFontHighlight, so a face applied once and
--     not re-applied per open is gone by the second menu.
-- ---------------------------------------------------------------------------

local menuPool = {}
_G.__menuOpens = 0

local function AcquireMenuFontString(owner)
	local fs = owner.__aetherMenuStrings and owner.__aetherMenuStrings[1]
	if not fs then
		fs = newFontStringForMenu(owner)
		owner.__aetherMenuStrings = { fs }
	end
	-- The pool's reset, every time.
	fs:SetFontObject("GameFontHighlight")
	fs:SetTextColor(1, 1, 1, 1)
	return fs
end

MenuVariants = {}
function MenuVariants.CreateFontString(frame)
	return AcquireMenuFontString(frame)
end

-- TWO STYLES, and which one a menu uses is the whole point.
--
-- MenuStyle1Mixin is what a dropdown BUTTON opens - a setting in a panel.
-- MenuStyle2Mixin is what a RIGHT-CLICK context menu opens, and on this
-- game type MenuVariants.GetDefaultContextMenuMixin returns that one. The
-- mock had only Style1, so a module that hooked Style1 and nothing else
-- passed every check here while changing nothing anybody would ever see.
MenuStyleMixin = {}

MenuStyle1Mixin = {}
function MenuStyle1Mixin:Generate()
	local t = self:AttachTexture()
	t:SetTexture("common-dropdown-classic-bg")
	self.__blizzArt = t
end

MenuStyle2Mixin = {}
function MenuStyle2Mixin:Generate()
	local t = self:AttachTexture()
	t:SetTexture("common-dropdown-classic-b-bg")
	self.__blizzArt = t
end

function MenuVariants.GetDefaultContextMenuMixin()
	return MenuStyle2Mixin
end

--- Open a menu the way the client does: acquire a pooled frame, mix the style
--  in FRESH, generate, then build one line through MenuVariants.
--
--  `style` names which mixin, and defaults to the CONTEXT one - because a
--  right-click menu is what a player means by a menu, and defaulting to the
--  other is how this went unnoticed the first time.

--- What the compositor keeps for a frame while its menu is open.
--
--  Off the frame, because the client's is too: every write to a menu frame
--  goes into a table on its metatable, not onto the frame.
local menuSnapshot = {}

--- Close a menu the way the client does.
--
--  MenuMixin:Close calls compositor:Detach(), which restores the frame's
--  ORIGINAL metatable - and with it goes the table every write since the menu
--  opened was collected in. So every key an addon set on the frame is gone,
--  and every region it attached goes back to a pool shared with every other
--  menu in the game.
--
--  Modelled because the mock without it was kinder than the client in the one
--  way that mattered here: a mark left on the frame looked permanent, so
--  dressing a menu "once" looked like once.
function _G.__CloseMenu(index)
	index = index or 1
	local menu, snap = menuPool[index], menuSnapshot[index]
	if not menu or not snap then return end
	-- Keys written since the open, gone.
	for k in pairs(menu) do
		if snap[k] == nil then menu[k] = nil end
	end
	-- Keys the open CHANGED, back as they were. Shallow, like the client's:
	-- it shadows the frame's own values rather than copying what is inside
	-- them, and the frame's C-side state is not touched by a detach at all.
	for k, v in pairs(snap) do menu[k] = v end
	menuSnapshot[index] = nil
end

function _G.__OpenMenu(index, style)
	index = index or 1
	style = style or MenuVariants.GetDefaultContextMenuMixin()
	local menu = menuPool[index]
	if not menu then
		menu = CreateFrame("Frame", nil, UIParent)
		menu.__isMenuFrame = true
		function menu:AttachTexture()
			self.__attached = self.__attached or {}
			local t = newTexture(self, "ARTWORK")
			self.__attached[#self.__attached + 1] = t
			return t
		end
		-- Disallowed by the compositor, and it says so rather than obliging.
		function menu:CreateTexture()
			fail("CreateTexture is disallowed on a pooled menu frame")
		end
		function menu:CreateFontString()
			fail("CreateFontString is disallowed on a pooled menu frame")
		end
		menuPool[index] = menu
	end

	-- A POOLED FRAME IS ONLY HANDED OUT AGAIN AFTER ITS MENU CLOSED, and
	-- closing is what takes our dressing back off it.
	_G.__CloseMenu(index)
	local snap = {}
	for k, v in pairs(menu) do snap[k] = v end
	menuSnapshot[index] = snap

	-- Mixin, EVERY TIME. This is the line that makes a late hook work.
	for k, v in pairs(style) do menu[k] = v end
	menu:Generate()
	menu.__line = MenuVariants.CreateFontString(menu)
	menu.__line:SetText("Raid Target Icon")
	_G.__menuOpens = _G.__menuOpens + 1
	return menu
end

FRIZ = FRIZ    -- the client face, shared with the checks below

