-- ---------------------------------------------------------------------------
-- drive a session
-- ---------------------------------------------------------------------------

local pump = A.pump

fire = function(event, ...)
	local fn = pump:GetScript("OnEvent")
	if fn then
		local ok, err = pcall(fn, pump, event, ...)
		if not ok then fail("event " .. event .. ": " .. tostring(err)) end
	end
end

-- Expanding or collapsing a header fires QUEST_LOG_UPDATE on the live client.
-- Modelling that matters more than it looks: it is what makes a collapse visible
-- to every other module's rebuild, and a mock that stays silent here hides the
-- fact that a collapsed zone's quests vanish from the log mid-operation.
do
	local realExpand, realCollapse = ExpandQuestHeader, CollapseQuestHeader
	ExpandQuestHeader = function(i) realExpand(i) fire("QUEST_LOG_UPDATE") end
	CollapseQuestHeader = function(i) realCollapse(i) fire("QUEST_LOG_UPDATE") end
end

local function tick(dt)
	time = time + dt
	local fn = pump:GetScript("OnUpdate")
	if fn then
		local ok, err = pcall(fn, pump, dt)
		if not ok then fail("OnUpdate: " .. tostring(err)) end
	end
	-- ...and anything C_Timer has due, which is what the client does on the same
	-- frame. Without it a timer sat in the queue until a test remembered to
	-- drain it, and anything whose correctness is "this stops after N seconds"
	-- was measured as "this stops whenever somebody looked".
	_G.__runDueTimers()
end

print("== boot ==")
AetherUIDB = nil
fire("ADDON_LOADED", ADDON)
fire("PLAYER_LOGIN")
fire("PLAYER_ENTERING_WORLD")

print("== assertions ==")

local function check(cond, msg)
	if cond then
		print("  ok  " .. msg)
	else
		fail(msg)
	end
end

--- A block of checks that cannot take the rest of the suite down with it.
--
--  The suite is one straight-line chunk, so a nil-index anywhere in it aborts
--  everything after that point. That is the difference between "one assertion
--  went stale" and "the last eight hundred checks did not run and nobody
--  noticed" - and the second is exactly what a refactor in progress looks like
--  from the next person's chair.
--
--  Same principle the addon itself is written to (report per-frame results so a
--  wrong name reads as `absent` rather than as silence), applied to the tests.
--  An error inside becomes one named failure and the run carries on.
--
--  `do ... end` blocks elsewhere in this file predate it and are fine to convert
--  as they are next touched; nothing needs doing to them at once.
--- The whole family, in one place. Every "on both skins" check in this file
--  became an "on all four" one when Daylight was replaced, and a check that
--  walks a hand-written pair is a check that will quietly stop covering the
--  skin somebody adds next.
local SKINS = { "midnight", "dawn", "noon", "dusk" }

--- A skin that is NOT the default, for the checks that only need one of those.
local OTHER = "dusk"

local function section(name, fn)
	print("== " .. name .. " ==")
	local ok, err = pcall(fn)
	if not ok then
		fail(name .. " -- the block itself errored: " .. tostring(err))
	end
end

section("the source itself: nothing under space that should not be", function()
	-- NO STRAY CONTROL BYTES IN OUR OWN SOURCE.
	--
	-- The middle dot this interface separates clauses with is written as a decimal
	-- escape, in a dozen files. Written by a tool that ate that escape it becomes
	-- byte 0x01 followed by the digits - which is still valid Lua, still loads, and
	-- draws on screen as a missing-glyph box followed by "94". It shipped in the
	-- Toolbox's mail hint and in the library's heard-line, and the check on the
	-- first of those carried the SAME broken bytes, so the two agreed with each
	-- other and the suite stayed green about it.
	--
	-- COMPARED AS NUMBERS, deliberately. Written as a Lua character class this
	-- check would need the very escapes it exists to police, and the first attempt
	-- at it had its own pattern eaten in exactly the same way.
	--
	-- Tab, newline and carriage return are the only bytes under space that a source
	-- file of ours has any business carrying.
	do
		local bad = 0
		for _, f in ipairs(FILES) do
			local fh = io.open(f, "rb")
			if fh then
				local data = fh:read("*a")
				fh:close()
				local line = 1
				for i = 1, #data do
					local b = data:byte(i)
					if b == 10 then line = line + 1 end
					-- Byte 13 too. This repo is LF, and one of our own files sat in it
			-- as CRLF for months - invisible in every editor, and it makes a
			-- one-line diff read as a whole-file rewrite.
			if b < 32 and b ~= 9 and b ~= 10 then
						print(("  |cffff8a8a!!|r %s:%d carries byte 0x%02X")
							:format(f, line, b))
						bad = bad + 1
					end
				end
			end
		end
		check(bad == 0, "no stray control bytes in our own Lua (" .. bad .. " found)")
	end

	-- AND NO HAND-WRITTEN COLOUR ESCAPES.
	--
	-- There were 203 of them and five distinct colours between them, two of
	-- which - the accent and the type - are chrome. Every /aether line printed
	-- the same violet whichever skin you were on, because the hex was baked
	-- into the string at the moment it was built. They read from the palette
	-- now, through A.Hi / A.Val / A.Good / A.Bad / A.Dim.
	--
	-- The three that remain are inside COMMENTS, describing escapes the CLIENT
	-- writes - a gossip title, a chat-format key, a nameplate count - which is
	-- why this counts code lines only rather than banning the sequence.
	do
		local baked, tag = {}, string.char(124) .. "cff"
		for _, f in ipairs(FILES) do
			-- Except the palette, which is where the sequence is DEFINED. One
			-- function writes it and everything else calls that.
			local fh = f ~= "Core/Palette.lua" and io.open(f, "r")
			if fh then
				local line = 0
				for text in fh:lines() do
					line = line + 1
					local code = text:match("^%s*%-%-") and "" or text
					if code:find(tag, 1, true) then
						baked[#baked + 1] = f .. ":" .. line
					end
				end
				fh:close()
			end
		end
		check(#baked == 0,
			"no colour escape is written by hand - a hex in a string is a colour that"
			.. " cannot follow the skin (" .. table.concat(baked, ", ") .. ")")

		-- The exemption above is only safe while the palette writes it ONCE.
		local owner = 0
		local fh = io.open("Core/Palette.lua", "r")
		if fh then
			for text in fh:lines() do
				if not text:match("^%s*%-%-") and text:find(tag, 1, true) then
					owner = owner + 1
				end
			end
			fh:close()
		end
	-- AND NOTHING IN HERE IS NEWER THAN LUA 5.1.
	--
	-- THIS HARNESS RUNS ON LUAJIT AND THE GAME DOES NOT. LuaJIT is 5.1 plus a
	-- handful of 5.2 features, and `goto` with its ::labels:: is one of them -
	-- so a loop written with one compiles perfectly here and the whole file
	-- fails to parse in the client, which takes the module with it. Every check
	-- in this suite passed on a file the game could not load at all.
	--
	-- The scan is for the statement, not the word: `goto` as a bare identifier
	-- at the head of a statement, and a label anywhere.
	do
		local newer = {}
		for _, f in ipairs(FILES) do
			local fh = io.open(f, "r")
			if fh then
				local line = 0
				for text in fh:lines() do
					line = line + 1
					local code = text:match("^%s*%-%-") and "" or text
					if code:find("^%s*goto%s+[%a_]") or code:find("::[%a_]+::") then
						newer[#newer + 1] = f .. ":" .. line
					end
				end
				fh:close()
			end
		end
		check(#newer == 0,
			"nothing in the addon uses a Lua 5.2 statement the game cannot parse -"
			.. " this harness runs on LuaJIT, which accepts them (" ..
			(#newer > 0 and table.concat(newer, ", ") or "none") .. ")")
	end

	-- AND NOBODY DRAWS A HAIRLINE OF THEIR OWN.
	--
	-- Four windows each built their own: their own fraction of glassEdge, and
	-- their own SetHeight(A:Px(1)) - which is UIParent's pixel used inside a
	-- frame drawn at the profile's scale, so every one of them asked for seven
	-- tenths of a pixel and got a line that measures correctly and cannot be
	-- seen. It was reported four times as a missing separator, on four
	-- different windows, and fixed four times in four places.
	--
	-- One component draws them now. This is what stops the fifth.
	do
		local rogue = {}
		for _, f in ipairs(FILES) do
			-- Except Widgets, which is where a hairline is DEFINED.
			local fh = f ~= "Core/Widgets.lua" and io.open(f, "r")
			if fh then
				local line = 0
				for text in fh:lines() do
					line = line + 1
					local code = text:match("^%s*%-%-") and "" or text
					if code:find("A:Px(1)", 1, true)
						and (code:find("SetHeight", 1, true)
						or code:find("SetWidth", 1, true)) then
						rogue[#rogue + 1] = f .. ":" .. line
					end
				end
				fh:close()
			end
		end
		check(#rogue == 0,
			"no window sizes a line of its own to UIParent's pixel - they go"
			.. " through W.Hairline, which converts into the frame's own units ("
			.. (#rogue > 0 and table.concat(rogue, ", ") or "none") .. ")")
	end

		check(owner == 1,
			"and the palette writes it exactly once - the exemption is a single"
			.. " owner, not a file nobody checks (" .. owner .. " lines)")
	end
end)

section("the harness itself: a size worked out from anchors", function()
	-- The mock reports a width for a region pinned by two opposing edges, the
	-- way the client does. It used to report the zero it was born with, and that
	-- is not a detail: "does this text fit its box" is the question this UI asks
	-- most often, and two overflow bugs shipped past checks that read that zero
	-- and passed. Both had to be re-checked by recomputing the width from the
	-- anchors inside the test, which is the mock's job.
	--
	-- Tested directly, because a derivation that never fires looks exactly like
	-- one that works: every check in the file went green either way.
	local parent = CreateFrame("Frame")
	parent:SetSize(200, 100)

	local box = CreateFrame("Frame", nil, parent)
	box:SetPoint("TOPLEFT", parent, "TOPLEFT", 10, -8)
	box:SetPoint("BOTTOMRIGHT", parent, "BOTTOMRIGHT", -12, 6)
	check(math.abs(box:GetWidth() - 178) < 0.001,
		"pinned by opposite corners, the width is the parent's less both insets"
		.. " (got " .. tostring(box:GetWidth()) .. " of 200 - 10 - 12)")
	check(math.abs(box:GetHeight() - 86) < 0.001,
		"and the height likewise, with y counted upward (got "
		.. tostring(box:GetHeight()) .. " of 100 - 8 - 6)")

	-- One axis only. A label pinned along the bottom of a tile has a width and
	-- no height, and inventing one would be worse than reporting none.
	local strip = CreateFrame("Frame", nil, parent)
	strip:SetPoint("BOTTOMLEFT", parent, "BOTTOMLEFT", 12, 10)
	strip:SetPoint("BOTTOMRIGHT", parent, "BOTTOMRIGHT", -12, 10)
	check(math.abs(strip:GetWidth() - 176) < 0.001,
		"two anchors on one edge still give a width (" .. tostring(strip:GetWidth()) .. ")")
	check(strip:GetHeight() == 0,
		"and no height, because two BOTTOMs do not describe one")

	-- An explicit size wins, or this would quietly rewrite the geometry every
	-- other check in the file is built on. Set on the frame that CAN derive one,
	-- and to a different number: on a frame with no derivable span the fallback
	-- returns the explicit value either way and the check proves nothing.
	box:SetWidth(50)
	check(box:GetWidth() == 50,
		"a width that was SET beats the one the anchors imply (50, not 178)")
	box:SetWidth(0)
	check(math.abs(box:GetWidth() - 178) < 0.001, "and clearing it goes back")
	box:SetHeight(40)
	check(box:GetHeight() == 40,
		"and the same on the other axis (40, not 86) - both branches, because"
		.. " they are two lines of code and only one of them was tested")
	box:SetHeight(0)
	check(math.abs(box:GetHeight() - 86) < 0.001, "and back again")

	-- A single anchor describes no span at all.
	local loose = CreateFrame("Frame", nil, parent)
	loose:SetPoint("LEFT", parent, "LEFT", 5, 0)
	check(loose:GetWidth() == 0, "one anchor gives nothing")

	-- Anchored to two DIFFERENT frames: not guessed at. Resolving it needs their
	-- absolute positions, which is a layout engine rather than a mock.
	--
	-- Shaped so that ignoring the same-frame rule gives a plausible POSITIVE
	-- number rather than a negative one. The first version of this check pinned
	-- LEFT to the other frame's RIGHT, which works out negative and is rejected
	-- by the span > 0 test anyway - so dropping the rule changed nothing and the
	-- check passed against a mock that was guessing.
	local other = CreateFrame("Frame", nil, parent)
	other:SetSize(30, 30)
	local spanning = CreateFrame("Frame", nil, parent)
	spanning:SetPoint("LEFT", other, "LEFT", 0, 0)
	spanning:SetPoint("RIGHT", parent, "RIGHT", 0, 0)
	check(spanning:GetWidth() == 0,
		"and a region pinned between two different frames is left at zero rather"
		.. " than answered wrongly (got " .. tostring(spanning:GetWidth())
		.. "; taking the first frame for both would say 30)")

	-- A cycle terminates instead of running the stack out.
	--
	-- BUILT PAST THE SETTER, ON PURPOSE. SetPoint now refuses a cycle the way
	-- the client does - "cannot anchor to a region dependent on it" - so this
	-- one is written straight into the points to keep proving the other half:
	-- that a chain which HAS looped is walked to a stop rather than running
	-- the stack out. Both matter, and only one of them can go through the
	-- front door.
	local a = CreateFrame("Frame", nil, parent)
	local b = CreateFrame("Frame", nil, parent)
	a.__points = { { "LEFT", b, "LEFT", 0, 0 }, { "RIGHT", b, "RIGHT", 0, 0 } }
	b.__points = { { "LEFT", a, "LEFT", 0, 0 }, { "RIGHT", a, "RIGHT", 0, 0 } }
	local ok, w = pcall(a.GetWidth, a)
	check(ok and w == 0,
		"two frames anchored to each other report zero rather than overflowing"
		.. " the stack")

	-- And the payoff: a FontString stretched between two anchors WRAPS, which is
	-- the measurement the overflow checks actually need.
	local fs = parent:CreateFontString(nil, "OVERLAY")
	fs:SetFont([[Fonts\FRIZQT__.TTF]], 12, "")
	fs:SetPoint("TOPLEFT", parent, "TOPLEFT", 0, 0)
	fs:SetPoint("TOPRIGHT", parent, "TOPRIGHT", 0, 0)
	fs:SetText(("word "):rep(40))
	check(fs:GetStringHeight() > 12 * 1.2 * 2,
		"a long line in a 200px box is several lines tall rather than one ("
		.. string.format("%.0f", fs:GetStringHeight()) .. ")")

	-- A clamped, non-wrapping string reports AT MOST its clamp.
	--
	-- Reporting the untruncated extent is the kinder answer and it hides a real
	-- bug: code that measures a label to decide whether a shorter form is needed
	-- - having clamped that same label last time round - gets the full width
	-- back, decides everything fits, and never uncollapses. Which is exactly
	-- what the unit frames' name row does.
	local clamped = parent:CreateFontString(nil, "OVERLAY")
	clamped:SetFont([[Fonts\FRIZQT__.TTF]], 12, "")
	clamped:SetText(("wide "):rep(30))
	local full = clamped:GetStringWidth()
	check(full > 300, "an unclamped string reports its full extent ("
		.. string.format("%.0f", full) .. ")")
	clamped:SetWordWrap(false)
	clamped:SetWidth(80)
	check(clamped:GetStringWidth() == 80,
		"and a clamped one reports the clamp, not the string it would have"
		.. " drawn (" .. string.format("%.0f", clamped:GetStringWidth()) .. ")")
	clamped:SetWordWrap(true)
	check(clamped:GetStringWidth() == full,
		"while one allowed to WRAP reports its extent again - it is not"
		.. " truncated, it is folded")
end)

local UF = A:GetModule("unitframes")
check(UF and UF.enabled, "unitframes module enabled")
check(UF.player and UF.target, "player and target capsules built")
check(UF.cast ~= nil, "cast bar built")
check(A.db and A.db.profile.skin == "midnight", "db initialised with default skin")
check(#UF.player.glass._fill == 3, "player capsule uses the 3-slice pill")
do
	-- Both caps must come out the same width. The frame's left and right edges
	-- sit at different sub-pixel phases, so `left + cap` and `right - cap` round
	-- in opposite directions unless cap is a whole number of physical pixels -
	-- one cap a pixel wider than the other, and the join between the arc and the
	-- straight edge a pixel out of true on that side.
	local L = UF.player.glass._fill[1]:GetWidth()
	local R = UF.player.glass._fill[3]:GetWidth()
	check(L == R, ("the two cap slices are the same width (%s vs %s)")
		:format(tostring(L), tostring(R)))
	local step = (A.pixel or 1) * (UIParent:GetEffectiveScale() or 1)
		/ (UF.player.glass:GetEffectiveScale() or 1)
	check(math.abs(L / step - math.floor(L / step + 0.5)) < 1e-6,
		"and land on a whole number of physical pixels")
end
do
	-- AND SO DOES A PANEL'S CORNER, which it never used to.
	--
	-- The pill has snapped its caps from the beginning and CreatePanel laid its
	-- corner out raw. A 12-unit corner at a scale of 0.71 is 8.5 physical
	-- pixels: the arc's outer edge falls across a pixel boundary the whole way
	-- round and the client resolves that as a ring of half-lit greys, which is
	-- exactly what "the curves are not smooth" looks like on screen. Worst on
	-- small shapes, which is why a button showed it first and a tooltip did not.
	local p = A.Glass.CreatePanel(UIParent, { corner = 12 })
	p:SetSize(200, 60)
	p:SetScale(0.71)
	p:_Relayout()

	local c = p._fill[1]:GetWidth()
	local step = (A.pixel or 1) * (UIParent:GetEffectiveScale() or 1)
		/ (p:GetEffectiveScale() or 1)
	check(math.abs(c / step - math.floor(c / step + 0.5)) < 1e-6,
		"a panel's corner lands on whole physical pixels too (" .. tostring(c)
		.. " at scale " .. tostring(p:GetScale()) .. ")")
	p:Hide()
end
do
	-- Pixel snapping stays ON. Turning it off was tried and made it worse; see
	-- the note at the top of Core/Glass.lua.
	local bad
	for _, set in ipairs({ UF.player.glass._fill, UF.player.glass._edge }) do
		for _, tex in ipairs(set) do
			if tex.__snap ~= nil then bad = true end
		end
	end
	check(not bad,
		"and none of them touches pixel snapping. These slices abut, so snapped"
		.. " they land on the same integer pixel and tile; unsnapped they land on"
		.. " the same fractional one, the boundary pixel is covered by both, and"
		.. " the rim there gets blended twice - a bright dot at every corner")
end
check(UF.player.glass._noise == nil and UF.player.glass.SetNoiseStrength == nil,
	"no runtime noise layer: grain is baked into the fill textures")
check(UF.player.glass._shadow and #UF.player.glass._shadow == 3,
	"pill gets the capsule-shaped 3-slice shadow")
check(UF.player.glass ~= UF.player and UF.player.glass.SetHeight ~= nil,
	"the glass is a separate frame from the layout core, so it can grow in combat")
do
	local panel = A.Glass.CreatePanel(UIParent, { shadow = 10 })
	check(panel._shadow and #panel._shadow == 9, "panel gets the rectangular 9-slice shadow")
end
do
	local cfg = A.db.profile.modules.unitframes
	local need = 10 + cfg.orbSize + 13 + cfg.barWidth + 12 + 40 + 24
	check(cfg.width >= need, "default capsule width fits its contents ("
		.. cfg.width .. " >= " .. need .. ")")
end
check(UF.player.name:GetText() == "Palabras", "player name populated")
check(UF.target.name:GetText() == "Savannah Prowler", "target name populated")
check(UF.player.orb.label:GetText() == "15", "player level in the orb")
-- The subtitle is the creature type, and the level after it WHEN IT FITS. At
-- these metrics "Savannah Prowler" plus the full form is a couple of pixels over
-- the bar, so the row gives up the level - which the orb is already showing.
-- Asserted as "one of the forms" rather than as a string, because which one you
-- get is a measurement and the mock's character width is an approximation of the
-- client's.
check(UF.target.sub:GetText() == "Beast · Lv 16" or UF.target.sub:GetText() == "Beast",
	"target subtitle from creature type (got " .. tostring(UF.target.sub:GetText())
	.. ")")
check(UF.player.hpText:GetText() == "208", "player health readout")
check(UF.target.hpText:GetText() == "64%", "target health shown as a percentage")
do
	local hp, hrel = UF.player.hpText:GetPoint(1)
	local mp, mrel = UF.player.mpText:GetPoint(1)
	check(hrel == UF.player.health and mrel == UF.player.power,
		"each readout is anchored to its own bar, so a missing power bar cannot"
		.. " leave the health number floating high")
	check(hp == "LEFT" and mp == "LEFT", "player readouts sit to the right of the bars")
	local thp, threl = UF.target.hpText:GetPoint(1)
	check(thp == "RIGHT" and threl == UF.target.health, "target readout mirrors")
end

section("unitframes: the name row collapses rather than the frame growing", function()
	local mo = _G.__units.target
	local was = { mo.name, mo.isPlayer, mo.race, mo.class, mo.classToken,
		mo.creature, mo.level }
	local block = UF.target.block
	local room  = block:GetWidth()
	local function refresh() fire("PLAYER_TARGET_CHANGED") end
	local function row()
		return UF.target.name:GetText() or "", UF.target.sub:GetText() or ""
	end
	--- What the row actually measures, the way the module measures it.
	local function used()
		local n = UF.target.name
		local w = n:GetStringWidth() or 0
		local s = UF.target.sub:GetText() or ""
		if s ~= "" then w = w + 8 + (UF.target.sub:GetStringWidth() or 0) end
		return w
	end

	check(room > 0, "the name row has the bars' own width to work in ("
		.. string.format("%.0f", room) .. ")")

	-- 1. A short NPC name keeps everything.
	mo.isPlayer, mo.name, mo.creature, mo.level = false, "Rat", "Beast", 3
	refresh()
	local n, s = row()
	check(n == "Rat" and s == "Beast · Lv 3",
		"a short name keeps the creature type AND the level (" .. n .. " / " .. s .. ")")

	-- 2. Longer: the LEVEL goes first. The orb is already showing it.
	-- Long enough that the row cannot hold "Beast · Lv 3", short enough that it
	-- can still hold "Beast". That band is what proves the ORDER rather than
	-- just proving something got dropped.
	mo.name = "Savannah Highmane"
	refresh()
	n, s = row()
	check(n == "Savannah Highmane" and s == "Beast",
		"a longer one gives up the level first - the badge on the orb has been"
		.. " saying it all along (" .. n .. " / " .. s .. ")")
	check(used() <= room + 0.5, "and the row fits (" ..
		string.format("%.0f of %.0f", used(), room) .. ")")

	-- 3. The NAME is never shortened by guessing at a title. The first version
	--    of this dropped the leading word when two remained, which turns
	--    "Savannah Highmane Prowler" into "Highmane Prowler" - and
	--    Adjective-Noun is the shape of most Classic mob names, so the guess is
	--    wrong far more often than right. The real title is the `<Innkeeper>`
	--    line in the unit's tooltip and needs a scanning tooltip to read.
	mo.name = "Innkeeper Boorand Plainswind of the Crossroads"
	refresh()
	n, s = row()
	check(n == "Innkeeper Boorand Plainswind of the Crossroads",
		"a long NPC name is left exactly as the client gave it rather than"
		.. " having its first word guessed off (" .. n .. ")")

	-- 4. The creature type is the LAST thing to go, after everything else has
	--    been tried.
	mo.name = ("Verylongwordindeed"):rep(4)
	refresh()
	n, s = row()
	check(s == "", "and only then is the creature type given up, because it is"
		.. " the one thing here that changes what you DO - polymorph works on a"
		.. " humanoid and not on a beast")
	check(UF.target._nameTruncated == true,
		"with the name truncated as the last resort, which everything above"
		.. " exists to avoid reaching")
	do
		local w = UF.target.name:GetWidth() or 0
		check(w > 0 and w <= room + 0.5,
			"and clamped to the bars' width, so the frame does not grow ("
			.. string.format("%.0f of %.0f", w, room) .. ") - a width of ZERO is"
			.. " not a clamp, it is the absence of one, and that is what a"
			.. " deleted SetWidth looks like from here")
		check(UF.target.name.__wordWrap == false,
			"and never wrapping - the health bar hangs off this line's bottom"
			.. " edge, so a name that took two of them would push the bars out"
			.. " through the floor of the capsule")
	end

	-- 5. ...and it UNCOLLAPSES. The clamp from the step above has to be cleared
	--    before the next measurement or every form "fits" and the row never
	--    comes back.
	mo.name, mo.level = "Rat", 3
	refresh()
	n, s = row()
	check(n == "Rat" and s == "Beast · Lv 3",
		"and a short name afterwards gets everything back - the width clamp is"
		.. " cleared before measuring, or a FontString reports the truncated"
		.. " string's extent and every form fits for ever (" .. n .. " / " .. s .. ")")
	check(UF.target._nameTruncated == false, "and is not truncated any more")

	-- A PLAYER gives up the race, not a title: their name is their name.
	mo.isPlayer, mo.name = true, "Padreamuerto"
	mo.race, mo.class, mo.classToken = "Undead", "Mage", "MAGE"
	refresh()
	n, s = row()
	check(n == "Padreamuerto" and s == "Undead Mage",
		"a player shows race and class when there is room (" .. s .. ")")

	mo.name = "Padreamuertoelmagonegro"
	refresh()
	n, s = row()
	check(n == "Padreamuertoelmagonegro" and s == "Mage",
		"and gives up the RACE when there is not, keeping the class - which is"
		.. " the half that tells you what they can do to you (" .. n .. " / "
		.. s .. ")")
	check(used() <= room + 0.5, "with the row still inside the bars ("
		.. string.format("%.0f of %.0f", used(), room) .. ")")
	check(UF.target.name:GetText() == "Padreamuertoelmagonegro",
		"and the player's name never shortened - there is no title to drop off"
		.. " the front of one")

	-- Both frames use the same routine, so the pair stays mirrored.
	check(UF.player.block:GetWidth() == UF.target.block:GetWidth(),
		"and the two frames' rows are the same width, which is what keeps the"
		.. " pair mirrored whatever either of them is showing")

	mo.name, mo.isPlayer, mo.race, mo.class, mo.classToken, mo.creature, mo.level =
		was[1], was[2], was[3], was[4], was[5], was[6], was[7]
	refresh()
end)

print("== health / power churn ==")
_G.__units.player.hp = 120
fire("UNIT_HEALTH", "player")
for i = 1, 40 do tick(0.1) end
check(math.abs(UF.player.health:GetValue() - 120) < 1, "smoothed health converges on the new value")
check(UF.player.hpText:GetText() == "120", "health text follows")

_G.__units.player.power = 90
fire("UNIT_POWER_UPDATE", "player")
check(UF.player.power:GetValue() ~= nil, "power bar accepted a value")

print("== death empties the bar ==")
do
	-- The client does not reliably send a final UNIT_HEALTH of zero when
	-- something dies, so the target frame sat reading "10%" over a corpse. Kill
	-- the target *without* firing anything and let the reconcile ticker find it.
	_G.__units.target.hp = 110
	fire("UNIT_HEALTH", "target")
	for i = 1, 20 do tick(0.1) end
	check(UF.target.health:GetValue() > 1, "target bar holds a sliver while alive")

	_G.__units.target.dead = true          -- no event at all
	for i = 1, 20 do tick(0.1) end
	check(UF.target.health:GetValue() < 1,
		"the bar empties anyway (got " .. string.format("%.2f", UF.target.health:GetValue())
		.. ") - events are the fast path, not the only path")
	check(UF.target.hpText:GetText() == "Dead",
		"and it says so rather than showing a stale percentage (got "
		.. tostring(UF.target.hpText:GetText()) .. ")")

	_G.__units.target.dead = false
	_G.__units.target.hp = 640
	for i = 1, 20 do tick(0.1) end
	check(UF.target.hpText:GetText():find("%%") ~= nil,
		"and it comes back when the next thing is targeted")
end

print("== target switching ==")
check(UF.target.unitWatched and _G.__unitWatched[UF.target.click],
	"the secure click button is what the unit watch drives, not the capsule")
check(UF.target.click:GetAttribute("unit") == "target"
	and UF.target.click:GetAttribute("*type1") == "target"
	and UF.target.click:GetAttribute("*type2") == "togglemenu",
	"target capsule carries the secure click attributes")

-- AND THE MENU ACTUALLY OPENS. The attributes were all plausible and
-- right-click did nothing for months: "menu" calls the button's own
-- menu-function attribute, and that was the one attribute never set. Nothing
-- errored and nothing was missing - it simply did nothing, and it took being
-- in a party and wanting to leave it to notice.
--
-- Driven through the attributes rather than a kept reference, because a
-- reference is precisely what the broken version also had.
_G.__unitMenu = nil
check(_G.__rightClick(UF.target.click), "right-click has an action to run")
check(_G.__unitMenu ~= nil and _G.__unitMenu.unit == "target",
	"and it opens the target's menu")

_G.__unitMenu = nil
check(_G.__rightClick(UF.player.click) and _G.__unitMenu ~= nil
	and _G.__unitMenu.which == "SELF",
	"and the player's own is SELF, which is the menu with Leave Party on it")
_G.__units.target.exists = false
fire("PLAYER_TARGET_CHANGED")
check(not UF.target.glass:IsShown(),
	"dropping the target hides the capsule's *glass*")
check(UF.target:IsShown(),
	"but never the core - it parents the secure click-catcher, and hiding a"
	.. " frame with a protected descendant is refused in combat")
check(_G.__unitWatched[UF.target.click],
	"the secure button stays under its unit watch either way")

do  -- the bug this replaced: it only ever showed up mid-fight
	_G.__inCombat = true
	_G.__units.target.exists = true
	fire("PLAYER_TARGET_CHANGED")
	_G.__units.target.exists = false
	fire("PLAYER_TARGET_CHANGED")
	check(not UF.target.glass:IsShown(),
		"losing a target in combat hides the glass without a blocked call")
	_G.__inCombat = false
end
_G.__units.target.exists = true
fire("PLAYER_TARGET_CHANGED")
check(UF.target:IsShown() and UF.target.name:GetText() == "Savannah Prowler",
	"target capsule repopulates after retargeting")

print("== casting ==")
do
	-- Both cast bars float free now. Every edge of a capsule belongs to an aura
	-- tray - buffs above, debuffs below - so a bar tied to one would be shoved
	-- around by whatever auras happened to be up.
	local entry = A.Movers.registry.cast
	check(entry ~= nil, "the player cast bar is a mover of its own")
	check(select(2, UF.cast:GetPoint(1)) == UIParent,
		"anchored to the screen, not to a capsule")
	check(entry.preview ~= nil,
		"and unlock previews it - a bar you only ever see mid-cast is a bar you"
		.. " could never aim at")
	entry.preview(true)
	check(UF.cast:IsShown() and UF.cast.spellName:GetText() == "Cast bar",
		"the preview puts something in it to aim at")
	entry.preview(false)
	check(not UF.cast:IsShown(), "and takes it away again on lock")
end
castState = { name = "Frostbolt", icon = 135846, channel = false,
	startTime = time * 1000, endTime = (time + 2.5) * 1000 }
fire("UNIT_SPELLCAST_START", "player")
check(UF.cast:IsShown(), "cast bar shows on cast start")
check(UF.cast:GetScript("OnUpdate") ~= nil,
	"cast bar drives itself per frame, not off the 10Hz shared ticker")

-- advance it the way the client would: many small frames, via its own OnUpdate
local function castFrames(n, dt)
	for _ = 1, n do
		time = time + dt
		UF.cast:GetScript("OnUpdate")(UF.cast, dt)
	end
end
castFrames(60, 1 / 60)
check(UF.cast.spellName:GetText() == "Frostbolt", "cast bar names the spell")
check(UF.cast.bar:GetValue() > 0, "cast bar progresses")
local midway = UF.cast.bar:GetValue()
castFrames(1, 1 / 60)
check(UF.cast.bar:GetValue() > midway,
	"a single 60fps frame advances the bar (smooth, not stepped)")
castState = nil
fire("UNIT_SPELLCAST_STOP", "player")
check(not UF.cast:IsShown(), "cast bar hides on stop")
check(UF.cast:GetScript("OnUpdate") == nil, "cast bar stops updating when hidden")

print("== casts: which source delivered somebody else's ==")
do
	-- THE QUESTION THE COUNTER EXISTS TO ANSWER.
	--
	-- Classic Era has never fired UNIT_SPELLCAST_* for anything but the
	-- player, so everything else comes from LibClassicCasterino reading the
	-- combat log. Both paths are wired and native is tried first, which means
	-- the day the client starts reporting it the library stops mattering -
	-- silently, and with nobody able to say which is true without guessing.
	--
	-- What is checked here is only that BOTH paths are counted. Which of them
	-- fires in the real client is not a question a mock can answer - it is the
	-- question - so this proves the instrument works and the game reads it.
	local NP = A:GetModule("nameplates")
	local was = { native = A.castSource.native, lib = A.castSource.lib }
	A.castSource.native, A.castSource.lib = 0, 0

	fire("UNIT_SPELLCAST_START", "nameplate1")
	check(A.castSource.native == 1,
		"a native cast event for a unit that is not the player is counted (" ..
		A.castSource.native .. ")")

	-- And the library's relay, through the same handlers.
	local lib = LibStub("LibClassicCasterino", true)
	if lib and lib.__fire then
		lib.__fire("UNIT_SPELLCAST_START", "nameplate1")
		check(A.castSource.lib == 1,
			"and a relayed one is counted separately, so the two can be told "
			.. "apart (" .. A.castSource.lib .. ")")
	else
		check(A.castSource.lib == 0,
			"and the library counter starts at nothing")
	end

	A.castSource.native, A.castSource.lib = was.native, was.lib
end

print("== target cast bar (LibClassicCasterino) ==")
check(UF.targetCast ~= nil, "target cast bar built")
do
