section("palette: Midnight is exactly what it was", function()
	local skin = A.Palette.skins.midnight
	check(skin ~= nil, "Midnight is still a skin")

	local function same(a, b)
		if type(a) ~= "table" or type(b) ~= "table" then return a == b end
		if #a ~= #b then return false end
		for i = 1, #a do
			if math.abs((a[i] or 0) - (b[i] or 0)) > 0.0005 then return false end
		end
		return true
	end

	local missing, changed, extra = {}, {}, {}
	local function walk(want, got, path)
		for k, v in pairs(want) do
			local g = got and got[k]
			local at = path .. tostring(k)
			if g == nil then
				missing[#missing + 1] = at
			elseif type(v) == "table" and not (#v >= 3 and type(v[1]) == "number") then
				walk(v, g, at .. ".")
			elseif not same(v, g) then
				changed[#changed + 1] = at
			end
		end
	end
	walk(MIDNIGHT_FROZEN, skin, "")

	for k in pairs(skin) do
		if MIDNIGHT_FROZEN[k] == nil and type(skin[k]) ~= "string" then
			extra[#extra + 1] = tostring(k)
		end
	end

	check(#missing == 0, "every colour Midnight had, it still has ("
		.. #missing .. " gone" .. (missing[1] and (": " .. table.concat(missing, ", ", 1,
			math.min(4, #missing))) or "") .. ")")
	if #changed > 0 then
		print("     |cffff8a8amoved:|r")
		for _, at in ipairs(changed) do
			local w, g = MIDNIGHT_FROZEN, A.Palette.skins.midnight
			for part in at:gmatch("[^.]+") do
				w, g = w and w[part] or w[tonumber(part)], g and g[part] or g[tonumber(part)]
			end
			local function hex(t)
				if type(t) ~= "table" then return "?" end
				return ("#%02x%02x%02x a=%.2f"):format(
					(t[1] or 0) * 255, (t[2] or 0) * 255, (t[3] or 0) * 255, t[4] or 1)
			end
			print(("       %-14s %s -> %s"):format(at, hex(w), hex(g)))
		end
	end
	check(#changed == 0, "and every one of them is the same colour ("
		.. #changed .. " moved)")

	-- New tokens are fine and expected - the addon grows. This only reports
	-- them, so that a token added to one skin and not the others is visible.
	if #extra > 0 then
		print("     |cff888888" .. #extra .. " token(s) added since the freeze: "
			.. table.concat(extra, ", ", 1, math.min(6, #extra)) .. "|r")
	end
end)

section("palette: semantic gold, one shade deeper in Dusk", function()
	local P = A.Palette
	local function hex(c)
		return ("#%02x%02x%02x"):format(c[1] * 255 + 0.5, c[2] * 255 + 0.5,
			c[3] * 255 + 0.5)
	end

	-- THE ONE SKIN-CONDITIONAL COLOUR. It carries meaning rather than chrome -
	-- leader crown, dock arrow, Convert to Raid, the console's landing warning -
	-- so it sits with the meanings and not with the six a skin remaps. Dusk is
	-- the exception, and only Dusk: its accent IS this colour, #f0d9a8 both and
	-- exactly, so on that skin the warning was the frame's own rim.
	for _, name in ipairs({ "midnight", "dawn", "noon" }) do
		check(hex(P.skins[name].semanticGold) == "#f0d9a8",
			name .. " leaves it alone (" .. hex(P.skins[name].semanticGold) .. ")")
	end
	check(hex(P.skins.dusk.semanticGold) == "#ffcf66",
		"and Dusk takes it one shade deeper (" ..
		hex(P.skins.dusk.semanticGold) .. ")")

	-- Which is the whole point, so it is worth saying on its own.
	check(hex(P.skins.dusk.semanticGold) ~= hex(P.skins.dusk.accent),
		"so it is no longer Dusk's own accent, which it used to be exactly (" ..
		hex(P.skins.dusk.accent) .. ")")

	-- AND NO CHROME TOKEN IS A MEANING. Dusk's deep and border were #e8c86a,
	-- which is the same three bytes as FOUR semantics: the console's gossip
	-- channel, a pet's content mood, an elite's chip and a neutral's reaction
	-- tint. One chrome value sitting on four meanings.
	--
	-- The fix went here rather than on those four, and this is the check that
	-- keeps it here. They answer questions about the GAME - what mood, what
	-- reaction, what kind of thing - and a skin may not reach them; routing
	-- them through a skin-conditional token is the mistake SEMANTIC exists to
	-- prevent. It would also have collapsed gossip and the landing warning
	-- into one colour on Dusk, since goldDim and gold are the same there.
	--
	-- Measured in CIE Lab: under about 5 is the same colour at a glance.
	local function lab(c)
		local function inv(u)
			if u <= 0.04045 then return u / 12.92 end
			return ((u + 0.055) / 1.055) ^ 2.4
		end
		local r, g, b = inv(c[1]), inv(c[2]), inv(c[3])
		local X = (r * 0.4124 + g * 0.3576 + b * 0.1805) / 0.95047
		local Y = (r * 0.2126 + g * 0.7152 + b * 0.0722)
		local Z = (r * 0.0193 + g * 0.1192 + b * 0.9505) / 1.08883
		local function fn(t)
			if t > 0.008856 then return t ^ (1 / 3) end
			return 7.787 * t + 16 / 116
		end
		local fx, fy, fz = fn(X), fn(Y), fn(Z)
		return 116 * fy - 16, 500 * (fx - fy), 200 * (fy - fz)
	end
	local function dE(a, b)
		local l1, a1, b1 = lab(a)
		local l2, a2, b2 = lab(b)
		return math.sqrt((l1 - l2) ^ 2 + (a1 - a2) ^ 2 + (b1 - b2) ^ 2)
	end

	local MEANINGS = {
		"ifecGossip", "petContent", "ttElite", "ttNeutral", "talentFull",
		"ttLore", "money",
	}
	local CHROME_TOKENS = { "accent", "accentDeep", "glassEdge" }
	local worst, worstAt = 999, "?"
	for _, skin in ipairs(P.order) do
		local sk = P.skins[skin]
		for _, m in ipairs(MEANINGS) do
			if sk[m] then
				for _, ch in ipairs(CHROME_TOKENS) do
					local d = dE(sk[m], sk[ch])
					if d < worst then
						worst, worstAt = d, skin .. "." .. ch .. " vs " .. m
					end
				end
			end
		end
	end
	check(worst >= 5,
		"no chrome token is a meaning, in any skin (closest: " .. worstAt ..
		(" at dE %.1f"):format(worst) .. ")")
	-- ONE NAME FOR IT. ifecLanding was a second name for the same colour, and a
	-- second name is a second place to forget.
	check(P.skins.midnight.ifecLanding == nil,
		"and it has one name - the console's landing gold IS this token")

	-- AND IT SWITCHES THROUGH THE PALETTE, like every other token.
	P:Apply("dusk")
	check(hex(A.Palette.c.semanticGold) == "#ffcf66",
		"switching to Dusk carries the gold with it")
	P:Apply("midnight")
	check(hex(A.Palette.c.semanticGold) == "#f0d9a8",
		"and switching back brings the other one home")
end)

section("party: four capsules in fixed slots", function()
	local PF = A:GetModule("partyframes")
	local c = A.Config:Module("partyframes")

	-- ON by default, like every other feature here. Somebody who installs
	-- this wants what it does; a feature switched off is a feature nobody
	-- knows is there. Checked because the default IS the product for
	-- almost everybody, and it is one word to get wrong.
	check(c.enabled == true, "on out of the box")

	_G.__units.party1.leader = true
	A:SetModuleEnabled("partyframes", true)
	check(PF.stack ~= nil, "the stack is built")
	check(#PF.frames == 4,
		"four capsules, one per party slot (" .. #PF.frames .. ")")

	-- THE PLAYER IS NOT IN IT. This interface already draws a player capsule,
	-- and a fifth here would be a second answer to the same question.
	local units = {}
	for _, f in ipairs(PF.frames) do units[#units + 1] = f.unit end
	check(table.concat(units, ",") == "party1,party2,party3,party4",
		"party1 to party4, and not the player (" .. table.concat(units, ",") .. ")")

	-- ONE GRIP FOR THE GROUP. The capsules are children of the container and
	-- the container is what Movers knows about - four separate movers would
	-- be four ways to end up with a stack that is not a stack.
	local mover = A.Movers.registry["party"]
	check(mover ~= nil and mover.frame == PF.stack,
		"the stack drags as one thing, not as four")

	-- SECURE, so a click targets and a right-click opens the unit menu even
	-- mid-fight. Without RegisterUnitWatch the client cannot show or hide these
	-- in combat and we would have to, which is the call it refuses.
	local f1 = PF.frames[1]
	check(f1.click ~= nil and f1.click:GetAttribute("unit") == "party1",
		"each capsule carries a secure unit button")
	check(f1.click:GetAttribute("*type2") == "togglemenu",
		"opened with togglemenu, which works out which menu the unit wants")
	check(f1.unitWatched == true,
		"and its visibility is the client's, through RegisterUnitWatch")

	-- AT THE PROFILE'S SCALE, on the container - one call for all four, and on
	-- the frame the mover positions. Every other frame in this interface is
	-- drawn at profile.scale and this one was not, which read on screen as a
	-- party capsule half again too big beside the player's own.
	-- MOVED FIRST, because this profile is at 1 and so is a frame nobody has
	-- scaled - so asking at the default proves nothing at all.
	local wasScale = A.db.profile.scale
	A.db.profile.scale = 0.6
	PF:OnConfigChanged()
	check(math.abs(PF.stack:GetScale() - 0.6) < 0.001,
		"the stack is drawn at the profile's scale (" ..
		tostring(PF.stack:GetScale()) .. ")")
	A.db.profile.scale = wasScale
	PF:OnConfigChanged()
	check(math.abs(PF.stack:GetScale() - (wasScale or 1)) < 0.001,
		"and follows it back")
	-- NO DEAD PILL ON THE END. The capsule reserved width for a role glyph
	-- that most members do not have, so two thirds of a party wore thirty-two
	-- units of empty glass past the last number. The glyph rides the pip now
	-- and the default width is exactly what the contents come to.
	--
	-- Read the other way it is the more serious check: the width slider goes
	-- down to 240 and the bars alone can be 300, so this is also the
	-- difference between a narrow capsule and a readout hanging out of one.
	check(c.width == PF.MinWidth(c),
		"the capsule is exactly as wide as what is in it (" .. c.width ..
		" vs " .. PF.MinWidth(c) .. ")")

	local narrow = A.Config:Module("partyframes")
	local keep = narrow.width
	narrow.width = 240
	PF:OnConfigChanged()
	check(PF.frames[1]:GetWidth() >= PF.MinWidth(narrow),
		"and a width dragged below that is clamped rather than obeyed (" ..
		tostring(PF.frames[1]:GetWidth()) .. ")")
	narrow.width = keep
	PF:OnConfigChanged()

	-- AND BLIZZARD'S OWN ARE GONE. Two of ours on top of four of theirs is not
	-- a skin, it is a mess - and this is the part that was missing when the
	-- module first went in: the capsules were built and the client's frames
	-- were left exactly where they were.
	-- AND THE REPORT SAYS SO PER FRAME. "absent" is the answer that matters:
	-- a name this client does not have hides nothing, silently, and that is
	-- exactly how the first version of this shipped - it went looking for
	-- PartyMemberFrame1..4, which are pooled and nameless here, found nothing
	-- four times and reported success.
	for _, name in ipairs({ "PartyFrame", "CompactPartyFrame",
		"CompactRaidFrameManager" }) do
		check(PF.hideReport[name] == "hidden",
			name .. " is hidden (" .. tostring(PF.hideReport[name]) .. ")")
		check(_G[name]:GetParent() ~= UIParent,
			"and reparented, not just hidden - Hide() alone is undone by the"
			.. " client's own roster code")
	end

	-- REFUSED IN A FIGHT, and asked again after it. These carry a secure
	-- template, so a party joined mid-combat is a party whose frames arrive in
	-- the one window where nothing can be done about them.
	PartyFrame:SetParent(UIParent)
	PartyFrame:Show()
	_G.__inCombat = true
	local blocked = _G.__blocked
	PF:HideBlizzard()
	check(_G.__blocked == blocked,
		"asking mid-fight refuses quietly rather than erroring")
	check(PartyFrame:IsShown(),
		"and the frame is still there, because the client would not have it")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(not PartyFrame:IsShown(),
		"the moment the fight ends, it goes")
end)

section("party: what a capsule says about the person", function()
	local PF = A:GetModule("partyframes")
	local f1, f2, f3, f4 = PF.frames[1], PF.frames[2], PF.frames[3], PF.frames[4]

	-- THE CROWN AND THE MARKER BOTH RIDE THE PIP, and the brief puts them in
	-- the same place on it. A leader who has also been marked is ordinary, so
	-- they get a corner each - and this is the check that says so, because the
	-- failure is not an error, it is one of them hidden under the other.
	_G.__raidTargets.party1 = 6
	fire("RAID_TARGET_UPDATE")
	check(f1.crown:IsShown() and f1.marker:IsShown(),
		"a marked leader shows both the crown and the mark")
	local _, _, crownAt = f1.crown:GetPoint()
	local _, _, markAt = f1.marker:GetPoint()
	check(crownAt ~= nil and markAt ~= nil and crownAt ~= markAt,
		"and they sit on different corners of the pip (" ..
		tostring(crownAt) .. " vs " .. tostring(markAt) .. ")")

	-- THE MARK IS THE GAME'S OWN ART. A skull is a skull on every skin, and
	-- the texcoord is half of what makes it the right one - a marker with the
	-- texture and no coords draws the whole sheet of eight.
	check(tostring(f1.marker.__tex):find("RaidTargetingIcons", 1, true) ~= nil,
		"from the client's own icon sheet (" .. tostring(f1.marker.__tex) .. ")")
	local l, r, t2, b = f1.marker:GetTexCoord()
	check(not (l == 0 and r == 1 and t2 == 0 and b == 1),
		"with a cell picked out of it, not the whole sheet")
	_G.__raidTargets.party1 = nil
	fire("RAID_TARGET_UPDATE")
	check(not f1.marker:IsShown(), "and it goes when the mark is cleared")

	-- ONLY TANK AND HEALER WEAR A GLYPH. The brief draws an arrow for dps
	-- too, and in a five-man that is an arrow on four capsules out of four
	-- - a mark every member wears tells you nothing about any of them. It
	-- is also unavoidable here: this client answers DAMAGER for somebody
	-- who has never set a role at all, so the arrow was not reporting a
	-- choice, it was reporting the absence of one.
	check(f2.role:IsShown(), "a tank wears a glyph")
	check(f3.role:IsShown(), "and so does a healer")
	check(not f1.role:IsShown(),
		"but a damager wears nothing, which is what everybody else is (" ..
		tostring(UnitGroupRolesAssigned("party1")) .. ")")

	-- DEAD. The word goes in the health track, where the bar that emptied is,
	-- and the name stays legible - which is what you are reading the frame for.
	check(f3.deadText:IsShown(), "a dead member says so in the health track")
	check(f3.hpText:GetText() == "0", "with the number at zero")
	check(math.abs(f3:GetAlpha() - 0.6) < 0.01,
		"and the capsule quietened (" .. tostring(f3:GetAlpha()) .. ")")

	-- AND A HEALER SEES SOMETHING TO DO ABOUT IT - keyed off CLASS, not off
	-- role. The brief shows this glyph to healers, but a role here is opt-in,
	-- so keying off one would hide it from almost every priest in the game.
	-- WHICH GLYPH, not whether one is there. The dead member is a healer, so
	-- the slot is occupied either way and a check on IsShown would pass with
	-- the wrong drawing in it.
	local function isGlyph(tex, name)
		local _, l, r, t2, b = A.Media:Icon(name)
		local L, R, T2, B = tex:GetTexCoord()
		return math.abs(L - l) < 0.001 and math.abs(R - r) < 0.001
			and math.abs(T2 - t2) < 0.001 and math.abs(B - b) < 0.001
	end
	check(isGlyph(f3.role, "healer"),
		"a mage sees the dead healer's own glyph, and nothing to do")
	_G.__units.player.classToken = "PRIEST"
	fire("GROUP_ROSTER_UPDATE")
	check(isGlyph(f3.role, "resurrect"),
		"and a priest sees a resurrect glyph in its place - on class rather"
		.. " than on a role nobody sets")
	_G.__units.player.classToken = "MAGE"
	fire("GROUP_ROSTER_UPDATE")

	-- OFFLINE is quieter still, and says what it is where the class was.
	check(math.abs(f4:GetAlpha() - 0.5) < 0.01,
		"somebody offline is quieter than somebody dead (" ..
		tostring(f4:GetAlpha()) .. ")")
	check(f4.class:GetText() ~= "Mage",
		"and the line under the name says so (" .. tostring(f4.class:GetText()) .. ")")
end)

section("party: the crown is on your own capsule too", function()
	local UFm = A:GetModule("unitframes")
	local PF = A:GetModule("partyframes")
	local me = UFm.player

	-- IF YOU LEAD THE GROUP, the frame you look at most is the one that should
	-- say so. It did not, and every party capsule could.
	check(me.crown ~= nil, "the player capsule has a crown")
	_G.__units.player.leader = false
	fire("PARTY_LEADER_CHANGED")
	check(not me.crown:IsShown(), "hidden when somebody else is running it")
	_G.__units.player.leader = true
	fire("PARTY_LEADER_CHANGED")
	check(me.crown:IsShown(), "and there the moment you are")

	-- ONE CROWN, TWO USERS. W.CreateCrown draws it for the player's capsule and
	-- for every party capsule, so there is one answer to where it sits and what
	-- colour it is - and the second copy is always the one that gets forgotten
	-- when the first moves.
	local _, _, mineAt = me.crown:GetPoint()
	local _, _, theirsAt = PF.frames[1].crown:GetPoint()
	check(mineAt == theirsAt,
		"and it rides the same corner on both (" .. tostring(mineAt) .. ")")

	-- TINTED BY TOKEN, not by hand. This is the reserved semantic gold and Dusk
	-- is the one skin that moves it - so a crown coloured with a copied table
	-- would still be Midnight's gold after a skin change.
	check(A.Widgets.tinted[me.crown] ~= nil or me.crown._aetherTint ~= nil,
		"the crown follows the skin, rather than keeping the colour it was"
		.. " built with")
end)

section("decorators: four corners of the level disc, everywhere there is one", function()
	local PF = A:GetModule("partyframes")
	local UFm = A:GetModule("unitframes")
	local f1 = PF.frames[1]

	-- A DECORATOR IS NOT PART OF THE LAYOUT. Who leads, what somebody is
	-- marked with, what they do and whether they are flagged all answer the
	-- same question - who is this - and the disc with their level in it is
	-- where that is already answered. So they ride the disc, one to a corner,
	-- and cost the capsule no width.
	--
	-- The role glyph used to have a well of its own at the far right with the
	-- width reserved for it on every member, which was a strip of empty glass
	-- on most capsules.
	local corners = {}
	for _, key in ipairs({ "crown", "marker", "role", "pvp" }) do
		local tex = f1[key]
		check(tex ~= nil, "the party capsule has a " .. key .. " decorator")
		local _, rel, at = tex:GetPoint()
		check(rel == f1.pip,
			key .. " rides the level pip, not the capsule (" .. tostring(at) .. ")")
		check(corners[at] == nil,
			key .. " has a corner to itself (" .. tostring(at) .. " also held by " ..
			tostring(corners[at]) .. ")")
		corners[at] = key

		-- ABOVE THE DISC, WHICH IS THE WHOLE POINT. The pip is a CHILD
		-- FRAME of the glass, and a child frame draws over every one of
		-- its parent's regions whatever layer they claim. A decorator
		-- drawn as a region of the glass therefore had its lower half
		-- behind the pip - the crown survived only because it hangs
		-- outside the pip's bounds, which is exactly why one of them
		-- looked right and the raid mark was invisible.
		local host = tex:GetParent()
		check(host ~= nil and host:GetFrameLevel() > f1.pip:GetFrameLevel(),
			key .. " is drawn ABOVE the pip, not behind it (" ..
			tostring(host and host:GetFrameLevel()) .. " vs " ..
			tostring(f1.pip:GetFrameLevel()) .. ")")
	end

	-- THE SAME ARRANGEMENT ON YOUR OWN CAPSULE. The orb is the player frame's
	-- level disc, and a mark that means one thing on a party member must not
	-- mean it somewhere else on you.
	for _, key in ipairs({ "crown", "marker", "pvp", "role" }) do
		local mine = UFm.player[key]
		check(mine ~= nil, "the player capsule has a " .. key .. " too")
		local _, _, mineAt = mine:GetPoint()
		local _, _, theirsAt = f1[key]:GetPoint()
		check(mineAt == theirsAt,
			key .. " on the same corner as theirs (" .. tostring(mineAt) .. ")")
	end

	-- A ROLE CHECK ANSWERS ON YOUR OWN FRAME TOO. It did not: every party
	-- capsule wore the answer to a poll and the player's said nothing, because
	-- the decorator was never built there - and because nothing in either
	-- module listened to PLAYER_ROLES_ASSIGNED, so the answer landed and no
	-- frame moved until something unrelated happened to refresh it.
	_G.__roles.player = "HEALER"
	fire("PLAYER_ROLES_ASSIGNED")
	check(UFm.player.role:IsShown(),
		"a role check reaches your own capsule")
	local function isGlyph2(tex, name)
		local _, l, r, t2, b = A.Media:Icon(name)
		local L, R, T2, B = tex:GetTexCoord()
		return math.abs(L - l) < 0.001 and math.abs(R - r) < 0.001
			and math.abs(T2 - t2) < 0.001 and math.abs(B - b) < 0.001
	end
	check(isGlyph2(UFm.player.role, "healer"),
		"and wears the one it was given")
	_G.__roles.player = "TANK"
	fire("PLAYER_ROLES_ASSIGNED")
	check(isGlyph2(UFm.player.role, "tank"),
		"and changes when the answer does")
	_G.__roles.player = nil
	fire("PLAYER_ROLES_ASSIGNED")
	check(not UFm.player.role:IsShown(),
		"and goes when there is no role worth showing - which on this client"
		.. " is what a DAMAGER is")

	-- THE DOCK ARROW IS THE INTERFACE'S OWN COLOUR, not the brief's gold. The
	-- Toolbox rail's chevron is the same control on the same screen edge doing
	-- the same job, and it is plain text - two docks whose arrows disagree is a
	-- detail nobody can name and everybody sees.
	local PFm = A:GetModule("partyframes")
	PFm:BuildHandle()
	-- W.tinted is a LIST of textures, not a map keyed by one - the token a
	-- texture was coloured with lives on the texture. Asking the list for a
	-- key it does not have answers nil, and nil is not "semanticGold", so the
	-- first version of this check passed with the gold still on it.
	local tint = PFm.handle.chev._aetherTint
	check(tint == "text",
		"the dock handle's arrow is the interface's own type colour, not the"
		.. " reserved gold (" .. tostring(tint) .. ")")
	local TBm = A:GetModule("toolbox")
	if TBm and TBm.rail and TBm.rail.chev then
		local r1 = { PFm.handle.chev:GetVertexColor() }
		local r2 = { TBm.rail.chev.glyph:GetVertexColor() }
		check(math.abs(r1[1] - r2[1]) < 0.01 and math.abs(r1[2] - r2[2]) < 0.01
			and math.abs(r1[3] - r2[3]) < 0.01,
			"and is the same colour as the Toolbox rail's")
	end
	-- THE FLAG IS THE CLIENT'S OWN FACTION ART, untinted - faction identity is
	-- the game's, like a class colour and like the raid marks.
	local f2 = PF.frames[2]
	check(f2.pvp:IsShown(), "a flagged member wears the crest")
	check(tostring(f2.pvp.__tex):find("UI%-PVP%-Horde") ~= nil,
		"in their own faction's art (" .. tostring(f2.pvp.__tex) .. ")")
	check(not f1.pvp:IsShown(), "and an unflagged one wears nothing")

	-- TWO CALLS, NOT ONE. A Neutral unit can be flagged and has no crest to
	-- draw, and asking for UI-PVP-Neutral gets a file the client has not got -
	-- which draws as nothing at all, silently.
	_G.__units.party1.pvp = true
	_G.__units.party1.faction = "Neutral"
	fire("GROUP_ROSTER_UPDATE")
	check(not f1.pvp:IsShown(),
		"a flagged Neutral asks for no texture rather than a missing one")
	_G.__units.party1.faction = "Horde"
	_G.__units.party1.pvp = false
	fire("GROUP_ROSTER_UPDATE")
end)

section("party: the numbers, and the colour they are not", function()
	local PF = A:GetModule("partyframes")
	local f2 = PF.frames[2]
	local c = A.Palette.c

	-- THE HURT NUMBER IS NOT THE WARNING GOLD. The brief turns it gold as a
	-- member gets hurt, which is the reserved semantic gold carried by hue
	-- alone on a number - the one thing its own companion rule forbids - and on
	-- Dusk that gold is a step from the chrome. The bar beside it is already
	-- shrinking and already going green to red.
	local function same(a, b)
		return math.abs(a[1] - b[1]) < 0.002 and math.abs(a[2] - b[2]) < 0.002
			and math.abs(a[3] - b[3]) < 0.002
	end
	local ink = f2.hpText._aetherInk
	check(ink ~= nil, "the health number is coloured by token")
	check(not same(c[ink] or c.text, c.semanticGold),
		"a member on 39% is not written in the warning gold (" ..
		tostring(ink) .. ")")

	-- IT DOES GO RED, though, when it is nearly over - which is the part of the
	-- brief that was carrying real information.
	_G.__units.party2.hp = 100
	fire("UNIT_HEALTH", "party2")
	check(f2.hpText._aetherInk == "danger",
		"and it does go red at a tenth (" ..
		tostring(f2.hpText._aetherInk) .. ")")
	_G.__units.party2.hp = 386
	fire("UNIT_HEALTH", "party2")
end)

section("party: a slot that empties does not move the others", function()
	local PF = A:GetModule("partyframes")
	local f2, f3 = PF.frames[2], PF.frames[3]

	-- FIXED SLOTS, and this is the reason for them. Re-anchoring a frame with a
	-- secure child is refused in combat, and somebody dropping group mid-pull
	-- is exactly when a growing stack would want to re-anchor. So a slot that
	-- empties leaves a gap, and every other capsule stays where it was put.
	local _, _, _, _, beforeY = f3:GetPoint()
	_G.__units.party2.exists = false
	fire("GROUP_ROSTER_UPDATE")
	check(not f2.glass:IsShown(), "an empty slot draws nothing")
	local _, _, _, _, afterY = f3:GetPoint()
	check(afterY == beforeY,
		"and the capsule below it has not moved (" ..
		tostring(beforeY) .. " -> " .. tostring(afterY) .. ")")
	_G.__units.party2.exists = true
	fire("GROUP_ROSTER_UPDATE")
	check(f2.glass:IsShown(), "and it comes back into its own slot")

	-- NOT IN A FIGHT. SetSize on a frame carrying a secure button is refused
	-- while the lockdown is on, so a config change waits - it is worth nothing
	-- to anybody mid-pull anyway.
	-- A ROSTER CHANGE MID-FIGHT. Somebody dying, releasing or dropping
	-- group is exactly when a stack that re-flowed would want to
	-- re-anchor, and exactly when the client refuses. Fixed slots mean
	-- there is nothing to re-anchor, so this is a no-op rather than four
	-- blocked calls and a frame left where it fell.
	_G.__inCombat = true
	local blocked = _G.__blocked
	_G.__units.party3.exists = false
	fire("GROUP_ROSTER_UPDATE")
	check(_G.__blocked == blocked,
		"a member leaving mid-fight blocks nothing (" ..
		(_G.__blocked - blocked) .. " refused calls)")
	_G.__units.party3.exists = true
	fire("GROUP_ROSTER_UPDATE")

	local w = A.Config:Module("partyframes").width
	A.Config:Module("partyframes").width = 400
	PF:OnConfigChanged()
	check(math.abs(PF.frames[1]:GetWidth() - w) < 0.5,
		"a width change in combat is not applied, rather than erroring (" ..
		tostring(PF.frames[1]:GetWidth()) .. ")")
	_G.__inCombat = false
	PF:OnConfigChanged()
	check(math.abs(PF.frames[1]:GetWidth() - 400) < 0.5,
		"and lands the moment the fight is over")
	A.Config:Module("partyframes").width = w
	PF:OnConfigChanged()

	A:SetModuleEnabled("partyframes", false)
	check(not PF.stack:IsShown(), "switching it off takes the stack away")
	check(not PF.frames[1].click:IsShown(),
		"and the click buttons with it")
	check(_G.__unitWatched[PF.frames[1].click] == nil,
		"with the unit watch OFF, not just the button hidden - the state"
		.. " driver owns that visibility and would put it straight back,"
		.. " and a button you cannot see still steals your target")
end)

section("panels: the main menu is a column of buttons, not a column of glass", function()
	local PN = A:GetModule("panels")
	local gm = _G.GameMenuFrame
	gm:Show()

	-- BLIZZARD SETS SPACING TO ZERO and it looks right, because its button art
	-- carries a transparent margin - the rows read as separated while the frames
	-- touch. Ours is a drawn rectangle with no margin at all, so at zero the
	-- buttons meet edge to edge and the menu is one slab of glass with lines of
	-- text in it.
	check(gm.spacing and gm.spacing > 0,
		"the menu is given room between its buttons (" ..
		tostring(gm.spacing) .. ")")

	-- AND ROOM UNDER THE TITLE. The template leaves 32, which the header sits
	-- in, so the first button lands against the words.
	check(gm.topPadding and gm.topPadding > 32,
		"and room under its title (" .. tostring(gm.topPadding) .. ")")

	-- LAID OUT AGAIN, or the numbers above are ones nobody has read. This is a
	-- VerticalLayoutFrame: it reads them off itself when it lays out, and it
	-- only lays out when something says it is dirty.
	local gap = nil
	local a, b = gm.__menuButtons[1], gm.__menuButtons[2]
	if a and b and a.__layoutY and b.__layoutY then
		gap = (a.__layoutY - b.__layoutY) - (a:GetHeight() or 0)
	end
	check(gap and gap > 0,
		"and the layout has actually run, so there is a gap on screen rather"
		.. " than a number in a table (" .. tostring(gap) .. ")")

	-- AND THE BUTTONS ARE OURS. The spacing and the skin are two different
	-- jobs on the same pass, and a menu that is correctly spaced and still
	-- red is what you get when only one of them ran.
	local red = 0
	for _, b in ipairs(gm.__menuButtons) do
		if not b.__aetherSkin then red = red + 1 end
	end
	check(red == 0, "every button on it wears our surface (" .. red ..
		" still the client's)")

	-- AND A BUTTON THE POOL MINTS LATER IS DRESSED TOO. InitButtons is
	-- called on OnShow and again on the client's own events, AFTER the hook
	-- that dressed the window - so a button acquired on one of those later
	-- passes has never been dressed, and the menu comes back red with no
	-- error anywhere.
	gm.__menuButtons[#gm.__menuButtons + 1] = (function()
		local b = CreateFrame("Button", nil, gm)
		b:SetSize(180, 26)
		b:SetText("Support")
		return b
	end)()
	gm:InitButtons()
	local late = 0
	for _, b in ipairs(gm.__menuButtons) do
		if not b.__aetherSkin then late = late + 1 end
	end
	check(late == 0,
		"a button the pool mints after the window opened is dressed too (" ..
		late .. " missed)")
	gm:Hide()
end)

section("panels: the postbox, the book and the trade skills", function()
	local PN = A:GetModule("panels")
	for _, n in ipairs({ "MailFrame", "ItemTextFrame", "TradeSkillFrame",
		"CraftFrame" }) do
		_G[n]:Show()
	end
	PN:Skin()

	local W = A.Widgets
	-- A ROW OF ITS OWN, under the band rather than in it.
	--
	-- These are the things that act on what the window is SHOWING - a filter, a
	-- rank bar. Chrome, so not in the recess; but a band is one line of type
	-- wide and they do not fit beside a title either. The trade skill proved
	-- it: its rank bar is three hundred across and its two filters landed
	-- straight on top of it.
	local ts = _G.TradeSkillFrame
	local rank = _G.TradeSkillRankFrame
	-- HOW FAR ALONG YOU ARE IS CONTENT, not chrome. A filter changes what the
	-- list is showing; a bar says how far along the thing IN it you are, and
	-- there can be several - first aid, fishing, riding. So it goes in the
	-- recess WITH the list, under the All switch, and the well reaches up over
	-- both of them rather than leaving them on bare glass between two wells.
	local listWell = _G.TradeSkillListScrollFrame.__aetherWell
	local rp, rrel = rank:GetPoint(1)
	check(rp == "TOPLEFT" and rrel == _G.TradeSkillCollapseAllButton,
		"the rank bar hangs under the All switch (" .. tostring(rp) .. " on " ..
		tostring(rrel and rrel.GetName and rrel:GetName()) .. ")")
	local ap, arel, arelP, ax, ay = _G.TradeSkillCollapseAllButton:GetPoint(1)
	check(ap == "TOPLEFT" and arel == listWell and arelP == "TOPLEFT"
		and ax == W.WELL_PAD and ay == -W.WELL_PAD,
		"and All sits inside the list's own well at its padding (" ..
		tostring(ax) .. ", " .. tostring(ay) .. ")")
	check(rank.__aetherFill ~= nil,
		"and the bar is one of ours rather than the client's blue")

	-- AND THE WELL REACHES UP OVER BOTH OF THEM, so they are inside the recess
	-- rather than above it - which is the whole point: several bars is a column
	-- of content, not a status line in the chrome.
	-- OVER THE CONTROLS, not merely past the list by the rim it always had.
	-- The measure is the All switch: the well has to reach its own padding
	-- above it, or the switch is sitting on bare glass with a recess under it.
	local sf = _G.TradeSkillListScrollFrame
	-- MEASURED AGAINST THE LIST, which is anchored to the WINDOW - not against
	-- the well, which the controls themselves hang off. Comparing the two
	-- things that move together proves nothing: they move together.
	--
	-- The bar is the last of them, so if IT clears the top of the list then the
	-- room reserved really does match what was put in it.
	check(rank:GetBottom() and sf:GetTop()
		and rank:GetBottom() >= sf:GetTop() - 0.5,
		"the bar and the switch above it fit in the room reserved, clear of the"
		.. " first recipe (bar ends at " ..
		string.format("%.0f", rank:GetBottom() or 0) .. ", list starts at " ..
		string.format("%.0f", sf:GetTop() or 0) .. ")")

	-- ...AND ONLY THAT PANE MOVES DOWN FOR IT. The detail pane beside it has
	-- no controls over it and must not travel to match: room reserved for the
	-- window rather than for the pane would have left a hand's width of nothing
	-- above the recipe you are reading.
	-- MEASURED AS A SHIFT, not as a position: the client starts these two at
	-- different heights, so where they end up says nothing on its own. What
	-- each was moved BY is the question, and the originals are the anchors the
	-- mover recorded before it touched them.
	local function moved(pane)
		local pts = pane.__aetherPts
		local was = pts and pts[1] and (pts[1][5] or 0)
		local now = select(5, pane:GetPoint(1))
		return was and now and (was - now) or 0
	end
	local listShift = moved(sf)
	local detailShift = moved(_G.TradeSkillDetailScrollFrame)
	check(listShift > detailShift,
		"and only the list moves down for the room, not the detail beside it -"
		.. " which has no controls over it and would have worn a hand's width of"
		.. " nothing above the recipe (" .. string.format("%.0f", listShift) ..
		" against " .. string.format("%.0f", detailShift) .. ")")
	check(rank._aetherStyle == nil and rank.__color == nil,
		"and is placed without being handed to the font setter or painted in"
		.. " a subtitle's ink, neither of which a status bar answers")
	check(PN.HeaderHeight("TradeSkillFrame") == W.PANEL_HEAD_H,
		"and the band stays the plain height, because the row is not in it")

	local dd = _G.TradeSkillFrame.InvSlotDropdown
	-- AND THE FILTERS SIT OVER THE PANE THEY FILTER. They change what the list
	-- shows and the list is what the detail is read from, so they belong above
	-- the RIGHT-hand recess and nowhere else: across the whole window in a tool
	-- row they read as being about the window.
	local detailWell = _G.TradeSkillDetailScrollFrame.__aetherWell
	local dp, drel, drelP, _, dy = dd:GetPoint(1)
	check(dp == "BOTTOMRIGHT" and drel == detailWell and drelP == "TOPRIGHT"
		and dy == W.PANEL_GAP,
		"the slot filter sits on the detail recess's top corner (" ..
		tostring(dp) .. " -> " .. tostring(drelP) .. " at " ..
		string.format("%.0f", dy or 0) .. ")")
	local d2p, d2rel = _G.TradeSkillFrame.SubClassDropdown:GetPoint(1)
	check(d2p == "RIGHT" and d2rel == dd,
		"and a second runs leftward from the first rather than over it")

	-- ...AND THE RECESS UNDER THEM STARTS LOWER TO MAKE ROOM. Reserved for that
	-- pane alone: the list on the other side has its own controls and its own
	-- headroom, and one number for the window would have moved both.
	-- MEASURED AS A SHIFT AGAINST THE PANE BESIDE IT, not against the well the
	-- filters hang off: those two move together and comparing them proves
	-- nothing. The client starts these two panes level, so the right-hand one
	-- moving further down IS the room being reserved for the filters over it.
	local detailShift2 = moved(_G.TradeSkillDetailScrollFrame)
	check(detailShift2 >= 26 + W.PANEL_GAP,
		"and the recess under them starts lower to make room, reserved for that"
		.. " pane alone (" .. string.format("%.0f", detailShift2) .. ")")

	-- ITS RECIPES GO IN ITS LIST, and they were not in it. Same shape as the
	-- trainer: a faux scroll frame is the BAR and nothing else, so the client
	-- hangs the rows off the WINDOW - and the list moved into the recess and
	-- left every recipe printed on the glass above an empty box.
	-- Wherever the client happened to put it relative to the list, which is
	-- what the mover records and puts back: the point is that it hangs off the
	-- LIST now rather than off the window, so it travels with it.
	local sp, srel, srelP = _G.TradeSkillSkill1:GetPoint(1)
	check(sp == "TOPLEFT" and srel == _G.TradeSkillListScrollFrame
		and srelP == "TOPLEFT",
		"the first recipe hangs off the LIST (" .. tostring(sp) .. " on " ..
		tostring(srel and srel.GetName and srel:GetName()) .. ")")
	local cp, crel = _G.Craft1:GetPoint(1)
	check(cp == "TOPLEFT" and crel == _G.CraftListScrollFrame,
		"and so does enchanting's, which is the same window under a second set"
		.. " of names")

	-- CREATE ALL, CREATE AND CLOSE, centred in the footer strip. The client
	-- puts all three 422 down from the window's TOPLEFT, in a frame that is no
	-- longer that tall, so they lay across the foot of both recesses.
	-- AND THE COUNT SPINNER IS IN THE ROW WITH THEM. How many to make is part
	-- of making them: left out of the strip it stayed where the client had put
	-- it, which is on top of Create.
	local sGap = 12
	local strip = { _G.TradeSkillCreateAllButton, _G.TradeSkillDecrementButton,
		_G.TradeSkillInputBox, _G.TradeSkillIncrementButton,
		_G.TradeSkillCreateButton, _G.TradeSkillCancelButton }
	local total, placed = -sGap, 0
	for _, w in ipairs(strip) do
		total = total + (w:GetWidth() or 0) + sGap
		if select(1, w:GetPoint(1)) == "LEFT" then placed = placed + 1 end
	end
	check(placed == #strip,
		"every control in the footer strip is laid out by the row, spinner"
		.. " included (" .. placed .. " of " .. #strip .. ")")
	-- CENTRED AS ONE GROUP, whatever order the client happened to leave them
	-- in: the row is laid out left to right from where they already were, so
	-- the leftmost of them starts half the group's width left of the middle.
	local first, edge, height
	for _, w in ipairs(strip) do
		local x, y = select(4, w:GetPoint(1))
		if not first or x < first then first = x end
		local ends = x + (w:GetWidth() or 0)
		if not edge or ends > edge then edge = ends end
		height = y
	end
	check(first == -total / 2 and edge == total / 2,
		"and the group is centred on the strip, from half its width left of the"
		.. " middle to half its width right (" .. tostring(first) .. " to " ..
		tostring(edge) .. " of " .. tostring(total) .. ")")
	check(height == W.PANEL_FOOT_H / 2,
		"on the strip's own line (" .. tostring(height) .. ")")

	-- AND ENCHANTING'S STRIP IS A PAIR, because that window has no Create All -
	-- so the group is narrower and centred on its own width rather than on the
	-- other window's.
	local cPair = 80 * 2 + sGap
	check(select(4, _G.CraftCreateButton:GetPoint(1)) == -cPair / 2,
		"the craft window centres the two it has (" ..
		tostring(select(4, _G.CraftCreateButton:GetPoint(1))) .. ")")

	-- AND THE LISTS STOP ABOVE THE STRIP. There is no recess of ours round
	-- these - each carries one of its own - so nothing was keeping them off the
	-- footer, and both ran forty units past the hairline with their rims under
	-- Create and Close.
	do
		local rule = ts.__aetherFootRule
		-- The strip's own top edge, which is the hairline's BOTTOM: the line has
		-- a thickness of its own and it is a fraction of a unit, so measuring
		-- from its top puts the answer half a pixel out.
		local floorY = rule and rule:GetBottom()
		local over = {}
		for _, n in ipairs({ "TradeSkillListScrollFrame",
			"TradeSkillDetailScrollFrame" }) do
			local pane = _G[n]
			local low = pane and pane:GetBottom()
			-- The well is drawn WELL_OUTSET outside the pane, so it is the pane's
			-- bottom plus that which has to clear the body's floor.
			if low and floorY
				and low - W.WELL_OUTSET < floorY + W.PANEL_PAD - 0.5 then
				over[#over + 1] = n
			end
		end
		check(floorY ~= nil and #over == 0,
			"neither list runs its recess down into the footer strip (" ..
			(#over > 0 and table.concat(over, ", ") or "both clear") .. ")")
	end

	-- WHICH RECIPE YOU ARE ON, in our ink. Neither crafting window touched its
	-- highlight frame at all, so Blizzard's blue listbox slice lay across our
	-- glass on whatever you had picked.
	check(_G.TradeSkillHighlight:GetTexture() == 0
		and _G.TradeSkillHighlightFrame.__aetherRowMark ~= nil,
		"the recipe list marks the picked row with our own wash")


	-- THE STRIP HAS A FOOT. 15a bounds it above the way the band is bounded
	-- below; without it the actions read as floating in the glass under the
	-- recesses rather than standing in a strip.
	local tsRule = ts.__aetherFootRule
	check(tsRule ~= nil and tsRule:IsShown()
		and tsRule:GetParent() == ts.__aetherChrome,
		"the trade skill window's footer has a hairline, on the chrome layer")

	-- AND THE LISTS CLEAR IT. A row nothing made room for is a row drawn on
	-- top of the first recipe.
	local sf = _G.TradeSkillListScrollFrame
	local floor = W.PANEL_HEAD_H + W.PANEL_PAD + W.WELL_PAD + 28 + W.PANEL_GAP
	check(-(select(5, sf:GetPoint(1)) or 0) + (sf.__aetherTop or 0) >= floor,
		"the lists are moved down past the row rather than under it (" ..
		string.format("%.0f", -(select(5, sf:GetPoint(1)) or 0)
		+ (sf.__aetherTop or 0)) .. " against " .. floor .. ")")

	-- ONE RECESS DEEP. Both of this window's lists are wells in their own
	-- right, so a body well behind them is a second rim round the first and a
	-- second helping of the same black - twice as deep wherever they overlap,
	-- which is everywhere.
	check(not (ts.__aetherBody and ts.__aetherBody:IsShown()),
		"and there is no recess drawn round the pair of them")
	check(_G.CharacterFrame.__aetherBody:IsShown(),
		"while a window whose content is bare still gets one")

	-- ALL FOUR GET THE GLASS. Three windows a player opens constantly - the
	-- postbox, a letter out of the bags, and every trade skill - and none of
	-- them was in this mock, so none of them could be checked and all of them
	-- shipped in stone.
	for _, n in ipairs({ "MailFrame", "ItemTextFrame", "TradeSkillFrame",
		"CraftFrame" }) do
		check(_G[n].__aetherPanel ~= nil,
			n .. " has glass behind it")
	end

	-- THE BOOK'S PAGE IS FOUR NAMED TEXTURES, not one, and not regions of
	-- anything the shell sweep walks. Miss them and the parchment stays exactly
	-- where it was with our glass behind it.
	local left = 0
	for _, n in ipairs({ "ItemTextMaterialTopLeft", "ItemTextMaterialTopRight",
		"ItemTextMaterialBotLeft", "ItemTextMaterialBotRight" }) do
		if _G[n]:IsShown() then left = left + 1 end
	end
	check(left == 0, "the letter's parchment is gone (" .. left .. " left)")

	-- ITS PAGE GOES IN THE RECESS, and its page turns go in the strip. The
	-- client puts the scroll frame 63 down - the room the stone title plate
	-- needed - and hangs a turn off each TOP corner of the window, 41 down,
	-- with the book's title between them and the count under it. 15c: a page
	-- turn is chrome and it lives in the footer, as a group.
	local itInner = W.PANEL_PAD + W.WELL_PAD
	local itSF = _G.ItemTextScrollFrame
	local _, _, _, itx, ity = itSF:GetPoint(1)
	check(-ity == W.PANEL_HEAD_H + itInner,
		"the page clears the band and sits in the well's padding (" ..
		tostring(-ity) .. ")")

	local pgGap = 12
	local pgBack, pgOn = _G.ItemTextPrevPageButton, _G.ItemTextNextPageButton
	local pgText = _G.ItemTextCurrentPage
	local pgTotal = pgBack:GetWidth() + pgText:GetStringWidth()
		+ pgOn:GetWidth() + pgGap * 2
	local pbp, pbrel, pbrelP, pbx, pby = pgBack:GetPoint(1)
	check(pbp == "LEFT" and pbrel == _G.ItemTextFrame.__aetherPanel
		and pbrelP == "BOTTOM" and pbx == -pgTotal / 2
		and pby == W.PANEL_FOOT_H / 2,
		"the turn back starts the group, centred in the footer strip (" ..
		tostring(pbx) .. ", " .. tostring(pby) .. ")")
	check(select(4, pgOn:GetPoint(1))
		== -pgTotal / 2 + pgBack:GetWidth() + pgText:GetStringWidth()
			+ pgGap * 2,
		"and the turn on ends it, a gap past the count - which is measured by"
		.. " its words rather than by the 192-wide box the client reserved (" ..
		tostring(select(4, pgOn:GetPoint(1))) .. ")")

	-- AND ITS WORDS ARE LIFTED. Printed near-black because they were printed
	-- on paper; on glass that is a dark smudge.
	local r = select(1, _G.ItemTextPageText:GetTextColor())
	check(r and r > 0.5,
		"and its words are lifted off the near-black they were printed in (" ..
		string.format("%.2f", r or 0) .. ")")

	-- EVERY TEXT TYPE IT HAS, not just the body. A letter's headings are a
	-- SimpleHTML's H1 to H3 and they are printed in the same near-black -
	-- "Horde Conscription Registration" at the top of a recruitment letter
	-- is one, and it stayed dark while the paragraphs came right.
	local darkTypes = {}
	for _, kind in ipairs({ "P", "H1", "H2", "H3" }) do
		local hr = select(1, _G.ItemTextPageText:GetTextColor(kind))
		if not hr or hr < 0.5 then darkTypes[#darkTypes + 1] = kind end
	end
	check(#darkTypes == 0,
		"and so are its headings (" ..
		(#darkTypes > 0 and table.concat(darkTypes, ",") or "all lifted")
		.. ")")

	-- The letter you are writing is on the same paper.
	local pane = _G.SendMailFrame
	local dark = 0
	for _, reg in ipairs({ pane:GetRegions() }) do
		if reg.GetObjectType and reg:GetObjectType() == "FontString" then
			local rr = select(1, reg:GetTextColor())
			if rr and rr < 0.5 then dark = dark + 1 end
		end
	end
	check(dark == 0, "the letter you are writing is lifted too (" .. dark .. ")")

	-- THE PAGE ITSELF is a ScrollingEditBox with its parchment in its OWN
	-- background layer and its bar as a frame beside it - neither is a region
	-- of the pane, so a sweep of SendMailFrame reaches neither and the letter
	-- stays gold behind our glass.
	local paper = 0
	for _, r in ipairs({ _G.MailEditBox:GetRegions() }) do
		if r.__tex and tostring(r.__tex):find("Stationery", 1, true)
			and r:IsShown() then paper = paper + 1 end
	end
	check(paper == 0, "the letter's own parchment comes off (" .. paper .. ")")
	check(_G.MailEditBoxScrollBar.__aetherScroll == true,
		"and the bar beside it is ours")
	local er = select(1, _G.MailEditBox:GetEditBox():GetTextColor())
	check(er and er > 0.5,
		"and what you type is lifted off the paper it was written for (" ..
		string.format("%.2f", er or 0) .. ")")

	-- THE PANE'S OWN TITLE is not the window's. Inbox and Send Mail each
	-- carry one in the client's gold, under a window title that already
	-- names the thing - two words on screen saying it in two colours.
	local goldTitles = {}
	for _, n in ipairs({ "InboxTitleText", "SendMailTitleText" }) do
		local tr, tg = _G[n]:GetTextColor()
		if tr == 1 and tg and tg < 0.9 then
			goldTitles[#goldTitles + 1] = n
		end
	end
	check(#goldTitles == 0,
		"the pane titles are in our own ink (" ..
		(#goldTitles > 0 and table.concat(goldTitles, ",") or "both") .. ")")

	-- AND ONE OF THEM IS THE WINDOW'S TITLE. This frame's own $parentTitleText
	-- is never filled in, so the band had nothing to say - while the words that
	-- name the tab you are on sat inside the pane in the client's gold.
	local mf = _G.MailFrame
	check(mf.__aetherTitle == _G.InboxTitleText,
		"the window is titled by the tab it is showing (" ..
		tostring(mf.__aetherTitle and mf.__aetherTitle:GetText()) .. ")")
	local mp, mrel = _G.InboxTitleText:GetPoint(1)
	check(mp == "TOP" and mrel == mf.__aetherPanel,
		"centred in the header band like every other window's")
	_G.InboxFrame:Hide()
	_G.SendMailFrame:Show()
	_G.PanelTemplates_UpdateTabs(mf)
	check(mf.__aetherTitle == _G.SendMailTitleText,
		"and it follows the tab (" ..
		tostring(mf.__aetherTitle and mf.__aetherTitle:GetText()) .. ")")

	-- AND THE STRIP LAYS OUT FOR THE PANE THAT IS UP. The second row is the
	-- INBOX's - Open All is a child of that pane - so on Send Mail there is
	-- nothing in it, and a strip that always splits itself in two put Send and
	-- Cancel in the upper half with an empty row's worth of glass beneath.
	--
	-- The strip's HEIGHT does not follow the pane: it is the declared count,
	-- so the window is the same size on both tabs rather than jumping 26 every
	-- time you change your mind about what you are doing.
	local sfloor = mf.__aetherPanel:GetBottom()
	local srule = mf.__aetherFootRule and mf.__aetherFootRule:GetBottom()
	local mid = (_G.SendMailMailButton:GetTop() + _G.SendMailMailButton:GetBottom()) / 2
	check(srule and math.abs((srule - sfloor) - A.Widgets.PANEL_FOOT_H * 1.5) < 0.5,
		"the strip stays the depth it was on the other tab (" ..
		string.format("%.1f", (srule or 0) - sfloor) .. ")")
	check(math.abs((mid - sfloor) - (srule - sfloor) / 2) < 0.5,
		"with Send and Cancel centred in it rather than in half of it (" ..
		string.format("%.1f", mid - sfloor) .. " of " ..
		string.format("%.1f", srule - sfloor) .. ")")

	_G.SendMailFrame:Hide()
	_G.InboxFrame:Show()
	_G.PanelTemplates_UpdateTabs(mf)

	-- The page turners, which are art rather than words.
	local stone = 0
	for _, n in ipairs({ "InboxPrevPageButton", "InboxNextPageButton" }) do
		local tex = _G[n].GetNormalTexture and _G[n]:GetNormalTexture()
		if tex and tostring(tex:GetTexture() or ""):find("Interface", 1, true) then
			stone = stone + 1
		end
	end
	check(stone == 0, "and the page turners have lost their plates (" ..
		stone .. ")")

	-- THE TABS HANG BELOW THE FRAME, and the money row runs right down to
	-- its bottom edge - so at the client's own 30 the two overlap. They do
	-- in the client too; its bottom border is drawn over the join and hides
	-- it, and taking that border off is what makes it visible.
	local _, rel, at, _, ty = _G.MailFrameTab1:GetPoint()
	check(rel == _G.MailFrame and at == "BOTTOMLEFT",
		"the tabs hang off the window's bottom edge")
	check(ty and ty <= -38,
		"far enough below it to clear the money row (" .. tostring(ty) ..
		", the client's own is -30)")

	-- AND THE GLASS FOLLOWS THEM DOWN, or they sit outside it.
	local entry = PN.ENTRY.MailFrame
	check(entry.insets and entry.insets[4] <= ty,
		"and the glass reaches past them (" .. tostring(entry.insets[4]) ..
		" vs " .. tostring(ty) .. ")")

	-- THE FIELDS. Every text box in the game is the same three slices of
	-- Common-Input-Border drawn as BACKGROUND regions of the box itself -
	-- nothing to swap, and nothing a sweep of the pane ever reaches.
	local stoneFields, wellless = {}, {}
	for _, n in ipairs({ "SendMailNameEditBox", "SendMailSubjectEditBox", "SendMailMoneyGold",
		"SendMailMoneySilver", "SendMailMoneyCopper" }) do
		local box = _G[n]
		for _, part in ipairs({ "Left", "Middle", "Right" }) do
			local tex = _G[n .. part]
			if tex and tex:IsShown() then stoneFields[#stoneFields + 1] = n .. part end
		end
		if not box.__aetherPill then wellless[#wellless + 1] = n end
	end
	check(#stoneFields == 0, "the fields have lost their borders (" ..
		(#stoneFields > 0 and table.concat(stoneFields, ",") or "all five") .. ")")
	check(#wellless == 0, "and every one has a well of ours instead (" ..
		(#wellless > 0 and table.concat(wellless, ",") or "all five") .. ")")

	-- AND THE COIN SURVIVES IT. It is in the same layer as the border, so
	-- the obvious sweep takes it too and the player is entering gold, silver
	-- and copper into three identical nameless boxes.
	local coins = 0
	for _, n in ipairs({ "SendMailMoneyGold", "SendMailMoneySilver",
		"SendMailMoneyCopper" }) do
		local coin = _G[n].texture
		if coin and coin:IsShown() and tostring(coin:GetTexture() or ""):find("MoneyIcons", 1, true) then
			coins = coins + 1
		end
	end
	check(coins == 3, "and each keeps its coin (" .. coins .. " of 3)")

	-- AND ALL THREE WEAR IT THE SAME WAY. The client hangs gold's 2 OUTSIDE
	-- the box and the other two 8 INSIDE, because its own border art stops ten
	-- short of the narrow pair and the overhang had to be filled. With that
	-- art gone and identical wells behind all three, the row came up with one
	-- coin clear of its field and two sitting in theirs.
	local offs, worst = {}, 0
	for _, n in ipairs({ "SendMailMoneyGold", "SendMailMoneySilver",
		"SendMailMoneyCopper" }) do
		local box = _G[n]
		offs[#offs + 1] = (box.texture:GetLeft() or 0) - (box:GetRight() or 0)
	end
	for _, o in ipairs(offs) do worst = math.max(worst, math.abs(o - offs[1])) end
	check(worst < 0.5, "and wears it at the same place on all three (" ..
		table.concat({ string.format("%.0f", offs[1]),
			string.format("%.0f", offs[2]),
			string.format("%.0f", offs[3]) }, ", ") .. ")")
	-- INSIDE THE FIELD, at the text inset - there is nowhere else for it to
	-- go. The gap to the next box is sixteen and a coin is thirteen, so put
	-- outside, silver's lands on copper's well.
	check(offs[1] < 0, "on the inside of it, where the digits stop (" ..
		string.format("%.0f", offs[1]) .. ")")

	-- THE TOTAL, which the client wraps TWICE - a black inset and a thin
	-- gold edge round one number.
	local wraps = 0
	for _, n in ipairs({ "SendMailMoneyInset", "SendMailMoneyBg" }) do
		for _, r in ipairs({ _G[n]:GetRegions() }) do
			if r:IsShown() then wraps = wraps + 1 end
		end
	end
	check(wraps == 0, "the total loses both its surrounds (" .. wraps .. ")")
	check(_G.SendMailMoneyBg.__aetherPill ~= nil,
		"and gets one of ours back")

	-- SEND MONEY OR C.O.D. - one choice with two answers, which is what a
	-- RADIO button is, and the last of the client's art left on this pane.
	local send, cod = _G.SendMailSendMoneyButton, _G.SendMailCODButton
	local stone = 0
	for _, b in ipairs({ send, cod }) do
		for _, r in ipairs({ b:GetRegions() }) do
			if r:IsShown() and r.GetTexture
				and tostring(r:GetTexture() or ""):find("RadioButton", 1, true) then
				stone = stone + 1
			end
		end
	end
	check(stone == 0, "the radio buttons lose Blizzard's disc (" .. stone .. ")")
	check(send.__aetherCheck and cod.__aetherCheck,
		"and each gets a chip of ours")

	-- ROUND, and the shape is the whole of the point: square is on or off,
	-- round is one of several. The check box next door is the same chip with a
	-- corner a third of its size, so reading the corner against the chip's own
	-- width is what separates them - a chip that merely EXISTS would pass with
	-- a square drawn here.
	local chip = send.__aetherCheck
	check(chip._corner >= chip:GetWidth() / 2 - 1.5,
		"drawn round rather than square, because it is one of several (" ..
		tostring(chip._corner) .. " on " .. tostring(chip:GetWidth()) .. ")")
	check(chip.tick == nil,
		"and with no tick on it - a radio is filled or it is empty")

	-- AND CLEAR OF THE ONE UNDER IT. A radio never appears alone, and the
	-- client stacks this pair FIFTEEN apart - so at the check box's 18 the two
	-- ran into each other, which is the one shape a group of them must not
	-- have.
	local gap = chip:GetBottom() and cod.__aetherCheck:GetTop()
		and (chip:GetBottom() - cod.__aetherCheck:GetTop())
	check(gap and gap > 0, "with air between it and the one under it (" ..
		string.format("%.1f", gap or -99) .. ")")

	-- AND THE PAIR FOLLOWS THE CLIENT. Only one of them is ever clicked: the
	-- other is turned off by the client CALLING SetChecked on it, and it does
	-- the same from its own update when an attachment rules C.O.D. out. A
	-- mark hooked to its own button's OnClick sees neither, and the one you
	-- just left stays filled in.
	-- FILLED IS ON. Same inversion the check box uses and the selected chat
	-- tab before it: a mark that is merely brighter reads as hovered.
	local function lit(b)
		local chip = b.__aetherCheck
		return chip and chip._edgeHidden == true
			and chip._fillColor == A.Palette.c.accent
	end
	_G.SendMailRadioButton_OnClick(2)
	check(cod:GetChecked() and not send:GetChecked(),
		"C.O.D. takes the choice when the client says so")
	check(lit(cod) and not lit(send),
		"and the marks follow it without either button being clicked")
	_G.SendMailRadioButton_OnClick(1)
	check(lit(send) and not lit(cod), "and back again")

	-- THE LETTER never had a border of its own: the stationery behind it WAS
	-- the frame, so taking that off leaves the words on bare glass with
	-- nothing saying where you may type.
	check(_G.MailEditBox.__aetherPill ~= nil, "the letter gets a well")
	local _, wellTo = _G.MailEditBox.__aetherPill:GetPoint(2)
	check(wellTo == _G.MailEditBoxScrollBar,
		"with its bar inside it rather than beside it")

	-- ONE WELL PER FIELD, HOWEVER OFTEN WE COME PAST. Skin() runs again on
	-- every show and on every skin change, and a well built fresh each time
	-- would stack a second surface behind the first - every alpha in the
	-- window then wrong by exactly the amount nobody could name. Same trap
	-- the right-click menus had, and the answer is the same: reuse the one
	-- that is there.
	local firstWell = _G.MailEditBox.__aetherPill
	local kids = #({ _G.SendMailNameEditBox:GetChildren() })
	for _ = 1, 3 do PN:Skin() end
	check(_G.MailEditBox.__aetherPill == firstWell,
		"a field keeps the one well it has however often we dress it")
	check(#({ _G.SendMailNameEditBox:GetChildren() }) == kids,
		"and gains no second surface behind it (" ..
		#({ _G.SendMailNameEditBox:GetChildren() }) .. " from " .. kids .. ")")

	-- THE ATTACHMENT SLOTS keep their plate in a BACKGROUND region rather
	-- than in the normal texture, so clearing the button's own four states
	-- leaves all sixteen of them stone - and a plain sweep would take the
	-- item's picture along with the plate.
	local slotStone, undressed, lostIcons = 0, 0, 0
	for i = 1, 16 do
		for _, n in ipairs({ "SendMailAttachment" .. i,
			"OpenMailAttachmentButton" .. i }) do
			local b = _G[n]
			for _, r in ipairs({ b:GetRegions() }) do
				if r ~= b.Icon and r:IsShown() and tostring(r:GetTexture() or ""):find("Slot-Background", 1, true) then
					slotStone = slotStone + 1
				end
			end
			if not b.__aetherSlot then undressed = undressed + 1 end
			if not (b.Icon:IsShown() and tostring(b.Icon:GetTexture() or ""):find("Icons", 1, true)) then
				lostIcons = lostIcons + 1
			end
		end
	end
	check(slotStone == 0, "the slots have lost their plates (" .. slotStone .. ")")
	check(undressed == 0, "and wear our cell instead (" .. undressed .. " bare)")
	check(lostIcons == 0, "with the item still on them (" .. lostIcons .. " blanked)")
	-- THE BUTTONS on all three. Send, Create, Create All, Close - a dozen of
	-- them across the windows, and every one a red UIPanelButtonTemplate plate.
	--
	-- BUT NOT THE LIST ROWS, which are Buttons with font strings on them and
	-- children of the same window. A sweep by shape gave all thirty of them a
	-- pressable SURFACE, and the recipe list came up as a column of pills. A
	-- row in a list is a line you pick, not a button you press, and nothing
	-- else in this interface draws one that way.
	local plain, pills = 0, 0
	for _, root in ipairs({ _G.SendMailFrame, _G.TradeSkillFrame, _G.CraftFrame,
		_G.InboxFrame }) do
		for _, child in ipairs({ root:GetChildren() }) do
			local name = child.GetName and child:GetName() or ""
			local isRow = name:find("^TradeSkillSkill%d") or name:find("^Craft%d")
				or name:find("CollapseAllButton$") or name:find("^MailItem%d")
			if child.GetObjectType and child:GetObjectType() == "Button"
				and child.GetFontString and child:GetFontString() then
				if isRow then
					if child.__aetherSkin then pills = pills + 1 end
				elseif not child.__aetherSkin then
					plain = plain + 1
				end
			end
		end
	end
	check(plain == 0, "every button on them is ours (" .. plain .. " left)")
	check(pills == 0,
		"and not one row in a list wears a button surface - not a recipe, not"
		.. " a letter in the postbox (" .. pills ..
		" pills)")

	-- AND NOT ONE OF THEM THREW ON THE WAY. The interiors are pcall'd, so a
	-- dresser that dies leaves the window in our glass with everything
	-- inside it untouched and says nothing - indistinguishable on screen
	-- from a fix that never deployed, and it cost three rounds of guessing
	-- once already.
	local broke = {}
	for _, n in ipairs({ "MailFrame", "ItemTextFrame", "TradeSkillFrame",
		"CraftFrame" }) do
		if PN.failures and PN.failures[n] then
			broke[#broke + 1] = n .. ": " .. tostring(PN.failures[n])
		end
	end
	check(#broke == 0, "and no dresser threw on the way (" ..
		(#broke > 0 and table.concat(broke, " | ") or "all four clean") .. ")")

	-- And the scroll bars, which are the old template on these windows.
	check(_G.ItemTextScrollFrame.ScrollBar.__aetherScroll == true,
		"the book's scroll bar is ours")

	-- AND ITS TROUGH IS OFF THE FRAME. The rail is not on the bar at all -
	-- it is three textures in the SCROLL FRAME's own layers - so reskinning
	-- the bar and stopping there leaves a black rail with stone caps down
	-- the side of a page that is otherwise ours.
	local rail = 0
	for _, r in ipairs({ _G.ItemTextScrollFrame:GetRegions() }) do
		if r.__tex and tostring(r.__tex):find("UI-Character-ScrollBar", 1, true)
			and r:IsShown() then rail = rail + 1 end
	end
	check(rail == 0,
		"and the trough on the frame behind it goes too (" .. rail ..
		" still drawing)")
	check(_G.TradeSkillDetailScrollFrame.ScrollBar.__aetherScroll == true,
		"and the trade skill's")

	-- THE LIST'S HEADINGS. The client draws its plus and minus as the row
	-- button's NORMAL texture, and it puts them back on every refill - so
	-- dressing them once and stopping there is dressing them until the
	-- player expands anything.
	local marked, wrongWay = 0, {}
	for _, spec in ipairs({ { "TradeSkillSkill", "TradeSkill" },
		{ "Craft", "Craft" } }) do
		for i = 1, 8, 2 do
		local btn = _G[spec[1] .. i]
		if btn.__aetherGlyph and btn.__aetherGlyph:IsShown() then
			marked = marked + 1
		end
		end
	end
	check(marked == 8, "every heading in both lists wears our mark (" ..
		marked .. " of 8)")

	-- AND THE RECIPES BETWEEN THEM DO NOT. A row that was a heading a
	-- moment ago is a recipe now - the buttons are reused down the page -
	-- and the client clears its own mark where ours would be left behind.
	local strays = 0
	for _, row in ipairs({ "TradeSkillSkill", "Craft" }) do
		for i = 2, 8, 2 do
			local g = _G[row .. i].__aetherGlyph
			if g and g:IsShown() then strays = strays + 1 end
		end
	end
	check(strays == 0, "and no recipe carries one (" .. strays .. ")")

	-- WHICH WAY THE MARK POINTS follows the client, not our own memory of
	-- it: an expanded heading is a minus and a collapsed one a plus.
	local function mark()
		local g = _G.TradeSkillSkill1.__aetherGlyph
		return g and g:GetText()
	end
	-- AND A ROW THAT IS NOT A HEADING KEEPS NONE OF THE TEMPLATE'S PLUS ART.
	-- The client clears the NORMAL texture on a recipe and leaves the other
	-- three, so hovering one lit it up with Blizzard's plus button - and the
	-- refill is the path that matters, because the dress-time sweep over the
	-- window's children does not run again.
	_G.TradeSkillSkill2:SetHighlightTexture("Interface\\Buttons\\UI-PlusButton-Hilight")

	local open = mark()
	_G.TradeSkillFrame_Update()
	local shut = mark()
	local recHi = _G.TradeSkillSkill2:GetHighlightTexture()
	check(not recHi or recHi:GetTexture() == 0,
		"and a recipe carries no plus button on any of its other states after"
		.. " the refill either (" .. tostring(recHi and recHi:GetTexture()) .. ")")
	check(open ~= shut,
		"the mark turns over when the heading collapses (" ..
		tostring(open) .. " to " .. tostring(shut) .. ")")

	-- AND THE REFILL DID NOT PUT THE CLIENT'S BACK. The check above only
	-- proves ours followed; this one proves theirs did not come with it.
	local restone = 0
	for i = 1, 8 do
		local tex = _G["TradeSkillSkill" .. i]:GetNormalTexture()
		local art = tex and tex.GetTexture and tex:GetTexture()
		if art and art ~= 0 then restone = restone + 1 end
	end
	check(restone == 0,
		"and the client's own is off again after the refill (" ..
		restone .. ")")

	-- AND THE MARK MOVES WHEN THE ROWS DO. The eight buttons are reused
	-- down the page: a row that is a heading now is a recipe after the
	-- next scroll, and the client clears its own mark where ours would
	-- otherwise be left sitting in the middle of a recipe's name.
	_G.__shiftSkillRows()
	local left, missing = 0, 0
	for i = 1, 8 do
		local g = _G["TradeSkillSkill" .. i].__aetherGlyph
		local shown = g and g:IsShown()
		if i % 2 == 1 then
			if shown then left = left + 1 end
		elseif not shown then
			missing = missing + 1
		end
	end
	check(left == 0, "no mark is left behind on a row turned recipe (" ..
		left .. ")")
	check(missing == 0, "and every row turned heading has one (" ..
		missing .. " of 4 without)")

	-- THE LITTLE STONE TAB the All control hangs off. Its own frame, and
	-- not one the shell walks, so it sat behind All on our glass.
	local tabArt = 0
	for _, prefix in ipairs({ "TradeSkill", "Craft" }) do
		for _, part in ipairs({ "Left", "Middle", "Right" }) do
			local tex = _G[prefix .. "ExpandTab" .. part]
			if tex and tex:IsShown() then tabArt = tabArt + 1 end
		end
	end
	check(tabArt == 0, "the tab behind All is gone (" .. tabArt .. " of 6)")

	-- THE TWO FILTERS. Neither carries a label of its own, so the sweep
	-- that finds a button by the words on it goes straight past both - and
	-- both stayed a stone holder with a stone arrow on a window of ours.
	local rawFilters = {}
	for _, key in ipairs({ "SubClassDropdown", "InvSlotDropdown" }) do
		local dd = _G.TradeSkillFrame[key]
		if not (dd and dd.__aetherSkin) then
			rawFilters[#rawFilters + 1] = key
		elseif tostring(dd.Arrow:GetTexture() or ""):find("dropdown", 1, true) then
			rawFilters[#rawFilters + 1] = key .. ":arrow"
		end
	end
	check(#rawFilters == 0, "both filters are ours (" ..
		(#rawFilters > 0 and table.concat(rawFilters, ",") or "holder and arrow")
		.. ")")

	-- THE COUNT SPINNER. The client draws these as a PICTURE OF A BUTTON -
	-- the arrow and the plate it stands on are one texture - so taking the
	-- plate off takes the arrow with it and leaves a live control with
	-- nothing drawn on it at all. Which is what the postbox's page turners
	-- had been since the day they were skinned.
	-- The count spinner, which is what is left wearing one: a spinner steps a
	-- number and is not navigation, so it keeps the round face. Every PAGE turn
	-- moved off it - see below.
	local arrows = {
		{ _G.TradeSkillDecrementButton, "LEFT" },
		{ _G.TradeSkillIncrementButton, "RIGHT" },
	}
	local blank, turns = 0, {}
	for _, pair in ipairs(arrows) do
		local mark = pair[1].__aetherArrow
		if not mark then blank = blank + 1
		else turns[#turns + 1] = mark:GetRotation() end
	end
	check(blank == 0,
		"every arrow button still has an arrow on it (" .. blank ..
		" bare of 6)")

	-- POINTING OPPOSITE WAYS, which is the whole of what they say. One
	-- table of radians shared with the dock handles, so there is one place
	-- to get a direction backwards rather than three.
	local backwards = 0
	for i = 1, #turns, 2 do
		if not (turns[i] and turns[i + 1] and turns[i] == -turns[i + 1]
			and turns[i] < 0) then backwards = backwards + 1 end
	end
	check(backwards == 0,
		"and back points back while forward points forward (" ..
		backwards .. " pairs wrong)")

	-- The box between the spinner's two halves, which is the same field the
	-- postbox is full of.
	local boxStone = 0
	for _, part in ipairs({ "Left", "Middle", "Right" }) do
		local tex = _G["TradeSkillInputBox" .. part]
		if tex and tex:IsShown() then boxStone = boxStone + 1 end
	end
	check(boxStone == 0 and _G.TradeSkillInputBox.__aetherPill ~= nil,
		"and the count between them is one of our fields (" .. boxStone ..
		" slices left)")

	-- WITH ITS TEXT OFF THE RIM. An edit box draws from its own edge and the
	-- well round it has a rim there, so the digit sat on it - which on a box
	-- one character wide is the whole of what you see.
	local li, ri = _G.TradeSkillInputBox:GetTextInsets()
	check((li or 0) > 0 and (ri or 0) > 0,
		"and its text starts inside the rim rather than on it (" ..
		tostring(li) .. ", " .. tostring(ri) .. ")")

	for _, n in ipairs({ "MailFrame", "ItemTextFrame", "TradeSkillFrame",
		"CraftFrame" }) do
		_G[n]:Hide()
	end
end)
section("panels: somebody else's character sheet", function()
	local PN = A:GetModule("panels")
	local inf = _G.InspectFrame
	inf:Show()
	PN:Skin()

	check(inf.__aetherPanel ~= nil, "the inspect window has glass behind it")
	check(PN.failures == nil or PN.failures.InspectFrame == nil,
		"and its dresser ran clean (" ..
		tostring(PN.failures and PN.failures.InspectFrame) .. ")")

	-- THE NAME IS NOT IN THE TITLE BAND. This window leaves its own TitleText
	-- empty and puts the name in a frame of its own, so a skin that only
	-- re-roles $parentTitleText re-roles an empty string and leaves the one
	-- word on screen in Blizzard's lettering.
	check(_G.InspectNameText._aetherStyle == "pnTitle",
		"the name at the top is in our type, not the client's")
	-- AUTO, which for a font string means "as wide as what you say" rather
	-- than nought: with a width set it reports that width, and without one it
	-- reports its string.
	check(_G.InspectNameText:GetWidth()
		== _G.InspectNameText:GetStringWidth(),
		"and free of the 109 the client measured for its smaller type - left"
		.. " at that width a name of any length comes out clipped")

	-- THE SLOTS. Their plate is a BACKGROUND region rather than the normal
	-- texture, the way a mail attachment's is, so clearing the button alone
	-- leaves all nineteen of them in stone.
	local head, neck = _G.InspectHeadSlot, _G.InspectNeckSlot
	check(head.__aetherSlot == true, "an inspected slot wears our cell")
	check(_G.InspectHeadSlotFrame:GetTexture() == 0,
		"and the stone plate behind it is gone - it is a background region"
		.. " of the button, which is where ClearButton cannot reach")
	check(_G.InspectHeadSlotIconTexture:GetTexture()
		== "item-icon-InspectHeadSlot",
		"with THE ITEM STILL IN IT - the picture is in that same layer, so"
		.. " the sweep that takes the plate takes the item unless it is told"
		.. " not to")

	-- AND THE RIM READS THE UNIT BEING INSPECTED. Every item in this window
	-- belongs to somebody else: asked for "player" it is your own gear
	-- colouring theirs, which looks entirely correct and is not. The head is
	-- RARE on the unit and epic on the player, so the two answers differ.
	local hr, hg, hb = head.edge:GetVertexColor()
	local q = _G.ITEM_QUALITY_COLORS[3]
	check(hr == q.r and hg == q.g and hb == q.b,
		"the rim is the quality the UNIT is wearing, not the one you are")

	-- Empty here and epic on the player, which is the same question the other
	-- way round: a slot with nothing in it must not borrow your own rim.
	local e = A.Palette.c.glassEdge
	local wr, wg, wb = _G.InspectMainHandSlot.edge:GetVertexColor()
	check(wr == e[1] and wg == e[2] and wb == e[3],
		"and a slot they have nothing in keeps the ordinary one, even where"
		.. " you have an epic")
	local nr, ng, nb = neck.edge:GetVertexColor()
	check(nr == e[1] and ng == e[2] and nb == e[3],
		"as does a slot neither of you has filled")

	-- The whole set arrives LATE on this window - on INSPECT_READY, after any
	-- skin has already been past - so a rim set once at dress time is a rim
	-- for whatever the slots held before the answer came back.
	_G.__setInspectQuality(1, nil)
	_G.InspectPaperDollItemSlotButton_Update(head)
	hr, hg, hb = head.edge:GetVertexColor()
	check(hr == e[1] and hg == e[2] and hb == e[3],
		"and the rim answers the client when it fills a slot in later")
	_G.__setInspectQuality(1, 3)

	-- THE PANES, and the two pictures among their stone.
	check(_G.InspectPaperDollFrame:GetRegions():GetTexture() == 0,
		"the panes lose their stone")
	check(_G.InspectHonorFramePvPIcon:GetTexture() ~= 0,
		"the PvP rank badge survives the honour pane's sweep - it is a"
		.. " region of that pane exactly as the parchment is, and taking one"
		.. " took the picture of the rank the words beside it are naming")
	check(_G.InspectFaction:GetTexture() ~= 0,
		"and so does the faction crest shown in place of a model too far"
		.. " off to draw")
	check(_G.InspectHonorFrameProgressBar.__aetherFill ~= nil,
		"the honour tab's rank bar takes our fill")

	-- AND BOTH PANES MOVE INTO THE RECESS, the way the character sheet's four
	-- do. Same shape, same problem: the doll's first slot starts 65 down and
	-- the honour pane 62, which is the strip the stone plate needed and
	-- neither our band nor our padding.
	do
		local inInner = A.Widgets.PANEL_PAD + A.Widgets.WELL_PAD
		local want = A.Widgets.PANEL_HEAD_SUB + inInner
		local doll = select(5, _G.InspectPaperDollFrame:GetPoint(1))
		local hon = select(5, _G.InspectHonorFrame:GetPoint(1))
		check(doll == -(want - 65) and hon == -(62 + (want - 62)),
			"each of the two tabs clears the band by its OWN measurement (" ..
			tostring(doll) .. ", " .. tostring(hon) .. ")")
		check(_G.InspectFrame.__aetherHeadH == A.Widgets.PANEL_HEAD_SUB,
			"and the band is the taller one, because this window has a class line"
			.. " under the name (" .. tostring(_G.InspectFrame.__aetherHeadH) .. ")")
	end

	-- A CHEVRON MEANS NAVIGATION AND NOTHING ELSE - a page, a carousel, a
	-- drawer. Turning the doll is MANIPULATION, so it gets its own glyph and
	-- sits ON the model rather than in the window's furniture. Two chevrons
	-- beside a character model say there is a next page of character.
	local bare, wrong = 0, 0
	for _, pair in ipairs({
		{ _G.InspectModelFrame, _G.InspectModelFrameRotateRightButton,
			_G.InspectModelFrameRotateLeftButton },
		{ _G.CharacterModelFrame, _G.CharacterModelFrameRotateRightButton,
			_G.CharacterModelFrameRotateLeftButton },
	}) do
		local model, right, left = pair[1], pair[2], pair[3]
		if not (right.__aetherRound and left.__aetherRound) then
			bare = bare + 1
		else
			-- ONE DRAWING, MIRRORED. The left-turning one is the
			-- right-turning one with two texture coordinates swapped, so the
			-- two can never disagree about what a circular arrow is.
			local rl, rr = right.__aetherRound:GetTexCoord()
			local ll, lr = left.__aetherRound:GetTexCoord()
			if not (rl == lr and rr == ll and rl ~= rr) then wrong = wrong + 1 end
		end
		local rp, rrel = right:GetPoint(1)
		if not (rp == "BOTTOMRIGHT" and rrel == model) then
			bare = bare + 1
		end
	end
	check(bare == 0,
		"both dolls' turn controls sit on the model itself, bottom-right (" ..
		bare .. " wrong of 4)")
	check(wrong == 0,
		"and the two are one drawing mirrored rather than two that have to"
		.. " agree (" .. wrong .. ")")

	-- IDLE AT THREE QUARTERS. These sit ON the thing they act on rather than
	-- in the furniture, so at full strength they compete with it - and what
	-- they are over is a lit, moving picture. The cursor brings them up.
	local rb = _G.CharacterModelFrameRotateRightButton
	check(math.abs(rb:GetAlpha() - 0.75) < 0.01,
		"and they sit back at three quarters over the model (" ..
		string.format("%.2f", rb:GetAlpha()) .. ")")
	rb:GetScript("OnEnter")(rb)
	check(rb:GetAlpha() == 1, "coming up under the cursor")
	rb:GetScript("OnLeave")(rb)
	check(math.abs(rb:GetAlpha() - 0.75) < 0.01, "and back again")

	-- THE POSTBOX'S ACTIONS GO IN A STRIP. The client hangs the two page turns
	-- and Open All 114 up from the window's bottom edge, which in a window this
	-- shape is inside the recess - so they sat hard against the last letter in
	-- the list with nothing between them and it.
	do
		local mf = _G.MailFrame
		-- AND A PANE THAT FILLS THE WINDOW HAS ITS FOOT LIFTED CLEAR OF THE STRIP.
	-- Send Mail hangs its money field, its two radio buttons and your purse off
	-- the BOTTOM of its pane, and with Send and Cancel moved into the strip the
	-- rest of that block was left sitting on top of them. The pane's box has to
	-- be the BODY's box, not the window's.
	do
		-- PINNED BY ONE CORNER, so nothing holds its foot but its own height:
		-- shortening it IS what holds it. A page pinned by BOTH corners is held
		-- already and must not be touched - the character sheet's weapon row hangs
		-- off exactly that edge.
		local pane = _G.SendMailFrame
		check(pane:GetNumPoints() == 1,
			"the send pane is pinned by one corner, as the client pins it (" ..
			tostring(pane:GetNumPoints()) .. ")")
		-- WHAT THE CLIENT HANGS ABOVE THAT FOOT IS THE THING THAT MATTERS. The
		-- pane's own foot hangs BELOW the window's, as it does unskinned - it is
		-- taller than its window on purpose. The money block sits a fixed distance
		-- up from it, and that is what has to land in the body rather than in the
		-- strip.
		-- THE LOWEST OF THEM, not the first one to hand. The radio sits 125 above
		-- the pane's foot and the total 96, so a window grown to clear the radio
		-- still had your purse printed across Send and Cancel.
		local well = _G.MailFrame.__aetherBody
		local under = {}
		for _, n in ipairs({ "SendMailMoneyButton", "SendMailSendMoneyButton",
			"SendMailCODButton", "SendMailMoneyFrame" }) do
			local w = _G[n]
			-- INSIDE THE WELL'S PADDING, not merely above its floor. Content that
			-- clears the rim by a hair is content the next change puts through it.
			if w:GetBottom() and well:GetBottom()
				and w:GetBottom() < well:GetBottom() + A.Widgets.WELL_PAD - 0.5 then
				under[#under + 1] = n
			end
		end
		check(#under == 0,
			"every part of the money block lands in the body rather than on top of"
			.. " Send and Cancel (" ..
			(#under > 0 and table.concat(under, ", ") or "all clear") .. ")")

		-- AND ITS OWN TITLE IS NOT ITS CONTENT. A window with panes has a title
		-- string per pane, and the ones whose panes are DOWN are still strings
		-- near the top of the window. Send Mail's is four units below the glass,
		-- so measuring that pane while the inbox was up said its content started
		-- there - and the form was pushed down to clear a band it was already
		-- clear of, leaving a hand's width of nothing at the top of the recess.
		check(pane.__aetherTop and pane.__aetherTop > 20,
			"the send pane is measured by its form and not by its own title (" ..
			tostring(pane.__aetherTop) .. ")")

		-- AND THE PAGE KEEPS THE HEIGHT ITS INSIDES WERE LAID OUT FOR. A page
		-- whose top goes down to clear the band and whose foot comes up to clear
		-- the strip has LOST that much height - and the client measured its
		-- insides for the height it had, so Send Mail's attachment row and its
		-- money block came up into the middle of the letter. The window grows by
		-- both ends instead of taking it out of the page.
		-- AND ITS DECLARED HEIGHT IS LEFT ALONE, because it is part of the
		-- client's arithmetic: 512 inside a window 424 tall, with the attachment
		-- row placed from Lua a fixed distance above the pane's bottom. Shortening
		-- it to fit the body dragged that row up into the middle of the letter.
		check(math.abs(pane:GetHeight() - 512) < 0.5,
			"the send pane keeps the height the client gave it (" ..
			string.format("%.0f", pane:GetHeight()) .. " of 512)")
		check(pane:GetHeight() > _G.MailFrame:GetHeight() - 88,
			"which is taller than the window it lives in, on purpose")

	end

	-- THE LETTERS LOSE THEIR OWN ART. Each row is drawn as two slices of
	-- MailItemBorder plus a rule, all BACKGROUND regions of the ROW - so the
	-- sweep over the pane reached none of them and seven stone plaques sat in
	-- the recess with the list on top of them.
	do
		local plaques, bare = 0, 0
		for i = 1, 7 do
			local row = _G["MailItem" .. i]
			for _, r in ipairs({ row:GetRegions() }) do
				if r.GetObjectType and r:GetObjectType() == "Texture"
					and r:GetTexture() ~= 0 then plaques = plaques + 1 end
			end
			if not _G["MailItem" .. i .. "Button"].__aetherSlot then
				bare = bare + 1
			end
		end
		check(plaques == 0,
			"every letter in the list loses its own plaque (" .. plaques ..
			" left)")
		check(bare == 0,
			"and its picture sits in one of our cells (" .. bare .. " bare)")
	end

	-- AND A PAGE TURN SAYS WHICH WAY ONCE. These carry "Prev" and "Next" as
	-- their own labels - forty units wide on a button thirty-two across - so
	-- two of them a chevron apart printed one word over the other.
	do
		local said = {}
		for _, btn in ipairs({ _G.InboxPrevPageButton,
			_G.InboxNextPageButton }) do
			for _, r in ipairs({ btn:GetRegions() }) do
				-- Our own mark is a region of the button too, and it is the one thing
				-- here that IS meant to say something.
				if r ~= btn.__aetherMark and r.GetObjectType
					and r:GetObjectType() == "FontString"
					and (r:GetText() or "") ~= "" then
					said[#said + 1] = r:GetText()
				end
			end
		end
		check(#said == 0,
			"a page turn carries the mark and not the word as well - the word is an"
			.. " unnamed region of the button, not its label (" ..
			(#said > 0 and table.concat(said, " ") or "none") .. ")")
	end

	-- AND THE RECEIPT IS LIFTED OFF THE PARCHMENT. The client prints it in a
	-- dark brown that reads on paper and vanishes on glass, and it is NOT black
	-- enough for the sweep to catch: that lifts ink under 0.35 and this sits
	-- just over it.
	do
		local dark = {}
		for _, n in ipairs({ "OpenMailInvoiceItemLabel",
			"OpenMailInvoicePurchaser" }) do
			local r = select(1, _G[n]:GetTextColor())
			if not r or r < 0.5 then dark[#dark + 1] = n end
		end

		-- AND THE LETTER ITSELF, WHICH IS COLOURED BY TEXT TYPE. Reaching this at
		-- all means the SimpleHTML path was taken: the mock raises if either
		-- SetFont or SetTextColor is called on it the font-string way, which is
		-- what took the whole mail dresser down in the game.
		for _, kind in ipairs({ "P", "H1" }) do
			local r = select(1, _G.OpenMailBodyText:GetTextColor(kind))
			if not r or r < 0.5 then dark[#dark + 1] = "body:" .. kind end
		end
		check(#dark == 0,
			"the auction house's receipt is readable on glass (" ..
			(#dark > 0 and table.concat(dark, ", ") or "all lifted") .. ")")

		-- AND THE FOUR MONEY LINES ARE SWEPT RATHER THAN NAMED. They are frames,
		-- not strings: both answer GetFont and SetFont, and calling either on a
		-- frame THROWS - which took the whole postbox dresser down and left every
		-- one of its insides in Blizzard's art, with the shell in ours around it.
		local coin = _G.OpenMailInvoiceSalePriceGoldButtonText
		check(coin and coin._aetherStyle ~= nil,
			"the amounts on it are in our lettering, reached through the frame that"
			.. " holds them rather than by being handed to the font setter")
	end

	-- AND THE LETTER WINDOW STANDS THE SAME HEIGHT AS THE POSTBOX. The client
	-- hangs it off the inbox's top right corner and gives it a height of its
	-- own, so the pair came up as two different sizes side by side.
	check(math.abs(_G.OpenMailFrame:GetHeight() - _G.MailFrame:GetHeight())
		< 0.5,
		"the letter you open is as tall as the postbox beside it (" ..
		string.format("%.0f", _G.OpenMailFrame:GetHeight()) .. " against " ..
		string.format("%.0f", _G.MailFrame:GetHeight()) .. ")")

	-- ...AND MADE ROOM FOR ITS OWN STRIP FIRST. Standing beside something is
	-- not a reason to be too short for your own insides: skipping the growth
	-- outright left the letter with no room made for its footer at all, and its
	-- attachment row sat under Delete.
	-- SHOWN BY MAKING THE TWIN THE SHORTER OF THE TWO, which is the only way
	-- to see it: while the postbox is taller its height wins either way, and a
	-- letter that skipped its own growth looks identical.
	do
		local letter, post = _G.OpenMailFrame, _G.MailFrame
		local postWas = post:GetHeight()
		local need = (letter:GetHeight() or 0)
			- (letter.__aetherBodyShift or 0)
		post:SetHeight(need)
		A:GetModule("panels").Dress(letter)
		check(letter:GetHeight() > need + 0.5,
			"and grew for its own band and strip rather than shrinking to a twin"
			.. " too short for it (" .. string.format("%.0f", letter:GetHeight())
			.. " against " .. string.format("%.0f", need) .. ")")
		post:SetHeight(postWas)
		A:GetModule("panels").Dress(letter)
	end

	-- AND WHO IT IS FROM IS BODY CONTENT. The client hangs the sender and the
	-- subject off the window's own TOPLEFT, 33 and 55 down, which is inside our
	-- band - so both were printed across the window's title.
	do
		local from = _G.OpenMailSenderLabel
		local fy = from and select(5, from:GetPoint(1))
		check(fy and -fy >= A.Widgets.PANEL_HEAD_H,
			"the sender clears the header band rather than being printed across the"
			.. " window's own title (" .. tostring(fy and -fy) .. ")")

		-- AND WHO IT IS FROM SITS BESIDE ITS OWN LABEL. That name lives in a frame
		-- pinned by TWO corners - the label on one side and the Report Player
		-- button on the other - and that button is HIDDEN on this build. A box
		-- pinned to something the client never lays out comes back with its bottom
		-- ABOVE its top, 239 wide and nothing tall, and the name is drawn beside
		-- the window's title instead of beside From.
		-- DRESSED BY ITS OWN, not by the postbox's. All of this used to run inside
		-- the postbox's dresser, reaching across into another window's globals -
		-- so anything that threw earlier in THAT function took the letter with it,
		-- silently, and it came up adrift while the postbox beside it looked
		-- perfect.
		local PN3 = A:GetModule("panels")
		check(PN3.INTERIORS.OpenMailFrame ~= nil,
			"the letter has a dresser of its own")
		-- AND THE RECEIPT IS LIFTED WHERE ITS INK ACTUALLY LIVES.
		local ink = select(1, _G.InvoiceTextFontNormal:GetTextColor())
		check(ink and ink > 0.5,
			"the receipt is lifted on the font object its lines inherit, not on the"
			.. " lines (" .. string.format("%.2f", ink or 0) .. ")")
		local small = select(1, _G.InvoiceTextFontSmall:GetTextColor())
		check(small and small > 0.5,
			"both of them, so the small print comes up with the rest")

		local who = _G.OpenMailSender
		check(not _G.OpenMailReportSpamButton:IsShown(),
			"the report button is down on this build, as it is in the game")
		check(who:GetHeight() > 0,
			"so the sender's box is a box rather than a line (" ..
			string.format("%.0f", who:GetHeight()) .. " tall)")
		check(who:GetLeft() and from:GetRight()
			and who:GetLeft() >= from:GetRight() - 0.5,
			"and the name sits beside the label rather than above it (" ..
			string.format("%.0f", who:GetLeft() or 0) .. " against " ..
			string.format("%.0f", from:GetRight() or 0) .. ")")
	end

	-- TWO ROWS IN THE ONE STRIP. Open All is an ACTION and the turns either
		-- side of it are NAVIGATION; on one line all three read as the same kind
		-- of thing.
		--
		-- AND THE STRIP GROWS FOR THE SECOND ROW rather than splitting the 52
		-- between them. Split, each row got 26 - and a 22 tall button centred in
		-- 26 has two pixels of air under it, so Open All sat on the postbox's
		-- own tab rule with the rest of the window still 15a's fixed height.
		--
		-- MEASURED OFF THE RAIL rather than restated from the arithmetic that
		-- placed it. The two checks here used to name the halves the layout was
		-- computing, which is the shape of check that passes whatever the
		-- layout does: they read 13 and 39 and agreed with both.
		-- THE STRIP'S FLOOR, found the way the layout finds it: the tab rail's
		-- top where the window has one and the glass's own foot where it does
		-- not. Naming the rail alone reads nil in here, where nothing calls
		-- the client's tab resize.
		local rail = mf.__aetherRails and mf.__aetherRails.BOTTOM
		local floor = (rail and rail:IsShown() and rail:GetTop())
			or (mf.__aetherPanel and mf.__aetherPanel:GetBottom())
		local turn, all = _G.InboxPrevPageButton, _G.OpenAllMail
		local air = floor and all:GetBottom() and (all:GetBottom() - floor)
		check(air and air >= 6,
			"Open All stands clear of the rule under it (" ..
			string.format("%.1f", air or -1) .. " of air)")
		check(turn:GetBottom() and all:GetTop()
			and turn:GetBottom() - all:GetTop() >= 6,
			"with the page turns a row above it rather than pressed onto it (" ..
			string.format("%.1f", (turn:GetBottom() or 0) - (all:GetTop() or 0))
			.. ")")

		-- AND THE STRIP IS A ROW TALLER FOR THE SECOND ROW. Without this the
		-- pair above passes by the row moving UP into the letters instead.
		local rule = mf.__aetherFootRule
		local deep = rule and floor and rule:GetBottom()
			and (rule:GetBottom() - floor)
		check(deep and math.abs(deep - A.Widgets.PANEL_FOOT_H * 1.5) < 0.5,
			"because the strip grew a row rather than splitting 15a's 52 (" ..
			string.format("%.1f", deep or -1) .. " deep)")
		local turns = 0
		for _, b in ipairs({ _G.InboxPrevPageButton, _G.InboxNextPageButton }) do
			if select(1, b:GetPoint(1)) == "LEFT" then turns = turns + 1 end
		end
		check(turns == 2,
			"with a page turn either side of it in the same row (" .. turns .. ")")
		check(mf.__aetherFootRule ~= nil and mf.__aetherFootRule:IsShown(),
			"and a hairline between the strip and the letters above it")
	end

	-- AND EVERY PAGE TURN IN THE INTERFACE IS THE SAME CONTROL. There were two:
	-- the spellbook's, a mark on nothing, and the postbox's, a filled circle -
	-- the same job one window apart in two flavours. 15c: a chevron means
	-- navigation, and navigation reads as chrome rather than as an action you
	-- read and choose.
	local turnMarks, turnRound = {}, 0
	for _, btn in ipairs({ _G.InboxPrevPageButton, _G.InboxNextPageButton,
		_G.ItemTextPrevPageButton, _G.ItemTextNextPageButton,
		_G.SpellBookPrevPageButton, _G.SpellBookNextPageButton }) do
		local mark = btn and btn.__aetherMark
		turnMarks[#turnMarks + 1] = mark and mark:GetText() or "none"
		if btn and btn.__aetherRoundDisc and btn.__aetherRoundDisc:IsShown() then
			turnRound = turnRound + 1
		end
	end
	local sameTurn = #turnMarks == 6
	for _, glyph in ipairs(turnMarks) do
		if glyph == "none" then sameTurn = false end
	end
	check(sameTurn,
		"every page turn in the interface wears the same mark (" ..
		table.concat(turnMarks, " ") .. ")")
	check(turnRound == 0,
		"and none of them is a filled circle any more (" .. turnRound .. ")")

	-- THE TABS HANG OFF THE BOTTOM EDGE, outside the window's own art, the
	-- way the vendor's do - so the glass has to reach past the frame or the
	-- row sits on bare screen.
	check(_G.InspectFrameTab1.__aetherMark ~= nil,
		"a tab gets the mark every other tab in the interface gets")
	local _, rel, at = _G.InspectFrameTab1:GetPoint()
	check(rel == inf.__aetherRails["BOTTOM"] and at == "BOTTOMLEFT",
		"laid out from the rail's bottom-left corner rather than left on the"
		.. " client's centre anchor, which reads an x as where the middle goes"
		.. " and hangs half the tab off the side")
	local ins = PN.ENTRY.InspectFrame.insets
	check(ins and ins[4] and ins[4] < 0,
		"and the glass reaches below the frame to hold them (" ..
		tostring(ins and ins[4]) .. ")")

	-- The character sheet's own honour tab has the same badge under a name of
	-- its own, and it had been coming off with the parchment since the day
	-- that pane was first swept.
	check(_G.HonorFramePvPIcon:GetTexture() ~= 0,
		"the badge on your OWN honour tab survives too")

	inf:Hide()
end)
section("panels: one broken dresser does not take the window with it", function()
	local PN = A:GetModule("panels")

	-- THE SHELL RUNS FIRST - strip, glass, scale, close button - and the
	-- INSIDES run after it. So a dresser that throws leaves a window in our
	-- glass with every one of its insides untouched, which on screen is
	-- indistinguishable from a dresser nobody has written yet.
	--
	-- Three separate reports this session looked like a fix not being deployed.
	local was = PN.INTERIORS.MerchantFrame
	PN.INTERIORS.MerchantFrame = function()
		error("deliberate: a name this game version does not have")
	end

	_G.MerchantFrame:Show()
	local ok = pcall(PN.Dress, _G.MerchantFrame)
	check(ok, "a dresser that throws does not take Dress down with it")
	check(_G.MerchantFrame.__aetherPanel ~= nil,
		"and the window still has its glass")

	-- AND IT SAYS SO. Silence here is how the last three rounds went.
	local why = PN.failures and PN.failures.MerchantFrame
	check(why ~= nil and why:find("deliberate", 1, true) ~= nil,
		"and the failure is kept, with the reason (" .. tostring(why) .. ")")

	local lines = {}
	A.PanelsDiag(function(fmt, ...) lines[#lines + 1] = string.format(fmt, ...) end)
	local all = table.concat(lines, "\n")
	check(all:find("deliberate", 1, true) ~= nil,
		"and /aether panels names it rather than listing the window as fine")

	-- AND A DRESSER THAT STOPS THROWING CLEARS ITS OWN FAILURE. Not cleared
	-- by hand here: the point is that Dress does it, or the report grows a
	-- list of things that were wrong once and stays wrong forever.
	PN.INTERIORS.MerchantFrame = was
	PN.Dress(_G.MerchantFrame)
	check(PN.failures.MerchantFrame == nil,
		"and a dresser that stops throwing clears its own failure")

	-- AND NEITHER DOES THE SHELL, which was the half that was NOT guarded. A
	-- throw in there came out of Skin, and Skin is called from OnEnable - so
	-- one bad window turned the WHOLE MODULE off, while every window already
	-- dressed by the time it threw kept its glass.
	--
	-- On screen that is an interface that looks skinned with every hook,
	-- refresh and re-measure in it dead, and nothing saying why. It cost this
	-- session four rounds of chasing hooks that were never going to fire.
	local hurt = _G.QuestFrame
	-- Through the walk over a window's children, which is where the real one
	-- went: a forbidden frame among them answers nothing at all.
	local realGet = hurt.GetChildren
	hurt.GetChildren = function() error("deliberate: a forbidden frame") end
	local safe = pcall(PN.Skin, PN)
	hurt.GetChildren = realGet
	check(safe,
		"one window that throws does not come out of Skin and turn the module"
		.. " off")
	check(PN.failures.QuestFrame ~= nil
		and tostring(PN.failures.QuestFrame):find("deliberate", 1, true) ~= nil,
		"the window that threw is named, with the reason (" ..
		tostring(PN.failures.QuestFrame) .. ")")
	check(_G.TaxiFrame.__aetherPanel ~= nil,
		"and the windows after it in the list are still dressed")
	PN:Skin()
	check(PN.failures.QuestFrame == nil,
		"and it clears once the window stops throwing")

	_G.MerchantFrame:Hide()
end)
section("panels: a report that says which window and why", function()
	local PN = A:GetModule("panels")

	-- A window that comes up in the client's own stone tells you nothing about
	-- WHY. It may not exist yet, it may exist under another name on this game
	-- version, it may have been dressed and had its art put back. Three
	-- different bugs, identical on screen - and this session has spent whole
	-- rounds guessing between them.
	local lines = {}
	local ok, err = pcall(A.PanelsDiag, function(fmt, ...)
		lines[#lines + 1] = string.format(fmt, ...)
	end)
	check(ok, "/aether panels reports without erroring (" .. tostring(err) .. ")")

	local all = table.concat(lines, "\n")
	check(all:find("MailFrame", 1, true) ~= nil, "with a row per window")

	-- AND IT TELLS THE TWO APART. A window with our glass and one without have
	-- to read differently, or the report is a list of names.
	_G.MailFrame:Show()
	PN:Skin()
	lines = {}
	A.PanelsDiag(function(fmt, ...) lines[#lines + 1] = string.format(fmt, ...) end)
	local dressed, bare
	for _, l in ipairs(lines) do
		if l:find("MailFrame", 1, true) then dressed = l end
		if l:find("WorldMapFrame", 1, true) then bare = l end
	end
	check(dressed ~= nil, "the postbox is in the report")
	check(dressed and dressed:find("NO", 1, true) == nil,
		"and reads as dressed, because it is")
	_G.MailFrame:Hide()
end)
section("panels: the Options window, part by part", function()
	local PN = A:GetModule("panels")
	local sp = _G.SettingsPanel
	-- SHOWN AND THEN RE-SKINNED, which is what happens in game: Skin runs
	-- again on ADDON_LOADED and on PLAYER_ENTERING_WORLD, and a player can
	-- have this window open across either.
	--
	-- That pair used to move the in-flight console's leg ticks by 8%, and the
	-- cause turned out to be nothing to do with this window at all: the ticks
	-- are placed in pixels off the flight bar's width, the bar settles about
	-- forty units narrower after it opens, and nothing repainted them. Fixed
	-- in Modules/IFEC/Player.lua. Kept here because this is the sequence that
	-- found it.
	sp:Show()
	PN:Skin()

	-- THE X IS ClosePanelButton. Every other window in the game names its X
	-- CloseButton; this one uses that name for the ordinary button along the
	-- bottom that says Close - so the generic answer put our glyph on the wrong
	-- one, at the bottom right behind the word, and left the client's red X
	-- exactly where it was.
	check(PN.CloseButton(sp) == sp.ClosePanelButton,
		"the X we dress is the X, not the button that says Close")

	-- The bottom buttons are ordinary buttons of ours.
	for _, key in ipairs({ "CloseButton", "ApplyButton" }) do
		check(sp[key].__aetherSkin ~= nil,
			key .. " wears our surface rather than the client's red plate")
	end

	-- THE TABS SIZE THEMSELVES TO THEIR OWN PLATE, and the plate is the first
	-- thing off - so both numbers have to be ours or one tab is the width of
	-- the word Game and the other of the word AddOns.
	check(sp.GameTab:GetWidth() > 0 and
		math.abs(sp.GameTab:GetWidth() - sp.AddOnsTab:GetWidth()) < 0.5,
		"the two tabs are the same width (" .. sp.GameTab:GetWidth() ..
		" vs " .. sp.AddOnsTab:GetWidth() .. ")")
	check(math.abs(sp.GameTab:GetHeight() - sp.AddOnsTab:GetHeight()) < 0.5,
		"and the same height")

	-- THE ROWS AND HEADINGS ARE POOLED ELEMENTS in a scroll box, not children
	-- of anything the shell sweep walks - which is why they kept the client's
	-- gold plates and fonts while every other part of the window came off.
	local heads, rows = 0, 0
	for _, el in ipairs(sp.CategoryList.ScrollBox:GetFrames()) do
		if el.Toggle then
			rows = rows + 1
			check(tostring(select(1, el.Label:GetFont())):find("AetherUI", 1, true),
				"a category row is in our lettering")
			check(el.Toggle.__aetherGlyph ~= nil,
				"and its expand toggle is our chevron, not a plus plate")
			check(tostring(el.Texture.__tex):find("OptionsFrame", 1, true) == nil,
				"and its selection is ours (" .. tostring(el.Texture.__tex) .. ")")
		elseif el.Background then
			heads = heads + 1
			check(tostring(el.Background.__tex):find("HeaderPlate", 1, true) == nil,
				"a section heading has lost its plate (" ..
				tostring(el.Background.__tex) .. ")")
			check(tostring(select(1, el.Label:GetFont())):find("AetherUI", 1, true),
				"and is in our lettering")
		end
	end
	check(heads == 3 and rows == 3,
		"every heading and every row was reached (" .. heads .. " headings, " ..
		rows .. " rows)")

	-- THE MODERN SCROLL BAR. Its arrows are Back and Forward rather than
	-- ScrollUpButton and ScrollDownButton, its rail lives in a CHILD FRAME
	-- called Track, and its thumb is a frame with its own art - a sweep written
	-- for the old template leaves every one of those drawing.
	for _, bar in ipairs({ sp.CategoryList.ScrollBar,
		sp.Container.SettingsList.ScrollBar }) do
		check(bar.__aetherScroll == true, "the scroll bar is ours")
		local left = 0
		for _, r in ipairs({ bar.Track:GetRegions() }) do
			if r.__tex and tostring(r.__tex):find("minimal-scrollbar", 1, true)
				and r:IsShown() then left = left + 1 end
		end
		check(left == 0,
			"with the client's own rail off it (" .. left .. " left)")
		check(bar.Thumb.__aetherFill ~= nil,
			"and a thumb of ours - it is a frame on this template, not a texture")
	end

	-- THE BUTTONS ON THE PAGES. Named nothing at all: the pages are built from
	-- data, so the only question that can be asked of a child is whether it is
	-- a button with a label on it.
	check(sp.Container.SettingsList.__defaults.__aetherSkin ~= nil,
		"Defaults wears our surface, wherever on the page it happens to be")
	sp:Hide()
end)

print("== movers ==")
SlashCmdList["AETHERUI"]("unlock")
check(A.Movers.unlocked, "movers unlocked")
local entry = A.Movers.registry.player
check(entry and entry.handle and entry.handle:IsShown(), "player mover handle visible")
local h = entry.handle
h:GetScript("OnDragStart")(h)
h:GetScript("OnDragStop")(h)
check(A.db.profile.anchors.player ~= nil, "drag persisted a position")

-- THE WAY OUT OF UNLOCK MODE. Unlocking puts a handle over everything -
-- including the Toolbox, which is exactly what you would reach for to lock
-- again - so without this the only ways back are a slash command and four steps
-- into the options panel. A mode you can leave only by typing is one people get
-- stuck in.
do
	local lock = A.Movers.lockButton
	check(lock ~= nil and lock:IsShown(), "unlocking puts a lock button on screen")

	-- MOVABLE, because it is one more thing over a screen you are arranging and
	-- the one place it must never be is on top of the frame you are dragging.
	-- Not a mover entry of its own: those are moved by a handle, and a handle
	-- over the button that hides the handles is a circle.
	check(A.Movers.registry.__lockButton == nil,
		"and it is not itself a mover entry, which would need a handle of its own")
	lock:GetScript("OnDragStart")(lock)
	lock:GetScript("OnDragStop")(lock)
	check(A.db.profile.anchors.__lockButton ~= nil,
		"dragging it is remembered, so it stays out of the way next time")

	-- AND IT LOCKS. That is the whole job.
	lock:GetScript("OnClick")(lock)
	check(not A.Movers.unlocked, "pressing it locks the frames")
	check(not lock:IsShown(), "and takes itself away with them")

	SlashCmdList["AETHERUI"]("unlock")
	check(A.Movers.lockButton:IsShown(), "unlocking again brings it back")
	check(A.Movers.lockButton:GetNumPoints() == 1,
		"anchored once, not spanned between where it was and where it is now")
end

SlashCmdList["AETHERUI"]("lock")
check(not A.Movers.unlocked, "movers locked")
SlashCmdList["AETHERUI"]("reset")
check(next(A.db.profile.anchors) == nil, "reset cleared saved anchors")

print("== commands: reading a window there is no source for ==")
do
	-- Every panel so far was built by reading Blizzard's own source for this
	-- flavour, which is what says which of a frame's regions carry the picture
	-- and which carry the chrome. Blizzard_Communities is not in the reference
	-- tree and the guild window on this client is Communities, so the addon asks
	-- the client instead of guessing.
	local shown = nil
	local realShow = A.Errors.ShowText
	A.Errors.ShowText = function(_, text) shown = text return end

	-- LOWER CASE, as the dispatcher hands it over. It lower-cases every argument,
	-- which is right for the words the other commands compare and wrong for a
	-- frame name - those are case-sensitive globals. The first attempt reported
	-- "no frame called communitiesframe", which reads as "that window does not
	-- exist" rather than "you typed it the way this addon made you type it".
	A:DumpPanel("characterframe")
	check(shown ~= nil and shown:find("CharacterFrame", 1, true) ~= nil,
		"a frame is found whatever case it was asked for in")

	-- WHICH BUILD PRODUCED IT, on the first line. A dump was once read against
	-- the copy still in memory, and the parts it was missing read as "the client
	-- does not have them" rather than "you have not reloaded yet". Lua loads at
	-- reload; a file on disk is not a build that is running.
	check(shown ~= nil and shown:find(tostring(A.version), 1, true) ~= nil,
		"and the report says which build it came from")
	check(shown ~= nil and shown:find("CharacterFrameTab1", 1, true) ~= nil,
		"and its children come with it, which is the whole point of asking")

	-- BY PARENTKEY where they have no global name. A dump of the guild window
	-- came back with eight named things in six hundred lines and <anonymous>
	-- for everything else, which is a report nobody can act on: you cannot
	-- reach a frame you cannot name. Modern windows hang their parts off the
	-- parent as plain fields, and that field is also the key Element takes.
	check(shown ~= nil and shown:find(".Bg", 1, true) ~= nil,
		"and anything without one is named by the key its parent holds it under")

	-- A FRAGMENT LISTS WHAT IT COULD HAVE MEANT, which is the more useful
	-- command when the question is what an unreadable window is even called.
	shown = nil
	local said = {}
	local realPrint = A.Print
	local chat = _G.DEFAULT_CHAT_FRAME
	local realAdd = chat.AddMessage
	A.Print = function(_, m) said[#said + 1] = tostring(m or "") end
	chat.AddMessage = function(_, m) said[#said + 1] = tostring(m or "") end

	A:DumpPanel("characterfra")
	A.Print, chat.AddMessage = realPrint, realAdd

	check(shown == nil, "a name that matches nothing opens no box")
	local suggested = false
	for _, line in ipairs(said) do
		if line:find("CharacterFrame", 1, true) then suggested = true end
	end
	check(suggested, "and says what it could have meant instead")

	A.Errors.ShowText = realShow
end

print("== other commands ==")
for _, cmd in ipairs({ "", "status", "diag", "hide", "scale 1.2", "shadow 14", "noise 0.5",
	"fade off", "fade on", "fade delay 4", "fade idle 0.2",
	"bar", "bar list", "bar 1 scale 0.8", "bar size 44", "bar 1 rows 2", "bar size 999",
	"bar font 3", "bar 1", "bar nope", "bar 1 bogus", "bar stance buttons 4",
	"bar stance page 2", "bar 1 backdrop", "bar 1 backdrop",
	"module unitframes off", "module unitframes on", "bogus" }) do
	local ok, err = pcall(SlashCmdList["AETHERUI"], cmd)
	if not ok then fail("/aether " .. cmd .. ": " .. tostring(err)) end
end
check(A:GetModule("unitframes").enabled, "module toggled back on cleanly")
-- FOUR NOW: player, target, pet and the target's target. The count is the
-- point of the check - a rebuild would leak a second set, because WoW has no
-- way to destroy a frame.
check(UF.player == A:GetModule("unitframes").player and #UF.frames == 4,
	"toggling the module reuses its frames instead of leaking a second set ("
	.. #UF.frames .. ")")
check(UF.pet ~= nil and UF.pet.unit == "pet", "and the pet capsule is one of them")

do
	local pet = UF.pet
	UF.UpdateAll(pet)

	-- THE SAME SHAPE, at a size of its own. A pet is glanced at rather than
	-- read, and everything the capsule builder makes comes from one config - so
	-- a smaller frame is a scale, not a second set of measurements to keep in
	-- step with the first.
	check(pet.glass:IsShown(), "with a pet out, the capsule is up")
	check(pet.name:GetText() == "Raptor",
		"named after the pet (" .. tostring(pet.name:GetText()) .. ")")
	check(pet.orb ~= nil and pet.health ~= nil and pet.power:IsShown(),
		"carrying an orb, a health bar and the pet's power")
	-- ON TOP OF THE PROFILE'S, not instead of it, which is the arrangement the
	-- console and the nameplates already have.
	check(math.abs(pet:GetScale() - A.db.profile.scale * 0.85) < 0.001,
		"at its own scale on top of the profile's (" .. tostring(pet:GetScale())
		.. " of " .. tostring(A.db.profile.scale) .. ")")
	check(pet:GetScale() < UF.player:GetScale(), "and smaller than the player's")

	-- ITS OWN MOVER, not hung off the player's. A pet frame you cannot put
	-- where you want it is one you end up turning off.
	local entry = A.Movers.registry and A.Movers.registry["pet"]
	check(entry ~= nil and entry.frame == pet,
		"and its own entry in the mover, like the other two")

	-- A MOOD ON THE RIM, and only for the kind of pet that has one.
	local c = A.Palette.c
	local function rim() return pet.orb.disc.__vertex end

	_G.__petHappiness = 3
	UF.UpdateAll(pet)
	local happy = { pet.orb.disc:GetVertexColor() }
	_G.__petHappiness = 1
	UF.UpdateAll(pet)
	local sad = { pet.orb.disc:GetVertexColor() }
	check(math.abs(happy[1] - sad[1]) > 0.01 or math.abs(happy[2] - sad[2]) > 0.01,
		"a happy pet and an unhappy one wear different rims")
	check(math.abs(sad[1] - c.petUnhappy[1]) < 0.01
		and math.abs(sad[2] - c.petUnhappy[2]) < 0.01,
		"and the unhappy one is the colour the palette calls that")

	-- A WARLOCK'S IMP HAS NO MOOD. GetPetHappiness answers nil and Blizzard's
	-- own frame hides the face; a rim tinted from that nil is a rim tinted from
	-- whatever the last hunter left behind.
	_G.__isHunterPet = false
	UF.UpdateAll(pet)
	local imp = { pet.orb.disc:GetVertexColor() }
	check(math.abs(imp[1] - sad[1]) > 0.01 or math.abs(imp[2] - sad[2]) > 0.01,
		"a pet with no mood does not wear the last one's rim")
	_G.__isHunterPet = true
	_G.__petHappiness = 3

	-- AND IT GOES WITH THE PET. Neither getting one nor dismissing one is a unit
	-- event on the pet - UNIT_PET fires on the OWNER - so without that the
	-- capsule sat on the last pet's name and health.
	_G.__units.pet.exists = false
	fire("UNIT_PET", "player")
	check(not pet.glass:IsShown(), "dismissing the pet takes the capsule away")
	_G.__units.pet.exists = true
	fire("UNIT_PET", "player")
	check(pet.glass:IsShown(), "and calling one back brings it up")
end
check(UF.tot ~= nil and UF.tot.unit == "targettarget",
	"and so is the target's target")

if UF.tot then
	local tot = UF.tot
	UF.UpdateAll(tot)

	-- THE PET'S ARGUMENT THE OTHER WAY ROUND: a thing you glance at, at a
	-- size of its own. This client has a target-of-target frame and hides it
	-- behind a setting most players never find.
	check(tot.glass:IsShown(), "with the target on somebody, the capsule is up")
	check(tot.orb ~= nil and tot.health ~= nil,
		"carrying an orb and a health bar like the other three")
	check(math.abs(tot:GetScale() - A.db.profile.scale * 0.85) < 0.001,
		"at its own scale on top of the profile's (" .. tostring(tot:GetScale())
		.. " of " .. tostring(A.db.profile.scale) .. ")")

	-- MIRRORED, like the target's rather than the player's - orb on the
	-- right. It belongs to the target, and the pair reads as a pair wherever
	-- the two are put.
	check(tot.mirror == true, "drawn as the target's is, not the player's")

	-- ITS OWN MOVER, for the reason the pet has one: welded under the target
	-- it would be a frame you turn off rather than move.
	local totEntry = A.Movers.registry and A.Movers.registry["targettarget"]
	check(totEntry ~= nil and totEntry.frame == tot,
		"and its own entry in the mover, like the other three")

	-- A NAME PER UNIT ON THE SECURE BUTTON. This was two names for four
	-- frames - the pet's button and the player's both came out as
	-- AetherUIPlayerFrame - and a click-cast binding names this button.
	local names = {}
	for _, f in ipairs(UF.frames) do
		local n = f.click and f.click.GetName and f.click:GetName()
		if n then
			if names[n] then names[#names + 1] = n end
			names[n] = true
		end
	end
	check(#names == 0, "every capsule's click button has a name of its own ("
		.. (#names > 0 and table.concat(names, ",") or "all four") .. ")")

	-- AND IT FOLLOWS THE TARGET'S TARGET, which changes without your own
	-- target changing. That is a unit event on the TARGET rather than on the
	-- target's target: UNIT_TARGET fires with the unit whose target moved,
	-- and nothing else reports it at all.
	_G.__units.targettarget = { name = "Watermule", hp = 40, hpMax = 100,
		power = 10, powerMax = 100, level = 12, exists = true, class = "MAGE" }
	fire("UNIT_TARGET", "target")
	check(tot.name:GetText() == "Watermule",
		"the capsule follows the target's target without your target changing ("
		.. tostring(tot.name:GetText()) .. ")")
	_G.__units.targettarget = nil
end
check(UF.player:IsShown() and UF.player.name:GetText() == "Palabras",
	"reused frames repopulate after a toggle")

print("== ui scale change ==")
fire("UI_SCALE_CHANGED")
fire("DISPLAY_SIZE_CHANGED")
check(A.pixel > 0 and A.pixel < 4, "pixel scale sane after a resolution change ("
	.. string.format("%.3f", A.pixel) .. ")")

-- ---------------------------------------------------------------------------
print("== action bars ==")

local AB = A:GetModule("actionbars")
check(AB and AB.enabled, "actionbars module enabled"
	.. (AB and AB.lastError and ("  -- " .. AB.lastError) or ""))
--- Bars are never destroyed - WoW has no way to - so a disabled one stays in the
--- list, built and hidden. Count what is actually on, not what exists.
local function EnabledBars()
	local n, ids = 0, {}
	for _, b in ipairs(AB.bars) do
		if b.cfg.enabled ~= false then n = n + 1; ids[#ids + 1] = b.id end
	end
	table.sort(ids)
	return n, table.concat(ids, ", ")
end

do
	local n, ids = EnabledBars()
	check(n == 4, "bar 1 plus stance, pet and extra are on; 2-6 off (" .. ids .. ")")
end

local bar = AB.bars[1]
check(#bar.buttons == 12, "12 buttons in the dock")
check(bar.buttons[1]:GetAttribute("type") == "action", "buttons are secure action buttons")
check(bar.buttons[1]:GetAttribute("action") == 1
	and bar.buttons[12]:GetAttribute("action") == 12,
	"page 1 maps button i to action i")

-- WHAT A BUTTON SAYS ABOUT ITSELF.
--
-- Three states and three tints, and until the literals moved into the palette
-- nothing checked any of them: 0.45/0.55/1 and 0.4/0.4/0.4 sat in the module
-- and could have been swapped for each other without a single check moving.
do
	local c = A.Palette.c
	local function tint(i)
		local r, g, b = bar.buttons[i].icon:GetVertexColor()
		return r, g, b
	end

	-- slot 2 is out of mana, slot 1 is ordinary. The fixture sets both.
	local nr, ng, nb = tint(2)
	check(math.abs(nr - c.iconNoMana[1]) < 0.001
		and math.abs(ng - c.iconNoMana[2]) < 0.001
		and math.abs(nb - c.iconNoMana[3]) < 0.001,
		"a spell you cannot afford takes the no-mana blue (" ..
		string.format("%.2f %.2f %.2f", nr, ng, nb) .. ")")

	local ur, ug, ub = tint(1)
	check(math.abs(ur - 1) < 0.001 and math.abs(ug - 1) < 0.001
		and math.abs(ub - 1) < 0.001,
		"while an ordinary one is UNTINTED - the icon is the artist's, and a"
		.. " tint that never comes off is a permanently wrong icon (" ..
		string.format("%.2f %.2f %.2f", ur, ug, ub) .. ")")

	-- Slot 9 is unusable but affordable, which is the ONLY way to tell the two
	-- branches apart: while every unusable action in the fixture was also a
	-- no-mana one, the second branch was never reached and the two tints could
	-- have been swapped for each other silently.
	local gr, gg, gb = tint(9)
	check(math.abs(gr - c.iconUnusable[1]) < 0.001
		and math.abs(gg - c.iconUnusable[2]) < 0.001
		and math.abs(gb - c.iconUnusable[3]) < 0.001,
		"a spell you simply cannot cast greys out (" ..
		string.format("%.2f %.2f %.2f", gr, gg, gb) .. ")")
	check(bar.buttons[9].icon:IsDesaturated(),
		"and desaturates with it - the dim alone reads as a cooldown")
	check(not bar.buttons[2].icon:IsDesaturated(),
		"while the unaffordable one keeps its colour, because THAT one comes"
		.. " back the moment you drink")

	check(c.iconNoMana[1] ~= c.iconUnusable[1]
		or c.iconNoMana[3] ~= c.iconUnusable[3],
		"and the two tints are different colours to begin with")
	check(c.iconUnusable[1] == c.iconUnusable[2]
		and c.iconUnusable[2] == c.iconUnusable[3],
		"unusable being GREY rather than a hue, which is what pairs with the"
		.. " desaturate the same branch sets")
end

-- The paging snippets are restricted Lua we cannot execute here, but a typo in
-- one is silent and only shows up as "my druid's bar stopped working". Parsing
-- them is cheap insurance.
for _, snippet in ipairs({
	bar.header:GetAttribute("_onstate-page"),
	bar.buttons[1]:GetAttribute("_childupdate-actionpage"),
}) do
	check(type(snippet) == "string" and loadstring(snippet) ~= nil,
		"secure snippet is syntactically valid Lua")
end
check(_G.__stateDrivers.page == nil,
	"no page driver: bars name their own source once and never change it")

check(AB.hideReport ~= nil, "HideBlizzard produced a per-frame report")
