print("== the target's cast bar is not your cast bar ==")
do
	-- Two capsules stacked one above the other, both the concept's blue, was
	-- unreadable mid-fight: the only thing distinguishing them was the spell
	-- name, which is the slowest thing on either bar to read.
	local UFm = A:GetModule("unitframes")
	_G.__units.target.exists = true
	_G.__units.target.reaction = 2          -- hostile

	time = time + 1
	_G.__ccCasts.target = { name = "Lightning Bolt", icon = 1, channel = false,
		start = time * 1000, finish = (time + 3) * 1000 }
	_G.__ccFire("UNIT_SPELLCAST_START", "target")
	local theirs = UFm.targetCast.bar._colors
	check(theirs == A.Palette.c.hostileBar,
		"a hostile caster's bar takes the hostile colours")

	castState = { name = "Fireball", icon = 135812, channel = false,
		startTime = time * 1000, endTime = (time + 2.5) * 1000 }
	fire("UNIT_SPELLCAST_START", "player")
	local yours = UFm.cast.bar._colors
	check(yours == A.Palette.c.cast, "and yours stays the concept's blue")
	check(yours ~= theirs, "so the two stacked bars are tellable apart at a glance")

	-- the glow follows the bar rather than staying blue around a red capsule
	local head = theirs[1]
	local gr, gg, gb = UFm.targetCast.glow:GetVertexColor()
	check(math.abs(gr - head[1]) < 0.01 and math.abs(gg - head[2]) < 0.01
		and math.abs(gb - head[3]) < 0.01,
		"and the glow takes the bar's head, not a blue halo round a red bar")

	-- friendly and neutral are their own answers, not just "not hostile"
	_G.__units.target.reaction = 4
	check(A.Palette:CastColor("target") ~= A.Palette.c.hostileBar, "neutral differs")
	_G.__units.target.reaction = 5
	check(A.Palette:CastColor("target") == A.Palette.c.cast,
		"a friendly caster is not painted as a threat")

	-- your own frame is never a reaction
	check(A.Palette:ReactionEdge("player") == A.Palette.c.glassEdge,
		"and the player's own rim never picks up friendly green off"
		.. " UnitReaction('player', 'player')")

	-- the toggle really turns it off
	A.db.profile.modules.unitframes.reactionTint = false
	_G.__units.target.reaction = 2
	_G.__ccCasts.target = { name = "Lightning Bolt", icon = 1, channel = false,
		start = time * 1000, finish = (time + 3) * 1000 }
	_G.__ccFire("UNIT_SPELLCAST_START", "target")
	check(UFm.targetCast.bar._colors == A.Palette.c.cast,
		"turning the tint off puts both bars back to blue")
	A.db.profile.modules.unitframes.reactionTint = true

	_G.__ccCasts.target = nil
	_G.__ccFire("UNIT_SPELLCAST_STOP", "target")
	castState = nil
	fire("UNIT_SPELLCAST_STOP", "player")
	_G.__units.target.reaction = 2
	_G.__units.target.exists = false
	fire("PLAYER_TARGET_CHANGED")
end

print("== auras: four trays of icon tiles ==")
-- the idle-fader section above dropped the target; put it back
_G.__units.target.exists = true
fire("PLAYER_TARGET_CHANGED")

local AU = A:GetModule("auras")
check(AU and AU.enabled, "auras module enabled"
	.. (AU and AU.lastError and ("  -- " .. AU.lastError) or ""))
check(#AU.trays == 4, "four trays: buffs and debuffs, player and target")

local PB, PD = AU.playerBuffs, AU.playerDebuffs
local TB, TD = AU.targetBuffs, AU.targetDebuffs

check(PB.active == 4, "four player buffs (got " .. PB.active .. ")")
check(PD.active == 2, "two player debuffs (got " .. PD.active .. ")")
check(TB.active == 2, "target buffs are shown at all now (got " .. TB.active .. ")")
check(TD.active == 3,
	"and only the player's own target debuffs (got " .. TD.active .. ")")

do  -- the ring says WHAT KIND of thing is on you
	-- The name is gone from a tile, so the school colour is the only thing
	-- left carrying it - and it has to be the client's own, or a curse reads
	-- as one thing here and another on Blizzard's own frames. Nothing checked
	-- this at all until the table moved into the palette.
	local school = A.Palette.c.debuffSchool
	local missing = {}
	for _, kind in ipairs({ "Magic", "Curse", "Disease", "Poison" }) do
		local c = school[kind]
		if type(c) ~= "table" or type(c[3]) ~= "number" then
			missing[#missing + 1] = kind
		end
	end
	check(#missing == 0,
		"all four schools are named (" .. table.concat(missing, ", ") .. ")")

	-- The player's second debuff is a Curse, the target's first is Magic.
	local curse = PD.tiles[2]
	local cr, cg, cb = curse.art.ring:GetVertexColor()
	check(math.abs(cr - school.Curse[1]) < 0.001
		and math.abs(cg - school.Curse[2]) < 0.001
		and math.abs(cb - school.Curse[3]) < 0.001,
		"a curse wears the curse purple (" ..
		string.format("%.2f %.2f %.2f", cr, cg, cb) .. ")")

	local magic = TD.tiles[1]
	local mr, mg, mb = magic.art.ring:GetVertexColor()
	check(math.abs(mr - school.Magic[1]) < 0.001
		and math.abs(mg - school.Magic[2]) < 0.001
		and math.abs(mb - school.Magic[3]) < 0.001,
		"and a magic debuff the magic blue, which is a DIFFERENT colour - one"
		.. " lookup returning the same tint for both would pass either alone")

	-- An untyped debuff has no school to show, and falls back to danger
	-- rather than to the last colour the ring happened to be wearing.
	local plain = PD.tiles[1]
	local pr = plain.art.ring:GetVertexColor()
	check(math.abs(pr - A.Palette.c.danger[1]) < 0.001,
		"an untyped debuff falls back to danger (" ..
		string.format("%.2f", pr) .. ")")
end

do  -- a tile is an icon and a timer, and nothing else
	local t = PB.tiles[1]
	check(t.name == nil, "no name field on a tile - the name is on the tooltip")
	check(t.art.icon:GetTexture() == 135843, "the icon is painted")
	check(t.time:GetText() == "30m", "the timer reads in minutes at this range")
	-- A mount, a Well Fed, most things a player walks around with. The field is
	-- fixed width either way, so an empty one read as a pill that had failed to
	-- load rather than one with nothing to say.
	check(PB.tiles[4].time:GetText() == "n/a",
		"a permanent aura says so rather than leaving the timer field blank")
	do
		-- On login the server has not finished sending aura data and everything
		-- comes back with a zero duration, which is indistinguishable from a
		-- permanent aura - so every buff was marked timeless, and a timeless tile
		-- is one the ticker never looks at again.
		local saved = _G.__auras.player.HELPFUL
		_G.__auras.player.HELPFUL = {
			{ "Frost Armor", 135843, 0, nil, 0, nil, "player", true },
		}
		fire("PLAYER_ENTERING_WORLD")
		check(PB.tiles[1].time:GetText() == "n/a", "a zero duration reads as timeless")
		_G.__auras.player.HELPFUL = saved
		_G.__tick()                       -- the settle pass the load kicked off
		check(PB.tiles[1].time:GetText() ~= "n/a",
			"and the settle pass picks up the real numbers when they arrive,"
			.. " without needing a UNIT_AURA to happen along")
	end
	check(PB.tiles[4]:GetWidth() == PB.tiles[1]:GetWidth(),
		"and keeps the same width as a timed one")
	check(PB.tiles[3].count:GetText() == 3, "a stack shows its count")
	check(PB.tiles[1].count:GetText() == "", "and a single application does not")

	local spec = AU.spec
	check(t:GetWidth() > spec.size * 2,
		"the pill is wide enough for the icon and a timer beside it")
	check(t:GetHeight() == spec.size + 8,
		"and only a little taller than the icon it wraps, the way the deck draws it")
	check(t.time:GetWidth() == 30,
		"the timer field is fixed width, so a ticking timer cannot resize the pill")
	check(PB.tiles[1]:GetWidth() == PB.tiles[4]:GetWidth(),
		"a permanent aura's pill is the same width as a timed one - the grid has"
		.. " to stay a grid")
end

print("== no tray exceeds the frame it belongs to ==")
do
	local cfg = A.db.profile.modules.auras
	local ufcfg = A.db.profile.modules.unitframes

	for _, t in ipairs(AU.trays) do
		local d = t.display
		local rowW = d.opts.perRow * (AU:TileWidth() + cfg.spacing) - cfg.spacing
		check(rowW <= UF.player:GetWidth(),
			("%s: a full row is %d wide, the capsule is %d")
				:format(t.key, rowW, UF.player:GetWidth()))
	end

	-- Columns are derived, not configured: widen the capsule and every tray gets
	-- wider on its own.
	local before = PB.opts.perRow
	local savedW, savedBar = ufcfg.width, ufcfg.barWidth
	ufcfg.width, ufcfg.barWidth = 500, 340
	A:Reconfigure()
	check(PB.opts.perRow > before,
		("a wider capsule gets more columns without touching the config (%d -> %d)")
			:format(before, PB.opts.perRow))
	ufcfg.width, ufcfg.barWidth = savedW, savedBar
	A:Reconfigure()
	check(PB.opts.perRow == before, "and loses them again when it narrows")

	-- perRow is a cap, not the source
	cfg.perRow = 3
	AU:OnConfigChanged()
	check(PB.opts.perRow == 3, "setting a column cap uses it")
	cfg.perRow = 0
	AU:OnConfigChanged()
	check(PB.opts.perRow == before, "and 0 goes back to whatever fits")
end

print("== the capsules never resize ==")
do
	local cfg = A.db.profile.modules.unitframes

	check(UF.player.tray == nil and UF.target.tray == nil,
		"there is no in-capsule tray any more")
	check(UF.player.glass:GetHeight() == cfg.height
		and UF.target.glass:GetHeight() == cfg.height,
		"both capsules sit at their designed height")
	local gp, _, grelP = UF.player.glass:GetPoint(1)
	check(gp == "TOPLEFT" and grelP == "TOPLEFT"
		and UF.player.glass:GetNumPoints() == 2,
		"the glass fills the core exactly rather than being pinned to its top edge")

	-- The complaint that started this: one unit with a debuff and one without
	-- used to be two frames of different heights side by side.
	local savedP = _G.__auras.player.HARMFUL
	_G.__auras.player.HARMFUL = {}
	fire("UNIT_AURA", "player")
	check(PD.active == 0 and TD.active > 0, "player clean, target debuffed")
	check(UF.player.glass:GetHeight() == UF.target.glass:GetHeight(),
		"the two capsules are still exactly the same height - which is the whole"
		.. " point of taking the auras out of them")
	_G.__auras.player.HARMFUL = savedP
	fire("UNIT_AURA", "player")
end

print("== tray placement ==")
do
	local cfg = A.db.profile.modules.auras

	local bp, brel, brelP = PB.frame:GetPoint(1)
	check(bp == "BOTTOMLEFT" and brel == UF.player and brelP == "TOPLEFT",
		"player buffs hang off the top of the player capsule (got "
		.. tostring(bp) .. " -> " .. tostring(brelP) .. ")")
	local dp, drel, drelP = PD.frame:GetPoint(1)
	check(dp == "TOPLEFT" and drel == UF.player and drelP == "BOTTOMLEFT",
		"player debuffs off the bottom")
	check(select(2, TB.frame:GetPoint(1)) == UF.target
		and select(2, TD.frame:GetPoint(1)) == UF.target,
		"and the target's two hang off the target, the same way round")

	check(PB.opts.growUp and not PD.opts.growUp,
		"rows grow away from the capsule, so the row nearest the frame stays put")
	check(PB.frame:GetParent() == UF.player,
		"a tray is a child of its capsule, so it inherits the fade and the scale")
	check(PB.frame:GetScale() == 1,
		"and takes no scale of its own - the capsule is already scaled")

	-- Centred, because a row of pills almost never divides evenly into a capsule
	-- and the slack pushed onto one side reads as a pill that failed to load.
	check(PB.opts.align == "CENTER" and TD.opts.align == "CENTER",
		"rows are centred on their frame by default")
	do
		local n, tw, gap = PB.active, AU:TileWidth(), cfg.spacing
		local rowW = n * tw + (n - 1) * gap
		local p, rel, relP, x = PB.tiles[1]:GetPoint(1)
		check(p == "BOTTOM" and relP == "BOTTOM" and rel == PB.frame,
			"a centred tile is anchored on the frame's centre line")
		check(math.abs(x - (-rowW / 2 + tw / 2)) < 0.01,
			("the first pill sits half a row left of centre (%.1f)"):format(x))
		-- and the row is symmetric about it
		local _, _, _, xn = PB.tiles[n]:GetPoint(1)
		check(math.abs(x + xn) < 0.01,
			("the last pill mirrors it (%.1f vs %.1f)"):format(x, xn))
	end

	-- ...and mirrored is still there for anyone who wants it
	cfg.align = "MIRROR"
	AU:OnConfigChanged()
	check(PB.opts.align == "LEFT" and TD.opts.align == "RIGHT",
		"mirrored follows the unit's own name and readout - left on the player,"
		.. " right on the target")
	check(select(1, TD.tiles[1]:GetPoint(1)) == "TOPRIGHT",
		"so a half-full target row is measured back from the right edge")
	cfg.align = "CENTER"
	AU:OnConfigChanged()

	-- second row
	local savedB = _G.__auras.player.HELPFUL
	local many = {}
	for i = 1, PB.opts.perRow + 2 do
		many[i] = { "Buff " .. i, 130000 + i, 0, nil, 60, nil, "player", true }
	end
	_G.__auras.player.HELPFUL = many
	fire("UNIT_AURA", "player")
	check(PB.active == PB.opts.perRow + 2, "a full row plus two")
	local _, _, _, _, y1 = PB.tiles[1]:GetPoint(1)
	local _, _, _, _, y2 = PB.tiles[PB.opts.perRow + 1]:GetPoint(1)
	check(y2 > y1, "the second row stacks upward, away from the capsule")
	_G.__auras.player.HELPFUL = savedB
	fire("UNIT_AURA", "player")
end

print("== timers ==")
do
	local before = PB.tiles[1]:GetWidth()
	time = time + 120
	PB:Tick()
	check(PB.tiles[1].time:GetText() == "28m", "the timer ticks down")
	check(PB.tiles[1]:GetWidth() == before,
		"and cannot reflow anything - every tile is the same size whatever its"
		.. " timer says")

	-- an aura about to fall off says so
	local saved = _G.__auras.player.HELPFUL
	_G.__auras.player.HELPFUL = {
		{ "Ice Barrier", 135988, 0, nil, 30, nil, "player", true },
	}
	fire("UNIT_AURA", "player")
	PB:Tick()
	check(PB.tiles[1]._urgent == false, "a healthy timer is not urgent")
	time = time + 27
	PB:Tick()
	check(PB.tiles[1]._urgent == true, "under five seconds it turns urgent")
	_G.__auras.player.HELPFUL = saved
	fire("UNIT_AURA", "player")
	PB:Tick()
	check(PB.tiles[1]._urgent ~= true, "and back again when it is replaced")
end


print("== auras: a timer that has not arrived yet is never a blank field ==")
do
	local saved = _G.__auras.player.HELPFUL

	-- Case one, as the client actually reports it for the first few seconds
	-- after a login: a real duration with an expiry of zero. This used to come
	-- out of W.AuraTime as an empty string, get written to a fixed-width field,
	-- and stay empty for the rest of the session because the tile was not
	-- flagged timeless and the ticker just kept writing the same nothing.
	_G.__auras.player.HELPFUL = {
		{ "Arcane Intellect", 135932, 0, nil, 1800, nil, "player", true, 0 },
	}
	fire("UNIT_AURA", "player")
	local t = PB.tiles[1]
	check(t.time:GetText() == "n/a",
		"a duration with no expiry reads n/a rather than going blank (got '"
		.. tostring(t.time:GetText()) .. "')")
	check(t._stale == true and t._timeless == false,
		"and is marked stale, not permanent - the difference is whether we ever"
		.. " ask again")

	-- the server catches up. No UNIT_AURA fires, because nothing changed as far
	-- as the client is concerned - the re-poll is the only thing that can notice.
	_G.__auras.player.HELPFUL[1][9] = nil
	for i = 1, 15 do tick(0.1) end
	check(t.time:GetText() == "30m",
		"and the tile picks the real timer up on its own, with no UNIT_AURA to"
		.. " prompt it (got '" .. tostring(t.time:GetText()) .. "')")
	check(t._stale == false, "and stops asking")

	-- Case two: duration zero, which is what a permanent aura and an aura the
	-- server has not described yet both look like.
	_G.__auras.player.HELPFUL = {
		{ "Frost Armor", 135843, 0, nil, 0, nil, "player", true },
	}
	fire("UNIT_AURA", "player")
	t = PB.tiles[1]
	check(t.time:GetText() == "n/a" and t._timeless == true,
		"duration zero reads n/a and is believed permanent")

	_G.__auras.player.HELPFUL[1][5] = 1800
	for i = 1, 15 do tick(0.1) end
	check(t.time:GetText() == "30m",
		"but the belief is re-tested, so a buff that turns out to have a timer"
		.. " gets one (got '" .. tostring(t.time:GetText()) .. "')")

	-- and a re-poll must not read a neighbour's clock when indices shift
	_G.__auras.player.HELPFUL = {
		{ "Well Fed", 133905, 0, nil, 0, nil, nil, false },
	}
	fire("UNIT_AURA", "player")
	t = PB.tiles[1]
	check(t._timeless == true and t._name == "Well Fed", "a genuinely permanent aura")
	_G.__auras.player.HELPFUL = {
		{ "Ice Barrier", 135988, 0, nil, 60, nil, "player", true },
	}
	for i = 1, 15 do tick(0.1) end   -- no UNIT_AURA: the tile still thinks it is Well Fed
	check(t.time:GetText() == "n/a",
		"whose tile refuses to take a duration from whatever now sits at its"
		.. " index, because the name no longer matches")

	-- The sequence actually seen in game. The buff is a real thirty-minute one
	-- with time left on it, but at login the client hands out an expiry that is
	-- only a few seconds away. The tile counts that down, reaches zero, and -
	-- before this - printed an empty string into a fixed-width field and kept
	-- printing it, because a tile only ever re-formats the numbers it cached at
	-- the last Update and UNIT_AURA never fires again if nothing changes.
	_G.__auras.player.HELPFUL = {
		{ "Arcane Intellect", 135932, 0, nil, 1800, nil, "player", true,
		  GetTime() + 3 },
	}
	fire("UNIT_AURA", "player")
	t = PB.tiles[1]
	check(t.time:GetText() == "3s", "a bad expiry from the server counts down")
	for i = 1, 40 do tick(0.1) end
	check(t.time:GetText() ~= "",
		"and when it runs out the field never goes blank (got '"
		.. tostring(t.time:GetText()) .. "')")

	_G.__auras.player.HELPFUL[1][9] = nil   -- the client finally has it right
	for i = 1, 15 do tick(0.1) end
	check(t.time:GetText() == "30m",
		"the tile re-reads and picks up the real remaining time, with no"
		.. " UNIT_AURA and long after Resettle has given up (got '"
		.. tostring(t.time:GetText()) .. "')")

	-- the diagnostic has to survive whatever state the trays are in, because the
	-- one time anybody runs it is when something is wrong
	_G.__auras.player.HELPFUL = {
		{ "Arcane Intellect", 135932, 0, nil, 1800, nil, "player", true, 0 },
		{ "Well Fed", 133905, 0, nil, 0, nil, nil, false },
	}
	fire("UNIT_AURA", "player")
	local printed = 0
	local realAdd = DEFAULT_CHAT_FRAME.AddMessage
	DEFAULT_CHAT_FRAME.AddMessage = function(self, msg)
		printed = printed + 1
		realAdd(self, msg)
	end
	local ok, err = pcall(function() SlashCmdList["AETHERUI"]("auras") end)
    DEFAULT_CHAT_FRAME.AddMessage = realAdd
	check(ok, "the aura diagnostic runs: " .. tostring(err))
	check(printed > 8,
		"and prints what the API says next to what the tile believes, which is the"
		.. " only way any of these has ever actually been found (" .. printed
		.. " lines)")

	_G.__auras.player.HELPFUL = saved
	fire("UNIT_AURA", "player")
end

print("== an empty tray takes up no room ==")
do
	local tall = PB.frame:GetHeight()
	local saved = _G.__auras.player.HELPFUL
	_G.__auras.player.HELPFUL = {}
	fire("UNIT_AURA", "player")
	check(PB.frame:GetHeight() < tall and PB.active == 0,
		"an empty tray collapses instead of holding its last size")
	check(PB.tiles[1]:GetAlpha() == 0,
		"and its tiles are parked rather than hidden - hiding one would be"
		.. " refused in combat, since they carry secure cancel buttons")
	_G.__auras.player.HELPFUL = saved
	fire("UNIT_AURA", "player")

	_G.__units.target.exists = false
	fire("PLAYER_TARGET_CHANGED")
	check(TB.active == 0 and TD.active == 0, "both target trays clear with no target")
	_G.__units.target.exists = true
	fire("PLAYER_TARGET_CHANGED")
	check(TD.active == 1 or TD.active == 3, "and come back with one")
end

print("== turning a tray off ==")
do
	local cfg = A.db.profile.modules.auras
	cfg.buffs.target = false
	AU:OnConfigChanged()
	check(not AU.trays[3].enabled and TB.active == 0,
		"target buffs off empties that tray and only that tray")
	check(TD.active > 0, "the target's debuffs are untouched")
	cfg.buffs.target = true
	AU:OnConfigChanged()
	check(TB.active > 0, "and back on again")
end

print("== right-click to cancel ==")
do
	local cfg = A.db.profile.modules.auras.buffs

	check(AU.playerBuffs.tiles[PB.opts.max] ~= nil,
		"every buff tile is built up front, not lazily (" .. PB.opts.max .. " of them)")

	local bad = nil
	for i = 1, PB.opts.max do
		local c = PB.tiles[i] and PB.tiles[i].click
		if not c or c:GetAttribute("type2") ~= "macro" then bad = i break end
	end
	check(bad == nil, "every tile carries a secure macro button"
		.. (bad and (" (tile " .. bad .. " does not)") or ""))

	-- "cancelaura" as a secure action type does not dispatch on Classic Era -
	-- right-click did nothing. /cancelaura via a macro does.
	local m = {}
	for i = 1, PB.active do m[i] = PB.tiles[i].click:GetAttribute("macrotext2") end
	check(m[1] == "/cancelaura Frost Armor" and m[3] == "/cancelaura Ice Barrier",
		"the macro cancels by name (got " .. tostring(m[3]) .. ")")

	check(PB.tiles[1].click:GetNumPoints() == 2,
		"the cancel button tracks the tile with SetAllPoints, so resizing the tile"
		.. " in combat never touches the secure frame")
	check(PB.tiles[1].click:GetScript("PreClick") == nil,
		"nothing insecure sits *before* the secure dispatch - a PreClick hook taints"
		.. " it and the cancel gets refused in combat")
	check(PB.tiles[1].click:GetScript("PostClick") ~= nil,
		"but PostClick does the out-of-combat cancel, after the dispatch")

	check(PD.tiles[1] and PD.tiles[1].click == nil and PD.tiles[1]._auraName == nil,
		"debuff tiles get no cancel wiring at all - debuffs cannot be cancelled")
	check(TB.tiles[1] and TB.tiles[1].click == nil,
		"and neither do the target's buffs - they are not yours to drop")

	-- the actual cancel, both routes
	do
		_G.__cancelled = nil
		PB.tiles[2].click:GetScript("PostClick")(PB.tiles[2].click, "RightButton")
		check(_G.__cancelled ~= nil and _G.__cancelled.index == 2,
			"right-click out of combat cancels the buff that tile is showing")

		_G.__cancelled = nil
		PB.tiles[2].click:GetScript("PostClick")(PB.tiles[2].click, "LeftButton")
		check(_G.__cancelled == nil, "left-click does not")

		_G.__inCombat = true
		_G.__cancelled = nil
		PB.tiles[2].click:GetScript("PostClick")(PB.tiles[2].click, "RightButton")
		check(_G.__cancelled == nil,
			"and in combat the insecure route stands down - only the macro can act")
		_G.__inCombat = false

		-- the tile underneath covers the case where the secure button never built
		_G.__cancelled = nil
		local orphan = PB.tiles[3]
		orphan:GetScript("OnMouseUp")(orphan, "RightButton")
		check(_G.__cancelled ~= nil and _G.__cancelled.index == 3,
			"the tile's own OnMouseUp is the same handler, for when there is no"
			.. " secure button on top of it")
	end

	-- raising the cap mid-fight has to defer, then land
	-- The cap is min(configured max, columns x rows), so raising it means
	-- raising the row count, not the number - which is itself worth asserting.
	local cols, wasMax, wasRows = PB.opts.perRow, PB.opts.max, cfg.maxRows
	-- Tiles are never destroyed, only parked, and an earlier section ran with the
	-- unit frames off - where a tray has no capsule to size itself against and
	-- takes the configured max instead. Start this one from an empty display so
	-- "was it built during the fight" means what it says.
	for i = #PB.tiles, 1, -1 do PB.tiles[i] = nil end
	PB.active = 0
	_G.__inCombat = true
	cfg.maxRows = wasRows + 2
	AU:OnConfigChanged()
	local want = math.min(cfg.max, cols * cfg.maxRows)
	check(PB.opts.max == want and want > wasMax,
		("the cap is columns x rows, capped by the configured max (%d)"):format(want))
	check(PB._primePending, "raising the buff cap in combat defers the wiring")
	check(PB.tiles[want] == nil or PB.tiles[want].click == nil,
		"and writes no secure attribute while locked")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(PB.tiles[want] and PB.tiles[want].click
		and PB.tiles[want].click:GetAttribute("type2") == "macro",
		"the deferred wiring lands when the fight ends")
	check(not PB._primePending, "and the pending flag clears")
	cfg.maxRows = wasRows
	AU:OnConfigChanged()

	-- The one this whole section was missing. The tray's tiles carry secure
	-- buttons, so the tray *and every tile in it* is off limits for geometry in
	-- combat - the restriction reaches ancestors, not just the protected frame.
	-- Buffs coming and going mid-fight is the most ordinary thing there is, and
	-- it produced fourteen blocked-action reports per fight.
	local savedBuffs = _G.__auras.player.HELPFUL
	_G.__inCombat = true
	A.lastFailure = nil

	_G.__auras.player.HELPFUL = {
		{ "Arcane Intellect", "T1", 0, nil, 1800, GetTime() + 1500, true },
		{ "Ice Armor",        "T2", 0, nil, 1800, GetTime() + 900,  true },
		{ "Evocation",        "T3", 3, nil,    8, GetTime() + 6,    true },
	}
	fire("UNIT_AURA", "player")
	_G.__auras.player.HELPFUL = {
		{ "Arcane Intellect", "T1", 0, nil, 1800, GetTime() + 1500, true },
	}
	fire("UNIT_AURA", "player")

	check(A.lastFailure == nil,
		"buffs coming and going mid-fight ask the client for nothing it will"
		.. " refuse (" .. tostring(A.lastFailure) .. ")")
	check(PB.active == 1, "and the tray still tracks what is actually up")
	check(PB.tiles[1]:GetAlpha() == 1 and PB.tiles[2]:GetAlpha() == 0,
		"the ones that dropped go to alpha rather than being moved or hidden")
	check(PB._layoutPending, "with the layout owed until the fight ends")

	-- A tile that has never been on screen still has a home, or a buff gained
	-- mid-fight would land nowhere: a frame with no points does not draw.
	check(PB.tiles[PB.opts.max] and PB.tiles[PB.opts.max]:GetPoint(1) ~= nil,
		"every slot was placed up front, so a new buff mid-fight has somewhere"
		.. " to appear")

	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(not PB._layoutPending, "and the layout is settled when it does")

	_G.__auras.player.HELPFUL = savedBuffs
	fire("UNIT_AURA", "player")
end

print("== quest tracker ==")

local QT = A:GetModule("questtracker")
check(QT and QT.enabled, "questtracker module enabled"
	.. (QT and QT.lastError and ("  -- " .. QT.lastError) or ""))
check(QT.panel and QT.panel.header, "glass panel with a header built")

do
	-- The fader section above entered combat and never left it, so the tracker
	-- is legitimately folded by the time we get here. Start from a known state.
	_G.__inCombat = false
	QT._preCombat = nil
	QT:SetCollapsed(false)
	A.db.char.tracked, A.db.char.untracked = {}, {}
	QT:Refresh()

	-- auto mode is the default: everything in the log, nothing to opt in to
	check(#QT.quests == 4,
		"auto-track shows every quest in the log with no gesture at all (got "
		.. #QT.quests .. ")")
	check(GetNumQuestWatches() == 0 and #_G.__watches == 0,
		"and never touches Blizzard's watch list to do it")
	check(QT.panel.header.count:GetText() == "4 / 20",
		"the heading counts quests in the log, not headers in it (got "
		.. tostring(QT.panel.header.count:GetText()) .. ")")

	-- dismissing one is a blacklist entry, and it has to stick across a refresh
	QT.SetTracked(1069, false)
	QT:Refresh()
	check(#QT.quests == 3 and A.db.char.untracked[1069],
		"dismissing a quest blacklists it rather than rebuilding a whitelist")
	local stillThere = false
	for _, q in ipairs(QT.quests) do
		if q.questID == 1069 then stillThere = true end
	end
	check(not stillThere, "and it stays gone across a refresh")

	-- a newly accepted quest appears on its own
	table.insert(_G.__questLog, { id = 7777, title = "A Fresh Errand", level = 20,
		objectives = { { "Errand run: 0/1", "event", false } } })
	QT:Refresh()
	check(#QT.quests == 4, "a newly accepted quest shows up without being tracked")
	table.remove(_G.__questLog)

	QT.SetTracked(1069, true)
	QT:Refresh()
	check(#QT.quests == 4 and A.db.char.untracked[1069] == nil, "and can be brought back")
end

do  -- both sets are pruned against the live log, the way Questie prunes its two
	A.db.char.untracked[999999] = true
	A.db.char.tracked[888888] = true
	QT:Refresh()
	check(A.db.char.untracked[999999] == nil and A.db.char.tracked[888888] == nil,
		"IDs that are not in the log are dropped from both sets - neither can grow"
		.. " without bound")
end

print("== quest tracker: manual mode ==")
do
	A.db.profile.modules.questtracker.autoTrack = false
	A.db.char.tracked, A.db.char.untracked = {}, {}
	QT:Refresh()
	check(#QT.quests == 0, "manual mode starts empty - it is a whitelist")
	local bare = QT.panel:GetHeight()

	-- shift-clicking in Blizzard's quest log puts an index in ITS watch list;
	-- we adopt it and hand the slot straight back, which is the only way that
	-- gesture keeps working past Blizzard's five-quest cap
	AddQuestWatch(2)
	AddQuestWatch(3)
	QT:Refresh()
	check(GetNumQuestWatches() == 0,
		"Blizzard's watch list is emptied again, so its five-slot cap never bites")
	check(A.db.char.tracked[861] and A.db.char.tracked[1069],
		"and both quests landed in our own set, keyed by questID")
	check(#QT.quests == 2, "two rows now (got " .. #QT.quests .. ")")
	check(QT.panel:GetHeight() > bare, "the panel grew to fit them")
end

do
	local row = QT.panel.rows[1]
	check(row.questTitle == "Chen's Empty Keg", "row 1 is the first tracked quest in log order")
	check(row.lines[1]:GetText() == "Empty Keg: 0/1", "objective text rendered")
	check(math.abs(QT.quests[1].pct - 0) < 0.01,
		"progress comes from the numbers in the objective text")
	check(QT.quests[2].complete and math.abs(QT.quests[2].pct - 1) < 0.01,
		"a finished quest reads as complete")
end

do  -- indices shift when the log changes; the tracker must not hold one
	table.insert(_G.__questLog, 2, { id = 99, title = "A New Quest", level = 12, objectives = {} })
	QT:Refresh()
	local row = QT.panel.rows[1]
	check(row.questTitle == "Chen's Empty Keg" and row.index == 3,
		"the same quest is still row 1, now at log index " .. tostring(row.index)
		.. " - tracking is by questID, not by index")
	table.remove(_G.__questLog, 2)
	QT:Refresh()
end

do  -- partial progress across two objectives: 3/8 and 1/4 is 4/12
	AddQuestWatch(5)
	QT:Refresh()
	local q
	for _, entry in ipairs(QT.quests) do
		if entry.questID == 4901 then q = entry end
	end
	check(q and math.abs(q.pct - (4 / 12)) < 0.001,
		"progress sums the counters across every objective (got "
		.. string.format("%.3f", q and q.pct or -1) .. ")")
	check(#QT.panel.rows[3].lines >= 2, "both objective lines drawn")
end

do  -- a quest with no objectives falls back to isComplete rather than showing 0%
	AddQuestWatch(6)
	QT:Refresh()
	local q
	for _, entry in ipairs(QT.quests) do
		if entry.questID == 5041 then q = entry end
	end
	check(q and #q.lines == 0 and q.pct == nil,
		"an objective-less quest gets no bar at all, rather than one pinned at zero")
end

print("== quest tracker: height budget ==")
do
	local cfg = A.db.profile.modules.questtracker
	local saved = cfg.maxHeight
	cfg.maxHeight = 80
	QT:Refresh()
	check(QT.hidden > 0, "a tight height budget drops rows (" .. QT.hidden .. " of them)")
	check(QT.panel.more:IsShown() and QT.panel.more:GetText() == "+" .. QT.hidden .. " more",
		"and the panel says so rather than silently truncating (got "
		.. tostring(QT.panel.more:GetText()) .. ")")

	-- AND IT OPENS THE LOG. That line was the one thing in this panel naming
	-- something you could not get to: it says the tracker ran out of room, and
	-- the place the rest of them live is one click away.
	check(QT.panel.moreHit and QT.panel.moreHit:IsShown(),
		"the line is clickable")
	check(QT.panel.moreQuest ~= nil,
		"and knows which quest it is standing in for")

	do
		-- AT THE FIRST OF THE HIDDEN ONES, which is what somebody reading that
		-- line is asking about - not at whatever the log picks for itself.
		local want = QT.panel.moreQuest

		-- THE FIRST HIDDEN ONE, not the first tracked one. Those are the same
		-- quest whenever nothing is hidden, so the difference only shows on a
		-- panel that has actually run out of room - which is this one.
		local firstShown = QT.panel.rows[1] and QT.panel.rows[1].questID
		check(firstShown ~= nil and want.questID ~= firstShown,
			"and it is one of the HIDDEN quests rather than the first row that"
			.. " is already on screen (" .. tostring(want.questID) .. " vs "
			.. tostring(firstShown) .. ")")

		local QLg = A:GetModule("questlog")
		QLg:Hide()
		QT.panel.moreHit:GetScript("OnClick")(QT.panel.moreHit)
		check(QLg.win and QLg.win:IsShown(), "clicking it opens our log")
		check(QLg.selectedID == (want.questID or ("i" .. tostring(want.index))),
			"at the first quest it was standing in for (got "
			.. tostring(QLg.selectedID) .. ", want "
			.. tostring(want.questID or ("i" .. tostring(want.index))) .. ")")
		QLg:Hide()
	end

	local tight = QT.panel:GetHeight()
	cfg.maxHeight = saved
	QT:Refresh()
	check(not QT.panel.more:IsShown() and QT.panel:GetHeight() > tight,
		"restoring the budget brings them back")
	check(not QT.panel.moreHit:IsShown(),
		"and the click target goes with the line rather than being left over"
		.. " the rows that replaced it")
end

print("== quest tracker: clicks ==")
do
	local row = QT.panel.rows[1]

	-- This check used to read `__questLogOpenedTo == row.index`, which asserted
	-- that Blizzard's QuestLog_OpenToQuest had been called - and that WAS the
	-- bug. A test can only ever pin down the behaviour somebody wrote into it;
	-- this one pinned down opening the very window the addon replaces, and went
	-- green for as long as it kept happening.
	local QL = A:GetModule("questlog")
	QL:Hide()
	_G.__questLogOpenedTo = nil
	row:GetScript("OnMouseUp")(row, "LeftButton")
	check(QL.win and QL.win:IsShown() and QL.selectedID == row.questID,
		"left-click opens OUR log at that quest")
	check(_G.__questLogOpenedTo == nil,
		"and leaves Blizzard's frame alone (it is the one we replaced)")
	QL:Hide()

	-- shift-click untracks
	_G.__shift = true
	local before = #QT.quests
	row:GetScript("OnMouseUp")(row, "LeftButton")
	check(#QT.quests == before - 1, "shift-click stops tracking it")
	check(A.db.char.tracked[861] == nil, "and it leaves our set")
	_G.__shift = false
	AddQuestWatch(2)
	QT:Refresh()

	-- right-click menu
	local r = QT.panel.rows[1]
	r:GetScript("OnMouseUp")(r, "RightButton")
	check(A.Widgets.MenuFrame() and A.Widgets.MenuFrame():IsShown(), "right-click opens the menu")
	check(#A.Widgets.MenuFrame().items >= 4, "menu has open / untrack / share / abandon")
	check(A.Widgets.MenuFrame().items[1].text:GetText() == "Open quest log", "first item opens the log")

	-- ...and it had better be OURS. Every route this used to take reached for
	-- Blizzard's QuestLogFrame - the frame Modules/QuestLog.lua exists to replace
	-- - so clicking a row opened the window the addon spends a module hiding, and
	-- threw on the way there: QuestLog_OnShow calls QuestLog_SetSelection BEFORE
	-- QuestLog_Update, and the selection path reads titleButton.r, which only
	-- Update ever writes. On a frame nobody has drawn that is SetVertexColor(nil).
	do
		local QL = A:GetModule("questlog")
		QL:Hide()
		_G.__questLogOpenedTo = nil

		local row = QT.panel.rows[1]
		row:GetScript("OnMouseUp")(row, "LeftButton")

		check(QL.win and QL.win:IsShown(),
			"clicking a row opens OUR quest log, not the one this addon replaced")
		check(_G.__questLogOpenedTo == nil,
			"and never calls Blizzard's QuestLog_OpenToQuest, which shows their"
			.. " frame and takes the SetVertexColor(nil) crash with it")
		QL:Hide()

		-- Opened AT the clicked quest - and this has to be checked against a row
		-- the log would NOT have landed on by itself. Asserting it on row 1 is
		-- vacuous: EnsureSelection picks the first quest on show, so removing the
		-- Select call entirely leaves the check green. (Confirmed by mutation:
		-- deleting the select passed until this block used a different row.)
		local default_ = nil
		QL:Show()
		default_ = QL.selectedID
		QL:Hide()

		local other
		for i = 1, #QT.panel.rows do
			local r2 = QT.panel.rows[i]
			if r2:IsShown() and r2.questID and r2.questID ~= default_ then other = r2 break end
		end
		check(other ~= nil,
			"there is a tracked row the log would not select on its own, or the"
			.. " check below proves nothing (default " .. tostring(default_) .. ")")
		if other then
			other:GetScript("OnMouseUp")(other, "LeftButton")
			check(QL.selectedID == other.questID,
				"opened AT the quest that was clicked rather than at whatever the"
				.. " log picks for itself (got " .. tostring(QL.selectedID)
				.. ", want " .. tostring(other.questID) .. ", default "
				.. tostring(default_) .. ")")
		end
		QL:Hide()
	end

	-- The menu opens ON TOP of the tracker's own panel, so it is a surface you
	-- read through two layers of glass unless it stops being glass. It takes the
	-- modal fill for exactly the reason the palette gives that token.
	check(A.Widgets.MenuFrame()._fillColor == A.Palette.c.dialogFill,
		"the menu is not glass - it takes the same fill as the abandon dialog")
	check((A.Widgets.MenuFrame()._fillColor[4] or 1) > (A.Palette.c.glassStrong[4] or 1),
		"which is more opaque than the panel underneath it (" .. (A.Widgets.MenuFrame()._fillColor[4] or 1)
		.. " vs " .. (A.Palette.c.glassStrong[4] or 1) .. ")")
	check(A.Widgets.MenuFrame()._edgeColor == A.Palette.c.glassEdgeHi,
		"with the brighter rim, or an opaque fill in a dim rim reads as a hole")

	-- And it follows a skin change, which goes through ApplySkin rather than
	-- through the constructor - the one place the two can disagree.
	local wasSkin = A.db.profile.skin
	A.db.profile.skin = OTHER
	A:Restyle()
	check(A.Widgets.MenuFrame()._fillColor == A.Palette.c.dialogFill
		and A.Widgets.MenuFrame()._edgeColor == A.Palette.c.glassEdgeHi,
		"and it is still the dialog surface after a skin change, not glass again")
	A.db.profile.skin = wasSkin
	A:Restyle()

	_G.__questShared = nil
	A.Widgets.MenuFrame().items[3]:GetScript("OnClick")(A.Widgets.MenuFrame().items[3])
	check(_G.__questShared == r.index, "share quest routes through SelectQuestLogEntry")
	check(not A.Widgets.MenuFrame():IsShown(), "and the menu closes behind it")

	_G.__abandonPopup = nil
	r:GetScript("OnMouseUp")(r, "RightButton")
	A.Widgets.MenuFrame().items[4]:GetScript("OnClick")(A.Widgets.MenuFrame().items[4])
	check(_G.__abandonPopup == "ABANDON_QUEST",
		"abandon goes through Blizzard's confirmation, never straight to AbandonQuest")
end

-- ---------------------------------------------------------------------------
-- Questie and TomTom mocks
--
-- Modelled on the contracts read out of the installed copies - Questie 11.33.2
-- and TomTom v4.3.8-release - rather than on how they are usually described,
-- because every detail below is a way this integration can be wrong while
-- looking perfectly right on screen:
--
--   * QuestieLoader:ImportModule returns an EMPTY STUB for a name it does not
--     know. Never nil, never an error. A module renamed out from under us is
--     therefore a table whose functions are all nil, and the only way to notice
--     is to type-check each one.
--   * Questie's spawn tables are keyed by AREA id, not uiMapID, and hold {x, y}
--     in 0-100. TomTom wants a uiMapID and 0-1. Two conversions, either of
--     which silently produces a waypoint somewhere else entirely.
--   * GetNearestSpawnForQuest returns the FINISHER when quest:IsComplete() == 1.
--   * ZoneDB:GetUiMapIdByAreaId is a COLON call - DistanceUtils' are not - and
--     returns nil for an area it has no mapping for.
--   * TomTom:AddWaypoint returns a uid TABLE, and deduplicates on map/x/y/title
--     without re-pointing its arrow, so a repeat call is a silent no-op.
-- ---------------------------------------------------------------------------

local questieNPCs = {
	-- npcId = { name, spawns keyed by areaId with 0-100 coords, dist = Questie's
	-- own ordering number, which is NOT yards and whose "nothing" is 999999999 }
	[3271] = { name = "Savannah Prowler", dist = 100, spawns = { [17] = { { 45.0, 62.0 } } } },
	[3441] = { name = "Mankrik",          dist = 100, spawns = { [17] = { { 52.5, 31.0 } } } },
	[3272] = { name = "Distant Prowler",  dist = 900, spawns = { [17] = { { 80.0, 20.0 } } } },
	[3273] = { name = "Near Prowler",     dist =  10, spawns = { [17] = { { 30.0, 40.0 } } } },
	[9999] = { name = "Somewhere Odd",    dist = 100, spawns = { [4242] = { { 10.0, 10.0 } } } },
	[8888] = { name = "In A Dungeon",     dist = 100, spawns = { [17] = { { -1, -1 } } } },
	[7777] = { name = "Off The Map",      dist = 100, spawns = { [17] = { { 150.0, 20.0 } } } },
	[6666] = { name = "Malformed",        dist = 100, spawns = "not a table" },
}

local questieObjects = {
	[1617] = { name = "Silverleaf", dist = 100, spawns = { [17] = { { 22.0, 74.0 } } } },
}

local questieItems = {
	-- What GetItem returns: an item has no location of its own, only sources.
	[4632] = { Sources = { { Id = 3273, Type = "monster" }, { Id = 1617, Type = "object" } } },
}

-- Counters for the things we should never hand another addon: a spawn table
-- that is not a table, or a nil area id. Both are guarded in Nav, and without
-- these the guards look redundant - the pcall around them would swallow the
-- error and the result would be nil either way, which is what the caller wanted
-- anyway. The property being tested is not "we survive it", it is "we do not do
-- it": an error raised inside Questie shows up in the player's chat as Questie's
-- bug, with our name nowhere near it.
local questieCalls = { getQuest = 0, badSpawns = 0, nilArea = 0 }

local function questieQuest(id, opts)
	opts = opts or {}
	local q = {
		Id = id,
		Objectives = opts.objectives or {},
		SpecialObjectives = {},
		ObjectiveData = opts.objectiveData or {},
		-- ALWAYS a table, exactly as QuestieDB.GetQuest builds it - it assigns
		-- Finisher unconditionally for every quest it knows. Modelling this as
		-- optional is what let an ordering bug through review: a `if not spawn
		-- and quest.Finisher` test placed too early is true for every quest
		-- alive, and it silently swallowed the database fallback underneath it.
		Finisher = opts.finisher or { NPC = { 3441 } },
		_complete = opts.complete and 1 or 0,
	}
	function q:IsComplete() return self._complete end
	return q
end

local questieQuests = {}

local function InstallQuestie()
	local modules = {}
	_G.QuestieLoader = {
		-- The real one hands back a stub rather than failing. That is the whole
		-- reason Nav type-checks every function it uses.
		ImportModule = function(_, name)
			modules[name] = modules[name] or { private = {} }
			return modules[name]
		end,
	}

	local db = _G.QuestieLoader:ImportModule("QuestieDB")
	local dist = _G.QuestieLoader:ImportModule("DistanceUtils")
	local zone = _G.QuestieLoader:ImportModule("ZoneDB")

	-- GetQuest is a DOT call; GetNPC / GetObject / GetItem are COLON calls. A
	-- mock that ignored the difference would hide the one class of mistake this
	-- integration is most likely to make.
	db.GetQuest = function(questId)
		questieCalls.getQuest = questieCalls.getQuest + 1
		return questieQuests[questId]
	end
	db.GetNPC = function(_, npcId) return questieNPCs[npcId] end
	db.GetObject = function(_, objectId) return questieObjects[objectId] end
	db.GetItem = function(_, itemId) return questieItems[itemId] end

	dist.GetNearestSpawn = function(spawns)
		if type(spawns) ~= "table" then
			-- The real one walks it with pairs() and no guard at all.
			questieCalls.badSpawns = questieCalls.badSpawns + 1
			error("GetNearestSpawn: spawns is not a table")
		end
		for areaId, coords in pairs(spawns) do
			if coords[1] then
				-- The real one ranks candidates; a mock that returned one
				-- constant would make "nearest" untestable.
				local d = 100
				for _, npc in pairs(questieNPCs) do if npc.spawns == spawns then d = npc.dist end end
				for _, obj in pairs(questieObjects) do if obj.spawns == spawns then d = obj.dist end end
				return coords[1], areaId, d
			end
		end
		return nil, nil, 999999999
	end
	dist.GetNearestObjective = function(spawnList)
		for _, entry in pairs(spawnList or {}) do
			local spawn, areaId = dist.GetNearestSpawn(entry.Spawns)
			if spawn then return spawn, areaId, entry.Name, 100 end
		end
		return nil, nil, nil, 999999999
	end
	dist.GetNearestFinisherOrStarter = function(finisher)
		for _, npcId in pairs((finisher or {}).NPC or {}) do
			local npc = questieNPCs[npcId]
			if npc then
				local spawn, areaId = dist.GetNearestSpawn(npc.spawns)
				if spawn then return spawn, areaId, npc.name, 100 end
			end
		end
		return nil, nil, nil, 999999999
	end
	dist.GetNearestSpawnForQuest = function(quest)
		if quest:IsComplete() == 1 then
			return dist.GetNearestFinisherOrStarter(quest.Finisher)
		end
		for _, objective in pairs(quest.Objectives) do
			local spawn, areaId, name = dist.GetNearestObjective(objective.spawnList)
			if spawn then return spawn, areaId, name, 100 end
		end
		return nil, nil, nil, 999999999
	end

	local areaToMap = { [17] = 1411 }  -- Barrens -> its uiMapID
	zone.GetUiMapIdByAreaId = function(_, areaId)
		if areaId == nil then questieCalls.nilArea = questieCalls.nilArea + 1 end
		return areaToMap[areaId]
	end

	_G.Questie = { API = { isReady = true } }
	return db, dist, zone
end

local tomtom
local function InstallTomTom()
	tomtom = { added = {}, removed = {}, arrows = {}, profile = { arrow = { arrival = 15 } } }

	local live = {}   -- TomTom.waypoints: [uiMapId][key] = uid
	local function key(m, x, y, title)
		return string.format("%d:%s:%s:%s", m, tostring(x), tostring(y), tostring(title))
	end

	_G.TomTom = {
		profile = tomtom.profile,
		waypoints = live,
		GetKey = function(_, uid) return key(uid[1], uid[2], uid[3], uid.title) end,

		--- The real one DEDUPLICATES on map/x/y/title and returns the existing
		--  uid early - before it sets the waypoint and before it points the
		--  arrow. Modelling that matters: the duplicate it refuses to make can
		--  be somebody ELSE's waypoint, which it then hands to us.
		AddWaypoint = function(_, m, x, y, opts)
			local k = key(m, x, y, opts.title)
			if live[m] and live[m][k] then return live[m][k] end

			local uid = { m, x, y, title = opts.title, from = opts.from, opts = opts }
			live[m] = live[m] or {}
			live[m][k] = uid
			tomtom.added[#tomtom.added + 1] = uid
			return uid
		end,

		RemoveWaypoint = function(_, uid)
			-- Errors on a non-table, like the real one.
			if type(uid) ~= "table" then error("RemoveWaypoint: uid is not a table") end
			tomtom.removed[#tomtom.removed + 1] = uid
			local m = uid[1]
			-- Deletes by KEY, not by identity - which is exactly how a stale uid
			-- deletes a live waypoint that merely looks like it.
			if live[m] then live[m][key(m, uid[2], uid[3], uid.title)] = nil end
		end,

		SetCrazyArrow = function(_, uid, _, title)
			tomtom.arrows[#tomtom.arrows + 1] = { uid = uid, title = title }
		end,
	}
	return tomtom
end

local function UninstallQuestieAndTomTom()
	A.Nav:Clear()
	_G.QuestieLoader, _G.Questie, _G.TomTom, tomtom = nil, nil, nil, nil
end

print("== nav: nothing installed ==")
do
	check(not A.Nav:Available(),
		"with neither addon there is nothing to offer")
	check(A.Nav:Locate(861) == nil, "and no location to be had")
	local ok, why = A.Nav:Route(861, "Prowlers of the Barrens")
	check(ok == false and type(why) == "string",
		"routing fails with a reason rather than raising")

	local r = QT.panel.rows[1]
	r:GetScript("OnMouseUp")(r, "RightButton")
	local texts = {}
	for _, item in ipairs(A.Widgets.MenuFrame().items) do
		if item:IsShown() then texts[#texts + 1] = item.text:GetText() end
	end
	check(#texts == 4 and texts[4] == "Abandon quest",
		"and the menu carries no Navigate item at all - a line that exists to"
		.. " advertise an addon you do not have is not a feature (" .. #texts .. ")")
	A.Widgets.MenuFrame():Hide()
end

print("== nav: questie to tomtom ==")
do
	InstallQuestie()
	local tt = InstallTomTom()

	-- A live quest with one objective: prowlers, in the Barrens, at 45/62.
	questieQuests[861] = questieQuest(861, {
		objectives = { { spawnList = { {
			Name = "Savannah Prowler",
			Spawns = { [17] = { { 45.0, 62.0 } } },
		} } } },
		finisher = { NPC = { 3441 } },
	})

	check(A.Nav:Available(), "with both addons present the feature exists")

	local loc = A.Nav:Locate(861)
	check(loc and loc.map == 1411,
		"the AREA id is converted to a uiMapID, which is the only thing TomTom"
		.. " understands (" .. tostring(loc and loc.map) .. ")")
	check(loc and math.abs(loc.x - 0.45) < 0.0001 and math.abs(loc.y - 0.62) < 0.0001,
		"and 0-100 spawn coordinates become the 0-1 fractions it wants ("
		.. tostring(loc and loc.x) .. ", " .. tostring(loc and loc.y) .. ")")
	check(loc and loc.name == "Savannah Prowler",
		"carrying the name of the thing you are being sent to")

	local ok = A.Nav:Route(861, "Prowlers of the Barrens")
	check(ok, "routing succeeds")
	check(#tt.added == 1, "one waypoint was set")
	local w = tt.added[1]
	check(w[1] == 1411 and math.abs(w[2] - 0.45) < 0.0001 and math.abs(w[3] - 0.62) < 0.0001,
		"at the right place on the right map")
	check(w.opts.from == "AetherUI", "stamped as ours, so its tooltip says where it came from")
	check(w.opts.crazy == true, "with the arrow armed - it is the whole point of asking")
	-- The trap that costs a phantom minimap pin per reload.
	check(w.opts.persistent == false,
		"and explicitly NOT persistent: TomTom's default is true, and a uid that"
		.. " comes back from saved variables is a different table, so removing it"
		.. " deletes the record and orphans the pin forever")

	-- The dedup trap: same map/x/y/title returns the old uid and does NOT
	-- re-point the arrow, so ours has to go first every time.
	A.Nav:Route(861, "Prowlers of the Barrens")
	check(#tt.removed == 1 and tt.removed[1] == w,
		"routing again removes our previous waypoint before adding one, or"
		.. " TomTom deduplicates the call away and the arrow never moves")
	check(#tt.added == 2, "and a fresh waypoint is what actually arms the arrow")
end

print("== nav: what it does with awkward quests ==")
do
	local tt = tomtom

	-- Complete: the target is the turn-in, not the boars. Questie decides this
	-- inside GetNearestSpawnForQuest, so the check is that we let it.
	questieQuests[862] = questieQuest(862, {
		complete = true,
		objectives = { { spawnList = { {
			Name = "Savannah Prowler", Spawns = { [17] = { { 45.0, 62.0 } } },
		} } } },
		finisher = { NPC = { 3441 } },
	})
	local loc = A.Nav:Locate(862)
	check(loc and loc.name == "Mankrik" and math.abs(loc.y - 0.31) < 0.0001,
		"a complete quest routes to its turn-in NPC, not back to its objectives ("
		.. tostring(loc and loc.name) .. ")")

	-- Objectives never populated. Questie only fills them from the quest log,
	-- and skips that for quests IT does not consider tracked - which, since we
	-- replace its tracker, can be all of them.
	questieQuests[863] = questieQuest(863, {
		objectiveData = { { Type = "monster", Id = 3271, Text = "Prowlers slain" } },
	})
	loc = A.Nav:Locate(863)
	check(loc and loc.map == 1411 and math.abs(loc.x - 0.45) < 0.0001,
		"a quest with no populated objectives still routes, out of the database"
		.. " rather than out of the quest log")

	-- An area ZoneDB has no uiMapID for. TomTom would take the nil, create the
	-- waypoint, arm the arrow and render nothing at all.
	questieQuests[864] = questieQuest(864, {
		objectiveData = { { Type = "monster", Id = 9999, Text = "Odd things" } },
	})
	local before = #tt.added
	check(A.Nav:Locate(864) == nil, "an area with no uiMapID is refused")
	local ok, why = A.Nav:Route(864, "Odd Quest")
	check(ok == false and #tt.added == before,
		"and TomTom is never called: it would have accepted the nil map, armed"
		.. " the arrow, and drawn nothing - the one failure that looks like it worked")
	check(why and #why > 0, "with a reason, which is what the chat line says")

	-- Questie's in-a-dungeon sentinel, if it ever reaches us unresolved.
	questieQuests[865] = questieQuest(865, {
		objectiveData = { { Type = "monster", Id = 8888, Text = "Inside" } },
	})
	check(A.Nav:Locate(865) == nil,
		"and {-1,-1} is refused rather than sent as a coordinate off the map")

	-- A quest Questie has never heard of.
	check(A.Nav:Locate(99999) == nil, "an unknown quest is nil, not an error")

	-- Nothing anywhere except a turn-in NPC: the last resort, and the only case
	-- where routing to the finisher of an unfinished quest is right.
	questieQuests[866] = questieQuest(866, { finisher = { NPC = { 3441 } } })
	loc = A.Nav:Locate(866)
	check(loc and loc.name == "Mankrik",
		"a quest with no objectives Questie can place at all falls back to its"
		.. " turn-in, rather than offering nothing")

	-- ...but only AFTER the database. Objectives outrank the turn-in, and the
	-- ordering is the whole correctness of Locate: GetQuest fills Finisher for
	-- every quest alive, so a finisher test placed first is always true and
	-- would send you to the hand-in of a quest you have not started killing.
	questieQuests[867] = questieQuest(867, {
		objectiveData = { { Type = "monster", Id = 3271, Text = "Prowlers slain" } },
		finisher = { NPC = { 3441 } },
	})
	loc = A.Nav:Locate(867)
	check(loc and loc.name == "Savannah Prowler",
		"a quest with both goes to the mobs, not to the hand-in ("
		.. tostring(loc and loc.name) .. ")")

	-- Nearest, out of several. Questie's "distance" is an ordering number, so
	-- this is checking we order by it rather than take whatever pairs() gives
	-- us first.
	questieQuests[868] = questieQuest(868, {
		objectiveData = {
			{ Type = "monster", Id = 3272, Text = "Distant" },
			{ Type = "monster", Id = 3273, Text = "Near" },
			{ Type = "monster", Id = 3271, Text = "Middling" },
		},
	})
	loc = A.Nav:Locate(868)
	check(loc and loc.name == "Near Prowler",
		"with several candidates it takes the nearest, not the first ("
		.. tostring(loc and loc.name) .. ")")

	-- An objective that is a game object rather than a creature.
	questieQuests[869] = questieQuest(869, {
		objectiveData = { { Type = "object", Id = 1617, Text = "Silverleaf" } },
	})
	loc = A.Nav:Locate(869)
	check(loc and loc.name == "Silverleaf" and math.abs(loc.x - 0.22) < 0.0001,
		"objects are placed as well as creatures - half of Classic's objectives"
		.. " are a herb or a crate")

	-- "Collect 8 hides" - the most common quest shape in the game. An item has
	-- no location; what has a location is whatever drops it.
	questieQuests[870] = questieQuest(870, {
		objectiveData = { { Type = "item", Id = 4632, Text = "Hides" } },
	})
	loc = A.Nav:Locate(870)
	check(loc and loc.name == "Near Prowler",
		"a collect quest routes to the nearest thing that DROPS the item ("
		.. tostring(loc and loc.name) .. ")")

	-- Coordinates off the map, from the other side of the range check.
	questieQuests[871] = questieQuest(871, {
		objectiveData = { { Type = "monster", Id = 7777, Text = "Off the map" } },
		finisher = { NPC = { 4321 } },
	})
	check(A.Nav:Locate(871) == nil,
		"a coordinate past 100 is refused too - TomTom does not range check, it"
		.. " extrapolates off the zone and points confidently at nowhere")

	-- A spawn table that is not a table. The real GetNearestSpawn walks it with
	-- pairs() and no guard, so this raises inside Questie unless we check first.
	questieQuests[872] = questieQuest(872, {
		objectiveData = { { Type = "monster", Id = 6666, Text = "Malformed" } },
		finisher = { NPC = { 4321 } },
	})
	local bad = questieCalls.badSpawns
	local ok = pcall(function() return A.Nav:Locate(872) end)
	check(ok and A.Nav:Locate(872) == nil,
		"malformed spawn data is refused rather than raised - pairs() on a"
		.. " string is an error inside Questie that would read as ours")
	check(questieCalls.badSpawns == bad,
		"and Questie is never handed it in the first place: a pcall would hide"
		.. " the throw from us, but the [ERROR] line it prints is in the"
		.. " player's chat either way, with Questie's name on our bug")

	-- A spawn with no zone. Nothing in the real data does this, but the guard
	-- is one `and` away from being dropped as redundant.
	local dist = QuestieLoader:ImportModule("DistanceUtils")
	local was = dist.GetNearestSpawnForQuest
	dist.GetNearestSpawnForQuest = function() return { 45.0, 62.0 }, nil, "Nowhere", 100 end
	local nilAreas = questieCalls.nilArea
	check(A.Nav:Locate(861) == nil, "a spawn with no area id is refused")
	check(questieCalls.nilArea == nilAreas,
		"without asking ZoneDB to convert a nil, which is how you get a nil"
		.. " uiMapID and a waypoint that renders nowhere")
	dist.GetNearestSpawnForQuest = was
end

print("== nav: the menu item ==")
do
	local r = QT.panel.rows[1]
	questieQuests[r.questID] = questieQuest(r.questID, {
		objectives = { { spawnList = { {
			Name = "Savannah Prowler", Spawns = { [17] = { { 45.0, 62.0 } } },
		} } } },
	})

	r:GetScript("OnMouseUp")(r, "RightButton")
	local texts, navItem = {}, nil
	for _, item in ipairs(A.Widgets.MenuFrame().items) do
		if item:IsShown() then
			texts[#texts + 1] = item.text:GetText()
			if item.text:GetText() == "Navigate with TomTom" then navItem = item end
		end
	end
	check(#texts == 5 and navItem, "the item appears once both addons are there")
	check(texts[5] == "Abandon quest",
		"and it goes ABOVE Abandon - the destructive one stays last, where the"
		.. " muscle memory for it already is")

	local tt = tomtom
	local before = #tt.added
	navItem:GetScript("OnClick")(navItem)
	check(#tt.added == before + 1, "clicking it sets the waypoint")
	check(not A.Widgets.MenuFrame():IsShown(), "and the menu closes behind it")

	-- Now a quest with no location at all: no objectives Questie populated, no
	-- database objectives, and a turn-in NPC it has no spawn for either. All
	-- three routes have to come back empty before the item goes grey.
	questieQuests[r.questID] = questieQuest(r.questID, { finisher = { NPC = { 4321 } } })
	r:GetScript("OnMouseUp")(r, "RightButton")
	local dead
	for _, item in ipairs(A.Widgets.MenuFrame().items) do
		if item:IsShown() and item.text:GetText() == "No location known" then dead = item end
	end
	check(dead, "a quest Questie cannot place says so in the menu")
	check(dead.action == nil, "and carries no action, so clicking it cannot half-work")
	check(dead.text.__color[1] == A.Palette.c.textFaint[1],
		"drawn faint, or it still reads as something you can click")
	local stillAdded = #tomtom.added
	dead:GetScript("OnClick")(dead)
	check(#tomtom.added == stillAdded, "clicking it does nothing at all")
	A.Widgets.MenuFrame():Hide()
end

print("== nav: when questie moves under us ==")
do
	-- The realistic failure. `ImportModule` cannot report a bad name: it hands
	-- back an empty stub that the real module would have filled. So a renamed
	-- function is not an error, it is a table of nils that raises later, inside
	-- a right-click, looking like OUR bug.
	-- EVERY function we depend on, one at a time. Checking only the obvious one
	-- would leave the other four resting on a type-check nothing exercises,
	-- which is the same as not having it.
	local depends = {
		{ "QuestieDB",     "GetQuest" },
		{ "DistanceUtils", "GetNearestSpawnForQuest" },
		{ "DistanceUtils", "GetNearestSpawn" },
		{ "DistanceUtils", "GetNearestFinisherOrStarter" },
		{ "ZoneDB",        "GetUiMapIdByAreaId" },
	}
	local gone = {}
	for _, dep in ipairs(depends) do
		local module = QuestieLoader:ImportModule(dep[1])
		local was = module[dep[2]]
		module[dep[2]] = nil
		if A.Nav:Available() then gone[#gone + 1] = dep[1] .. "." .. dep[2] end
		module[dep[2]] = was
	end
	check(#gone == 0,
		"ANY of the five functions renamed out from under us takes the feature"
		.. " away quietly - ImportModule cannot report a bad name, it hands back"
		.. " an empty table, so each one has to be checked (" .. table.concat(gone, ", ") .. ")")

	local dist = QuestieLoader:ImportModule("DistanceUtils")
	local was = dist.GetNearestSpawnForQuest
	dist.GetNearestSpawnForQuest = nil

	local r = QT.panel.rows[1]
	r:GetScript("OnMouseUp")(r, "RightButton")
	local n = 0
	for _, item in ipairs(A.Widgets.MenuFrame().items) do if item:IsShown() then n = n + 1 end end
	check(n == 4, "the menu goes back to four items rather than raising on click")
	A.Widgets.MenuFrame():Hide()
	dist.GetNearestSpawnForQuest = was

	-- Questie loaded but its database not built yet. Calling in here would raise
	-- inside Questie itself - GetQuest's query function is not assigned until
	-- its own init has run.
	_G.Questie.API.isReady = false
	check(not A.Nav:Available(), "and nothing is offered until Questie says it is ready")
	check(A.Nav:Locate(861) == nil, "or asked for, which would raise inside Questie")
	_G.Questie.API.isReady = true
	check(A.Nav:Available(), "and it comes back when it is")

	-- TomTom gone, Questie fine.
	local hadTomTom = _G.TomTom
	_G.TomTom = nil
	check(not A.Nav:Available(), "no TomTom, no item")
	local ok, why = A.Nav:Route(861, "Prowlers")
	check(ok == false and why and why:find("TomTom"),
		"and routing says which addon is missing")
	_G.TomTom = hadTomTom
end

print("== nav: the waypoint is ours and stays ours ==")
do
	A.Nav:Route(861, "Prowlers of the Barrens")
	check(type(A.Nav:Waypoint()) == "table", "we hold the uid ourselves")

	-- Questie keeps its handle in `Questie.db.char._tom_waypoint`, a SAVED
	-- variable, and clears it from three separate places. Ours is a file-local
	-- upvalue: not in our saved variables either, because a uid restored from
	-- disk is a different table and removing it orphans the pin.
	local held = A.Nav:Waypoint()
	local function findsUid(t, depth, seen)
		if depth > 4 or type(t) ~= "table" then return false end
		seen = seen or {}
		if seen[t] then return false end
		seen[t] = true
		for _, v in pairs(t) do
			if v == held then return true end
			if findsUid(v, depth + 1, seen) then return true end
		end
		return false
	end
	check(not findsUid(A.db, 0), "and it is nowhere in our saved variables")

	A.Nav:Clear()
	check(A.Nav:Waypoint() == nil and tomtom.removed[#tomtom.removed] == held,
		"clearing removes exactly the one we made")
	local removals = #tomtom.removed
	A.Nav:Clear()
	check(#tomtom.removed == removals,
		"and clearing again asks TomTom nothing - a second RemoveWaypoint would"
		.. " be deleting by key something we no longer own")
end

print("== nav: not stepping on Questie's waypoints ==")
do
	-- The dedup trap from the other side. Questie builds its waypoints from the
	-- same call we do - same map, same coordinates, and the same spawn NAME as
	-- the title - so all four parts of TomTom's key match and AddWaypoint hands
	-- us back QUESTIE'S uid, early, with its arrow untouched.
	questieQuests[880] = questieQuest(880, {
		objectiveData = { { Type = "monster", Id = 3271, Text = "Prowlers" } },
	})
	local theirs = TomTom:AddWaypoint(1411, 0.45, 0.62,
		{ title = "Savannah Prowler", from = "Questie" })
	local arrows = #tomtom.arrows
	local added = #tomtom.added

	local ok = A.Nav:Route(880, "Prowlers of the Barrens")
	check(ok, "routing still reports success")
	check(#tomtom.added == added,
		"TomTom made no new waypoint - it deduplicated ours away against theirs")
	check(A.Nav:Waypoint() == nil,
		"and we do NOT adopt it: their uid in our hands means our next route"
		.. " deletes their waypoint, which is the whole thing this avoids")
	check(#tomtom.arrows == arrows + 1 and tomtom.arrows[#tomtom.arrows].uid == theirs,
		"we point the arrow at it instead, which is all that was missing")

	A.Nav:Clear()
	check(tomtom.removed[#tomtom.removed] ~= theirs, "and clearing leaves theirs alone")
	-- Out of the way, or every waypoint below dedups against it as well.
	TomTom:RemoveWaypoint(theirs)

	-- Now the stale-handle case. TomTom removes a waypoint by itself once you
	-- walk within `cleardistance` of it, and nothing tells us. Our handle is
	-- then a dead table - and RemoveWaypoint deletes by KEY while clearing
	-- frames by identity, so calling it would delete a live waypoint that
	-- merely looks the same and orphan its pins until a reload.
	questieQuests[873] = questieQuest(873, {
		objectiveData = { { Type = "monster", Id = 3271, Text = "Prowlers" } },
	})
	A.Nav:Route(873, "Prowlers")
	local ours = A.Nav:Waypoint()
	TomTom:RemoveWaypoint(ours)                       -- as if we had arrived
	local impostor = TomTom:AddWaypoint(ours[1], ours[2], ours[3],
		{ title = ours.title, from = "Questie" })     -- same key, different table
	local before = #tomtom.removed

	A.Nav:Clear()
	check(#tomtom.removed == before,
		"a handle TomTom has already retired is dropped, not removed again")
	local live = TomTom.waypoints[impostor[1]][TomTom:GetKey(impostor)]
	check(live == impostor,
		"so the waypoint that now owns that key survives, rather than losing its"
		.. " record while its pins stay on the minimap forever")
	TomTom:RemoveWaypoint(impostor)
end

print("== nav: a waypoint does not outlive its quest ==")
do
	local r = QT.panel.rows[1]
	questieQuests[r.questID] = questieQuest(r.questID, {
		objectiveData = { { Type = "monster", Id = 3271, Text = "Prowlers" } },
	})
	A.Nav:Route(r.questID, r.questTitle)
	check(A.Nav:Routed() == r.questID, "the waypoint knows which quest it is for")

	-- One click, one trip through Questie: the menu already resolved the
	-- location to decide whether to grey the item, and asking again is both
	-- wasted work and racy, since the answer is ranked by where you are standing.
	local calls = questieCalls.getQuest
	A.Nav:Route(r.questID, r.questTitle, { map = 1411, x = 0.5, y = 0.5 })
	check(questieCalls.getQuest == calls,
		"routing with a location already in hand does not ask Questie again")

	-- Untracking is the one gesture that covers turn-in, abandon and dismissal:
	-- all three take the quest out of the tracker's list.
	local QTmod = A:GetModule("questtracker")
	QTmod.SetTracked(r.questID, false)
	QTmod:Refresh()
	check(A.Nav:Waypoint() == nil and A.Nav:Routed() == nil,
		"a quest leaving the tracker retires its waypoint, rather than leaving an"
		.. " arrow pointing at the boars of a quest you handed in")
	QTmod.SetTracked(r.questID, true)
	QTmod:Refresh()

	UninstallQuestieAndTomTom()
	check(not A.Nav:Available(), "teardown leaves the rest of the run as it was")
end

print("== quest tracker: combat fold ==")
do
	-- Start from what a fresh load actually looks like. `collapsed` is nil until
	-- something sets it, and every check below used to begin by setting it -
	-- which is why the bug survived: the state that breaks the restore was the
	-- one state the test never used. First fight of a session folds it and it
	-- never comes back.
	QT.collapsed = nil
	QT._preCombat = nil
	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(not QT.collapsed,
		"the first fight after a load gives the tracker back afterwards - nil is"
		.. " a state, not the absence of one")

	QT:SetCollapsed(false)
	local open = QT.panel:GetHeight()
	check(QT.panel.body:IsShown(), "body visible out of combat")

	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	check(QT.collapsed and not QT.panel.body:IsShown(), "folds to the heading in combat")
	local folded = QT.panel:GetHeight()
	check(folded < open, "and the panel is shorter for it ("
		.. math.floor(folded) .. " < " .. math.floor(open) .. ")")

	-- unfolding by hand mid-fight has to survive the end of the fight
	QT:ToggleCollapsed()
	check(not QT.collapsed, "you can unfold it by hand during the fight")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(not QT.collapsed, "and leaving combat does not fold it back on you")

	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(not QT.collapsed, "an untouched fight restores whatever state it found")
end

do  -- turning a quest in should drop it from the tracked set
	local saved = _G.__questLog[2]
	table.remove(_G.__questLog, 2)
	QT:Refresh()
	check(A.db.char.tracked[861] == nil,
		"a quest that has left the log stops being tracked - the set cannot grow forever")
	table.insert(_G.__questLog, 2, saved)
	QT:Refresh()
end

A.db.profile.modules.questtracker.autoTrack = true
QT:Refresh()
check(#QT.quests == 4, "back in auto mode the whole log is tracked again")

print("== quest tracker: difficulty ==")
do
	-- player is level 15 in the mock; the log spans 15 to 18
	local byId = {}
	for _, q in ipairs(QT.quests) do byId[q.questID] = q end

	check(byId[861] and byId[861].band == "difficult",
		"a quest at the player's own level is the neutral band (got "
		.. tostring(byId[861] and byId[861].band) .. ")")
	check(byId[5041] and byId[5041].band == "verydifficult",
		"and one three levels up moves a band redder (got "
		.. tostring(byId[5041] and byId[5041].band) .. ")")

	-- The band is the quest log's, not a second copy of the thresholds living
	-- here. Same call, same answer, or the two lists disagree on screen.
	check(byId[5041].band == A:GetModule("questlog").DifficultyBand(18),
		"and it is the quest log's own banding, not a private reimplementation")

	-- and it must move with the player, not be baked in at build time
	local before = QT.quests[1].band
	_G.__units.player.level = 40
	QT:Refresh()
	local after = QT.quests[1].band
	check(after ~= before and after == "trivial",
		"levelling up rebands the list - the same quest is trivial now (got "
		.. tostring(after) .. ")")
	_G.__units.player.level = 15
	QT:Refresh()

	-- The row wears a level CHIP, like a quest log row, rather than a "[15]"
	-- prefix - and the difficulty is on the chip, never on the title.
	local row = QT.panel.rows[1]
	check(row.chip:IsShown() and row.chip.text:GetText() == "15",
		"the level is shown in a chip in front of the title (got "
		.. tostring(row.chip.text:GetText()) .. ")")
	local band = A.Palette.c.questDiff[QT.quests[1].band]
	check(row.chip._fillColor == band.bg, "tinted with its difficulty band's fill")
	-- The chip is a label on the title, so it must not be drawn louder than the
	-- title. The qlChip role's own 12 was picked against the log's 14pt rows.
	local _, chipPt = row.chip.text:GetFont()
	local _, titlePt = row.title:GetFont()
	check(chipPt and titlePt and chipPt < titlePt,
		"the chip's digits are smaller than the title beside them ("
		.. tostring(chipPt) .. " vs " .. tostring(titlePt) .. ")")
	-- All three components. On the neutral band the ink and the fill both start
	-- at 255, so comparing only the red channel passes with the digits painted
	-- in the background colour.
	local ink = row.chip.text.__color
	check(ink and ink[1] == band.text[1] and ink[2] == band.text[2]
		and ink[3] == band.text[3], "and the digits take the band's ink")
	check(row.title.__color and row.title.__color[1] == A.Palette.c.text[1]
		and row.title.__color[2] == A.Palette.c.text[2]
		and row.title.__color[3] == A.Palette.c.text[3],
		"while the title itself stays plain body text, whatever the difficulty")

	-- The chip has to fit the title's own line. It is anchored at the top of the
	-- row and RowHeight() budgets TITLE_H for that line, so a chip taller than
	-- the title draws straight through the first objective and the bar.
	check(row.chip:GetHeight() <= row.title:GetHeight(),
		"the chip fits inside the title line rather than overrunning the objectives ("
		.. row.chip:GetHeight() .. " vs " .. row.title:GetHeight() .. ")")
	-- PINNED, not just non-zero: the chip is a fixed width so that a two-digit
	-- level and a one-digit level start their titles on the same edge. Sized to
	-- its text instead, the column steps in and out as you read down it.
	check(row.chip:GetWidth() == 28,
		"and a pinned width, so the titles line up down the column (got "
		.. row.chip:GetWidth() .. ")")

	local titleLeft, gap, titleRight
	for i = 1, 4 do
		local p, rel, _, x = row.title:GetPoint(i)
		if p == "TOPLEFT" then titleLeft, gap = rel, x end
		if p == "TOPRIGHT" then titleRight = rel end
	end
	check(titleLeft == row.chip and (gap or 0) > 0,
		"and the title hangs off the chip's right edge, not off the row")
	-- TOPRIGHT rather than RIGHT, and it matters. RIGHT plus TOPLEFT pins the
	-- top edge and the vertical centre at once, so on a row with three objective
	-- lines under it the title's box stretches to the whole row and the text,
	-- being MIDDLE-justified, drifts down among its own objectives.
	check(titleRight == row, "with its right edge pinned by the TOP corner, not the middle")

	-- The band -> palette step, checked on a quest whose band is NOT the neutral
	-- fallback. Every assertion above rides on quests[1], a level-15 quest for a
	-- level-15 player, which lands on exactly the band the `or` degrades to - so
	-- a tracker that painted every chip one colour would satisfy all of them.
	local hard, hardRow
	for i, q in ipairs(QT.quests) do
		if q.questID == 5041 then hard, hardRow = q, QT.panel.rows[i] end
	end
	local hardBand = A.Palette.c.questDiff[hard and hard.band]
	check(hard and hard.band == "verydifficult" and hardRow.chip.text:GetText() == "18",
		"the level-18 quest has its own row and its own band")
	check(hardRow.chip._fillColor == hardBand.bg
		and hardRow.chip._fillColor ~= band.bg,
		"and a chip in a different colour from the level-15 one beside it")
	local hardInk = hardRow.chip.text.__color
	check(hardInk[1] == hardBand.text[1] and hardInk[2] == hardBand.text[2]
		and hardInk[3] == hardBand.text[3], "with the matching ink")

	-- Turning the level off must move the title back to the row's edge. An
	-- anchor to a hidden region still resolves, so a stale one would indent
	-- every title by the width of a chip that is not on screen.
	local cfgQT = A.db.profile.modules.questtracker
	cfgQT.showLevel = false
	QT:Refresh()
	local row1 = QT.panel.rows[1]
	check(not row1.chip:IsShown(), "with the level off the chip goes away")
	local anchored
	for i = 1, 4 do
		local p, rel = row1.title:GetPoint(i)
		if p == "TOPLEFT" then anchored = rel end
	end
	check(anchored == row1, "and the title re-anchors to the row, not to the hidden chip")
	cfgQT.showLevel = true
	QT:Refresh()

	-- a complete quest says so in words, not only in colour
	local complete
	for i, q in ipairs(QT.quests) do
		if q.complete then complete = q end
	end
	check(complete and complete.lines[#complete.lines].text == "Complete",
		"a complete quest gets a Complete line, so an objective-less one is not silent")
end

print("== widgets: pill defaults ==")
do
	-- A scratch parent, so these never join the tracker's own children.
	local scratch = CreateFrame("Frame", nil, UIParent)

	-- Five callers lean on these two defaults and none of them pass the value,
	-- so a change here is silent everywhere it matters.
	local p = A.Widgets.Pill(scratch, "qlChip")
	check(p:GetHeight() == 19, "a pill with no height asked for is 19 (got " .. p:GetHeight() .. ")")
	check(p._edge and not p._edge[1]:IsShown(),
		"and it wears no rim unless the caller asks - the concept's level chip has none")

	local e = A.Widgets.Pill(scratch, "qlTag", { edge = true })
	check(e._edge[1]:IsShown(), "while edge = true keeps it")

	-- The size override has to survive a restyle: it exists precisely because
	-- the role's own number is wrong where the string sits.
	local s = A.Widgets.Pill(scratch, "qlChip", { size = 9 })
	local _, before = s.text:GetFont()
	A.Widgets.Restyle(s.text)
	local _, after = s.text:GetFont()
	check(before == 9 and after == 9,
		"a pill's size override outlives W.Restyle (" .. tostring(before)
		.. " -> " .. tostring(after) .. ")")

	-- Dark ink FIRST. W.Text builds every string with the 0.55 shadow already on,
	-- so asserting the light case against a fresh pill proves nothing - it is
	-- green with the restoring branch deleted entirely.
	s:SetColors(nil, { 0.10, 0.08, 0.03 })
	check((s.text.__shadow or {})[4] == 0, "dark ink on a pill drops its shadow")
	s:SetColors(nil, { 1, 1, 1 })
	check((s.text.__shadow or {})[4] == 0.55, "and light ink gets it back again")

	-- The threshold has to sit below the DIMMEST ink either palette hands a
	-- pill, not merely below white: midnight's trivial band is the darkest light
	-- type on screen, and it is the first thing a raised threshold would strip.
	s:SetColors(nil, A.Palette.skins.midnight.questDiff.trivial.text)
	check((s.text.__shadow or {})[4] == 0.55,
		"midnight's dimmest band is still light type, and keeps its shadow")
	-- And it is the same threshold on every skin, because the band inks are
	-- SEMANTIC - a skin cannot reach them. Daylight could, and its palest band
	-- came back dark ink, which is the one case this branch exists for; the
	-- family that replaced it has no light chrome at all, so the claim to hold
	-- is the opposite one, on all four.
	local dark = {}
	for _, name in ipairs(SKINS) do
		s:SetColors(nil, A.Palette.skins[name].questDiff.trivial.text)
		if (s.text.__shadow or {})[4] ~= 0.55 then dark[#dark + 1] = name end
	end
	check(#dark == 0,
		"and so is every other skin's - brightness lives in the hue, so no skin"
		.. " ever hands a band dark ink (" .. table.concat(dark, ", ") .. ")")
end

section("fonts: the game's own lettering, in one pass", function()
	local FTm = A:GetModule("fonts")
	check(FTm and FTm.enabled, "fonts module enabled"
		.. (FTm and FTm.lastError and ("  -- " .. FTm.lastError) or ""))

	-- THE ONE GLOBAL LEVER THIS API HAS. Every string that INHERITS a font
	-- object follows it, for as long as it lives - including strings made long
	-- afterwards, and including ones a pool hands back out and resets. There is
	-- no equivalent for art, which is why borders are per-frame work and this is
	-- not.
	local WANT = {
		{ "GameFontHighlight", "Outfit-Regular", 12 },
		{ "GameFontNormal",    "Outfit-Regular", 12 },
		{ "ZoneTextFont",      "Outfit-SemiBold", 32 },
		{ "SubZoneTextFont",   "Outfit-SemiBold", 26 },
		{ "ErrorFont",         "Outfit-SemiBold", 16 },
		{ "GameFontNormalHuge","Outfit-SemiBold", 20 },
	}
	local wrong = {}
	for _, w in ipairs(WANT) do
		local path, size = _G[w[1]]:GetFont()
		if not tostring(path):find(w[2], 1, true) then
			wrong[#wrong + 1] = w[1] .. "=" .. tostring(path)
		elseif size ~= w[3] then
			wrong[#wrong + 1] = w[1] .. " size " .. tostring(size)
		end
	end
	check(#wrong == 0,
		"every font object we name is ours, at ITS OWN size - the weight is a"
		.. " choice, the size is the client's and nothing on screen reflows ("
		.. table.concat(wrong, ", ") .. ")")

	-- AND THE OUTLINE. Load-bearing on anything drawn over the world.
	check(select(3, _G.ZoneTextFont:GetFont()) == "THICKOUTLINE",
		"with the outline it had (" ..
		tostring(select(3, _G.ZoneTextFont:GetFont())) .. ")")

	-- THE STRINGS FOLLOW, which is the whole mechanism. Checked on one made
	-- BEFORE the sweep and one made after, because those are different claims:
	-- the first is inheritance working, the second is why a pooled string the
	-- client resets on every use is covered at all.
	check(tostring(select(1, _G.ZoneTextString:GetFont())):find("AetherUI", 1, true),
		"a string that already existed follows its object (" ..
		tostring(select(1, _G.ZoneTextString:GetFont())) .. ")")
	local fresh = UIParent:CreateFontString(nil, "ARTWORK")
	fresh:SetFontObject("GameFontNormal")
	check(tostring(select(1, fresh:GetFont())):find("AetherUI", 1, true),
		"and so does one created afterwards, which no per-string pass could have"
		.. " reached")

	-- A STRING THAT NAMES ITS OWN FACE IS LEFT ALONE. An addon that called
	-- SetFont said what it wanted; this is meant to carry the ones that did not.
	local theirs = UIParent:CreateFontString(nil, "ARTWORK")
	theirs:SetFont("Interface\\SomeAddon\\Their.ttf", 14, "")
	check(select(1, theirs:GetFont()) == "Interface\\SomeAddon\\Their.ttf",
		"an explicit face is untouched - that is the promise to other addons, and"
		.. " the reason this is safe to do at all")

	-- THE FRAME CASE. UIErrorsFrame is a MessageFrame: its font is on the FRAME
	-- and it builds a string per message from that, so remapping ErrorFont does
	-- not reach it. "You can't do that yet" was the one thing on screen that
	-- made the old lettering obvious, and it is why the frame list exists.
	local path, size = _G.UIErrorsFrame:GetFont()
	check(tostring(path):find("AetherUI", 1, true),
		"the error frame is ours too, from the frame list rather than from"
		.. " inheritance (" .. tostring(path) .. ")")
	check(size == 16, "at its own size (" .. tostring(size) .. ")")

	_G.UIErrorsFrame.__messages = {}
	_G.UIErrorsFrame:AddMessage("You can't do that yet.", 1, 0.1, 0.1)
	local msg = _G.UIErrorsFrame.__messages[1]
	check(msg and msg.font and tostring(msg.font[1]):find("AetherUI", 1, true),
		"and a message added afterwards carries it, which is the only thing that"
		.. " proves the font went on the frame rather than beside it")
end)

section("fonts: and gives the game back when you switch it off", function()
	local FTm = A:GetModule("fonts")

	A:SetModuleEnabled("fonts", false)
	local path, size, flags = _G.ZoneTextFont:GetFont()
	check(path == "Fonts\\FRIZQT__.TTF",
		"the client's own face is back (" .. tostring(path) .. ")")
	check(size == 32 and flags == "THICKOUTLINE",
		"at its own size and outline, not ours (" .. tostring(size) .. " " ..
		tostring(flags) .. ")")
	check(select(1, _G.UIErrorsFrame:GetFont()) == "Fonts\\FRIZQT__.TTF",
		"and the error frame with it")
	check(tostring(select(1, _G.ZoneTextString:GetFont())) == "Fonts\\FRIZQT__.TTF",
		"and every string that was following - one object put back, not one"
		.. " string at a time")

	-- ON, OFF, ON, OFF. The original is recorded ONCE. A recording made on the
	-- second pass would record OUR font as the client's, and off would then be a
	-- no-op that looked like it worked.
	A:SetModuleEnabled("fonts", true)
	FTm:Dress()
	A:SetModuleEnabled("fonts", false)
	check(select(1, _G.ZoneTextFont:GetFont()) == "Fonts\\FRIZQT__.TTF",
		"and still the client's after off, on, dress, off")

	A:SetModuleEnabled("fonts", true)
	check(tostring(select(1, _G.ZoneTextFont:GetFont())):find("AetherUI", 1, true),
		"and ours again on the way back")
end)

section("fonts: a face the client cannot load is put back, not left half on", function()
	-- SetFont on a face the client cannot load leaves the font UNCHANGED and
	-- says nothing about it. So a remap that assumed it worked would record the
	-- original, appear to succeed, and leave the object in Friz - and then
	-- switching the module off would "restore" a font that never moved.
	local FTm = A:GetModule("fonts")
	A:SetModuleEnabled("fonts", false)

	A:SetModuleEnabled("fonts", true)
	local dressedOk = FTm.dressed
	A:SetModuleEnabled("fonts", false)

	_G.__badFonts = { [A.Media.font.semibold] = true }
	A:SetModuleEnabled("fonts", true)
	check(select(1, _G.ZoneTextFont:GetFont()) == "Fonts\\FRIZQT__.TTF",
		"an object whose new face would not load keeps the one it had")

	-- COUNTED HONESTLY, and that is the only observable difference here.
	-- Comparing the tally against the run where every face loaded is what
	-- makes it a check at all: "missed is more than zero" is true anyway on
	-- a client that does not define every object in the list.
	check(FTm.dressed == dressedOk - 5,
		"and is counted as missed rather than dressed - five semibold entries"
		.. " short of the run where the face loaded (" .. tostring(FTm.dressed)
		.. " of " .. tostring(dressedOk) .. ")")

	-- And the ones that CAN load still did.
	check(tostring(select(1, _G.GameFontNormal:GetFont())):find("AetherUI", 1, true),
		"while the rest of the pass carries on - one missing face is not a"
		.. " reason to leave the interface in two fonts")

	_G.__badFonts = nil
	A:SetModuleEnabled("fonts", false)
	A:SetModuleEnabled("fonts", true)
	check(tostring(select(1, _G.ZoneTextFont:GetFont())):find("AetherUI", 1, true),
		"and it takes on a client that can load it")
end)

section("tooltips: a bar button says where its tooltip goes", function()
	local TTm = A:GetModule("tooltips")
	local AB3 = A:GetModule("actionbars")
	check(TTm and TTm.enabled, "tooltips module enabled")

	-- ONE BAR ANSWERED A DIFFERENT QUESTION FROM THE REST.
	--
	-- An ordinary action button sets its own owner, so its tooltip appears
	-- beside it. A pet or stance button carries the CLIENT'S OnEnter, which
	-- calls GameTooltip_SetDefaultAnchor - so with an anchor configured, the pet
	-- bar sent its tooltips across the screen while the bar above it did not.
	local pet
	for _, bar in ipairs(AB3.bars) do
		if bar.kind == "pet" then pet = bar end
	end
	check(pet and pet.buttons[1], "there is a pet bar to look at")

	local b = pet.buttons[1]
	check(b.__aetherTipBesideOwner == true,
		"a pet button asks for its tooltip beside it")

	-- Through the client's own call, which is the only path that matters: this
	-- is what PetActionButtonMixin_OnEnter does before it sets any content.
	GameTooltip_SetDefaultAnchor(GameTooltip, b)
	check(GameTooltip:GetOwner() == b,
		"and the tooltip belongs to the button after the client anchors it")
	check(GameTooltip.__anchor == "ANCHOR_RIGHT",
		"beside it, by the SAME call an ordinary action button makes - not by a"
		.. " SetPoint of ours that lands somewhere similar (" ..
		tostring(GameTooltip.__anchor) .. ")")

	-- A stance button too. It is the same template family and the same client
	-- handler, and checking one of the two proves nothing about the other.
	local stance
	for _, bar in ipairs(AB3.bars) do
		if bar.kind == "stance" then stance = bar end
	end
	if stance and stance.buttons[1] then
		check(stance.buttons[1].__aetherTipBesideOwner == true,
			"and so does a stance button")
	end

	-- AND EVERYTHING ELSE STILL HONOURS THE ANCHOR. The point is not that the
	-- setting is ignored, it is that action bars are a deliberate exception -
	-- so a tooltip from anything else must still go where it was told.
	local plain = CreateFrame("Frame", nil, UIParent)
	GameTooltip_SetDefaultAnchor(GameTooltip, plain)
	check(GameTooltip.__anchor == "ANCHOR_NONE",
		"a frame that did not ask keeps the anchorless owner the client gave it,"
		.. " and the configured position with it (" ..
		tostring(GameTooltip.__anchor) .. ")")
end)

section("menus: the client's own right-click menus, in our glass", function()
	local M = A:GetModule("menus")
	check(M and M.enabled, "menus module enabled"
		.. (M and M.lastError and ("  -- " .. M.lastError) or ""))
	check(not M.absent, "and it found a menu system it knows how to dress")

	-- BOTH STYLES, and this is the check that was missing.
	--
	-- MenuStyle1Mixin is what a dropdown BUTTON opens - a setting in a panel.
	-- MenuStyle2Mixin is what a RIGHT-CLICK opens, which is the one on your
	-- portrait and your pet's and the only one anybody notices. Hooking the
	-- first alone changed nothing visible, and the suite was green about it
	-- because the mock had only the mixin that had been hooked.
	check(MenuVariants.GetDefaultContextMenuMixin() == MenuStyle2Mixin,
		"a right-click menu is the STYLE 2 one on this game type - which is what"
		.. " makes hooking style 1 alone invisible")

	local menu = _G.__OpenMenu(1)                      -- the context one
	local dropdown = _G.__OpenMenu(7, MenuStyle1Mixin) -- the dropdown one
	check(menu.__blizzArt == nil and dropdown.__blizzArt == nil,
		"neither style draws the client's own panel any more - a dropdown in the"
		.. " options and a right-click on a unit frame are the same control to"
		.. " look at, and one of them being Blizzard's reads as a bug")


	-- THE TEXT IS NOT THIS MODULE'S DOING, and checking it here is the point:
	-- a menu line is handed GameFontHighlight by the compositor on every
	-- acquire, and Modules/Fonts.lua remapped that object before any menu
	-- existed. Nothing in Modules/Menus.lua knows the text is there.
	local path, size = menu.__line:GetFont()
	check(tostring(path):find("AetherUI", 1, true),
		"a menu line is in our lettering, from the font object rather than from"
		.. " anything here (" .. tostring(path) .. ")")
	check(size == 12,
		"at the size the client's own object was using, which the remap read"
		.. " back off it rather than inventing (" .. tostring(size) .. ")")

	-- AND AGAIN ON THE NEXT OPEN. The menu frames are pooled and the pool
	-- re-applies GameFontHighlight on every acquire, so a face set once and not
	-- re-applied is gone by the second menu - which is exactly the bug you would
	-- never see while testing, because you always look at the first one.
	local again = _G.__OpenMenu(1)
	check(tostring(select(1, again.__line:GetFont())):find("AetherUI", 1, true),
		"and still ours the second time the same pooled frame is handed out")

	-- ONE BACKGROUND, NOT TWO. Blizzard's Generate attaches an atlas and a
	-- black fill; ours replaces it rather than drawing over it, or the glass
	-- would be sitting on top of - or behind - a panel already saying the same
	-- thing.
	check(menu.__blizzArt == nil,
		"the client's own panel art is not attached at all")

	-- THE MENU FRAME *IS* THE GLASS, rather than carrying a panel inside it.
	--
	-- A panel added as a child is a SIBLING of the menu's own entries, and then
	-- which draws on top rests on level, strata and creation order all at once.
	-- It came out as an empty sheet of glass with every line hidden behind it.
	-- A frame's own textures are always under its children, so there is nothing
	-- left to get wrong.
	check(menu._kind == "panel", "the menu frame is itself the panel")
	check(menu._fillToken == "dialogFill",
		"dressed as a dialog surface, by token - so the skin sweep finds it like"
		.. " any other surface of ours")

	-- ATTACHED, NOT CREATED. CreateTexture is disallowed on a pooled menu frame
	-- - the compositor has to know about every region it will later recycle -
	-- and the mock refuses it, so this passing at all is the proof that Glass
	-- asked the frame how to make a texture rather than assuming.
	check(#(menu.__attached or {}) > 0,
		"and its glass is attached through the compositor (" ..
		#(menu.__attached or {}) .. " regions)")
	local kids = 0
	for _ in ipairs(menu.__children or {}) do kids = kids + 1 end
	check(kids == 0,
		"with no child frame of ours to sit over the entries (" .. kids .. ")")

	-- AND THE LINE IS STILL THERE. The whole failure was a menu that opened as
	-- an empty sheet of glass, so the check that matters is not where the glass
	-- sits but whether anything can still be read on it.
	check(menu.__line and menu.__line:GetText() ~= nil,
		"and the menu's own line survives being dressed (" ..
		tostring(menu.__line and menu.__line:GetText()) .. ")")

	-- ONE SET OF REGIONS PER OPEN. A menu that came back with two would be
	-- drawing its glass over its own glass, and every alpha in the skin would
	-- be wrong by exactly the amount nobody could name.
	local before = #(menu.__attached or {})
	for _ = 1, 5 do _G.__OpenMenu(1) end
	check(#(menu.__attached or {}) == before,
		"one set of regions however many times it opens (" ..
		#(menu.__attached or {}) .. " from " .. before .. ")")

	-- CLOSING TAKES OUR DRESSING OFF, and everything below rests on that.
	--
	-- MenuMixin:Close calls compositor:Detach(), which puts the frame's own
	-- metatable back and drops the table every write since the open went
	-- into. Not some of them: _kind, the tokens, and every method Adopt
	-- copied on. The frame is undressed again, and there is nothing we can
	-- leave on it to say otherwise.
	_G.__CloseMenu(1)
	check(menu._kind == nil and menu.ApplySkin == nil,
		"a closed menu keeps nothing of ours - not a mark, not a method")
	_G.__OpenMenu(1)
	check(menu._kind == "panel", "and the next open dresses it from scratch")

	-- SO THE SURFACE LIST MUST NOT GROW WITH THEM. Dressing again is right;
	-- joining the list again is not, and the mark that stops it cannot live
	-- on the frame for the reason just checked. It lives in Glass, which is
	-- the one place a detach cannot reach. Without it the list gained an
	-- entry per right-click for the whole session, and every skin change
	-- walked the lot.
	local surfaces = #A.Glass.surfaces
	for _ = 1, 10 do _G.__OpenMenu(1) end
	check(#A.Glass.surfaces == surfaces,
		"and the surface list does not gain one per open (" ..
		#A.Glass.surfaces .. " from " .. surfaces .. ")")

	-- A SECOND POOLED FRAME gets its own, though - they are different menus.
	local other = _G.__OpenMenu(2)
	check(other._kind == "panel", "and a second menu frame is dressed too")
end)

section("menus: and gives them back when you switch it off", function()
	local M = A:GetModule("menus")

	A:SetModuleEnabled("menus", false)
	local menu = _G.__OpenMenu(3)
	check(menu.__blizzArt ~= nil,
		"the client draws its own panel again")
	-- The LETTERING stays ours, and should: it belongs to the fonts module, and
	-- somebody switching the menu glass off has said nothing about type.
	check(tostring(select(1, menu.__line:GetFont())):find("AetherUI", 1, true),
		"while the lettering stays ours - that is a different module, and a"
		.. " different question (" ..
		tostring(select(1, menu.__line:GetFont())) .. ")")

	A:SetModuleEnabled("menus", true)
	local back = _G.__OpenMenu(4)
	check(back._kind == "panel" and back.__blizzArt == nil,
		"and ours again on the way back")
end)

section("menus: a client without them costs a skin, not the interface", function()
	-- Blizzard_Menu is present on 1.15.9 and this is written against it. A
	-- module whose absence should cost a context menu its glass must not cost
	-- the player their whole interface on a build that does not have it.
	local M = A:GetModule("menus")
	A:SetModuleEnabled("menus", false)

	local keep1, keep2 = _G.MenuStyle1Mixin, _G.MenuStyle2Mixin
	_G.MenuStyle1Mixin, _G.MenuStyle2Mixin = nil, nil
	A.lastFailure = nil
	A:SetModuleEnabled("menus", true)
	check(A.lastFailure == nil,
		"enabling against a client with no menu system raises nothing (" ..
		tostring(A.lastFailure) .. ")")
	check(M.absent == true, "and it says so rather than pretending it worked")

	_G.MenuStyle1Mixin, _G.MenuStyle2Mixin = keep1, keep2
	A:SetModuleEnabled("menus", false)
	A:SetModuleEnabled("menus", true)
	check(M.absent == nil, "and picks them up again when they are there")
end)

section("skins: the picker is four chips, not four words", function()
	local gui = LibStub("AceGUI-3.0", true)
	local P2 = A.Palette
	check(gui and gui:GetWidgetVersion("AetherUISkinSwatches") == 1,
		"the swatch widget is registered with AceGUI")

	-- AND THE OPTION ASKS FOR IT. Registering a control nothing names is a
	-- control nobody sees, and the picker would quietly still be a dropdown.
	local tree = A.Options:Build()
	local skinOpt = tree.args.general and tree.args.general.args.skin
	check(skinOpt and skinOpt.dialogControl == "AetherUISkinSwatches",
		"and the skin option names it (" ..
		tostring(skinOpt and skinOpt.dialogControl) .. ")")
	check(skinOpt.type == "select",
		"while staying an ordinary select underneath - same profile key, same"
		.. " setter, same restyle after")

	-- The values are WRITTEN NAMES. This read midnight/dawn/noon/dusk in lower
	-- case, because the builder asked List() for `name` and it answers `label`.
	local values = skinOpt.values
	if type(values) == "function" then values = values() end
	check(values.midnight == "Midnight" and values.dusk == "Dusk",
		"offered under written names rather than table keys (" ..
		tostring(values.midnight) .. ")")

	local w = gui:Create("AetherUISkinSwatches")
	w:SetLabel("Skin")
	w:SetList(values)
	w:SetValue("midnight")

	check(#w.chips == 4, "four chips (" .. #w.chips .. ")")

	-- ON A ROW OF ITS OWN. AceConfigDialog's Common Init hands a control one
	-- column's width unless it is already "fill", and the flow layout then puts
	-- the next control beside it - which put the scale slider across the last
	-- chip. Asserted on the widget rather than on the option: four chips side by
	-- side never fit in a column, whatever they are being used to choose.
	check(w.width == "fill",
		"and they take a row of their own, so nothing is laid over the last one"
		.. " (" .. tostring(w.width) .. ")")
	check(w.frame:GetHeight() > 60,
		"with height enough for a chip and its caption, or the row below rides"
		.. " up over them instead (" .. tostring(w.frame:GetHeight()) .. ")")

	-- IN THE DAY'S ORDER, which belongs to the palette. Alphabetical gives dawn,
	-- dusk, midnight, noon and reads as four unrelated words.
	local got = {}
	for i, c in ipairs(w.chips) do got[i] = c.__skinKey end
	check(table.concat(got, ",") == table.concat(P2.order, ","),
		"in the palette's order, not the alphabet's (" ..
		table.concat(got, ", ") .. ")")

	-- EACH CHIP WEARS ITS OWN SKIN. The whole point is to show what choosing it
	-- would do, so the colours come from Palette.skins[key] - not from
	-- Palette.c, which is whatever you are running right now. Checked with
	-- Midnight live, so a chip reading the live palette would make all four the
	-- same and pass nothing.
	A.db.profile.skin = "midnight" A:Restyle()
	w:Refresh()
	local wrong = {}
	for _, c in ipairs(w.chips) do
		local skin = P2.skins[c.__skinKey]
		if c._fillColor ~= skin.glass then wrong[#wrong + 1] = c.__skinKey end
		local r = select(1, c.dot:GetVertexColor())
		if math.abs(r - skin.accent[1]) > 0.001 then
			wrong[#wrong + 1] = c.__skinKey .. ".accent"
		end
	end
	check(#wrong == 0,
		"every chip is its OWN accent on its OWN glass, with Midnight live ("
		.. table.concat(wrong, ", ") .. ")")

	-- And they really do differ, or the line above passes on four identical ones.
	local a, b = w.chips[1], w.chips[4]
	check(select(1, a.dot:GetVertexColor()) ~= select(1, b.dot:GetVertexColor()),
		"and the first and last are different colours")

	-- THE MARK FOLLOWS THE VALUE.
	check(w.chips[1].tick:IsShown() and not w.chips[4].tick:IsShown(),
		"the live skin is the marked one")
	w:SetValue("dusk")
	check(w.chips[4].tick:IsShown() and not w.chips[1].tick:IsShown(),
		"and the mark moves with it rather than accumulating")

	-- CLICKING SAYS SO. AceConfigDialog listens on OnValueChanged and does the
	-- rest; a chip that changed the skin itself would be a second owner for a
	-- fact the option already owns.
	local fired
	w:SetCallback("OnValueChanged", function(_, _, key) fired = key end)
	w.chips[2]:GetScript("OnClick")(w.chips[2])
	check(fired == "dawn",
		"clicking a chip fires the option's own callback with that skin (" ..
		tostring(fired) .. ")")

	-- DISABLED SAYS NOTHING.
	fired = nil
	w:SetDisabled(true)
	w.chips[3]:GetScript("OnClick")(w.chips[3])
	check(fired == nil, "a disabled picker does not answer a click")
	w:SetDisabled(false)

	-- CHIPS ARE BUILT ONCE. AceGUI pools its widgets, so a panel opened twenty
	-- times hands this same widget back - anything built per refresh would
	-- accumulate for the life of the session.
	local function kids()
		local n = 0
		for _ in ipairs(w.frame.__children or {}) do n = n + 1 end
		return n
	end
	local before = kids()
	for _ = 1, 10 do w:Refresh() end
	check(kids() == before,
		"and are reused rather than rebuilt on every refresh - counted on the"
		.. " FRAME, because a chip replaced in the list is still parented and"
		.. " still on screen, stacked under the one that replaced it (" ..
		kids() .. " after ten, from " .. before .. ")")

	-- A SKIN THE ORDER DOES NOT NAME still appears, appended, rather than
	-- vanishing from the picker with no way to choose it.
	local extra = {}
	for k, v in pairs(values) do extra[k] = v end
	extra.twilight = "Twilight"
	w:SetList(extra)
	check(#w.chips == 5 and w.chips[5].__skinKey == "twilight",
		"one the order does not name is offered last rather than not at all")

	w:SetList(values)
	A.db.profile.skin = "midnight" A:Restyle()
end)

section("panels: the Options window our settings live inside", function()
	local PNm = A:GetModule("panels")
	local sp = _G.SettingsPanel
	check(sp ~= nil, "the client has an Options window")

	-- SKINNED LIKE ANY OTHER CLIENT WINDOW. It is the one place a player sees
	-- ours and Blizzard's at the same time - our page inside their frame - so a
	-- stone shell around glass contents makes OURS look like the thing that does
	-- not belong.
	check(sp.__aetherPanel ~= nil, "and it wears our glass")
	check(sp.__aetherArt ~= nil, "with its own art recorded and taken off")

	-- EVERY PART IS A parentKey, not a named global. That is what makes this a
	-- list rather than a hunt, and it is why the pieces below have to be named:
	-- nothing in the shell strip reaches a child frame with art of its own.
	for _, key in ipairs({ "GameTab", "AddOnsTab" }) do
		local tab = sp[key]
		check(tab and tab.__aetherMark ~= nil and tab.__aetherSkin == nil,
			key .. " is ours rather than the client's plate - and a MARK rather"
			.. " than a fill, like every other tab in the interface")
	end
	-- ITS RAIL IS ON TOP, because its tabs are - the line and the mark go on
	-- whichever edge faces the settings they switch between.
	local srail = sp.__aetherRails["TOP"]
	check(srail ~= nil and srail._edge == "TOP",
		"the Options tabs sit on a rail of their own (" ..
		tostring(srail and srail._edge) .. ")")

	-- AND THIS WINDOW SAYS WHICH IS OPEN DIFFERENTLY. The older panels disable
	-- the selected tab; this one uses SelectableButtonMixin and moves the
	-- label and swaps the font object on every selection - so the state is
	-- read from IsSelected and re-asserted from a hook, or the first click
	-- hands the word straight back to Blizzard's own font.
	-- AT DRESS TIME, before anything has been clicked. The window opens on
	-- whichever tab it was left on, and a mark that only appears once you
	-- click is a window that comes up saying you are nowhere.
	check(sp.GameTab.__aetherMark:IsShown()
		and not sp.AddOnsTab.__aetherMark:IsShown(),
		"the one it opened on is the marked one, with no click involved")

	sp.GameTab:OnSelected(false)
	sp.AddOnsTab:OnSelected(true)
	check(sp.AddOnsTab.__aetherMark:IsShown()
		and not sp.GameTab.__aetherMark:IsShown(),
		"and it moves when the client moves its own selection")
	sp.AddOnsTab:OnSelected(false)
	sp.GameTab:OnSelected(true)
	check(sp.GameTab.Text._aetherStyle == "pnBody",
		"with its word still in our type after the client re-fonted it (" ..
		tostring(sp.GameTab.Text._aetherStyle) .. ")")

	for _, key in ipairs({ "CloseButton", "ApplyButton" }) do
		local btn = sp[key]
		check(btn and btn.__aetherSkin ~= nil, key .. " likewise")
	end

	-- The category list, the container and the search box are each a frame with
	-- their own background, so each needs saying.
	local function bare(frame)
		for _, r in ipairs({ frame:GetRegions() }) do
			if r.GetTexture and r:GetTexture() ~= 0 and r:GetTexture() ~= nil then
				return false
			end
		end
		return true
	end
	check(bare(sp.CategoryList), "the category list has lost its own background")
	check(bare(sp.Container), "and the pane that holds the open page")
	check(sp.SearchBox.__aetherPill ~= nil,
		"and the search box wears a pill rather than its own art")

	-- And switching the module off gives the whole window back, which is the
	-- promise every reskin here makes.
	A:SetModuleEnabled("panels", false)
	check(sp.__aetherArt == nil,
		"switching Windows off hands the Options frame back whole")
	A:SetModuleEnabled("panels", true)
	check(sp.__aetherArt ~= nil, "and takes it again on the way back")
end)

section("options: our own settings, in our own interface", function()
	local M = A:GetModule("optionsskin")
	local gui = LibStub("AceGUI-3.0", true)
	check(M and M.enabled, "options skin enabled"
		.. (M and M.lastError and ("  -- " .. M.lastError) or ""))
	check(not M.absent, "and it found the library it dresses")

	-- ONE HOOK, DISPATCHED BY TYPE. Every control in the panel comes out of
	-- AceGUI:Create, so a widget made right now - after the module enabled -
	-- arrives dressed without anything naming it.
	local btn = gui:Create("Button")
	check(btn.frame.__aetherSkin ~= nil,
		"a button comes back wearing our glass rather than Blizzard's red")

	local grp = gui:Create("InlineGroup")

	-- THE BOX YOU CAN SEE IS NOT THE WIDGET'S FRAME. An InlineGroup's `frame` is
	-- invisible chrome; what is drawn is a CHILD carrying a BackdropTemplate,
	-- and the group's contents are children of THAT. AceGUI keeps it as a local,
	-- so the one way to it is the content's parent - and dressing `frame`
	-- instead stripped nothing anybody could see.
	local box = grp.content:GetParent()
	check(box ~= grp.frame, "the drawn box is not the widget's own frame")
	check(box.__aetherPanel ~= nil and box.__aetherStripped ~= nil,
		"and it is the one that gets stripped and glassed")

	-- AND ITS CONTENTS ABOVE THE GLASS. Reskin.Panel puts a panel a level below
	-- its frame, which is right for a client window whose insides are REGIONS of
	-- it. An Ace group keeps its contents in a CHILD frame, and two children at
	-- the same level draw in creation order - so the panel, made last, went over
	-- every control in the group and the text was still there behind a sheet of
	-- 97% glass.
	-- BEHIND THE FRAME, not inside it. An Ace container keeps its contents in a
	-- child frame rather than in regions of its own, so glass placed inside is a
	-- SIBLING of everything in the group - and the draw order then rests on
	-- level, strata and creation order together, which is three things to keep
	-- right instead of none.
	local panel = box.__aetherPanel

	-- A CHILD OF THE BOX, and that is the whole safeguard.
	--
	-- Glass as a SIBLING was tried, to sidestep a draw-order problem that turned
	-- out to be us dressing the wrong frame - and it put two sheets across the
	-- screen at login, twice. AceGUI parents its widget frames to UIParent, so a
	-- sibling is parented to UIParent, and glass whose visibility is tracked by
	-- hand outlives the frame it was drawn for the moment anything hides that
	-- frame by a path that does not fire OnHide. A child cannot: it is not drawn
	-- when its parent is not.
	check(panel:GetParent() == box,
		"the glass is a CHILD of the box, so it cannot outlive it")
	check(panel:GetFrameLevel() < box:GetFrameLevel(),
		"and a level below it (" .. panel:GetFrameLevel() .. " vs "
		.. box:GetFrameLevel() .. ")")
	check(grp.content:GetFrameLevel() > panel:GetFrameLevel(),
		"with the contents above, which is what the box's own children give for"
		.. " free (" .. grp.content:GetFrameLevel() .. ")")

	-- A BUTTON'S ART IS NOT ALWAYS A STATE TEXTURE. UIPanelButtonTemplate draws
	-- itself with three BACKGROUND regions - Left, Middle, Right - and clearing
	-- the normal/pushed/highlight set never touched them, so a button came back
	-- with our glass behind it and Blizzard's red still on top.
	local red = 0
	for _, r in ipairs({ btn.frame:GetRegions() }) do
		local tex = r.GetTexture and r:GetTexture()
		if type(tex) == "string" and tex:find("UI%-Panel%-Button") then
			red = red + 1
		end
	end
	check(red == 0,
		"and not one piece of the client's button art is left on it (" .. red
		.. ")")
	check(btn.text and btn.text:GetText() ~= nil or true,
		"with its label kept - a plain strip takes the words off with the stone")


	-- THE ROWS ARE MADE LATER, and remade whenever the tree is filtered or a
	-- branch opens - so dressing whatever exists at Create time would cover the
	-- first page and nothing after it. RefreshTree is what builds and repaints
	-- them, and it is wrapped.
	--
	-- Driven the way the client does: the tree bails out and defers to an
	-- OnUpdate while its frame is parented to UIParent, so the fixture gives it
	-- a real parent and a real height first.
	local tree = gui:Create("TreeGroup")
	tree.frame:SetParent(CreateFrame("Frame", nil, UIParent))
	tree.frame:SetSize(400, 300)
	tree.treeframe:SetSize(160, 300)
	tree:SetTree({ { value = "a", text = "Alpha" }, { value = "b", text = "Beta" } })
	tree:SelectByValue("a")

	check(#tree.buttons > 0, "the tree builds rows (" .. #tree.buttons .. ")")

	local chosen, other
	for _, row in ipairs(tree.buttons) do
		if row.selected then chosen = chosen or row else other = other or row end
	end
	check(chosen ~= nil, "and one of them is the selected one")

	-- A row is an OptionsListButtonTemplate and the selection is Blizzard's blue
	-- gradient, drawn by LockHighlight on the button's own highlight texture. So
	-- the art comes off and the selection is drawn by us - which means reading
	-- `selected` rather than a texture we have just taken away.
	if chosen then
		-- The client's own selection is a blue gradient on the row's HIGHLIGHT
		-- texture, drawn permanently by LockHighlight. It has to come off, or
		-- ours is simply painted underneath it.
		local hl = chosen.GetHighlightTexture and chosen:GetHighlightTexture()
		check(hl == nil or hl:GetTexture() == 0,
			"the client's blue gradient is off the row (" ..
			tostring(hl and hl:GetTexture()) .. ")")

		check(chosen.__aetherSel ~= nil and chosen.__aetherSel:IsShown(),
			"the chosen row wears our selection")
		local r = select(1, chosen.__aetherSel:GetVertexColor())
		check(math.abs(r - A.Palette.c.rowSel[1]) < 0.001,
			"in the palette's row colour rather than the client's blue (" ..
			string.format("%.2f", r) .. ")")
	end
	if other then
		check(other.__aetherSel ~= nil and not other.__aetherSel:IsShown(),
			"and an unchosen row wears none - one drawn on every row is a list with"
			.. " nothing chosen at all")
	end

	-- AND THE ROWS BUILT ON THE NEXT REFRESH TOO. This is the whole reason the
	-- method is wrapped rather than the rows dressed once.
	tree:SetTree({ { value = "a", text = "Alpha" }, { value = "b", text = "Beta" },
		{ value = "c", text = "Gamma" } })
	local undressed = 0
	for _, row in ipairs(tree.buttons) do
		if not row.__aetherSel then undressed = undressed + 1 end
	end
	check(undressed == 0,
		"a row built by a later refresh is dressed with the rest (" .. undressed
		.. " bare of " .. #tree.buttons .. ")")

	check(tree.border and tree.border.__aetherPanel ~= nil,
		"the category list gets glass")
	check(tree.treeframe and tree.treeframe.__aetherPanel ~= nil,
		"and so does the list beside it - two frames, and dressing one of them"
		.. " leaves a stone edge down the middle")

	-- A SLIDER IS THREE PIECES OF ART. The groove, the thumb and the number box
	-- under it, and leaving any one alone is what makes a control look half done.
	local sl = gui:Create("Slider")
	check(sl.slider.__aetherTrack ~= nil, "a slider gets a hairline groove")
	local thumb = sl.slider:GetThumbTexture()
	check(tostring(thumb.__tex):find("AetherUI", 1, true),
		"and our thumb on it (" .. tostring(thumb.__tex) .. ")")
	check(sl.editbox.__aetherPill ~= nil,
		"with the number box under it in glass too")

	-- The check box keeps its TICK and loses its box. A tick taken off with the
	-- rest never looks checked, whatever the state says.
	local cb = gui:Create("CheckBox")
	local r = select(1, cb.check:GetVertexColor())
	check(math.abs(r - A.Palette.c.accent[1]) < 0.001,
		"a check box keeps its tick, in the accent (" ..
		string.format("%.2f", r) .. ")")

	-- THE STANDALONE WINDOW has three parts a plain container does not, and all
	-- three are anchored to art we have just taken off.
	local win = gui:Create("Frame")
	A.lastFailure = nil
	M.Dress(win)
	check(A.lastFailure == nil,
		"dressing the window raises nothing (" .. tostring(A.lastFailure) .. ")")
	check(win.frame.__aetherPanel ~= nil,
		"and it gets its glass - the LAST thing the dresser does, so this is"
		.. " what says the whole of it ran rather than the first half")

	-- The title hung off a header texture anchored ABOVE the frame, so with the
	-- art gone the words landed on the top border with nothing over them. The
	-- HEADER is re-anchored rather than the words, because the invisible frame
	-- you drag the window by is SetAllPoints on it and is not exposed at all.
	local p, rel, relP, _, y = win.titlebg:GetPoint(1)
	check(rel == win.frame,
		"the title bar hangs off the window itself (" .. tostring(rel and "frame")
		.. ")")
	check(p == "TOP" and relP == "TOP" and y < 0,
		"and sits INSIDE its top edge rather than over it (" .. tostring(p) ..
		" " .. tostring(y) .. ")")
	check(select(2, win.titletext:GetPoint(1)) == win.titlebg,
		"with the words on the bar, so the two cannot drift apart")

	-- The status line is a Button with its own backdrop, so stripping the
	-- window's regions never reached it - it is the wide dark box along the
	-- bottom.
	-- Reached through the status TEXT, because AceGUI keeps the bar itself as a
	-- local and never puts it on the widget. The first pass read widget.statusbg,
	-- found nil, and did nothing at all - silently, since skipping a part that
	-- is not there raises nothing.
	local statusbg = win.statustext:GetParent()
	check(statusbg:GetBackdrop() == nil,
		"the status line has lost its backdrop")
	check(statusbg.__aetherPill ~= nil, "and wears glass instead")

	-- The Close button is the other thing AceGUI keeps to itself, and it was
	-- the last red thing on the window.
	local closed
	for _, child in ipairs({ win.frame:GetChildren() }) do
		if child ~= statusbg and child.__aetherSkin then closed = child end
	end
	check(closed ~= nil, "and the Close button is ours rather than Blizzard's red")

	-- The size grip is three textures out of the tooltip border atlas, children
	-- of the sizer rather than regions of the window, so they survive the strip
	-- and read as a scrap of somebody else's art in the corner.
	local tinted, total = 0, 0
	for _, r in ipairs({ win.sizer_se:GetRegions() }) do
		total = total + 1
		if r._aetherTint then tinted = tinted + 1 end
	end
	check(total > 0 and tinted == total,
		"and every piece of the size grip is re-tinted (" .. tinted .. " of "
		.. total .. ")")

	-- AND THE SCROLL BAR, which only appears once the window is dragged small
	-- enough to need one - which is exactly when nobody is looking for it, and
	-- is where Blizzard's arrows came back.
	local sf = gui:Create("ScrollFrame")
	check(sf.scrollbar and sf.scrollbar.__aetherScroll,
		"a scroll frame's bar is ours before it is ever shown")
	check(sf.scrollbar.__aetherTrack ~= nil,
		"with a rail, so a list you can scroll says so even at rest")

	-- A DROPDOWN IS NOT AN EDIT BOX. Handing the whole UIDropDownMenuTemplate
	-- frame to the edit box dresser wrapped a pill round the ART rather than
	-- round the control, which is why they came out half again too tall.
	local dd = gui:Create("Dropdown")
	check(dd.dropdown.__aetherStripped ~= nil,
		"a dropdown loses the template's own art")
	check(dd.dropdown.__aetherPill ~= nil, "and wears a pill instead")
	check(dd.dropdown.__aetherPill:GetHeight() < 30,
		"sized to the text row rather than to the frame around it (" ..
		tostring(dd.dropdown.__aetherPill:GetHeight()) .. ")")
	check(dd.button and dd.button.__aetherGlyph ~= nil,
		"and the arrow is our chevron rather than a gold plate")

	local hd = gui:Create("Heading")
	check(tostring(hd.left.__tex):find("AetherUI", 1, true),
		"a heading rule is ours (" .. tostring(hd.left.__tex) .. ")")

	-- STRIPPED ONCE. AceGUI pools its widgets, so this same frame comes back for
	-- the next panel that needs one - and stripping again would record our own
	-- emptied regions as the originals, which makes switching the module off a
	-- no-op that looks like it worked.
	local store = box.__aetherStripped
	local n = 0
	for _ in pairs(store) do n = n + 1 end
	M.Dress(grp)
	M.Dress(grp)
	local after = 0
	for _ in pairs(box.__aetherStripped) do after = after + 1 end
	check(box.__aetherStripped == store and after == n,
		"dressing again keeps the first recording rather than re-taking it (" ..
		after .. " of " .. n .. ")")

	-- A TYPE WE DO NOT DRESS IS LEFT ALONE, not guessed at.
	A.lastFailure = nil
	local ok = pcall(M.Dress, { type = "SomethingElse", frame = CreateFrame("Frame") })
	check(ok and A.lastFailure == nil,
		"a widget type this does not know is passed over in silence")

	-- AND A DRESSER THAT ERRORS DOES NOT TAKE THE PANEL WITH IT. These are
	-- somebody else's frames, built by a library that changes shape between
	-- versions, and a settings panel that errors is worse than one that looks
	-- like Blizzard's.
	A.lastFailure = nil
	ok = pcall(M.Dress, { type = "Slider" })   -- no slider, no editbox, no frame
	check(ok, "a dresser handed a widget with nothing on it raises nothing")
end)

section("options: and hands Blizzard's panel back", function()
	local M = A:GetModule("optionsskin")
	local gui = LibStub("AceGUI-3.0", true)

	local grp = gui:Create("InlineGroup")
	local box = grp.content:GetParent()
	check(box.__aetherStripped ~= nil, "dressed to begin with")

	A:SetModuleEnabled("optionsskin", false)
	check(box.__aetherStripped == nil,
		"switching off puts the client's own regions back")

	-- And the hook comes off with it: a widget built while the module is off is
	-- Blizzard's, or "off" only means "off for the ones already made".
	local after = gui:Create("InlineGroup")
	local abox = after.content:GetParent()
	check(abox.__aetherStripped == nil and abox.__aetherPanel == nil,
		"and one built afterwards is untouched")

	A:SetModuleEnabled("optionsskin", true)
	local back = gui:Create("InlineGroup")
	check(back.content:GetParent().__aetherPanel ~= nil,
		"and ours again on the way back")
end)

section("conveniences: instant quest text is the client's own setting", function()
	local CVm = A:GetModule("conveniences")
	local c = A.Config:Module("conveniences")
	check(CVm and CVm.enabled, "conveniences module enabled")

	-- OFF TO BEGIN WITH, and that is a decision rather than an oversight: this
	-- overrides a setting the client already has, under Interface, which the
	-- player may have chosen on purpose.
	check(c.instantQuestText == false,
		"off by default - it overrides a setting the player may have chosen")
	check(GetCVar("instantQuestText") == "0",
		"and the game is left as it was until asked")

	-- NOTHING IS HOOKED. QuestFrame reads this CVar itself every time it opens a
	-- page, so writing it IS the feature - hooking the fade or forcing an alpha
	-- would be a second owner for something the client already decides.
	c.instantQuestText = true
	CVm:ApplyQuestText()
	check(GetCVar("instantQuestText") == "1",
		"turning it on sets the client's own variable (" ..
		tostring(GetCVar("instantQuestText")) .. ")")

	-- AND IT IS IDEMPOTENT. Every write to a CVar is a write the client logs,
	-- and a config change runs this again.
	local writes = _G.__cvarWrites
	CVm:ApplyQuestText()
	CVm:ApplyQuestText()
	check(_G.__cvarWrites == writes,
		"and setting it again writes nothing - it is already what we want")

	-- BACK THE WAY IT WAS. Not to "0" - to whatever it was before we touched
	-- it, which is the difference between restoring and guessing.
	c.instantQuestText = false
	CVm:ApplyQuestText()
	check(GetCVar("instantQuestText") == "0",
		"turning it off puts the player's own setting back")

	do
		-- A player who had it on ALREADY gets it back on, which is the case a
		-- restore-to-zero would quietly break.
		SetCVar("instantQuestText", "1")
		c.instantQuestText = true
		CVm:ApplyQuestText()
		c.instantQuestText = false
		CVm:ApplyQuestText()
		check(GetCVar("instantQuestText") == "1",
			"and somebody who already had it on keeps it on afterwards")
		SetCVar("instantQuestText", "0")
	end
end)

section("conveniences: repairing spends money, so it says so", function()
	local CVm = A:GetModule("conveniences")
	local c = A.Config:Module("conveniences")
	local R = _G.__repair

	check(c.autoRepair == false,
		"off by default, because it spends your money")

	-- NOTHING TO DO IS NOT AN ERROR. GetRepairAllCost answers TWO values - the
	-- cost and whether anything needs doing - and reading only the first is how
	-- an addon repairs for nothing every time a merchant opens.
	c.autoRepair = true
	R.cost, R.repairs, R.refused = 0, 0, 0
	_G.__money = 100000
	check(CVm:Repair() == nil, "a merchant with nothing to repair costs nothing")
	check(R.repairs == 0, "and no repair is attempted")

	-- The ordinary case.
	R.cost = 5000
	local before = _G.__money
	check(CVm:Repair() == "repaired", "an armour bill is paid")
	check(_G.__money == before - 5000,
		"and the money goes (" .. tostring(before - _G.__money) .. ")")

	-- CANNOT AFFORD IT. RepairAllItems on too little money does NOTHING in the
	-- client - no error, no partial repair - so an addon that fired blind would
	-- look like it had repaired and leave you in a fight with a broken weapon.
	R.cost, R.repairs, R.refused = 9999999, 0, 0
	_G.__money = 10
	check(CVm:Repair() == "broke", "too little money is reported, not ignored")
	check(R.repairs == 0 and R.refused == 0,
		"and the client is never asked - it would have said nothing either way")
	check(_G.__money == 10, "with the money untouched")

	-- A MERCHANT WHO CANNOT REPAIR is left alone.
	R.canMerchant, R.cost, R.repairs = false, 5000, 0
	_G.__money = 100000
	check(CVm:Repair() == nil, "a merchant who cannot repair is not asked to")
	check(R.repairs == 0, "and nothing is spent at one")
	R.canMerchant = true

	-- AND THE SWITCH IS THE SWITCH.
	c.autoRepair = false
	R.cost, R.repairs = 5000, 0
	check(CVm:Repair() == nil and R.repairs == 0,
		"switched off, a merchant opening costs nothing")

	-- Through the EVENT, which is what actually drives it: MERCHANT_SHOW rather
	-- than a frame appearing, because the event is the game saying a merchant is
	-- open whether or not anything has drawn a window yet.
	c.autoRepair = true
	R.cost, R.repairs = 3000, 0
	_G.__money = 100000
	fire("MERCHANT_SHOW")
	check(R.repairs == 1,
		"and opening a merchant repairs, from the event rather than a frame")

	c.autoRepair = false
	R.cost = 0
end)

section("options: every page has a place of its own", function()
	-- TWO PAGES ON THE SAME NUMBER is not an error and does not look like one:
	-- AceConfig sorts by order and breaks the tie however it likes, so a page
	-- inserted in the middle silently swaps places with its neighbour on some
	-- runs and not others. Which is precisely what inserting one just did.
	local tree = A.Options:Build()
	local seen, clash = {}, nil
	for key, node in pairs(tree.args or {}) do
		local o = node and node.order
		if type(o) == "number" then
			if seen[o] then clash = clash or (key .. " and " .. seen[o] .. " are both " .. o) end
			seen[o] = key
		end
	end
	check(not clash, "no two pages share an order (" .. tostring(clash) .. ")")

	-- AND EVERY MODULE IS REACHABLE FROM SOMEWHERE IN IT. A module with a
	-- config table and no control anywhere is one a player cannot switch on,
	-- and it ships looking exactly like a module that does not work. This one
	-- nearly went out that way.
	--
	-- Reachability, not a page each: five modules share the "The game's own"
	-- page and are perfectly reachable there. So the tree is walked for the
	-- config paths its controls actually write to, which is the same question
	-- asked without assuming the shape of the answer.
	local reached = {}
	local function walk(node)
		if type(node) ~= "table" then return end
		local path = node.arg and node.arg.path
		if type(path) == "table" and path[1] == "modules" and path[2] then
			reached[path[2]] = true
		end
		for _, child in pairs(node.args or {}) do walk(child) end
	end
	walk(tree)

	local unreachable = {}
	for name in pairs(A.Config.defaults.profile.modules or {}) do
		if not reached[name] then unreachable[#unreachable + 1] = name end
	end
	table.sort(unreachable)
	check(#unreachable == 0,
		"every module with settings can be reached from the panel (" ..
		(#unreachable > 0 and table.concat(unreachable, ", ") or "all of them")
		.. ")")
end)

print("== options tree ==")
do
	local tree = A.Options:Build()
	check(type(tree) == "table" and tree.type == "group", "the tree builds")

	-- Walking it and checking every path is the whole reason Build() is pure.
	-- A typo in a path is otherwise a control that silently does nothing, and
	-- you find it a month later.
	local leaves, bad, kinds = 0, {}, {}
	local function walk(node, trail)
		for key, opt in pairs(node.args or {}) do
			local where = trail .. "." .. key
			if opt.type == "group" then
				walk(opt, where)
			elseif opt.arg and opt.arg.path then
				leaves = leaves + 1
				kinds[opt.type] = (kinds[opt.type] or 0) + 1
				local t, k = A.Options.Resolve(opt.arg.path)
				if not t then
					bad[#bad + 1] = where .. " (no table at " .. table.concat(opt.arg.path, ".") .. ")"
				elseif t[k] == nil then
					bad[#bad + 1] = where .. " -> " .. table.concat(opt.arg.path, ".") .. " is nil"
				end
			end
		end
	end
	walk(tree, "root")

	check(leaves > 50, "it has a real number of controls in it (" .. leaves .. ")")
	check(#bad == 0, "every control's path resolves to something that exists"
		.. (#bad > 0 and ("  -- " .. table.concat(bad, "; ")) or ""))
	check((kinds.toggle or 0) > 0 and (kinds.range or 0) > 0 and (kinds.select or 0) > 0,
		"toggles, ranges and selects all present")

	-- A button that leaves a MODE running has to name what it will do next.
	--
	-- Both of these close the panel and leave something switched on, so the
	-- next time anybody opens this page the mode is already running - and a
	-- button still offering to start it is a button lying about the state of
	-- the screen. Ace resolves a function `name` when the page is built, which
	-- is exactly the moment that matters here.
	do
		local function Find(node, key)
			for k, opt in pairs(node.args or {}) do
				if k == key then return opt end
				if opt.type == "group" then
					local hit = Find(opt, key)
					if hit then return hit end
				end
			end
		end

		local unlock = Find(tree, "unlock")
		check(unlock and type(unlock.name) == "function",
			"the unlock button names itself dynamically rather than carrying a"
			.. " fixed string")

		A.Movers:Lock()
		check(unlock.name() == "Unlock frames", "locked, it offers to unlock")
		A.Movers:Unlock()
		check(unlock.name() == "Lock frames",
			"and once they ARE unlocked it offers to lock - the panel is shut"
			.. " for the whole time the mode is on, so this is read on the next"
			.. " open (got " .. tostring(unlock.name()) .. ")")
		A.Movers:Lock()

		local bind = Find(tree, "bind")
		check(bind and type(bind.name) == "function",
			"and keybind mode does the same - it has the identical shape and"
			.. " would have the identical bug")
		local AB = A:GetModule("actionbars")
		if AB and AB.enabled then
			AB:SetBindMode(false)
			check(bind.name() == "Keybind mode", "off, it offers to enter")
			AB:SetBindMode(true)
			check(bind.name() == "Leave keybind mode", "on, it offers to leave")
			AB:SetBindMode(false)
		end
	end

	-- and the accessors round-trip through the real db
	local widthOpt = tree.args.unitframes.args.width
	local before = widthOpt.get({ arg = widthOpt.arg, type = "range" })
	check(before == A.db.profile.modules.unitframes.width, "get reads the live value")
	widthOpt.set({ arg = widthOpt.arg, type = "range" }, 360)
	check(A.db.profile.modules.unitframes.width == 360, "set writes it back")
	widthOpt.set({ arg = widthOpt.arg, type = "range" }, before)

	-- a nil-means-true toggle has to report true, or the checkbox lies
	local hb = tree.args.auras.args.hideBlizzard
	A.db.profile.modules.auras.hideBlizzard = nil
	check(hb.get({ arg = hb.arg, type = "toggle" }) == true,
		"a toggle that defaults to nil-means-true reports true, not nil")
	A.db.profile.modules.auras.hideBlizzard = true

	-- bar pages are generated from the config, so a bar added later gets controls
	local bars = tree.args.actionbars.args
	local pages = 0
	for k in pairs(bars) do if k:find("^bar") then pages = pages + 1 end end
	check(pages == #A.db.profile.modules.actionbars.bars,
		"one page per configured bar, generated rather than hard-coded (got "
		.. pages .. " for " .. #A.db.profile.modules.actionbars.bars .. " bars)")
	check(bars.barstance.args.page == nil,
		"a stance bar gets no page control - its buttons come from the game")
	check(bars.bar1.args.page ~= nil, "an action bar does")

	-- profiles go last, and that has to be a decision rather than a guess: the
	-- running order counter lands in the hundreds by the end of the tree
	local tops = {}
	for key, opt in pairs(tree.args) do
		if opt.type == "group" and opt.order then tops[key] = opt.order end
	end
	check(tops.general == 1, "General is the first page")
	local maxOther = 0
	for key, n in pairs(tops) do
		if key ~= "profiles" then maxOther = math.max(maxOther, n) end
	end
	check(A.Options.PAGE_ORDER.profiles > maxOther,
		"and profiles sorts after every other page (" .. A.Options.PAGE_ORDER.profiles
		.. " > " .. maxOther .. ")")

	-- registration degrades rather than erroring when Ace3 is absent
	check(A.Options:Register() == false,
		"Register reports false without the Ace libraries instead of throwing")
	SlashCmdList["AETHERUI"]("")
	check(true, "and bare /aether falls back to the command list")
end

print("== minimap ==")

local MMm = A:GetModule("minimap")
check(MMm and MMm.enabled, "minimap module enabled"
	.. (MMm and MMm.lastError and ("  -- " .. MMm.lastError) or ""))
check(MMm.frame and MMm.pill, "map holder and zone pill built")
check(MMm.drawer == nil,
	"and NO drawer - addon launchers live on the Toolbox rail now. Defaulting"
	.. " it off was not enough: the drawer showed its contents ON HOVER, so"
	.. " any button the rail had not claimed sat in a frame at alpha 0 and"
	.. " simply vanished until somebody hovered the zone pill")

do  -- Blizzard's Minimap is reshaped, not replaced: it cannot be recreated
	local cfg = A.db.profile.modules.minimap
	check(Minimap:GetParent() == MMm.frame,
		"the real Minimap is reparented into our holder rather than rebuilt")
	check(Minimap.__mask ~= nil, "and masked round")
	check(Minimap:GetWidth() == cfg.size, "sized from the config")
	-- Layering: an earlier version hung a soft ring off the holder as a plain
	-- BACKGROUND region meaning to put it behind the map, and a region draws at
	-- its own frame's strata - so it landed on top instead.
	check(MMm.frame.border ~= nil and MMm.frame.vignette == nil and MMm.frame.rim == nil,
		"the whole edge is one texture - a rim plus a separately-gated vignette"
		.. " was two draw orders and two switches, and the bug was in the seam"
		.. " between them every single time")
	check(MMm.frame.border:GetAlpha() == 1,
		"drawn at full alpha rather than behind a config value that could be 0")
	do
		-- Same hue as every pill's rim. The band survives the multiply because
		-- it is baked dark, which is why the tones are luminance and not colour.
		local r = select(1, MMm.frame.border:GetVertexColor())
		check(math.abs(r - A.Palette.c.glassEdge[1]) < 0.001,
			"and tinted with glassEdge, so the map's border and the zone pill"
			.. " under it are the same colour")
	end
	check(MMm.frame.top:GetFrameStrata() == "MEDIUM"
		and Minimap:GetFrameStrata() == "LOW",
		"and on a whole strata above the map, not merely a higher level - the"
		.. " Minimap is a widget the client renders into, and it does not"
		.. " composite against a sibling at its own strata")
	do
		local _, rel, _, x = MMm.frame.border:GetPoint(1)
		check(rel == MMm.frame and x < 0,
			"and drawn proud of the map, not flush with it - a mask edge is the"
			.. " client's to anti-alias and it stair-steps, so the border has to"
			.. " lap over it rather than stop short")
	end
	check(A.db.profile.modules.minimap.shadow == nil,
		"the old shadow key is migrated away - a profile carrying 0 from the"
		.. " version where it was off by default would hide the border")
	check(Minimap:GetFrameStrata() == "LOW",
		"with the map itself left in Blizzard's own band, where other addons"
		.. " expect to find it")
	check(MinimapCluster.__mouse == false,
		"the cluster's mouse is off - it is a rectangle much bigger than the map"
		.. " and it swallows clicks meant for what is behind it")
end

do  -- the furniture
	local r = MMm.hideReport
	check(r.MinimapBorder == "hidden" and r.MinimapZoomIn == "hidden"
		and r.MiniMapTracking == "hidden" and r.GameTimeFrame == "hidden",
		"the border, zoom, tracking and day/night dial are all banished")
	check(_G.MinimapZoomIn:GetParent() ~= MinimapCluster,
		"banished frames are reparented off the cluster, so another addon calling"
		.. " Show() on one cannot put it back")
	check(r.MiniMapWorldMapButton == nil,
		"MiniMapWorldMapButton is never touched - it is Wrath+ only and does not"
		.. " exist on this client")

	-- The named list is not the whole job: some of the art up there is an
	-- anonymous region with no global to put in a list, which is what left a
	-- border bar and a toggle tab sitting above the map first time round.
	check(not _G.__clusterArt:IsShown() and _G.__clusterArt:GetAlpha() == 0,
		"an unnamed region of the cluster is swept too")
	check(not _G.MinimapZoneTextButton:IsShown(),
		"and a named Blizzard child is banished whether it was listed or not")
	check(_G.SomeAddonOnTheCluster:IsShown(),
		"but an addon's own frame on the cluster is left exactly where it is -"
		.. " issecurevariable tells the two apart")
	check(r.MinimapBackdrop == "swept",
		"the backdrop is recursed into rather than carried off, so a third-party"
		.. " button parented there does not go with it")

	-- the two that were doing real work survive without any chrome
	_G.__minimapPinged, _G.__trackingMenu = nil, nil
	Minimap:GetScript("OnMouseWheel")(Minimap, 1)
	check(Minimap:GetZoom() == 1, "the wheel zooms in")
	Minimap:GetScript("OnMouseWheel")(Minimap, -1)
	check(Minimap:GetZoom() == 0, "and out")
	-- THROUGH THE CLIENT'S OWN MENU. The dropdown frame this used to reach for
	-- has not existed for years; the mock invented it because we asked, so the
	-- suite was green while right-clicking the map did nothing at all. Opened
	-- as a CONTEXT menu, which puts it at the cursor: the button's own OpenMenu
	-- anchors to the button, and the button is hidden furniture in a corner.
	Minimap:GetScript("OnMouseUp")(Minimap, "RightButton")
	check(_G.__trackingMenu == Minimap,
		"right-click opens the tracking menu at the map, not at the hidden"
		.. " button that used to own it")
	Minimap:GetScript("OnMouseUp")(Minimap, "LeftButton")
	check(_G.__minimapPinged, "and left-click still pings")
end

print("== the zone pill ==")
do
	local cfg = A.db.profile.modules.minimap
	MMm:UpdateZone()
	check(MMm.pill.zone:GetText() == "The Barrens", "zone named")
	check(MMm.pill.coords:GetText() == "45 · 58",
		"coordinates read out of C_Map (got " .. tostring(MMm.pill.coords:GetText()) .. ")")
	check(MMm.pill.clock:GetText() ~= "", "and the clock is in there too")

	-- Coordinates walk a digit at a time as you move and the clock ticks over
	-- every minute. Measured to their content, either one nudges the whole block
	-- sideways while you are standing still looking at it.
	do
		local before = MMm.pill:GetWidth()
		_G.__playerPos = { 0.07, 0.09 }        -- "7 . 9" - much narrower
		MMm:UpdateZone()
		check(MMm.pill:GetWidth() == before,
			"the block does not move when the coordinates change width")
		check(MMm.pill.coordW and MMm.pill.coordW > 0
			and MMm.pill.coordW < MMm.pill:GetWidth(),
			"and the fixed field is *measured* from the font rather than guessed"
			.. " - the guess was half again too wide and pushed the block off the"
			.. " side of the screen (" .. tostring(MMm.pill.coordW) .. ")")
		_G.__playerPos = { 0.45, 0.58 }
		MMm:UpdateZone()
	end
	check(not MMm.pill.dot:IsShown(), "no combat dot out of combat")

	-- tinted by zone type, the same colours the rest of the game uses
	_G.__pvpType = "contested"
	MMm:UpdateZone()
	local r = select(1, MMm.pill.zone:GetTextColor())
	check(math.abs(r - 1.0) < 0.01, "a contested zone is tinted")
	_G.__pvpType = nil

	-- an instance has a map but no position on it, which is a different nil
	-- from having no map at all - both have to mean "no coordinates"
	_G.__playerPos = nil
	MMm:UpdateZone()
	check(MMm.pill.coords:GetText() == "",
		"an instance drops the coordinates rather than showing nils")
	_G.__playerPos = { 0.45, 0.58 }
	_G.__uiMap = nil
	MMm:UpdateZone()
	check(MMm.pill.coords:GetText() == "", "and so does having no map at all")
	_G.__uiMap = 1413

	-- in combat the pill says so
	_G.__inCombat = true
	MMm:UpdateZone()
	check(MMm.pill.dot:IsShown() and MMm.pill.zone:GetText() == "In combat",
		"in a fight the pill swaps for a dot and 'In combat'")
	check(select(2, MMm.pill.zone:GetPoint(1)) == MMm.pill.dot,
		"and the label moves out of the dot's way - both were anchored 14 in from"
		.. " the same edge, so the dot was drawn on top of the first word")
	check(MMm.pill.clock:GetText() ~= "", "the clock stays either way")
	check(MMm.pill.coords:GetWidth() == 0,
		"and the empty coordinate field collapses - a fixed-width field with"
		.. " nothing in it still takes up its width in the anchor chain, which"
		.. " pushed the clock out past the end of the pill")
	_G.__inCombat = false
	MMm:UpdateZone()
	check(MMm.pill.zone:GetText() == "The Barrens", "and comes back afterwards")
end

print("== toolbox: a widget nobody has poked is still right ==")
do
	local TBm = A:GetModule("toolbox")
	TBm:SetDock("LEFT")

	-- THE GOLD WIDGET SAID "0s" while the bag window on the same screen said
	-- 3g 38s 13c.
	--
	-- GetMoney answers 0 at login, before the client has been told otherwise.
	-- Gold carried only PLAYER_MONEY, which fires when your money CHANGES - so
	-- the single read at enable wrote a zero and nothing looked again until you
	-- earned or spent something. Bag space and durability were right on that
	-- same screen because they carry PLAYER_ENTERING_WORLD and Gold did not.
	do
		local gold
		for _, p in ipairs(TBm.PROVIDERS) do if p.key == "Gold" then gold = p end end
		local hasLogin = false
		for _, e in ipairs(gold.events or {}) do
			if e == "PLAYER_ENTERING_WORLD" then hasLogin = true end
		end
		check(hasLogin,
			"Gold is swept at login like every other event-driven widget - an"
			.. " event that only fires on CHANGE cannot establish a first value")

		-- Every event-driven provider, not just the one that was reported. A
		-- widget whose only event is a change event has the same bug waiting.
		local missing = {}
		for _, p in ipairs(TBm.PROVIDERS) do
			if p.events then
				local ok = false
				for _, e in ipairs(p.events) do
					if e == "PLAYER_ENTERING_WORLD" then ok = true end
				end
				if not ok then missing[#missing + 1] = p.key end
			end
		end
		check(#missing == 0,
			"and so is every other one (" ..
			(#missing > 0 and table.concat(missing, ", ") or "all of them") .. ")")
	end

	-- ...and the general version: opening the drawer re-reads the lot, so a
	-- value that was not available at login is right by the time it is seen.
	do
		TBm:SetOpen(false, true)
		_G.__money = 0
		TBm:RefreshProviders("Gold")
		local zero = TBm._published.Gold.value

		-- The client finally knows, and says nothing about it.
		_G.__money = 33813
		check(TBm._published.Gold.value == zero,
			"a value that changed with no event still reads stale while shut")

		TBm:SetOpen(true, true)
		check(TBm._published.Gold.value ~= zero,
			"and opening the drawer re-reads it (was " .. tostring(zero)
			.. ", now " .. tostring(TBm._published.Gold.value) .. ")")
	end

	-- The two that cannot be event-driven answer on the FIRST tick after the
	-- drawer opens rather than a second later - and on the first open of a
	-- session, a second later is the difference between a number and nothing.
	do
		TBm:SetOpen(false, true)
		TBm:SetOpen(true, true)
		check(TBm._pollAccum ~= nil and TBm._pollAccum >= 1.0,
			"the poll is due immediately on opening rather than after a full"
			.. " period (got " .. tostring(TBm._pollAccum) .. ")")
	end

	TBm:SetOpen(false, true)

	-- THE DRAWER IS TRANSIENT: Escape shuts it, and so does a click anywhere
	-- else on the screen.
	--
	-- TWO FRAMES, because the drawer never hides - it SLIDES, travelling off
	-- the edge and staying shown the whole time. So neither of the usual
	-- mechanisms can be pointed at the panel itself.
	do
		TBm:SetOpen(true, true)
		local esc = TBm._escape
		check(esc ~= nil and esc.IsShown and esc:IsShown(),
			"with the drawer out there is a proxy frame up for Escape to close")

		-- IN UISpecialFrames BY NAME, which is how the client closes a window on
		-- Escape: it walks that list and HIDES what it finds shown. Given the
		-- panel it would stop the slide dead and leave the travel bookkeeping
		-- believing the drawer was still out.
		local listed = false
		for _, n in ipairs(_G.UISpecialFrames or {}) do
			if esc and n == esc:GetName() then listed = true end
		end
		check(listed, "and it is in UISpecialFrames, which is what Escape reads")
		check(TBm.panel and TBm.panel:IsShown(),
			"while the panel itself stays shown, because it travels rather than "
			.. "hiding")

		-- ESCAPE, as the client performs it.
		if esc then esc:Hide() end
		check(not TBm:IsOpen(), "hiding that proxy - which is Escape - shuts the "
			.. "drawer")

		-- A CLICK ANYWHERE ELSE. The catcher is under everything the drawer draws
		-- - the panel is at frame level 10 and the rail at 20 - so both stay
		-- clickable and everything outside them is not.
		TBm:SetOpen(true, true)
		local catch = TBm._catch
		check(catch and catch:GetPropagateMouseClicks(),
			"the catcher passes the click on to whatever is underneath - closing "
			.. "is a side effect of the click, not the whole of it")
		check(catch ~= nil and catch:IsShown() and catch:GetFrameLevel() == 0,
			"and a catcher across the screen, under the panel and the rail (level "
			.. tostring(catch and catch:GetFrameLevel()) .. ")")
		local onDown = catch and catch:GetScript("OnMouseDown")
		if onDown then onDown(catch) end
		check(not TBm:IsOpen(),
			"and clicking it puts the drawer away")
		check(catch and esc and not catch:IsShown() and not esc:IsShown(),
			"after which neither is left up eating clicks or answering Escape")
	end

end

print("== the copy box ==")
do
	A.db.profile.anchors = A.db.profile.anchors or {}
	A.db.profile.anchors.player = { point = "CENTER", relPoint = "CENTER",
		x = -180, y = -120 }

	-- CHAT CANNOT BE COPIED FROM IN THIS CLIENT. That is the whole reason the
	-- copy box exists, so a capture that only reaches chat has not reached
	-- anybody.
	local said = {}
	local chat = _G.DEFAULT_CHAT_FRAME
	local realAdd = chat.AddMessage
	chat.AddMessage = function(self, msg)
		said[#said + 1] = tostring(msg)
		return realAdd(self, msg)
	end
	SlashCmdList["AETHERUI"]("preset capture centre")
	chat.AddMessage = realAdd

	local box = _G.AetherUIErrorBox
	check(box ~= nil, "the copy box was opened")
	local text = box and box:GetText() or ""
	check(text:find("centre = {", 1, true) ~= nil
		and text:find("player", 1, true) ~= nil,
		"the whole table is in the box, which is the only thing in this client "
		.. "whose text can be selected")

	-- AND OUT TO THE DISK, WHICH IS THE ONLY ROUTE THAT WORKS.
	--
	-- Ctrl+A, Ctrl+C takes what the EditBox LAID OUT rather than the string it
	-- was handed: a capture that read correctly in the box, and counted
	-- correctly in chat at 1683 characters and 25 lines, arrived in Windows as
	-- thousands of lines. CopyToClipboard would have stepped over the box and
	-- is forbidden to addons - see the mock. What is left is the saved
	-- variables file, which is a text file that holds what it is given.
	local out = A.db.global.export and A.db.global.export.preset_centre
	check(out == text,
		"a capture is written to the saved variables byte for byte, which is the "
		.. "one way text leaves this client intact")

	-- NOTHING TRAILING. The symptom was the report followed by a screenful of
	-- empty lines, so what matters is that the last character of the export is
	-- the last character of the report.
	local pad = tostring(out or ""):match("%s*$") or ""
	check(pad:find("\n") == nil,
		"and not one blank line after it (" .. #pad .. " characters of trailing "
		.. "space)")

	-- THE BUTTON DOES THE SAME, for a panel dump or an error log that was not
	-- put there by a command.
	local dlg = box and box:GetParent() and box:GetParent():GetParent()
	check(dlg and dlg.copy ~= nil, "the copy box has an Export button")
	if dlg and dlg.copy then
		A.Errors:ShowText("one\ntwo\nthree")
		dlg.copy:GetScript("OnClick")(dlg.copy)
		check(A.db.global.export.last == "one\ntwo\nthree",
			"and its Export button writes whatever is on screen (" ..
			tostring(A.db.global.export.last) .. ")")
	end

	-- AND NOTHING GOES NEAR THE CLIPBOARD. CopyToClipboard is in this client -
	-- Blizzard's own console and Edit Mode both call it - and forbidden to
	-- addons, so an attempt is an error report in the player's face whether or
	-- not it is pcall'd. It shipped once and came straight back.
	local tried = false
	local realCopy = _G.CopyToClipboard
	_G.CopyToClipboard = function() tried = true end
	if dlg and dlg.copy then
		pcall(dlg.copy:GetScript("OnClick"), dlg.copy)
	end
	pcall(SlashCmdList["AETHERUI"], "preset capture centre")
	_G.CopyToClipboard = realCopy
	check(not tried,
		"and nothing on this path calls the forbidden clipboard function")

	-- AND IT SAYS HOW MUCH IT WAS GIVEN. A box showing one line of an
	-- eight-line report looks exactly like a report that had one line in it,
	-- and telling those apart from the outside took two builds.
	local counted = false
	for _, line in ipairs(said) do
		if line:find("copy box:", 1, true) then counted = true end
	end
	check(counted,
		"and it says how many characters and lines it was handed, so a short "
		.. "box can be told from a short report")

	A.db.profile.anchors.player = nil
end
print("== presets: three arrangements of the HUD ==")
do
	-- WHAT NO ARRANGEMENT NAMES, AND WHY.
	--
	-- Apply wipes the anchors and writes the preset's, so a mover that no
	-- preset names falls back on its coded default every time somebody tries
	-- an arrangement on. That is harmless for a default that is right
	-- anywhere and a bug for one that is not: the stance bar's used to be
	-- BOTTOMLEFT 24, 220, which is on top of the chat window in all three of
	-- them. Reported from the game against 0.31.0.
	--
	-- A NEW NAME ON THIS LIST IS A DECISION rather than an oversight, which is
	-- the whole point of writing them down. Anything else appearing here fails
	-- this and somebody has to say which of the two it is.
	do
		local UNNAMED = {
			-- Parks itself beside bar 1, computed from bar 1's real width, so it
			-- lands correctly in every arrangement without any of them naming
			-- it. Which is just as well: only some classes have a stance bar, so
			-- nobody capturing an arrangement has one on screen to place.
			barstance = true,
			-- Twenty-four in from the top right, and no arrangement moves it.
			minimap = true,
		}

		local named = {}
		for _, key in ipairs(A.Presets.order) do
			for name in pairs(A.Presets.list[key].anchors or {}) do
				named[name] = true
			end
		end

		local surprises = {}
		for name in pairs(A.Movers.registry) do
			if not named[name] and not UNNAMED[name] then
				surprises[#surprises + 1] = name
			end
		end
		table.sort(surprises)
		check(#surprises == 0,
			"every mover is either named by an arrangement or written down as one "
			.. "that is not (" .. (#surprises > 0 and
			table.concat(surprises, ", ") or "no surprises") .. ")")

		-- AND THE STANCE BAR'S OWN DEFAULT IS THE COMPUTED ONE. The list above
		-- excuses it on the grounds that it parks itself beside bar 1; this is
		-- the half that checks it actually does, so the excuse cannot outlive
		-- the reason for it.
		local stance
		for _, bar in ipairs(A:GetModule("actionbars").bars or {}) do
			if bar.id == "stance" then stance = bar end
		end
		local entry = A.Movers.registry.barstance
		check(stance ~= nil and stance.cfg.beside == "1"
			and entry and entry.default and entry.default.point == "BOTTOM",
			"the stance bar parks beside bar 1 rather than in the chat's corner ("
			.. tostring(entry and entry.default and entry.default.point) .. ")")
	end

	local P = A.Presets
	check(P ~= nil, "the presets loaded")

	-- PUT BACK AFTERWARDS. Applying an arrangement writes the profile scale
	-- and every anchor in it, and the checks after this one are laid out
	-- against the scale the suite started at.
	local wasScale = A.db.profile.scale
	check(#P.order == 3, "there are three of them (" .. #P.order .. ")")

	-- AND EVERY ONE OF THEM HAS COORDINATES IN IT.
	--
	-- These three shipped as empty tables for two builds while the layouts were
	-- being made by eye in the game, and an empty preset APPLIES CLEANLY: it
	-- wipes the anchors, moves nothing, and reads back as the arrangement you
	-- just chose. A first-run tour offering three cards that all do nothing is
	-- the worst possible version of this feature and it looks like it works.
	local anchors = A.db.profile.anchors
	for _, key in ipairs(P.order) do
		local preset = P.list[key]
		local named = 0
		for _ in pairs(preset and preset.anchors or {}) do named = named + 1 end
		check(named > 6,
			"\"" .. key .. "\" is a real arrangement rather than an empty table ("
			.. named .. " frames)")
		check((preset.scale or 0) > 0,
			"and the scale travels with it, because frames hugging the character "
			.. "want to be smaller than frames along the bottom of an ultrawide")
	end

	-- NO NAME IN THEM THAT IS NOT A FRAME. These tables are pasted in by hand
	-- from a capture, and a mistyped key is not an error - it is an entry that
	-- silently moves nothing. Bars past the first are exempt: they register
	-- only when they are switched on, and this profile has one.
	for _, key in ipairs(P.order) do
		local bad = {}
		for name in pairs(P.list[key].anchors) do
			if not A.Movers.registry[name] and not tostring(name):find("^bar%d$") then
				bad[#bad + 1] = name
			end
		end
		table.sort(bad)
		check(#bad == 0,
			"every frame \"" .. key .. "\" names is one this addon can move (" ..
			(#bad > 0 and table.concat(bad, ", ") or "all of them") .. ")")
	end

	-- AND NO TWO OF THEM ARE THE SAME LAYOUT. Three cards on the tour that
	-- differ only in their wording is a choice that is not one.
	for i = 1, #P.order do
		for j = i + 1, #P.order do
			local a, b = P.order[i], P.order[j]
			check(not P:Matches(P.list[a].anchors, P.list[b].anchors),
				"\"" .. a .. "\" and \"" .. b .. "\" are different arrangements")
		end
	end

	-- NOTHING CHOSEN YET reads as nothing chosen. Every shipped arrangement now
	-- has coordinates, so an untouched profile is none of them - and a tour
	-- that ticked one anyway would be telling a new player they had already
	-- picked.
	wipe(anchors)
	check(P:Current() == nil,
		"an untouched profile is none of them (" .. tostring(P:Current()) .. ")")

	-- APPLYING ONE WRITES IT AND TELLS THE FRAMES TO LOOK AGAIN. The movers put
	-- a frame back from the store on demand rather than watching it, so writing
	-- the table is only half of the job.
	local moved = 0
	local realRestore = A.Movers.RestoreAll
	A.Movers.RestoreAll = function(self)
		moved = moved + 1
		return realRestore(self)
	end

	-- EACH OF THE THREE, there and back. Reading the arrangement off the
	-- anchors rather than off a note somebody wrote down is the whole point:
	-- a stored answer goes stale the first time a frame is dragged.
	for _, key in ipairs(P.order) do
		check(P:Apply(key), "\"" .. key .. "\" applies")
		check(P:Current() == key,
			"and reads back as itself off the anchors (" ..
			tostring(P:Current()) .. ")")
		check(A.db.profile.scale == P.list[key].scale,
			"at its own scale (" .. tostring(A.db.profile.scale) .. ")")
	end
	check(moved == #P.order,
		"and every frame is told to look again each time (" .. moved .. ")")

	-- WIPED, NOT MERGED. What the last arrangement moved and this one does not
	-- mention is two layouts at once and belongs to neither.
	anchors.minimap = { point = "TOPRIGHT", relPoint = "TOPRIGHT", x = -9, y = -9 }
	P:Apply("centre")
	check(anchors.minimap == nil,
		"applying a preset takes away what the last one moved and this one does "
		.. "not mention")

	-- EXCEPT THE LOCK BUTTON, which is not a position in an arrangement at all.
	-- It is the button that hides the handles, parked wherever the player last
	-- shoved it out of the way; Movers keeps its spot in this same table under
	-- __lockButton precisely because it is NOT a mover entry. Wiping it puts
	-- that button back in the middle of the screen every time somebody tries a
	-- preset on.
	anchors.__lockButton = { point = "CENTER", relPoint = "CENTER", x = 2, y = 164 }
	P:Apply("bottom")
	check(anchors.__lockButton ~= nil and anchors.__lockButton.y == 164,
		"where the player parked the lock button survives a preset being applied "
		.. "over it")

	-- AND IT IS NEVER CAPTURED. Shipping it would send one player's idea of
	-- where that button goes to everybody - and would stop Current() 
	-- recognising its own arrangement the moment somebody dragged it.
	local lines, count = P:Capture("bottom")
	local text = table.concat(lines, "\n")
	check(text:find("__lockButton", 1, true) == nil,
		"and never goes into a capture")

	-- A LAYOUT CAN BE CAPTURED BACK OUT, which is how these three were made: by
	-- eye, in the game, at a real resolution. Guessing coordinates in a text
	-- editor gives a layout that is plausible in every dimension and right in
	-- none.
	check(type(lines) == "table" and #lines > 1,
		"a capture comes back as lines, one per row of the table (" ..
		tostring(type(lines)) .. ", " .. tostring(#lines) .. ")")
	check(count > 6 and text:find('%["player"%]') ~= nil,
		"naming every frame in it (" .. tostring(count) .. ")")
	check(text:find("	", 1, true) == nil,
		"and indented with spaces - a tab is not reliably carried through a "
		.. "chat frame and out through the clipboard, and this text exists to "
		.. "be pasted")
	check(text:find("scale", 1, true) ~= nil,
		"with the scale in it, because that is part of an arrangement")

	-- SORTED, so two captures of the same layout are the same text and a diff
	-- shows the line that really changed.
	local order = {}
	for name in text:gmatch('%["([%w_]+)"%]') do order[#order + 1] = name end
	local sorted = true
	for i = 2, #order do
		if order[i] < order[i - 1] then sorted = false end
	end
	check(#order > 1 and sorted,
		"and in a fixed order rather than whatever pairs() felt like (" ..
		#order .. " frames)")

	-- AND THE NUMBERS ARE FRACTIONS OF THE SCREEN, not pixels.
	--
	-- An arrangement made on a 3840x1600 monitor and shipped in pixels is an
	-- arrangement for that monitor. How many UI units UIParent measures
	-- depends on BOTH the aspect ratio and the player's UI Scale slider - the
	-- capture the shipped three came from reports 2885 x 1202, where 768-tall
	-- is what the default scale gives you - so neither axis can be assumed. A
	-- frame 596 units in from the left edge is a third of the way across one
	-- screen and nearly half way across another, and a "bottom corners"
	-- layout quietly becomes "bottom middle".
	do
		P.order[#P.order + 1] = "__probe"
		P.list.__probe = {
			label = "probe", blurb = "", scale = 0.71,
			anchors = {
				player = { point = "BOTTOMLEFT", relPoint = "BOTTOMLEFT",
					fx = 0.25, fy = 0.10 },
				target = { point = "CENTER", relPoint = "CENTER", fx = -0.20, fy = 0 },
			},
		}

		local wasW, wasH = UIParent:GetWidth(), UIParent:GetHeight()
		local function at(width)
			UIParent:SetSize(width, 768)
			P:Apply("__probe")
			return anchors.player.x, anchors.target.x, anchors.player.y
		end

		-- The two shapes that matter, in the units the client draws in.
		local wideX, wideC, wideY = at(1843)
		local narrowX, narrowC, narrowY = at(1365)

		check(wideX > narrowX and math.abs(narrowX / wideX - 1365 / 1843) < 0.01,
			"a frame placed a quarter of the way across stays a quarter of the way "
			.. "across on a narrower screen (" .. string.format("%.0f then %.0f",
			wideX, narrowX) .. ")")

		-- BOTH DIRECTIONS FROM CENTRE. A negative offset that grew instead of
		-- shrinking would put the left-hand frame off the left edge, which is the
		-- one failure of this that is not merely untidy.
		check(wideC < 0 and narrowC < 0 and narrowC > wideC,
			"and one placed left of centre moves in rather than out (" ..
			string.format("%.0f then %.0f", wideC, narrowC) .. ")")

		-- AND THE OTHER AXIS ON ITS OWN TERMS. Both screens here are the same
		-- height, so nothing should move vertically - but that is a property of
		-- these two screens, not of the client. UIParent's height follows the
		-- player's UI Scale slider as well as the display, which is why `fy` is
		-- a fraction rather than carried across untouched.
		check(wideY == narrowY,
			"and nothing moves vertically between two screens of the same height "
			.. "(" .. wideY .. ", " .. narrowY .. ")")

		local _, _, shortY = at(1365)
		UIParent:SetSize(1365, 384)
		P:Apply("__probe")
		check(anchors.player.y < shortY,
			"and a shorter screen moves it proportionally too, because UIParent's "
			.. "height follows the UI Scale slider and is not a constant (" ..
			anchors.player.y .. " against " .. shortY .. ")")

		-- AND THE ARRANGEMENT STILL READS BACK AS ITSELF once resolved. Comparing
		-- a preset's fractions against the units the movers wrote makes every
		-- preset answer "not this one" on every display.
		check(P:Current() == "__probe",
			"and it is still recognised as the arrangement on screen (" ..
			tostring(P:Current()) .. ")")

		-- A CAPTURE COMES BACK IN FRACTIONS, which is what makes the next one
		-- portable. A capture in units is a capture of one monitor.
		local text = table.concat((P:Capture("__probe")), "\n")
		check(text:find("fx = ", 1, true) ~= nil and text:find("x = %-?%d+,") == nil,
			"and a capture writes fractions rather than the units it read")
		check(text:find("captured on a", 1, true) ~= nil,
			"saying what size screen it was made on, because whether a layout still "
			.. "composes at 16:9 is a question the numbers cannot answer")

		UIParent:SetSize(wasW, wasH)
		P.list.__probe = nil
		P.order[#P.order] = nil
	end

	-- AND A PRESET OWNS THE ACTION BARS, on and off both.
	--
	-- An arrangement that places bar 5 on a profile where bar 5 is switched off
	-- places nothing, and a layout designed around six bars has a hole in it
	-- with two. So a preset records which of the six numbered bars are on and
	-- sets them exactly - a bar it does not use is switched OFF, because
	-- leaving one on where the last arrangement put it is two layouts at once.
	do
		local AB = A:GetModule("actionbars")
		local was = {}
		for _, id in ipairs({ "1", "2", "3", "4", "5", "6" }) do
			was[id] = AB:BarConfig(id).enabled
		end

		P.order[#P.order + 1] = "__bars"
		P.list.__bars = {
			label = "bars", blurb = "", scale = 0.71,
			bars = { ["1"] = true, ["2"] = true, ["3"] = false,
				["4"] = false, ["5"] = true, ["6"] = false },
			anchors = {
				player = { point = "CENTER", relPoint = "CENTER", fx = 0, fy = 0 },
			},
		}

		-- Switched the other way round to start with, so both directions are
		-- actually exercised rather than one of them happening to be right.
		AB:SetBarEnabled("1", false)
		AB:SetBarEnabled("5", false)
		AB:SetBarEnabled("3", true)

		P:Apply("__bars")
		check(AB:BarConfig("1").enabled and AB:BarConfig("5").enabled,
			"applying an arrangement switches on the bars it uses")
		check(not AB:BarConfig("3").enabled,
			"and switches OFF the ones it does not - a bar left on where the last "
			.. "arrangement put it is two layouts at once")

		-- AND IT IS PART OF THE QUESTION "which arrangement is this". One that
		-- answered "yes, this is the one you have" with three of its bars missing
		-- would be telling the player something plainly untrue.
		check(P:Current() == "__bars",
			"the arrangement reads back as itself with its bars set (" ..
			tostring(P:Current()) .. ")")
		AB:SetBarEnabled("6", true)
		check(P:Current() ~= "__bars",
			"and stops being itself the moment a bar it does not want is switched "
			.. "on (" .. tostring(P:Current()) .. ")")

		-- REBUILT ONCE, not once per bar. SetBarEnabled is the per-bar door and
		-- calls OnConfigChanged itself, so six of them is six teardowns of every
		-- button on the screen for one click.
		local rebuilds = 0
		local realChanged = AB.OnConfigChanged
		AB.OnConfigChanged = function(self)
			rebuilds = rebuilds + 1
			return realChanged(self)
		end
		-- Three bars away from the preset, then one. If the dock were torn
		-- down per bar the first would cost three times the second; the same
		-- number both ways is the whole claim. Counted rather than asserted
		-- as a fixed figure, because Reconfigure rebuilds at the end of an
		-- Apply too and that is not the thing being measured.
		AB:SetBarEnabled("1", false)
		AB:SetBarEnabled("5", false)
		AB:SetBarEnabled("3", true)
		rebuilds = 0
		P:Apply("__bars")
		local three = rebuilds

		AB:SetBarEnabled("3", true)
		rebuilds = 0
		P:Apply("__bars")
		local one = rebuilds
		AB.OnConfigChanged = realChanged
		check(three == one,
			"and three bars changing costs the same rebuild as one - the dock is "
			.. "not torn down once per bar (" .. three .. ", " .. one .. ")")

		-- THE SIX NUMBERED BARS AND NOTHING ELSE. Stance, pet, taxi and the extra
		-- action button are not layout choices - the game gives you one or it does
		-- not, by class and by circumstance - and a preset captured by a mage that
		-- switched off a druid's stance bar would be reaching well past where
		-- things go.
		local stance = AB:BarConfig("stance")
		if stance then
			stance.enabled = true
			P.list.__bars.bars.stance = false
			P:Apply("__bars")
			check(stance.enabled,
				"a preset cannot switch off the stance bar even when it says to")
			P.list.__bars.bars.stance = nil
		end

		-- AND A CAPTURE RECORDS THEM, which is what makes the next arrangement
		-- reproducible at all.
		local text = table.concat((P:Capture("__bars")), "\n")
		check(text:find("bars = {", 1, true) ~= nil
			and text:find('%["5"%] = true') ~= nil
			and text:find('%["3"%] = false') ~= nil,
			"a capture writes which bars are on AND which are off, because a preset "
			.. "that only names what it wants cannot switch anything off")

		for _, id in ipairs({ "1", "2", "3", "4", "5", "6" }) do
			AB:SetBarEnabled(id, was[id])
		end
		P.list.__bars = nil
		P.order[#P.order] = nil
	end

	A.Movers.RestoreAll = realRestore
	wipe(anchors)
	A.db.profile.scale = wasScale
	A:Reconfigure()
end
print("== zen: it eases out rather than snapping ==")
do
	local Z = A:GetModule("zen")
	local cfg = A.Config:Module("zen")
	local f = Z.frame

	-- ZEN ENDING WANTS A SHAPE OF ITS OWN. It used to borrow the HUD's
	-- fade-in - 0.30 - and step PROPORTIONALLY, fourteen per cent of whatever
	-- was left every frame. An exponential decay is front-loaded: half of it
	-- is gone in five frames and the rest trails away under the eye, which
	-- reads as a snap with a tail rather than as something ending.
	-- Through the module's own door, which is what registers the ticker that
	-- drives the fade - the fade function itself is a file local.
	Z:SetActive(false)
	f:SetAlpha(1)
	Z._out = nil

	-- A TENTH OF THE WAY IN it has barely moved, because smoothstep is slow
	-- at both ends. The old curve was a fifth of the way gone by here.
	tick((cfg.easeOut or 0.8) * 0.1)
	check(f:GetAlpha() > 0.9,
		"a tenth of the way out, zen has barely started to go (" ..
		string.format("%.2f", f:GetAlpha()) .. ")")

	-- HALFWAY THROUGH IT IS HALFWAY OUT, which is what a fixed time buys: the
	-- fade is the same length however far it has to travel.
	tick((cfg.easeOut or 0.8) * 0.4)
	check(math.abs(f:GetAlpha() - 0.5) < 0.08,
		"halfway through the time, halfway out (" ..
		string.format("%.2f", f:GetAlpha()) .. ")")

	-- AND IT IS STILL GOING AT HALF A SECOND, which is the whole of the
	-- report: the old one was done in a fifth of that.
	check((cfg.easeOut or 0.8) >= 0.5,
		"and the whole of it takes at least half a second (" ..
		tostring(cfg.easeOut) .. "s)")

	-- THEN IT ARRIVES. The rest of the time and a frame to park.
	tick((cfg.easeOut or 0.8) * 0.6)
	tick(0.05)
	check(f:GetAlpha() <= 0.001,
		"and it gets all the way there (" ..
		string.format("%.3f", f:GetAlpha()) .. ")")

	-- FROM WHEREVER IT HAD GOT TO. The player can move at any point in the
	-- fade IN, so the fade out starts from that alpha and still takes its own
	-- time rather than being quicker because there was less to do.
	Z:SetActive(false)
	f:SetAlpha(0.5)
	Z._out = nil
	tick((cfg.easeOut or 0.8) * 0.5)
	check(math.abs(f:GetAlpha() - 0.25) < 0.05,
		"starting from half, it is a quarter at the halfway mark - the same "
		.. "length of fade, not a quicker one (" ..
		string.format("%.2f", f:GetAlpha()) .. ")")

	-- AND THE TRACK FADES WITH IT. This used to ramp only for somebody whose
	-- own music volume was UNDER zen's floor; anybody above it got no ramp at
	-- all - the track started at full and StopMusic cut it dead.
	do
		local seen = {}
		local realSet = _G.SetCVar
		_G.SetCVar = function(name, value)
			if name == "Sound_MusicVolume" then seen[#seen + 1] = tonumber(value) end
			return realSet(name, value)
		end

		-- Well above zen's floor, which is the case that had no ramp.
		realSet("Sound_MusicVolume", "1.0")
		Z._audio = nil
		Z:SetAudio(1)
		Z:SetAudio(0.5)
		Z:SetAudio(0.1)
		_G.SetCVar = realSet

		-- COUNTED, not indexed: Borrow writes only when the value CHANGES, so at
		-- the top of the fade - where the track plays at the player's own level -
		-- there is nothing to write and no call to see.
		local falling = #seen > 0
		for i = 2, #seen do
			if seen[i] >= seen[i - 1] then falling = false end
		end
		local low = seen[#seen]
		check(falling and #seen >= 2,
			"the track's volume comes down with the readout rather than playing "
			.. "at full until StopMusic cuts it (" ..
			table.concat(seen, " to ") .. ")")
		check(low and low < 0.2,
			"and is all but silent by the time the readout is (" ..
			tostring(low) .. ")")

		-- AND THE PLAYER'S OWN SETTING COMES BACK, whatever we left it at.
		Z:RestoreAudio()
		check(tonumber(GetCVar("Sound_MusicVolume")) == 1.0,
			"and the player's own volume is handed back untouched (" ..
			tostring(GetCVar("Sound_MusicVolume")) .. ")")
	end

	Z.want = 0
	f:SetAlpha(0)
	Z._out = nil
end
print("== toolbox: the drawer breathes with everything else ==")
do
	local TBm = A:GetModule("toolbox")

	-- The HUD dims when you stand still and the rail did not, which is the one
	-- place a missing fader registration is actually visible: it sits on screen
	-- at all times, next to things that ARE dimming.
	check(A.Fader.watched[TBm.rail] ~= nil,
		"the rail is registered with the fader")
	check(A.Fader.watched[TBm.panel] ~= nil, "and so is the drawer")

	-- ...but NOT the scrim. Its alpha is written on every Layout from the slide
	-- position, so a second writer fights it once per frame while the drawer
	-- moves. One owner per alpha, the same rule the aura trays follow.
	check(A.Fader.watched[TBm.scrim] == nil,
		"the scrim is NOT - its alpha is written by Layout from the slide"
		.. " position, and two writers on one alpha is a fight per frame")

	-- Every fadeable thing this module draws, so a new surface added later has
	-- to make the same decision rather than default to being forgotten.
	do
		local unregistered = {}
		for _, part in ipairs({ { "rail", TBm.rail }, { "panel", TBm.panel } }) do
			if part[2] and not A.Fader.watched[part[2]] then
				unregistered[#unregistered + 1] = part[1]
			end
		end
		check(#unregistered == 0,
			"nothing the module draws is left out of the breathing ("
			.. (#unregistered > 0 and table.concat(unregistered, ", ")
				or "all registered") .. ")")
	end
end

print("== toolbox: nothing on the rail sits on anything else ==")
do
	local TBm = A:GetModule("toolbox")
	local LN = A.Launchers
	TBm:SetDock("LEFT")

	-- The envelope anchors above the gear, and the gear anchors to the FAR END
	-- of the rail. So anything anchored from that end which is missing from the
	-- rail's length does not get clipped - it walks backwards into the list and
	-- lands on the last pin, where it reads as simply not being drawn. That is
	-- what happened the day the envelope was added.
	--
	-- Measured off the frames rather than by restating the formula: a test that
	-- recomputes the same sum agrees with the bug.
	for i = 1, 3 do
		_G.__makeLDB("RailFit" .. i, "launcher")
		local b = _G.__makeDBIcon("RailFit" .. i)
	end
	LN:Scan()
	TBm:ClaimPins()
	for i = 1, 3 do TBm:SetPinned("RailFit" .. i, true) end
	TBm:LayoutRail()

	local rail = TBm.rail
	local railLen = rail:GetHeight()

	-- Distance from the rail's TOP down to the top edge of each fixed control.
	-- The gear is anchored BOTTOM-to-BOTTOM with a pad; the envelope sits a pad
	-- above it.
	local gearTop = railLen - select(5, rail.gear:GetPoint(1)) - rail.gear:GetHeight()
	local mailTop = gearTop - select(5, rail.mail:GetPoint(1)) - rail.mail:GetHeight()

	check(rail.mail:GetHeight() > 0 and rail.gear:GetHeight() > 0,
		"the envelope and the gear are both real sizes")

	-- The rail's OWN controls are bare glyphs - no chip, no rim - because they
	-- are part of the rail. A launcher looks different because it IS different:
	-- somebody else's art in its own circle. That only works if the bare glyphs
	-- carry comparable weight; at 18 against 26 they read as an afterthought
	-- rather than as a deliberately quieter treatment.
	--
	-- A ratio rather than the number itself. The number is a taste decision and
	-- restating it here would test nothing; "not visibly smaller than the
	-- launchers, and still inside its slot" is the rule that was broken.
	for _, part in ipairs({ { "envelope", rail.mail }, { "gear", rail.gear } }) do
		local g = part[2].glyph
		local slot = part[2]:GetHeight()
		check(g:GetHeight() <= slot,
			part[1] .. "'s glyph fits its slot (" .. tostring(g:GetHeight())
			.. " in " .. tostring(slot) .. ")")
		check(g:GetHeight() >= slot * 0.8,
			"and fills enough of it to sit beside a launcher rather than under"
			.. " it (" .. tostring(g:GetHeight()) .. " of " .. tostring(slot)
			.. ", want >= " .. tostring(slot * 0.8) .. ")")
	end

	-- The lowest pinned button, from its own anchor.
	local lowest = 0
	for _, key in ipairs(TBm:Pinned()) do
		local e = LN.byKey[key]
		local b = e and e.button
		if b and LN:OwnerOf(e) == TBm then
			local bottom = -select(5, b:GetPoint(1)) + b:GetHeight()
			if bottom > lowest then lowest = bottom end
		end
	end
	check(lowest > 0, "and there are pins on the rail to collide with ("
		.. tostring(lowest) .. ")")

	check(lowest <= mailTop,
		"the last pin ends ABOVE the envelope rather than underneath it - a"
		.. " rail one icon too short does not clip what is anchored from its far"
		.. " end, it stacks it on the list (pin ends " .. tostring(lowest)
		.. ", envelope starts " .. tostring(mailTop) .. ")")
	check(mailTop + rail.mail:GetHeight() <= gearTop,
		"and the envelope ends above the gear (" .. tostring(mailTop) .. " + "
		.. tostring(rail.mail:GetHeight()) .. " vs " .. tostring(gearTop) .. ")")

	-- Adding a pin must lengthen the rail, or the next one collides instead.
	local before = rail:GetHeight()
	_G.__makeLDB("RailFit4", "launcher"); _G.__makeDBIcon("RailFit4")
	LN:Scan(); TBm:ClaimPins(); TBm:SetPinned("RailFit4", true); TBm:LayoutRail()
	check(rail:GetHeight() > before,
		"and one more pin makes the rail longer rather than tighter ("
		.. tostring(before) .. " -> " .. tostring(rail:GetHeight()) .. ")")

	for i = 1, 4 do TBm:SetPinned("RailFit" .. i, false) end
	TBm:LayoutRail()
end

print("== toolbox: mail, and what the client will not tell us ==")
do
	local TBm = A:GetModule("toolbox")
	-- The REAL geometry, not the mock's 1024x768 default. That default clamps
	-- the drawer to about 506 tall, which is short enough that the panel is
	-- already cutting both lists to nothing - and an EMPTY mail section is the
	-- one thing that gives way at that extreme. Testing the section's ordinary
	-- behaviour on a panel that is busy dropping it reads as the section being
	-- broken.
	local mailOldW, mailOldH = UIParent:GetWidth(), UIParent:GetHeight()
	local mailOldScale = A.db.profile.scale
	UIParent:SetSize(1365, 768)
	A.db.profile.scale = 0.71
	TBm:SetDock("LEFT")
	TBm:SetOpen(true, true)

	-- The minimap used to carry this and no longer does. Nothing in Minimap.lua
	-- should mention mail, and the module must not have kept a frame for it - a
	-- leftover pill at alpha 0 is invisible until somebody re-enables it.
	check(MMm.mail == nil,
		"the minimap has no mail pill any more - it lives on the toolbox rail,"
		.. " which is reachable with the drawer shut")

	_G.__mail, _G.__mailFrom = false, nil
	fire("UPDATE_PENDING_MAIL")

	local mailBtn = TBm.rail.mail
	check(mailBtn ~= nil, "the rail carries an envelope")
	check(select(2, mailBtn:GetPoint(1)) == TBm.rail.gear,
		"anchored off the gear, so the two travel together whichever edge the"
		.. " drawer is docked to")

	local empty = select(2, A.Media:Icon("mail"))
	local full  = select(2, A.Media:Icon("mailfull"))
	check(empty ~= full, "empty and full are different cells of the sheet")
	check(select(1, mailBtn.glyph:GetTexCoord()) == empty,
		"no mail draws the outline envelope")
	-- The section is there with an EMPTY box too. It used to vanish, on the
	-- reasoning that a section reporting nothing is furniture; what that missed
	-- is that a section which comes and goes is one you go looking for and
	-- cannot find, and that the panel below it shifting every time the postman
	-- calls is worse than one quiet line.
	check(TBm.content.mailHead ~= nil and TBm.content.mailHead:IsShown(),
		"the drawer still shows a MAIL section with an empty box")
	check(TBm.content.mail[1]:IsShown()
		and TBm.content.mail[1].name:GetText() == "No unread mail",
		"carrying one quiet line saying so (got "
		.. tostring(TBm.content.mail[1] and TBm.content.mail[1].name:GetText())
		.. ")")
	check(not TBm.content.mail[2]:IsShown(),
		"and only the one - an empty box is not three empty rows")
	check(TBm.content.mailHint:GetText() == "",
		"with nothing in the hint, or the section says the same thing twice at"
		.. " both ends of one line")

	-- Mail arrives.
	_G.__mail, _G.__mailFrom = true, { "Thrall", "Sylvanas" }
	fire("UPDATE_PENDING_MAIL")

	check(select(1, mailBtn.glyph:GetTexCoord()) == full,
		"mail swaps the glyph for the filled one")
	local r, g, b = mailBtn.glyph:GetVertexColor()
	local ac = A.Palette.c.accent
	check(ac and math.abs(r - ac[1]) < 0.01 and math.abs(g - ac[2]) < 0.01
		and math.abs(b - ac[3]) < 0.01,
		"in the accent, which is what makes it readable at 26px without a badge")

	check(TBm.content.mailHead:IsShown(), "and the MAIL section appears")
	check(TBm.content.mail[1]:IsShown() and TBm.content.mail[1].name:GetText() == "Thrall",
		"listing the senders the client named")
	check(TBm.content.mail[2].name:GetText() == "Sylvanas", "in order")
	check(not TBm.content.mail[3]:IsShown(),
		"and no row for a sender that does not exist")
	check(TBm.content.mailHint:GetText() == "2 new",
		"the count is EXACT below the client's cap (got "
		.. tostring(TBm.content.mailHint:GetText()) .. ")")

	-- At the cap the number stops being a total.
	_G.__mailFrom = { "Thrall", "Sylvanas", "Jaina" }
	fire("UPDATE_PENDING_MAIL")
	check(TBm.content.mailHint:GetText() == "3+ new",
		"at three it reads 3+, because three is the CLIENT's cap and not"
		.. " necessarily the total - GetLatestThreeSenders is named for what it"
		.. " does, and there is no call that counts (got "
		.. tostring(TBm.content.mailHint:GetText()) .. ")")
	check(TBm.content.mail[3]:IsShown(), "and the third row is used")

	-- Mail with nobody's name on it. Real, and not a broken mock: this is what
	-- auction house and NPC mail looks like from outside a mailbox.
	_G.__mailFrom = nil
	fire("UPDATE_PENDING_MAIL")
	check(TBm.content.mailHead:IsShown(),
		"mail with no sender still shows the section - HasNewMail is true and"
		.. " saying nothing would be a lie")
	-- ONE row, and it is not a sender. This state was reading as a bug because
	-- the section said "you have mail" and stopped; the answer is something the
	-- player can actually do, so it says that instead.
	check(TBm.content.mail[1]:IsShown()
		and TBm.content.mail[1].chip.label:GetText() == "?",
		"one row saying it does not know, rather than a heading over nothing")
	check(not TBm.content.mail[2]:IsShown(), "and only the one")
	check(TBm.content.mailHint:GetText() == HAVE_MAIL,
		"and the client's own wording instead of a number (got "
		.. tostring(TBm.content.mailHint:GetText()) .. ")")

	-- An empty section is the ONE thing that gives way, and only at an extreme
	-- nobody sees. "Mail is never cut" is right about mail you HAVE - a list
	-- that drops the sender you were looking for to make room for a toggle has
	-- its priorities backwards - and wrong about a line reading "No unread
	-- mail", which is the least informative thing on the panel.
	--
	-- Swept rather than asserted at one size, because a rule that quietly fired
	-- on an ordinary screen would look exactly like the section not having been
	-- made permanent at all.
	do
		local wasW, wasH = UIParent:GetWidth(), UIParent:GetHeight()
		local wasScale = A.db.profile.scale
		_G.__mail, _G.__mailFrom = false, nil

		local kept = {}
		for _, case in ipairs({ { 1365, 768, 0.71 }, { 1365, 768, 1.0 },
			{ 1024, 768, 0.71 }, { 2560, 1440, 0.71 }, { 1365, 768, 0.85 } }) do
			UIParent:SetSize(case[1], case[2])
			A.db.profile.scale = case[3]
			TBm:SetDock("LEFT")
			fire("UPDATE_PENDING_MAIL")
			if not TBm.content.mailHead:IsShown() then
				kept[#kept + 1] = string.format("%dx%d@%.2f", case[1], case[2], case[3])
			end
		end
		check(#kept == 0, "an empty MAIL section survives every ordinary screen"
			.. (#kept > 0 and (" - dropped at " .. table.concat(kept, ", ")) or ""))

		-- ...and it really can give way, or the rule is dead code and the panel
		-- overflows on the one screen that needed it.
		UIParent:SetSize(1000, 600)
		A.db.profile.scale = 1.0
		TBm:SetDock("LEFT")
		fire("UPDATE_PENDING_MAIL")
		check(not TBm.content.mailHead:IsShown(),
			"and gives way on a 506px panel, where keeping it would not leave"
			.. " room for a single row of settings tiles")
		check(TBm._contentHeight <= TBm.panel:GetHeight() + 0.5,
			"which is what keeps that panel fitting ("
			.. string.format("%.0f of %.0f", TBm._contentHeight,
				TBm.panel:GetHeight()) .. ")")

		UIParent:SetSize(wasW, wasH)
		A.db.profile.scale = wasScale
		TBm:SetDock("LEFT")
		fire("UPDATE_PENDING_MAIL")
	end

	-- The section takes part in the ONE top-down accumulator rather than being
	-- drawn over whatever was already there.
	--
	-- Measured on the accumulator itself, not on the settings tiles: the panel
	-- in here is 505 units tall and every tile is already cut, so a tile's
	-- position is stale rather than informative. The first version of this
	-- check read one anyway and passed a stale -430 against itself.
	do
		_G.__mail, _G.__mailFrom = false, nil
		fire("UPDATE_PENDING_MAIL")
		local dry = TBm._contentHeight

		_G.__mail, _G.__mailFrom = true, { "Thrall", "Sylvanas", "Jaina" }
		fire("UPDATE_PENDING_MAIL")
		local wet = TBm._contentHeight

		check(dry and wet and wet > dry,
			"the content grows by the mail block rather than the section landing"
			.. " on top of what was already laid out (" .. tostring(dry)
			.. " -> " .. tostring(wet) .. ")")

		-- Mail with nobody's name on it costs ONE row, the same as an empty box:
		-- both are a line that is not a sender, and the section reserves height
		-- for rows it draws rather than for senders it has.
		--
		-- This used to compare against the section being ABSENT, which is no
		-- longer a state - it is always there now. What is left to check is that
		-- the two one-row cases really are one row, and that three senders costs
		-- more than one line rather than the header simply being drawn over
		-- whatever was under it.
		_G.__mail, _G.__mailFrom = true, nil
		fire("UPDATE_PENDING_MAIL")
		local nameless = TBm._contentHeight
		check(TBm._mailRowCount == 1,
			"a nameless mail section is one row - the 'we cannot say who from'"
			.. " line (got " .. tostring(TBm._mailRowCount) .. ")")
		check(nameless == dry,
			"and costs exactly what the empty box did, because both are one line"
			.. " (" .. tostring(dry) .. " vs " .. tostring(nameless) .. ")")
		check(wet > nameless,
			"while three named senders costs two rows more, so the accumulator"
			.. " really is being advanced by what is drawn rather than the"
			.. " header being laid over what was under it (" .. tostring(nameless)
			.. " -> " .. tostring(wet) .. ")")

		_G.__mail, _G.__mailFrom = true, { "Thrall", "Sylvanas", "Jaina" }
		fire("UPDATE_PENDING_MAIL")

		local mailY = select(5, TBm.content.mailHead:GetPoint(1))
		local newsY = select(5, TBm.content.news:GetPoint(1))
		check(mailY < newsY,
			"and it lands BELOW the fixed sections above it rather than at the"
			.. " top of the panel")
	end

	-- On a TALL screen, where the settings tiles actually fit.
	--
	-- At the harness's default 1024x768 the panel clamps to 505 units and every
	-- tile is cut, so nothing below the mail section is laid out and the
	-- arithmetic that gives it room is never run. The first version of this
	-- test read a cut tile's stale position and passed a value against itself.
	do
		local oldW, oldH = UIParent:GetWidth(), UIParent:GetHeight()
		UIParent:SetSize(1365, 1600)

		_G.__mail, _G.__mailFrom = false, nil
		TBm:SetDock("LEFT")           -- re-measures the panel against the screen
		fire("UPDATE_PENDING_MAIL")
		check(TBm.content.tiles[1]:IsShown(),
			"the settings tiles fit on a tall screen (cut " ..
			tostring(TBm._tilesCut) .. ")")
		local dryTile = select(5, TBm.content.tiles[1]:GetPoint(1))

		_G.__mail, _G.__mailFrom = true, { "Thrall", "Sylvanas", "Jaina" }
		fire("UPDATE_PENDING_MAIL")
		local wetTile = select(5, TBm.content.tiles[1]:GetPoint(1))
		check(wetTile < dryTile,
			"and they move DOWN when the mail section appears above them rather"
			.. " than being drawn under it - y is negative here, so lower is"
			.. " smaller (" .. tostring(dryTile) .. " -> " .. tostring(wetTile)
			.. ")")

		UIParent:SetSize(oldW, oldH)
		TBm:SetDock("LEFT")
	end

	-- WHAT THE MAILBOX KNOWS, which is everything the notification does not.
	do
		_G.__mail, _G.__mailFrom = true, nil
		fire("UPDATE_PENDING_MAIL")
		check(TBm.content.mail[1].chip.label:GetText() == "?",
			"before a mailbox visit the section admits it does not know")

		-- Standing at a mailbox: the inbox arrives and MAIL_INBOX_UPDATE fires.
		_G.__inbox = {
			{ sender = "Thrall",   subject = "Warchief business", read = false },
			{ sender = "Thrall",   subject = "Again",             read = false },
			{ sender = "Vol'jin",  subject = "Darkspear",         read = false },
			{ sender = "Cairne",   subject = "Read already",      read = true  },
			{ sender = "Sylvanas", subject = "Forsaken",          read = false },
		}
		fire("MAIL_INBOX_UPDATE")

		local _, senders, unread, stale = TBm:MailState()
		check(unread == 4,
			"a TRUE unread count, which exists at a mailbox and nowhere else -"
			.. " the read one is not in it (got " .. tostring(unread) .. ")")
		check(#senders == 3,
			"senders deduplicated - two from Thrall is one name in a list of"
			.. " who has written to you (got " .. #senders .. ")")
		check(senders[1] == "Thrall" and senders[2] == "Vol'jin",
			"in the order the box holds them")
		check(stale == true,
			"and flagged as REMEMBERED rather than current - mail read on"
			.. " another character is not in this and the section has to say so")

		check(TBm.content.mailHint:GetText() == "4 unread \194\183 last visit",
			"the hint says which claim it is making (got "
			.. tostring(TBm.content.mailHint:GetText()) .. ")")
		check(TBm.content.mail[1].chip.label:GetText() == "T",
			"and the rows are senders again rather than a question mark")

		-- Walk away, come back later. The record outlives the mailbox, which is
		-- the entire point of writing it down.
		_G.__inbox = nil
		fire("UPDATE_PENDING_MAIL")
		check(select(3, TBm:MailState()) == 4,
			"and it survives leaving the mailbox (got "
			.. tostring(select(3, TBm:MailState())) .. ")")

		-- The client's own answer WINS when it has one: it is about now, and
		-- the record is about the last time anybody looked.
		_G.__mailFrom = { "Jaina" }
		fire("UPDATE_PENDING_MAIL")
		local _, live, count, wasStale = TBm:MailState()
		check(live[1] == "Jaina" and #live == 1 and not wasStale and not count,
			"mail that arrives NOW is named by the client and takes precedence"
			.. " over the record")

		-- Reading it all clears the record rather than leaving a number that
		-- describes mail that is no longer there.
		_G.__mailFrom = nil
		_G.__inbox = { { sender = "Thrall", read = true } }
		fire("MAIL_INBOX_UPDATE")
		check(select(3, TBm:MailState()) == nil,
			"an empty box clears the record - a remembered count that outlives"
			.. " its mail is worse than no count")

		-- ...and the record is REMOVED, not left holding zeroes. MailState
		-- reads the same either way, so this is the only place the difference
		-- shows: an empty table in saved variables is a thing that gets read
		-- back next session and reasoned about by somebody who did not write it.
		check(TBm:MailRecord() == nil,
			"and nothing is left behind in saved variables")
	end

	-- ...and on a screen where it does NOT all fit, which is the only place the
	-- arithmetic that hands out the room can be observed at all.
	--
	-- 1365x620 was found by sweeping 560 to 800 in tens: below 590 the tiles are
	-- cut whatever the mail is doing and above 640 they fit either way, so both
	-- ends are blind to whether the mail block was subtracted from what is left.
	-- In the band between, three named senders cost exactly two settings tiles
	-- against an empty box, and a version that forgot to subtract them lays
	-- those tiles out past the bottom of the panel where nobody can reach them.
	--
	-- It was 780 when the section came and went with the mail and the whole
	-- block was the difference. Now the section is always there, so the
	-- difference is only the two extra ROWS - a smaller step, which moves the
	-- band.
	do
		local oldW, oldH = UIParent:GetWidth(), UIParent:GetHeight()
		UIParent:SetSize(1365, 620)

		-- A long addon list too, so the OTHER list that gives way is not empty.
		for i = 1, 10 do _G.__makeLDB("RoomTest" .. i, "launcher") end
		A.Launchers:Scan()
		TBm:RefreshAddons()

		TBm:SetDock("LEFT")
		_G.__mail, _G.__mailFrom = false, nil
		fire("UPDATE_PENDING_MAIL")
		local panelH = TBm.panel:GetHeight()
		check(TBm._contentHeight <= panelH + 1,
			"with no mail, everything laid out fits the panel ("
			.. string.format("%.0f of %.0f", TBm._contentHeight, panelH) .. ")")

		_G.__mail, _G.__mailFrom = true, { "Thrall", "Sylvanas", "Jaina" }
		fire("UPDATE_PENDING_MAIL")
		check(TBm._contentHeight <= panelH + 1,
			"and WITH mail it still does - the lists below give way by exactly"
			.. " the mail block rather than being laid out past the bottom edge"
			.. " ("  .. string.format("%.0f of %.0f", TBm._contentHeight, panelH)
			.. ")")
		check(TBm._tilesCut > 0,
			"which cost something real here rather than fitting anyway - the"
			.. " check above is blind on a screen with room to spare")

		-- The sender's own initial, not a third copy of the envelope the
		-- heading already carries. The only thing that varied down that column
		-- was the name, which is what made it read as flat as it was.
		check(TBm.content.mail[1].chip ~= nil
			and TBm.content.mail[1].chip.label:GetText() == "T",
			"each row carries its sender's initial (got "
			.. tostring(TBm.content.mail[1].chip
				and TBm.content.mail[1].chip.label:GetText()) .. ")")
		check(TBm.content.mail[2].chip.label:GetText() == "S",
			"and they differ down the column, which is the job of a list")

		UIParent:SetSize(oldW, oldH)
		TBm:SetDock("LEFT")
	end

	-- A name that starts with a multi-byte character. Lua has no unicode, so
	-- who:sub(1,1) takes one BYTE and half a character draws as a box.
	do
		_G.__mail, _G.__mailFrom = true, { "\195\150lrun", "Thrall" }
		fire("UPDATE_PENDING_MAIL")
		check(TBm.content.mail[1].chip.label:GetText() == "\195\150",
			"a name beginning with a multi-byte character gives a whole one -"
			.. " sub(1,1) would hand the font half a codepoint (got "
			.. tostring(TBm.content.mail[1].chip.label:GetText()) .. ")")
	end

	-- Reading it at a mailbox clears the flag without UPDATE_PENDING_MAIL
	-- necessarily firing, which is why MAIL_INBOX_UPDATE is registered too.
	_G.__mail, _G.__mailFrom = false, nil
	fire("MAIL_INBOX_UPDATE")
	check(select(1, mailBtn.glyph:GetTexCoord()) == empty,
		"emptying the box at a mailbox puts the envelope back - an indicator"
		.. " still glowing after you have read your mail is the version of this"
		.. " anybody would notice")

	UIParent:SetSize(mailOldW, mailOldH)
	A.db.profile.scale = mailOldScale
	TBm:SetDock("LEFT")
	TBm:SetOpen(false, true)
end

print("== launchers: what counts as somebody's button ==")
do
	local LN = A.Launchers

	-- These assertions used to live in "the button drawer". The drawer is gone -
	-- the Toolbox rail is the only surface now - but what it knew about OTHER
	-- ADDONS' buttons is the hardest-won thing in this codebase and none of it
	-- was about minimaps. It moved with the code.

	local dbi = _G.__makeDBIcon("BigWigs")
	local own = CreateFrame("Button", "SomeAddonMinimapButton", Minimap)
	own:SetScript("OnDragStart", function() end)
	local pin = CreateFrame("Frame", "QuestieFramePin42", Minimap)
	local bliz = CreateFrame("Button", "MiniMapTracking", Minimap)
	_G.__secureNames["MiniMapTracking"] = true

	LN:Scan()

	check(LN.seen[dbi] ~= nil, "a LibDBIcon button is found")
	check(LN.seen[own] ~= nil, "and so is an addon that rolled its own")
	check(LN.seen[pin] == nil,
		"but a map pin is not - Questie and HandyNotes put THOUSANDS of children"
		.. " on the minimap and none of them is a button")
	check(LN.seen[bliz] == nil,
		"and neither is Blizzard's own furniture, which issecurevariable sorts"
		.. " from the arrivals with no name list to keep up to date")

	-- Pacified, so the library stops yanking them back onto the ring.
	local e = LN.seen[dbi]
	LN:Claim(e, {})
	check(dbi.__locked,
		"a LibDBIcon button is Locked THROUGH the library, which is the"
		.. " supported way and survives a Refresh - its drag handler recomputes"
		.. " an angle from the cursor and re-anchors every frame otherwise")
	local eo = LN.seen[own]
	LN:Claim(eo, {})
	check(own:GetScript("OnDragStart") == nil,
		"and a hand-rolled one has its drag scripts taken off instead")

	-- Skinned by the SERVICE, so every surface gets the same treatment. It used
	-- to happen inside the drawer's Collect, which would have left the rail
	-- showing whatever bevel each addon shipped.
	check(dbi.__aetherSkinned and dbi.__aetherRing ~= nil,
		"skinning happens in Core/Launchers.lua rather than in whichever module"
		.. " claimed the button - it is a fact about somebody else's frame, not"
		.. " about a minimap")
	check(dbi.border == nil or not dbi.border:IsShown(),
		"with whatever bevel it arrived with switched off")

	do
		-- The rule is "keep the icon, hide every other texture", not "match the
		-- bevel against a list of known files" - an addon's border is whatever
		-- that addon shipped, and there is no list that covers that.
		local kept, hidden = 0, 0
		for _, r in ipairs({ dbi.icon, dbi.border, dbi.background }) do
			if r and r.IsShown then
				if r:IsShown() then kept = kept + 1 else hidden = hidden + 1 end
			end
		end
		check(kept == 1 and hidden == 2,
			"the icon is kept and everything else is hidden (" .. kept
			.. " kept, " .. hidden .. " hidden)")
	end

	-- SOMEBODY ELSE'S SPELLING OF "MINIMAP". There is no agreed one - Blizzard's
	-- own interface says MiniMapTracking and MinimapBorder in the same breath,
	-- and addons follow whichever they read first. SmartBuff's button is
	-- SmartBuff_MiniMapButton, which every pattern here was written past, so it
	-- stayed on the ring beside the map while the same addon's broker launcher
	-- sat in the drawer and the player had the button twice.
	do
		_G.__makeLDB("SmartBuff", "launcher")
		local loose = CreateFrame("Button", "SmartBuff_MiniMapButton", Minimap)
		LN:Scan()

		local entry = LN.seen[loose]
		check(entry ~= nil,
			"a button that spells it MiniMapButton is collected too - the word"
			.. " has two spellings and both are somebody's button")
		check(entry == LN.byKey["SmartBuff"],
			"and joins the launcher its own addon registered rather than arriving"
			.. " as a second entry: Broker_SmartBuff registers SmartBuff and"
			.. " SmartBuff builds SmartBuff_MiniMapButton, and the same addon"
			.. " twice in the drawer is the bug the player was reporting")
		check(entry.button == loose and not entry.owned,
			"with the addon's real button in place of our proxy, because that is"
			.. " the one carrying its own click behaviour")
	end

	-- AND WHEN THE NAME DOES NOT SAY. Enchantrix registers a launcher called
	-- "Enchantrix" and builds a button called EnxMiniMapIcon, and no amount of
	-- stripping "minimap icon" off one end of that gets to the other. The client
	-- knows, though: issecurevariable's second return is the addon that tainted
	-- the global, which is the only thing in the game that can say so.
	do
		_G.__makeLDB("Enchantrix", "launcher")
		local enx = CreateFrame("Button", "EnxMiniMapIcon", Minimap)
		_G.__taintedBy["EnxMiniMapIcon"] = "Enchantrix"
		LN:Scan()

		local entry = LN.seen[enx]
		check(entry == LN.byKey["Enchantrix"],
			"a button whose name shares nothing with its addon still joins that"
			.. " addon's launcher, because the client is asked who made it rather"
			.. " than the name being read for clues")
		check(LN.byKey["EnxMiniMapIcon"] == nil,
			"and no second entry is left under the button's own name")
	end

	-- Arrivals after the sweep. There is no event for "a child was added to the
	-- minimap", so the registry callback is the only thing that catches an addon
	-- finishing its load late.
	local late = _G.__makeDBIcon("Later")
	check(LN.seen[late] ~= nil,
		"a button created after the sweep arrives through LibDBIcon's own"
		.. " creation callback")

	-- Somebody else's "hide until you hover the minimap".
	--
	-- This is the one that looked most like our bug and was least like it. The
	-- flag is per button, but the library's handlers walk the WHOLE registry, so
	-- hovering anything anywhere faded every adopted button back out a second
	-- later. On a minimap that preference is reasonable; on a rail in a drawer
	-- it is just a missing icon, and it followed the button when we adopted it.
	do
		local ldbi = LibStub("LibDBIcon-1.0", true) or _G.__ldbi
		local fade = _G.__makeDBIcon("Fader")
		_G.__makeLDB("Fader", "launcher")
		ldbi:ShowOnEnter("Fader", true)
		check(fade.showOnMouseover and fade:GetAlpha() == 0,
			"an addon really can hide a registered button until mouseover")

		-- Note the ORDER this test happens in, because it is the order the game
		-- happens in: __makeDBIcon fires LibDBIcon_IconCreated, we adopt the
		-- button in that callback, and only THEN does the other addon's handler
		-- for the same callback set the flag. Prepare has already run and will
		-- early-out for the rest of the session, so a fix that only lives there
		-- leaves the button faded until the next full layout.
		LN:Scan()
		local fe = LN.seen[fade]
		check(fe and fe._prepared,
			"the button was adopted BEFORE the flag was set - both addons are"
			.. " listening to the same LibDBIcon callback")

		LN:Claim(fe, {})

		check(not fade.showOnMouseover,
			"adopting a button clears it - alpha alone would lose to the next"
			.. " fadeOut, and the flag is the only thing gating that call")
		check(fade:GetAlpha() == 1, "and the button is visible now")

		ldbi:__mouseLeftEverything()
		check(fade:GetAlpha() == 1,
			"so the cursor leaving something else entirely no longer takes it"
			.. " away - the library fades every button it knows about, not the"
			.. " one being hovered")

		LN:Release(fe)
	end

	LN:Release(LN.seen[dbi]); LN:Release(LN.seen[own])
end

print("== launchers: the two mechanisms, merged ==")
do
	local LN = A.Launchers
	local ldb = LibStub("LibDataBroker-1.1")

	-- The guard test. Everything else in this block is only meaningful if the
	-- library really is the one with the metatable, so prove it first: a real
	-- dataobj keeps nothing on the table itself.
	do
		local obj = _G.__makeLDB("ProbeAddon", "launcher")
		local n = 0
		for _ in pairs(obj) do n = n + 1 end
		check(n == 0 and obj.type == "launcher",
			"a real LDB dataobj is EMPTY to pairs() while indexing fine - every"
			.. " field lives in the library's attributestorage behind __index."
			.. " A mock that stored them on the table would be the one shape in"
			.. " which walking one works, and this whole block would prove"
			.. " nothing (" .. n .. " keys, type=" .. tostring(obj.type) .. ")")
	end

	-- A launcher whose addon never made a minimap button. The OLD collector
	-- could not see this at all: it only ever walked what was already parented
	-- onto the map.
	local clicked
	_G.__makeLDB("LauncherOnly", "launcher", {
		label = "Launcher Only",
		OnClick = function(_, btn) clicked = btn or true end,
	})
	LN:Scan()
	A:GetModule("toolbox"):ClaimPins()

	local e = LN.byKey["LauncherOnly"]
	check(e ~= nil, "an LDB launcher with no minimap button is found at all -"
		.. " which the minimap-only collector could never do")
	check(e and e.button and e.owned,
		"and is given a proxy frame of OUR making, so every consumer has exactly"
		.. " one job: place entry.button")
	A:GetModule("toolbox"):ClaimPins()
	check(e and A.Launchers:OwnerOf(e) ~= nil,
		"and the rail adopts it alongside the real buttons")

	-- Read at call time, never captured. An addon is entitled to swap its own
	-- handler after login.
	LN:Click(e, "LeftButton")
	check(clicked == "LeftButton", "clicking it runs the object's OnClick")
	e.obj.OnClick = function() clicked = "replaced" end
	LN:Click(e, "LeftButton")
	check(clicked == "replaced",
		"and a handler swapped AFTER registration is the one that runs - Titan"
		.. " re-reads it at click time for this reason, and a captured reference"
		.. " would go stale silently rather than erroring")

	-- Both mechanisms, one addon. LibDBIcon keys lib.objects by the LDB name,
	-- which is the whole basis of the dedupe.
	local before = LN:Count()
	_G.__makeLDB("BothWays", "launcher", { label = "Both Ways" })
	local btn = _G.__makeDBIcon("BothWays")
	LN:Scan()
	A:GetModule("toolbox"):ClaimPins()
	check(LN:Count() == before + 1,
		"an addon offering a launcher AND a LibDBIcon button is ONE entry, not"
		.. " two - they share a name, which is what LibDBIcon keys on ("
		.. before .. " -> " .. LN:Count() .. ")")
	local both = LN.byKey["BothWays"]
	check(both and both.button == btn and not both.owned,
		"and the real button wins over the proxy - it is the one carrying that"
		.. " addon's own click behaviour")

	-- A data source is a readout, not something to click.
	_G.__makeLDB("SomeReadout", "data source", { text = "1234" })
	LN:Scan()
	A:GetModule("toolbox"):ClaimPins()
	check(LN.byKey["SomeReadout"] == nil,
		"a `data source` is NOT an addon entry - it is a number to display, and"
		.. " the Toolbox puts those to a different use entirely")

	-- One owner. Two surfaces positioning the same borrowed frame is a bug that
	-- only appears for whoever has both switched on.
	-- One owner. The Toolbox rail holds every entry now, so the case worth
	-- pinning down is a second surface trying to take one from it.
	local holder = LN:OwnerOf(both)
	local other = {}
	check(holder ~= nil, "something owns it")
	check(not LN:Claim(both, other),
		"a second surface cannot claim an entry the first one holds")
	check(LN:OwnerOf(both) == holder, "the first owner keeps it")
	check(LN:Claim(both, other, true),
		"and a FORCED claim takes it, which is what a pin is")

	-- Releasing PARKS it rather than leaving it stranded wherever its last owner
	-- put it. That is the fix for an unpinned icon sitting on top of the gear:
	-- unowned used to mean laid out by nobody, so it persisted where it was.
	LN:Release(both, other)
	check(both._parked, "and releasing parks it")
	A:GetModule("toolbox"):ClaimPins()
end

print("== reading surfaces reach solid ==")
do
	local cfg = A.db.profile.glass
	local was = cfg.readOpacity

	-- 100% MUST MEAN 100%. The fill art's own alpha carries the top-light
	-- falloff as well as the shape - 0.89 in the middle, less at the foot - and
	-- a vertex tint MULTIPLIES that, so no colour however solid could push a
	-- reading surface past 89%. The setting said 100 and the panel did not.
	cfg.readOpacity = 1
	check(math.abs((A.Palette:ReadingFill()[4] or 0) - 1) < 0.001,
		"at 100% the reading colour is solid ("
		.. string.format("%.2f", A.Palette:ReadingFill()[4] or 0) .. ")")

	local QLm = A:GetModule("questlog")
	QLm.win:SetFillColor(A.Palette:ReadingFill())
	check(QLm.win._backing ~= nil, "and the panel gets a plate behind it")
	local plate = QLm.win._backing[1] and { QLm.win._backing[1]:GetVertexColor() }
	check(plate and math.abs(plate[4] - 1) < 0.001,
		"opaque, because at a request of 1 nothing else can close the gap ("
		.. string.format("%.2f", plate and plate[4] or 0) .. ")")

	-- BUILT ON DEMAND, and only when it is needed. The HUD's surfaces are meant
	-- to be seen through, so nine textures a panel for a case that never arises
	-- is nine textures a panel wasted.
	cfg.readOpacity = 0
	QLm.win:SetFillColor(A.Palette:ReadingFill())
	check(QLm.win._backing[1]:IsShown() == false,
		"and it goes away again when the surface is meant to be seen through")

	local plain = A.Glass.CreatePanel(UIParent, { corner = 12 })
	plain:SetFillColor(A.Palette.c.glass)
	check(plain._backing == nil, "a surface nobody asked to be solid never grows one")

	-- THE TOOLBOX IS A READING SURFACE TOO. It slides out OVER whatever is
	-- behind it carrying five columns of small text.
	cfg.readOpacity = 0.6
	A:Restyle()
	local want = A.Palette:ReadingFill()[4]
	check(math.abs((A:GetModule("toolbox").panel._fillColor[4] or 0) - want) < 0.001,
		"the Toolbox drawer is at the readable opacity too")

	cfg.readOpacity = was
	A:Restyle()
end

print("== xp hairline ==")
local XPm = A:GetModule("xpbar")
check(XPm and XPm.enabled and XPm.frame, "xpbar module built")
check(XPm.frame:IsShown(), "xp bar visible below max level")
-- WHAT IS LEFT, not what is done. "86% Level 15" is two facts about where you
-- have been; the line counts DOWN to the level you are working towards, which is
-- what anybody watching it is actually watching.
check(XPm.frame.text:GetText() == "14% to Level 16",
	"the readout counts down to the next level ("
	.. tostring(XPm.frame.text:GetText()) .. ")")

-- ROUNDED UP, so it never reads 0% while there is still experience to earn -
-- the one number a countdown must not show early.
do
	local wasXP = _G.__xp
	_G.__xp = _G.__xpMax - 1
	XPm.Update()
	check(XPm.frame.text:GetText():find("^1%% to"),
		"one point short of a level still reads 1%, never 0 ("
		.. tostring(XPm.frame.text:GetText()) .. ")")
	_G.__xp = 0
	XPm.Update()
	check(XPm.frame.text:GetText():find("^100%% to"),
		"and a fresh level reads 100% (" .. tostring(XPm.frame.text:GetText()) .. ")")
