	_G.__cursor = { link = "|Hitem:5|h[Small Brown Pouch]|h" }
	Bg.confirm:Hide()
	tiles[2]:GetScript("OnClick")(tiles[2], "LeftButton")
	check(not Bg.confirm:IsShown(),
		"a slot you have just BOUGHT does not offer to sell you the next one")
