		"and again on Midnight, from the one shared helper")

	local c = A.Palette.c
	check(c.itemQuality and c.itemQuality[4] and c.itemQuality[4].glow,
		"epic carries a glow as well as a rim - that is what makes a purple"
		.. " findable at a glance in a grid of eighty")
	check(c.itemQuality[1].glow == nil,
		"and common does not, which is not the same as a transparent one")
	Bg:Hide()
end

print("== bags: every quality band exists in both skins ==")
do
	-- The vocabulary check below only compares TOP-LEVEL keys, so a nested band
	-- missing from one skin is a nil index in the middle of a redraw and would
	-- sail straight past it.
	local missing = {}
	for _, name in ipairs(SKINS) do
		local q6 = A.Palette.skins[name].itemQuality
		for q = 0, 5 do
			if not q6[q] then missing[#missing + 1] = name .. " " .. q
			elseif not q6[q].edge then missing[#missing + 1] = name .. " " .. q .. ".edge" end
		end
	end
	check(#missing == 0, "all six bands, all four skins, each with a rim ("
		.. table.concat(missing, ", ") .. ")")
end

-- ---------------------------------------------------------------------------
-- skins
--
-- Daylight became a genuinely LIGHT skin on 2026-08-11 - white panels, dark ink
-- - which inverts the assumption every other module was written under. These
-- checks exist because the failure mode is not an error: it is a colour that is
-- technically applied and visually absent.
-- ---------------------------------------------------------------------------

print("== nameplates: the mock is as unkind as the client ==")
do
	-- The module out of the way: this block is about what the CLIENT does, and
	-- the module's whole job is to countermand some of it.
	A:SetModuleEnabled("nameplates", false)

	local seen = { created = 0, added = 0, removed = 0 }
	local spy = {}
	A:RegisterEvent(spy, "NAME_PLATE_CREATED", function() seen.created = seen.created + 1 end)
	A:RegisterEvent(spy, "NAME_PLATE_UNIT_ADDED", function() seen.added = seen.added + 1 end)
	A:RegisterEvent(spy, "NAME_PLATE_UNIT_REMOVED", function() seen.removed = seen.removed + 1 end)

	local base = __spawnPlate("nameplate1", {
		exists = true, name = "Kolkar Marauder", level = 18, reaction = 2,
		hp = 900, hpMax = 1000,
	})
	check(C_NamePlate.GetNamePlateForUnit("nameplate1") == base,
		"a plate that is up is findable by its token")
	check(seen.created == 1 and seen.added == 1, "created once, added once")

	base.__leftBehind = "kodo"
	__despawnPlate("nameplate1")
	check(seen.removed == 1 and C_NamePlate.GetNamePlateForUnit("nameplate1") == nil,
		"and unfindable once it is taken away")
	check(UnitExists("nameplate1") == false,
		"with the token no longer a unit at all - a module still holding it gets"
		.. " nothing back, which is exactly what the client says")

	local again = __spawnPlate("nameplate1", {
		exists = true, name = "Wandering Kodo", level = 15, reaction = 4,
	})
	check(again == base,
		"the next mob is handed the SAME frame - plates are recycled, not minted,"
		.. " so anything left on one turns up on somebody else")
	check(again.__leftBehind == "kodo", "with the last tenant's things still on it")
	check(seen.created == 1, "and no second CREATED for a frame that already exists")

	again.UnitFrame:Hide()
	__despawnPlate("nameplate1")
	local third = __spawnPlate("nameplate1", {
		exists = true, name = "Gazrog", level = 20, reaction = 2,
	})
	check(third.UnitFrame:IsShown(),
		"Blizzard's own plate is pooled separately and comes back SHOWN on the"
		.. " next unit - hiding it once when the plate is created is not enough,"
		.. " and is why skinned nameplates ship with theirs flickering underneath")

	__spawnForbiddenPlate("nameplate99")
	check(C_NamePlate.GetNamePlateForUnit("nameplate99") == nil,
		"a forbidden plate is invisible to the getters, the way it is to any"
		.. " insecure caller - handling that event pair earns you a nil and a taint")

	__despawnPlate("nameplate1")
	A:UnregisterAllEvents(spy)
	check(__plateCount() == 0, "and nothing is left standing behind us")

	A:SetModuleEnabled("nameplates", true)
end

local NPm = A:GetModule("nameplates")

print("== nameplates: one capsule, and Blizzard's put away ==")
do
	local base = __spawnPlate("nameplate1", {
		exists = true, name = "Kolkar Marauder", level = 18, reaction = 2,
		hp = 700, hpMax = 1000, classification = "normal",
	})
	local f = NPm.plateFor(base)
	check(f ~= nil and f:IsShown(), "a hostile gets a plate")
	check(f:GetParent() == base,
		"parented to the client's base rather than replacing it - the base is the"
		.. " click target and it is protected, so it is left entirely alone")
	check(not base.UnitFrame:IsShown(), "and Blizzard's own is put away")

	check(f.name:GetText() == "Kolkar Marauder", "the name is on it")
	check(f.badge.label:GetText() == "18", "with the level in the badge")
	local fill = select(1, A.Palette:DifficultyColors(18))
	check(f.badge.disc.__color and f.badge.disc.__color[1] == fill[1],
		"tinted by difficulty, off the same band the quest log uses")
	check(f.bar:IsShown() and f.bar:GetValue() == 700, "and the health bar reads")

	-- The recycling trap, end to end.
	__despawnPlate("nameplate1")
	check(f.name:GetText() == "", "a plate that goes away is CLEARED, not just hidden")

	local again = __spawnPlate("nameplate1", {
		exists = true, name = "Wandering Kodo", level = 15, reaction = 4,
		hp = 500, hpMax = 500,
	})
	check(again == base and NPm.plateFor(again) == f,
		"the recycled base keeps the same plate rather than growing a second one")
	check(f.name:GetText() == "Wandering Kodo", "rebound to whoever turned up on it")
	check(not base.UnitFrame:IsShown(),
		"and Blizzard's plate is hidden AGAIN - it is pooled per unit and arrives"
		.. " shown, so hiding it once when the base was created would have left it"
		.. " flickering under every mob after the first")

	check(not f.bar:IsShown(),
		"a neutral out of combat carries a name and nothing else - a yellow plate"
		.. " is 'not my problem yet' and a health bar on one says nothing")
	check(select(1, f.name:GetPoint()) == "LEFT",
		"and with nothing under it the name CENTRES rather than staying anchored"
		.. " for a bar that is not there, hanging high over a band of empty glass")

	_G.__units.nameplate1.inCombat = true
	fire("UNIT_FLAGS", "nameplate1")
	check(f.bar:IsShown(), "until it is in a fight, and then it does")
	check(select(1, f.name:GetPoint()) == "BOTTOMLEFT",
		"and the name moves up to make room for it")

	-- Drawn at profile.scale like every other module. Left at 1 the capsule is
	-- enormous against a HUD at 0.71, which is what the first pass shipped as.
	--
	-- On a plate BUILT after the change, not one that has since been through
	-- OnConfigChanged: those are two different code paths and only one of them
	-- runs when a mob walks up.
	A.db.profile.scale = 0.9
	local other = __spawnPlate("nameplate2", {
		exists = true, name = "Gazrog", level = 20, reaction = 2, hp = 10, hpMax = 10,
	})
	local of = NPm.plateFor(other)
	local mult = A.Config:Module("nameplates").scale
	check(math.abs(of:GetScale() - 0.9 * mult * 0.8) < 0.001,
		"a plate is BUILT at profile.scale, times the module's own multiplier,"
		.. " times the .8 an off-target plate wears")

	A.db.profile.scale = 0.71
	NPm:OnConfigChanged()
	check(math.abs(of:GetScale() - 0.71 * mult * 0.8) < 0.001,
		"and follows profile.scale when it moves, without losing the .8")
	__despawnPlate("nameplate2")

	-- A token with nothing behind it. The client does this when a unit arrives
	-- and is gone inside the same frame, and it is what a forbidden plate would
	-- look like if one ever reached this handler. It has to be a no-op, not a
	-- capsule hung on a frame we invented to have something to hang it on.
	local function built()
		local n = 0
		for _ in pairs(NPm.plates) do n = n + 1 end
		return n
	end
	local before = built()
	fire("NAME_PLATE_UNIT_ADDED", "nameplate77")
	check(built() == before,
		"a token with no plate behind it builds nothing and raises nothing")

	__despawnPlate("nameplate1")
end

print("== nameplates: the target is the one you can read ==")
do
	local mob = { exists = true, name = "Kolkar Marauder", level = 18, reaction = 2,
		hp = 900, hpMax = 1000 }
	local other = { exists = true, name = "Kolkar Wrangler", level = 17, reaction = 2,
		hp = 400, hpMax = 1000 }

	local baseA = __spawnPlate("nameplate1", mob)
	local baseB = __spawnPlate("nameplate2", other)
	local a, b = NPm.plateFor(baseA), NPm.plateFor(baseB)
	local full = A.db.profile.scale * A.Config:Module("nameplates").scale

	check(math.abs(a:GetScale() - full * 0.8) < 0.001
		and math.abs(a:GetAlpha() - 0.62) < 0.001,
		"with nothing targeted every plate is off-target: .8 and .62")

	-- UnitIsUnit answers on identity, so this is the same mob, not a copy.
	_G.__units.target = mob
	fire("PLAYER_TARGET_CHANGED")

	check(NPm.step(nil, 1) == false, "the fade finishes")
	check(math.abs(a:GetScale() - full) < 0.001 and math.abs(a:GetAlpha() - 1) < 0.001,
		"the target comes up to full size and full strength")
	check(a._rimColor ~= nil, "and takes a rim glow in its reaction")
	check(math.abs(a._rimColor[4] - 0.28) < 0.001, "at the deck's .28")
	check(a._edgeColor[4] > b._edgeColor[4],
		"with a stronger rim than the plates around it")

	check(math.abs(b:GetScale() - full * 0.8) < 0.001 and b._rimColor == nil,
		"while everything else stays small and unglowed")

	-- The transition, rather than a snap.
	_G.__units.target = other
	fire("PLAYER_TARGET_CHANGED")
	NPm.step(nil, 0.05)
	local mid = a:GetScale()
	check(mid < full and mid > full * 0.8,
		"a target change is a 150ms move, not a jump - part way through, the plate"
		.. " losing focus is between the two sizes")
	check(NPm.step(nil, 1) == false and math.abs(a:GetScale() - full * 0.8) < 0.001,
		"and it arrives")
	check(b._rimColor ~= nil and a._rimColor == nil,
		"with the glow having moved across, not been left on both")

	-- Losing the target entirely.
	_G.__units.target = nil
	fire("PLAYER_TARGET_CHANGED")
	NPm.step(nil, 1)
	check(b._rimColor == nil, "dropping the target takes the glow with it")

	-- A plate that arrives already targeted does not swell into place.
	_G.__units.target = mob
	__despawnPlate("nameplate1")
	local again = __spawnPlate("nameplate1", mob)
	local a2 = NPm.plateFor(again)
	check(math.abs(a2:GetScale() - full) < 0.001,
		"and a plate that walks up ALREADY targeted arrives at full size rather"
		.. " than growing into it - it was correct before you could see it")

	-- The client will not always answer UnitIsUnit about a plate the instant it
	-- arrives, and a whole batch of them comes back at once when zen gives the
	-- nameplate CVars back. Answer "not the target" then and nothing asks again
	-- until the player clicks something.
	do
		local late = { exists = true, name = "Late Kodo", level = 15, reaction = 2,
			hp = 5, hpMax = 5 }
		_G.__units.target = late
		local baseL = __spawnPlate("nameplate3", late)
		local lf = NPm.plateFor(baseL)

		-- ...as if the token had not resolved yet when the plate came up.
		lf._want, lf._at = 0, 0
		NPm.applyEmphasis(lf)
		check(math.abs(lf:GetScale() - full * 0.8) < 0.001, "dim to begin with")

		tick(0)
		check(math.abs(lf:GetScale() - full) < 0.001,
			"asked again on the next frame, so your own target does not sit at"
			.. " off-target dim until you click something")

		_G.__units.target = nil
		__despawnPlate("nameplate3")
	end

	-- Released part way through a fade, which is the ordinary case: you switch
	-- target and the mob you left dies before the transition finishes.
	_G.__units.target = nil
	fire("PLAYER_TARGET_CHANGED")
	NPm.step(nil, 0.05)
	__despawnPlate("nameplate1")
	__despawnPlate("nameplate2")
	check(next(NPm.moving) == nil,
		"a plate released mid-fade is taken out of the moving set, not left"
		.. " animating a frame nobody can see")
	check(a._rimColor == nil and b._rimColor == nil,
		"and keeps no glow for whoever gets it next")
end

print("== nameplates: your debuffs, under your target, and nobody else's ==")
do
	-- Four debuffs, one of them cast by somebody else. Hung on `target` and the
	-- nameplate token pointed at the same unit, because that is the shape in
	-- game: the plate and the target frame are two tokens for one mob and both
	-- have to read the same list.
	local savedAuras = _G.__auras.target
	_G.__auras.target = { HARMFUL = {
		{ "Chilled",   135834, 0, "Magic", 8,  nil, "player", true },
		{ "Bleeding",  132090, 2, nil,     12, nil, "boss1",  false },
		{ "Frostbite", 135842, 0, "Magic", 5,  nil, "player", true },
		{ "Rend",      132155, 0, nil,     10, nil, "player", true },
	} }

	local mob = { exists = true, name = "Kolkar Marauder", level = 18,
		reaction = 2, hp = 900, hpMax = 1000 }
	_G.__units.target = mob

	local baseA = __spawnPlate("nameplate1", mob)
	-- B carries debuffs of mine TOO. Without that, "off-target shows none" is
	-- true whether the module checks focus or simply has nothing to draw.
	local savedFocus = _G.__auras.focus
	_G.__auras.focus = { HARMFUL = {
		{ "Serpent Sting", 132204, 0, nil, 15, nil, "player", true },
	} }
	local mate = { exists = true, name = "Kolkar Wrangler", level = 17,
		reaction = 2, hp = 400, hpMax = 1000 }
	_G.__units.focus = mate
	local baseB = __spawnPlate("nameplate2", mate)
	local a, b = NPm.plateFor(baseA), NPm.plateFor(baseB)

	fire("PLAYER_TARGET_CHANGED")
	NPm.step(nil, 1)

	check(a._chipCount == 3,
		"the target shows the three debuffs that are MINE - the fourth on it was"
		.. " cast by somebody else and is not my business")
	check((b._chipCount or 0) == 0,
		"and an off-target plate carries none at all even though I have a debuff"
		.. " on that one too - which is most of what makes the target's readable")

	local first = a.chips[1].text:GetText()
	check(first:find("Chilled") ~= nil and first:find("s") ~= nil,
		"a chip is the name and what is left of it (" .. tostring(first) .. ")")
	check(a.chips[1].icon:IsShown(), "with its icon")

	-- Overflow.
	local saved = _G.__auras.target.HARMFUL
	local many = {}
	for i = 1, 7 do
		many[i] = { "Debuff " .. i, 135834, 0, "Magic", 10, nil, "player", true }
	end
	_G.__auras.target.HARMFUL = many
	fire("UNIT_AURA", "nameplate1")
	check(a._chipCount == 5,
		"seven of mine is four chips and a fifth carrying the remainder")
	check(a.chips[5].text:GetText() == "+3", "which says how many are not shown")
	check(not a.chips[5].icon:IsShown(), "and has no icon of its own")

	_G.__auras.target.HARMFUL = saved
	fire("UNIT_AURA", "nameplate1")
	check(a._chipCount == 3, "and it comes back down again")
	check(not a.chips[4]:IsShown() and not a.chips[5]:IsShown(),
		"with the chips it no longer needs HIDDEN rather than left on screen"
		.. " showing a debuff that has expired")

	-- Focus moving takes them with it.
	_G.__units.target = nil
	fire("PLAYER_TARGET_CHANGED")
	check((a._chipCount or 0) == 0, "dropping the target takes its chips away")

	_G.__auras.target = savedAuras
	_G.__auras.focus = savedFocus
	_G.__units.focus = nil
	__despawnPlate("nameplate1")
	__despawnPlate("nameplate2")
end

print("== nameplates: the cast capsule ==")
do
	local mob = { exists = true, name = "Kolkar Wrangler", level = 17, reaction = 2,
		hp = 900, hpMax = 1000 }
	local base = __spawnPlate("nameplate1", mob)
	local f = NPm.plateFor(base)

	check(f.cast == nil or not f.cast:IsShown(), "nothing casting, no capsule")

	-- Through the LIBRARY's registry, which is the only route that exists for a
	-- nameplate unit: the native UNIT_SPELLCAST_* events fire for the player
	-- alone on this client.
	_G.__ccCasts.nameplate1 = { name = "Lightning Bolt", icon = 136048,
		channel = false, start = time * 1000, finish = (time + 3) * 1000 }
	_G.__ccFire("UNIT_SPELLCAST_START", "nameplate1")

	check(f.cast and f.cast:IsShown(), "the library's callback opens the capsule")
	check(f.cast.text:GetText() == "Lightning Bolt", "with the spell named")
	check(f.cast.bar:GetValue() < 0.1, "and the bar at the start of it")

	time = time + 1.5
	f.cast:GetScript("OnUpdate")(f.cast, 1.5)
	check(f.cast.bar:GetValue() > 0.4 and f.cast.bar:GetValue() < 0.6,
		"half way through a three second cast, the bar is half way along")

	-- Chips share the space under the plate, so they move down out of its way.
	local savedAuras = _G.__auras.target
	_G.__auras.target = { HARMFUL = {
		{ "Chilled", 135834, 0, "Magic", 8, nil, "player", true },
	} }
	_G.__units.target = mob
	fire("PLAYER_TARGET_CHANGED")
	NPm.step(nil, 1)
	check(f._chipCount == 1, "the target has a chip")
	check(select(2, f.chips[1]:GetPoint()) == f.cast,
		"and it hangs off the CAST capsule while one is open, rather than being"
		.. " drawn through the middle of it")

	_G.__ccCasts.nameplate1 = nil
	_G.__ccFire("UNIT_SPELLCAST_STOP", "nameplate1")
	check(not f.cast:IsShown(), "the capsule closes when the cast stops")
	check(select(2, f.chips[1]:GetPoint()) == f,
		"and the chips move back up under the plate")

	-- A channel runs the other way.
	_G.__ccCasts.nameplate1 = { name = "Drain Life", icon = 136163, channel = true,
		start = time * 1000, finish = (time + 4) * 1000 }
	_G.__ccFire("UNIT_SPELLCAST_CHANNEL_START", "nameplate1")
	local atStart = f.cast.bar:GetValue()
	time = time + 2
	f.cast:GetScript("OnUpdate")(f.cast, 2)
	check(atStart > f.cast.bar:GetValue(),
		"a channel EMPTIES rather than fills - it is time you have left, not time"
		.. " you have spent")

	-- And a plate handed on mid-cast does not carry it to the next mob.
	__despawnPlate("nameplate1")
	check(not f.cast:IsShown() and f.cast.state == nil,
		"a plate released mid-cast stops casting, rather than showing the last"
		.. " tenant's spell over whoever gets it next")

	_G.__ccCasts.nameplate1 = nil
	_G.__auras.target = savedAuras
	_G.__units.target = nil
end

print("== nameplates: a friendly is a name, not a plate ==")
do
	local mate = { exists = true, name = "Kindarhazan", level = 19, reaction = 5,
		isPlayer = true, class = "Shaman", classToken = "SHAMAN",
		guild = "Samophlange", hp = 800, hpMax = 800 }
	local base = __spawnPlate("nameplate1", mate)
	local f = NPm.plateFor(base)

	check(f._nameForm == true, "a friendly player is drawn as a name")
	check(f.name._aetherStyle == "npFriendly",
		"in its own type role, a point up on the capsule's - a friendly name is"
		.. " shadowed type straight onto the world with no glass under it, and"
		.. " the same size there is a size smaller")
	A:Restyle()
	check(f.name._aetherStyle == "npFriendly",
		"and it SURVIVES a skin change - W.Restyle used to apply a named role"
		.. " without recording it, so the next skin pass put the original back"
		.. " and the name shrank with nothing on screen to explain why")
	check(f._fillColor[4] == 0,
		"with the glass gone entirely rather than dimmed - a faint capsule behind"
		.. " a friendly name is the thing the deck is most explicit about not wanting")
	check(f.name:GetText() == "Kindarhazan", "the name is there")
	check(f.guild:IsShown() and f.guild:GetText() == "<Samophlange>",
		"and the guild under it, in angle brackets")

	check(f.badge:IsShown() and f.badge.label:GetText() == "19",
		"a player gets a level pip")
	local cc = A.Palette:OrbBaseColor("nameplate1")
	check(cc ~= nil and math.abs(f.badge.disc.__color[1] - cc[1]) < 0.001,
		"tinted by CLASS, from the orb palette the HUD's own level disc uses -"
		.. " two sizes of one disc should not be two different colours")
	check(not f.bar:IsShown(),
		"and no health bar at all while they are unhurt - a street of full green"
		.. " bars is noise with nothing in it")

	_G.__units.nameplate1.hp = 300
	fire("UNIT_HEALTH", "nameplate1")
	check(f.bar:IsShown(), "a bar appears when they are hurt, and only then")

	-- The skull rule. Seen in game at 0.3.19: a friendly player showed one.
	_G.__units.nameplate1.level = -1
	NPm.UpdateAll(f)
	check(not f.badge:IsShown(),
		"a friendly whose level the client will not report has NO pip - never a"
		.. " skull, which says 'too far above you to judge as a threat' and is"
		.. " meaningless about somebody who is not one")

	-- A friendly NPC is a name and nothing else.
	__despawnPlate("nameplate1")
	local npc = { exists = true, name = "Innkeeper Boorand Plainswind", level = 30,
		reaction = 5, isPlayer = false, hp = 500, hpMax = 500 }
	__spawnPlate("nameplate1", npc)
	check(not f.badge:IsShown() and not f.guild:IsShown(),
		"a friendly NPC carries a name alone - no pip, no guild")
	check(f.name:GetText() == "Innkeeper Boorand Plainswind", "just the name")

	-- Party class colours are an opt-in.
	__despawnPlate("nameplate1")
	__spawnPlate("nameplate1", mate)
	check(f.name.__color[1] == A.Palette.c.ttFriendly[1],
		"a friendly player's name is blue by default, whoever they are")
	A.Config:Module("nameplates").partyClassColors = true
	_G.__units.nameplate1.inParty = true
	NPm.UpdateAll(f)
	check(math.abs(f.name.__color[1] - cc[1]) < 0.001,
		"class-coloured once you ask for it, from the same palette as the pip")
	_G.__units.nameplate1.inParty = false
	NPm.UpdateAll(f)
	check(f.name.__color[1] == A.Palette.c.ttFriendly[1],
		"and only for your PARTY, not for everybody in the city")
	A.Config:Module("nameplates").partyClassColors = false

	-- And the form has to be able to change back, because the frame is recycled.
	__despawnPlate("nameplate1")
	local mob = { exists = true, name = "Kolkar Marauder", level = 18, reaction = 2,
		hp = 900, hpMax = 1000 }
	__spawnPlate("nameplate1", mob)
	check(f._nameForm == false and f._fillColor[4] > 0,
		"the same frame becomes a capsule again for the next mob that walks up")
	check(f.name._aetherStyle == "npName",
		"with the capsule's own type role back, rather than the friendly one it"
		.. " was wearing a moment ago")
	check(f.badge:IsShown() and f.badge.label:GetText() == "18"
		and not f.guild:IsShown(),
		"with the badge back at plate size and the guild line gone")
	check(select(2, f.bar:GetPoint()) == f.name,
		"and the bar re-anchored inside the capsule rather than left under a"
		.. " guild line belonging to somebody who has walked off")

	__despawnPlate("nameplate1")
end

print("== nameplates: asking the client for friendly plates ==")
do
	local cv = _G.__cvars
	cv.nameplateShowFriendlyPlayers = "0"
	cv.nameplateShowFriendlyNpcs    = "0"
	_G.__badCVarWrites = 0

	NPm.applyCVars()
	cv.nameplateShowFriendlyPlayerMinions = "0"
	cv.nameplateShowEnemyMinions = "0"
	check(cv.nameplateShowFriendlyPlayerMinions == "0", "(minions start off)")

	NPm.applyCVars()
	check(cv.nameplateShowFriendlyPlayerMinions == "1"
		and cv.nameplateShowEnemyMinions == "1",
		"pets, imps and everything else somebody summoned are asked for too -"
		.. " without them a hunter's pet keeps the client's own floating name"
		.. " while the hunter standing next to it wears ours")

	check(cv.nameplateShowAll == "1",
		"the client is asked to draw plates for EVERYTHING, not only for your"
		.. " target and whatever is hitting you - without it a vendor at her"
		.. " counter never gets a plate at all, so nothing of ours runs on her"
		.. " and she keeps the engine's own floating name")

	-- ...but only when we are setting up. V toggles this one, and putting it
	-- back every time it moved would mean pressing V did nothing.
	cv.nameplateShowAll = "0"
	fire("CVAR_UPDATE", "nameplateShowAll", "0")
	check(cv.nameplateShowAll == "0",
		"and NOT forced back when the player turns it off themselves - it is on"
		.. " a keybind, and an addon that fights V is an addon that broke V")
	NPm.applyCVars(true)
	check(cv.nameplateShowAll == "1", "though changing a setting re-applies it")

	check(cv.nameplateMaxDistance == "41",
		"and the client is asked to make plates as far out as it will - past that"
		.. " there is no plate and the engine draws its own floating name, which"
		.. " is why the lettering changed at a fixed distance")

	A.Config:Module("nameplates").maxDistance = 900
	NPm.applyCVars()
	check(cv.nameplateMaxDistance == "41",
		"clamped to what the client's own slider offers rather than written raw")
	A.Config:Module("nameplates").maxDistance = 41

	check(cv.nameplateShowFriendlyPlayers == "1" and cv.nameplateShowFriendlyNpcs == "1",
		"friendly players AND friendly NPCs are asked for - without this the"
		.. " engine draws them as floating name text and never makes a plate, so"
		.. " the friendly form has nothing at all to draw on")
	check(_G.__badCVarWrites == 0,
		"and nameplateShowFriends, which this flavour does not have, is probed"
		.. " rather than fired blind - the client logs the blind one")

	-- Refused in combat, so queued rather than dropped.
	cv.nameplateShowFriendlyNpcs = "0"
	_G.__inCombat = true
	NPm.applyCVars()
	check(cv.nameplateShowFriendlyNpcs == "0" and NPm._cvarsPending == true,
		"a fight starting mid-load defers the write rather than losing it")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(cv.nameplateShowFriendlyNpcs == "1" and NPm._cvarsPending == nil,
		"and it lands when the fight ends")

	-- Zen borrows these. Two modules writing the same console variable is how
	-- one of them silently undoes the other.
	local Zn = A:GetModule("zen")
	-- On before zen, because that is what we asked the client for.
	cv.nameplateShowFriendlyNpcs = "1"
	Zn:SetWorldText(1)
	NPm.applyCVars()
	check(cv.nameplateShowFriendlyNpcs == "0" and NPm._cvarsPending == true,
		"a nameplate setting changed DURING a zen does not put every friendly"
		.. " plate back on screen in the middle of it")
	Zn:RestoreWorldText()
	check(cv.nameplateShowFriendlyNpcs == "1",
		"and zen gives back the value it borrowed, which was ours - so there is"
		.. " nothing left to redo when it ends")

	-- Somebody else moving them puts ours back. A console variable has no owner,
	-- and an addon that backs these up before we set them restores the old
	-- values over the top when its cutscene ends.
	cv.nameplateShowFriendlyNpcs = "0"
	cv.nameplateMaxDistance = "20"
	fire("CVAR_UPDATE", "nameplateShowFriendlyNpcs", "0")
	check(cv.nameplateShowFriendlyNpcs == "1" and cv.nameplateMaxDistance == "41",
		"a console variable moved out from under us is put back, whoever moved it")

	_G.__cvarWrites = 0
	fire("CVAR_UPDATE", "nameplateShowFriendlyNpcs", "1")
	check(_G.__cvarWrites == 0,
		"and re-running it when nothing is wrong writes nothing at all - which is"
		.. " what stops us and the next addon setting each other off forever")

	-- Never turned off: that state is the player's own console setting.
	A.Config:Module("nameplates").friendlyNames = false
	cv.nameplateShowFriendlyNpcs = "0"
	NPm.applyCVars()
	check(cv.nameplateShowFriendlyNpcs == "0",
		"switching friendly names off makes friendlies wear the capsule - it does"
		.. " not go and clear their console variables")
	A.Config:Module("nameplates").friendlyNames = true
end

print("== options: every control is wired to something that exists ==")
do
	-- A control bound to a key that is not in the defaults does NOTHING, and
	-- says nothing about it: the slider moves, the value is written into a
	-- table nobody reads, and the setting silently has no effect. The panel is
	-- the only way most of this is reachable, so a typo here is a feature that
	-- quietly is not there.
	local missing, count = {}, 0

	local function walk(node, where)
		for key, opt in pairs(node.args or {}) do
			local at = (where or "") .. "/" .. tostring(key)
			if opt.type == "group" then
				walk(opt, at)
			elseif opt.arg and opt.arg.path then
				count = count + 1
				-- Against the DEFAULTS, not the live profile. The profile is
				-- whatever this suite has written into it by now, and Set writes
				-- a key whether or not it was ever declared - so resolving there
				-- means a control with a typo in its path CREATES the key it was
				-- looking for and then reports itself as fine.
				-- `defaultTrue` toggles are absent from the defaults ON PURPOSE:
				-- Get reads nil as true for them, so declaring one would say the
				-- same thing twice and the two could disagree.
				local t = (not opt.arg.defaultTrue) and A.Config.defaults.profile or nil
				local path = opt.arg.path
				if t == nil then path = nil end
				if path then
					for i = 1, #path - 1 do
						t = type(t) == "table" and t[path[i]] or nil
					end
					if type(t) ~= "table" or t[path[#path]] == nil then
						missing[#missing + 1] = at .. " -> "
							.. table.concat(path, ".")
					end
				end
			end
		end
	end
	walk(A.Options:Build())

	check(count > 40, "the panel binds a fair number of controls (" .. count .. ")")

	-- And nothing bound to a key no code reads. That is not statically knowable
	-- in general, so this is the two that were: the minimap drawer's switches
	-- outlived the drawer itself, wrote modules.minimap.drawer and .skinButtons,
	-- and nothing had consulted either since the buttons moved to the rail.
	local tree = A.Options:Build()
	check(tree.args.minimap and tree.args.minimap.args.drawer == nil
		and tree.args.minimap.args.skinButtons == nil
		and tree.args.minimap.args.buttonSpacing == nil,
		"and the minimap's dead drawer controls are gone with the drawer")
	check(#missing == 0,
		"and every one resolves to a key that exists in the defaults ("
		.. table.concat(missing, ", ") .. ")")

	-- And the nameplate page in particular, since it is the newest.
	local np = A.Options:Build().args.nameplates
	check(np ~= nil and np.type == "group", "nameplates has a page of its own")
	check(np and np.args.enabled and np.args.friendlyNames and np.args.scale,
		"carrying the switches that were only reachable by editing a table")
end

print("== nameplates: an NPC is not a mob ==")
do
	-- From the game: a kodo is a mob, Flight Master Devrak is an NPC. Reaction
	-- cannot tell
	-- them apart - a wandering kodo is neutral and so is an NPC of a faction you
	-- have not earned yet. What separates them is whether you can hit it.
	local kodo = { exists = true, name = "Wandering Kodo", level = 15,
		reaction = 4, hp = 500, hpMax = 500 }
	local devrak = { exists = true, name = "Devrak", level = 30,
		reaction = 4, hp = 900, hpMax = 900, canAttack = false,
		title = "Flight Master" }

	local baseK = __spawnPlate("nameplate1", kodo)
	local baseD = __spawnPlate("nameplate2", devrak)
	local k, d = NPm.plateFor(baseK), NPm.plateFor(baseD)

	check(k._nameForm == false and k._fillColor[4] > 0,
		"a neutral MOB keeps the capsule - it is a thing you might have to"
		.. " fight, and the level and the health are what you want off it")
	check(d._nameForm == true and d._fillColor[4] == 0,
		"while an NPC at the same reaction is a name - not enough reputation is"
		.. " a fact about your standing, not about whether he is a mob")
	check(d.name:GetText() == "Devrak" and not d.badge:IsShown(),
		"the name, with no capsule and no level on it")
	check(not d.bar:IsShown(), "and no health bar while he is unhurt")

	check(d.guild:IsShown() and d.guild:GetText() == "<Flight Master>",
		"and his TITLE under it - which is what tells you he is the one to talk"
		.. " to. A nameplate carries no title, so it is read off the second line"
		.. " of his tooltip, where the client keeps it")
	check(GameTooltip.__unit ~= "nameplate2",
		"through a tooltip of our own, never GameTooltip - that one belongs to"
		.. " whatever the cursor is over, and driving it here would flicker"
		.. " somebody else's tooltip every time a vendor walked past")

	_G.__units.nameplate2.hp = 100
	fire("UNIT_HEALTH", "nameplate2")
	check(d.bar:IsShown(), "which appears if somebody is beating on him")

	-- And a hostile one is a capsule whatever else is true of it.
	__despawnPlate("nameplate2")
	__spawnPlate("nameplate2", { exists = true, name = "Kolkar Marauder",
		level = 18, reaction = 2, hp = 900, hpMax = 1000 })
	check(d._nameForm == false, "anything you can attack is a capsule")

	-- Vendors and flight masters are names whatever their reaction. Kaja
	-- the ammo merchant is NEUTRAL, and therefore attackable, and therefore
	-- indistinguishable from the kodo by reaction or by attackability. The
	-- client gives her a title and gives the kodo none.
	__despawnPlate("nameplate2")
	__spawnPlate("nameplate2", { exists = true, name = "Kaja", level = 30,
		reaction = 4, hp = 1003, hpMax = 1003, title = "Guns and Ammo Merchant" })
	check(d._nameForm == true,
		"a NEUTRAL vendor is a name - she has a job, and the title is the only"
		.. " thing in Lua that says so")
	check(d.guild:GetText() == "<Guns and Ammo Merchant>", "with her trade under it")
	check(k._nameForm == false,
		"while the kodo standing beside her, equally neutral and equally"
		.. " attackable, is still a capsule")

	-- A mob's second line is its LEVEL, and taking that for a title puts
	-- "Level 15 Beast" under a kodo's name - which is worse than no title.
	check(k.guild:IsShown() == false, "a mob's level line is not read as a title")

	-- COLOURBLIND MODE INSERTS A LINE. With it on the title is on line three,
	-- and reading line two regardless gets you the wrong string for every NPC
	-- in the game - for the players who need that setting, and nobody else.
	_G.__cvars.colorblindMode = "1"
	__despawnPlate("nameplate2")
	__spawnPlate("nameplate2", { exists = true, name = "Zargh", level = 30,
		reaction = 4, hp = 900, hpMax = 900, title = "Butcher" })
	check(d._nameForm == true and d.guild:GetText() == "<Butcher>",
		"the title line moves with colourblind mode, which adds one above it")
	_G.__cvars.colorblindMode = "0"

	-- ...but a named hostile carries a title too, and that one you want to see
	-- the health of.
	__despawnPlate("nameplate2")
	__spawnPlate("nameplate2", { exists = true, name = "Edwin VanCleef", level = 22,
		reaction = 2, hp = 4000, hpMax = 4000, title = "Defias Kingpin" })
	check(d._nameForm == false,
		"a hostile with a title is still a capsule - a named boss has one, and"
		.. " its name without its health is the worst of both")

	-- A creature with no title is remembered as having none, or every plain mob
	-- is re-scanned on every plate it ever appears on.
	local vendor = { exists = true, name = "Larhka", level = 30, reaction = 5,
		hp = 500, hpMax = 500, canAttack = false, title = "Beverage Merchant" }
	__despawnPlate("nameplate1")
	__spawnPlate("nameplate1", vendor)
	check(k.guild:GetText() == "<Beverage Merchant>", "a vendor keeps her trade")

	__despawnPlate("nameplate1")
	__despawnPlate("nameplate2")
end

print("== palette: the orb's class colours are the CLIENT's ==")
do
	-- The orb names its nine colours rather than reading RAID_CLASS_COLORS, so a
	-- colour-blind addon can recolour every name in the game without the level
	-- disc moving under it. That is worth keeping and it is also how a copy goes
	-- stale, so the copy is checked.
	--
	-- Shaman is the one that matters: PINK on Vanilla, blue from TBC on. The two
	-- files sit side by side in Blizzard_SharedXML and this client loads the
	-- Vanilla one, so pink is not a preference here, it is the version.
	local wrong = {}
	for class, cc in pairs(RAID_CLASS_COLORS) do
		local units = _G.__units
		units.__cc = { exists = true, isPlayer = true, class = class,
			classToken = class, reaction = 5 }
		local ours = A.Palette:OrbBaseColor("__cc")
		if math.abs(ours[1] - cc.r) > 0.004 or math.abs(ours[2] - cc.g) > 0.004
			or math.abs(ours[3] - cc.b) > 0.004 then
			wrong[#wrong + 1] = class
		end
		units.__cc = nil
	end
	check(#wrong == 0,
		"every class the client names, the orb names the same (" ..
		table.concat(wrong, ", ") .. ")")

	-- And the shipped default is a default, not somebody's setting.
	-- Reachable, or A:Debug is a diagnostic nobody can read.
	A.db.profile.debug = false
	SlashCmdList["AETHERUI"]("debug on")
	check(A.db.profile.debug == true, "debug can be switched on from a slash command")
	SlashCmdList["AETHERUI"]("debug off")
	check(A.db.profile.debug == false, "and off again")

	check(A.Config.defaults.profile.scale == 1.0,
		"the default scale is 1, which is what a 1920x1080 screen wants. It was"
		.. " 0.71 under a comment deriving it from the DECK's proportions, which"
		.. " is sound arithmetic about the deck and was never a claim about what"
		.. " a player should get")

	check(math.abs(RAID_CLASS_COLORS.SHAMAN.r - 0.96) < 0.004
		and math.abs(RAID_CLASS_COLORS.SHAMAN.b - 0.73) < 0.004,
		"and a Shaman is pink, because this is Vanilla - blue is TBC's answer")
end

print("== popups: the client's dialogs in our glass ==")
do
	local PPm = A:GetModule("popups")

	-- SCALE. A dialog left at the client's size is enormous beside the
	-- interface that raised it, and it is the one window that turns up without
	-- being asked for.
	local popScale = A.db.profile.scale
	A.db.profile.scale = 0.8
	PPm:Skin()
	check(_G.StaticPopup1:GetScale() == 0.8,
		"a dialog is drawn at the profile's scale like everything else of ours")
	A.db.profile.scale = popScale
	PPm:Skin()

	-- BOTH conventions. Half the mock's dialogs carry their parts as fields and
	-- half name them globally, because both are live on this client - and a
	-- module that knows one convention skins half the dialogs in the game while
	-- looking perfectly correct on whichever half it was written against.
	for i = 1, 4 do
		local p = _G["StaticPopup" .. i]
		check(p.__aetherPanel ~= nil,
			"dialog " .. i .. " has a glass panel behind it")
		check(p.__border:IsShown() == false and p.__bg:IsShown() == false,
			"and the stone frame it came with is hidden, not covered over")
		check(p.__nine.__fill:GetTexture() == 0,
			"including the background hanging off it in a CHILD FRAME - that is"
			.. " not one of the dialog's own regions, so a strip that only walks"
			.. " GetRegions leaves the thing you actually see through")

		local alert = PPm.Element(p, "AlertIcon")
		check(alert and not alert:IsShown(),
			"the warning triangle goes with the stone it was drawn for - what the"
			.. " dialog asks is in the words")

		local text = PPm.Element(p, "Text")
		check(text and text._aetherStyle == "qlObjName",
			"the question is re-roled into our type")

		local b1 = PPm.Element(p, "Button1")
		check(b1 and b1.__aetherSkin ~= nil, "and each button gets a pill behind it")
				check(b1:GetFontString()._aetherStyle == "tbCardTitle", "with our lettering on it")

		-- THE ONE THAT SHIPPED WRONG. A button's pushed art is hidden until you
		-- press it, so hiding "everything currently shown" left it in place and
		-- Blizzard's button flashed back the instant you clicked.
		local pushed = b1:GetPushedTexture()
		check(pushed and pushed:GetTexture() == 0,
			"the PUSHED art is cleared through the setter, not merely hidden -"
			.. " the client shows it on mousedown and there is no moment of ours"
			.. " in between")
		local normal = b1:GetNormalTexture()
		check(normal and normal:GetTexture() == 0, "and so is the normal art")
		local hi = b1:GetHighlightTexture()
		check(hi and hi:GetTexture() == 0, "and the highlight")
	end

	-- The client can put art BACK. A button's pushed texture is hidden until it
	-- is pressed, and once shown it stayed shown for every dialog after.
	do
		local p2 = _G.StaticPopup2
		p2.__later:Show()
		p2:GetScript("OnShow")(p2)
		check(not p2.__later:IsShown(),
			"art the client reveals later is taken down on the next show, rather"
			.. " than being left because it was not up when we first looked -"
			.. " which is how a texture appears once and then stays for good")
	end

	-- The buttons are DRESSED, not rebuilt: what you click is still the
	-- client's, because several of these dialogs run protected actions.
	local p1 = _G.StaticPopup1
	local b1 = PPm.Element(p1, "Button1")
	check(b1:GetParent() == p1 and b1.__aetherSkin:GetParent() == b1,
		"the button is still the client's own, in the client's own place - the"
		.. " pill hangs off it rather than the other way round")

	-- Off gives Blizzard's back, whole. Every module here is a reskin.
	A:SetModuleEnabled("popups", false)
	check(p1.__aetherPanel == nil and p1.__border:IsShown()
		and b1.__aetherSkin == nil,
		"switching it off returns the dialog the client drew, art and all")
	A:SetModuleEnabled("popups", true)
	check(_G.StaticPopup1.__aetherPanel ~= nil, "and on again re-dresses it")

	-- ...and off puts the button's own art back, not just our pill.
	A:SetModuleEnabled("popups", false)
	local restored = PPm.Element(_G.StaticPopup1, "Button1"):GetNormalTexture()
	check(restored and restored:GetTexture() == "dialog-button-up",
		"switching off gives the button its own art back, by name - clearing a"
		.. " texture is not undone by hiding a region")
	check(_G.StaticPopup1.__nine.__fill:GetTexture() == "dialog-background",
		"and the dialog's own background comes back with it, out of the child"
		.. " frame it lives in")
	A:SetModuleEnabled("popups", true)
end

print("== reskin: taking a client frame apart, reversibly ==")
do
	local R = A.Reskin

	-- Element, under both conventions. The reworked frames are MIXIN objects
	-- and resolve their parts through __index, so rawget finds a frame and none
	-- of its pieces - which shipped once as a dialog with untouched buttons.
	local mixin = CreateFrame("Frame", "AetherTestMixinFrame", UIParent)
	local part = CreateFrame("Button", nil, mixin)
	setmetatable(mixin, { __index = function(_, k) return k == "Button1" and part or nil end })
	check(R.Element(mixin, "Button1") == part,
		"a part reached through __index is found - rawget would answer nil for"
		.. " every one of them")

	local named = CreateFrame("Frame", "AetherTestNamedFrame", UIParent)
	local far = CreateFrame("Button", "AetherTestNamedFrameButton1", named)
	check(R.Element(named, "Button1") == far,
		"and a part that only exists as a global name is found too")
	check(R.Element(named, "Nothing") == nil, "with nothing invented for a part that is absent")

	-- Strip: regions, and the art hiding in child frames.
	local host = CreateFrame("Frame", nil, UIParent)
	local own = host:CreateTexture(nil, "BACKGROUND")
	own:SetTexture("stone")
	local hiddenArt = host:CreateTexture(nil, "OVERLAY")
	hiddenArt:SetTexture("glow")
	hiddenArt:Hide()

	host.NineSlice = CreateFrame("Frame", nil, host)
	local backdrop = host.NineSlice:CreateTexture(nil, "BACKGROUND")
	backdrop:SetTexture("dialog-background")

	local store = {}
	R.Strip(host, store)
	check(own:GetTexture() == 0 and not own:IsShown(),
		"a texture is CLEARED, not merely hidden - a hidden one is one the"
		.. " client can show again, and does")
	check(backdrop:GetTexture() == 0,
		"and the backdrop in a child frame goes with it, which GetRegions never"
		.. " returns and is the whole reason a stripped dialog stayed opaque")

	hiddenArt:Show()
	R.Strip(host, store)
	check(not hiddenArt:IsShown(),
		"art revealed later is taken down on the next pass, rather than being"
		.. " left because it was down when we first looked")

	R.Restore(store)
	check(own:GetTexture() == "stone" and own:IsShown(), "and it all goes back")
	check(backdrop:GetTexture() == "dialog-background", "including the child frame's")
	check(not hiddenArt:IsShown(),
		"except what the client had hidden itself, which stays hidden - putting"
		.. " everything back means as it WAS, not as much of it as possible")

	-- Buttons: the four state textures, through the setters.
	local btn = CreateFrame("Button", nil, UIParent)
	btn:SetNormalTexture("up")
	btn:SetPushedTexture("down")
	R.ClearButton(btn)
	check(btn:GetNormalTexture():GetTexture() == 0
		and btn:GetPushedTexture():GetTexture() == 0,
		"cleared through the setters - the client shows the pushed one on"
		.. " mousedown and there is no moment of ours in between")
	R.RestoreButton(btn)
	check(btn:GetNormalTexture():GetTexture() == "up"
		and btn:GetPushedTexture():GetTexture() == "down",
		"and restored by name, because clearing is not undone by showing")

	-- ORDER-INDEPENDENT. A caller may strip a button's regions before clearing
	-- its state textures - both orders are reasonable and each has been written
	-- once already. Clearing second must not record the emptied value as though
	-- it were the client's, or the restore puts "cleared" back.
	local either = CreateFrame("Button", nil, UIParent)
	either:SetNormalTexture("up")
	local st = {}
	R.Strip(either, st)
	R.ClearButton(either)
	R.Restore(st)
	R.RestoreButton(either)
	check(either:GetNormalTexture():GetTexture() == "up",
		"whichever order the caller strips and clears in, the button gets its"
		.. " own art back")

	-- DRESSED, HANDED BACK, DRESSED AGAIN. Switching a module off restores every
	-- state texture it took, and switching it on runs the dressing a second time
	-- over a widget that still carries our marker - so a dresser that tests the
	-- marker before it clears returns before it has taken back what it gave up,
	-- and the client's border is on our cell until the next reload.
	local twice = CreateFrame("Button", nil, UIParent)
	twice:SetNormalTexture("slot-border")
	twice.IconTexture = twice:CreateTexture(nil, "BACKGROUND")
	twice.IconTexture:SetTexture("an-item")
	R.Slot(twice)
	R.RestoreButton(twice)
	R.Slot(twice)
	check(twice:GetNormalTexture():GetTexture() == 0,
		"and a slot dressed, handed back and dressed again is bare the second"
		.. " time too")
	check(twice.IconTexture:GetTexture() == "an-item",
		"with the item still in it")
end

print("== panels: one body, one recess, one set of numbers ==")
do
	local W = A.Widgets
	local PN = A:GetModule("panels")
	local cf = _G.CharacterFrame

	-- THE HANDOFF'S NUMBERS, not numbers near them. 15a is specific: the band
	-- is 54 and 64 with a subtitle, the body is 18 in on all four sides and 14
	-- between blocks. These were 50/58/16/12 - close enough to look right on
	-- their own and wrong against every measurement in the document.
	check(W.PANEL_HEAD_H == 54 and W.PANEL_HEAD_SUB == 64
		and W.PANEL_PAD == 18 and W.PANEL_GAP == 14,
		"the panel metrics are the handoff's own (" .. W.PANEL_HEAD_H .. "/" ..
		W.PANEL_HEAD_SUB .. "/" .. W.PANEL_PAD .. "/" .. W.PANEL_GAP .. ")")
	check(W.WELL_CORNER == 14 and W.WELL_PAD == 16,
		"and so are the well's - 15b: radius 14, padding 16 (" ..
		W.WELL_CORNER .. "/" .. W.WELL_PAD .. ")")

	-- EVERY HAIRLINE STOPS SHORT OF THE RIM. A rail and the panel's border are
	-- drawn in the same ink, so where one runs into the other the two alphas
	-- add and the join lights a bright pip on the edge of the window.
	local _, _, _, hx = cf.__aetherHeadRule:GetPoint(1)
	local _, _, _, hx2 = cf.__aetherHeadRule:GetPoint(2)
	check(hx == W.RULE_GAP and hx2 == -W.RULE_GAP and W.RULE_GAP > 0,
		"the header hairline stops short of the border at both ends (" ..
		tostring(hx) .. ", " .. tostring(hx2) .. ")")
	local foot = cf.__aetherRails["BOTTOM"]
	local _, _, _, rx = foot.rule:GetPoint(1)
	local _, _, _, rx2 = foot.rule:GetPoint(2)
	check(rx == W.RULE_GAP and rx2 == -W.RULE_GAP,
		"and so does the tab rail's (" .. tostring(rx) .. ", " ..
		tostring(rx2) .. ")")

	-- AND A REAL PIXEL OF IT, in the frame's OWN units. This is the one that
	-- actually hid them. A.pixel is in UIParent units and every one of these
	-- lines lives inside a frame drawn at the profile's scale, so
	-- SetHeight(A:Px(1)) asks for seven tenths of a pixel: present in every
	-- measurement, correct in every anchor, and grey to nothing on screen.
	-- Reported four times, on four windows, as a separator that was not there.
	local mine = A:PxIn(cf.__aetherChrome)
	check(math.abs(A:Px(1) - mine) > 0.001,
		"a panel really is drawn at a scale of its own, so this can tell the two"
		.. " pixels apart (" .. string.format("%.3f", A:Px(1)) .. " against " ..
		string.format("%.3f", mine) .. ")")
	check(math.abs(cf.__aetherHeadRule:GetHeight() - mine) < 0.001,
		"and the header hairline is one pixel in its own frame's units rather"
		.. " than UIParent's (" ..
		string.format("%.3f", cf.__aetherHeadRule:GetHeight()) .. ")")
	local col = _G.SpellBookFrame.__aetherRails.RIGHT.rule
	check(math.abs(col:GetWidth() - A:PxIn(col:GetParent())) < 0.001,
		"and an upright one is a pixel WIDE rather than a pixel tall (" ..
		string.format("%.3f", col:GetWidth()) .. ")")

	-- AND EVERY ONE OF THEM IS THE SAME INK. A tab rail took glassEdge whole,
	-- a header band took 0.7 of it and the quest log's two dividers 0.55 and
	-- 0.5 - so the rails landed at 0.32 and the rest between 0.16 and 0.22,
	-- which on frosted glass is a line present in every measurement and absent
	-- from the screen. Four separate reports of a missing separator, one
	-- number.
	local edge = A.Palette.c.glassEdge
	local faint = {}
	local function ink(t, what)
		if not t then return end
		local _, _, _, a = t:GetVertexColor()
		if math.abs((a or 0) - (edge[4] or 1)) > 0.001 then
			faint[#faint + 1] = what .. " " .. string.format("%.2f", a or -1)
		end
	end
	ink(cf.__aetherHeadRule, "a panel header")
	ink(foot.rule, "a tab rail")
	ink(QLog.win.head.rule, "the quest log header")
	ink(QLog.win.list.rule, "the quest log divider")
	local bagsWin = A:GetModule("bags").frames.bags
	ink(bagsWin.head.rule, "the bags header")
	ink(bagsWin.foot.rule, "the bags footer")
	check(#faint == 0,
		"every hairline in the interface is drawn in the same ink (" ..
		(#faint > 0 and table.concat(faint, ", ") or "all at " ..
		string.format("%.2f", edge[4] or 1)) .. ")")

	-- EVERY PANEL HAS A BODY, and it is one recess rather than whatever that
	-- window's own dresser thought was content - which on the character sheet
	-- was a box round the model and nothing at all round the rest of it.
	local bare = {}
	for _, name in ipairs({ "CharacterFrame", "SpellBookFrame", "MerchantFrame",
		"GossipFrame", "MailFrame" }) do
		local f = _G[name]
		if f and f.__aetherPanel and not f.__aetherBody then
			bare[#bare + 1] = name
		end
	end
	check(#bare == 0,
		"every window has one (" .. (#bare > 0 and
		(table.concat(bare, ", ") .. " without") or "all of them") .. ")")

	-- IT HANGS OFF THE GLASS, for the same reason the hairline does.
	check(cf.__aetherBody:GetParent() == cf.__aetherPanel,
		"drawn on the glass rather than on the window under it")

	-- AND IT CLEARS THE HEADER BY THE BODY PADDING.
	local bp, brel, brelP, bx, by = cf.__aetherBody:GetPoint(1)
	check(bp == "TOPLEFT" and brel == cf.__aetherPanel and brelP == "TOPLEFT"
		and bx == W.PANEL_PAD
		and by == -(cf.__aetherHeadH + W.PANEL_PAD),
		"starting a body padding below the header rather than against it (" ..
		tostring(bx) .. ", " .. tostring(by) .. ")")

	-- AND IT STOPS AT THE RAILS. The spellbook wears both: a column of school
	-- icons down the right and a row of book tabs along the foot. A recess
	-- running under either reads as the tabs floating on the content.
	local sb = _G.SpellBookFrame
	local sbSide = sb.__aetherRails["RIGHT"]
	local rp, rrel, rrelP = sb.__aetherBody:GetPoint(2)
	check(rp == "RIGHT" and rrel == sbSide and rrelP == "LEFT",
		"the body stops at the tab column rather than running under it (" ..
		tostring(rp) .. " to " .. tostring(rrelP) .. ")")

	-- The row is read off the character sheet, which wears five tabs and no
	-- column at all.
	local cfFoot = cf.__aetherRails["BOTTOM"]
	local fp, frel, frelP = cf.__aetherBody:GetPoint(3)
	check(fp == "BOTTOM" and frel == cfFoot and frelP == "TOP",
		"and stands on the tab row rather than behind it (" .. tostring(fp) ..
		" to " .. tostring(frelP) .. ")")

	-- THE CLIENT'S CONTENT IS MOVED DOWN INTO IT. The character sheet's first
	-- slot is anchored 74 below the frame, which is 64 below the glass - the
	-- strip the stone title plate used to fill. Our band with a subtitle is 64
	-- exactly, so the content began ON the hairline with nothing left for the
	-- body padding, and the recess had to be drawn under its own content.
	-- ACROSS AS WELL AS DOWN. The vendor's rows are anchored eleven in from
	-- the window and the body is eighteen, so its icons hung out of the recess
	-- on the left and its prices out of it on the right - the same seven units
	-- at each end, and the well drawn round content it did not contain.
	check(_G.PaperDollFrame.__aetherLeft == 11,
		"the client's content is measured across too (" ..
		tostring(_G.PaperDollFrame.__aetherLeft) .. ")")
	-- INSIDE THE WELL'S OWN PADDING, not against its rim: 15b gives a well 16
	-- on all four sides, and content moved only as far as the body's edge is
	-- content jammed into the corner of the recess.
	local inner = W.PANEL_PAD + W.WELL_PAD
	local ix = select(4, _G.PaperDollFrame:GetPoint(1))
	check(ix == inner - 11 and ix > 0,
		"and moved in past the well's own padding (" .. tostring(ix) ..
		" for content that started at 11)")

	-- WITH THE WINDOW WIDENED BY WHAT EACH SIDE IS SHORT, added together -
	-- moving the content in from the left puts it that much closer to the
	-- right, and the two edges are not short by the same amount. Doubling the
	-- left was an assumption that the client centred its content in its own
	-- window, and the vendor's rows are not centred in its.
	local grown, grow = cf:GetWidth(), cf.__aetherBodyGrow
	check(grow and grow > 0,
		"the window is widened to pay for the inset (" .. tostring(grow) .. ")")
	PN.LayoutBody(cf, PN.ENTRY.CharacterFrame)
	check(math.abs(grown - cf:GetWidth()) < 0.5,
		"re-laying it out does not widen a window that is already inset")
	cf.__aetherBodyGrow = nil
	cf:SetWidth(grown - grow)
	PN.LayoutBody(cf, PN.ENTRY.CharacterFrame)
	check(math.abs(cf:GetWidth() - grown) < 0.5,
		"and one that has not been widened yet grows by exactly that (" ..
		string.format("%.0f", cf:GetWidth()) .. " of " ..
		string.format("%.0f", grown) .. ")")

	-- MEASURED, not declared. Every window turned out to want a different
	-- number and the character sheet three of them, one per tab.
	check(_G.PaperDollFrame.__aetherTop == 64
		and _G.ReputationFrame.__aetherTop == 47
		and _G.SkillFrame.__aetherTop == 39,
		"each tab is measured on its own rather than sharing one number (" ..
		tostring(_G.PaperDollFrame.__aetherTop) .. "/" ..
		tostring(_G.ReputationFrame.__aetherTop) .. "/" ..
		tostring(_G.SkillFrame.__aetherTop) .. ")")
	local want = cf.__aetherHeadH + inner - 39
	check(cf.__aetherBodyShift == want and want > 0,
		"and the window grows by the deepest of them (" ..
		tostring(cf.__aetherBodyShift) .. " against " .. tostring(want) .. ")")
	local pp, prel, pprel, _, py = _G.PaperDollFrame:GetPoint(1)
	check(pp == "TOPLEFT" and prel == cf and pprel == "TOPLEFT"
		and py == -(cf.__aetherHeadH + inner - 64),
		"by moving the PANE, so every slot and model on the tab travels with"
		.. " it (" .. tostring(py) .. ")")
	local _, _, _, _, ry = _G.ReputationFrame:GetPoint(1)
	check(ry == -(cf.__aetherHeadH + inner - 47),
		"and each tab by its own amount rather than all by the window's (" ..
		tostring(ry) .. ")")

	-- BY ITS TOP CORNER ONLY, because a pane that fills the window is a page
	-- AND a footer at once: the client hangs the gear down from its top edge
	-- and the weapon row 127 UP from its bottom. Shifting both corners moved
	-- that row twice - once with the pane and once more when the window grew
	-- underneath it - and it came out through the foot of the recess and across
	-- the tab rail, on this window and on the inspect one both.
	local bp, brel, bprel, bx, by = select(1, _G.PaperDollFrame:GetPoint(2))
	check(bp == "BOTTOMRIGHT" and brel == cf and bprel == "BOTTOMRIGHT"
		and bx == 0 and by == 0,
		"the pane's bottom corner stays on the window's (" .. tostring(bx) ..
		", " .. tostring(by) .. ")")
	check(_G.PaperDollFrame:GetBottom() == cf:GetBottom(),
		"so the page still reaches the foot of the window (" ..
		tostring(_G.PaperDollFrame:GetBottom()) .. " against " ..
		tostring(cf:GetBottom()) .. ")")
	local weapon = _G.CharacterMainHandSlot
	check(weapon:GetBottom() - _G.PaperDollFrame:GetBottom() == 127 - 37,
		"and the weapon row is still the 127 up from it that the client put it"
		.. " at, rather than that minus the shift twice over (" ..
		tostring(weapon:GetBottom() - _G.PaperDollFrame:GetBottom()) .. ")")

	-- A CONTROL OVER A LIST IS CONTENT. The spellbook's rank switch is the
	-- same kind of thing an expand-all is over a tree, so it belongs in the
	-- recess with the list rather than floating in the band above it - and the
	-- client hangs it 38 below the frame, which is inside our header.
	local ranks = _G.ShowAllSpellRanksCheckbox
	local kp, krel, krelP, kx, ky = ranks:GetPoint(1)
	check(kp == "TOPLEFT" and krel == sb.__aetherBody and krelP == "TOPLEFT"
		and kx == W.WELL_PAD and ky == -W.WELL_PAD,
		"the rank switch sits inside the well at its own padding (" ..
		tostring(kx) .. ", " .. tostring(ky) .. ")")

	-- ...AND THE SPELLS MOVE DOWN TO MAKE ROOM FOR IT. Putting the switch in
	-- the well without that lands it on top of the first spell in the list.
	local lead = 22 + W.PANEL_GAP
	local wantShift = W.PANEL_HEAD_H + W.PANEL_PAD + W.WELL_PAD + lead
		- _G.SpellBookSpellIconsFrame.__aetherTop
	check(sb.__aetherBodyShift == wantShift and wantShift > 0,
		"and the page is moved down by the room it takes (" ..
		tostring(sb.__aetherBodyShift) .. " against " .. tostring(wantShift)
		.. ")")
	local ip, irel, _, _, iy = _G.SpellBookSpellIconsFrame:GetPoint(1)
	check(ip == "TOPLEFT" and irel == sb and iy == -sb.__aetherBodyShift,
		"by moving the page, so all twelve travel together (" ..
		tostring(iy) .. ")")

	-- AND THE PAGE IS MEASURED AGAINST THE TAB COLUMN, not against the glass.
	-- The recess stops at the rail, so a window measured to the window's own
	-- edge thinks its content has a hand's width of room it has not got - and
	-- the second column of spell names ran out through the rim and under the
	-- school tabs. Our lettering is wider than the client's; the box it sized
	-- for its own is what has to fit.
	local PN2 = A:GetModule("panels")
	local icons = _G.SpellBookSpellIconsFrame
	local side = sb.__aetherRails and sb.__aetherRails["RIGHT"]
	local function remeasure()
		icons.__aetherTop, icons.__aetherLeft, icons.__aetherRight =
			nil, nil, nil
		return select(3, PN2.MeasureTop(sb, icons))
	end
	local withRail = remeasure()
	side:Hide()
	local noRail = remeasure()
	side:Show()
	remeasure()
	check(side ~= nil and withRail and noRail and withRail < noRail,
		"the page is measured against the tab column rather than against the"
		.. " glass, so what the rail takes is room the content has not got (" ..
		string.format("%.0f", withRail or 0) .. " against " ..
		string.format("%.0f", noRail or 0) .. ")")

	-- AND CONTENT THAT ALREADY RUNS PAST THAT EDGE IS MEASURED RATHER THAN
	-- SKIPPED. The walk used to ignore anything reaching beyond the boundary,
	-- which meant the one thing it could never see was an overflow - so a
	-- window whose text runs out through the rim could not be widened to fit
	-- it. A negative answer here IS the overflow, in units.
	check(withRail and withRail < 0,
		"and a page that is already too wide for it measures as short by the"
		.. " overflow rather than as fitting (" ..
		string.format("%.0f", withRail or 0) .. ")")

	-- A WINDOW WITH A FOOTER KEEPS THE STRIP CLEAR. The vendor's repair buttons
	-- and your purse are anchored to its bottom edge - the client's own footer,
	-- whether we asked for one or not - and a body that reached the tab rail
	-- ran its recess down through the money row.
	local mf = _G.MerchantFrame
	local mfoot = mf.__aetherRails["BOTTOM"]
	local _, _, _, _, my = mf.__aetherBody:GetPoint(3)
	-- The strip's own height and the body's padding ON TOP of it - and nothing
	-- underneath. 15a's strip sits against the bottom edge, or against the rail
	-- where one replaces it; inset at both ends it read as a row of buttons
	-- pushed up with a third of the strip empty beneath them.
	check(my == W.PANEL_PAD + W.PANEL_FOOT_H,
		"the recess stops a footer's height clear of the tab rail (" ..
		tostring(my) .. ")")
	local _, _, _, _, cy = cf.__aetherBody:GetPoint(3)
	check(cy == W.PANEL_PAD,
		"and a window with no footer keeps none of it back (" ..
		tostring(cy) .. ")")
	local _ = mfoot

	-- A HIDDEN RAIL IS NOT A RAIL. A window can carry a rail it is not using -
	-- the spellbook's column is built and then hidden on a class with a single
	-- school - and a body that stopped at a rail nobody can see would leave a
	-- strip of bare glass along that edge with nothing standing in it.
	cfFoot:Hide()
	PN.LayoutBody(cf, PN.ENTRY.CharacterFrame)
	local hp, hrel = cf.__aetherBody:GetPoint(3)
	check(hp == "BOTTOM" and hrel == cf.__aetherPanel,
		"the body reaches the foot of the glass when the rail is down")
	cfFoot:Show()
	PN.LayoutBody(cf, PN.ENTRY.CharacterFrame)

	-- ...AND THE WINDOW GROWS BY THE SAME AMOUNT, or the shift pushes whatever
	-- was anchored to the bottom edge straight out of the frame.
	local tall = cf:GetHeight()
	PN.Dress(cf, cf.__aetherArt)
	check(cf:GetHeight() == tall,
		"and dressing the window twice does not grow it twice (" ..
		tostring(cf:GetHeight()) .. " against " .. tostring(tall) .. ")")
end

print("== panels: the band carries the chrome, and the body starts under it ==")
do
	local W = A.Widgets
	local PN = A:GetModule("panels")

	-- AND A WINDOW THAT LAYS ITSELF OUT IS TOLD THE PADDING. The game menu is
	-- a VerticalLayoutFrame: its buttons are placed by the client from
	-- layoutIndex and re-placed on every show, so moving one is undone before
	-- you see it - which is why its first button sat across the hairline.
	local gm = _G.GameMenuFrame
	check(gm.topPadding == gm.__aetherHeadH + W.PANEL_PAD + W.WELL_PAD,
		"it is handed a top padding that clears the band and the body (" ..
		tostring(gm.topPadding) .. ")")
	-- AND LAYING THE WINDOW OUT IS WHAT RUNS IT. A VerticalLayoutFrame reads
	-- its padding when it lays out and only lays out when told to, so a number
	-- written into the table and never read is a gap that is not on screen.
	local before = gm.__layoutRuns
	PN.LayoutBody(gm, PN.ENTRY.GameMenuFrame)
	check(gm.__layoutRuns > before,
		"and laying the body out re-runs it, rather than leaving the number in"
		.. " a table nobody has read (" .. tostring(gm.__layoutRuns - before)
		.. ")")
	check((gm.__menuButtons[1].__layoutY or 0) <= -gm.topPadding,
		"so the first button lands under the hairline rather than on it (" ..
		tostring(gm.__menuButtons[1].__layoutY) .. ")")
end

print("== panels: one header band, and two rails that do not cross ==")
do
	local W = A.Widgets
	local PN = A:GetModule("panels")

	-- EVERY PANEL WEARS THE SAME BAND. The client's windows had none of it -
	-- each put its title wherever its own art wanted it, and nothing separated
	-- the title from what was under it.
	local bare = {}
	for _, name in ipairs({ "CharacterFrame", "SpellBookFrame", "MerchantFrame",
		"GossipFrame", "MailFrame" }) do
		local f = _G[name]
		if f and f.__aetherPanel and not f.__aetherHeadRule then
			bare[#bare + 1] = name
		end
	end
	check(#bare == 0,
		"every window has a hairline along the foot of its header (" ..
		(#bare > 0 and table.concat(bare, ", ") or "all of them") .. ")")

	-- AND THE TITLE IS CENTRED IN IT, on every one. The spellbook's sat six
	-- pixels right of centre because the page it was printed on was not centred
	-- in the frame either.
	local off = {}
	for _, name in ipairs({ "SpellBookFrame", "MerchantFrame", "GossipFrame" }) do
		local f = _G[name]
		local t = f and f.__aetherTitle
		if t then
			local pt, rel, _, x = t:GetPoint(1)
			-- Off the GLASS, which is the window you can see - the frame is
			-- wider than that and centring on it is centring on the margins.
			if not (pt == "TOP" and rel == f.__aetherPanel and x == 0) then
				off[#off + 1] = name .. ":" .. tostring(pt) .. "/" .. tostring(x)
			end
		end
	end
	check(#off == 0,
		"and its title centred in the window rather than where its own art"
		.. " wanted it (" .. (#off > 0 and table.concat(off, ", ") or "all"
		.. " centred") .. ")")

	-- A TALLER BAND WHERE THERE IS A SUBTITLE, which is the one variation.
	-- A character sheet says who you are and then what you are, and the second
	-- line needs somewhere to be.
	check(PN.HeaderHeight("CharacterFrame") == W.PANEL_HEAD_SUB
		and PN.HeaderHeight("MerchantFrame") == W.PANEL_HEAD_H,
		"a window with a subtitle gets the taller header and one without does"
		.. " not (" .. PN.HeaderHeight("CharacterFrame") .. " / " ..
		PN.HeaderHeight("MerchantFrame") .. ")")
	local sp, srel, srelP = _G.CharacterLevelText:GetPoint(1)
	check(srel == _G.CharacterNameText and sp == "TOP" and srelP == "BOTTOM",
		"with the class line hung under the name rather than placed on its own")

	-- AND NOT JAMMED AGAINST IT. The handoff's one pixel is a number about
	-- 12pt type in a browser; at these sizes the descenders of the name and
	-- the caps of the line under it touched.
	local _, _, _, _, sy = _G.CharacterLevelText:GetPoint(1)
	check(sy <= -3,
		"and given room to breathe under it (" .. tostring(sy) .. ")")

	-- THE HAIRLINE IS CHROME, and it is drawn above everything.
	--
	-- It was a texture of the WINDOW first, and a frame's own textures draw
	-- under its children, so the glass painted over it on every panel. Moving
	-- it onto the glass fixed the windows whose content starts below the band
	-- and not the ones whose content starts inside it - the client's panes are
	-- children of the window too. The vendor window lost its hairline that way
	-- while the character sheet kept one.
	local cf = _G.CharacterFrame
	check(cf.__aetherHeadRule:GetParent() == cf.__aetherChrome,
		"the hairline hangs off a layer of its own rather than off the glass")
	check(cf.__aetherChrome:GetFrameLevel()
		> _G.PaperDollFrame:GetFrameLevel(),
		"which sits above the client's own panes, so nothing it draws can cover"
		.. " the band (" .. cf.__aetherChrome:GetFrameLevel() .. " against " ..
		_G.PaperDollFrame:GetFrameLevel() .. ")")
	check(cf.__aetherHeadRule:GetHeight() > 0
		and cf.__aetherHeadRule:GetHeight() <= 2,
		"and it is a hairline - one pixel, not nothing and not a band (" ..
		tostring(cf.__aetherHeadRule:GetHeight()) .. ")")

	-- THE PET TAB NAMES THE PET. The window is one frame with five panes in
	-- it, and the band was left saying who YOU are while the pane under it was
	-- showing somebody else's portrait, level and family.
	-- Driven THROUGH the client's own tab call, because that is the only
	-- thing that tells us a tab changed - reaching in and redrawing the header
	-- ourselves proves the header and not the wiring.
	_G.PaperDollFrame:Hide()
	_G.PetPaperDollFrame:Show()
	_G.PanelTemplates_UpdateTabs(cf)
	local pPt, pRel, pRelP = _G.PetNameText:GetPoint(1)
	check(pPt == "TOP" and pRel == cf.__aetherPanel and pRelP == "TOP",
		"the pet's name is placed as the window's title while its tab is up")
	check(_G.PetNameText._aetherStyle == "pnTitle"
		and _G.PetLevelText._aetherStyle == "pnSub",
		"in the header's own type, title and subtitle both")
	local _, petSize = _G.PetNameText:GetFont()
	local _, gossipSize2 = _G.GossipFrameTitleText:GetFont()
	check(petSize == gossipSize2,
		"at the same size as every other title in the interface - the point" .. " every client string here gets is for text sitting in the client's" .. " own rows, and a title has the window to itself (" .. tostring(petSize).. " against " .. tostring(gossipSize2) .. ")")
	local _, plRel = _G.PetLevelText:GetPoint(1)
	check(plRel == _G.PetNameText,
		"with its level and family hung under it exactly as the class line is")

	-- ...and hands it straight back.
	_G.PetPaperDollFrame:Hide()
	_G.PaperDollFrame:Show()
	_G.PanelTemplates_UpdateTabs(cf)
	local bPt, bRel = _G.CharacterNameText:GetPoint(1)
	check(bPt == "TOP" and bRel == cf.__aetherPanel,
		"and your own name comes back when you leave the tab")

	-- THE TWO RAILS DO NOT CROSS. They are the same hairline at ninety degrees
	-- to each other, and running one through the other draws a cross in the
	-- corner of the window - a join that is joining nothing.
	local sb = _G.SpellBookFrame
	-- ITS BOOK TABS START HIDDEN and the client shows the ones that apply from
	-- its own update, so the foot rail is not laid out until that has run.
	sb:Show()
	sb:Update()
	local side = sb.__aetherRails["RIGHT"]
	local foot = sb.__aetherRails["BOTTOM"]
	local _, frel, frelP = foot:GetPoint(2)
	check(frel == side and frelP == "BOTTOMLEFT",
		"the foot rail stops at the column rather than running under it (" ..
		tostring(frelP) .. ")")

	-- AND THE COLUMN RUNS THE HEIGHT OF THE WINDOW. It used to be only as long
	-- as the icons on it, which is an argument about a WASH - and there is no
	-- wash. A hairline that stops halfway down is a line that has been cut off.
	local tp, trel = side:GetPoint(1)
	local bp, brel = side:GetPoint(2)
	check(tp == "TOPRIGHT" and trel == sb and bp == "BOTTOMRIGHT"
		and brel == sb,
		"the column is pinned top and bottom to the window (" .. tostring(tp)
		.. " / " .. tostring(bp) .. ")")

	-- ...BUT NEVER OVER THE HEADER. The title and the way out run the full
	-- width of the frame, exactly as they do on a window with no column.
	local _, _, _, _, ty = side:GetPoint(1)
	check(ty <= -PN.HeaderHeight("SpellBookFrame"),
		"starting below the header rather than beside it (" .. tostring(ty) ..
		" against a header of " .. PN.HeaderHeight("SpellBookFrame") .. ")")

	-- And on a window with no column at all, the foot rail runs the full width.
	local mf = _G.MerchantFrame
	local mfoot = mf.__aetherRails["BOTTOM"]
	local _, mrel = mfoot:GetPoint(2)
	check(mrel == mf,
		"with nothing to stop at, it reaches the window's own edge")

	-- AND PUT THE BOOK BACK. Its tabs start hidden and a later block checks
	-- exactly that, so bringing it up here must not be what un-hides them.
	for i = 1, 3 do
		local t = _G["SpellBookFrameTabButton" .. i]
		if t then t:Hide() end
	end
	sb:Hide()
end

print("== panels: content sits in a well, and the well owns the scrolling ==")
do
	local W = A.Widgets

	-- CONTENT FLOATING IN CHROME was the complaint, and it was fair: every
	-- list, grid and page in this interface scrolled inside a bare frame with
	-- nothing marking where it began or ended, and no bar at all to say how far
	-- down you were. W.Scroller had no scrollbar in it.
	local wells = {}
	local scrollers = {
		{ "the bag grid", Bg.frames.bags.scroll },
		{ "the quest list", A:GetModule("questlog").win.list.scroll },
		{ "the quest detail", A:GetModule("questlog").win.detail.scroll },
	}
	for _, pair in ipairs(scrollers) do
		local sc = pair[2]
		if not (sc and sc.well and sc.bar) then
			wells[#wells + 1] = pair[1]
		end
	end
	check(#wells == 0,
		"everything that scrolls sits in a recess with a bar (" ..
		(#wells > 0 and table.concat(wells, ", ") or "all of them") .. ")")

	local sc = Bg.frames.bags.scroll
	check(sc.well._fillToken == "wellFill"
		and sc.well._edgeToken == "wellEdge",
		"the recess is a token rather than a colour, so a skin reaches it")
	check(sc.well:GetFrameLevel() < sc:GetFrameLevel(),
		"and it draws BELOW what it holds - it is a sibling of the scroll frame"
		.. " rather than its parent, because a ScrollFrame clips its child and a"
		.. " recess inside that clip would be cut off with the content")

	-- THE BAR HUGS THE WELL'S EDGE FROM THE INSIDE, which is what stops it
	-- reading as floating: it is measured against a border you can see.
	sc:SetHeight(100)
	sc.child:SetHeight(400)
	sc:SetVerticalScroll(0)
	check(sc:Measure() == true, "a list longer than its view raises the bar")
	-- IN THE GUTTER BETWEEN THE SCROLL FRAME AND THE WELL'S RIM, which is the
	-- one strip with nothing in it. Inset from the SCROLL frame's own right
	-- edge - which is what it was - put it over the last few pixels of every
	-- row in the quest log's list.
	local bp, brel, brelP, bx = sc.bar:GetPoint(1)
	check(bp == "TOPLEFT" and brel == sc and brelP == "TOPRIGHT" and bx > 0,
		"the bar sits OUTSIDE the content, in the well's gutter (" ..
		tostring(bp) .. " -> " .. tostring(brelP) .. " x=" .. tostring(bx) ..
		")")
	check(bx + 4 <= sc.__aetherGutter,
		"and inside the rim rather than through it (" .. tostring(bx) ..
		" + 4 in a gutter of " .. tostring(sc.__aetherGutter) .. ")")

	-- AND THE GUTTER WIDENS FOR A CALLER WHO ASKED FOR LESS THAN THE BAR
	-- NEEDS. The console's library asks for two, because it is a narrow drawer
	-- whose list already sits ten from the frame edge - and two is not a
	-- gutter, it is a hairline with a bar drawn through it.
	local narrow = A.IFEC and A.IFEC.Library and A.IFEC.Library.frame
		and A.IFEC.Library.frame.list
	if narrow then
		check(narrow.__aetherGutter >= 8,
			"a well too narrow on that side is widened to hold one (" ..
			tostring(narrow.__aetherGutter) .. " from the 2 it asked for)")
	end
	check(sc.bar:GetWidth() == 4,
		"four pixels of it (" .. tostring(sc.bar:GetWidth()) .. ")")

	-- AS TALL A FRACTION OF THE TRACK AS THE VIEW IS OF THE CONTENT, and as
	-- far down it as you are through the list. A thumb that is always the same
	-- size tells you where you are and not how much there is.
	local quarter = sc.bar:GetHeight()
	check(math.abs(quarter - 25) < 0.5,
		"a quarter of the content in view makes a quarter-height thumb (" ..
		string.format("%.1f", quarter) .. " of 100)")
	local _, _, _, _, topY = sc.bar:GetPoint(1)
	sc:SetVerticalScroll(300)
	sc:Measure()
	local _, _, _, _, botY = sc.bar:GetPoint(1)
	check(botY < topY and math.abs(botY + (100 - quarter)) < 0.5,
		"and at the end of the list it is at the end of the track (" ..
		string.format("%.1f", botY) .. ")")

	-- IT IS NOT THERE WHILE YOU READ. Present while you are moving, gone about
	-- a second after you stop - a bar permanently up is furniture.
	sc.bar:SetAlpha(0)
	sc:Flash()
	check(sc.bar:GetAlpha() == 1, "scrolling brings it up")
	local drive = sc:GetScript("OnUpdate")
	check(drive ~= nil, "and starts it counting down")
	drive(sc, 0.5)
	check(sc.bar:GetAlpha() == 1,
		"half a second later it is still up, because you may not have finished")
	for _ = 1, 20 do
		local fn = sc:GetScript("OnUpdate")
		if not fn then break end
		fn(sc, 0.1)
	end
	check(sc.bar:GetAlpha() == 0 and sc:GetScript("OnUpdate") == nil,
		"and then it fades out and stops polling")

	-- AND THERE IS NO BAR WHEN THERE IS NOTHING TO SCROLL.
	sc.child:SetHeight(50)
	check(sc:Measure() == false, "a list that fits raises none")
	check(not sc.bar:IsShown(), "and the bar is not merely transparent")

	-- A BUTTON YOU CANNOT PRESS IS STILL A BUTTON YOU CAN READ. Share dimmed
	-- the whole FRAME to 0.4, which multiplies the label as well - and an
	-- outline button's label is already the dim ink, so 0.55 by 0.4 came out at
	-- 0.22 and the word vanished over anything bright. Share is off more often
	-- than it is on: you have to be grouped for it.
	do
		local b = A:GetModule("questlog").win.detail.foot.share
		b:SetDisabled(true)
		check(b:GetAlpha() == 1,
			"a disabled button is not dimmed as a whole frame (" ..
			string.format("%.2f", b:GetAlpha()) .. ")")
		local a = select(4, b.label:GetTextColor())
		check(a >= A.Palette.c.textFaint[4] - 0.001,
			"its word goes faint instead, which is still a word (" ..
			string.format("%.2f", a) .. ")")
		b:SetDisabled(false)
		local on = select(4, b.label:GetTextColor())
		check(on > a, "and comes back when it can be pressed")
	end

	-- A SEARCH FIELD IS A ROUNDED RECTANGLE, not a capsule. A pill's two caps
	-- come out of a 256-texel texture and at thirty pixels tall they are
	-- minified more than eight times with no mipmap behind them, which is the
	-- crunch on the ends of both of these. Same fix the chat tabs carry.
	local fields = {}
	for _, pair in ipairs({
		{ "the quest log", A:GetModule("questlog").win.head.search },
		{ "the bags", Bg.frames.bags.search },
	}) do
		if pair[2]._kind ~= "panel" then fields[#fields + 1] = pair[1] end
	end
	check(#fields == 0,
		"both search fields are drawn as panels rather than capsules (" ..
		(#fields > 0 and table.concat(fields, ", ") or "both") .. ")")

	-- AND THE BUTTONS CLEAR THE READING. The description's well used to stop
	-- two pixels above the row of actions, which reads as the buttons being
	-- part of the description rather than what you do about it.
	local d = A:GetModule("questlog").win.detail
	-- THE WELL'S OWN EDGE, not the scroll frame's - the recess reaches below
	-- the frame it holds, and it is the rim you can see that has to clear the
	-- buttons.
	local _, _, _, _, scrollBottom = d.scroll:GetPoint(2)
	local _, _, _, _, footTop = d.foot:GetPoint(1)
	local wellBottom = scrollBottom - d.scroll.well.__aetherWellOut
	local gap = wellBottom - (footTop + d.foot:GetHeight())
	check(gap >= W.PANEL_GAP,
		"the reading well's own edge stops a block's gap above the buttons ("
		.. tostring(gap) .. " of " .. W.PANEL_GAP .. ")")

	-- AND THERE IS NO SECOND LINE ACROSS THE FOOT OF IT. There was a rule
	-- above the buttons, and with the description in a well of its own the two
	-- draw as a doubled hairline with a sliver between them.
	check(d.foot.rule == nil,
		"with no rule of its own above them - the well's edge is the line")

	-- THE MORE-BELOW HINT. A gradient at the foot of the well, so a list that
	-- runs past the bottom says so without a bar having to be up.
	sc.child:SetHeight(400)
	sc:SetVerticalScroll(0)
	sc:Measure()
	check(sc.fade:IsShown(), "with more below, the foot of the well fades")
	sc:SetVerticalScroll(300)
	sc:Measure()
	check(not sc.fade:IsShown(),
		"and at the end it does not - a shadow over the last row for no reason"
		.. " is a list that always looks unfinished")
end

print("== surfaces: a capsule is drawn the way its size can carry ==")
do
	-- THE SAME FAULT, FOUND FOUR TIMES. A pill is a 3-slice out of a 512x256
	-- texture whose two caps are 128 texels wide, drawn at half the pill's
	-- height - so at twenty tall that is a twelvefold minification of a curve
	-- with no mipmap behind it, and the ends come back jagged.
	--
	-- The chip rim found it, then the check box, then the tooltip badge, then
	-- the chat tab, and each one fixed it locally as a local surprise, because
	-- nothing anywhere said where the line was. This is that line, and it is
	-- held against EVERY surface the addon has ever built rather than against
	-- the handful anybody thought to look at.
	local floor = A.Glass.PILL_ART_MIN
	local jagged, seen = {}, 0
	for _, f in ipairs(A.Glass.surfaces) do
		if f._kind == "pill" then
			seen = seen + 1
			local h = f.GetHeight and f:GetHeight() or 0
			-- `_art` is WHICH TEXTURE it is drawn from. A capsule under the
			-- floor must be drawn from the small one, not renamed.
			if h > 0 and h < floor and f._art ~= "small" then
				jagged[#jagged + 1] = string.format("%.0f", h)
			end
		end
	end
	check(#jagged == 0,
		"no capsule anywhere is drawn below the height its art can carry (" ..
		floor .. "; " .. (#jagged > 0 and (#jagged .. " of " .. seen ..
		" at " .. table.concat(jagged, ", ")) or (seen .. " checked")) .. ")")

	-- AND THE COMPONENT PICKS FOR YOU. Below the line the same shape comes
	-- out of the panel art with its corner at half the height - which is what
	-- a capsule is - and that corner IS snapped to whole physical pixels.
	local host = CreateFrame("Frame", nil, UIParent)
	local cap = A.Glass.CreatePill(host, {})
	cap:SetSize(80, 20)
	check(cap._art == "small"
		and cap._fill[1]:GetTexture() == A.Media.texture.pillSmall,
		"asked for one under the floor, the component draws the small art (" ..
		tostring(cap._art) .. ")")
	check(#cap._fill == 3,
		"and it is still a three-slice capsule - ONE geometry, two textures. It"
		.. " was briefly a nine-slice panel with its corner at half the height,"
		.. " which is the same shape on paper: Layout9 anchors the top and bottom"
		.. " corner pieces to opposite edges, so half the height makes them meet"
		.. " and any rounding makes them OVERLAP - a doubled rim in a band"
		.. " through the middle, which is a bright line across every chip")

	-- AND THE HALF-TEXEL INSET GOES WITH THE TEXTURE. It is computed from the
	-- source dimensions and these differ by a factor of four; left alone, the
	-- small art is sampled a quarter-texel wrong at every join.
	local l1 = select(2, cap._fill[1]:GetTexCoord())

	-- IT DECIDES AGAIN ON EVERY RESIZE. Most of these are built at a default
	-- and sized afterwards, so a decision taken once at creation is a decision
	-- taken on a height the pill never had.
	cap:SetSize(80, 60)
	check(cap._art == "big"
		and cap._fill[1]:GetTexture() == A.Media.texture.pill,
		"and grown past it, the large art comes back (" ..
		tostring(cap._art) .. ")")
	local l2 = select(2, cap._fill[1]:GetTexCoord())
	check(l1 ~= l2,
		"with its own half-texel inset (" .. string.format("%.5f", l1) ..
		" / " .. string.format("%.5f", l2) .. ")")
	cap:SetSize(80, 20)
	check(cap._art == "small", "and shrunk again, so does the other")
end

print("== panels: one frame, one header, one way out ==")
do
	local W = A.Widgets

	-- FOUR SETS OF NUMBERS FOR ONE ANATOMY. The corner radius alone was 16 on
	-- the client's windows, 20 on the party controls and 28 on the bags, the
	-- quest log and the Toolbox - three answers to a question with one, and
	-- nobody can see all three at once to notice.
	local corners, want = {}, W.PANEL_CORNER
	local panels = {
		{ "the bags", Bg.frames.bags },
		{ "the quest log", A:GetModule("questlog").win },
		{ "the character sheet", _G.CharacterFrame.__aetherPanel },
		{ "the Toolbox drawer", A:GetModule("toolbox").panel },
		{ "the party controls", A:GetModule("partyframes").panel },
	}
	for _, pair in ipairs(panels) do
		local f = pair[2]
		if f and f._corner and f._corner ~= want then
			corners[#corners + 1] = pair[1] .. " " .. tostring(f._corner)
		end
	end
	check(#corners == 0,
		"every framed panel takes the same corner (" .. want .. (#corners > 0
		and (" - " .. table.concat(corners, ", ")) or "") .. ")")

	-- ONE WAY OUT. There were four: a bare multiplication sign on the client's
	-- own button, a 22px one on the quest log, an 18px one on the Toolbox and
	-- an icon button on the bags - four hit targets, four hover behaviours and
	-- four sizes of cross, none of which agree.
	local closes = {
		{ "the bags", Bg.frames.bags.head.close },
		{ "the quest log", A:GetModule("questlog").win.head.close },
		{ "the character sheet", _G.CharacterFrameCloseButton },
	}
	local odd = {}
	for _, pair in ipairs(closes) do
		local b = pair[2]
		if not (b and b.__aetherClose) then
			odd[#odd + 1] = pair[1] .. " has none"
		elseif b:GetWidth() ~= 28 or b:GetHeight() ~= 28 then
			odd[#odd + 1] = pair[1] .. " " .. tostring(b:GetWidth())
		end
	end
	check(#odd == 0,
		"and the same way out, at the same hit size (" .. (#odd > 0 and
		table.concat(odd, ", ") or "28 square everywhere") .. ")")

	-- IT LIGHTS UP UNDER THE CURSOR, and it is chrome rather than an action -
	-- so it wears nothing at rest and washes softly on hover, the way a tab
	-- does. A close that looks pressable competes with the buttons that are.
	local cb = Bg.frames.bags.head.close
	check(cb.__aetherCloseWash:GetAlpha() == 0,
		"at rest it is a cross and nothing else")
	cb:GetScript("OnEnter")(cb)
	check(cb.__aetherCloseWash:GetAlpha() == 1,
		"and a wash comes up behind it under the cursor")
	cb:GetScript("OnLeave")(cb)
	check(cb.__aetherCloseWash:GetAlpha() == 0, "and goes again")

	-- ONE TITLE SIZE for every panel, and 16 is the ceiling. It was 18 here
	-- with a point added on top of it for the client's windows, which is 19.
	local titleSize = (A.Media.style["pnTitle"] or {})[2]
	check(titleSize == 16,
		"a panel title is 16 and never larger (" .. tostring(titleSize) .. ")")
	local _, drawn = _G.CharacterFrameTitleText:GetFont()
	check(drawn and drawn <= 16,
		"including on the client's own windows, which used to add a point on"
		.. " top of it (" .. tostring(drawn) .. ")")

	-- AND THE CROSS IS ITS OWN ROLE, drawn at its own size. Hung off the title
	-- role it grew and shrank with a heading it has nothing to do with - so
	-- the size is what is read here, not the name: a role that does not exist
	-- still leaves the name recorded on the string.
	local _, crossSize = cb.__aetherClose:GetFont()
	check(cb.__aetherClose._aetherStyle == "pnClose" and crossSize == 16,
		"the cross has a role of its own, at its own size (" ..
		tostring(crossSize) .. ")")
end

print("== tabs: one language, and it is not the button's ==")
do
	local W = A.Widgets
	-- A BUTTON DOES A THING; A TAB CHANGES WHICH VIEW OF THE FRAME YOU ARE
	-- LOOKING AT. Four tabbed surfaces here drew the second as the first - the
	-- same filled accent pill that Create, Send and Accept wear - so the only
	-- thing telling them apart was knowing which was which already.
	--
	-- The pattern is bare text on a shared hairline, with a 2px accent mark on
	-- that line under the one you are on. This block checks the language
	-- itself; the surfaces that speak it are checked where they live.
	local host = CreateFrame("Frame", nil, UIParent)
	host:SetSize(200, 40)

	local rail = W.TabRail(host, "BOTTOM")
	check(rail ~= nil and host.__aetherRails["BOTTOM"] == rail,
		"a rail is made once and kept on its host")
	check(W.TabRail(host, "BOTTOM") == rail,
		"so asking again is a re-layout rather than a second rail")

	-- WHICH EDGE FACES THE CONTENT is the whole of the placement rule. A rail
	-- along the bottom of a panel has its line and its marks on its TOP,
	-- because that is the side the panel is on; chat's rail is on top and all
	-- of it mirrors. Backwards, a tab reads as attached to the world.
	check(rail.rule:GetPoint(1) == "TOPLEFT",
		"a bottom rail's hairline is on its top (" ..
		tostring(rail.rule:GetPoint(1)) .. ")")
	-- ONE RAIL PER EDGE, not one per host. The spellbook carries TWO - the
	-- schools down its right side and the books along its foot - and they were
	-- sharing a frame: whichever was laid out last re-pointed it, and the other
	-- set of tabs was left chained to a rail that had become the other rail. On
	-- screen that is the school column hanging below the window on the first
	-- dress, and the book tabs in the middle of it after a click.
	local top = W.TabRail(host, "TOP")
	check(top ~= rail,
		"a second edge gets a rail of its own rather than re-pointing the first")
	check(rail.rule:GetPoint(1) == "TOPLEFT",
		"which leaves the first where it was (" ..
		tostring(rail.rule:GetPoint(1)) .. ")")
	check(top.rule:GetPoint(1) == "BOTTOMLEFT",
		"and a top rail's line is on its bottom (" ..
		tostring(top.rule:GetPoint(1)) .. ")")

	-- THE WASH IS MANDATORY ON A VERTICAL RAIL and absent on a horizontal one.
	-- It is the only thing saying a column of pictures is one control rather
	-- than a handful of loose buttons; a row of words has the hairline.
	-- NO WASH ON EITHER ORIENTATION. The handoff calls the vertical rail's
	-- mandatory, on the argument that it is the only thing saying a column of
	-- pictures is one control - and that argument is written against a FLAT
	-- background. Ours is frosted glass: a wash lands on a fill that is
	-- already semi-transparent and doubles it locally, so four per cent of
	-- lilac came out as a slab down the side of the spellbook. The hairline
	-- runs the length of the column and gathers it, which is exactly how the
	-- horizontal rail gathers a row of words. One mechanism for both.
	check(not rail.tint:IsShown(), "a row of words gets no wash")
	local side = W.TabRail(host, "RIGHT")
	check(not side.tint:IsShown(),
		"and neither does a column of icons - the hairline is the grouping,"
		.. " here as everywhere else")
	check(side.rule:GetPoint(1) == "TOPLEFT",
		"with its line on the side facing the content")
	W.TabRail(host, "RIGHT", { tint = true })
	check(side.tint:IsShown(),
		"though a caller that wants one may still ask")
	W.TabRail(host, "RIGHT")

	-- A TAB, and what it is made of.
	W.TabRail(host, "BOTTOM")
	local tab = CreateFrame("Button", nil, host)
	tab:SetSize(60, 38)
	local label = tab:CreateFontString(nil, "OVERLAY")
	label:SetFont("Fonts\\FRIZQT__.TTF", 12, "")
	label:SetText("Character")
	-- THE RAIL IS HANDED OVER, never looked up off the parent. Nothing here
	-- promises a tab is a child of the frame that owns its rail, and on the
	-- spellbook it is not: the schools hang off SpellBookSideTabsFrame, a
	-- full-window frame of Blizzard's that exists only to hold them.
	W.Tab(tab, { label = label, rail = rail })

	check(tab.__aetherMark ~= nil and tab.__aetherDot ~= nil,
		"a tab gets a mark and an attention dot")
	check(tab.__aetherSkin == nil,
		"and NO button surface - which is the whole of the distinction")

	W.TabState(tab, false, false)
	check(not tab.__aetherMark:IsShown(),
		"unselected, it carries nothing at all")
	local faint = select(4, label:GetTextColor())
	W.TabState(tab, false, true)
	local dim = select(4, label:GetTextColor())
	local hoverA = select(4, tab.__aetherWash:GetVertexColor())
	check(hoverA > 0 and hoverA < 0.15,
		"a hovered tab washes faintly - it is a hint, not a fill (" ..
		string.format("%.3f", hoverA) .. ")")
	check(tab.__aetherWash:IsShown() and dim > faint,
		"hovered, the word brightens and a faint wash comes up behind it (" ..
		string.format("%.2f", faint) .. " -> " .. string.format("%.2f", dim) ..
		")")
	W.TabState(tab, true, false)
	local bright = select(4, label:GetTextColor())
	check(tab.__aetherMark:IsShown() and bright > dim,
		"and selected it takes the mark, brightest of the three (" ..
		string.format("%.2f", bright) .. ")")
	W.TabState(tab, true, true)
	check(not tab.__aetherWash:IsShown() and tab.__aetherMark:IsShown(),
		"and hovering the tab you are ALREADY on adds no wash - the mark is"
		.. " the signal, and two signals for one state is one too many")
	W.TabState(tab, true, false)

	-- THREE POINTS, FROM TWO FRAMES. The two that fix its LENGTH are the
	-- tab's, because the mark is as long as the thing it marks; the one that
	-- fixes WHICH LINE it sits on is the rail's, because that is the line.
	--
	-- They were the same frame for a row of words, where each tab is the full
	-- height of its rail - and not the same frame for a column of icons, where
	-- a 32px picture in a 44px rail leaves six either side. On the spellbook's
	-- schools that drew the mark stuck to the icon rather than on the rail.
	local mp, mrel, mrelP, mx = tab.__aetherMark:GetPoint(1)
	check(mp == "LEFT" and mrel == tab and mrelP == "LEFT" and mx == 5,
		"the mark is as long as its tab, less an inset at each end (" ..
		tostring(mp) .. " x=" .. tostring(mx) .. ")")
	local lp, lrel, lrelP = tab.__aetherMark:GetPoint(3)
	check(lp == "TOP" and lrel == rail and lrelP == "TOP",
		"and it sits on the RAIL's content-facing edge rather than the tab's ("
		.. tostring(lp) .. " -> " .. tostring(lrelP) .. ")")
	check(tab.__aetherMark:GetHeight() == 2,
		"two pixels of it")

	-- A VERTICAL TAB TURNS THE SAME MARK ON ITS SIDE, and takes the same rule
	-- with it: length from the icon, line from the rail.
	W.TabRail(host, "RIGHT")
	W.Tab(tab, { label = label, edge = "RIGHT", rail = side })
	W.TabState(tab, true, false)
	local vp, vrel = tab.__aetherMark:GetPoint(1)
	local vf, vfrel, vfrelP = tab.__aetherMark:GetPoint(3)
	check(vp == "TOP" and vrel == tab and tab.__aetherMark:GetWidth() == 2,
		"its length still comes from the icon (" .. tostring(vp) .. ")")
	check(vf == "LEFT" and vfrel == side and vfrelP == "LEFT",
		"and it stands on the rail's own left edge, not the icon's - which is"
		.. " six pixels further in and reads as a bar glued to the picture (" ..
		tostring(vf) .. ")")

	-- A PICTURE'S HOVER IS THE PICTURE COMING BACK - full colour, full
	-- strength - and a wash behind it as well is a second answer to the same
	-- question, laid over a rail that is already washed.
	W.Tab(tab, { icon = true, edge = "RIGHT", rail = side })
	W.TabState(tab, false, true)
	check(not tab.__aetherWash:IsShown(),
		"a hovered ICON takes no wash of its own")
	W.Tab(tab, { label = label, edge = "RIGHT", rail = side })
	W.TabRail(host, "BOTTOM")
	W.Tab(tab, { label = label, edge = "BOTTOM", rail = rail })

	-- ATTENTION: an accent dot for ordinary traffic, the RESERVED GOLD for
	-- something addressed to you. Never a flashing fill, which is what the
	-- client does and what this replaces.
	W.TabDot(tab, nil)
	check(not tab.__aetherDot:IsShown(), "no dot until something arrives")
	W.TabDot(tab, "new", label)
	local dr = { tab.__aetherDot:GetVertexColor() }
	check(tab.__aetherDot:IsShown()
		and math.abs(dr[1] - A.Palette.c.accent[1]) < 0.01,
		"ordinary traffic takes the accent")
	W.TabDot(tab, "personal", label)
	local gr = { tab.__aetherDot:GetVertexColor() }
	check(math.abs(gr[1] - A.Palette.c.semanticGold[1]) < 0.01,
		"and something addressed to you takes the reserved gold, the way every"
		.. " other personal signal in this interface does")
	local dp, drel = tab.__aetherDot:GetPoint(1)
	check(dp == "LEFT" and drel == label,
		"sitting after the word rather than over it")

	-- A SKIN CHANGE REACHES IT, because every colour above is a token.
	local wasSkin = A.db.profile.skin
	A.Palette:Apply("dusk")
	W.TabState(tab, true, false)
	local after = { tab.__aetherMark:GetVertexColor() }
	check(math.abs(after[1] - A.Palette.c.accent[1]) < 0.01,
		"the mark follows a skin change on its own")
	A.Palette:Apply(wasSkin or "midnight")
end

print("== panels: the client's windows in our glass ==")
do
	local PNm = A:GetModule("panels")

	local cf = _G.CharacterFrame
	check(cf.__aetherPanel ~= nil, "the character sheet has a glass panel behind it")
	check(cf.__stone:GetTexture() == 0, "and its stone frame is cleared")
	check(cf.Bg.__fill:GetTexture() == 0,
		"including the background in its child frame, which is where these keep"
		.. " the thing you can actually see")
	check(cf.TitleContainer.__bar:GetTexture() == 0,
		"and the stone band behind the title, which hangs off a TitleContainer -"
		.. " the game menu's Header under a second name. On the help window that"
		.. " band was the last thing left drawing on the whole frame")
	-- THIS WINDOW'S TITLE IS THE NAME, not the frame's own $parentTitleText -
	-- which it never fills in. The panel list names it, so the shell dresses
	-- and places it like any other window's.
	check(cf.__aetherTitle == _G.CharacterNameText,
		"the window's title is the character's name")
	check(cf.__aetherTitle._aetherStyle == "pnTitle",
		"re-roled into our type")

	-- OUTLINED, unlike our own panels' type. These labels sit over whatever the
	-- window is showing - a paper doll, a talent tree's artwork, a map - rather
	-- than over an even fill of ours, and an unoutlined word on that reads as
	-- smudged.
	-- NOT OUTLINED, and it used to be. The argument was that these labels sit
	-- over the window's own contents rather than over a fill of ours - true of
	-- the stone windows, and untrue the moment the art came off. What they sit
	-- over now is our glass, like every other string in this interface, and
	-- nothing else here is outlined.
	local _, _, titleFlags = _G.CharacterFrameTitleText:GetFont()
	check(titleFlags == "",
		"and NOT outlined - it sits on our own glass now, and a stroke round it"
		.. " is a thing this interface does nowhere else ("
		.. tostring(titleFlags) .. ")")

	local close = _G.CharacterFrameCloseButton
	check(close.__aetherClose and (close.__aetherClose:GetText() or "") ~= "",
		"and the way out is our own mark - with the stone X cleared there would"
		.. " otherwise be nothing left to click")
	check(close:GetNormalTexture():GetTexture() == 0, "its art gone with the rest")
	check(close:GetParent() == cf,
		"on the client's own button, which is still the thing that closes the"
		.. " window - nothing here is rebuilt or reparented")

	-- THE INSIDES. A window is mostly not a window: the character sheet is item
	-- slots, tabs, bars, lists and check boxes, and a shell in our glass with
	-- Blizzard's stone furniture inside it is the worse of the two looks.
	local head, neck = _G.CharacterHeadSlot, _G.CharacterNeckSlot

	check(head.__aetherSlot == true, "an equipment slot wears our cell")
	check(head:GetNormalTexture():GetTexture() == 0, "its stone border cleared")
	check(_G.CharacterHeadSlotIconTexture:GetTexture() == "item-icon-CharacterHeadSlot",
		"and THE ITEM IS STILL IN IT - the icon is a region of the button, so"
		.. " stripping the slot would blank the item and leave the border"
		.. " correctly gone, which is why Reskin.Slot must not strip")

	local hr, hg, hb = head.edge:GetVertexColor()
	local q = _G.ITEM_QUALITY_COLORS[4]
	check(hr == q.r and hg == q.g and hb == q.b,
		"an epic sits in a rim of its own quality")
	local nr, ng, nb = neck.edge:GetVertexColor()
	local e = A.Palette.c.glassEdge
	check(nr == e[1] and ng == e[2] and nb == e[3],
		"and an empty slot keeps the ordinary rim - colouring every slot would"
		.. " make the colour mean nothing")

	-- The rim has to answer the client, not just the dressing. Unequip it.
	_G.__setSlotQuality(1, nil)
	_G.PaperDollItemSlotButton_Update(head)
	hr, hg, hb = head.edge:GetVertexColor()
	check(hr == e[1] and hg == e[2] and hb == e[3],
		"take the item off and the rim follows, because the client repaints a"
		.. " slot whenever its item changes and a rim set once at dress time"
		.. " would keep an epic border around an empty slot")
	_G.__setSlotQuality(1, 4)

	check(_G.CharacterFrameTab1.__aetherTab ~= nil, "a tab gets our pill")
	check(_G.CharacterFrameTab1:GetNormalTexture():GetTexture() == 0
		and _G.CharacterFrameTab1:GetDisabledTexture():GetTexture() == 0,
		"with BOTH its art sets cleared - Blizzard draws a tab in three pieces"
		.. " and keeps a whole second set for the disabled state")
	check(_G.CharacterFrameTab1Text._aetherStyle ~= nil, "and its label in our type")

	check(_G.PaperDollFrame:GetRegions():GetTexture() == 0,
		"the panes inside lose their stone as well")

	check(_G.ReputationBar1.__aetherFill ~= nil, "a reputation bar takes our fill")
	check(_G.ReputationBar1:GetStatusBarTexture():GetTexture() == A.Media.texture.bar,
		"set AFTER the strip, which empties the fill along with everything else")

	local thumb = _G.ReputationListScrollFrameScrollBar:GetThumbTexture()
	check(thumb:GetTexture() == A.Media.texture.flat,
		"a scroll bar's thumb is ours - the one part of a scroll bar anybody"
		.. " actually looks at")

	check(_G.ReputationDetailAtWarCheckbox.__aetherCheck ~= nil,
		"and a check box gets a pill")

	-- MORE ROWS, NOT JUST MORE ROOM. Blizzard builds twelve and reuses them as
	-- you scroll, so a taller window buys nothing: the list still ends twelve
	-- rows down with empty glass under it. The rows come from the client's own
	-- templates and its own update function fills them - we only add to the
	-- pool and say how many there are.
	check(_G.SKILLS_TO_DISPLAY > 12,
		"the skill list grows to fit the window (" .. _G.SKILLS_TO_DISPLAY
		.. " rows, from the client's twelve)")
	check(_G.SkillRankFrame13 ~= nil and _G.SkillTypeLabel13 ~= nil,
		"with real rows behind the number - a count raised over rows that do not"
		.. " exist is an error in the client's own update loop, not a longer list")

	local newPt, newRel, newRelPt, _, newY = _G.SkillRankFrame13:GetPoint(1)
	check(newPt == "TOPLEFT" and newRel == _G.SkillRankFrame12
		and newRelPt == "BOTTOMLEFT",
		"each new row hangs off the one above it, as the client's own do")
	check(_G.SkillRankFrame13.__aetherFill ~= nil,
		"and the rows we added are skinned like the rest")

	-- And it stops at the window. A count larger than the space is the same
	-- bug in the other direction.
	local tallEnough = _G.SKILLS_TO_DISPLAY * 18 + 79 + 78
	check(tallEnough <= cf:GetHeight() + 18,
		"and no more of them than the window can hold ("
		.. _G.SKILLS_TO_DISPLAY .. " x 18 inside " .. cf:GetHeight() .. ")")

	-- THE DISCLOSURE MARKS. Blizzard's stone plus and minus are the last thing
	-- in either tree still drawn by the other interface.
	local header = _G.SkillTypeLabel1
	check(header:GetNormalTexture():GetTexture() == 0,
		"a group header's stone mark is cleared")
	check(header.__aetherGlyph ~= nil, "and ours is drawn instead")
	check(header.__aetherGlyph:GetText() == "\226\136\146",
		"an expanded group shows a minus - the real one, U+2212, because a"
		.. " hyphen beside a full-height plus reads as a dash that lost something")
	check(_G.SkillTypeLabel2.__aetherGlyph:GetText() == "+",
		"and a collapsed one shows a plus")

	-- Where the client's own mark was, not in the middle of the row.
	local gp, grel = header.__aetherGlyph:GetPoint(1)
	check(gp == "CENTER" and grel == header:GetNormalTexture(),
		"drawn on the texture we emptied, which still holds the client's own"
		.. " anchors - a header button is the whole 285px row, so a glyph"
		.. " centred on it lands in the middle of the group's name")

	-- And it survives the client repainting them, which it does on every
	-- expand, every collapse and every scroll.
	_G.SkillFrame_UpdateSkills()
	check(header:GetNormalTexture():GetTexture() == 0
		and header.__aetherGlyph:GetText() == "\226\136\146",
		"and the mark stays ours after the client repaints the list")

	check(_G.ReputationHeader1.__aetherGlyph ~= nil,
		"the reputation tree's headers get the same treatment")

	-- A SCROLL BAR HAS TO SAY IT SCROLLS. A list you can scroll with no visible
	-- sign of it reads as a list that ends where its rows stop.
	local sb = _G.SkillListScrollFrameScrollBar
	check(sb.__aetherTrack ~= nil,
		"a scroll bar keeps a visible rail, not just a thumb")
	local _, _, _, thumbAlpha = sb:GetThumbTexture():GetVertexColor()
	check(thumbAlpha and thumbAlpha > 0.3,
		"with a thumb you can actually see against the glass (" .. tostring(thumbAlpha) .. ")")

	-- "ALL" governs every group in the tree, so it belongs at the head of them,
	-- on the left. The client hangs it off a stone tab out to the right, which
	-- reads as a sibling of the groups rather than their parent.
	local allBtn = _G.SkillFrameCollapseAllButton
	local allPt, allRel, allRelPt, _, allY = allBtn:GetPoint(1)
	check(allPt == "BOTTOMLEFT" and allRel == _G.SkillTypeLabel1 and allRelPt == "TOPLEFT",
		"the All control sits above the first group and shares its left edge,"
		.. " which is what makes it read as their parent")
	check(_G.SkillFrameExpandTabLeft:GetTexture() == 0,
		"and the stone tab it used to hang off is cleared")
	check(_G.CharacterNameText._aetherStyle == "pnTitle",
		"the character's name is re-roled")

	-- THE INSIDE LETTERING. A window in our glass with the client's own font in
	-- every row of it is half a skin.
	local statLabel = _G.CharacterStatFrame1Label
	local labelFont, labelSize, labelFlags = statLabel:GetFont()
	check(labelFont and labelFont:find("Outfit", 1, true) ~= nil,
		"a stat row is in our lettering (" .. tostring(labelFont) .. ")")
	check(labelSize == 10,
		"AT THE CLIENT'S OWN SIZE (" .. tostring(labelSize) .. ") - these sit in"
		.. " rows it measured, so a size of ours reflows somebody else's window")
	check(labelFlags == "", "and unoutlined like the rest of the window")

	-- Nested one deeper, because the client nests these.
	local nestedFont, nestedSize = _G.CharacterStatFrame1StatText:GetFont()
	check(nestedFont and nestedFont:find("Outfit", 1, true) and nestedSize == 12,
		"including the ones a level down inside it (" .. tostring(nestedSize) .. ")")

	-- THE MAIN MENU. Its shell was in glass while every button inside it stayed
	-- a red Blizzard plate, which is the worst of both.
	local opt = _G.GameMenuButtonOptions
	check(opt.__aetherSkin ~= nil, "the main menu's buttons are ours as well")
	check(opt:GetNormalTexture():GetTexture() == 0, "with their own plate cleared")
	check(opt:GetFontString()._aetherStyle ~= nil, "and their lettering re-roled")

	-- Named nowhere: the client's set of these changes between builds, so the
	-- frame is asked what it has.
	check(_G.GameMenuButtonQuit.__aetherSkin ~= nil,
		"every one of them, however many the build happens to have")

	-- ITS TITLE IS SOMEWHERE ELSE. Anything on the shared dialog template keeps
	-- the title inside a Header child, with the ornate stone plate as that
	-- header's BG - not in a global $parentTitleText like the older frames.
	local gmHeader = _G.GameMenuFrame.Header
	check(gmHeader.BG:GetTexture() == 0,
		"the menu's stone title bar is cleared - it hangs off a Header child, so"
		.. " a strip that only knows Border and Bg leaves it standing")
	check(gmHeader.Text._aetherStyle == "pnTitle",
		"and its title is found there and re-roled, rather than missed for want"
		.. " of a $parentTitleText")

	-- That header straddles the frame's top edge ON PURPOSE, so the stone plate
	-- can overhang it. Take the plate away and the words hang over the rim.
	local htPt, htRel, htRelPt, _, htY = gmHeader.Text:GetPoint(1)
	check(htPt == "TOP" and htRel == _G.GameMenuFrame.__aetherPanel
		and htRelPt == "TOP" and htY < 0,
		"and it is brought inside the window (y=" .. tostring(htY) .. ") rather"
		.. " than left hanging over the top edge where the plate used to be")

	check(_G.SkillTypeLabel1:GetFontString()._aetherStyle ~= nil,
		"a skill tree's collapse header is re-roled THROUGH the button - it is a"
		.. " Button carrying a string, answers SetText like a FontString, and"
		.. " has no SetFont, so handing it straight to the font setter took the"
		.. " whole module down with a nil call")

	check(not _G.SkillFrameCancelButton:IsShown()
		and not _G.PetPaperDollCloseButton:IsShown(),
		"the spare Close on the skills list and the one on the pet tab are"
		.. " both gone - the corner already has an X and three of them is two"
		.. " too many")

	-- THE BOX THE DOLL STANDS IN, DRAWN. Without it the model floats in the
	-- window and every asymmetry in it reads as OUR mistake - the imp on the
	-- pet tab looked pushed to the right, and the reason is that its own box,
	-- which the client centres it in, has whitespace on one side that nothing
	-- was marking. With a rim round it the whitespace is plainly whitespace.
	do
		local bare = {}
		for _, name in ipairs({ "CharacterModelFrame", "PetModelFrame",
			"InspectModelFrame" }) do
			local m = _G[name]
			local well = m and m.__aetherModelWell
			if not well then
				bare[#bare + 1] = name
			elseif well._fillToken ~= "wellFill" then
				bare[#bare + 1] = name .. ":" .. tostring(well._fillToken)
			elseif well:GetFrameLevel() >= m:GetFrameLevel() then
				bare[#bare + 1] = name .. ":over"
			end
		end
		check(#bare == 0,
			"every doll stands in a recess of its own (" .. (#bare > 0 and
			table.concat(bare, ", ") or "all three") .. ")")

		-- BEHIND the model, not around it. A PlayerModel renders a scene with a
		-- transparent ground once the client's black overlay is off, so a recess
		-- behind it shows through exactly where the doll is not - which is the
		-- whole point of drawing one.
		local w = _G.PetModelFrame.__aetherModelWell
		check(w:GetParent() ~= _G.PetModelFrame,
			"as a sibling rather than a child, so the model draws over it")
	end

	-- THE RESISTANCE SCHOOLS KEEP THEIR ICONS. These chips were stripped
	-- whole, which took the icon with them and left five bare numbers floating
	-- down the side of the sheet with nothing saying which school each one was.
	-- The icon is the frame's only texture and has no name, so it is found by
	-- walking the regions rather than asked for by key - the same shape as the
	-- spellbook's school tabs, where the picture IS the thing.
	do
		local gone = 0
		for _, prefix in ipairs({ "MagicResFrame", "PetMagicResFrame" }) do
			for i = 1, 5 do
				local chip = _G[prefix .. i]
				if chip.__icon:GetTexture() == 0 then gone = gone + 1 end
			end
		end
		check(gone == 0,
			"every resistance keeps the icon that says which school it is (" ..
			gone .. " blanked of 10)")
	end

	-- BOTH DOLLS. The pet has a model box of its own on its own tab, and it
	-- kept the client's stone discs beside a sheet that was otherwise ours - a
	-- mock with only the player's doll in it agrees that dressing one dresses
	-- both.
	do
		local bare = 0
		for _, pair in ipairs({
			{ _G.CharacterModelFrame, _G.CharacterModelFrameRotateRightButton },
			{ _G.PetModelFrame, _G.PetModelFrameRotateRightButton },
		}) do
			local model, right = pair[1], pair[2]
			local rp, rrel = right:GetPoint(1)
			if not (right.__aetherRound
				and rp == "BOTTOMRIGHT" and rrel == model) then
				bare = bare + 1
			end
		end
		check(bare == 0,
			"the pet's doll carries the same turn controls as the player's, on"
			.. " the model rather than beside it (" .. bare .. " of 2)")

		-- AND THE BOX BEHIND THE PET comes off with them. It was never in the
		-- list of panes - only PetPaperDollFrame was, which is the tab and not
		-- the model box - so the doll stood in a stone frame on glass.
		check(_G.PetModelFrame:GetRegions():GetTexture() == 0,
			"the pet's model box loses its stone the way the player's does")
	end

	-- INSETS. A client frame is bigger than the window you can see: its art
	-- carries wide transparent margins and it reserves room below for the tabs.
	local px, _, _, ox, oy = cf.__aetherPanel:GetPoint(1)
	check(px == "TOPLEFT" and ox ~= 0 and oy ~= 0,
		"the glass is inset to the visible window rather than the frame's full"
		.. " extent, which is what left a slab of padding down the right")

	-- TABS. Blizzard's overlap on purpose and the art hides the join; with the
	-- art gone the overlap is the only thing you can see.
	local function ShownTabs()
		local out, k = {}, 1
		while _G["CharacterFrameTab" .. k] do
			local tb = _G["CharacterFrameTab" .. k]
			if tb:IsShown() then out[#out + 1] = tb end
			k = k + 1
		end
		return out
	end

	local function RowSpill(tabs)
		for _, tb in ipairs(tabs) do
			local lb = tb:GetFontString()
			if lb and lb:GetStringWidth() > tb:GetWidth() - 6 then
				return lb:GetText() .. " (" .. string.format("%.1f", lb:GetStringWidth())
					.. " in " .. string.format("%.1f", tb:GetWidth()) .. ")"
			end
		end
	end

	-- ONLY THE ONES YOU CAN SEE. The pet tab sits SECOND, between Character and
	-- Reputation, and is hidden on a character without a pet. Laying out every
	-- tab the client defined gave it a slot of its own, and the row had a hole
	-- in it exactly one tab wide with nothing in it.
	local shown = ShownTabs()
	check(#shown == 4 and not _G.CharacterFrameTab2:IsShown(),
		"the hidden pet tab is left out of the row (" .. #shown .. " of 5 placed)")

	local t1, t2 = shown[1], shown[2]

	-- BARE TEXT ON A SHARED HAIRLINE. The rail is the one thing the row sits
	-- on, and its line is on the edge facing the content the tabs switch -
	-- these are bottom tabs, so the top of the rail. Get that backwards and a
	-- tab reads as attached to the world rather than to its own window.
	local rail = cf.__aetherRails["BOTTOM"]
	check(rail ~= nil and rail._edge == "BOTTOM", "the row sits on a rail (" ..
		tostring(rail and rail._edge) .. ")")
	local rp = rail.rule:GetPoint(1)
	check(rp == "TOPLEFT",
		"whose hairline is on the edge that faces the content (" ..
		tostring(rp) .. ")")

	local tp, trel, trelP, tgap = t2:GetPoint(1)
	check(tp == "BOTTOMLEFT" and trel == t1 and trelP == "BOTTOMRIGHT",
		"and each tab chains off the one before it IN THE ROW rather than in the"
		.. " client's numbering, which is where that hole came from")
	check(tgap == 0,
		"flush against it, with no gap - the padding either side of a word is"
		.. " what separates one from the next now there is no pill to space")

	-- EACH HUGS ITS OWN LABEL. It used to be one width for all of them, on the
	-- argument that a row of pills at five different widths reads as sprung.
	-- That was true of pills. With no container left to be uneven, an even row
	-- was only wasting the rail - and the handoff says so in as many words.
	local hugs = true
	for _, tb in ipairs(shown) do
		local lb = tb:GetFontString()
		local slack = tb:GetWidth() - (lb and lb:GetStringWidth() or 0)
		if slack < 18 or slack > 34 then hugs = false end
	end
	check(hugs, "each tab is its own word plus the padding, not one width for"
		.. " all of them (" .. string.format("%.1f", t1:GetWidth()) .. " vs " ..
		string.format("%.1f", shown[3]:GetWidth()) .. ")")
	check(math.abs(t1:GetWidth() - shown[3]:GetWidth()) > 1,
		"which for Character and Skills is visibly not the same number")

	local _, tabSize, tabFlags = t1:GetFontString():GetFont()
	check(tabFlags == "",
		"a tab's label is our own type and unoutlined (" .. tostring(tabFlags)
		.. " at " .. tostring(tabSize) .. ")")

	local spilled = RowSpill(shown)
	check(spilled == nil,
		"no label is wider than the tab it sits in" ..
		(spilled and (": " .. spilled) or ""))

	-- LEFT-ALIGNED, off the rail's own corner. A row of tabs is a list of
	-- places you can go, and a list starts at the left edge of the thing it
	-- belongs to. Centred, the row moved every time a tab appeared or went
	-- away: a hunter's pet tab arriving slid Character, Skills and Reputation
	-- sideways under the cursor.
	local sp, srel, srelP, sx = t1:GetPoint(1)
	check(sp == "BOTTOMLEFT" and srel == rail and srelP == "BOTTOMLEFT"
		and sx == 0,
		"the row starts at the rail's own left corner (" .. tostring(sp) ..
		" -> " .. tostring(srelP) .. " x=" .. tostring(sx) .. ")")

	local insL, insR = 10, -30
	local visible = cf:GetWidth() + insR - insL
	local function RowWidth(list)
		local total = 0
		for _, tb in ipairs(list) do total = total + tb:GetWidth() end
		return total
	end
	check(RowWidth(shown) <= visible + 0.5,
		"and the whole row is inside the window (" ..
		string.format("%.1f", RowWidth(shown)) .. " of " ..
		string.format("%.1f", visible) .. ")")

	-- AND WITH A PET, WHICH IS FIVE. Every check above ran on the four a
	-- character without one has, so the row that actually overhung in game -
	-- Character, Pet, Reputation, Skills, Honor - was the one arrangement
	-- nothing here had ever laid out.
	do
		_G.CharacterFrameTab2:Show()
		fire("PLAYER_ENTERING_WORLD")

		local five = ShownTabs()
		check(#five == 5, "a hunter's sheet has five tabs (" .. #five .. ")")
		check(RowSpill(five) == nil,
			"no label is wider than its tab with five of them")
		-- RE-READ, because dressing the window can WIDEN it: the body inset
		-- moves the client's content in to the panel padding and grows the
		-- frame to pay for it. Measured once at the top, this compared a row
		-- laid out in the new width against the old one.
		visible = cf:GetWidth() + insR - insL
		check(RowWidth(five) <= visible + 0.5,
			"and five still fit, on tighter padding (" ..
			string.format("%.1f", RowWidth(five)) .. " of " ..
			string.format("%.1f", visible) .. ")")

		_G.CharacterFrameTab2:Hide()
		fire("PLAYER_ENTERING_WORLD")
	end

	-- Scoped, because this file's main chunk is close to Lua's ceiling of 200
	-- locals and this run alone declares a dozen.
	do
		-- WHAT GIVES, AND IN WHAT ORDER. Padding first, then a point off the
		-- lettering, and only then the words - a ranking of what each costs the
		-- player. White space costs nothing; half a word costs a lot.
		local fullWidth = cf:GetWidth()
		local basePad = (t1:GetWidth() - t1:GetFontString():GetStringWidth()) / 2
		local baseSize = t1:GetFontString():GetFont() and
			select(2, t1:GetFontString():GetFont())

		cf:SetWidth(320)
		fire("PLAYER_ENTERING_WORLD")
		local tight = ShownTabs()
		local tightPad = (tight[1]:GetWidth()
			- tight[1]:GetFontString():GetStringWidth()) / 2
		local _, tightSize = tight[1]:GetFontString():GetFont()
		check(tightPad < basePad,
			"squeezed, the padding gives first (" ..
			string.format("%.0f", tightPad) .. " from " ..
			string.format("%.0f", basePad) .. ")")
		check(tightSize < baseSize,
			"and after that a point off the lettering (" .. tostring(tightSize) ..
			" from " .. tostring(baseSize) .. ")")
		check(RowSpill(tight) == nil, "with every label still inside its tab")
		local cutYet
		for _, tb in ipairs(tight) do cutYet = cutYet or tb.__aetherCut end
		check(cutYet == nil,
			"and NO word cut yet - three dots in place of three letters tells the"
			.. " player less than the word did, so it is the last thing spent")

		-- AND WHEN THERE IS NOTHING ELSE LEFT, the words themselves - with the
		-- whole of each on a tooltip, because a cut label that says nothing else
		-- is a tab you have to click to identify.
		cf:SetWidth(280)
		fire("PLAYER_ENTERING_WORLD")
		local cut = ShownTabs()
		local cutOne
		for _, tb in ipairs(cut) do cutOne = cutOne or tb.__aetherCut end
		check(cutOne ~= nil,
			"narrower still and a long label is cut (" .. tostring(cutOne) .. ")")
		check(RowSpill(cut) == nil, "and it is inside its tab when it is")
		local tipped
		for _, tb in ipairs(cut) do
			if tb.__aetherCut then
				tb:GetScript("OnEnter")(tb)
				tipped = GameTooltip:IsShown() and GameTooltip.__lines[1]
				tb:GetScript("OnLeave")(tb)
				break
			end
		end
		check(tipped ~= nil,
			"and the whole word is on a tooltip (" .. tostring(tipped) .. ")")

		-- THE WINDOW NEVER GROWS. It used to widen by up to 48 units to hold a row
		-- that would not fit, which is a panel changing shape because of how many
		-- tabs it happens to have. The rail is set by the frame, never the reverse.
		local grownRight
		for pi = 1, 4 do
			local pt, _, _, px = cf.__aetherPanel:GetPoint(pi)
			if pt == "BOTTOMRIGHT" then grownRight = px end
		end
		check(grownRight == insR,
			"and the glass is still trimmed to the window rather than stretched"
			.. " round the row (" .. tostring(grownRight) .. " of " .. insR .. ")")

		cf:SetWidth(fullWidth)
		fire("PLAYER_ENTERING_WORLD")
	end

	-- AND IT HAS TO STAY FITTED. The client re-sizes its own tabs on show and
	-- on every click, straight over anything we set. A row that is only correct
	-- until the player touches it is not correct.
	local fitted = t2:GetWidth()
	_G.PanelTemplates_TabResize(t2, 24)
	check(t2:GetWidth() == fitted,
		"the client re-sizing a tab does not undo the fit (" .. t2:GetWidth()
		.. ") - it does this on show and on every tab click, so a width set"
		.. " once at dress time lasts until the player touches the window")

	-- The client's own placement is still remembered, because off has to put
	-- the tab back where it found it.
	check(t1.__aetherAnchor and t1.__aetherAnchor[1] == "CENTER",
		"while the client's own anchor is still recorded for the way back")

	-- The client marks the OPEN tab by disabling it, which reads backwards
	-- until you know it. Selected through the CLIENT'S OWN function, which
	-- moves the label up into the raised part of its stone art on the way.
	_G.PanelTemplates_SelectTab(t1)
	_G.PanelTemplates_UpdateTabs(cf)

	local lp, _, lrelP, lx, ly = t1:GetFontString():GetPoint(1)
	check(lp == "CENTER" and lrelP == "CENTER" and lx == 0 and ly == 0,
		"the selected tab's label stays in the middle of its tab (y=" ..
		tostring(ly) .. ") - the client nudges it up on every selection, which"
		.. " is right for raised stone and wrong for a flat rail")

	fire("PLAYER_ENTERING_WORLD")

	do
		-- A MARK, NOT A FILL. This is the whole of the pattern: a tab changes
		-- which view of the frame you are looking at, a button does a thing, and
		-- an interface where both wear the accent fill is one where you cannot
		-- tell them apart. Four tabbed surfaces here wore that fill.
		check(t1.__aetherMark ~= nil and t1.__aetherMark:IsShown(),
			"the open tab carries a mark")
		check(not t2.__aetherMark:IsShown(),
			"and the others carry nothing at all")
		check(t1.__aetherSkin == nil,
			"with no button surface anywhere on it - a filled tab is Create, Send"
			.. " and Accept in a row along the bottom of the window")

		-- ON THE HAIRLINE, on the content-facing edge, inset from both ends.
		local mp, mrel, mrelP, mx = t1.__aetherMark:GetPoint(1)
		check(mp == "LEFT" and mrel == t1 and mrelP == "LEFT" and mx == 5,
			"as long as its own tab, less an inset at each end (" ..
			tostring(mp) .. " x=" .. tostring(mx) .. ")")
		local lp, lrel = t1.__aetherMark:GetPoint(3)
		check(lp == "TOP" and lrel == rail,
			"and standing on the rail's own line (" .. tostring(lp) .. ")")
		check(t1.__aetherMark:GetHeight() == 2,
			"two pixels of it (" .. tostring(t1.__aetherMark:GetHeight()) .. ")")
		local mr = { t1.__aetherMark:GetVertexColor() }
		local acc = A.Palette.c.accent
		check(math.abs(mr[1] - acc[1]) < 0.01 and math.abs(mr[2] - acc[2]) < 0.01,
			"in the skin's accent, so it follows a skin change on its own")

		-- AND THE INK IS THE LADDER. Bright for the one you are on, faint for the
		-- ones you are not - the interface's own three steps rather than three
		-- literal alphas out of the deck.
		local onR = { t1:GetFontString():GetTextColor() }
		local offR = { t2:GetFontString():GetTextColor() }
		check(onR[4] > offR[4],
			"the open tab's word is brighter than the rest (" ..
			string.format("%.2f", onR[4]) .. " vs " ..
			string.format("%.2f", offR[4]) .. ")")
	end
	t1:Enable()

	-- SCALE. A PANEL IS THE SIZE THE REST OF THE INTERFACE IS, less the panel
	-- package's own tenth - it is drawn about that much tighter than the HUD
	-- on purpose, because its metrics were measured for review at a size that
	-- reads a shade generous in the game.
	--
	-- This used to be a FLOOR of 0.85, on the argument that the client's own
	-- fixed art stops being readable below there. At a profile scale of 0.71 -
	-- which is a common one - that drew every window at 0.85: a fifth larger
	-- than everything else on screen. They did not read as readable, they read
	-- as oversized, and that is what was reported.
	local wasScale = A.db.profile.scale
	A.db.profile.scale = 1.2
	fire("PLAYER_ENTERING_WORLD")
	check(math.abs(cf:GetScale() - 1.2 * 1.1) < 0.001,
		"a window rides the profile's scale, a tenth above it (" ..
		string.format("%.3f", cf:GetScale()) .. ")")

	-- IT TRACKS THE PROFILE, whatever the multiplier is - which is the whole of
	-- the report. It used to be a FLOOR of 0.85: at 0.71 that drew every window
	-- at 0.85 whatever the player had chosen, and stopped moving with it
	-- entirely below that. The multiplier itself has been 0.92, then 1.0, then
	-- this, each step on the strength of looking at it.
	A.db.profile.scale = 0.71
	fire("PLAYER_ENTERING_WORLD")
	local small = cf:GetScale()
	A.db.profile.scale = 1.0
	fire("PLAYER_ENTERING_WORLD")
	check(math.abs(cf:GetScale() / small - 1 / 0.71) < 0.01,
		"and moves with it point for point (" .. string.format("%.3f", small)
		.. " at 0.71, " .. string.format("%.3f", cf:GetScale()) .. " at 1.0)")

	-- The floor stays, an order lower, and it is now about the one thing it
	-- was ever really about: below this the client's own art is not small, it
	-- is gone. Nothing a player would choose comes near it.
	A.db.profile.scale = 0.1
	fire("PLAYER_ENTERING_WORLD")
	check(cf:GetScale() == 0.45,
		"and it still will not go below the floor (" .. cf:GetScale() .. ")")

	A.db.profile.scale = wasScale
	fire("PLAYER_ENTERING_WORLD")

	-- NOT A WINDOW. The old FriendsFrame XML still defines a GuildFrame pane -
	-- setAllPoints, inside the social window - and the panel list named it as a
	-- window of its own, so it got glass behind a pane that already had some and
	-- a scale of its own inside a frame already scaled. The guild button on this
	-- client opens Communities; nothing opens that pane at all.
	do
		local pane = CreateFrame("Frame", "GuildFrame", _G.FriendsFrame)
		pane:SetAllPoints(_G.FriendsFrame)
		fire("PLAYER_ENTERING_WORLD")
		check(pane.__aetherPanel == nil,
			"a pane that happens to carry a window's name is not dressed as one")
	end

	-- LOAD ON DEMAND. Half of these do not exist at login; they arrive with
	-- their own addon the first time you open them, and a list walked once at
	-- startup would never see them.
	check(_G.WorldMapFrame == nil, "the map is not loaded yet")
	_G.__loadPanelAddon("WorldMapFrame")
	fire("ADDON_LOADED", "Blizzard_WorldMap")
	check(_G.WorldMapFrame.__aetherPanel ~= nil,
		"and is skinned when its addon turns up, rather than only at login")

	-- Off hands the client its windows back.
	A:SetModuleEnabled("panels", false)
	check(cf.__aetherPanel == nil and cf.__stone:GetTexture() == "stone-border"
		and cf.Bg.__fill:GetTexture() == "panel-background",
		"switching it off returns the window the client drew, background and all")
	check(close:GetNormalTexture():GetTexture() == "close-up"
		and close.__aetherClose == nil,
		"and its own close button with it")
	A:SetModuleEnabled("panels", true)
	check(cf.__aetherPanel ~= nil, "and on again re-dresses it")
end

print("== panels: the spellbook, which spells nothing the way the others do ==")
do
	local sb = _G.SpellBookFrame
	fire("PLAYER_ENTERING_WORLD")

	-- ITS TITLE IS NOT $parentTitleText. Nothing errors when a skin looks for
	-- one and does not find it; the window simply keeps the client's lettering
	-- and the skin reports success.
	check(_G.SpellBookTitleText._aetherStyle == "pnTitle",
		"the title is found under the client's own name for it and re-roled")

	local tPt, tRel, tRelPt, _, tY = _G.SpellBookTitleText:GetPoint(1)
	check(tPt == "TOP" and tRel == sb.__aetherPanel and tRelPt == "TOP"
		and tY < 0,
		"and brought to the top of the glass (y=" .. tostring(tY) .. ") - the"
		.. " client put it six pixels right of centre because the page it was"
		.. " printed on is not centred in the frame either")

	local close = _G.SpellBookCloseButton
	check(close.__aetherClose and close:GetNormalTexture():GetTexture() == 0,
		"its close button is found under ITS own name and gets our mark, rather"
		.. " than being missed for want of a $parentCloseButton")
	local cPt, cRel, cRelPt = close:GetPoint(1)
	check(cPt == "TOPRIGHT" and cRel == sb and cRelPt == "TOPRIGHT",
		"and moves to the corner (" .. tostring(cPt) .. ") - the client sat it 44"
		.. " in and 25 down, in the middle of a stone rim that is now gone")

	-- THE SPELLS. Icon in a region, ring as the normal texture, parchment disc
	-- behind both: one sweep would blank the icon and the other would leave the
	-- disc, and only knowing which is which gets it right.
	local b1 = _G.SpellButton1
	check(b1.__aetherSlot == true, "a spell sits in one of our cells")
	check(_G.SpellButton1IconTexture:GetTexture() == "spell-icon-1",
		"AND THE SPELL IS STILL IN IT - the icon is a region of the button, so a"
		.. " strip takes the picture and leaves the cell correctly empty")
	check(b1.EmptySlot:GetTexture() == 0,
		"with the parchment disc behind it cleared - that one is not a state"
		.. " texture, so clearing the button's four would leave it drawing")
	check(b1:GetNormalTexture():GetTexture() == 0, "and the ring around it gone")
	check(b1.SpellName._aetherStyle ~= nil and b1.SpellSubName._aetherStyle ~= nil,
		"the spell's name and rank are in our lettering")

	-- The client repaints these on every refresh - on open, on a tab click, on
	-- learning a spell - and puts its own white highlight square back with them.
	b1:UpdateButton()
	check(b1:GetHighlightTexture():GetTexture() == 0,
		"and the client's own highlight square does not come back on the next"
		.. " refresh, which is every time the book is opened or turned")
	local nr, ng, nb = b1.SpellName:GetTextColor()
	local ink = A.Palette.c.text
	check(nr == ink[1] and ng == ink[2] and nb == ink[3],
		"nor its own gold on the name (" .. string.format("%.2f", nr) .. ")")

	-- THE SCHOOL TABS. Here the icon IS the normal texture: the client calls
	-- SetNormalTexture with the school's image every time it refreshes them.
	local st1, st2 = _G.SpellBookSkillLineTab1, _G.SpellBookSkillLineTab2
	check(st1.__aetherSlot == true, "a school tab wears the same cell")
	check(st1.__plate:GetTexture() == 0,
		"with the 64px stone plate behind a 32px button cleared")

	sb:UpdateSkillLineTabs()
	check(st1:GetNormalTexture():GetTexture() == "Interface\\Icons\\Spell_Frost_FrostBolt02",
		"AND THE SCHOOL'S ICON SURVIVES - it is the normal texture, so the sweep"
		.. " that clears a button's art blanks the picture the player is looking"
		.. " for and leaves a column of empty cells")
	check(st1:GetCheckedTexture():GetTexture() == "Interface\\Buttons\\CheckButtonHilight",
		"and so does the mark saying which school you are on")

	-- THE SAME RAIL, ROTATED. The schools are a secondary filter within the
	-- book the bottom rail has already chosen - two axes, one panel - so they
	-- get the icon rail rather than a second row of words.
	local srail = sb.__aetherRails["RIGHT"]
	check(srail ~= nil and srail._edge == "RIGHT",
		"the column sits on a vertical rail down the window's right edge (" ..
		tostring(srail and srail._edge) .. ")")
	local rrp = srail.rule:GetPoint(1)
	check(rrp == "TOPLEFT",
		"with its hairline on the side facing the spells (" .. tostring(rrp) ..
		")")
	check(not srail.tint:IsShown(),
		"and NO wash behind it - four per cent of lilac on a frosted panel is"
		.. " a slab down the side of the window, and the hairline gathers the"
		.. " column the same way it gathers a row of words")

	local sPt, sRel, sRelPt = st1:GetPoint(1)
	check(sPt == "TOP" and sRel == srail and sRelPt == "TOP",
		"the column hangs off the rail rather than off the glass (" ..
		tostring(sPt) .. ")")

	-- AN INACTIVE ICON DIMS AND DRAINS, which is the exact analogue of dim
	-- text: a picture cannot go faint without losing what it is a picture of.
	local st2 = _G.SpellBookSkillLineTab2
	st1:SetChecked(true)
	st2:SetChecked(false)
	sb:UpdateSkillLineTabs()
	check(st1.__aetherMark:IsShown() and not st2.__aetherMark:IsShown(),
		"the school you are in carries the same mark a word tab does")

	-- ON THE RAIL'S LINE, NOT THE ICON'S EDGE. These tabs are children of
	-- SpellBookSideTabsFrame - a full-window frame of Blizzard's that exists
	-- only to hold them - so looking the rail up off the parent finds nothing
	-- and the mark falls back to the icon, six pixels in from the line. It has
	-- to be handed the rail, and this is the check that says so.
	local _, sfrel, sfrelP = st1.__aetherMark:GetPoint(3)
	check(sfrel == srail and sfrelP == "LEFT",
		"and it stands on the rail's own left edge rather than the icon's (" ..
		tostring(sfrelP) .. ")")
	check(st1:GetParent() ~= srail:GetParent(),
		"which the parent could not have told it - the tab hangs off a frame of"
		.. " Blizzard's and the rail off the window")
	check(st1:GetNormalTexture():GetAlpha() == 1
		and st2:GetNormalTexture():GetAlpha() < 1,
		"and the ones you are not in are dimmed (" ..
		string.format("%.2f", st2:GetNormalTexture():GetAlpha()) .. ")")
	check(st2:GetNormalTexture().__desaturated == true,
		"and drained of their colour with it")
	local s2Rel, s2Y = select(2, st2:GetPoint(1)), select(5, st2:GetPoint(1))
	check(s2Rel == st1 and s2Y == -6,
		"and closes up under it (" .. tostring(s2Y) .. ") - Blizzard's 17 is the"
		.. " clearance its stone needed, and without the stone it reads as a"
		.. " column of unrelated icons")

	-- THE PAGE TURNER. Both arrows are engraved in the art; take the art off
	-- without putting something there and it is two invisible squares.
	local prev = _G.SpellBookPrevPageButton
	check(prev:GetNormalTexture():GetTexture() == 0 and prev.__aetherMark
		and (prev.__aetherMark:GetText() or "") ~= "",
		"the page turner keeps a mark of ours where its engraved arrow was")

	local pr, pg, pb = _G.SpellBookPageText:GetTextColor()
	check(_G.SpellBookPageText._aetherStyle ~= nil and (pr + pg + pb) > 1,
		"and the page number is readable (" .. string.format("%.2f", pr) .. ","
		.. string.format("%.2f", pg) .. ") - the client prints it in near-black"
		.. " because it is printing it on parchment")

	local ranks = _G.ShowAllSpellRanksCheckbox
	check(ranks.__aetherCheck ~= nil, "the spell-ranks box is ours")

	-- A BOX, NOT A DISC. It was a round badge, and round is what a RADIO
	-- button is: one of several. Square is on or off. Drawing an independent
	-- toggle as a circle says the wrong thing about what pressing it does,
	-- before anybody has read the label beside it.
	local chip = ranks.__aetherCheck
	check(chip._kind == "panel" and chip.tick ~= nil,
		"and drawn as a rounded SQUARE with a tick in it (" ..
		tostring(chip._kind) .. ")")

	-- AND SIZED FROM THE MARK, not from the client's button - which is a
	-- small square inside a much larger transparent hit area. Taking its
	-- width gave a box the size of a bag slot.
	check(chip:GetWidth() == A.Widgets.CHECK_SIZE
		and chip:GetWidth() < ranks:GetWidth(),
		"at its own size rather than the hit area's (" .. chip:GetWidth() ..
		" in a button of " .. ranks:GetWidth() .. ")")

	-- OUR OWN TICK, off the atlas. It carried BLIZZARD'S check mark - their
	-- art, in their weight, in the middle of a control that is otherwise
	-- entirely ours. The sheet has had a tick on it since the console's
	-- channel list needed one; there was never a reason for two.
	check(chip.tick:GetTexture() == A.Media.icons.file,
		"with our tick rather than the client's (" ..
		tostring(chip.tick:GetTexture()) .. ")")
	check(ranks:GetCheckedTexture():GetTexture() == 0,
		"and the client's taken off with the rest of its art")

	-- ON OR OFF, and it answers the CLIENT: a check box is toggled by
	-- Blizzard's own OnClick as often as by ours, so a mark drawn once at
	-- dress time is right until the first press.
	ranks:SetChecked(true)
	ranks:GetScript("OnClick")(ranks)
	check(chip.tick:IsShown(), "ticked when the client says it is on")
	ranks:SetChecked(false)
	ranks:GetScript("OnClick")(ranks)
	check(not chip.tick:IsShown(), "and empty when it says it is off")

	-- AND ITS LABEL HANGS OFF THE MARK, not off the button.
	--
	-- Blizzard's check box is a small square inside a much larger transparent
	-- hit area, and its label is anchored flush to THAT - which clears the
	-- square by several pixels. Ours is the size of the mark and centred in
	-- the hit area, so a gap measured from the button's left edge put the
	-- words underneath it, which is what was reported.
	local lPt, lRel, lRelPt, lx = _G.ShowAllSpellRanksCheckboxText:GetPoint(1)
	check(lRel == ranks.__aetherCheck,
		"the words hang off the mark rather than the hit area (" ..
		tostring(lRel == ranks and "the button" or "the mark") .. ")")
	check(lPt == "LEFT" and lRelPt == "RIGHT" and lx > 0,
		"clear of its right edge (" .. tostring(lPt) .. " -> " ..
		tostring(lRelPt) .. " x=" .. tostring(lx) .. ")")

	-- THE BOOK'S OWN TABS. All three start hidden and the client shows the ones
	-- that apply from its own update, so the first dress sees an empty row. A
	-- layout that gives up on an empty row without asking to be told when a tab
	-- appears never runs at all.
	local bt1, bt2 = _G.SpellBookFrameTabButton1, _G.SpellBookFrameTabButton2
	check(bt1.__aetherTab == nil, "the book's tabs start hidden, so none is placed")

	sb:Update()
	check(bt1.__aetherTab ~= nil and bt2.__aetherTab ~= nil,
		"and are laid out when the client shows them - from the client's own"
		.. " update, not from a re-dress nobody would have run")
	check(math.abs(bt1:GetWidth() - bt2:GetWidth()) > 1,
		"each hugging its own word rather than sharing one width - Spellbook"
		.. " and Demon are not the same length and there is no pill left to be"
		.. " uneven (" .. string.format("%.1f", bt1:GetWidth()) .. " / " ..
		string.format("%.1f", bt2:GetWidth()) .. ")")

	local hl, hr, ht, hb = bt1:GetHitRectInsets()
	check(hl == 0 and hr == 0 and ht == 0 and hb == 0,
		"AND STILL CLICKABLE. The client keeps the clicks 13 in from the top of"
		.. " a 64px tab and 15 up from the bottom; re-size that tab to 26 and the"
		.. " two insets meet, so it draws, highlights, reads correctly and does"
		.. " nothing at all when you click it")

	check(bt1.__aetherMark:IsShown() and not bt2.__aetherMark:IsShown(),
		"and the book you are in is the marked one - a FILLED tab is Create,"
		.. " Send and Accept in a row along the bottom of the window")

	local bPt, bRel, bRelPt = bt1:GetPoint(1)
	check(bPt == "BOTTOMLEFT" and bRel == sb.__aetherRails["BOTTOM"]
		and bRelPt == "BOTTOMLEFT",
		"anchored by its own corner to the RAIL's (" .. tostring(bPt) .. ")")

	-- AND WITH NO CLICK INVOLVED. Enabling a tab moves its label up into the
	-- raised part of art that is no longer there, and the client enables and
	-- disables these from its own update - which runs when a spell is learned
	-- while the book is open, with nothing of ours prompted to answer it.
	sb:Update()
	local lPt, _, lRelPt, lx, ly = bt1:GetFontString():GetPoint(1)
	check(lPt == "CENTER" and lRelPt == "CENTER" and lx == 0 and ly == 0,
		"the selected tab's label is put back in the middle of its tab (y="
		.. tostring(ly) .. ") after the client's own rebuild")

	-- OFF AND ON AGAIN. Switching the module off hands the client every texture
	-- back, which is the point of it - and switching it on runs the dressing a
	-- second time over a frame that already carries our markers. Every one of
	-- these returned early on its own marker, so the second pass stopped before
	-- it had taken back the art the first pass had just given up.
	A:SetModuleEnabled("panels", false)
	check(b1.EmptySlot:GetTexture() ~= 0 and st1.__plate:GetTexture() ~= 0,
		"off gives the spellbook its parchment and its stone back")

	A:SetModuleEnabled("panels", true)
	fire("PLAYER_ENTERING_WORLD")
	check(b1.EmptySlot:GetTexture() == 0 and st1.__plate:GetTexture() == 0
		and b1:GetNormalTexture():GetTexture() == 0,
		"and on again takes all of it off a second time, rather than stopping at"
		.. " a marker left over from the first")
	check(_G.SpellButton1IconTexture:GetTexture() == "spell-icon-1",
		"with the spell still where it was")
end

print("== panels: the windows an NPC opens ==")
do
	fire("PLAYER_ENTERING_WORLD")

	-- THE VENDOR. A row's own regions are the empty-slot disc and the stone
	-- label plate; the item's picture is on a BUTTON INSIDE IT. Get that
	-- backwards and you blank the shop and keep the furniture.
	-- ITS GRID IS MOVED INTO THE RECESS, and it has no pane to do it with: the
	-- ten rows are children of the window and only the first is anchored to it,
	-- so that one row is the handle for all of them. Rewriting it to the
	-- window's corners the way a pane is rewritten would stretch one row across
	-- the whole window.
	local mf2 = _G.MerchantFrame
	local inner2 = A.Widgets.PANEL_PAD + A.Widgets.WELL_PAD
	check(_G.MerchantItem1.__aetherTop == 69
		and _G.MerchantItem1.__aetherLeft == 11,
		"the first row is measured where the client anchors it (" ..
		tostring(_G.MerchantItem1.__aetherTop) .. ", " ..
		tostring(_G.MerchantItem1.__aetherLeft) .. ")")

	-- BOTH EDGES, separately. The widest thing on this window is not the row:
	-- its template is a good deal wider than the name and the price printed in
	-- it, so a measurement that stops at the row is measuring a box with air in
	-- it and pads the window out to fit the air.
	-- The row starts 11 in and its widest printed thing ends 261 short of the
	-- far side - the row template is 153 across and the name in it is 70. So
	-- the left is short of the padding and the right is not short at all.
	-- Off what is PRINTED and not the box round it: the row template is 153
	-- across and the name in it is 70, so the far side is nowhere near short
	-- of the padding even though the near side is.
	check((_G.MerchantItem1.__aetherRight or 0) > inner2,
		"the right-hand edge is measured too, off what is printed rather than"
		.. " the box round it (" .. tostring(_G.MerchantItem1.__aetherRight)
		.. ")")
	check(mf2.__aetherBodyGrow == inner2 - 11,
		"and the window grows by what the near side is short and nothing for"
		.. " the far one, rather than double (" ..
		tostring(mf2.__aetherBodyGrow) .. " against " .. (inner2 - 11) .. ")")
	local mp, mrel, mrelP, mx, my = _G.MerchantItem1:GetPoint(1)
	check(mp == "TOPLEFT" and mrel == mf2 and mrelP == "TOPLEFT"
		and _G.MerchantItem1:GetNumPoints() == 1,
		"and keeps the ONE anchor it had rather than being pinned corner to"
		.. " corner, which would stretch one row across the window (" ..
		_G.MerchantItem1:GetNumPoints() .. " point)")
	check(mx == 11 + (inner2 - 11) and my == -(69 + mf2.__aetherHeadH
		+ inner2 - 69),
		"with that anchor offset into the well's padding (" .. tostring(mx) ..
		", " .. tostring(my) .. ")")
	check(select(5, _G.MerchantItem2:GetPoint(1)) == 0,
		"and the nine chained off it are not touched at all")

	-- ITS TITLE IS THE VENDOR, not the window's own name for itself. This was
	-- roled as body text and left wherever the portrait art had put it, which
	-- was the fourth place the panel file was setting a title by hand.
	check(_G.MerchantFrame.__aetherTitle == _G.MerchantNameText,
		"the merchant window's title is who you are buying from")
	check(_G.MerchantNameText._aetherStyle == "pnTitle",
		"in title type rather than the body type it used to take")
	local vPt, vRel = _G.MerchantNameText:GetPoint(1)
	check(vPt == "TOP" and vRel == _G.MerchantFrame.__aetherPanel,
		"and centred in the header band like every other window's")

	-- ITS PAGE TURNERS GO IN THE FOOTER. 15c is specific: a page turn lives in
	-- the chrome and never floats in the body. Prev, Page 1 and Next sat inside
	-- the recess, over the last row of what you were being sold.
	local page = _G.MerchantPageText
	-- ABOVE THE TAB RAIL, not on the window's bottom edge. The footer strip
	-- sits between the recess and the tabs; a pager anchored to the glass lands
	-- on Merchant and Buyback.
	local pp, prel, pprelP, px, py = page:GetPoint(1)
	local rail = mf2.__aetherRails["BOTTOM"]
	check(pp == "LEFT" and prel == rail and pprelP == "TOP"
		and py == A.Widgets.PANEL_FOOT_H / 2,
		"the page count is in the footer strip, above the tab rail (" ..
		tostring(pp) .. " -> " .. tostring(pprelP) .. " at " .. tostring(py)
		.. ")")

	-- LAID OUT BY THE LINE THAT LAYS OUT EVERY OTHER WINDOW'S ACTIONS. A page
	-- turn had a function of its own, which is one more copy of centre-a-row
	-- than the interface needs - and the copy was already a gap out of step
	-- with the other one.
	local qGap = 12
	local back, on = _G.MerchantPrevPageButton, _G.MerchantNextPageButton
	-- BY THE WORDS, NOT BY THE BOX. A font string's declared width is the room
	-- the client reserved for it: the page count in a book is 192 wide and says
	-- "Page 1", so measuring the box put the two turns at opposite ends of the
	-- strip with a hand's width of nothing between them.
	local turn = back:GetWidth() + page:GetStringWidth() + on:GetWidth()
		+ qGap * 2
	local bx = select(4, back:GetPoint(1))
	local nx = select(4, on:GetPoint(1))
	check(bx == -turn / 2 and px == bx + back:GetWidth() + qGap
		and nx == px + page:GetStringWidth() + qGap,
		"with a turn either side of it, centred as one group rather than flung"
		.. " to the far corners of the window (" .. tostring(bx) .. ", "
		.. tostring(px) .. ", " .. tostring(nx) .. ")")

	local row = _G.MerchantItem1
	check(_G.MerchantFrame.__aetherPanel ~= nil, "the vendor window is in glass")
	check(row.__slot:GetTexture() == 0 and row.__plate:GetTexture() == 0,
		"a row's empty-slot disc and label plate come off")
	check(row.ItemButton.__aetherSlot == true,
		"the item sits in one of our cells")
	check(_G.MerchantItem1ItemButtonIconTexture:GetTexture() == "merchant-icon-1",
		"WITH THE GOODS STILL IN IT - the picture is on the button inside the"
		.. " row, not on the row, which is what makes stripping the row safe")
	check(row.Name._aetherStyle ~= nil, "the item's name is in our lettering")

	-- The anvil IS the normal texture on these, so they go the way a school tab
	-- does rather than the way a button does.
	-- REPAIR KEEPS EVERY REGION IT HAS. Its anvil is a BORDER-layer region, not
	-- the normal texture, it is named after the button's stem rather than the
	-- button, and it is cropped out of a shared sheet by texcoords. Dressing
	-- these as icon buttons cleared the anvils and left two empty squares.
	check(_G.MerchantRepairAllButton.__aetherSkin ~= nil,
		"repair gets our surface behind it")

	do
		-- AND THE PAIR GOES ON THE ROW THE BUYBACK SLOT IS ON.
		--
		-- The client pins them to the window's own bottom-left corner, which is
		-- where our footer strip now is, so they sat across its hairline with the
		-- page turn beside them. The last row of the grid is half empty - the
		-- client hangs the buyback slot 53 below the tenth item, in the RIGHT
		-- column, and nothing is ever drawn beside it - so the pair goes in the
		-- left half of that row, level with it.
		local one, all = _G.MerchantRepairItemButton, _G.MerchantRepairAllButton
		local buy = _G.MerchantBuyBackItem
		check(math.abs(one:GetTop() - buy:GetTop()) < 0.5,
			"the repair pair is level with the buyback slot (" ..
			string.format("%.0f vs %.0f", one:GetTop(), buy:GetTop()) .. ")")
		check(math.abs(one:GetLeft() - _G.MerchantItem1ItemButton:GetLeft()) < 0.5,
			"and starts where the left column of items does (" ..
			string.format("%.0f vs %.0f", one:GetLeft(),
			_G.MerchantItem1ItemButton:GetLeft()) .. ")")

		-- CLEAR OF THE STRIP BELOW, which is the page turn's and your purse's.
		local rule = _G.MerchantFrame.__aetherFootRule
		check(rule == nil or one:GetBottom() > rule:GetTop(),
			"and clear of the footer's hairline rather than sitting across it")

		-- AND THEY DO NOT TOUCH EACH OTHER. The client spaces them TWO apart,
		-- which is close enough that two surfaces with a rim on them read as one
		-- shape with a seam down it - reported as the icons overlapping.
		check(all:GetLeft() - one:GetRight() >= 6,
			"the two repair buttons stand apart rather than running into each "
			.. "other (" .. string.format("%.0f", all:GetLeft() - one:GetRight())
			.. " apart, the client's own is 2)")

		-- AND IT ALL SURVIVES THE CLIENT DOING IT AGAIN.
		--
		-- MerchantFrame_UpdateRepairButtons runs on every merchant update and
		-- re-places all three WITHOUT clearing their points. So a placement made
		-- once is a button stretched between two anchors the next time somebody
		-- opens a vendor - and the pair anchored the other way round from the
		-- client's is an ANCHOR LOOP, which is a real error with a real stack.
		-- Reported from the game as exactly that.
		_G.MerchantFrame_UpdateRepairButtons()
		check(one:GetNumPoints() == 1 and all:GetNumPoints() == 1,
			"each repair button is left pinned by ONE corner after the client "
			.. "has been past (" .. one:GetNumPoints() .. ", "
			.. all:GetNumPoints() .. ")")
		check(math.abs(one:GetTop() - buy:GetTop()) < 0.5
			and all:GetLeft() - one:GetRight() >= 6,
			"and still on the buyback row, still apart (" ..
			string.format("%.0f vs %.0f, %.0f apart", one:GetTop(),
			buy:GetTop(), all:GetLeft() - one:GetRight()) .. ")")

		-- AND THE LABEL IS UNDER THE PAIR IT NAMES, not 16 in from a corner that
		-- is now the footer strip.
		local lbl = _G.MerchantRepairText
		check(math.abs(lbl:GetLeft() - one:GetLeft()) < 0.5
			and lbl:GetTop() <= one:GetBottom(),
			"and Repair Items sits under them (" ..
			string.format("%.0f, %.0f", lbl:GetLeft(), lbl:GetTop()) .. ")")
	end
	check(_G.MerchantRepairAllIcon:GetTexture()
			== "Interface\\MerchantFrame\\UI-Merchant-RepairIcons",
		"and keeps its anvil, which is a region of its own and not this"
		.. " button's normal texture")

	-- THE PAGE TURN IS THE SPELLBOOK'S, like every other one in the interface.
	--
	-- It used to keep the client's words in a pill of ours, on the argument that
	-- "Prev" and "Next" already said which way they went. They did, and they
	-- said it in the WRONG PLACE: each word is anchored outside its own button -
	-- Prev's to the right of it, Next's to the left - so both landed in the
	-- middle, on top of the page number. Reported from the game as the count
	-- being occluded by the turns.
	check(_G.MerchantPrevPageButton.__aetherMark ~= nil
		and _G.MerchantNextPageButton.__aetherMark ~= nil,
		"both page turns wear a chevron of ours")
	check((_G.MerchantPrevPageButtonText:GetText() or "") == "",
		"and the client's own word is off, rather than printed over the count "
		.. "in the middle (" .. tostring(_G.MerchantPrevPageButtonText:GetText())
		.. ")")
	check(not _G.MerchantPrevPageButton.__aetherSkin
		or not _G.MerchantPrevPageButton.__aetherSkin:IsShown(),
		"with nothing round it - a chevron means navigation, and navigation is "
		.. "chrome rather than an action you choose")

	-- AND THE COUNT IS CUT TO ITS WORDS. The client gives it a box 104 wide
	-- with "Page 1" in it, and a string draws CENTRED in its box however little
	-- it says - so a row that measures the words, as the footer strip correctly
	-- does, reserves forty units for something that paints a hundred and four
	-- and the ends slide under whatever is beside it.
	check(_G.MerchantPageText:GetWidth() < 104,
		"the page count is cut to its words rather than keeping the box the "
		.. "client reserved (" .. string.format("%.0f",
		_G.MerchantPageText:GetWidth()) .. " of 104)")

	-- ONE OF THESE, EVERYWHERE. Four windows page and each had grown its own
	-- answer; the spellbook's is the one kept.
	do
		local bare = {}
		for _, n in ipairs({ "SpellBookPrevPageButton", "SpellBookNextPageButton",
			"InboxPrevPageButton", "InboxNextPageButton",
			"ItemTextPrevPageButton", "ItemTextNextPageButton",
			"MerchantPrevPageButton", "MerchantNextPageButton" }) do
			local b = _G[n]
			if b and not b.__aetherMark then bare[#bare + 1] = n end
		end
		check(#bare == 0, "every page turn in the interface wears the same mark (" ..
			(#bare > 0 and table.concat(bare, ",") or "all eight") .. ")")
	end
	check(_G.MerchantFrameTab1.__aetherTab ~= nil,
		"and its two tabs are laid out like every other window's")

	-- THE QUEST GIVER: four panels of one window, one shown at a time.
	local detail = _G.QuestFrameDetailPanel
	check(_G.QuestFrame.__aetherPanel ~= nil, "the quest window is in glass")
	check(select(1, detail:GetRegions()):GetTexture() == 0,
		"and every one of its four panels loses its parchment")
	check(_G.QuestFrameNpcNameText._aetherStyle == "pnTitle",
		"who you are talking to is in our lettering")
	check(_G.QuestFrameAcceptButton.__aetherSkin ~= nil, "its buttons are ours")

	-- ONE BUTTON SHAPE, AND IT IS A ROUNDED RECTANGLE.
	--
	-- There were three versions of this: a pill behind a client button, a pill
	-- behind a client tab, and a pill built as a button in the quest log. All
	-- three drew a CAPSULE, because CreatePill was the nearest thing to hand -
	-- and a capsule's two caps come out of a 256-texel texture, so at button
	-- height they are minified more than ten times and the client does not
	-- mipmap. Same crunch as the tooltip badge and the check box.
	check(_G.QuestFrameAcceptButton.__aetherSkin._kind == "panel",
		"and drawn as a rounded rectangle at the deck's own radius rather than"
		.. " a capsule (" .. tostring(_G.QuestFrameAcceptButton.__aetherSkin._kind)
		.. ")")
	check(_G.MerchantFrameTab1.__aetherSkin == nil
		and _G.MerchantFrameTab1.__aetherMark ~= nil,
		"a tab is NOT a surface at all - it is a word on a rail with a mark"
		.. " under the one you are on, which is the only thing telling it apart"
		.. " from the Accept button above it")

	-- LEFT-ALIGNED, and this is the window that can tell. The character sheet's
	-- four tabs happen to total exactly the width that centring would give
	-- them, so it agreed with both rules; two tabs in a 336-wide window do not.
	local _, mrel, _, mtx = _G.MerchantFrameTab1:GetPoint(1)
	check(mtx == 0 and mrel == _G.MerchantFrame.__aetherRails["BOTTOM"],
		"the vendor's tab row starts at the rail's left edge (" .. tostring(mtx)
		.. ") - centred, a row slides sideways every time a tab comes or goes")
	-- NOT A CELL. These are wide rows - an icon at one end, the item's name
	-- beside it - and a cell sizes its picture to the whole button, so the icon
	-- came out stretched the width of the row.
	check(_G.QuestProgressItem1.__aetherSlot == nil,
		"what the quest wants from you is NOT dressed as a cell - the row is"
		.. " wide and a cell would stretch the icon across all of it")
	check(_G.QuestProgressItem1IconTexture:GetTexture() == "quest-item-1"
		and _G.QuestProgressItem1:GetNormalTexture():GetTexture() == 0,
		"its border comes off and the icon is left where the client drew it")

	-- ITS TITLE IS IN THE BAND. This one was roled by hand in the window's own
	-- dresser, through a lookup that could never find the string - the name is
	-- QuestFrameNpcNameText and the frame it hangs off is QuestNpcNameFrame, so
	-- "frame name + Text" asked for a global this game does not have.
	check(_G.QuestFrame.__aetherTitle == _G.QuestFrameNpcNameText,
		"the quest window's title is who is talking to you")
	local qp, qrel, qrelP = _G.QuestFrameNpcNameText:GetPoint(1)
	check(qp == "TOP" and qrel == _G.QuestFrame.__aetherPanel and qrelP == "TOP",
		"centred in the header band like every other window's (" ..
		tostring(qp) .. ")")

	-- AND THE QUEST IS MOVED INTO THE RECESS. The client anchors all four of
	-- its scroll frames to the WINDOW rather than to the panel they are on, 23
	-- in and 81 down - the margin the parchment used to need, which is neither
	-- our band nor our padding.
	local qsf = _G.QuestDetailScrollFrame
	local qInner = A.Widgets.PANEL_PAD + A.Widgets.WELL_PAD
	check(qsf.__aetherTop == 73 and qsf.__aetherLeft == 15,
		"the quest text is measured where the client anchors it (" ..
		tostring(qsf.__aetherTop) .. ", " .. tostring(qsf.__aetherLeft) .. ")")
	local _, _, _, qx, qy = qsf:GetPoint(1)
	check(qx == 23 + (qInner - 15)
		and qy == -(81 + (_G.QuestFrame.__aetherHeadH + qInner - 73)),
		"and moved down and in until it clears the band and sits inside the"
		.. " well's own padding (" .. tostring(qx) .. ", " .. tostring(qy) .. ")")

	-- AND THE PAGE STOPS WHERE THE RECESS DOES. A scroll frame CLIPS AT ITS OWN
	-- BOUNDS and nowhere else, so moving one down the window without shortening
	-- it moves where the clipping happens too - a long quest carried on past
	-- the foot of the well, over the hairline and under Accept and Decline.
	do
		local page = _G.QuestDetailScrollFrame
		local well = _G.QuestFrame.__aetherBody
		check(page:GetBottom() and well and well:GetBottom()
			and page:GetBottom() >= well:GetBottom() + A.Widgets.WELL_PAD - 0.5,
			"the quest's page ends inside the well's own padding rather than"
			.. " running out through its foot (page " ..
			string.format("%.0f", page:GetBottom() or 0) .. ", well " ..
			string.format("%.0f", (well and well:GetBottom()) or 0) .. ")")
	end

	-- ITS FOOTER HAS A FOOT. 15a bounds the strip above the way the band is
	-- bounded below; without it the actions read as floating in the glass under
	-- the recess rather than standing in a strip.
	local qfr = _G.QuestFrame.__aetherFootRule
	check(qfr ~= nil and qfr:IsShown(), "the footer strip has a hairline")
	local fp, frel, frelP, _, fy = qfr:GetPoint(1)
	check(fp == "BOTTOMLEFT" and frel == _G.QuestFrame.__aetherPanel
		and frelP == "BOTTOMLEFT"
		and fy == A.Widgets.PANEL_FOOT_H,
		"along the top of the strip (" .. tostring(fy) .. ")")
	check(qfr:GetParent() == _G.QuestFrame.__aetherChrome,
		"drawn on the chrome layer, like the band's - anywhere else and the"
		.. " client's own panels are over it")

	-- UP, because the strip is laid out for what is VISIBLE and a window that
	-- has never been opened has nothing visible on it. This is the first open:
	-- the panel was already shown when the window came up.
	_G.QuestFrame:Show()

	-- ACCEPT AND DECLINE, TOGETHER, IN THE MIDDLE. The client flings this pair
	-- to opposite bottom corners of a window 384 across, with the whole quest
	-- between them.
	local qGap = 12
	local pair = _G.QuestFrameAcceptButton:GetWidth()
		+ _G.QuestFrameDeclineButton:GetWidth() + qGap
	local ap, arel, arelP, ax, ay = _G.QuestFrameAcceptButton:GetPoint(1)
	check(ap == "LEFT" and arel == _G.QuestFrame.__aetherPanel
		and arelP == "BOTTOM" and ax == -pair / 2
		and ay == A.Widgets.PANEL_FOOT_H / 2,
		"accept starts half the pair's width left of the strip's middle (" ..
		tostring(ax) .. ", " .. tostring(ay) .. ")")
	local dx = select(4, _G.QuestFrameDeclineButton:GetPoint(1))
	check(dx == -pair / 2 + _G.QuestFrameAcceptButton:GetWidth() + qGap,
		"and decline sits a footer gap along from it (" .. tostring(dx) .. ")")

	-- AND ONLY THE PAIR THAT IS UP. Every one of these seven is a child of the
	-- panel it belongs to and carries its own shown flag the whole time; what
	-- the client hides is the PANEL. Asked IsShown, all seven were laid into
	-- the strip on top of each other.
	check(select(2, _G.QuestFrameCompleteQuestButton:GetPoint(1))
		~= _G.QuestFrame.__aetherPanel,
		"the reward panel's buttons are left where they were while it is down")

	-- AND THE STRIP IS RE-LAID WHEN THE CLIENT SWAPS PANELS. There is no tab on
	-- this window to tell us; the four panels come and go on their own.
	_G.QuestFrameDetailPanel:Hide()
	_G.QuestFrameRewardPanel:Show()
	local rPair = _G.QuestFrameCompleteQuestButton:GetWidth()
		+ _G.QuestFrameCancelButton:GetWidth() + qGap
	local rx, ry = select(4, _G.QuestFrameCompleteQuestButton:GetPoint(1))
	check(rx == -rPair / 2
		and ry == A.Widgets.PANEL_FOOT_H / 2,
		"handing the quest in puts ITS pair in the strip (" .. tostring(rx)
		.. ", " .. tostring(ry) .. ")")
	_G.QuestFrameRewardPanel:Hide()
	_G.QuestFrameDetailPanel:Show()

	-- THE SOCIAL WINDOW. Four tabs over five panes, every pane setAllPoints to
	-- the window - which is the fact the whole thing turns on: a setAllPoints
	-- frame has no points, so moving a pane moves nothing at all and every
	-- piece of content is hung off the WINDOW instead.
	do
	local PN = A:GetModule("panels")
	_G.FriendsFrame:Show()
	PN.Dress(_G.FriendsFrame)
	local fInner = A.Widgets.PANEL_PAD + A.Widgets.WELL_OUTSET
	local fWant = A.Widgets.PANEL_HEAD_H + fInner

	do
		-- ITS TABS ARE TABS. Nothing in this window's dresser laid them out,
		-- so the only thing that ever reached them was the client's own resize
		-- hook - and until that fired they were whatever the pane sweep had
		-- made of them, which is the pill Add Friend and Send Message wear. A
		-- tab and a button are not the same control and are deliberately not
		-- drawn the same way.
		local rail = _G.FriendsFrame.__aetherRails
			and _G.FriendsFrame.__aetherRails.BOTTOM
		local _, tRel = _G.FriendsFrameTab1:GetPoint(1)
		check(rail and rail:IsShown() and tRel == rail,
			"the social window's four tabs stand on a rail of ours (" ..
			tostring(tRel and tRel.GetName and tRel:GetName() or tRel) .. ")")

		local pilled = {}
		for i = 1, 4 do
			local tab = _G["FriendsFrameTab" .. i]
			if tab.__aetherSkin then
				pilled[#pilled + 1] = "FriendsFrameTab" .. i
			end
			if not tab.__aetherTab then
				pilled[#pilled + 1] = "FriendsFrameTab" .. i .. ":untabbed"
			end
		end
		check(#pilled == 0,
			"and none of them is also wearing a button's surface (" ..
			(#pilled > 0 and table.concat(pilled, ",") or "all four clean")
			.. ")")

		-- AND THE GLASS REACHES PAST THE RAIL, or the row sits outside it -
		-- the postbox's case one window along.
		local railY = rail and select(5, rail:GetPoint(1)) or 0
		check(PN.ENTRY.FriendsFrame.insets[4] <= railY,
			"and the glass reaches past them (" ..
			tostring(PN.ENTRY.FriendsFrame.insets[4]) .. " vs " ..
			tostring(railY) .. ")")
	end

	do
		-- WHO YOU ARE ON BATTLE.NET IS AT THE TOP OF THE CONTENT, not in the
		-- band. The client hangs the status dropdown, your tag and the
		-- broadcast button 26 and 27 down from the WINDOW's top edge, which is
		-- the middle of our header - so all three came up printed across the
		-- window's own title.
		local dAt, _, dRelP, dX = _G.FriendsFrameStatusDropdown:GetPoint(1)
		check(dAt == "LEFT" and dRelP == "TOPLEFT"
			and dX == A.Widgets.PANEL_PAD,
			"your status dropdown starts the tool row under the band (" ..
			tostring(dAt) .. "/" .. tostring(dRelP) .. "/" .. tostring(dX)
			.. ")")
		local gAt, gRel = _G.FriendsFrameBattlenetFrame:GetPoint(1)
		check(gAt == "LEFT" and gRel == _G.FriendsFrameStatusDropdown,
			"your tag follows it along the same row (" .. tostring(gAt) .. ")")
		local bAt, _, bRelP =
			_G.FriendsFrameBattlenetFrame.BroadcastButton:GetPoint(1)
		check(bAt == "RIGHT" and bRelP == "TOPRIGHT",
			"and the broadcast button is at the far end of it (" ..
			tostring(bAt) .. "/" .. tostring(bRelP) .. ")")

		-- AND THE TAG IS IN OUR INK. The client draws it in Battle.net's own
		-- blue - 0.345, 0.667, 0.867 - which is a second accent nothing else
		-- in this interface uses, a line under the window's title.
		local tr, tg, tb = _G.FriendsFrameBattlenetFrame.Tag:GetTextColor()
		check(not (tr < 0.4 and tg > 0.6 and tb > 0.8),
			"your tag is re-inked out of Battle.net blue (" ..
			string.format("%.2f %.2f %.2f", tr, tg, tb) .. ")")
		check(_G.FriendsFrameStatusDropdown.__aetherSkin
			and _G.FriendsFrameStatusDropdown.Arrow:GetTexture()
				== A.Media.texture.chevron,
			"and the status dropdown is the same control the trade skill's"
			.. " filters are, chevron and all")
	end


	-- NOT ONE OF THE FIVE PANES IS IN THE BODY LIST, and that is deliberate:
	-- setAllPoints leaves a frame with NO POINTS, so the mover has nothing to
	-- offset and a body list of panes would move nothing while reporting that
	-- it had.
	local paned = {}
	for _, n in ipairs(PN.ENTRY.FriendsFrame.body) do
		if _G[n] and _G[n].GetNumPoints and _G[n]:GetNumPoints() == 0 then
			paned[#paned + 1] = n
		end
	end
	check(#paned == 0, "nothing in the body list is a setAllPoints pane, "
		.. "which has no points to move (" ..
		(#paned > 0 and table.concat(paned, ",") or "none of them") .. ")")

	-- THE SUB-TABS AND THE LIST UNDER THEM TRAVEL TOGETHER. Friends and Ignore
	-- sit 36 above the list they switch; measured against the band each on its
	-- own, the pair would move 36 further than the list and land on it. The
	-- room is RESERVED over the list instead, which makes both short of the
	-- band by the same amount.
	--
	-- AND BOTH CLEAR THE TOOL ROW, which this pane now has one of: the
	-- Battle.net header is chrome and sits in it, so the body starts a row
	-- lower here than it does on a pane with nothing in the row.
	local fRow = A.Widgets.PANEL_GAP + 28
	local subY = select(5, _G.FriendsTabHeaderTab1:GetPoint(1))
	local listY = select(5, _G.FriendsFrameFriendsScrollFrame:GetPoint(1))
	fWant = fWant + fRow
	check(subY == -fWant and listY == -(fWant + 36),
		"the friends sub-tabs sit under the band with their list 36 below "
		.. "them, as the client had it (" .. tostring(subY) .. ", "
		.. tostring(listY) .. ")")

	-- AND THE IGNORE LIST'S ROWS ARE MOVED INTO ITS LIST. A faux scroll frame
	-- is a scroll BAR and nothing else - the client hangs the rows off the
	-- WINDOW - so the list went into the recess and left all nineteen of them
	-- printed on the glass above an empty box.
	local ig1 = _G.FriendsFrameIgnoreButton1
	check(select(2, ig1:GetPoint(1)) == _G.FriendsFrameIgnoreScrollFrame,
		"the ignore rows are re-anchored into the list they belong to")
	local who1 = _G.WhoFrameButton1
	check(select(2, who1:GetPoint(1)) == _G.WhoListScrollFrame,
		"and so are the who list's")

	-- EVERY LIST IN A RECESS OF ITS OWN, and none round the outside.
	local bare = {}
	for _, n in ipairs({ "FriendsFrameFriendsScrollFrame",
		"FriendsFrameIgnoreScrollFrame", "WhoListScrollFrame" }) do
		if not _G[n].__aetherWell then bare[#bare + 1] = n end
		for _, part in ipairs({ "Top", "Bottom", "Middle" }) do
			if _G[n .. part]:GetTexture() ~= 0 then
				bare[#bare + 1] = n .. part
			end
		end
	end
	check(#bare == 0, "all three lists are in recesses of ours with the "
		.. "client's scroll art gone (" ..
		(#bare > 0 and table.concat(bare, ",") or "all three") .. ")")
	check(not (_G.FriendsFrame.__aetherBody
		and _G.FriendsFrame.__aetherBody:IsShown()),
		"and no seventh recess round the three")

	-- A FRIEND'S ROW KEEPS THE LAMP AND THE BADGE. Its backing, the online
	-- lamp and the game badge are all regions of the same button in the same
	-- two layers, so a plain strip takes the two things the row is telling you
	-- along with the plaque behind them.
	local frow = _G.FriendsFrameFriendsScrollFrame.buttons[1]
	check(not frow.background:IsShown() and frow.status:IsShown()
		and frow.gameIcon:IsShown(),
		"a friend's row loses its plaque and keeps its lamp and its badge")

	-- AND A ROW THAT ARRIVES AFTERWARDS IS DRESSED TOO, which is the whole
	-- reason the client's own refresh is hooked.
	--
	-- HybridScrollFrame_CreateButtons makes as many rows as fit the box and
	-- adds more whenever the box's height changes - and changing it is exactly
	-- what dressing this window does. So the rows that existed when the
	-- dresser ran are not the rows the player ends up looking at, and the ones
	-- made afterwards would be the only stone left in the window.
	local before = #_G.FriendsFrameFriendsScrollFrame.buttons
	_G.FriendsList_Update()
	local grown = _G.FriendsFrameFriendsScrollFrame.buttons[before + 1]
	check(grown and not grown.background:IsShown() and grown.status:IsShown(),
		"a row the list grows after we have been past is dressed as well ("
		.. before .. " -> " ..
		#_G.FriendsFrameFriendsScrollFrame.buttons .. ")")

	-- THE WHO LIST'S COLUMNS ARE HEADINGS, NOT BUTTONS. Each is drawn as three
	-- slices of stone tab art and each is a Button with a label on it, so the
	-- sweep for buttons-with-labels hands all five a pressable surface - and a
	-- column head is something you read, not an action you choose. Same
	-- argument that keeps a letter in the postbox from being drawn as a
	-- button, and it had to be made twice.
	local cols = {}
	for i = 1, 5 do
		local n = "WhoFrameColumnHeader" .. i
		for _, part in ipairs({ "Left", "Middle", "Right" }) do
			if _G[n .. part]:IsShown() then cols[#cols + 1] = n .. part end
		end
		if _G[n].__aetherSkin then cols[#cols + 1] = n .. ":surface" end
	end
	check(#cols == 0, "the five column heads lose their stone and are given "
		.. "no surface (" ..
		(#cols > 0 and table.concat(cols, ",") or "all five") .. ")")

	-- ON THE WHO TAB NOW, because a row that serves five panes can only be
	-- read while the pane it belongs to is up.
	--
	-- AND THE FRIENDS TAB'S OWN HEADER GOES WITH IT. FriendsFrame_Update does
	-- `FriendsTabHeader:SetShown(selectedTab == FRIEND_TAB_FRIENDS)`, so the
	-- status dropdown, the tag and the broadcast button are down on every
	-- other tab - which is the only reason one row can serve all five.
	--
	-- AND THE TAB IS CHANGED THE WAY THE PLAYER CHANGES IT, through the
	-- client's own FriendsFrame_Update. Hiding one pane and showing another by
	-- hand is a tidier swap than the client performs and hides both of the
	-- faults this window had: the arbitrary order inside ShowSubFrame, and the
	-- raid pane never firing OnShow because it was shown all along.
	_G.FriendsFrame.selectedTab = 2
	_G.FriendsFrame_Update()

	-- THE QUERY IS CHROME AND GOES IN THE TOOL ROW. The client hangs it off
	-- the window's BOTTOM edge, which is where the footer strip now is - so
	-- left alone it sat under Refresh and Add Friend.
	local qAt, qRel, qRelP, qX, qY = _G.WhoFrameEditBox:GetPoint(1)
	check(qAt == "LEFT" and qRelP == "TOPLEFT" and qX == A.Widgets.PANEL_PAD,
		"the who query is in the tool row under the band, not in the footer ("
		.. tostring(qAt) .. "/" .. tostring(qRelP) .. "/" .. tostring(qX) .. ")")
	check(_G.WhoFrameEditBox.searchIcon:IsShown()
		and _G.WhoFrameEditBoxLeft:GetTexture() == 0,
		"and it keeps its magnifying glass, which is in the same layer as the "
		.. "border that came off")

	-- AND THE COLUMN HEADS AND THE LIST UNDER THEM TRAVEL TOGETHER, the same
	-- reserved-room trick the sub-tabs use one pane along: the heads sit 30
	-- above the list, so 30 is reserved over the list and both are short of
	-- the band by the same amount.
	local colY = select(5, _G.WhoFrameColumnHeader1:GetPoint(1))
	local wlY = select(5, _G.WhoListScrollFrame:GetPoint(1))
	check(wlY - colY == -30, "the who columns keep the 30 the client left "
		.. "between them and their list (" .. tostring(colY) .. ", "
		.. tostring(wlY) .. ")")

	-- AND WHAT THE QUERY FOUND IS AT THE FOOT OF THE BODY, not under the band.
	-- The client anchors the count to the SEARCH BOX - BOTTOM to its TOP - so
	-- moving the box into the tool row took the count up with it, where "0
	-- People Found" read as a subtitle for the window.
	--
	-- Off the footer's own hairline rather than off the list: the list keeps
	-- the height the client gave it and stops well short of the body's floor,
	-- so a count hung under the list floats in the middle of the window.
	local totAt, totRel, totRelP, _, totY = _G.WhoFrameTotals:GetPoint(1)
	check(totAt == "BOTTOM" and totRel == _G.FriendsFrame.__aetherFootRule
		and totRelP == "TOP" and totY == A.Widgets.PANEL_GAP,
		"the who count sits at the foot of the body, over the footer's rule ("
		.. tostring(totAt) .. "/" .. tostring(totRelP) .. "/" .. tostring(totY)
		.. ")")

	-- ONE ROW SERVES FIVE PANES, AND IT IS LAID OUT FROM WHAT IS VISIBLE.
	--
	-- What the client hides when it swaps tabs is the PANE; every child of it
	-- goes on reporting itself shown. Asked that question the who query held
	-- the row's first slot on the raid tab and pushed the raid's own switch
	-- along behind it - which is the same trap the footer's middle group was
	-- already written round.
	-- AND THE RAID TAB IS THE ONE THAT NEVER FIRED A HOOK AT ALL: its pane is
	-- shown from load, so the client's own Show() on it does nothing and no
	-- OnShow of ours runs. First visit came up with the blurb still under the
	-- band and Convert to Raid wherever the last pane had left it.
	_G.FriendsFrame.selectedTab = 4
	_G.FriendsFrame_Update()
	check(_G.RaidFrame:GetParent() == _G.FriendsFrame,
		"the raid pane is claimed by this window before it is shown")
	local blurbY = select(5, _G.RaidFrameRaidDescription:GetPoint(1))
	check(blurbY < -(A.Widgets.PANEL_HEAD_H + A.Widgets.PANEL_PAD),
		"and its blurb is below the band rather than printed across it (" ..
		tostring(blurbY) .. ")")
	local aAt, aRel, aRelP, aX = _G.RaidFrameAllAssistCheckButton:GetPoint(1)
	check(aAt == "LEFT" and aX == A.Widgets.PANEL_PAD,
		"on the raid tab the raid's own switch starts the tool row (" ..
		tostring(aAt) .. " at " .. tostring(aX) .. ")")

	-- AND THE STRIP IS CENTRED ON WHAT IS UP. Convert to Raid is the raid
	-- tab's one action, so it is centred alone - counting the seven buttons
	-- the other three panes own would push it most of the way off the window.
	--
	-- The hidden panes' buttons are LEFT where they last were rather than put
	-- back, which is the same thing the quest giver's reward panel does: they
	-- are invisible while their pane is down and re-laid when it comes up.
	--
	-- OFF THE RAIL, because this window has one: 15e stacks the strip ABOVE
	-- the tab row rather than on the window's own bottom edge, and the tabs
	-- hang below that edge. Centred on the panel instead, the strip sat on top
	-- of the tabs.
	local cRail = _G.FriendsFrame.__aetherRails
		and _G.FriendsFrame.__aetherRails.BOTTOM
	local cAt, cRel, cRelP, cX, cY = _G.RaidFrameConvertToRaidButton:GetPoint(1)
	check(cRel == cRail and cRelP == "TOP"
		and cX == -_G.RaidFrameConvertToRaidButton:GetWidth() / 2
		and cY == A.Widgets.PANEL_FOOT_H / 2,
		"Convert to Raid is centred in the strip on its own, above the tab "
		.. "rail (" .. tostring(cX) .. ", " .. tostring(cY) .. ")")

	-- AND BACK ON THE FRIENDS TAB. This is the swap that broke it: the pane
	-- going up can be shown before the raid pane coming down is hidden, so a
	-- hook on the first one sees a window with two panes up and lays Convert to
	-- Raid into the friends list's strip - which pushed Add Friend and Send
	-- Message a button's width apart, one off each side of the glass.
	_G.FriendsFrame.selectedTab = 1
	_G.FriendsFrame_Update()
	local pair = _G.FriendsFrameAddFriendButton:GetWidth()
		+ _G.FriendsFrameSendMessageButton:GetWidth() + 12
	check(select(4, _G.FriendsFrameAddFriendButton:GetPoint(1)) == -pair / 2,
		"coming back off the raid tab leaves the strip centred on its own two "
		.. "buttons (" ..
		tostring(select(4, _G.FriendsFrameAddFriendButton:GetPoint(1)))
		.. " of " .. tostring(-pair / 2) .. ")")

	-- AND BACK ON THE FRIENDS TAB WITH THE RAID PANE CLAIMED BY SOMEBODY ELSE,
	-- which is the state the client leaves it in.
	--
	-- RaidFrame carries no parent in its XML - "Parent set dynamically, see
	-- ClaimRaidFrame" - and is not hidden either, so once its addon has loaded
	-- it is a SHOWN frame with nothing above it. A frame outside UIParent's
	-- hierarchy is never drawn, but IsVisible walks the parent chain and a
	-- chain that simply ends has no hidden link in it: every child answers yes.
	--
	-- So Convert to Raid took a slot in this window's strip, 115 wide, and drew
	-- nothing in it - Add Friend and Send Message a button's width further
	-- apart than they should be, one hanging off each side of the glass. And
	-- only after the raid tab had been visited once, because until then the
	-- button does not exist at all.
	--
	-- The client makes the same test: FriendsFrame_ShowSubFrame hides RaidFrame
	-- only `if RaidFrame:GetParent() == FriendsFrame`.
	_G.RaidFrame:SetParent(nil)
	_G.RaidFrame:Show()
	PN.Dress(_G.FriendsFrame)
	check(_G.RaidFrameConvertToRaidButton:IsVisible(),
		"a pane with no parent at all still reports its buttons visible")
	local backX = select(4, _G.FriendsFrameAddFriendButton:GetPoint(1))
	check(backX == -pair / 2,
		"but it is not this window's button and takes no room in its strip ("
		.. tostring(backX) .. " of " .. tostring(-pair / 2) .. ")")
	-- AND THE DUMP SAYS SO OUT LOUD, because the tree above it does not. A
	-- report of what the client built cannot show why two buttons are a
	-- button's width too far apart - what is missing is what OUR layout can
	-- see, and a dump of this window while it was wrong said nothing at all.
	do
		local box
		local realShow = A.Errors.ShowText
		A.Errors.ShowText = function(_, text) box = text end
		A:DumpPanel("FriendsFrame")
		A.Errors.ShowText = realShow
		check(box and box:find("NOT OURS", 1, true) ~= nil,
			"the dump names the widget that is visible but not this window's")
		check(box and box:find("FriendsFrameAddFriendButton", 1, true) ~= nil
			and box:find("WhoFrameEditBox", 1, true) ~= nil,
			"and lists every member of the strip and the tool row beside it")
	end

	_G.RaidFrame:Hide()
	_G.RaidFrame:SetParent(_G.FriendsFrame)
	PN.Dress(_G.FriendsFrame)
	_G.FriendsFrame:Hide()
	end

	-- THE TOOLBOX'S GUTTER. The client docks its own windows against the left
	-- edge of the screen and the Toolbox's rail lives there too, so the
	-- character sheet opened on top of the handle and the handle could not be
	-- reached without shutting the sheet.
	do
		local PN = A:GetModule("panels")
		local TBg = A:GetModule("toolbox")

		-- APPLIED BY THE DRESSER ITSELF, not only when something asks for it. The
		-- offset is read when the panel system PLACES a window, so it has to be
		-- set before one opens rather than in answer to it opening.
		PN:Skin()
		check((_G.__panelXOffset(_G.CharacterFrame) or 0) > 0,
			"skinning the panels moves them clear of the rail (" ..
			tostring(_G.__panelXOffset(_G.CharacterFrame)) .. ")")

		-- NOT BY DETACHING THE WINDOW. Clearing its `area` is supported and was
		-- researched, and it forfeits whileDead, checkFit and bottomClampOverride
		-- and turns every combat toggle into a blocked-action error. What moves it
		-- is the panel system's OWN number: a left-area window is placed at
		-- leftOffset + xoffset.
		PN:LayoutGutter(48)
		check(_G.CharacterFrame:GetAttribute("UIPanelLayout-area") == "left",
			"the character sheet is still a panel of the client's, not detached")
		check(_G.__panelXOffset(_G.CharacterFrame) == 48,
			"and is moved clear of the rail by the panel system's own offset (" ..
			tostring(_G.__panelXOffset(_G.CharacterFrame)) .. ")")

		-- ADDED TO THE CLIENT'S NUMBER, not instead of it. The group finder carries
		-- -16 of its own, and a gutter that replaced it would drag that window
		-- sixteen units away from where the client wanted it.
		check(_G.__panelXOffset(_G.LFGParentFrame) == 32,
			"a window with an offset of its own keeps it, plus the gutter (" ..
			tostring(_G.__panelXOffset(_G.LFGParentFrame)) .. " of 32)")

		-- AND NOTHING IS WRITTEN INTO UIPanelWindows, which the client reads inside
		-- secure code. SetUIPanelAttribute stamps the FRAME; the table keeps the
		-- client's own numbers, which is also why the original is never lost.
		check(_G.UIPanelWindows.LFGParentFrame.xoffset == -16
			and _G.UIPanelWindows.CharacterFrame.xoffset == nil,
			"and the client's own table is not written to at all")

		-- A CENTRED WINDOW IS LEFT ALONE. UIParentPanelManager deliberately ignores
		-- xoffset when it centres one, so moving it would be a write that does
		-- nothing dressed up as a fix.
		check(_G.GameMenuFrame == nil
			or _G.GameMenuFrame:GetAttribute("UIPanelLayout-defined") == nil,
			"a centred window is not touched, because the offset would do nothing")

		-- THE GUTTER IS MEASURED, NOT DECLARED: the rail is drawn at the profile's
		-- scale and the panel system's offsets are in UIParent's, so a constant
		-- would be right at one scale and wrong at every other. And it is NOUGHT
		-- when the rail is not on that edge - there is nothing to clear.
		-- THE REAL FUNCTION BACK, not a closure that answers the same thing.
		-- Three toolbox checks further down move the dock and read it again, and
		-- a stand-in that always says LEFT makes all three of them fail.
		local realDock = TBg and TBg.Dock
		if TBg then
			TBg.Dock = function() return "RIGHT" end
			PN:LayoutGutter()
			check(_G.__panelXOffset(_G.CharacterFrame) == 0,
				"with the toolbox docked elsewhere the windows go back to the "
				.. "client's own place (" ..
				tostring(_G.__panelXOffset(_G.CharacterFrame)) .. ")")
			TBg.Dock = realDock
			PN:LayoutGutter()
			check((_G.__panelXOffset(_G.CharacterFrame) or 0) > 0,
				"and clear of it again when it comes back")

			-- MOVING THE RAIL SAYS SO NOW. The offset is read when a window is
			-- PLACED, so a dock change that left it until the next login is a
			-- character sheet sitting in a gutter with no rail in it.
			if TBg.SetDock then
				TBg:SetDock("RIGHT")
				check(_G.__panelXOffset(_G.CharacterFrame) == 0,
					"docking the toolbox elsewhere hands the windows back at once (" ..
					tostring(_G.__panelXOffset(_G.CharacterFrame)) .. ")")
				TBg:SetDock("LEFT")
				check((_G.__panelXOffset(_G.CharacterFrame) or 0) > 0,
					"and takes the gutter back when it returns")
			end

			-- AND SWITCHING THE PANELS OFF PUTS THEM WHERE THE CLIENT HAD THEM.
			-- Through the module's own OnDisable rather than by calling the mover
			-- with a nought: what is being checked is that switching off REACHES it.
			PN:OnDisable()
			check(_G.__panelXOffset(_G.CharacterFrame) == 0
				and _G.__panelXOffset(_G.LFGParentFrame) == -16,
				"switching the panels off hands every window back to the client's "
				.. "own place (" .. tostring(_G.__panelXOffset(_G.CharacterFrame))
				.. ", " .. tostring(_G.__panelXOffset(_G.LFGParentFrame)) .. ")")
			PN:OnEnable()
			check((_G.__panelXOffset(_G.CharacterFrame) or 0) > 0,
				"and switching them on again takes the gutter back")
		end
	end
	-- SOMETHING SAYING WHERE YOU ARE IN A FIELD. Reported from the game as a
	-- letter you can type into with no cursor in it - and nothing this addon
	-- does can hide the engine's own: it is not a region, so no sweep reaches
	-- it, the well behind the box is a frame level below the box's, and the
	-- text beside it is perfectly legible. So the caret is ours instead, where
	-- it can be seen, coloured and checked.
	do
		local box = _G.SendMailSubjectEditBox
		local caret = box and box.__aetherCaret
		check(caret ~= nil,
			"a dressed field carries a caret of ours")
		check(caret and not caret:IsShown(),
			"which is down until the field is the one being typed in - four fields "
			.. "on a letter is four cursors otherwise")

		-- WHERE THE CLIENT SAYS IT IS. OnCursorChanged hands over the caret's x,
		-- y and HEIGHT in the box's own coordinates, which is exactly the question
		-- and saves measuring the text ourselves. y is negative downward, which is
		-- already the sign SetPoint wants.
		caret = caret or { GetPoint = function() end, GetHeight = function() end,
			GetWidth = function() end, GetAlpha = function() end,
			IsShown = function() end }
		local focus = box:GetScript("OnEditFocusGained")
		if focus then focus(box) end
		check(caret:IsShown(), "and comes up when the field takes focus")

		local moved = box:GetScript("OnCursorChanged")
		if moved then moved(box, 37, -4, 1, 15) end
		local at, rel, relP, cx, cy = caret:GetPoint(1)
		check(at == "TOPLEFT" and rel == box and relP == "TOPLEFT"
			and cx == 37 and cy == -4,
			"and it goes where the client says the cursor is (" .. tostring(cx)
			.. ", " .. tostring(cy) .. ")")
		check(caret:GetHeight() == 15,
			"at the height the client says, rather than a guess at the font (" ..
			tostring(caret:GetHeight()) .. ")")
		check(caret:GetWidth() == 1,
			"and a hairline wide, because a text cursor is a hairline")

		-- IT BLINKS, because a cursor that does not is hard to find in a line of
		-- type and easy to mistake for a letter.
		local tick = box:GetScript("OnUpdate")
		local lit = caret:GetAlpha()
		if tick then tick(box, 1.0) end
		check(caret:GetAlpha() ~= lit,
			"it blinks rather than sitting there being mistaken for a letter (" ..
			tostring(lit) .. " to " .. tostring(caret:GetAlpha()) .. ")")

		-- AND GOES WITH THE FOCUS.
		local lost = box:GetScript("OnEditFocusLost")
		if lost then lost(box) end
		check(not caret:IsShown(),
			"and goes away with the focus, so only the field you are in has one")

		-- THE LETTER ITSELF TOO, which does not go through Reskin.EditBox: it is a
		-- ScrollingEditBox and the box you type in is inside it.
		local body = _G.MailEditBox and _G.MailEditBox.GetEditBox
			and _G.MailEditBox:GetEditBox()
		check(body == nil or body.__aetherCaret ~= nil,
			"the letter you are writing has one as well as the fields above it")
	end
	-- THE GROUP FINDER: two windows behind two tabs, both setAllPoints to the
	-- frame, on the OLD parchment build carrying MODERN content - a
	-- WowScrollBoxList for its results and two WowStyle1 dropdowns for its
	-- filters, inside three slabs of UI-LFG-FRAME.
	do
		local PN = A:GetModule("panels")
		local lfg = _G.LFGParentFrame
		lfg:Show()
		-- THROUGH THE CLIENT'S OWN TAB CLICK, not by hiding a pane by hand: a
		-- tidier swap than the client performs is what hid two faults in the
		-- social window.
		_G.LFGParentFrameTab2_OnClick()
		PN.Dress(lfg)

		-- ITS TITLE IS PER PANE. The frame's own has nothing in it; the words
		-- are printed inside whichever pane is up, the way the postbox prints
		-- INBOX and SEND MAIL inside its two.
		check(lfg.__aetherTitle == _G.LFGBrowseFrameFrameTitle,
			"the group finder is titled by the pane it is showing")
		local gAt, gRel = _G.LFGBrowseFrameFrameTitle:GetPoint(1)
		check(gAt == "TOP" and gRel == lfg.__aetherPanel,
			"centred in the header band like every other window's (" ..
			tostring(gAt) .. ")")

		-- NEITHER PANE IS IN THE BODY LIST, and that is deliberate: both are
		-- setAllPoints to the window, so moving one moves the window's own
		-- extent and nothing inside it. Everything the player looks at is hung
		-- off a pane at its own fixed distance and is listed here by name.
		local paned = {}
		for _, n in ipairs({ "LFGBrowseFrame", "LFGListingFrame" }) do
			for _, part in ipairs(PN.ENTRY.LFGParentFrame.body) do
				if part == n then paned[#paned + 1] = n .. ":in body" end
			end
		end
		check(#paned == 0, "neither pane is in the body list, having no points to move by (" ..
			(#paned > 0 and table.concat(paned, ",") or "both out") .. ")")

		-- ITS TWO TABS ARE TABS, not buttons wearing a pill. A tab is a Button
		-- with a label on it and a child of the window, which is exactly what the
		-- pane sweep looks for.
		local rail = lfg.__aetherRails and lfg.__aetherRails.BOTTOM
		local pilled = {}
		for i = 1, 2 do
			local tab = _G["LFGParentFrameTab" .. i]
			if tab.__aetherSkin then pilled[#pilled + 1] = "Tab" .. i .. ":pill" end
			if not tab.__aetherTab then pilled[#pilled + 1] = "Tab" .. i .. ":untabbed" end
		end
		check(rail and rail:IsShown() and #pilled == 0,
			"its two tabs stand on a rail of ours and wear no button surface (" ..
			(#pilled > 0 and table.concat(pilled, ",") or "both clean") .. ")")

		-- THE PARCHMENT GOES, all three slabs of it and the decorative atlas
		-- behind the list - every one a region of the pane rather than of the
		-- window, so a sweep of the window reaches none of them.
		local stone = {}
		for _, n in ipairs({ "LFGBrowseFrameFrameBackgroundTop",
			"LFGBrowseFrameFrameBackgroundBottom", "LFGListingFrameFrameBackgroundTop",
			"LFGParentFramePortraitIcon" }) do
			if _G[n]:GetTexture() ~= 0 then stone[#stone + 1] = n end
		end
		if _G.LFGBrowseFrame.BackgroundArt:GetTexture() ~= 0 then
			stone[#stone + 1] = "BackgroundArt"
		end
		check(#stone == 0, "the parchment, the eye and the art behind the list all come off (" ..
			(#stone > 0 and table.concat(stone, ",") or "all of it") .. ")")

		-- THE TWO FILTERS AND THE REFRESH ARE CHROME and go in the tool row. The
		-- client hangs them 94 down from the window's top, which is our header
		-- band and a line under it.
		local dAt, _, dRelP, dX = _G.LFGBrowseFrameCategoryDropdown:GetPoint(1)
		check(dAt == "LEFT" and dRelP == "TOPLEFT" and dX == A.Widgets.PANEL_PAD,
			"the category filter starts the tool row under the band (" ..
			tostring(dAt) .. "/" .. tostring(dRelP) .. "/" .. tostring(dX) .. ")")
		local oAt, _, oRelP = _G.LFGBrowseFrameOptionsButton:GetPoint(1)
		check(oAt == "RIGHT" and oRelP == "TOPRIGHT",
			"and the gear is at the far end of it (" .. tostring(oAt) .. "/" ..
			tostring(oRelP) .. ")")

		-- THE TWO GEARS ARE PICTURES. Each keeps its own glyph and loses the
		-- plate behind it - and IconButton has to be TOLD which region the
		-- picture is, because on both of these the normal texture is the plate
		-- and the glyph is a region of its own.
		local plates = {}
		for _, n in ipairs({ "LFGBrowseFrameOptionsButton",
			"LFGListingFrameOptionsButton" }) do
			local btn = _G[n]
			if btn.Icon and btn.Icon:GetTexture() == 0 then
				plates[#plates + 1] = n .. ":glyph gone"
			end
			local norm = btn.GetNormalTexture and btn:GetNormalTexture()
			if norm and norm:GetTexture() ~= 0 and norm ~= btn.Icon then
				plates[#plates + 1] = n .. ":plate kept"
			end
		end
		check(#plates == 0, "both gears keep the glyph and lose the plate (" ..
			(#plates > 0 and table.concat(plates, ",") or "both") .. ")")

		-- AND SEARCH AGAIN IS OUR OWN CIRCULAR ARROW ON OUR OWN ROUND BUTTON.
		-- The client's is a 16px glyph centred on a 32px stone square, and a
		-- slot cell sized to the button stretched it across the whole face. It
		-- is the same gesture the character sheet's model turners are - go round
		-- again - so it takes the same control, from the same one drawing.
		local again = _G.LFGBrowseFrameRefreshButton
		check(again.__aetherRound
			and again.__aetherRound:GetTexture() == A.Media.icons.file,
			"search again wears our own circular arrow rather than a 16px client "
			.. "glyph stretched across a 32px cell")
		check(again.Icon:GetTexture() == 0
			and (again:GetNormalTexture() == nil
				or again:GetNormalTexture():GetTexture() == 0),
			"and the client's glyph and its stone square are both gone")
		check(_G.LFGBrowseFrameCategoryDropdown.Arrow:GetTexture()
			== A.Media.texture.chevron,
			"and the two filters are the control the trade skill's are")

		-- THE LIST REACHES THE FLOOR OF THE RECESS. It is a fixed 324 by 282 in a
		-- frame the client made 512 tall; ours is half as tall again, so left
		-- alone it sits in a recess with a hand's width of empty glass under it
		-- and shows fewer results than there is room for.
		local box = _G.LFGBrowseFrameScrollBox
		check(box:GetHeight() > 282, "the results list is stretched to the recess rather than left at the height the client gave it (" ..
			tostring(box:GetHeight()) .. " of 282)")
		check(box.__grew ~= nil, "and the box was asked to lay itself out again after it, which is when it acquires its rows")

		-- ITS ROWS ARE POOLED, and a scroll box acquires them during its OWN
		-- layout - after the window's update has returned. So a row minted late
		-- is dressed too, or it is the only stone left in the window.
		-- AND ONE MORE ACQUIRED AFTER THE DRESSER HAS BEEN PAST, which is what
		-- scrolling a real list does over and over. Nothing but the hook on the
		-- box's own Update can reach that one.
		box.__wantRow = true
		box:Update()
		local raw = {}
		for _, row in ipairs(box.__rows) do
			if row.Selected:GetTexture() ~= 0 or row.ResultBG:GetTexture() ~= 0 then
				raw[#raw + 1] = "bar"
			end
			if row.PartyIcon:GetTexture() == 0 then raw[#raw + 1] = "icon gone" end
			-- ITS INK IS THE CLIENT'S BUSINESS AND ITS LETTERING IS OURS. A name
			-- in this list is coloured to mean something - whose group it is,
			-- what class they are - and Reskin.Font lifts only ink chosen for
			-- PARCHMENT. What has to change is the face it is set in.
			if select(1, row.Name:GetFont())
				~= A.Media.font[A.Media.style.pnBody[1]] then
				raw[#raw + 1] = "font"
			end
		end
		check(#raw == 0, "every row in the box - the one it minted late"
			.. " included - loses its bars, keeps its icons and takes our"
			.. " lettering (" .. #box.__rows .. " rows, " ..
			(#raw > 0 and table.concat(raw, ",") or "all clean") .. ")")

		-- AND THE STRIP IS LAID OUT FOR THE PANE THAT IS UP. Four buttons across
		-- two panes and only one pane is ever showing, so the other pane's pair
		-- must not take room between them.
		local bPair = _G.LFGBrowseFrameSendMessageButton:GetWidth()
			+ _G.LFGBrowseFrameGroupInviteButton:GetWidth() + 12
		local bAt, bRel, bRelP, bX, bY =
			_G.LFGBrowseFrameSendMessageButton:GetPoint(1)
		check(bAt == "LEFT" and bRel == rail and bRelP == "TOP"
			and bX == -bPair / 2 and bY == A.Widgets.PANEL_FOOT_H / 2,
			"Send Message starts the pair, centred in the strip above the tab rail (" .. tostring(bX) .. ", " .. tostring(bY) .. ")")

		-- ON THE LISTING TAB NOW, which is tab ONE - it reads backwards until you
		-- look at LFGParentFrameTab1_OnClick.
		_G.LFGParentFrameTab1_OnClick()
		PN.Dress(lfg)
		check(lfg.__aetherTitle == _G.LFGListingFrameFrameTitle,
			"the title follows the tab")

		-- THE ROLE STRIP AND THE VIEW UNDER IT TRAVEL TOGETHER. The client puts
		-- the role buttons 60 down and the views 128, so measured against the
		-- band each on its own the strip travels 74 and the view travels 6 - and
		-- the strip lands on top of the view. The room is RESERVED over the view
		-- instead, which is the social window's sub-tab trick.
		local roleY = select(5, _G.LFGListingFrameSoloRoleButtons:GetPoint(1))
		local viewY = select(5, _G.LFGListingFrameCategoryView:GetPoint(1))
		check(viewY - roleY == -62,
			"the listing's views clear the role strip above them (" ..
			tostring(roleY) .. ", " .. tostring(viewY) .. ")")

		local lPair = _G.LFGListingFrameBackButton:GetWidth()
			+ _G.LFGListingFramePostButton:GetWidth() + 12
		check(select(4, _G.LFGListingFrameBackButton:GetPoint(1)) == -lPair / 2,
			"and the strip is Back and Post alone, not all four buttons (" ..
			tostring(select(4, _G.LFGListingFrameBackButton:GetPoint(1)))
			.. " of " .. tostring(-lPair / 2) .. ")")
		-- AND ALL OF IT SURVIVES THE PLAYER CHANGING TABS - with no dress of our
		-- own after the click, which is the whole point: what the client does on
		-- that path has to be answered by something already hooked.
		do
			_G.LFGParentFrameTab2_OnClick()
			_G.LFGParentFrameTab1_OnClick()

			-- THE TABS ARE STILL ON THE RAIL. Each pane re-anchors BOTH of them from
			-- its OnShow - the client's own "baby hack", 45 up from the frame on one
			-- pane and 43 on the other - and neither is where our rail is, so the row
			-- left the rail and sat above it the moment a tab was clicked. Nothing
			-- calls PanelTemplates_TabResize on that path, so the hook on that never
			-- fires for it either.
			local rail3 = lfg.__aetherRails.BOTTOM
			local tAt, tRel, _, _, tY = _G.LFGParentFrameTab1:GetPoint(1)
			check(tAt == "BOTTOMLEFT" and tRel == rail3 and tY == 0,
				"the tabs are still standing on the rail after a tab change (" ..
				tostring(tAt) .. "/" .. tostring(tY) .. ")")

			-- AND THE STRIP IS THIS PANE'S TWO BUTTONS. LFGParentFrameTab1_OnClick
			-- shows the listing and THEN hides the browse, so anything hooked to the
			-- pane going up fires while the pane coming down is still visible - and
			-- the strip is laid out for four buttons instead of two, which is Back and
			-- List Self a button's width too far apart.
			local lp = _G.LFGListingFrameBackButton:GetWidth()
				+ _G.LFGListingFramePostButton:GetWidth() + 12
			check(select(4, _G.LFGListingFrameBackButton:GetPoint(1)) == -lp / 2,
				"and the strip is laid out for the pane that ended up showing (" ..
				tostring(select(4, _G.LFGListingFrameBackButton:GetPoint(1)))
				.. " of " .. tostring(-lp / 2) .. ")")

			-- AND ON THE PATH THAT CHANGES PANE WITHOUT A TAB CLICK. The listing's
			-- own "find my group" hides one pane and shows the other by hand, so
			-- the hook on the click functions never fires - and the pane it shows
			-- moves both tabs off the rail from its OnShow all the same.
			_G.LFGParentFrame_SearchActiveEntry()
			local sAt, sRel, _, _, sY = _G.LFGParentFrameTab1:GetPoint(1)
			check(sAt == "BOTTOMLEFT" and sRel == rail3 and sY == 0,
				"and after a pane change that no tab click was part of (" ..
				tostring(sAt) .. "/" .. tostring(sY) .. ")")
			_G.LFGParentFrameTab1_OnClick()

			-- ITS X HAS NO NAME AND NO PARENT KEY, so nothing could ask for it and it
			-- kept the client's red one on a window where everything else had come
			-- off. Found by shape instead: the only nameless Button child this window
			-- has, the two tabs being named and everything else a Frame.
			check(lfg.__shut.__aetherClose ~= nil
				and (lfg.__shut:GetNormalTexture() == nil
					or lfg.__shut:GetNormalTexture():GetTexture() == 0),
				"the window's X is ours, though the client gave it no name to ask for")
		end
		lfg:Hide()
	end
	-- THE TRADE WINDOW: a dozen pieces hung off the frame at their own fixed
	-- offsets, and the two nearest the top - the names, five units down - are
	-- inside our header band.
	--
	-- MOVED TOGETHER, by the deepest of them. Shifting each by what IT is short
	-- of squeezes the layout: the names would travel eighty units and the slot
	-- columns eight, so what the client laid out as rows becomes a heap.
	do
	_G.TradeFrame:Show()
	A:GetModule("panels").Dress(_G.TradeFrame)
	-- WELL_OUTSET AND NOT WELL_PAD. This window's content is already in six
	-- recesses of the client's, so the entry asks for no body well round the
	-- outside - and a window of that shape is inset by what its own rims cost
	-- rather than by the body padding.
	local trInner = A.Widgets.PANEL_PAD + A.Widgets.WELL_OUTSET
	-- ...PLUS THE ROOM RESERVED FOR THE PURSES. They are the one row in this
	-- window that cannot travel - the client has forbidden your own - so the
	-- body starts below where they already are rather than at the usual 80.
	local trLead = A:GetModule("panels").ENTRY.TradeFrame.lead or 0
	-- MEASURED FROM THE COLUMNS, which are the topmost thing in the body now
	-- that the two names are in the band. They used to set this from five
	-- units down, and `together` handed that same 99 to everything - which
	-- left a hand's width of empty glass between the purses and the goods.
	local trDown = A.Widgets.PANEL_HEAD_H + trInner + trLead - 83
	local slotY = select(5, _G.TradePlayerItem1:GetPoint(1))
	local insY = select(5, _G.TradePlayerItemsInset:GetPoint(1))
	check(insY == -(83 + trDown) and slotY == -(89 + trDown),
		"the columns and the slots in them move by the SAME amount (" ..
		tostring(insY) .. ", " .. tostring(slotY) .. ")")

	-- AND THEY START A GAP BELOW THE PURSES, which is what the reserved room
	-- is for: the money row ends 90 down and cannot move, so anything laid out
	-- at the usual 80 lands on top of it.
	check(-insY - 90 == A.Widgets.PANEL_GAP,
		"the goods start one gap under the money row - no more and no less ("
		.. tostring(-insY - 90) .. " of " .. tostring(A.Widgets.PANEL_GAP)
		.. ")")

	-- THE TWO NAMES ARE THIS WINDOW'S TITLE, and they are in the band with it.
	-- It takes two strings to say what this window is - two people, one per
	-- column - and one centred string cannot carry that.
	local trGlass = _G.TradeFrame.__aetherPanel
	local nAt, nRel, nRelP, nX, nY = _G.TradeFramePlayerNameText:GetPoint(1)
	check(nAt == "CENTER" and nRel == trGlass and nRelP == "TOP"
		and nY == -A.Widgets.PANEL_HEAD_H / 2,
		"the names sit in the band at the title's own baseline (" ..
		tostring(nAt) .. "/" .. tostring(nRelP) .. "/" .. tostring(nY) .. ")")
	local col = _G.TradePlayerItemsInset
	check(nX and math.abs(nX - ((col:GetLeft() + col:GetRight()) / 2
		- (trGlass:GetLeft() + trGlass:GetRight()) / 2)) < 0.5,
		"and each one over the middle of the goods it names, not where the "
		.. "client had it (" .. tostring(nX) .. ")")

	local slotX = select(4, _G.TradePlayerItem1:GetPoint(1))

	-- BOTH CORNERS OF AN INSET, not one. These stone recesses are pinned by
	-- TOPLEFT and BOTTOMRIGHT both; a mover that rewrote a single point would
	-- stretch one of them across the window.
	check(_G.TradePlayerItemsInset:GetNumPoints() == 2,
		"an inset keeps both of the corners it was pinned by (" ..
		tostring(_G.TradePlayerItemsInset:GetNumPoints()) .. ")")

	-- AND TRADE AND CANCEL ARE IN THE STRIP. They sat in the window's bottom
	-- right corner, five up from the glass and under the recess.
	local trPair = _G.TradeFrameTradeButton:GetWidth()
		+ _G.TradeFrameCancelButton:GetWidth() + 12
	local tbp, tbrel, tbrelP, tbx, tby = _G.TradeFrameTradeButton:GetPoint(1)
	check(tbp == "LEFT" and tbrel == _G.TradeFrame.__aetherPanel
		and tbrelP == "BOTTOM" and tbx == -trPair / 2
		and tby == A.Widgets.PANEL_FOOT_H / 2,
		"trade starts the pair, centred in the footer strip (" .. tostring(tbx)
		.. ", " .. tostring(tby) .. ")")

	-- AND SO DO THE PIECES PINNED TO THE WINDOW'S OWN CORNERS. The two enchant
	-- recesses and the second wrap round their purse are anchored to the frame
	-- rather than chained off anything above them, so a body list without them
	-- leaves three pieces where the client put them while the rest of the
	-- window travels down past them.
	local stuck = {}
	for _, n in ipairs({ "TradePlayerEnchantInset", "TradeRecipientEnchantInset",
		"TradeFramePlayerEnchantText",
		"TradeHighlightPlayer" }) do
		local y = select(5, _G[n]:GetPoint(1))
		local was = ({ TradePlayerEnchantInset = -354,
			TradeRecipientEnchantInset = -354,
			TradeFramePlayerEnchantText = -360, TradeHighlightPlayer = -85 })[n]
		if y ~= was - trDown then stuck[#stuck + 1] = n .. "@" .. tostring(y) end
	end
	check(#stuck == 0, "everything pinned to the window travels with it (" ..
		(#stuck > 0 and table.concat(stuck, ",") or "all four") .. ")")

	-- AND THE MONEY ROW DOES NOT TRAVEL AT ALL, because one piece of it
	-- cannot. TradeFrame_OnLoad forbids your own purse, so moving the four
	-- pieces that CAN move only separates them from the one that cannot: the
	-- recesses went down with the window and your gold, silver and copper
	-- stayed at 61, above the two players' names, with an empty recess a
	-- hundred units below them.
	local drift = {}
	for n, was in pairs({ TradePlayerInputMoneyInset = -58,
		TradeRecipientMoneyInset = -58, TradeRecipientMoneyBg = -60,
		TradeRecipientMoneyFrame = -64 }) do
		local y = select(5, _G[n]:GetPoint(1))
		if y ~= was then drift[#drift + 1] = n .. "@" .. tostring(y) end
	end
	check(#drift == 0, "the money row stays exactly where the client has it, "
		.. "which is the only place the forbidden half of it can be (" ..
		(#drift > 0 and table.concat(drift, ",") or "all four") .. ")")

	-- AND NOTHING IN THIS WINDOW MOVES SIDEWAYS EITHER, for the same reason.
	-- The margin is made by widening the GLASS past the frame instead, which
	-- MeasureTop measures against - so the sideways shift comes out as zero
	-- rather than needing a flag of its own, and every recess still stands the
	-- standard distance in from the rim.
	check(slotX == 14 and select(4, _G.TradeRecipientItem1:GetPoint(1)) == 182,
		"nothing in the trade window travels sideways (" .. tostring(slotX)
		.. ")")
	check(_G.TradePlayerItemsInset:GetLeft() - trGlass:GetLeft() == trInner,
		"and the glass reaching past the frame puts its recesses the standard "
		.. "distance in all the same (" ..
		tostring(_G.TradePlayerItemsInset:GetLeft() - trGlass:GetLeft())
		.. " vs " .. tostring(trInner) .. ")")

	-- THE RECESSES ARE THE WELLS, so there is no seventh one round the lot.
	check(not (_G.TradeFrame.__aetherBody
		and _G.TradeFrame.__aetherBody:IsShown()),
		"no body recess round content that is already in six of them")
	local dry = {}
	for _, side in ipairs({ "TradePlayer", "TradeRecipient" }) do
		for _, part in ipairs({ "ItemsInset", "EnchantInset" }) do
			local ins = _G[side .. part]
			local stone = select(1, ins:GetRegions())
			if stone and stone:GetTexture() ~= 0 then
				dry[#dry + 1] = side .. part .. ":stone"
			end
			if not ins.__aetherPill then dry[#dry + 1] = side .. part end
		end
	end
	check(#dry == 0, "and each of the four wears one of ours instead (" ..
		(#dry > 0 and table.concat(dry, ",") or "all four") .. ")")

	-- A ROW IS A FRAME, NOT A BUTTON, and its plate and its parchment strip
	-- are BACKGROUND regions of that frame - so a sweep of the WINDOW reaches
	-- neither and fourteen stone-and-paper strips sit in the recess.
	local plated = {}
	for _, side in ipairs({ "TradePlayer", "TradeRecipient" }) do
		for i = 1, 7 do
			local n = side .. "Item" .. i
			for _, part in ipairs({ "SlotTexture", "NameFrame" }) do
				local t = _G[n .. part]
				if t and t:GetTexture() ~= 0 then plated[#plated + 1] = n .. part end
			end
			if not _G[n .. "ItemButton"].__aetherSlot then
				plated[#plated + 1] = n .. ":cell"
			end
		end
	end
	check(#plated == 0, "every row has lost its plate and its parchment, and "
		.. "its picture is in a cell (" ..
		(#plated > 0 and table.concat(plated, ",") or "all fourteen") .. ")")

	-- AND THE ITEM'S NAME SURVIVES BOTH. It is a FontString in the same
	-- background layer as the parchment it was printed on, so a sweep that
	-- takes the paper without sparing the words leaves the row empty.
	check(_G.TradePlayerItem1Name:GetText() == "Item Name",
		"the item's name survives the sweep that takes the paper under it")
	local red, green, blue = _G.TradePlayerItem1Name:GetTextColor()
	check(red == A.Palette.c.text[1] and green == A.Palette.c.text[2]
		and blue == A.Palette.c.text[3],
		"and is lifted out of the near-black paper wanted (" ..
		tostring(red) .. "," .. tostring(green) .. "," .. tostring(blue) .. ")")

	-- YOUR PURSE IS OUT OF REACH, AND THAT IS THE CLIENT'S DOING.
	--
	-- TradeFrame_OnLoad calls SetForbidden on TradePlayerInputMoneyFrame - a
	-- real call on an ordinary window, not something reserved for the shop -
	-- so every method on it and on its three fields throws from insecure code.
	-- Send Mail's answer to the identical template cannot be applied here at
	-- any price, and the honest thing to check is that we do not try.
	check(_G.TradePlayerInputMoneyFrame:IsForbidden(),
		"the client has put your own purse out of reach")
	check(A:GetModule("panels").Part("TradePlayerInputMoneyFrame") == nil,
		"and nothing in this file will hand it to something that measures or"
		.. " moves it")
	check(_G.TradePlayerInputMoneyFrameGoldLeft:IsShown(),
		"so its field art is left exactly as the client drew it, rather than"
		.. " half-taken")

	-- WHAT CAN BE DONE IS THE RECESS ROUND IT, which is a frame of the window
	-- like any other. Your purse sits in one of ours with the client's own
	-- fields inside it and theirs sits in one with our figure in it, so the
	-- pair still reads as a pair.
	check(_G.TradePlayerInputMoneyInset.__aetherPill
		and _G.TradeRecipientMoneyBg.__aetherPill,
		"but both purses are in a recess of ours all the same")

	-- AND THEIRS IS WRAPPED TWICE by the client - the recess and a thin gold
	-- edge inside it. One comes off and one well goes back on the inner of
	-- them, which is the one sized to the number.
	check(select(1, _G.TradeRecipientMoneyInset:GetRegions()):GetTexture() == 0
		and _G.TradeRecipientMoneyBg.__aetherPill,
		"and theirs is unwrapped once and welled once, not both or neither")

	-- WHICH SIDE IS LIVE, marked the way every other row in this interface is.
	--
	-- AND BEHIND THE GOODS. The wash fills the frame and the frame covers the
	-- whole column, so at the level the client gave it the mark would be drawn
	-- over the seven items it is pointing at.
	check(_G.TradeHighlightPlayer.__aetherRowMark
		and _G.TradeHighlightPlayerTop:GetTexture() == 0,
		"the live column wears a wash of ours rather than the client's rope")
	-- AGAINST THE ROW, which is the highlight's SIBLING - both are children of
	-- the window and both take its level plus one, so that is a comparison the
	-- dresser has to win. Against the item BUTTON it could not be lost: the
	-- button is a child of the row and a level above it either way, so the
	-- check passed with the line that earns it deleted.
	check(_G.TradeHighlightPlayer:GetFrameLevel()
		< _G.TradePlayerItem1:GetFrameLevel(),
		"under what it is pointing at, not over it (" ..
		_G.TradeHighlightPlayer:GetFrameLevel() .. " vs " ..
		_G.TradePlayerItem1:GetFrameLevel() .. ")")

	-- AND THE READOUT IS NOT A ROW OF PRESSABLE BUTTONS. A MoneyFrame prints
	-- gold, silver and copper on three Buttons WITH LABELS ON THEM, which is
	-- exactly what the sweep at the foot of the dresser looks for.
	check(not _G.TradeRecipientMoneyFrameGoldButton.__aetherSkin,
		"the other side's coin readout is not given three pressable surfaces")
	check(_G.TradeFrameTradeButton.__aetherSkin
		and _G.TradeFrameCancelButton.__aetherSkin,
		"while Trade and Cancel, which are buttons, get one each")
	end

	-- GOSSIP, on the modern template - so the shell is the shared one and what
	-- is left is the parchment behind the words.
	local panel = _G.GossipFrame.GreetingPanel
	check(select(1, panel:GetRegions()):GetTexture() == 0,
		"the gossip window's parchment comes off")

	-- ITS LIST GOES IN THE RECESS. The client hangs the scroll box off the
	-- WINDOW at 8 in and 65 down - the strip its stone title plate used to
	-- need - so what you can say started inside our header band.
	--
	-- REACHED BY PATH. This one has no global name at all: it is
	-- GossipFrame.GreetingPanel.ScrollBox, and a panel entry that could only
	-- name globals could not reach a single part of a modern window.
	_G.GossipFrame:Show()
	local gInner = A.Widgets.PANEL_PAD + A.Widgets.WELL_PAD
	local gBox = panel.ScrollBox
	local _, _, _, gx, gy = gBox:GetPoint(1)
	check(gx == 8 + (gInner - 8)
		and gy == -(65 + (A.Widgets.PANEL_HEAD_H + gInner - 65)),
		"what you can say clears the band and sits in the well's padding (" ..
		tostring(gx) .. ", " .. tostring(gy) .. ")")

	-- AND GOODBYE IS IN THE STRIP. It sat in the window's bottom right corner,
	-- four up from the glass and under the recess.
	local byp, byrel, byrelP, byx, byy = panel.GoodbyeButton:GetPoint(1)
	check(byp == "LEFT" and byrel == _G.GossipFrame.__aetherPanel
		and byrelP == "BOTTOM"
		and byx == -panel.GoodbyeButton:GetWidth() / 2
		and byy == A.Widgets.PANEL_FOOT_H / 2,
		"goodbye is centred in the footer strip (" .. tostring(byx) .. ", " ..
		tostring(byy) .. ")")

	-- AND THE TOOL ROW COSTS NOTHING WHEN IT IS EMPTY. Only a handful of the
	-- people you talk to keep track of how well they know you, so declaring
	-- the row wore a forty-two unit band of nothing on every other NPC in the
	-- game.
	check(_G.GossipFrame.FriendshipStatusBar
		and not _G.GossipFrame.FriendshipStatusBar:IsShown(),
		"the reputation bar is down on an ordinary NPC")
	local gTop = A.Widgets.PANEL_HEAD_H + gInner
	check(-gy == gTop,
		"so the list starts at the body's own top rather than below a row"
		.. " nothing is in (" .. tostring(-gy) .. " against " .. tostring(gTop)
		.. ")")

	-- A WINDOW HAS NO RECT WHEN IT TELLS YOU IT HAS OPENED. ShowUIPanel clears
	-- a panel's anchors and places it AFTER its OnShow has run, so everything
	-- this module measures is being asked of a frame that is not anywhere yet
	-- and comes back nil. The window then sits there laid out for the answer it
	-- got at login, which is the same nil - which is what the gossip window
	-- looked like: its list on the well's rim and its Goodbye in the corner.
	do
		local box = panel.ScrollBox
		local bye = panel.GoodbyeButton
		box.__aetherTop, box.__aetherLeft, box.__aetherRight = nil, nil, nil
		box.__aetherPts = nil
		box:ClearAllPoints()
		box:SetPoint("TOPLEFT", _G.GossipFrame, "TOPLEFT", 8, -65)
		bye:ClearAllPoints()
		bye:SetPoint("BOTTOMRIGHT", _G.GossipFrame, "BOTTOMRIGHT", -6, 4)
		_G.GossipFrame:Hide()
		_G.GossipFrame.__unplaced = true
		_G.GossipFrame:Show()
		check(box.__aetherTop == nil,
			"a window that has just opened measures as nothing, because the"
			.. " client has not placed it yet (" .. tostring(box.__aetherTop) .. ")")

		-- ...and the client finishes putting it up.
		_G.GossipFrame.__unplaced = nil
		_G.__drainTimers(1)
		check(box.__aetherTop == 65,
			"and is measured again on the next frame, when there is something to"
			.. " measure (" .. tostring(box.__aetherTop) .. ")")
		check(select(3, bye:GetPoint(1)) == "BOTTOM",
			"which is also when its Goodbye finally reaches the strip - the button"
			.. " was visible but the window was not anywhere (" ..
			tostring(select(3, bye:GetPoint(1))) .. ")")
	end

	-- ALREADY UP WHEN THE ADDON LOADED, and never shown again. This is the case
	-- that had the gossip window laid out for nothing all session: reload while
	-- you are talking to somebody and the client puts the window straight back,
	-- so no OnShow ever fires afterwards - and the one layout it did get ran
	-- against a frame the panel system had not placed yet.
	do
		local box = panel.ScrollBox
		local PN2 = A:GetModule("panels")
		box.__aetherTop, box.__aetherLeft, box.__aetherRight = nil, nil, nil
		box.__aetherPts = nil
		box:ClearAllPoints()
		box:SetPoint("TOPLEFT", _G.GossipFrame, "TOPLEFT", 8, -65)
		_G.GossipFrame:Show()
		_G.GossipFrame.__aetherTries = nil
		_G.GossipFrame.__unplaced = true
		PN2.Dress(_G.GossipFrame)
		check(box.__aetherTop == nil,
			"a window dressed while the panel system has not placed it measures"
			.. " as nothing (" .. tostring(box.__aetherTop) .. ")")
		-- ON OUR OWN LAYER, NOT ON A HOOK OF THE CLIENT'S. Three hooks were tried
		-- before this and not one of them fired on the gossip window: OnShow does
		-- not come round again for a window that was already up when the addon
		-- loaded, and not every window goes up through the panel system's front
		-- door. The chrome layer is a CHILD of the window, so the client ticks it
		-- exactly when there is a window on screen to measure.
		local watch = _G.GossipFrame.__aetherChrome
		local fn = watch:GetScript("OnUpdate")
		check(fn ~= nil,
			"the layer asks to be ticked while the window has nothing to measure")

		_G.GossipFrame.__unplaced = nil
		if fn then fn(watch, 0) end
		check(box.__aetherTop == 65,
			"and measures on the next tick, without waiting for a show that is"
			.. " never coming (" .. tostring(box.__aetherTop) .. ")")
		check(watch:GetScript("OnUpdate") == nil,
			"then stops asking, so a window that is laid out costs nothing a frame")
	end

	-- OVER THE CLIENT'S OWN FURNITURE. Twenty levels above the window was picked
	-- off the old hand-built panels, whose panes sit a level or two up. A modern
	-- one is nothing like that - the gossip window carries children at 400, 500
	-- and 510 - so the chrome layer was UNDER the client's own frames and the
	-- band's hairline was drawn behind the window it belongs to.
	do
		local tall = CreateFrame("Frame", nil, _G.GossipFrame)
		tall:SetFrameLevel(510)

		-- AND A FORBIDDEN ONE AMONG THEM. A protected frame answers nothing at
		-- all - asking it for its own level throws "calling '?' on bad self" -
		-- and one of these windows really does have one. Unguarded it took the
		-- whole panels module down at login: every window in the interface came
		-- up in Blizzard's own art with no sign of why.
		local banned = CreateFrame("Frame", nil, _G.GossipFrame)
		function banned:GetFrameLevel()
			error("calling '?' on bad self")
		end
		local ok = pcall(A:GetModule("panels").Dress, _G.GossipFrame)
		check(ok,
			"a forbidden child does not take the window down with it - unguarded"
			.. " this threw at login and every panel in the interface came up in"
			.. " Blizzard's own art with no sign of why")
		check(ok and _G.GossipFrame.__aetherChrome:GetFrameLevel() > 510,
			"the chrome layer clears the highest thing the client put in the window"
			.. " (" .. tostring(_G.GossipFrame.__aetherChrome:GetFrameLevel()) ..
			" against 510)")

		-- AND IT DOES NOT CLIMB. The chrome layer is a child of the window too, so
		-- a scan that counted it would push itself one lift higher on every dress
		-- until the window ran out of levels.
		local was = _G.GossipFrame.__aetherChrome:GetFrameLevel()
		A:GetModule("panels").Dress(_G.GossipFrame)
		check(_G.GossipFrame.__aetherChrome:GetFrameLevel() == was,
			"and stays where it is when the window is dressed again (" ..
			tostring(_G.GossipFrame.__aetherChrome:GetFrameLevel()) .. " against "
			.. tostring(was) .. ")")
		tall:Hide()
		tall:SetFrameLevel(1)
		banned:Hide()
		banned.GetFrameLevel = nil
	end

	-- AND THROUGH THE PANEL SYSTEM'S OWN DOOR, which is the moment that
	-- actually matters: ShowUIPanel shows the window and THEN places it, so
	-- hooking it catches the window once there is something to measure - with
	-- no timer in it at all.
	do
		local box = panel.ScrollBox
		box.__aetherTop, box.__aetherLeft, box.__aetherRight = nil, nil, nil
		box.__aetherPts = nil
		box:ClearAllPoints()
		box:SetPoint("TOPLEFT", _G.GossipFrame, "TOPLEFT", 8, -65)
		_G.GossipFrame:Hide()
		ShowUIPanel(_G.GossipFrame)
		check(box.__aetherTop == 65,
			"a window put up by the panel system is laid out for where it ended"
			.. " up, without waiting a frame for it (" ..
			tostring(box.__aetherTop) .. ")")
	end

	-- AND COSTS THE ROW WHEN THERE IS SOMETHING IN IT. Same window, same
	-- entry: what changes is whether the client has anything to put up there.
	_G.GossipFrame.FriendshipStatusBar:Show()
	A:GetModule("panels").Dress(_G.GossipFrame)
	local gy2 = select(5, gBox:GetPoint(1))
	check(-gy2 == gTop + 28 + A.Widgets.PANEL_GAP,
		"an NPC who keeps track of you gets the row, and the list moves down by"
		.. " it (" .. tostring(-gy2) .. ")")
	local fp, frel2, frelP2, fx2, fy2 =
		_G.GossipFrame.FriendshipStatusBar:GetPoint(1)
	check(fp == "LEFT" and frel2 == _G.GossipFrame.__aetherChrome
		and frelP2 == "TOPLEFT" and fx2 == A.Widgets.PANEL_PAD
		and fy2 == -(A.Widgets.PANEL_HEAD_H + A.Widgets.PANEL_PAD + 28 / 2),
		"and the bar itself starts that row (" .. tostring(fx2) .. ", " ..
		tostring(fy2) .. ")")
	_G.GossipFrame.FriendshipStatusBar:Hide()
	A:GetModule("panels").Dress(_G.GossipFrame)
	check(panel.GoodbyeButton.__aetherSkin ~= nil, "its goodbye is one of ours")
	check(select(1, panel.ScrollBar.Track:GetRegions()):GetTexture() == 0
		and panel.ScrollBar.Back:GetNormalTexture():GetTexture() == 0,
		"and its scroll bar is taken apart, being a frame of frames like the"
		.. " community list's rather than a slider with regions on it")

	-- INK CHOSEN FOR PARCHMENT. A quest's text and a gossip option are near
	-- black because that is what reads on paper; on glass they are a smudge.
	-- The rule everywhere else - the client's colours are meant, leave them -
	-- is right for a window whose background we did not change and wrong here.
	local ink = A.Palette.c.text
	local qr, qg, qb = _G.QuestFrameDetailPanelInk:GetTextColor()
	check(qr == ink[1] and qg == ink[2] and qb == ink[3],
		"the quest's text is lifted off the paper it was printed for ("
		.. string.format("%.2f", qr) .. ")")

	-- AND ONLY THE DARK. The test is the colour rather than the window, so a
	-- heading that was gold because gold means something stays gold.
	local gr, gg = _G.QuestFrameDetailPanelGold:GetTextColor()
	check(gr == 1 and gg == 0.82,
		"while a gold heading is left exactly as the client set it ("
		.. string.format("%.2f,%.2f", gr, gg) .. ")")

	-- THE GREETING PAGE, WHICH THE CLIENT REDRAWS UNDER US. An NPC with more
	-- than one quest lists them under Current Quests and Available Quests, and
	-- QuestFrame re-runs QuestFrameGreetingPanel_OnShow on QUEST_LOG_UPDATE
	-- while that page is up - which is exactly what accepting one of them
	-- does. The redraw repaints the parchment, re-inks the greeting and both
	-- headings, re-embeds |cff000000 in every title and shows the gold swirl
	-- again, so the window came back looking as though its interior had never
	-- been dressed at all.
	local function greetingLifted()
		local bad = {}
		for _, n in ipairs({ "GreetingText", "CurrentQuestsText",
			"AvailableQuestsText" }) do
			local r = select(1, _G[n]:GetTextColor())
			if math.abs(r - ink[1]) > 0.01 then
				bad[#bad + 1] = n .. "=" .. string.format("%.2f", r)
			end
		end
		-- AND THE BLACK THAT IS INSIDE THE STRING. Every title is formatted
		-- through NORMAL_QUEST_DISPLAY, so GetTextColor answers the font
		-- object and never sees the escape that is actually being drawn.
		for i = 1, 3 do
			local t = _G["QuestTitleButton" .. i]:GetFontString():GetText() or ""
			if t:find("|cff000000", 1, true) then
				bad[#bad + 1] = "title" .. i .. " still black inside"
			end
		end
		return bad
	end

	local bad = greetingLifted()
	check(#bad == 0, "the greeting page is lifted (" ..
		(#bad > 0 and table.concat(bad, ", ") or "all of it") .. ")")
	check(not _G.QuestGreetingFrameHorizontalBreak:IsShown(),
		"and the gold swirl between the two sections is gone")
	check(_G.QuestTitleButton1QuestIcon:IsShown(),
		"with the quest icons kept - they are the only thing saying which of"
		.. " these you already have")

	-- NOW THE CLIENT REDRAWS IT, which is what accepting one of the quests
	-- does. Everything above has to survive it.
	_G.QuestFrameGreetingPanel_OnShow()
	bad = greetingLifted()
	check(#bad == 0, "and stays lifted when the client redraws the page (" ..
		(#bad > 0 and table.concat(bad, ", ") or "all of it") .. ")")
	check(not _G.QuestGreetingFrameHorizontalBreak:IsShown(),
		"with the swirl staying gone, not coming back with it")
	check(_G.QuestTitleButton1QuestIcon:IsShown(),
		"and the icons still there afterwards")

	-- THE GOSSIP ROWS ARE POOLED, and re-acquired every time the list is
	-- rebuilt - which is on open and on every option you pick. Dressed once,
	-- they are right until you click something.
	local row = panel.ScrollBox:GetFrames()[1]
	local rr = row:GetFontString():GetTextColor()
	check(rr == ink[1], "a gossip option is lifted too")

	-- AND AFTER THE LAYOUT THAT FOLLOWS IT, not the instant Update returns.
	-- GossipFrameSharedMixin:Update hands the box a new data provider and
	-- returns; the box acquires and fills its rows during its OWN Update, at
	-- layout. Asserting the ink immediately after the window's Update asserted
	-- something the client does not do either - and passed only because the
	-- mock used to re-lift synchronously.
	_G.GossipFrame:Update()
	tick(0)
	rr = row:GetFontString():GetTextColor()
	check(rr == ink[1],
		"and stays lifted after the list is rebuilt, which is what picking an"
		.. " option does (" .. string.format("%.2f", rr) .. ")")
	check(row.Icon:GetTexture() == "Interface\\QuestFrame\\UI-Quest-BulletPoint",
		"with its bullet still on it")

	-- AND A ROW THE BOX MINTS DURING LAYOUT, which is after Update has
	-- returned. That is the case that broke the gossip window: a scroll box
	-- acquires its frames while it lays out, so asking GetFrames from inside
	-- an Update hook is answered with the set that was there BEFORE - and
	-- the greeting and every option came up in the near-black the client
	-- prints gossip in.
	--
	-- It also explains why it looked intermittent rather than broken:
	-- whether a row had been lifted depended on whether the pool happened
	-- to hand back one that had. Hooking the BOX's Update instead of the
	-- window's removes the guess: it runs after the box's own layout, which
	-- is the moment the rows exist. ElvUI's gossip skin hooks exactly that.
	local late = panel.ScrollBox.__late
	check(late ~= nil, "the box mints a row while it lays out")
	local lr = late and late:GetFontString():GetTextColor()
	check(lr == ink[1],
		"and a row minted then is lifted too (" ..
		string.format("%.2f", lr or 0) .. ")")

	-- THROUGH THE BOX'S OWN REBUILD TOO, which is a different entry point:
	-- Update rebuilds the data and UpdateScrollBox rebuilds the box, and
	-- the client calls both. Hooking only the one leaves the other's rows
	-- in the client's ink.
	panel.ScrollBox.__late = nil
	_G.GossipFrame:UpdateScrollBox()
	tick(0)
	local boxLate = panel.ScrollBox.__late
	local br = boxLate and boxLate:GetFontString():GetTextColor()
	check(br == ink[1],
		"and so is one minted by the box's own rebuild (" ..
		string.format("%.2f", br or 0) .. ")")

	-- AND SO IS A QUEST TITLE, which keeps its string in a region of its own
	-- rather than answering GetFontString. Naming the string per shape found
	-- nothing on this row, so it kept our lettering from the first pass and got
	-- the client's ink back on every rebuild.
	local quest = panel.ScrollBox.__quest
	check(quest.__fs._aetherStyle ~= nil, "a quest title is in our lettering")

	-- AND ITS INK IS INSIDE THE STRING. The title comes through
	-- NORMAL_QUEST_DISPLAY as |cff000000<name>|r, so the font string reports
	-- white while drawing black. Lifting the font string's colour changed
	-- nothing you could see.
	local qtext = quest.__fs:GetText()
	check(not qtext:find("|cff000000", 1, true),
		"with the black baked into it rewritten (" .. tostring(qtext) .. ")")
	check(qtext:find("Verog the Dervish", 1, true) ~= nil,
		"and the title itself still in there")
	check(quest.Icon:GetTexture() == "Interface\\GossipFrame\\AvailableQuestIcon",
		"with the quest mark still on it")

	-- ONE TITLE SIZE, ON EVERY WINDOW. This used to differ on purpose: a
	-- window on the modern template kept the CLIENT's size, because its title
	-- band is twenty pixels tall and our own role at nineteen filled it corner
	-- to corner. At 16 it fits the band and the old windows both, and a title
	-- that is one size on the gossip window and another on the spellbook is
	-- exactly what the panel package exists to stop.
	local _, gossipSize = _G.GossipFrameTitleText:GetFont()
	local _, charSize = _G.CharacterFrame.__aetherTitle:GetFont()
	check(gossipSize == charSize and gossipSize == 16,
		"the gossip window and the character sheet wear the same title size (" ..
		tostring(gossipSize) .. " / " .. tostring(charSize) .. ")")
end

print("== panels: the trainer, whose rows are two things at once ==")
do
	_G.__loadPanelAddon("ClassTrainerFrame")
	fire("ADDON_LOADED", "Blizzard_TrainerUI")

	local tf = _G.ClassTrainerFrame
	check(tf.__aetherPanel ~= nil, "the trainer is in glass")

	-- UP, because the strip is laid out for what is VISIBLE on the window and
	-- a window nobody has opened has nothing visible on it.
	tf:Show()
	local tGlass = tf.__aetherPanel
	local tPad = A.Widgets.PANEL_PAD

	-- ITS ROWS GO IN ITS LIST, and they were not in it: this is a FAUX scroll
	-- frame - the scroll frame is the bar and nothing else - so the client
	-- hangs eleven row buttons off the WINDOW and scrolls them by refilling.
	-- The list moved into the recess and left every skill behind, printed on
	-- the glass above an empty box.
	local rp, rrel, rrelP, rx, ry = _G.ClassTrainerSkill1:GetPoint(1)
	check(rp == "TOPLEFT" and rrel == _G.ClassTrainerListScrollFrame
		and rrelP == "TOPLEFT" and rx == 1 and ry == -4,
		"the first skill hangs off the LIST now, exactly where the client had"
		.. " it relative to it (" .. tostring(rx) .. ", " .. tostring(ry) .. ")")

	-- MEASURED ONCE. The offset is taken off where the CLIENT had the two of
	-- them, so a second pass would be measuring our own work.
	A:GetModule("panels").Dress(tf)
	local rx2, ry2 = select(4, _G.ClassTrainerSkill1:GetPoint(1))
	check(rx2 == 1 and ry2 == -4,
		"and dressing the window again does not measure it a second time (" ..
		tostring(rx2) .. ", " .. tostring(ry2) .. ")")

	-- AND THE LIST IS INSET BY WHAT ITS OWN RIM COSTS, not by the well
	-- padding: the recess round a client scroll frame is drawn WELL_OUTSET
	-- outside it, so a list moved in by the full padding puts its RIM that far
	-- inside the body - a wider margin than every other window in the deck.
	-- MEASURED WHERE IT ENDS UP, not by the offset written on it. This list is
	-- pinned to the window's RIGHT corner, so it is carried right by the window
	-- growing rather than by an offset of ours - and adding one as well pushed
	-- anything already flush to that corner out through the glass.
	local tInner = tPad + A.Widgets.WELL_OUTSET
	local listLeft = _G.ClassTrainerListScrollFrame:GetLeft()
	local glassLeft = tGlass:GetLeft()
	check(listLeft and glassLeft and listLeft - glassLeft >= tInner - 0.5,
		"the list clears the body padding by its rim rather than by its own"
		.. " edge (" .. string.format("%.0f", (listLeft or 0) - (glassLeft or 0))
		.. " against " .. tInner .. ")")

	-- YOUR PURSE IS IN THE STRIP. The client hangs it off the window's BOTTOM
	-- LEFT corner, 86 up - which in a window this shape is inside the recess,
	-- and it sat two thirds of the way down the list with skills over it.
	local mp, mrel2, mrelP, mx2, my2 = _G.ClassTrainerMoneyFrame:GetPoint(1)
	check(mp == "LEFT" and mrel2 == tGlass and mrelP == "BOTTOMLEFT"
		and mx2 == tPad
		and my2 == A.Widgets.PANEL_FOOT_H / 2,
		"the purse is pinned to the left of the footer strip (" ..
		tostring(mp) .. " -> " .. tostring(mrelP) .. " at " .. tostring(mx2)
		.. ", " .. tostring(my2) .. ")")

	-- TRAIN ALL, TRAIN AND CLOSE, centred in it. The client puts all three at
	-- a fixed 420 down from the window's TOPLEFT, in a frame that is no longer
	-- that tall, so they lay across the foot of both recesses.
	--
	-- AND IN THE ORDER THE CLIENT HAD THEM. Train All has no name to declare -
	-- it is an anonymous child whose label is ClassTrainerFrameText - so the
	-- three are found by shape, and where they were is the only thing left
	-- saying which the player reads first.
	local tGap = 12
	local three = 80 * 3 + tGap * 2
	local ax2, ay2 = select(4, tf.__trainAll:GetPoint(1))
	check(ax2 == -three / 2
		and ay2 == A.Widgets.PANEL_FOOT_H / 2,
		"Train All is leftmost of the three, centred as one group (" ..
		tostring(ax2) .. ", " .. tostring(ay2) .. ")")
	check(select(4, _G.ClassTrainerTrainButton:GetPoint(1)) == -three / 2 + 92
		and select(4, _G.ClassTrainerCancelButton:GetPoint(1))
			== -three / 2 + 184,
		"with Train and then Close a footer gap along from it (" ..
		tostring(select(4, _G.ClassTrainerTrainButton:GetPoint(1))) .. ", "
		.. tostring(select(4, _G.ClassTrainerCancelButton:GetPoint(1))) .. ")")

	-- THE SAME ELEVEN BUTTONS ARE BOTH KINDS. The client fills them from one
	-- list: a heading gets a plus or a minus as its normal texture, a spell
	-- gets ClearNormalTexture. So which a row is has to be read on every
	-- refresh, from the mark itself, BEFORE ours replaces it.
	local head, spell = _G.ClassTrainerSkill1, _G.ClassTrainerSkill2
	check(head.__aetherGlyph ~= nil and head.__aetherGlyph:IsShown(),
		"a heading gets our own disclosure mark")
	check(head:GetNormalTexture():GetTexture() == 0,
		"with the client's stone plus or minus cleared")
	check(spell.__aetherGlyph == nil or not spell.__aetherGlyph:IsShown(),
		"and a SPELL gets none - it is the same button, and a mark on it would"
		.. " say the row folds when it does not")

	check(head:GetFontString()._aetherStyle ~= nil, "the row is in our lettering")
	local hr = head:GetFontString():GetTextColor()
	check(hr == A.Palette.c.text[1],
		"lifted off the parchment it was printed for")

	check(_G.ClassTrainerSkillIcon.__aetherSlot == true,
		"the spell you are being sold sits in a cell - this one IS square,"
		.. " unlike the quest giver's wide rows")
	check(_G.ClassTrainerTrainButton.__aetherSkin ~= nil, "and Train is ours")

	-- TRAIN ALL IS ANONYMOUS. It carries no name at all - only its label is
	-- named, as ClassTrainerFrameText - so the three push buttons are found by
	-- their three-slice shape rather than by a list of names that cannot
	-- include this one.
	check(tf.__trainAll.__aetherSkin ~= nil,
		"and so is Train All, which has no name to be listed under")
	check(tf.__trainAll.Left:GetTexture() == 0,
		"with its three slices of client stone taken off")
	check(tf.__trainAll.__fs._aetherStyle ~= nil, "and its label in our lettering")

	-- THE FILTER. Its holder comes off, its arrow stays because nothing of ours
	-- says "this opens" better at 24 pixels - but tinted, since the client's is
	-- gold stone and gold on our glass reads as a colour that means something.
	local filter = tf.FilterDropdown
	check(filter.__aetherSkin ~= nil, "the filter is in one of our pills")
	check(filter.Background:GetTexture() == 0, "with its stone holder taken off")
	local ar = filter.Arrow:GetVertexColor()
	check(ar == A.Palette.c.textDim[1],
		"and its arrow inked like the rest of our marks ("
		.. string.format("%.2f", ar) .. ")")

	-- AND PULLED INSIDE THE GLASS. 44 in from the frame's right edge sat inside
	-- the parchment's margin and outside ours, which stops 28 short.
	local point, _, _, x = filter:GetPoint()
	check(point == "TOPRIGHT" and x > -44,
		"and moved in off the frame's edge, where the glass stops (" .. tostring(x) .. ")")

	-- THE ARROW IS REPLACED, NOT TINTED. The client's is a blue-grey stone
	-- BUTTON, and a vertex colour multiplies that rather than replacing it - so
	-- tinting it left a blue stone button sitting in one of our pills.
	check(filter.Arrow:GetTexture() == A.Media.texture.chevron,
		"its arrow is our own chevron, which points down unrotated")
	check(filter.Arrow:GetWidth() == 10,
		"at a mark's size rather than the client's 24px control")

	-- AND THE LIST IT OPENS IS LEFT ALONE, which is the opposite of what this
	-- used to assert.
	--
	-- THERE IS ONE MENU IN THE WHOLE INTERFACE. The menu system keeps a POOL and
	-- hands the same frame to every dropdown, every right-click on a unit, every
	-- context menu in the game. Stripping it and glassing it is not dressing a
	-- window - it is editing a frame something else will be handed a moment
	-- later, and what we did to it stayed done: it came back as an empty black
	-- box, first on this window's filters and then on every context menu in the
	-- game, with no error anywhere because as far as Lua was concerned nothing
	-- had gone wrong.
	--
	-- A pooled frame is not ours to keep unless we put it back on release, and
	-- that is a mechanism rather than a paint job.
	filter:OpenMenu()
	local menu = filter.menu
	check(menu ~= nil and menu.__aetherPanel == nil,
		"the menu a dropdown opens is left in the client's own art - it is a"
		.. " POOLED frame shared with every context menu in the game")
	check(menu.__bg:GetTexture() ~= 0 and menu.__fill:GetTexture() ~= 0,
		"with its plate and its fill still on it, so the menu handed out next"
		.. " still has something to draw")
	check(menu.__firstRow._aetherStyle == nil,
		"and its rows in the client's lettering, for the same reason")

	-- AND THE ARROW SURVIVES BEING CLICKED. The client re-atlases it and
	-- re-colours the text on every state change.
	filter:OnButtonStateChanged()
	check(filter.Arrow:GetTexture() == A.Media.texture.chevron
		and filter.Arrow:GetWidth() == 10,
		"the chevron goes back after the client redraws the control")
	check(filter.Text:GetTextColor() == A.Palette.c.text[1],
		"and so does our ink on its label")
	-- WHICH ROW YOU ARE ON, in our ink rather than Blizzard's blue. One frame,
	-- slid onto whatever you picked - and it was in the list of panes to STRIP,
	-- which left the window with nothing at all saying which skill was
	-- selected. Stripped and washed is the answer, not stripped.
	do
		local hl = _G.ClassTrainerSkillHighlightFrame
		check(_G.ClassTrainerSkillHighlight:GetTexture() == 0,
			"the client's listbox slice comes off the selection bar")
		check(hl.__aetherRowMark ~= nil and hl.__aetherRowMark:GetTexture()
			== A.Media.texture.flat,
			"and our own wash goes on in its place")
		local mr, mg, mb, ma = hl.__aetherRowMark:GetVertexColor()
		local ac = A.Palette.c.accent
		check(mr == ac[1] and mg == ac[2] and mb == ac[3] and ma < 0.3,
			"in the skin's accent, at an alpha that does not fight the words"
			.. " printed on it (" .. string.format("%.2f", ma or 0) .. ")")
	end

	-- AND A ROW THAT IS NOT A HEADING KEEPS NONE OF THE TEMPLATE'S PLUS ART.
	-- The client clears the NORMAL texture on a spell row and leaves the other
	-- three, so hovering one lit it up with Blizzard's plus button.
	do
		local spell2 = _G.ClassTrainerSkill2
		local hi = spell2.GetHighlightTexture and spell2:GetHighlightTexture()
		local dis = spell2.GetDisabledTexture and spell2:GetDisabledTexture()
		check((not hi or hi:GetTexture() == 0)
			and (not dis or dis:GetTexture() == 0),
			"a spell row keeps no plus button on any state (" ..
			tostring(hi and hi:GetTexture()) .. ", " ..
			tostring(dis and dis:GetTexture()) .. ")")
	end
	check(_G.ClassTrainerExpandTabLeft:GetTexture() == 0,
		"the little stone tab the All control hangs off is cleared")

	-- AND THE ROWS SWAP KINDS. Expand a heading and the client refills all
	-- eleven from a longer list, so row one may be a spell next time and row
	-- two a heading. A mark decided once is a mark on the wrong row.
	_G.ClassTrainerFrame_Update()
	check(head.__aetherGlyph:IsShown() and head.__aetherGlyph:GetText() == "+",
		"a heading that collapsed shows a plus rather than the minus it had")
	check(spell.__aetherGlyph == nil or not spell.__aetherGlyph:IsShown(),
		"and the spell row still carries no mark after the refresh")

	-- EVERY ROW, NOT THE FIRST ELEVEN. CLASS_TRAINER_SKILLS_DISPLAYED is 11 in
	-- Blizzard's source and this client draws more, so a loop bounded by the
	-- number in the source left the rest of a mage's spell list in Friz.
	local last = _G["ClassTrainerSkill26"]
	check(last ~= nil and last:GetFontString()._aetherStyle ~= nil,
		"a row past the eleventh is in our lettering too")
	check(last:GetFontString():GetTextColor() == A.Palette.c.text[1],
		"and lifted off the parchment with the rest")

	-- The mark is read from the client's own service data. Its texture answers
	-- with a file ID here, as the client's does, so anything reading the path
	-- gets a number and decides every row is a spell.
	check(_G.ClassTrainerSkill25.__aetherGlyph ~= nil
		and _G.ClassTrainerSkill25.__aetherGlyph:IsShown(),
		"a heading below the eleventh gets its mark from the service, not the art")

	-- "All" carries a flag rather than a service index, and reading its texture
	-- instead left a plus on it with the whole tree expanded.
	local all = _G.ClassTrainerCollapseAllButton
	all.collapsed = nil
	A:GetModule("panels").Dress(tf)
	check(all.__aetherGlyph:GetText() == "\226\136\146",
		"All shows a minus while the tree is expanded ("
		.. tostring(all.__aetherGlyph:GetText()) .. ")")
	all.collapsed = 1
	A:GetModule("panels").Dress(tf)
	check(all.__aetherGlyph:GetText() == "+", "and a plus once it is collapsed")
end

print("== panels: the client's own lists sit in a recess too ==")
do
	-- 15b: anything that can grow sits in a well, and the well is the only
	-- scroll container. Our own windows have had this since the quest log was
	-- built; the client's never did - a trainer's skill list and the detail
	-- beside it floated on bare glass with nothing marking where either began
	-- or ended, and so did every trade skill's.
	local bare = {}
	for _, name in ipairs({ "ClassTrainerListScrollFrame",
		"ClassTrainerDetailScrollFrame" }) do
		local sf = _G[name]
		if sf and not sf.__aetherWell then bare[#bare + 1] = name end
	end
	check(#bare == 0,
		"every list the client owns is in one (" ..
		(#bare > 0 and table.concat(bare, ", ") or "all of them") .. ")")

	-- BEHIND the scroll frame, not around it: the rows are children of the
	-- scrolling child and draw over anything at the scroll frame's own level.
	local sf = _G.ClassTrainerListScrollFrame
	check(sf.__aetherWell:GetFrameLevel() < sf:GetFrameLevel(),
		"and drawn behind it rather than over the rows (" ..
		sf.__aetherWell:GetFrameLevel() .. " against " ..
		sf:GetFrameLevel() .. ")")
	local wp, wrel, wrelP, wx = sf.__aetherWell:GetPoint(1)
	check(wp == "TOPLEFT" and wrel == sf and wrelP == "TOPLEFT" and wx < 0,
		"and outset from it, so the rim is not drawn under the first row (" ..
		tostring(wx) .. ")")
end

print("== panels: the flight master, whose map is a region of the frame ==")
do
	local tx = _G.TaxiFrame
	tx:Show()

	check(tx.__aetherPanel ~= nil, "the flight map is in glass")

	-- THE MAP IS THE WINDOW. It is a texture region of the frame, exactly like
	-- the parchment around it, so the sweep that took the art took the map and
	-- left the flight points floating in the dark.
	check(_G.TaxiMap:GetTexture() ~= 0 and _G.TaxiMap:IsShown(),
		"the map itself survives the strip ("
		.. tostring(_G.TaxiMap:GetTexture()) .. ")")
	check(tx.__stone:GetTexture() == 0, "while the frame's own art still comes off")
	check(_G.TaxiPortrait:GetTexture() == 0,
		"and the portrait goes, having lost the ring it sat in")

	-- AND IT MOVES INTO THE RECESS, with the routes drawn over it. The client
	-- hangs both 75 down from the middle of the top edge, which is inside our
	-- band - and moves them TOGETHER, because a shift measured per piece would
	-- part the map from the lines drawn on it.
	do
		local txInner = A.Widgets.PANEL_PAD + A.Widgets.WELL_PAD
		local mapY = select(5, _G.TaxiMap:GetPoint(1))
		local routeY = select(5, _G.TaxiRouteMap:GetPoint(1))
		check(mapY == routeY,
			"the map and the routes over it stay together (" .. tostring(mapY)
			.. ", " .. tostring(routeY) .. ")")
		check(-mapY == 75 + (A.Widgets.PANEL_HEAD_H + txInner - (75 - 8)),
			"and clear the band by the body padding (" .. tostring(-mapY) .. ")")

		-- The flight points come with it: the client anchors every one of them to
		-- the MAP's own bottom left corner rather than to the window.
		local np, nrel = _G.TaxiButton1:GetPoint(1)
		check(np == "CENTER" and nrel == _G.TaxiMap,
			"and every flight point is hung off the map, so it travels with it")
	end

	-- Named TaxiCloseButton, not TaxiFrameCloseButton, which is why this one
	-- window kept the client's red X.
	check(_G.TaxiCloseButton.__aetherClose ~= nil, "its close button is ours")

	local who = _G.TaxiMerchant
	check(who._aetherStyle ~= nil and who:GetTextColor() == A.Palette.c.text[1],
		"and the flight master's name is lifted into our lettering")
end

print("== timers: breath, fatigue, and the colour that says which ==")
do
	local TMm = A:GetModule("timers")
	check(TMm ~= nil and TMm.enabled, "the timers module is on")

	local f = _G.MirrorTimer1
	check(f.__border:GetTexture() == 0 and f.__plate:GetTexture() == 0,
		"a timer's stone border and its black plate come off")
	check(f.__aetherPill ~= nil, "and glass goes behind it")

	-- THE CAPSULE IS THE FRAME. Behind the bar alone it is a sliver two pixels
	-- taller than the fill, which is a rim rather than a capsule.
	local bar = _G.MirrorTimer1StatusBar
	check(f.__aetherPill:GetParent() == f
		and f.__aetherPill:GetWidth() == f:GetWidth(),
		"the capsule covers the frame, the way the cast bar's does ("
		.. tostring(f.__aetherPill:GetWidth()) .. " of " .. tostring(f:GetWidth())
		.. ") - behind the fill alone it is a rim two pixels taller than the bar")

	-- ABOVE THE GLASS. The template lowers this bar's frame level in its own
	-- OnLoad, so a capsule put behind the frame draws over the fill - which is
	-- the bar coming back as a pale block with no capsule anywhere.
	check(bar:GetFrameLevel() > f.__aetherPill:GetFrameLevel(),
		"and the fill sits above it (" .. bar:GetFrameLevel() .. " vs "
		.. f.__aetherPill:GetFrameLevel() .. ") - the template LOWERS this bar,"
		.. " so left alone the glass is drawn over the top of it")

	-- The cast bar's layout: the word on the left, the fill beside it.
	local tPt, tRel, tRelPt = _G.MirrorTimer1Text:GetPoint(1)
	check(tPt == "LEFT" and tRel == f and tRelPt == "LEFT",
		"the word sits at the left of the capsule (" .. tostring(tPt) .. ")")
	check(_G.MirrorTimer1Text._aetherStyle == "castName",
		"in the cast bar's own lettering, because this is the same object")

	local bPt, bRel = bar:GetPoint(1)
	check(bPt == "LEFT" and bRel == _G.MirrorTimer1Text,
		"and the fill starts where the word ends rather than at a fixed offset -"
		.. " 'Feign Death' is half again the width of 'Breath', so the bar gives"
		.. " way rather than the word being clipped")
	check(bar:GetHeight() == 7,
		"at the cast bar's own height (" .. bar:GetHeight() .. ")")

	-- WHICH TIMER IT IS, IN THE COLOUR - and re-applied, because the client
	-- sets its own from MirrorTimerColors every time a timer starts. A colour
	-- set once at login is a colour you see until the first time you dive.
	MirrorTimer_Show("BREATH", 30000, 60000, 1, 0, "Breath")
	local br, bg, bb = bar:GetStatusBarTexture():GetVertexColor()
	-- POWER rather than CAST. Both are blue and the cast blue is the paler, so
	-- over bright water it came back reading as a white bar with a grey end.
	local breath = A.Palette.c.power[1]
	check(br == breath[1] and bg == breath[2] and bb == breath[3],
		"breath is our blue rather than Blizzard's (" ..
		string.format("%.2f,%.2f,%.2f", br, bg, bb) .. ")")

	-- A DIFFERENT TIMER TAKES A DIFFERENT FRAME. The client picks whichever of
	-- the three is free, so all three have to have been dressed - and the
	-- colour has to follow the KIND, not the frame.
	MirrorTimer_Show("EXHAUSTION", 30000, 60000, 1, 0, "Fatigue")
	local bar2 = _G.MirrorTimer2StatusBar
	local er, eg = bar2:GetStatusBarTexture():GetVertexColor()
	local tired = A.Palette.c.energy[1]
	check(er == tired[1] and eg == tired[2],
		"and fatigue is our yellow, on whichever of the three frames was free")

	-- Off hands the client its own back.
	A:SetModuleEnabled("timers", false)
	check(f.__border:GetTexture() == "Interface\\CastingBar\\UI-CastingBar-Border"
		and f.__aetherPill == nil,
		"switching it off returns the border the client drew")
	A:SetModuleEnabled("timers", true)
	check(_G.MirrorTimer1.__aetherPill ~= nil, "and on again re-dresses it")

	for i = 1, 3 do _G["MirrorTimer" .. i]:Hide() end
end

print("== panels: guild and communities, read off the live client ==")
do
	_G.__loadPanelAddon("CommunitiesFrame")
	fire("ADDON_LOADED", "Blizzard_Communities")

	local cf = _G.CommunitiesFrame
	check(cf.__aetherPanel ~= nil, "the guild window is in glass")

	-- THE SIDE TABS keep their picture in an Icon REGION rather than as the
	-- normal texture the spellbook's school tabs use. Assuming the spellbook's
	-- shape here would dress four empty cells and throw the icons away, and it
	-- is the kind of wrong that looks deliberate.
	local roster = cf.RosterTab
	check(roster.__aetherSlot == true, "a side tab wears one of our cells")
	check(roster.Icon:GetTexture() == "communities-icon-RosterTab",
		"WITH ITS PICTURE STILL IN IT - the icon is a region called Icon, not"
		.. " this button's normal texture, so the shape that works on the"
		.. " spellbook would blank it here")
	check(roster.__ring:GetTexture() == 0, "and the stone ring behind it gone")

	-- THREE-SLICE BUTTONS. Left, Right and Middle rather than a normal texture,
	-- so ClearButton finds nothing to clear and the plate outlives it.
	local invite = cf.InviteButton
	check(invite.__aetherSkin ~= nil, "a push button is in one of our pills")
	check(invite.Left:GetTexture() == 0 and invite.Middle:GetTexture() == 0,
		"with all three of its slices cleared, which a normal texture is not")

	-- A DROPDOWN'S ARROW IS REPLACED. It was kept once, on the grounds that it
	-- says "this opens" better than anything of ours would at that size. It
	-- does not: the atlas is a blue-grey stone BUTTON, a picture of a control
	-- rather than a mark on one, and a tint multiplies it rather than
	-- replacing it. Every dropdown gets our chevron now, this one included.
	local dd = cf.StreamDropdown
	check(dd.__aetherSkin ~= nil and dd.Background:GetTexture() == 0,
		"a dropdown's stone holder comes off")
	check(dd.Arrow:GetTexture() == A.Media.texture.chevron,
		"and its arrow is our chevron")
	check(dd.Text._aetherStyle ~= nil, "with its text re-roled")

	check(cf.CommunitiesList.FilligreeOverlay ~= nil
		and select(1, cf.CommunitiesList.FilligreeOverlay:GetRegions()):GetTexture() == 0,
		"the ornate frame around the community list is cleared - it hangs off a"
		.. " child of its own, so a strip of the list alone leaves it drawing")

	-- THE ROSTER'S ROWS. A ScrollBox takes them from a pool during its own
	-- layout, so stripping the PANE reaches none of them - and a row's plaque
	-- is its own NORMAL TEXTURE, which is not a region of anything the pane
	-- sweep walks.
	local stony, glyphless = {}, {}
	for _, key in ipairs({ "MemberList", "CommunitiesList", "ApplicantList" }) do
		for i, row in ipairs(cf[key].ScrollBox.__rows) do
			if row:GetNormalTexture() and row:GetNormalTexture():GetTexture() ~= 0 then
				stony[#stony + 1] = key .. i
			end
			if not (row.Class:IsShown() and row.VoiceChatStatusIcon:IsShown()) then
				glyphless[#glyphless + 1] = key .. i
			end
		end
	end
	check(#stony == 0, "every row in the three lists has lost its plaque (" ..
		(#stony > 0 and table.concat(stony, ",") or "all of them") .. ")")
	check(#glyphless == 0, "and kept its class glyph and its voice lamp, which "
		.. "are in the same layer (" ..
		(#glyphless > 0 and table.concat(glyphless, ",") or "all of them") .. ")")

	-- AND A ROW SCROLLED INTO VIEW AFTERWARDS IS DRESSED TOO. A ScrollBox
	-- acquires from its pool during its own Update, after the window's has
	-- returned - so the window is the wrong thing to hook, which is the same
	-- lesson the gossip window taught.
	local rosterBox = cf.MemberList.ScrollBox
	local was = #rosterBox.__rows
	rosterBox:Update()
	local fresh = rosterBox.__rows[was + 1]
	check(fresh and fresh:GetNormalTexture()
		and fresh:GetNormalTexture():GetTexture() == 0,
		"a row the list acquires later is dressed as well (" .. was .. " -> "
		.. #rosterBox.__rows .. ")")

	check(cf.MemberList.ShowOfflineButton.__aetherCheck ~= nil,
		"and the roster's own check box is ours")

	-- THE SCROLL BAR IS A FRAME OF FRAMES on this window - a track, a thumb and
	-- two arrows, each a child - so a strip of the bar itself finds no regions,
	-- clears nothing, and leaves the stone down the side of the list.
	local bar = cf.CommunitiesList.ScrollBar
	check(select(1, bar.Track:GetRegions()):GetTexture() == 0
		and bar.Back:GetNormalTexture():GetTexture() == 0,
		"a scroll bar is taken apart rather than swept, because nothing in one"
		.. " is a picture and every part of it is a child")

	-- THE CREST comes inside. The portrait template hangs it off the corner to
	-- overlap a stone ring that framed it - the main menu's title plate again -
	-- so with the ring gone it floats outside the window.
	local crest = cf.PortraitOverlay.Portrait
	local cPt, cRel, cRelPt, cx, cy = crest:GetPoint(1)
	check(cPt == "TOPLEFT" and cRel == cf and cx > 0 and cy < 0,
		"the guild crest is brought inside the glass (" .. tostring(cx) .. ","
		.. tostring(cy) .. ") rather than hung off the corner")
	check(crest:GetWidth() < 61,
		"and drawn smaller than the template's own size ("
		.. tostring(crest:GetWidth()) .. " from 61)")
	check(cf.PortraitOverlay.CircleMask:GetWidth() == crest:GetWidth(),
		"with its mask following it - one left where the portrait used to be"
		.. " crops a circle out of empty air")

	-- The big pane you get when you are in no guild: the client's own dark
	-- plate, and two paragraphs in the client's own lettering.
	local finder = _G.ClubFinderGuildFinderFrame
	check(select(1, finder:GetRegions()):GetTexture() == 0
		and select(1, finder.DisabledFrame:GetRegions()):GetTexture() == 0,
		"the pane on the right loses its plate")
	check(finder.DisabledFrame.Title._aetherStyle ~= nil
		and finder.DisabledFrame.Description._aetherStyle ~= nil,
		"and its heading and its paragraph are in our lettering")

	-- A PANE ARRIVES WHEN ITS TAB IS PICKED. Everything but the one you are
	-- looking at is hidden, and a window dressed once at open leaves the other
	-- three in Blizzard's stone the moment you click.
	local benefits = cf.GuildBenefitsFrame
	local art = select(1, benefits:GetRegions())
	art:SetTexture("communities-pane-art")           -- as the client repaints it

	local click = roster:GetScript("OnClick")
	check(click ~= nil,
		"a side tab is hooked - there is no update function on this window to"
		.. " wrap, and none we could name without its source, so the click is"
		.. " the only thing that says which pane is showing now")
	if click then click(roster) end

	check(art:GetTexture() == 0,
		"and a pane that comes back is taken back off, because a window dressed"
		.. " once at open leaves the other three in stone the moment you click")
end

print("== panels: the talent tree, without cutting its branches ==")
do
	_G.__loadPanelAddon("PlayerTalentFrame")
	fire("ADDON_LOADED", "Blizzard_TalentUI")

	local tf = _G.PlayerTalentFrame
	check(tf.__aetherPanel ~= nil,
		"the talent frame is in glass when its addon turns up")
	check(_G.PlayerTalentFrameBackgroundTopLeft:GetTexture() == 0,
		"and the tree's parchment comes off it")

	-- THE BRANCHES AND ARROWS STAY. They are regions of the scroll child and of
	-- the arrow frame, and they are the only thing on screen saying which talent
	-- depends on which. Strip either frame and the tree becomes forty
	-- unconnected icons - which looks tidy enough to pass a screenshot.
	check(_G.PlayerTalentFrameBranch1:GetTexture() == "Interface\\TalentFrame\\UI-TalentBranches"
		and _G.PlayerTalentFrameArrow1:GetTexture() == "Interface\\TalentFrame\\UI-TalentArrows",
		"but the branches and arrows are left alone - they ARE the tree, and a"
		.. " sweep of the frame they hang off takes them with the parchment")

	local t1, t2, t3 = _G.PlayerTalentFrameTalent1, _G.PlayerTalentFrameTalent2,
		_G.PlayerTalentFrameTalent3
	check(t1.__aetherSlot == true, "a talent wears the same cell as a spell")
	check(_G.PlayerTalentFrameTalent1IconTexture:GetTexture() == "talent-icon-1",
		"with the talent still in it")
	check(_G.PlayerTalentFrameTalent1Slot:GetTexture() == 0
		and t1:GetNormalTexture():GetTexture() == 0,
		"and both the stone ring and the empty slot behind it cleared")

	-- THE STATE, IN THE RIM. The client weighs the rank against the maximum,
	-- the tier against the points spent, the prerequisites and whether there is
	-- a point spare - and then says the answer in the Slot's vertex colour.
	-- Reading that is one source of truth; working it out again from
	-- GetTalentInfo would be a second set of rules to keep in step.
	local function rim(b)
		local r, g = b.edge:GetVertexColor()
		return r, g
	end
	local open, full, plain =
		A.Palette.c.talentOpen, A.Palette.c.talentFull, A.Palette.c.glassEdge

	local r1, g1 = rim(t1)
	check(r1 == open[1] and g1 == open[2],
		"one you can put a point in takes the open rim")
	local r2, g2 = rim(t2)
	check(r2 == full[1] and g2 == full[2],
		"a finished one takes the full rim")
	local r3, g3 = rim(t3)
	check(r3 == plain[1] and g3 == plain[2],
		"and one you cannot reach yet keeps the ordinary one - three states, so"
		.. " a rim set for one of them cannot pass by looking right once")

	check(t1.__aetherRank and t1.__aetherRank.disc:GetTexture() == A.Media.texture.chipDisc,
		"the rank sits on a chip of ours rather than Blizzard's stone plate")
	check(_G.PlayerTalentFrameTalent1Rank._aetherStyle ~= nil,
		"with the client's own count on top of it, re-roled - it is what does"
		.. " the counting, and ours would be a second number to keep in step")
	check(not t3.__aetherRank:IsShown(),
		"and no chip at all where the client shows no rank")

	-- THE REPAINT. TalentFrame_Update runs on open, on every tab click and on
	-- every point spent, and it re-sets all four background pieces from the
	-- spec's own art. Art taken off once at dress time is art you see again on
	-- the first click.
	_G.TalentFrame_Update()
	check(_G.PlayerTalentFrameBackgroundTopLeft:GetTexture() == 0
		and t1:GetNormalTexture():GetTexture() == 0,
		"the parchment and the rings stay off after the client repaints the tree")
	local r1b = rim(t1)
	check(r1b == open[1], "and the rims still say what state each talent is in")

	local tb1, tb2 = _G.PlayerTalentFrameTab1, _G.PlayerTalentFrameTab2
	check(tb1.__aetherTab ~= nil and tb1.__aetherMark ~= nil,
		"its tabs are on the same rail as everything else (" ..
		string.format("%.1f", tb1:GetWidth()) .. ")")
	check(_G.PlayerTalentFrameTab4.__aetherTab == nil,
		"and the glyph tab, which this flavour never shows, is left out of it")

	check(not _G.PlayerTalentFrameCancelButton:IsShown(),
		"the spare Close in the corner of the tree is gone, like the skills"
		.. " list's - the window already has one")

	local cPt, cRel, cRelPt = _G.PlayerTalentFrameCloseButton:GetPoint(1)
	check(cPt == "TOPRIGHT" and cRel == tf and cRelPt == "TOPRIGHT",
		"and the real one is in the corner rather than 44 in and 25 down, where"
		.. " the stone rim used to be")

	check(_G.PlayerTalentFrameLearnButton.__aetherSkin ~= nil
		and _G.PlayerTalentFrameLearnButton:GetNormalTexture():GetTexture() == 0,
		"its buttons are ours")
	check(_G.PlayerTalentFrameTalentPointsText._aetherStyle ~= nil
		and _G.PlayerTalentFrameSpentPointsText._aetherStyle ~= nil,
		"and both point readings are in our lettering")

	-- THE OTHER SKIN. A window's shell is a surface and answers ApplySkin; a
	-- talent's rim is a colour read out of the palette once, at dress time, and
	-- nothing re-reads it. So the tree kept the skin it was dressed under until
	-- the next time the frame happened to be redrawn.
	--
	-- Which rim to watch matters. The learned/available greens are SEMANTIC and
	-- deliberately identical in every skin, so a tree that never re-read them at
	-- all would still look right - they cannot prove anything. The unreachable
	-- talent wears glassEdge, which is chrome and moves, and it is the only one
	-- of the three that can tell a re-read from a stale colour.
	do
		local was = A.db.profile.skin
		local midEdge = A.Palette.skins.midnight.glassEdge
		local otherEdge = A.Palette.skins[OTHER].glassEdge
		check(midEdge[1] ~= otherEdge[1] or midEdge[2] ~= otherEdge[2],
			"the ordinary rim is chrome, and really is a different colour on "
			.. OTHER .. " - the greens are semantic and would prove nothing")

		A.db.profile.skin = OTHER
		A:Restyle()
		local dr, dg = rim(t3)
		check(math.abs(dr - otherEdge[1]) < 0.001 and math.abs(dg - otherEdge[2]) < 0.001,
			"switching skin takes the talent rims with it (" ..
			string.format("%.2f", dr) .. " vs " .. string.format("%.2f", otherEdge[1]) .. ")")

		-- And the semantic half of the same tree did NOT move, which is the rule
		-- the family is built on rather than an accident of this module.
		check(rim(t1) == open[1],
			"while the learned green is exactly what it was - a skin remaps"
			.. " chrome, never what a colour MEANS")

		A.db.profile.skin = was
		A:Restyle()
	end
end

print("== palette: difficulty has one owner ==")
do
	local P = A.Palette
	local QLm = A:GetModule("questlog")

	_G.__units.player.level = 16
	check(P:DifficultyBand(21) == "impossible" and P:DifficultyBand(19) == "verydifficult"
		and P:DifficultyBand(16) == "difficult" and P:DifficultyBand(10) == "standard"
		and P:DifficultyBand(1) == "trivial",
		"all five bands answer off the player's level")
	check(QLm.DifficultyBand(21) == P:DifficultyBand(21),
		"and the quest log still answers under its own name - the tracker resolves"
		.. " QL.DifficultyBand per call and would have dropped silently to its"
		.. " neutral fallback if the move had taken that away")

	check(P:SkullLevel(26) == true, "ten levels up is a skull")
	check(P:SkullLevel(25) == false, "nine is still a number")
	check(P:SkullLevel(-1) == true,
		"and so is a unit the client will not name a level for - it hands back -1"
		.. " there, which as a number is far BELOW you, not above")

	local fill, edge, ink = P:DifficultyColors(21)
	local band = P.c.questDiff.impossible.text
	check(ink == band, "the badge's number is the quest log's own band colour")
	check(fill[1] == band[1] and fill[4] == 0.15 and edge[4] == 0.40,
		"with the disc at .15 of it and the rim at .40 - the tooltip badge's recipe")
	local triv = P:DifficultyColors(1)
	check(triv[1] ~= fill[1] or triv[2] ~= fill[2],
		"and a trivial level is not tinted like a deadly one")
end

print("== palette: a name tells friendly PLAYER from friendly NPC ==")
do
	local P, units = A.Palette, _G.__units
	units.__np = { exists = true, name = "Kolkar Marauder", level = 18, reaction = 2 }

	check(P:NameReaction("__np") == P.c.ttHostile, "a hostile mob takes the red")
	units.__np.reaction = 4
	check(P:NameReaction("__np") == P.c.ttNeutral, "neutral takes the gold")
	units.__np.reaction = 5
	check(P:NameReaction("__np") == P.c.ttFriendlyNPC, "a friendly NPC is green")
	units.__np.isPlayer = true
	check(P:NameReaction("__np") == P.c.ttFriendly, "and a friendly PLAYER is blue")

	-- Why the name does not simply go through ReactionEdge.
	local playerEdge = P:ReactionEdge("__np")
	units.__np.isPlayer = false
	local npcEdge = P:ReactionEdge("__np")
	check(npcEdge[1] == playerEdge[1] and npcEdge[2] == playerEdge[2],
		"ReactionEdge collapses both friendlies into one green - correct for a rim,"
		.. " useless for the one line of text on a friendly nameplate")

	units.__np = nil
end

print("== skins: all four define the same vocabulary ==")
do
	-- Composed from one function now, so this ought to be unfalsifiable - and it
	-- is kept precisely because it USED to fail. Two hand-written tables drifted
	-- to 81 differences in 86 tokens. The day somebody adds a per-skin special
	-- case to Compose, this is what notices.
	local mid = A.Palette.skins.midnight
	local missing = {}
	for _, name in ipairs(SKINS) do
		local skin = A.Palette.skins[name]
		check(skin ~= nil, name .. " exists at all")
		for token in pairs(mid) do
			if skin[token] == nil then missing[#missing + 1] = name .. " lacks " .. token end
		end
		for token in pairs(skin) do
			if mid[token] == nil then missing[#missing + 1] = name .. " only: " .. token end
		end
	end
	check(#missing == 0,
		"every token exists in every skin - a token added to one only is a nil"
		.. " index in the middle of a redraw (missing: "
		.. table.concat(missing, ", ") .. ")")
end

print("== palette: the colours that are written out, so drift fails ==")
do
	-- WRITTEN OUT, deliberately. Everywhere else in this file a colour is
	-- compared against the palette, which proves the lookup works and says
	-- nothing about the value - move the token and the check moves with it.
	--
	-- These are the client's own numbers and the whole point of them is that
	-- they MATCH THE GAME: a curse that is one purple on an aura ring and
	-- another on Blizzard's own frames is worse than no colour at all. So the
	-- expected values live here, spelled out, and drift fails.
	local WANT = {
		{ "debuffSchool", "Magic",     0.55, 0.78, 1.00 },
		{ "debuffSchool", "Curse",     0.70, 0.50, 1.00 },
		{ "debuffSchool", "Disease",   0.70, 0.60, 0.35 },
		{ "debuffSchool", "Poison",    0.55, 0.85, 0.45 },
		{ "zonePvP",      "sanctuary", 0.41, 0.80, 0.94 },
		{ "zonePvP",      "arena",     1.00, 0.10, 0.10 },
		{ "zonePvP",      "friendly",  0.10, 1.00, 0.10 },
		{ "zonePvP",      "hostile",   1.00, 0.10, 0.10 },
		{ "zonePvP",      "contested", 1.00, 0.70, 0.00 },
		{ "zonePvP",      "combat",    1.00, 0.10, 0.10 },
	}
	-- Flat colours rather than tables, so they are listed apart. The gold is
	-- ours rather than the client's, but it is here for the same reason: a
	-- colour compared only against its own token can move without a check
	-- noticing, and the coin moving is a thing somebody would see.
	local FLAT = {
		{ "iconNoMana",   0.45, 0.55, 1.00 },
		{ "iconUnusable", 0.40, 0.40, 0.40 },
		{ "money",        0.90, 0.76, 0.42 },
	}
	local moved = {}
	for _, w in ipairs(WANT) do
		local group, key = w[1], w[2]
		local c = (A.Palette.c[group] or {})[key]
		if type(c) ~= "table" then
			moved[#moved + 1] = group .. "." .. key .. " missing"
		else
			for i = 1, 3 do
				if math.abs(c[i] - w[i + 2]) > 0.0001 then
					moved[#moved + 1] = string.format("%s.%s[%d] %.3f want %.3f",
						group, key, i, c[i], w[i + 2])
				end
			end
		end
	end
	for _, w in ipairs(FLAT) do
		local c = A.Palette.c[w[1]]
		for i = 1, 3 do
			if type(c) ~= "table" or math.abs(c[i] - w[i + 1]) > 0.0001 then
				moved[#moved + 1] = w[1] .. "[" .. i .. "]"
			end
		end
	end
	check(#moved == 0,
		"the schools, the zone types, the button states and the money gold are"
		.. " exactly the values they shipped as ("
		.. table.concat(moved, ", ") .. ")")

	-- And they are the same on every skin, because they are not ours to remap.
	local drifted = {}
	for _, group in ipairs({ "debuffSchool", "zonePvP" }) do
		for _, name in ipairs(SKINS) do
			if A.Palette.skins[name][group] ~= A.Palette.skins.midnight[group] then
				drifted[#drifted + 1] = name .. "." .. group
			end
		end
	end
	check(#drifted == 0,
		"and one table shared by all four skins, not four copies to keep in"
		.. " step (" .. table.concat(drifted, ", ") .. ")")
end

section("skins: a live switch, with no reload", function()
	local P, W2 = A.Palette, A.Widgets

	-- THE POINT OF THE WHOLE FAMILY. The brief asks for a live switch and a
	-- character keeping its choice; a skin you have to /reload into is a skin
	-- nobody tries on.
	--
	-- Before the two registries below, a switch left around five hundred
	-- surfaces wearing the skin they were BUILT under - every module walked its
	-- own widgets on OnSkinChanged and most of them missed some. A surface knows
	-- which tokens it was dressed from; its owner should not have to remember on
	-- its behalf.
	local function key(c)
		return string.format("%.4f/%.4f/%.4f/%.4f", c[1], c[2], c[3], c[4] or 1)
	end

	A.db.profile.skin = "midnight" A:Restyle()
	local wasGlass = P.c.glass
	A.db.profile.skin = OTHER A:Restyle()
	check(P.current == OTHER, "the switch lands on " .. OTHER)
	check(key(P.c.glass) ~= key(wasGlass),
		"and the glass really is a different colour, or nothing below means"
		.. " anything")

	-- Every registered surface, every registered string, every registered
	-- texture. Swept as a set rather than named one at a time: a check that
	-- lists frames only covers the frames somebody thought to list.
	-- AND EVERY TOKEN A SURFACE WAS DRESSED FROM IS ONE THE PALETTE HAS.
	--
	-- Glass looks the name up in Palette.c and falls back SILENTLY when it
	-- misses, so `fill = "none"` - which is what somebody writes meaning "no
	-- fill", and which Glass has no token for - draws the default glass and
	-- then never moves again. The welcome card's quiet button carried one, and
	-- the only symptom was the loop below indexing nil three hundred checks
	-- later, in a block about something else entirely.
	do
		local bogus = {}
		for _, sf in ipairs(A.Glass.surfaces) do
			if sf._fillToken and not P.c[sf._fillToken] then
				bogus[#bogus + 1] = "fill:" .. tostring(sf._fillToken)
			end
			if sf._edgeToken and not P.c[sf._edgeToken] then
				bogus[#bogus + 1] = "edge:" .. tostring(sf._edgeToken)
			end
		end
		check(#bogus == 0,
			"no surface was dressed from a token this palette has not got (" ..
			(#bogus > 0 and table.concat(bogus, ", ", 1, math.min(#bogus, 6))
			or "none") .. ")")
	end

	local stale = {}
	for _, sf in ipairs(A.Glass.surfaces) do
		if sf._fillToken and sf._fillColor
			and key(sf._fillColor) ~= key(P.c[sf._fillToken]) then
			stale[#stale + 1] = "fill:" .. sf._fillToken
		end
		if sf._edgeToken and sf._edgeColor
			and key(sf._edgeColor) ~= key(P.c[sf._edgeToken]) then
			stale[#stale + 1] = "edge:" .. sf._edgeToken
		end
	end
	check(#stale == 0,
		#A.Glass.surfaces .. " glass surfaces, and not one still wearing the old"
		.. " skin (" .. table.concat(stale, ", ", 1, math.min(#stale, 6)) .. ")")

	local inkStale = 0
	for _, fs in ipairs(W2.inked) do
		local want = fs._aetherInk and P.c[fs._aetherInk]
		if want and fs.GetTextColor and key({ fs:GetTextColor() }) ~= key(want) then
			inkStale = inkStale + 1
		end
	end
	check(inkStale == 0,
		#W2.inked .. " strings, likewise (" .. inkStale .. " stale)")

	local tintStale = 0
	for _, tex in ipairs(W2.tinted) do
		local want = tex._aetherTint and P.c[tex._aetherTint]
		if want then
			local a = tex._aetherTintAlpha or want[4] or 1
			local r, g, b, ta = tex:GetVertexColor()
			if math.abs(r - want[1]) > 0.001 or math.abs(g - want[2]) > 0.001
				or math.abs(b - want[3]) > 0.001 or math.abs((ta or 1) - a) > 0.001 then
				tintStale = tintStale + 1
			end
		end
	end
	check(tintStale == 0,
		#W2.tinted .. " textures, likewise, AT THE WEIGHT THE CALLER ASKED FOR -"
		.. " the XP wash is quieter than a status bar and has to stay that way"
		.. " across a restyle (" .. tintStale .. " stale)")

	-- And the sweeps are not no-ops. Zero surfaces swept passes every line
	-- above, and is exactly what a registry that never registers looks like.
	check(#A.Glass.surfaces > 100 and #W2.inked > 100,
		"with real numbers in both registries, not an empty sweep (" ..
		#A.Glass.surfaces .. " surfaces, " .. #W2.inked .. " strings, " ..
		#W2.tinted .. " textures)")

	A.db.profile.skin = "midnight" A:Restyle()
end)

section("profiles: nothing keeps a reference to a config table", function()
	local AB2 = A:GetModule("actionbars")
	local was = A.db:GetCurrentProfile()

	-- WHAT ACEDB DOES ON THE WAY OUT, and it is not a bug: switching away from
	-- a profile strips every value equal to a default OUT OF THAT PROFILE'S
	-- TABLES, in place, so only the differences are saved. Anything holding one
	-- of those tables is left with an EMPTY one - not stale, empty.
	--
	-- Proved here directly rather than inferred, because every file involved
	-- reads perfectly correctly and only a real SetProfile shows it.
	local held = A.db.profile.modules.actionbars.bars[2]
	check(held.point ~= nil, "a config entry has a point in it to begin with")
	A.db:SetProfile("__profiletest")
	check(held.point == nil,
		"and the table we held is emptied by the switch - THIS is the hazard, and"
		.. " a module that cached one has been reading nothing ever since")

	-- So every bar must be pointing at the LIVE entry, not the one it was built
	-- with. Checked by identity: equal contents would also pass if the module
	-- had copied the values across, and a copy goes stale on the next write.
	local live = A.db.profile.modules.actionbars.bars
	local byId = {}
	for _, c in ipairs(live) do byId[tostring(c.id)] = c end
	local wrong, hollow = {}, {}
	for _, bar in ipairs(AB2.bars) do
		if byId[tostring(bar.id)] and bar.cfg ~= byId[tostring(bar.id)] then
			wrong[#wrong + 1] = bar.id
		end
		if bar.kind == "action" and bar.cfg.point == nil then
			hollow[#hollow + 1] = bar.id
		end
	end
	check(#wrong == 0,
		"every bar reads the new profile's own table (" ..
		table.concat(wrong, ", ") .. ")")
	check(#hollow == 0,
		"and every one of them has an anchor point - a bar with none is anchored"
		.. " to nothing, which is the top-left corner and no way to drag it back ("
		.. table.concat(hollow, ", ") .. ")")

	-- AND IT HAPPENS BEFORE ANYTHING READS IT. The restyle reads bar.cfg for the
	-- dock skin and the per-bar scale, and it runs first - so re-binding inside
	-- OnConfigChanged alone was already too late, and the bug survived a fix
	-- that looked complete.
	check(A.lastFailure == nil,
		"and the whole switch raised nothing (" .. tostring(A.lastFailure) .. ")")

	-- A DISABLED bar too. Every bar that was wrong was a disabled one: the
	-- re-bind lived in the branch that runs for enabled bars only, so the check
	-- has to name a bar that is off.
	local off
	for _, bar in ipairs(AB2.bars) do
		if bar.cfg.enabled == false then off = off or bar end
	end
	check(off ~= nil, "there is a disabled bar to look at")
	if off then
		check(off.cfg == byId[tostring(off.id)],
			"a bar that is switched OFF is re-bound as well - those were the only"
			.. " ones that were wrong, and they are the ones nobody looks at")
	end


	-- IN COMBAT, which is what makes the re-binding its own step rather than a
	-- line inside SyncBars.
	--
	-- AB:OnConfigChanged returns immediately in combat - laying bars out means
	-- moving frames with secure children, and the client refuses - so SyncBars,
	-- and the re-bind with it, does not run at all. The restyle does. Without a
	-- step of its own, every bar would read a hollow table for as long as the
	-- fight lasted, and nothing would look wrong until something asked one of
	-- them where it lived.
	A.db:SetProfile(was)
	_G.__inCombat = true
	A.lastFailure = nil
	A.db:SetProfile("__profiletest")

	local liveNow = {}
	for _, c in ipairs(A.db.profile.modules.actionbars.bars) do
		liveNow[tostring(c.id)] = c
	end
	local stale = {}
	for _, bar in ipairs(AB2.bars) do
		if liveNow[tostring(bar.id)] and bar.cfg ~= liveNow[tostring(bar.id)] then
			stale[#stale + 1] = bar.id
		end
	end
	check(#stale == 0,
		"a profile change IN COMBAT still re-binds every bar, even though the"
		.. " layout pass it used to ride on is skipped entirely (" ..
		table.concat(stale, ", ") .. ")")
	check(A._profilePending == true,
		"while the REDRESSING is deferred whole - rescaling a unit capsule means"
		.. " touching a frame with a secure button in it, which the client"
		.. " refuses, and the player gets an interface-blocked dialog mid-fight"
		.. " for something they did before it started")
	check(A.lastFailure == nil,
		"and nothing was blocked on the way (" .. tostring(A.lastFailure) .. ")")

	-- And it catches up when the fight ends, from a registration made at load
	-- rather than one made inside the deferral.
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(A._profilePending == nil,
		"and the deferred half runs when the fight ends, once")

	A.db:SetProfile(was)
	for _, bar in ipairs(AB2.bars) do
		if bar.kind == "action" then
			check(bar.cfg.point ~= nil,
				"and switching back is the same story in the other direction (bar "
				.. bar.id .. ")")
			break
		end
	end
end)

section("skins: the choice belongs to the profile, and travels with it", function()
	local P = A.Palette
	local was = A.db:GetCurrentProfile()

	-- WHERE THE CHOICE LIVES. The brief says persist it per character; this
	-- addon has Ace profiles, so the honest answer is profile scope and the
	-- player picks what that scope IS - default, character, class, realm. Storing
	-- it per character behind the profile system would give somebody two places
	-- to set one thing and no way to tell which had won.
	A.db.profile.skin = "midnight" A:Restyle()
	check(P.current == "midnight", "midnight on this profile")

	A.db:SetProfile("__skintest")
	A.db.profile.skin = OTHER A:Restyle()
	check(P.current == OTHER, "and " .. OTHER .. " on another")

	-- The switch back is the whole point, and it must NOT need a reload: AceDB
	-- fires OnProfileChanged, Core answers it with a restyle, and the interface
	-- is in the other skin before the profile dropdown has closed.
	A.db:SetProfile(was)
	check(P.current == "midnight",
		"and changing profile carries the skin with it, live - no reload, no"
		.. " second call (" .. tostring(P.current) .. ")")
	check(P.c.glass == P.skins.midnight.glass,
		"with the palette actually swapped, not merely the name")

	-- A profile naming a skin that no longer exists degrades to midnight rather
	-- than to a nil palette - which is every colour in the addon at once.
	A.db.profile.skin = "daylight" A:Restyle()
	check(P.current == "midnight",
		"a profile still asking for a skin that was removed falls back to midnight"
		.. " rather than to a nil table (" .. tostring(P.current) .. ")")
	A.db.profile.skin = "midnight" A:Restyle()
end)
section("skins: what a live switch actually looks like on the HUD", function()
	local P = A.Palette
	local function rgb(...) local r, g, b = ... return r, g, b end

	-- The two registries cover everything dressed BY TOKEN. These are the ones
	-- they deliberately do not reach - colours a module sets from state - and so
	-- the ones that need naming one at a time. Both were wrong: an empty action
	-- slot kept its old rim because every state painter returned early on a slot
	-- with nothing in it, and a buff tile was dressed with a colour rather than
	-- a token so the sweep passed it by.
	A.db.profile.skin = "midnight" A:Restyle()
	A.db.profile.skin = OTHER A:Restyle()

	local want = P.c.glassEdge
	local AB2 = A:GetModule("actionbars")
	local empty
	for _, bar in ipairs(AB2.bars) do
		for i, b in ipairs(bar.buttons) do
			if bar.kind == "action" and not b.__aetherAdopted
				and not HasAction(b:GetAttribute("action")) then
				empty = empty or b
			end
		end
	end
	check(empty ~= nil, "the fixture has an empty action slot to look at")
	if empty then
		local r, g, b = rgb(empty.edge:GetVertexColor())
		check(math.abs(r - want[1]) < 0.001 and math.abs(g - want[2]) < 0.001
			and math.abs(b - want[3]) < 0.001,
			"an EMPTY slot wears the new skin's rim - it is still on screen at a"
			.. " quarter alpha, and it was the last thing on the bar still wearing"
			.. " the old one (" .. string.format("%.2f %.2f %.2f", r, g, b) .. ")")
	end

	-- A stance button on a client with no stance API at all: built, on screen,
	-- and returning before any rim was ever set.
	for _, bar in ipairs(AB2.bars) do
		if bar.kind == "stance" and bar.buttons[1] then
			local r, g, b = rgb(bar.buttons[1].edge:GetVertexColor())
			check(math.abs(r - want[1]) < 0.001 and math.abs(g - want[2]) < 0.001
				and math.abs(b - want[3]) < 0.001,
				"and so does a stance slot (" ..
				string.format("%.2f %.2f %.2f", r, g, b) .. ")")
		end
	end

	-- And on a client with NO stance API at all. The rim is dressed before that
	-- guard rather than after it, and with the API present both orders look the
	-- same - so the only way to see the difference is to take it away.
	do
		local real = _G.GetShapeshiftFormInfo
		_G.GetShapeshiftFormInfo = nil
		for _, bar in ipairs(AB2.bars) do
			if bar.kind == "stance" and bar.buttons[1] then
				bar.buttons[1].edge:SetVertexColor(1, 0, 1, 1)   -- something wrong
				AB2.Repaint(bar.buttons[1])
				local r, g, b = rgb(bar.buttons[1].edge:GetVertexColor())
				check(math.abs(r - want[1]) < 0.001 and math.abs(g - want[2]) < 0.001
					and math.abs(b - want[3]) < 0.001,
					"a stance button on a client that has no stance API is still"
					.. " built, still on screen, and still gets a rim (" ..
					string.format("%.2f %.2f %.2f", r, g, b) .. ")")
			end
		end
		_G.GetShapeshiftFormInfo = real
		AB2:RefreshAll()
	end

	-- A buff tile, which is plain glass and had to say so BY TOKEN to be swept.
	local AU2 = A:GetModule("auras")
	local tile = AU2.playerBuffs and AU2.playerBuffs.tiles[1]
	check(tile ~= nil, "and a buff tile to look at")
	if tile then
		check(tile._fillToken == "glass",
			"a buff tile is dressed from the glass token rather than handed the"
			.. " colour, which is what puts it on the sweep at all")
		check(tile._fillColor == P.c.glass,
			"so it is wearing the live skin's glass after the switch")
	end

	-- A debuff tile is the other way round on purpose: its colour is its school,
	-- which is semantic, so it must NOT move when the skin does.
	local dtile = AU2.playerDebuffs and AU2.playerDebuffs.tiles[2]
	if dtile then
		local r, g, b = rgb(dtile.art.ring:GetVertexColor())
		local curse = P.c.debuffSchool.Curse
		check(math.abs(r - curse[1]) < 0.001 and math.abs(g - curse[2]) < 0.001
			and math.abs(b - curse[3]) < 0.001,
			"while a debuff tile keeps its school colour, which is semantic and the"
			.. " same in all four (" ..
			string.format("%.2f %.2f %.2f", r, g, b) .. ")")
	end

	A.db.profile.skin = "midnight" A:Restyle()
end)
section("skins: a colour set by hand is NOT swept away", function()
	local P = A.Palette
	A.db.profile.skin = "midnight" A:Restyle()

	-- The other half of the same rule, and the one that would break the HUD if
	-- it were wrong: a target capsule takes its reaction tint, a slot its
	-- quality rim, an aura tile its debuff school. Whoever set that owns it, and
	-- the sweep walking in afterwards and painting the skin default back over
	-- the top would turn every stateful colour on screen into plain glass.
	local s = A.Glass.CreatePanel(UIParent, { corner = 8 })
	s:ApplySkin("glass", "glassEdge")
	check(s._fillToken == "glass", "a surface dressed from a token remembers it")

	local mine = { 0.9, 0.1, 0.2, 1 }
	s:SetFillColor(mine)
	check(s._fillToken == nil,
		"and setting a colour by hand hands ownership back - the token is gone,"
		.. " not merely overwritten")

	A.db.profile.skin = OTHER A:Restyle()
	check(s._fillColor == mine,
		"so a restyle leaves it exactly where its owner put it")

	-- Same for a string. W.Color is handed a palette table or a computed one,
	-- and only the first kind is the palette's to keep changing.
	local fs = A.Widgets.Text(UIParent, "label", "LEFT")
	A.Widgets.Color(fs, P.c.accent)
	check(fs._aetherInk == "accent", "a string coloured from a token remembers it")
	A.Widgets.Color(fs, { 0.1, 0.9, 0.3, 1 })
	check(fs._aetherInk == nil, "and a computed colour clears it")
	A:Restyle()
	local r, g = fs:GetTextColor()
	check(math.abs(r - 0.1) < 0.001 and math.abs(g - 0.9) < 0.001,
		"so the sweep leaves that one alone too")

	A.db.profile.skin = "midnight" A:Restyle()
end)

section("skins: things that are not modules get told too", function()
	-- Eighteen modules get OnSkinChanged and always have. The context menu is
	-- not a module - any of them can open it - and Core used to name it by hand
	-- in Restyle, which is a list that only holds what somebody remembered to
	-- put in it.
	local fired = 0
	A:OnSkinChanged(function() fired = fired + 1 end)
	A:Restyle()
	check(fired == 1, "a listener is called once per restyle (" .. fired .. ")")
	A:Restyle()
	check(fired == 2, "and again on the next one")

	-- A bad listener must not take the restyle down with it. Half a skin change
	-- is worse than none: the interface is left in two skins at once.
	A:OnSkinChanged(function() error("deliberate") end)
	local after = 0
	A:OnSkinChanged(function() after = after + 1 end)
	A.lastFailure = nil
	A:Restyle()
	check(after == 1,
		"a listener that errors does not stop the ones behind it")
	check(A.lastFailure ~= nil, "and the failure is recorded rather than swallowed")
	A.lastFailure = nil
end)

print("== skins: chat ink follows the skin, because it is not baked in ==")
do
	local P = A.Palette

	-- A chat line cannot be re-coloured once it is in the log, so the colour
	-- has to be right at the moment the string is built. The 203 escapes this
	-- replaced were right on exactly one skin.
	P:Apply("midnight")
	local mid = A.Hi("x")
	P:Apply(OTHER)
	local other = A.Hi("x")
	check(mid ~= other,
		"the same call gives a different colour on a different skin")
	check(other:find(P:Hex(P.skins[OTHER].accent), 1, true) ~= nil,
		"and it is the LIVE skin's accent, not a remembered one (" .. other
		.. ")")

	-- Each helper on its own token. Two of them pointing at the same one is
	-- the kind of thing every other check here would sail past.
	local roles = {
		{ A.Hi, "accent" }, { A.Val, "text" }, { A.Good, "friendly" },
		{ A.Bad, "danger" }, { A.Dim, "dim" },
	}
	local seen = {}
	for _, r in ipairs(roles) do
		local fn, token = r[1], r[2]
		local hex = P:Hex(P.c[token])
		check(fn("x") == P:InkHex(hex, "x"),
			token .. " is what its helper writes (" .. fn("x") .. ")")
		check(not seen[hex], token .. " has a colour of its own")
		seen[hex] = true
	end

	-- A token that does not exist falls back to type rather than to nil, which
	-- in a chat line is the string |cffnil<text>.
	check(P:Ink("noSuchToken", "x") == P:InkHex(P:Hex(P.c.text), "x"),
		"an unknown token draws as ordinary type rather than as the word nil")

	P:Apply("midnight")
end

print("== skins: the family is offered in the order it is named for ==")
do
	local P = A.Palette
	local list = P:List()
	check(#list == #SKINS, "four skins are offered (" .. #list .. ")")

	-- The order is the day, not the alphabet - which sorts to dawn, dusk,
	-- midnight, noon and reads as four unrelated words.
	local keys, labels = {}, {}
	for i, e in ipairs(list) do
		keys[i] = e.key
		labels[i] = e.label
		check(e.label and e.label ~= "" and e.label ~= e.key,
			e.key .. " is offered under a written name rather than its key ("
			.. tostring(e.label) .. ")")
	end
	check(table.concat(keys, ",") == table.concat(SKINS, ","),
		"and in the day's order, not the alphabet's (" ..
		table.concat(keys, ", ") .. ")")

	-- And the order is what BUILDS them, so a skin left out of it does not exist
	-- rather than existing unreachably.
	local n = 0
	for _ in pairs(P.skins) do n = n + 1 end
	check(n == #SKINS,
		"there are no skins outside the order - one built and not offered is a"
		.. " skin nobody can pick and everybody has to maintain (" .. n .. ")")
end

print("== skins: a skin is a HUE remap, never a value one ==")
do
	-- THE BRIEF'S BINDING RULE, and the reason Daylight was dropped: components
	-- never change geometry, size, opacity, blur or shadow between skins.
	-- Brightness lives in the hue. So every alpha in the family has to be
	-- identical across all four, and only the RGB may move.
	--
	-- Written as a sweep rather than a list because the failure it catches is a
	-- token somebody tuned on one skin and nowhere else, which is exactly the
	-- token nobody would think to enumerate here.
	local function alphas(t, prefix, out)
		for k, v in pairs(t) do
			if type(v) == "table" then
				if type(v[1]) == "number" and #v >= 3 then
					out[prefix .. tostring(k)] = v[4] or 1
				else
					alphas(v, prefix .. tostring(k) .. ".", out)
				end
			end
		end
		return out
	end
	local base = alphas(A.Palette.skins.midnight, "", {})
	local moved, hues = {}, 0
	for _, name in ipairs(SKINS) do
		if name ~= "midnight" then
			local other = alphas(A.Palette.skins[name], "", {})
			for token, a in pairs(base) do
				if math.abs((other[token] or -1) - a) > 0.0001 then
					moved[#moved + 1] = name .. "." .. token
				end
			end
		end
	end
	check(#moved == 0,
		"not one alpha moves between skins (" .. table.concat(moved, ", ") .. ")")

	-- And the other half of the same claim: the hue DID move. Without this the
	-- check above passes on four identical skins.
	for _, name in ipairs(SKINS) do
		if name ~= "midnight" then
			local a, b = A.Palette.skins.midnight.accent, A.Palette.skins[name].accent
			if a[1] ~= b[1] or a[2] ~= b[2] or a[3] ~= b[3] then hues = hues + 1 end
		end
	end
	check(hues == #SKINS - 1,
		"while every other skin's accent is a different colour from midnight's ("
		.. hues .. " of " .. (#SKINS - 1) .. ")")
end

print("== skins: every skin draws LIGHT type on DARK glass ==")
do
	-- Not a stylistic note, a constraint. Daylight was tried as a light theme
	-- with dark ink and it failed on something that cannot be configured: WoW's
	-- OUTLINE flag is always BLACK, so every role carrying it - the level orb,
	-- stack counts, keybinds - drew dark text inside a black rim on white.
	--
	-- So the whole family keeps light text on dark glass, and every colour the
	-- game hands us (RAID_CLASS_COLORS, GetQuestDifficultyColor, ChatTypeInfo)
	-- works unchanged on all of them. A future skin wanting dark ink has to drop
	-- those outlines first.
	local function lum(c) return 0.299*c[1] + 0.587*c[2] + 0.114*c[3] end
	for _, name in ipairs(SKINS) do
		local skin = A.Palette.skins[name]
		check(lum(skin.text) > 0.7,
			name .. "'s primary text is light (" ..
			string.format("%.2f", lum(skin.text)) .. ")")
		check(lum(skin.glass) < 0.2,
			name .. "'s panel fill is dark (" ..
			string.format("%.2f", lum(skin.glass)) .. ") - the glass stays dark"
			.. " in all four, which is what the family is FOR")
	end

	local outlined = 0
	for _, style in pairs(A.Media.style) do
		if style[3] == "OUTLINE" then outlined = outlined + 1 end
	end
	check(outlined > 0,
		"there are still " .. outlined .. " roles with a hardcoded black OUTLINE,"
		.. " which is what pins the whole family to light type")
end

print("== skins: the rim is what makes a panel a panel ==")
do
	-- A dark panel over dark terrain is a smudge without a boundary, and this is
	-- the pairing that gives it one. Daylight needed a rim twice midnight's to
	-- survive on pale ground; the family that replaced it is dark throughout, so
	-- the rim can be the same weight on all four - but it still has to be THERE,
	-- and it still has to out-read the fill it surrounds.
	local function lum(c) return 0.299*c[1] + 0.587*c[2] + 0.114*c[3] end
	for _, name in ipairs(SKINS) do
		local skin = A.Palette.skins[name]
		check(lum(skin.glassEdge) * (skin.glassEdge[4] or 1)
			> lum(skin.glass) * (skin.glass[4] or 1),
			name .. ": the rim reads stronger than the fill it encloses")
		check((skin.glass[4] or 1) < 0.8,
			name .. ": and the fill is still glass rather than a slab (" ..
			string.format("%.2f", skin.glass[4]) .. ")")
		check((skin.shadow[4] or 1) > 0,
			name .. ": with a drop shadow lifting it off the ground")
	end
end

print("== skins: reading surfaces sit deeper than control surfaces ==")
do
	local P = A.Palette
	local C2, QLg = A:GetModule("chat"), A:GetModule("questlog")

	-- Two kinds of panel, two opacities. Action bars and unit capsules are
	-- glanced at; chat and the quest log carry paragraphs of small text over
	-- moving scenery, and at the control-surface opacity the clutter behind
	-- competes with every glyph. Chat has always sat deeper - the quest log was
	-- shipped at the control opacity and was hard to read for exactly that reason.
	for _, name in ipairs(SKINS) do
		P:Apply(name)
		local control = P.c.glassStrong[4] or 1
		local reading = P:ReadingFill()[4] or 1
		check(reading > control,
			name .. ": a reading surface is deeper than a control surface (" ..
			string.format("%.2f vs %.2f", reading, control) .. ")")
		check(reading < 1,
			"and never fully opaque - it is still glass")
	end

	P:Apply("midnight")
	C2:OnSkinChanged()
	QLg:OnSkinChanged()
	local want = P:ReadingFill()[4]
	check(math.abs((C2.panel._fillColor[4] or 1) - want) < 0.001,
		"chat uses it")
	check(math.abs((QLg.win._fillColor[4] or 1) - want) < 0.001,
		"and so does the quest log - one helper, so the two cannot drift apart")

	-- The boost closes a fraction of the remaining transparency rather than
	-- adding a constant: a flat addition is a different proportion on every skin,
	-- and a multiplier overshoots into opaque once the base is high.
	local function closed(skin)
		P:Apply(skin)
		local base = P.c.glassStrong[4] or 1
		return ((P:ReadingFill()[4] or 1) - base) / (1 - base)
	end
	local a, spread = closed("midnight"), 0
	for _, name in ipairs(SKINS) do
		spread = math.max(spread, math.abs(closed(name) - a))
	end
	check(spread < 0.001,
		"and closes the same fraction of the gap to opaque on every skin (worst"
		.. " gap " .. string.format("%.3f", spread) .. ")")
	P:Apply("midnight")
	C2:OnSkinChanged()
	QLg:OnSkinChanged()
end

print("== skins: reading opacity is a setting, not a constant ==")
do
	local P = A.Palette
	local C2, QLg = A:GetModule("chat"), A:GetModule("questlog")
	local cfg = A.db.profile.glass
	local saved = cfg.readOpacity

	check(saved == 0.35,
		"the default matches the constant it replaced, so nobody's HUD moved")

	-- How much background clutter a person can read through is eyesight and
	-- taste, so it is a slider rather than a number in the source.
	local function alphas(v)
		cfg.readOpacity = v
		A:Restyle()
		return (C2.panel._fillColor[4] or 1), (QLg.win._fillColor[4] or 1)
	end

	local base = P.c.glassStrong[4]
	local c0, q0 = alphas(0)
	check(math.abs(c0 - base) < 0.001 and math.abs(q0 - base) < 0.001,
		"at 0 they match the control surfaces exactly (" ..
		string.format("%.2f", c0) .. ")")

	local c1, q1 = alphas(1)
	check(c1 > 0.99 and q1 > 0.99, "at 1 they are solid")

	local ch, qh = alphas(0.7)
	check(ch > c0 and ch < c1 and math.abs(ch - qh) < 0.001,
		"and in between they move together - one setting, both panels (" ..
		string.format("%.2f", ch) .. ")")

	-- A saved variable is whatever was last written to it, including by hand.
	cfg.readOpacity = -3
	A:Restyle()
	check((C2.panel._fillColor[4] or 1) >= base,
		"a negative value clamps rather than making the panel more transparent"
		.. " than the HUD it belongs to")
	cfg.readOpacity = 42
	A:Restyle()
	check((C2.panel._fillColor[4] or 1) <= 1, "and an absurd one clamps to solid")

	cfg.readOpacity = saved
	A:Restyle()

	-- Reachable without editing the source, which is the whole point.
	local found
	local function walk(node)
		for _, opt in pairs(node.args or {}) do
			if opt.type == "group" then walk(opt)
			elseif opt.arg and opt.arg.path and opt.arg.path[1] == "glass"
				and opt.arg.path[2] == "readOpacity" then found = opt end
		end
	end
	walk(A.Options:Build())
	check(found and found.type == "range",
		"and it is a slider in the options panel, not a line in Palette.lua")
	check(found and found.arg.after == "restyle",
		"which restyles on change, so it takes effect without a /reload")
end

print("== chat: the selected tab ==")
do
	local C3 = A:GetModule("chat")
	local tab1, tab2 = _G.ChatFrame1Tab, _G.ChatFrame2Tab

	-- `dock.selected` is a FRAME. Comparing it to tab:GetID() is comparing a
	-- table to a number, which is never equal - so the selected tab never lit up
	-- in game while the harness, which stored a number, was perfectly happy.
	check(type(_G.GeneralDockManager.selected) == "table",
		"the dock records its selection as a frame, as the client does")
	check(C3.SelectedChatID() == 1,
		"and the module resolves it to an id (got " ..
		tostring(C3.SelectedChatID()) .. ")")

	-- THE UNREAD DOT. Blizzard's tab flash runs with flashDuration -1, so once
	-- it starts it stays SHOWN until something stops it - and selecting the tab
	-- is not reliably that something. So the dot appeared on the very window
	-- whose contents were in front of you, which is what got reported.
	do
		local flash1 = _G.ChatFrame1TabFlash
		local flash2 = _G.ChatFrame2TabFlash
		check(flash1 and flash2, "the tabs have Blizzard's flash textures")

		-- Tab 2 is unselected and flashing: that is a real unread.
		flash2:Show()
		flash1:Show()
		C3:UpdateFlashes()
		check(tab2.__aetherDot:IsShown(),
			"an unselected tab with a live flash gets the unread dot")
		check(not tab1.__aetherDot:IsShown(),
			"and the SELECTED tab does not, however long its flash has been"
			.. " shown - an unread marker on the window you are reading is"
			.. " noise, and it is the one that was reported")

		-- Select the other one and the dots swap.
		_G.GeneralDockManager.selected = _G.ChatFrame2
		C3:UpdateFlashes()
		check(not tab2.__aetherDot:IsShown() and tab1.__aetherDot:IsShown(),
			"selecting a tab clears its dot and the other one keeps its own")
		_G.GeneralDockManager.selected = _G.ChatFrame1

		flash1:Hide(); flash2:Hide()
		C3:UpdateFlashes()
		check(not tab1.__aetherDot:IsShown()
			and not tab2.__aetherDot:IsShown(),
			"and with nothing flashing there are no dots at all")

		-- AND A WHISPER IS NOT A CHANNEL. The handoff reserves the gold dot for
		-- something addressed to you; Blizzard's flash says only that something
		-- arrived, so the window is asked what it is registered to carry.
		_G.ChatFrame2.__groups = { WHISPER = true }
		flash2:Show()
		C3:UpdateFlashes()
		local wr = { tab2.__aetherDot:GetVertexColor() }
		check(math.abs(wr[1] - A.Palette.c.semanticGold[1]) < 0.01,
			"a window you get whispered in takes the reserved gold")
		_G.ChatFrame2.__groups = nil
		C3:UpdateFlashes()
		local cr = { tab2.__aetherDot:GetVertexColor() }
		check(math.abs(cr[1] - A.Palette.c.accent[1]) < 0.01,
			"and an ordinary channel takes the accent")
		flash2:Hide()
		C3:UpdateFlashes()
	end

	C3:StyleTab(tab1)
	C3:StyleTab(tab2)
	check(tab1.__aetherMark:IsShown(),
		"the selected tab draws its mark")
	local mk = { tab1.__aetherMark:GetVertexColor() }
	check(math.abs(mk[1] - A.Palette.c.accent[1]) < 0.01,
		"in the skin's accent, which is the one colour the pattern uses")
	check(not tab2.__aetherMark:IsShown(),
		"and an unselected tab draws none")

	-- Selecting the other one moves it.
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame2)
	C3:StyleTab(tab1)
	C3:StyleTab(tab2)
	check(tab2.__aetherMark:IsShown() and not tab1.__aetherMark:IsShown(),
		"and it follows the selection")

	-- A client that hands back a number instead must still work.
	_G.GeneralDockManager.selected = 1
	check(C3.SelectedChatID() == 1, "a numeric selection is accepted too")

	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:StyleTab(tab1)
	C3:StyleTab(tab2)

	-- Called with a colon, `dock` is the module table: non-nil, no `.selected`,
	-- and every tab goes unselected with nothing raised to say why.
	check(C3:SelectedChatID() == 1,
		"and calling it as a method answers the same as calling it plainly")

	-- The client hands the answer to the hook and the old one declared
	-- `function(tab)` and dropped it on the floor.
	FCFTab_UpdateColors(tab2, true)
	check(tab2.__aetherMark:IsShown(),
		"a tab the client itself calls selected lights up, whatever the dock says")

	-- ...and that must not outlive the selection that produced it. This is the
	-- stale-flag case: two tabs marked at once.
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:SkinAllTabs()
	check(tab1.__aetherMark:IsShown() and not tab2.__aetherMark:IsShown(),
		"and moving the selection back leaves exactly one tab marked")

	-- An undocked window is not in the dock, so it can never be the dock's
	-- selection - but it is the window you are reading.
	--
	-- `nil`, NOT `false`. FCFDock_RemoveChatFrame writes `chatFrame.isDocked =
	-- nil` and FCFDock_AddChatFrame writes `1`; those are the only two
	-- assignments the client makes. The first version of this test set `false`,
	-- which made a module written as `isDocked == false` pass here while doing
	-- nothing whatsoever in game.
	_G.ChatFrame2.isDocked = nil
	C3:SkinAllTabs()
	check(tab2.__aetherMark:IsShown(),
		"an undocked window's tab is not dimmed forever for not being in the dock")

	-- ...and the whole undock sequence, in the client's order: colour the tab
	-- selected, then update the dock - which is our own SkinAllTabs wiping the
	-- flag that first step set. If the tier below it is wrong, the pill lights
	-- and then goes straight back out.
	FCFTab_UpdateColors(tab2, true)
	FCFDock_UpdateTabs(_G.GeneralDockManager)
	C3:SkinAllTabs()
	check(tab2.__aetherMark:IsShown(),
		"and it survives the dock update that follows the undock")

	-- A CLOSED window is undocked too, and stays in CHAT_FRAMES forever.
	_G.ChatFrame2:Hide()
	C3:SkinAllTabs()
	check(not tab2.__aetherMark:IsShown(),
		"but a closed window's tab is not lit just for being undocked")
	_G.ChatFrame2:Show()

	_G.ChatFrame2.isDocked = true
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:SkinAllTabs()

	-- A tab with no id must not match a dock with no selection: `nil == nil`.
	local saved = _G.GeneralDockManager.selected
	_G.GeneralDockManager.selected = nil
	-- pcall because the guard is load-bearing twice over: without it the answer
	-- is `nil == nil`, true, an unknown tab lights - and one line further down
	-- `"ChatFrame" .. nil` raises, which in game is an error thrown out of a
	-- Blizzard hook every time a tab is coloured.
	local ok, lit = pcall(C3.TabIsSelected, {})
	check(ok and lit == false,
		"a tab that cannot say which window it is does not light, and does not"
		.. " error either (" .. tostring(ok) .. ", " .. tostring(lit) .. ")")
	_G.GeneralDockManager.selected = saved

	check(C3:TabIsSelected(tab1) == C3.TabIsSelected(tab1),
		"and TabIsSelected answers the same called as a method")
end

print("== chat: the pill is a pill, and it clears the divider ==")
do
	local C3 = A:GetModule("chat")
	local tab1 = _G.ChatFrame1Tab
	C3:StyleTab(tab1)

	-- THE MARK IS NOT THE TAB. A docked ChatFrameTab is 32 tall against a 26
	-- dock, so its own bottom edge is three pixels BELOW the divider the mark
	-- is supposed to sit on - and a mark measured from the tab would be down
	-- there rather than on the line.
	check(tab1.__aetherMark:GetHeight() == 2,
		"the mark is two pixels of it, whatever the tab is (" ..
		tab1.__aetherMark:GetHeight() .. ")")

	-- ...and it must not START inheriting the tab. A taller tab is the thing
	-- that would reveal a corner anchor, so give it one.
	local was = tab1:GetHeight()
	tab1:SetHeight(64)
	C3:StyleTab(tab1)
	local _, mrel = tab1.__aetherMark:GetPoint(1)
	check(mrel == _G.ChatFrame1TabText and tab1.__aetherMark:GetHeight() == 2,
		"and doubling the tab's height moves neither its width nor its"
		.. " thickness, because neither comes from the tab")
	tab1:SetHeight(was)
	C3:StyleTab(tab1)
	-- THE MARK SITS ON THE DIVIDER, which is the rail's own line - computed
	-- from what the module actually anchored rather than from numbers retyped
	-- here. The pill this replaced had to CLEAR the divider by a couple of
	-- pixels; the mark is the opposite of that. It belongs on it.
	local _, drel, drelP, _, dy = tab1.__aetherMark:GetPoint(3)
	check(drel == C3.panel.divider and drelP == "BOTTOM" and dy == 0,
		"exactly on the line rather than clear of it (" .. tostring(drelP) ..
		" y=" .. tostring(dy) .. ")")
end

print("== chat: clicking a tab does not deform the pill ==")
do
	local C3 = A:GetModule("chat")
	local tab1, tab2 = _G.ChatFrame1Tab, _G.ChatFrame2Tab
	local fs2 = _G.ChatFrame2TabText

	-- Everything above this point measured a tab the module had just styled.
	-- The bug only appears once BLIZZARD has had its turn: FCF_SelectDockFrame
	-- rebuilds the tabs and FCF_DockUpdate rebuilds them again, so
	-- PanelTemplates_TabResize runs twice per click, rewriting the tab's width
	-- and - for every tab but ChatFrame1's - pinning the label to a hard
	-- `dynTabSize - 32`.
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame2)   -- the click
	FCFDock_UpdateTabs(_G.GeneralDockManager)                    -- ...and again
	C3:SkinAllTabs()

	-- AUTO, which for a font string is "as wide as the word in it" rather than
	-- nought - the client pinned it to a hard dynTabSize - 32.
	check(fs2:GetWidth() == fs2:GetStringWidth(),
		"the label is handed back its auto width after the client pins it ("
		.. fs2:GetWidth() .. ")")
	check(fs2:GetHeight() == 0,
		"and its auto height, so its rect is the size of the word in it")

	local want = fs2:GetStringWidth() + 20
	check(math.abs(tab2:GetWidth() - want) < 0.01,
		"the tab is our width, not the client's 60 (" .. tab2:GetWidth() .. ")")

	-- The invariant that makes a drifting mark impossible rather than merely
	-- unlikely: it is anchored to the LABEL for its width. Its centre is then
	-- the word's centre by construction, whatever the tab is doing - and the
	-- tab is doing a lot, because PanelTemplates_TabResize rewrites its width
	-- twice on every click.
	local p1, rel1 = tab2.__aetherMark:GetPoint(1)
	local p2, rel2 = tab2.__aetherMark:GetPoint(2)
	check(rel1 == fs2 and rel2 == fs2,
		"the mark hangs off the label, not off the tab (" .. tostring(p1)
		.. "/" .. tostring(p2) .. ")")

	-- Three points, not six: re-anchoring every pass without clearing first
	-- would pile them up until the frame is over-defined. Two for the width,
	-- one for the line it sits on.
	local n = 0
	while tab2.__aetherMark:GetPoint(n + 1) do n = n + 1 end
	check(n == 3, "and exactly three anchor points survive repeated styling ("
		.. n .. ")")

	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:SkinAllTabs()
	check(_G.ChatFrame1TabText:GetWidth()
			== _G.ChatFrame1TabText:GetStringWidth()
		and tab1.__aetherMark:GetHeight() == 2,
		"and clicking back leaves the first tab as it started")
end

print("== chat: the tab label is not smudged ==")
do
	local C3 = A:GetModule("chat")
	local tab1, tab2 = _G.ChatFrame1Tab, _G.ChatFrame2Tab
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:SkinAllTabs()

	local sel, unsel = _G.ChatFrame1TabText, _G.ChatFrame2TabText

	-- NO SHADOW ON ANY OF THEM. GameFontNormalSmall inherits
	-- SystemFont_Shadow_Small, which carries a hard black shadow, and SetFont
	-- does not clear it. It used to be cleared on the SELECTED tab only,
	-- because that was the one with a pale fill behind it to be smudged
	-- against - and there is no fill behind any of them now. A black halo
	-- under a word on glass reads as a smudge rather than as depth.
	local _, _, _, sa = sel:GetShadowColor()
	local _, _, _, ua = unsel:GetShadowColor()
	check(sa == 0 and ua == 0,
		"neither the tab you are reading nor the ones you are not casts a"
		.. " shadow (" .. tostring(sa) .. " / " .. tostring(ua) .. ")")

	-- And the ink is opaque. `c.glass` is the panel FILL and carries alpha
	-- 0.55; passing it through as a text colour drew the label fainter than
	-- the black shadow behind it, which is what made it look blurred.
	local _, _, _, ta = sel:GetTextColor()
	check(ta == 1, "and the tab you are reading is fully opaque, not the panel"
		.. " fill's alpha (" .. tostring(ta) .. ")")

	-- Reselecting has to leave both alone, or the treatment is one-way.
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame2)
	C3:SkinAllTabs()
	local _, _, _, a1 = _G.ChatFrame1TabText:GetShadowColor()
	local _, _, _, a2 = _G.ChatFrame2TabText:GetShadowColor()
	check(a1 == 0 and a2 == 0,
		"and moving the selection does not hand one of them a shadow back")

	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:SkinAllTabs()
end

print("== chat: the idle composer does NOT follow the selection ==")
do
	local C3 = A:GetModule("chat")
	local eb1, eb2 = _G.ChatFrame1EditBox, _G.ChatFrame2EditBox

	-- This block asserted the opposite for one draft, which is how it earns its
	-- comment. The reasoning that produced it was: `selected == id or f ==
	-- ChatFrame1` inside a loop over CHAT_FRAMES can never let the selection
	-- decide, because ChatFrame1 is first in that list - therefore promote the
	-- selection. Correct diagnosis, wrong cure: the selection term was dead AND
	-- wrong, and making it live made the composer lie.
	--
	-- Era's OPENCHAT binding is `ChatFrameUtil.OpenChat("")` with no frame, and
	-- ChooseBoxForSend's first branch returns DEFAULT_CHAT_FRAME.editBox
	-- whenever `chatStyle == "classic"`, without looking at the dock at all. So
	-- pressing Enter with the guild window selected still types into SAY, and a
	-- capsule previewing the selection would name a channel you cannot reach.
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame2)
	C3:UpdateComposers()
	if eb1 and eb1._pill and eb2 and eb2._pill then
		check(eb1._pill:IsShown() and not eb2._pill:IsShown(),
			"with nothing focused the composer previews the box Enter opens,"
			.. " whatever the dock has selected")
	end

	-- ...but a box that is genuinely open wins, and that is the whole of the
	-- `chatStyle = "im"` case: there the client hides the old box and shows the
	-- new one, so "which box is shown" already answers "which one moves".
	if eb1 and eb1._pill and eb2 and eb2._pill then
		eb2:Show()
		C3:UpdateComposers()
		check(eb2._pill:IsShown() and not eb1._pill:IsShown(),
			"and an open box outranks it, which is how the im chat style moves")
		eb2:Hide()
	end

	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:UpdateComposers()
	if eb1 and eb1._pill then
		check(eb1._pill:IsShown(), "back to ChatFrame1's once it closes again")
	end
end

print("== chat: the tab type is smaller than the messages ==")
do
	local C3 = A:GetModule("chat")
	local tab = A.Media.style.chatTab[2]

	-- Two worthless versions of this check were written before this one, and
	-- both are worth naming so a third is not.
	--
	--   `tab < body` - passed at the old 11 against chatText's 12, so it could
	--   not see the very change it was added for.
	--
	--   `body - tab >= 2` - discriminates, but against a number that never
	--   reaches the screen. `Media.style.chatText[2]` supplies the message
	--   FACE only: Chat:SetFrameFont takes the SIZE from Chat:FontSize, which
	--   is Blizzard's own window size plus the `fontDelta` setting. On a stock
	--   profile that is 14 - 5 = 9, not 12.
	--
	-- So the messages are measured where they are actually drawn.
	local body = C3:FontSize(_G.ChatFrame1)
	check(body ~= A.Media.style.chatText[2],
		"the message size does not come from the chatText role - it is"
		.. " Blizzard's size plus fontDelta (" .. body .. ", not "
		.. A.Media.style.chatText[2] .. "), so never compare against that")

	-- The agreed value, pinned. There is nothing internal that distinguishes 10
	-- from 11 - it is a judgement about how loud the navigation should read -
	-- so the only honest guard is the number itself, checked where it lands.
	local fs = _G.ChatFrame1TabText
	-- `fs and fs:GetFont()` would truncate to one value and hand `drawn` a nil.
	local drawn
	if fs then drawn = select(2, fs:GetFont()) end
	check(drawn == 10,
		"and the tab label is drawn at the agreed 10 (" .. tostring(drawn) .. ")")
	check(drawn == tab,
		"which is the role's own number, so Media.lua still governs it")

	-- ...but the composer's channel capsule does not inherit it: the code you
	-- type beside reads at the size you type at.
	local eb = _G.ChatFrame1EditBox
	if eb and eb._tagText then
		local _, size = eb._tagText:GetFont()
		check(size and size ~= tab,
			"while the composer capsule is sized from the typing font, not from"
			.. " the tab role (" .. tostring(size) .. ")")
	end
end

-- ---------------------------------------------------------------------------
-- tooltips
--
-- This module reskins frames it does not own, alongside other addons doing the
-- same thing to the same frames. So most of what is worth asserting is not
-- "does it look right" - it is "does it still leave room for everybody else".
-- ---------------------------------------------------------------------------

print("== tooltips: the card, and what it is drawn instead of ==")
do
	local T = A:GetModule("tooltips")
	check(T and T.enabled, "tooltips module enabled")
	check(T.skinned[GameTooltip], "GameTooltip adopted")
	check(GameTooltip.aetherCard ~= nil, "and given a glass card")
	check(#GameTooltip.aetherCard._fill == 9, "which is a 9-slice panel, not a pill")

	-- The stone border has to be OFF, and it has to stay off. Classic's
	-- SharedTooltip_SetBackdropStyle re-applies the default NineSlice layout on
	-- every OnHide and on every item tooltip, so suppressing it once at login
	-- lasts until the first thing you hover.
	check(not GameTooltip.NineSlice:IsShown(), "Blizzard's NineSlice is suppressed")
	SharedTooltip_SetBackdropStyle(GameTooltip)
	check(not GameTooltip.NineSlice:IsShown(),
		"and is suppressed AGAIN after SharedTooltip_SetBackdropStyle puts it back")

	-- Every other tooltip in the family, so a linked item or a shift-compare does
	-- not open a stone box next to a glass one.
	for _, n in ipairs({ "ItemRefTooltip", "ShoppingTooltip1", "ShoppingTooltip2",
		"EmbeddedItemTooltip", "WorldMapTooltip" }) do
		check(_G[n] and T.skinned[_G[n]], n .. " adopted too")
	end
end

print("== media: every role reaches the real face ==")
do
	-- THE WHOLE INTERFACE went to Friz Quadrata once, and it got there through
	-- this one function. Media:SetFont is the chokepoint every string in the
	-- addon passes through, so a gate in front of it that answers wrong once
	-- answers wrong for everything - which is exactly what happened when the
	-- fallback probed each face through a scratch FontString and CACHED the
	-- verdict. The client said no, the cache remembered it, and the only text
	-- left in Outfit was chat's, because Modules/Chat.lua sets the message font
	-- directly and never comes through here.
	--
	-- So: every role, not a sample. A gate cannot fail for one and not the rest.
	local bad = {}
	for name, style in pairs(A.Media.style) do
		local fs = UIParent:CreateFontString(nil, "ARTWORK")
		A.Media:SetFont(fs, name)
		local got, size = fs:GetFont()
		local want = A.Media.font[style[1]]
		if got ~= want then
			bad[#bad + 1] = name .. " -> " .. tostring(got)
		elseif size ~= math.floor(style[2] + 0.5) then
			bad[#bad + 1] = name .. " @ " .. tostring(size)
		end
	end
	check(#bad == 0,
		"every role in Media.style lands on its own Outfit weight at its own"
		.. " size (" .. (#bad > 0 and table.concat(bad, ", ") or "all of them")
		.. ")")

	-- ...and it does that without reading a return value from anything. Both
	-- SetFont mocks answer nothing on purpose; if this passes, nothing in the
	-- path depends on a client being generous enough to reply.
	do
		local fs = UIParent:CreateFontString(nil, "ARTWORK")
		check(fs:SetFont(A.Media.font.regular, 12, "") == nil,
			"the mock's SetFont answers nothing, as the worst plausible client"
			.. " does")
		A.Media:SetFont(fs, "chatText")
		check(select(1, fs:GetFont()) == A.Media.font[A.Media.style.chatText[1]],
			"and the face still lands - verified by READ-BACK rather than by"
			.. " whatever the call felt like returning")
	end

	-- The fallback still exists for the thing it is for: one of OUR OWN new
	-- FontStrings whose face will not load has no font at all, and no font
	-- draws as nothing.
	do
		_G.__badFonts = { [A.Media.font.light] = true }
		local fs = UIParent:CreateFontString(nil, "ARTWORK")
		A.Media:SetFont(fs, "ttBody")
		check(select(1, fs:GetFont()) == [[Fonts\FRIZQT__.TTF]],
			"a face that will not load degrades to the game font rather than to"
			.. " invisible text (got " .. tostring(select(1, fs:GetFont())) .. ")")

		-- A font OBJECT that refuses keeps the client's own face, which IS the
		-- fallback. Nothing to correct, and nothing to have an opinion about.
		local obj = _G.GameTooltipText
		local before = select(1, obj:GetFont())
		A.Media:SetFont(obj, "ttBody")
		check(select(1, obj:GetFont()) == before,
			"and a font object that refuses one keeps the face it had - the"
			.. " client's, which is what the fallback would have set anyway")
		_G.__badFonts = nil
	end
end

print("== tooltips: drawn over everything, on every show ==")
do
	-- A tooltip is a shared object anything can reparent or restrata, and this
	-- addon does exactly that - the console takes it out of UIParent for a
	-- flight so it can be read over a hidden interface. Anything that leaves it
	-- somewhere else leaves it drawing UNDER a panel, which is where a quest
	-- reward's tooltip was found: half of it behind the quest window.
	--
	-- W.Tooltip asserts this, but only for the tooltips WE raise. A quest
	-- reward, a merchant's wares and a bag slot are all raised by the client.
	local tip = _G.GameTooltip
	tip:SetFrameStrata("MEDIUM")
	tip:Hide()
	tip:Show()
	check(tip:GetFrameStrata() == "TOOLTIP",
		"showing a tooltip puts it back at the tooltip strata, whoever raised"
		.. " it (" .. tostring(tip:GetFrameStrata()) .. ")")
	tip:Hide()
end

print("== tooltips: the typeface actually reaches the client's font objects ==")
do
	local T = A:GetModule("tooltips")

	-- The three font objects are the highest-leverage thing the module touches:
	-- every line in every tooltip inherits one of them, including lines other
	-- addons add later. They are also the ONLY things the addon styles that are
	-- not FontStrings, and that difference is what broke them.
	--
	-- FontString:SetFont answers isValid. Font:SetFont answers NOTHING. Media
	-- used to read the return of the call it had just made and fall back to the
	-- game font when it was falsy, so every font object landed on
	-- FRIZQT__.TTF - at our sizes, which is why it read as "huge Friz" rather
	-- than as a font that had failed to load. Every FontString was fine
	-- throughout, so nothing else on screen looked wrong.
	for _, n in ipairs({ "GameTooltipHeaderText", "GameTooltipText",
		"GameTooltipTextSmall" }) do
		local obj = _G[n]
		check(obj:SetFont([[Interface\X.ttf]], 12, "") == nil,
			n .. " answers nothing from SetFont, as the client's does - a mock"
			.. " kinder than the client tests the wrong code")
	end

	T:ApplyFonts()

	local wanted = {
		GameTooltipHeaderText = A.Media.style.ttName,
		GameTooltipText       = A.Media.style.ttBody,
		GameTooltipTextSmall  = A.Media.style.ttSmall,
	}
	for n, style in pairs(wanted) do
		local path, size = _G[n]:GetFont()
		check(path == A.Media.font[style[1]],
			n .. " is left on Outfit " .. style[1] .. " rather than on the"
			.. " client's own face (got " .. tostring(path) .. ")")
		check(size == style[2],
			"at the role's size, " .. style[2] .. " (got " .. tostring(size) .. ")")
	end

	-- ...and the fallback still exists for the thing it was written for: an
	-- install with its Media folder missing.
	do
		local saved = A.Media.font.light
		A.Media.font.light = [[Interface\AddOns\AetherUI\Media\Fonts\Nope.ttf]]
		_G.__badFonts = { [A.Media.font.light] = true }
		T:ApplyFonts()
		local path = GameTooltipText:GetFont()
		check(path ~= A.Media.font.light,
			"a face the client cannot load falls back rather than leaving the"
			.. " tooltip blank (got " .. tostring(path) .. ")")
		_G.__badFonts = nil
		A.Media.font.light = saved
		T:ApplyFonts()
	end

	-- Turning the option off puts the CLIENT's face back, not our idea of it.
	local before = select(1, GameTooltipHeaderText:GetFont())
	A.Config:Module("tooltips").restyleFonts = false
	T:ApplyFonts()
	check(GameTooltipHeaderText:GetFont() == [[Fonts\FRIZQT__.TTF]],
		"unticking the option restores the face captured BEFORE we overwrote it"
		.. " (got " .. tostring(GameTooltipHeaderText:GetFont()) .. ")")
	A.Config:Module("tooltips").restyleFonts = true
	T:ApplyFonts()
	check(GameTooltipHeaderText:GetFont() == before, "and ticking it goes back")
end

print("== tooltips: drawn at the deck's scale, and kept there ==")
do
	local T = A:GetModule("tooltips")
	local was = A.db.profile.scale

	A.db.profile.scale = 0.71
	T:OnConfigChanged()
	check(math.abs(GameTooltip:GetScale() - 0.71) < 0.001,
		"the tooltip is drawn at profile.scale like every other module - the"
		.. " deck's 15pt title only lands where the deck put it if the surface"
		.. " under it is the same size as the rest of the HUD (got "
		.. tostring(GameTooltip:GetScale()) .. ")")

	-- ...and SOMEBODY ELSE writes to this.
	--
	-- Leatrix Plus's "Enhance tooltip" sets GameTooltip:SetScale from its own
	-- slider at startup, across the whole family - Leatrix_Plus.lua:10309. Its
	-- default is 100%, so on a UI at 0.71 it lands after us and the tooltip
	-- comes out forty per cent bigger than everything around it. That is not a
	-- preference, it is two addons disagreeing in public, and the one drawing
	-- the card should be the one that answers.
	GameTooltip:Hide()
	GameTooltip:SetScale(1.0)
	check(math.abs(GameTooltip:GetScale() - 1.0) < 0.001,
		"another addon really can take it away")

	GameTooltip:Show()
	check(math.abs(GameTooltip:GetScale() - 0.71) < 0.001,
		"and showing the tooltip takes it back - same rule as StripArt, and the"
		.. " same reason: setting either one once at login lasts until the first"
		.. " thing you hover (got " .. tostring(GameTooltip:GetScale()) .. ")")

	-- The per-module multiplier still rides on top, because a tooltip is the
	-- one surface people most often want a size apart from the HUD.
	-- Hide first: OnShow only fires on a hidden->shown transition, here and in
	-- the client. A test that calls Show on something already up is asserting
	-- against a hook that never ran.
	A.Config:Module("tooltips").scale = 1.2
	GameTooltip:Hide()
	GameTooltip:SetScale(1.0)
	GameTooltip:Show()
	check(math.abs(GameTooltip:GetScale() - 0.71 * 1.2) < 0.001,
		"profile scale times the tooltip's own (got "
		.. tostring(GameTooltip:GetScale()) .. ", want "
		.. tostring(0.71 * 1.2) .. ")")
	A.Config:Module("tooltips").scale = 1.0

	-- No write when it is already right. SetScale re-lays out everything
	-- anchored to the frame and this runs on every show.
	do
		GameTooltip:Hide(); GameTooltip:Show()
		local n = GameTooltip.__scaleWrites or 0
		GameTooltip:Hide(); GameTooltip:Show()
		GameTooltip:Hide(); GameTooltip:Show()
		check((GameTooltip.__scaleWrites or 0) == n,
			"and a tooltip already at the right scale is not written to again -"
			.. " this runs on every show, and SetScale re-lays out everything"
			.. " anchored to the frame")
	end

	A.db.profile.scale = was
	T:OnConfigChanged()
end

print("== tooltips: the card follows lines added AFTER the tooltip is up ==")
do
	-- Pawn hooksecurefuncs about thirty GameTooltip:Set*Item methods and adds its
	-- lines once the tooltip is already on screen; VendorPricePlus and every
	-- LibExtraTip consumer do the same. A card measured at OnShow is the wrong
	-- height for all of them, which is why the module sizes from OnSizeChanged.
	GameTooltip:SetItemByID(1234, "Staff of the Blessed Seer", 3)
	GameTooltip:Show()

	local card = GameTooltip.aetherCard
	card:ClearAllPoints()
	check(#card.__points == 0, "card points cleared, as a sentinel")

	GameTooltip:AddLine("|cff20ff20Pawn: 41.2 DPS|r")   -- what Pawn does
	check(#card.__points == 2,
		"adding a line after Show re-lays the card (the Pawn case)")
	local p1, rel1 = card:GetPoint(1)
	check(p1 == "TOPLEFT" and rel1 == GameTooltip,
		"and it is re-anchored to the tooltip, not to whatever it last held")
end

print("== tooltips: the level strip keeps what other addons appended ==")
do
	local T = A:GetModule("tooltips")

	-- MobInfo2 appends to the same line the badge takes the level out of:
	--     GameTooltipTextLeft2:SetText( txt.." "..mobData.class )   MI2_Tooltip.lua:381
	-- Our hook is already installed, so registering this one AFTER means our
	-- handler runs first and MobInfo2's runs second - one of the two load orders.
	-- Gated on a flag rather than installed and forgotten, for the same reason
	-- the addon gates its own hook bodies: a HookScript hook can never be taken
	-- off again. Left running, this one goes on appending to line 2 for the rest
	-- of the suite and quietly becomes part of every later assertion's fixture.
	local appended = false
	_G.__mi2Active = true
	GameTooltip:HookScript("OnTooltipSetUnit", function(self)
		if not _G.__mi2Active then return end
		local fs = _G.GameTooltipTextLeft2
		if fs and fs:GetText() then
			fs:SetText(fs:GetText() .. " MI2:8-11 dmg")
			appended = true
		end
	end)

	GameTooltip:SetUnit("mouseover")
	check(appended, "the simulated MobInfo2 hook ran at all")

	local line2 = _G.GameTooltipTextLeft2:GetText()
	check(not line2:find("Level"),
		"the level token is out of the line (" .. tostring(line2) .. ")")
	check(line2:find("Humanoid", 1, true),
		"the creature type survived")
	check(line2:find("MI2:8%-11 dmg"),
		"and so did everything MobInfo2 appended - THE point of the whole design")

	-- The other load order, done honestly rather than argued: a fresh tooltip
	-- that the simulated MobInfo2 hooked BEFORE we did.
	local other = _G.__makeTooltip("HarnessOrderTooltip")
	other:HookScript("OnTooltipSetUnit", function(self)
		local fs = _G.HarnessOrderTooltipTextLeft2
		if fs and fs:GetText() then fs:SetText(fs:GetText() .. " MI2-first") end
	end)
	T:Register(other)
	other:SetUnit("mouseover")
	local o2 = _G.HarnessOrderTooltipTextLeft2:GetText()
	check(o2 and not o2:find("Level") and o2:find("MI2%-first"),
		"and it works with the hooks installed the other way round too")

	_G.__mi2Active = nil
end

print("== tooltips: the strip is idempotent, and declines what it cannot parse ==")
do
	local T = A:GetModule("tooltips")

	-- The client re-runs SetUnit about five times a second for a mouseover, so a
	-- strip that ate one more word per pass would look fine for a frame.
	GameTooltip:SetUnit("mouseover")
	local first = _G.GameTooltipTextLeft2:GetText()
	GameTooltip:SetUnit("mouseover")
	GameTooltip:SetUnit("mouseover")
	check(_G.GameTooltipTextLeft2:GetText() == first,
		"three SetUnit passes produce the same line (" .. tostring(first) .. ")")

	-- A line that is not a level line is not a line we touch. This is the
	-- graceful-degradation path: wrong locale, or another addon rewrote it first.
	check(T.ParseLevelLine("Binds when equipped", false) == nil,
		"a non-level line does not parse")
	check(T.ParseLevelLine(nil, false) == nil, "and neither does nil")

	local lvl, rest = T.ParseLevelLine("Level 20 Elite Humanoid trailing junk", true)
	check(lvl == "20", "a level parses out of a full line")
	check(rest == "Humanoid trailing junk",
		"with the classification word dropped and the trailing text kept ("
		.. tostring(rest) .. ")")

	local lvl2, rest2 = T.ParseLevelLine("Level 20 Elite Humanoid", false)
	check(lvl2 == "20" and rest2 == "Elite Humanoid",
		"and the classification word is KEPT when no chip is going to say it")

	local skull = T.ParseLevelLine("Level ?? Boss", false)
	check(skull == "??", "the skull parses as a level, not as a failure")

	-- The pattern comes from the client's own string, not from an English
	-- literal, or every non-enUS player loses the badge.
	check(T.LevelPattern():find("Level"),
		"and the pattern is built from UNIT_LEVEL_TEMPLATE")
end

print("== tooltips: the elite chip, the badge, and the gutter that makes room ==")
do
	GameTooltip:SetUnit("mouseover")     -- Gazrog, elite

	local badge, chip = GameTooltip.aetherBadge, GameTooltip.aetherChip
	check(badge and badge:IsShown(), "the level badge is drawn")
	check(badge.label:GetText() == "20", "carrying the unit's level")
	check(chip and chip:IsShown(), "and an elite chip beside the name")

	-- The badge gets its room from the CARD growing left, not from re-anchoring
	-- the tooltip's own FontStrings - which would fight the C layout code and
	-- break LibExtraTip's right-column arithmetic (LibExtraTip.lua:1222).
	check(GameTooltip.aetherGutter and GameTooltip.aetherGutter > 0,
		"the card carries a left gutter for it (" .. tostring(GameTooltip.aetherGutter) .. ")")
	local _, _, _, x = GameTooltip.aetherCard:GetPoint(1)
	check(x and x < 0,
		"so the card's TOPLEFT sits left of the tooltip's (" .. tostring(x) .. ")")

	local anchorTo = select(2, badge:GetPoint(1))
	check(anchorTo == _G.GameTooltipTextLeft1,
		"and the badge hangs off line 1, so it tracks the name's own baseline")

	-- A plain mob gets neither, and the gutter goes back to nothing.
	_G.__units.mouseover.classification = "normal"
	GameTooltip:SetUnit("mouseover")
	check(not GameTooltip.aetherChip:IsShown(), "a normal mob gets no chip")
	_G.__units.mouseover.classification = "elite"
end

print("== tooltips: the health hairline ==")
do
	local T = A:GetModule("tooltips")
	local bar = _G.GameTooltipStatusBar
	check(bar and bar.aetherStyled, "the status bar is restyled in place")
	check(bar and bar.lockColor,
		"with lockColor set, or HealthBar_OnValueChanged forces it back to flat green")
	check(bar and bar:GetHeight() == 7, "at the deck's 7px")

	-- Guarded rather than indexed straight through. A regression that loses the
	-- readout entirely should show up here as a failed check naming what is
	-- missing, not as a nil-index that takes the rest of the suite with it.
	check(bar and bar.aetherValue ~= nil, "and a readout under it")
	if bar and bar.aetherValue then
		local function readout() return bar.aetherValue:GetText() or "<nil>" end

		GameTooltip:SetUnit("mouseover")
		check(readout() == "4,820  /  4,820",
			"which is grouped (" .. readout() .. ")")

		-- Driven from OnValueChanged, which is the only hook there is: nothing in
		-- Lua shows or fills this bar, the C tooltip code does it.
		_G.__units.mouseover.hp = 2410
		bar:SetValue(2410)
		check(readout() == "2,410  /  4,820", "a value change alone updates it")
		_G.__units.mouseover.hp = 4820

		local conf = A.Config:Module("tooltips")
		conf.healthValues = false
		T:UpdateStatusBar(bar)
		check(readout() == "", "and the readout is separable from the bar")
		conf.healthValues = true
	end
end

print("== tooltips: a player is their class colour ==")
do
	local T = A:GetModule("tooltips")

	-- The report: everybody appeared in "mage blue". They were - one blue for
	-- every friendly player is the deck's own treatment, and it was the default
	-- here while the unit frames class-coloured by default. Same player, two
	-- answers, a tooltip's width apart. That reads as class colours having been
	-- LOST rather than as a preference being expressed.
	check(A.Config:Module("tooltips").classColorNames ~= false,
		"tooltips class-colour by default, like the unit frames")

	-- The tooltip's own unit, not the target - see the note on __units.mouseover.
	local mo = _G.__units.mouseover
	local was = { mo.isPlayer, mo.class, mo.classToken, mo.reaction, mo.creature }
	mo.isPlayer, mo.class, mo.classToken = true, "Rogue", "ROGUE"
	mo.reaction, mo.creature = 5, nil
	GameTooltip:SetUnit("mouseover")

	local r, g, b = _G.GameTooltipTextLeft1:GetTextColor()
	-- Rogue yellow, chosen because it is nowhere near the deck's blue: a class
	-- colour that happens to look like the thing it replaced proves nothing.
	local want = RAID_CLASS_COLORS.ROGUE
	check(math.abs(r - want.r) < 0.01 and math.abs(g - want.g) < 0.01
		and math.abs(b - want.b) < 0.01,
		"a friendly player's name is their class colour (got "
		.. string.format("%.2f %.2f %.2f", r, g, b) .. ", want "
		.. string.format("%.2f %.2f %.2f", want.r, want.g, want.b) .. ")")

	-- ...and CUSTOM_CLASS_COLORS wins, which is what a colour-blind or
	-- ClassColors addon publishes. Chat already honoured it and the other two
	-- places did not, so one addon got recoloured names in chat and Blizzard's
	-- palette everywhere else.
	_G.CUSTOM_CLASS_COLORS = { ROGUE = { r = 0.1, g = 0.9, b = 0.2 } }
	GameTooltip:SetUnit("mouseover")
	local r2, g2, b2 = _G.GameTooltipTextLeft1:GetTextColor()
	check(math.abs(r2 - 0.1) < 0.01 and math.abs(g2 - 0.9) < 0.01,
		"an addon's own class colours are used ahead of Blizzard's (got "
		.. string.format("%.2f %.2f %.2f", r2, g2, b2) .. ")")
	_G.CUSTOM_CLASS_COLORS = nil

	-- The deck's treatment is still one switch away.
	A.Config:Module("tooltips").classColorNames = false
	GameTooltip:SetUnit("mouseover")
	local r3 = select(1, _G.GameTooltipTextLeft1:GetTextColor())
	check(math.abs(r3 - A.Palette.c.ttFriendly[1]) < 0.01,
		"and off gives the deck's one blue for every friendly player")
	A.Config:Module("tooltips").classColorNames = true

	-- An NPC that DOES have a class token, which is the realistic case: the
	-- client happily answers UnitClass for a great many of them. Class colouring
	-- has to be gated on being a PLAYER, not on there being a class to use -
	-- and an NPC left with a class token is the only way to tell those apart.
	mo.isPlayer = false
	mo.class, mo.classToken = "Rogue", "ROGUE"
	mo.creature = "Humanoid"
	GameTooltip:SetUnit("mouseover")
	local r4 = select(1, _G.GameTooltipTextLeft1:GetTextColor())
	check(math.abs(r4 - A.Palette.c.ttFriendlyNPC[1]) < 0.01,
		"an NPC keeps the friendly-NPC green - 'that is a person' is different"
		.. " information from 'that is a quest giver'")

	mo.isPlayer, mo.class, mo.classToken = was[1], was[2], was[3]
	mo.reaction, mo.creature = was[4], was[5]
end

print("== tooltips: quality drives the rim, not just the title ==")
do
	GameTooltip:SetItemByID(1234, "Staff of the Blessed Seer", 3)   -- rare
	local card = GameTooltip.aetherCard
	local rare = A.Palette.c.itemQuality[3].edge
	local e = card._edgeColor
	check(e and math.abs(e[1] - rare[1]) < 0.001 and math.abs(e[3] - rare[3]) < 0.001,
		"a rare item tints the card's rim")
	check(card._rim ~= nil and card._rim[1]:IsShown(),
		"and rare and above get an outer bloom")

	local ink = { _G.GameTooltipTextLeft1:GetTextColor() }
	check(math.abs(ink[1] - rare[1]) < 0.001, "the title takes the quality colour")

	GameTooltip:SetItemByID(99, "Linen Cloth", 1)                    -- common
	check(GameTooltip.aetherCard._rim == nil
		or not GameTooltip.aetherCard._rim[1]:IsShown(),
		"a common item gets no bloom - that is what makes a purple readable")

	-- The title's INK is a DIFFERENT token from the rim, and the two share an RGB
	-- to the digit - so nothing about the colour can tell them apart and a check
	-- on r,g,b passes whichever one was used. They part on ALPHA: a rim on common
	-- is a hint at 0.30, the title is type at 0.90. Reusing the rim as ink put a
	-- barely-there item name at the top of the card, and it was the alpha that
	-- did it, not the hue.
	--
	-- This was Daylight's check, where the rims were dark and the title read
	-- near-black on a pale wash. The family that replaced it has no pale skin, so
	-- the rims are semantic and identical throughout, and alpha is now the only
	-- thing left that can catch the same mistake.
	local ink1 = { _G.GameTooltipTextLeft1:GetTextColor() }
	local rim = A.Palette.c.itemQuality[1].edge
	local titleInk = A.Palette.c.ttQuality[1]
	check(math.abs(rim[1] - titleInk[1]) < 0.001,
		"the common rim and the common title ink share an RGB, so hue can prove"
		.. " nothing here")
	check(math.abs((rim[4] or 1) - (titleInk[4] or 1)) > 0.2,
		"and part on alpha - a rim is a hint, a title is type ("
		.. string.format("%.2f vs %.2f", rim[4] or 1, titleInk[4] or 1) .. ")")
	check(math.abs((ink1[4] or 1) - (titleInk[4] or 1)) < 0.001,
		"so the title is drawn at the TITLE's alpha, not the rim's (" ..
		string.format("%.2f", ink1[4] or 1) .. ")")
	local lum = 0.299 * ink1[1] + 0.587 * ink1[2] + 0.114 * ink1[3]
	check(lum > 0.7, "and it stays light type, like every other string on the"
		.. " card (" .. string.format("%.2f", lum) .. ")")
end

print("== tooltips: lore gold does not paint over another addon's line ==")
do
	GameTooltip:SetSpell(5504, "Conjure Water", "Conjures 14 bottles of fresh water.")
	local gold = A.Palette.c.ttLore
	local body = { _G.GameTooltipTextLeft2:GetTextColor() }
	check(math.abs(body[1] - gold[1]) < 0.001,
		"the client's own body copy goes lore gold")

	-- Pawn's score line is green on purpose. Recolouring it would be exactly the
	-- kind of thing this module exists not to do.
	GameTooltip:AddLine("Pawn: 41.2", 0.12, 1.0, 0.0)
	A:GetModule("tooltips"):OnSpell(GameTooltip)
	local pawn = { _G.GameTooltipTextLeft3:GetTextColor() }
	check(math.abs(pawn[2] - 1.0) < 0.001 and pawn[1] < 0.5,
		"but a line another addon deliberately coloured keeps its colour")
end

print("== tooltips: anchoring is scoped ==")
do
	local T = A:GetModule("tooltips")
	check(T.anchor ~= nil, "there is a mover anchor for unit tooltips")
	local entry = A.Movers.registry and A.Movers.registry.tooltip
	check(entry and entry.frame == T.anchor,
		"and Movers is actually holding it - `x ~= nil or true` is a check that"
		.. " cannot fail, which is not a check")

	GameTooltip_SetDefaultAnchor(GameTooltip, UIParent)
	local _, rel = GameTooltip:GetPoint(1)
	check(rel == T.anchor,
		"a default-anchored tooltip lands on the mover frame, not Blizzard's corner")

	-- The scoping rule. A bag slot that called SetOwner on itself keeps the
	-- position it asked for; only default/world tooltips get dragged to the
	-- cursor. Widening this is the fastest way to make every other addon's
	-- tooltips feel broken.
	GameTooltip.default = nil
	GameTooltip:SetOwner(_G.ContainerFrame1 or CreateFrame("Frame", nil, UIParent), "ANCHOR_RIGHT")
	check(not T.WantsCursor(GameTooltip),
		"a tooltip with its own owner is NOT dragged to the cursor")

	GameTooltip.default = 1
	check(T.WantsCursor(GameTooltip), "a default-anchored one is")

	local conf = A.Config:Module("tooltips")
	conf.cursorItems = false
	check(not T.WantsCursor(GameTooltip), "and the whole behaviour is one switch")
	conf.cursorItems = true
end

print("== tooltips: the typeface reaches lines we never see ==")
do
	-- Restyling the three FONT OBJECTS is the highest-leverage thing in the
	-- module: every line inherits from one of them, including the ones Pawn and
	-- MobInfo2 add later, so their lines come out in Outfit without either addon
	-- knowing we exist.
	local size = {}
	for _, n in ipairs({ "GameTooltipHeaderText", "GameTooltipText", "GameTooltipTextSmall" }) do
		local path, pt = _G[n]:GetFont()
		size[n] = pt
		check(path and path:find("Outfit"), n .. " is drawn in Outfit")
		check(type(pt) == "number" and pt > 0, "  at a real size (" .. tostring(pt) .. ")")
	end

	-- `size.a > size.b` on two nils is an error, not a failure, and an error here
	-- eats every check after it. Ask the question only once both answers exist.
	check(size.GameTooltipHeaderText and size.GameTooltipText
		and size.GameTooltipHeaderText > size.GameTooltipText,
		"and the name outranks the body copy")
end

print("== tooltips: the badge stands down for an addon that READS that line ==")
do
	local T = A:GetModule("tooltips")
	local conf = A.Config:Module("tooltips")

	-- MobInfo2 does not only append to line 2. It locates a mob's extra info by
	-- scanning for the level NUMBER as a substring (MobInfo2.lua:2118-2131):
	--     if string.find(ttLeft, levelInfo) then levelLine = idx
	-- Move the digits into the badge and that scan finds nothing, on its shipped
	-- default path (MobInfoConfig.UseGameTT == 0). There is no having it both
	-- ways, so the badge yields.
	_G.MobInfoConfig = { UseGameTT = 0 }
	_G.MI2_BuildTooltipMob = function() end

	GameTooltip:SetUnit("mouseover")
	local line = _G.GameTooltipTextLeft2:GetText()
	check(line and line:find("20", 1, true),
		"with MobInfo2 loaded the level NUMBER stays in the line (" .. tostring(line) .. ")")
	check(not GameTooltip.aetherBadge:IsShown(),
		"and the badge stands down rather than blinding it")

	-- ...but it is the player's tooltip. One switch takes it back.
	conf.deferToLevelReaders = false
	GameTooltip:SetUnit("mouseover")
	check(GameTooltip.aetherBadge:IsShown(), "overriding the deference restores the badge")
	conf.deferToLevelReaders = true

	-- MobInfo2 in its own-window mode does not do that scan, so it is not a
	-- reason to give up the badge. Detected by the SETTING, not by the addon.
	_G.MobInfoConfig.UseGameTT = 1
	GameTooltip:SetUnit("mouseover")
	check(GameTooltip.aetherBadge:IsShown(),
		"and MobInfo2 in its own-window mode is not a reason to stand down")

	_G.MobInfoConfig, _G.MI2_BuildTooltipMob = nil, nil
end

print("== tooltips: re-entry, and the two-word classification ==")
do
	local T = A:GetModule("tooltips")

	GameTooltip:SetUnit("mouseover")
	check(GameTooltip.aetherBadge:IsShown(), "badge up after a fill")
	local before = _G.GameTooltipTextLeft2:GetText()

	-- Running the handler again over text it has ALREADY stripped finds no level
	-- - correctly, we took it out. Reading that as "no badge here" would hide the
	-- badge drawn a moment ago, so the fill remembers it was stripped.
	T:OnUnit(GameTooltip)
	check(GameTooltip.aetherBadge:IsShown(),
		"and still up after the handler is re-entered on the same text")
	check(_G.GameTooltipTextLeft2:GetText() == before, "with the line unchanged")
	check(GameTooltip.aetherGutter > 0, "and the gutter still held open")

	-- The badge number comes from UnitLevel, not from the parsed token, so a
	-- locale or an addon that reformatted the line cannot put a wrong number in
	-- the disc.
	check(GameTooltip.aetherBadge.label:GetText() == tostring(UnitLevel("mouseover")),
		"and the number is the unit's own level, not the parsed string")

	-- A rare elite writes TWO classification words in front of the type. Breaking
	-- after the first left "Elite Humanoid" under a chip already saying "Rare+".
	local _, rest = T.ParseLevelLine("Level 20 Rare Elite Humanoid", true)
	check(rest == "Humanoid", "both classification words come off a rare elite ("
		.. tostring(rest) .. ")")
end

section("tooltips: the level badge is a circle, not a rumour of one", function()
	local T = A:GetModule("tooltips")

	-- Pinned, not inherited. By the time this runs the suite has flipped every
	-- toggle in the options tree both ways and the tooltip happens to be sitting
	-- at scale 1 - where "snap in the badge's own units" and "snap in UIParent's"
	-- give the same answer, and the assertion below cannot tell them apart. The
	-- whole point of the fix is what happens at the scale it actually ships at.
	local wasScale = GameTooltip:GetScale()
	GameTooltip:SetScale(0.71)

	_G.__units.mouseover.isPlayer = false
	GameTooltip:SetUnit("mouseover")
	local badge = GameTooltip.aetherBadge
	check(badge and badge:IsShown(), "badge drawn")
	check(math.abs(badge:GetEffectiveScale() - 0.71) < 1e-6,
		"and it inherits the tooltip's scale (" .. string.format("%.3f", badge:GetEffectiveScale()) .. ")")

	-- 1. No MaskTexture. A mask edge is the client's to anti-alias and it does
	--    that poorly - the same fact Tools/generate_textures.py records against
	--    minimap_border. At 46px with a portrait in it that is a fair trade; at
	--    26px the stair-stepping IS the shape.
	local masked = false
	for _, r in ipairs({ badge.disc, badge.ring }) do
		if r.__masks and #r.__masks > 0 then masked = true end
	end
	check(not masked, "the disc is drawn from Circle-Mask as artwork, not cut out"
		.. " with a mask")

	-- 2. The rim laps OVER the disc rather than sitting flush inside it, so the
	--    disc's own outer texel row cannot peek out from under it.
	local p1, rel1, _, x1, y1 = badge.ring:GetPoint(1)
	check(p1 == "TOPLEFT" and rel1 == badge and x1 < 0 and y1 > 0,
		"and the rim is drawn proud of it on every side (" .. tostring(x1) .. ")")
	check(math.abs(x1) == A:PxIn(badge),
		"by exactly one physical pixel, in the badge's own units - not UIParent's,"
		.. " which at the tooltip's 0.71 would be seven tenths of one")

	-- 3. The diameter lands on the pixel grid. Unsnapped, a 26-unit disc inside a
	--    frame scaled to 0.71 is 18.46 physical pixels and its rim crosses a
	--    boundary the whole way round, which the client resolves as half-lit grey.
	local step = A:PxIn(badge)
	local q = badge:GetWidth() / step
	check(math.abs(q - math.floor(q + 0.5)) < 1e-6,
		"and the diameter is a whole number of physical pixels ("
		.. string.format("%.3f", q) .. ")")
	check(math.abs(step - A.pixel) > 1e-6,
		"measured in the badge's OWN units, which at 0.71 are not UIParent's"
		.. " (" .. string.format("%.4f vs %.4f", step, A.pixel) .. ")")

	-- 4. The badge is the NAME'S colour, whoever the name belongs to.
	--
	--    Screen 6a tints the three NPC variants by reaction and leaves the
	--    anchored player card's badge in the skin's purple, and the reason is
	--    sound about REACTION: a player is friendly nearly every time you see
	--    one, so tinting by that says nothing the name did not and comes out a
	--    washed grey-blue. It is not sound about a CLASS colour, which is the
	--    one thing on the card you cannot read off the name's wording.
	local hostile = A.Palette.c.ttHostile
	local dr, dg, db, da = badge.disc:GetVertexColor()
	check(math.abs(dr - hostile[1]) < 0.001 and math.abs(da - 0.15) < 0.001,
		"a hostile NPC's badge is its reaction colour at .15")

	-- A class TOKEN, not just a display name. UnitClass returns the token
	-- second, and Palette:ClassColor keys on it - a mock player carrying only
	-- "Shaman" has no class colour at all, so the branch under test is never
	-- reached and the badge falls back to the purple the check was expecting.
	-- Which is how this passed before the behaviour changed.
	_G.__units.mouseover.isPlayer = true
	_G.__units.mouseover.class, _G.__units.mouseover.classToken = "Mage", "MAGE"
	GameTooltip:SetUnit("mouseover")
	local mage = RAID_CLASS_COLORS.MAGE
	local pr, pg, pb, pa = badge.disc:GetVertexColor()
	check(math.abs(pr - mage.r) < 0.001 and math.abs(pg - mage.g) < 0.001
		and math.abs(pa - 0.15) < 0.001,
		"and a player's badge is their CLASS colour at the same .15, so the rule"
		.. " is one rule (got " .. string.format("%.2f %.2f %.2f @%.2f",
			pr, pg, pb, pa) .. ")")
	local ir = { badge.label:GetTextColor() }
	check(math.abs(ir[1] - mage.r) < 0.001 and math.abs(ir[2] - mage.g) < 0.001,
		"with the same colour on it, not the skin's #cdbcff")

	-- Switch class colours off and the ink is a reaction again - and so is the
	-- reason, so the badge goes back to the skin's purple.
	local wasCC = A.db.profile.modules.tooltips.classColorNames
	A.db.profile.modules.tooltips.classColorNames = false
	GameTooltip:SetUnit("mouseover")
	local want = A.Palette.c.ttBadgeBg
	pr, pg, pb, pa = badge.disc:GetVertexColor()
	check(math.abs(pr - want[1]) < 0.001 and math.abs(pa - want[4]) < 0.001,
		"with class colours off it is the skin's own purple again, as screen 6a"
		.. " draws it - a friendly player's REACTION still says nothing worth"
		.. " spending the card's accent on")
	A.db.profile.modules.tooltips.classColorNames = wasCC

	_G.__units.mouseover.isPlayer = false
	GameTooltip:SetScale(wasScale)
end)

section("tooltips: the cursor follow, and the flip at a screen edge", function()
	local T = A:GetModule("tooltips")

	-- A flat coordinate space to reason in. The maths is done entirely in the
	-- TOOLTIP's own units - GetCursorPosition returns physical pixels, and
	-- SetPoint offsets are read in the space of the frame being positioned - so
	-- scale 1 everywhere is the case where the two agree and any arithmetic slip
	-- shows up as a plain wrong number rather than as a scale factor.
	local oldW, oldH = UIParent:GetWidth(), UIParent:GetHeight()
	UIParent:SetSize(1000, 600)
	UIParent.__scale = 1
	GameTooltip.__scale = 1
	GameTooltip:SetSize(300, 120)

	GameTooltip.default = 1
	GameTooltip:SetItemByID(1234, "Staff of the Blessed Seer", 3)
	check(GameTooltip.aetherFollow, "a default-anchored item tooltip is marked to follow")

	cursorX, cursorY = 200, 400
	GameTooltip.__scripts.OnUpdate(GameTooltip)
	local p, rel, relP, x, y = GameTooltip:GetPoint(1)
	check(p == "TOPLEFT" and rel == UIParent and relP == "BOTTOMLEFT",
		"it hangs its TOPLEFT off the screen origin")
	check(x == 224 and y == 378,
		"at the deck's +24 / -22 from the cursor (" .. tostring(x) .. ", " .. tostring(y) .. ")")

	-- Near the right edge it FLIPS rather than clamping. Clamping slides the card
	-- under the cursor, which is worse than putting it on the other side.
	cursorX, cursorY = 900, 400
	GameTooltip.__scripts.OnUpdate(GameTooltip)
	local _, _, _, fx = GameTooltip:GetPoint(1)
	check(fx == 900 - 24 - 300,
		"crowded on the right it flips to the other side of the cursor ("
		.. tostring(fx) .. ")")
	check(fx + 300 <= 900, "so the card never lands under the pointer")

	-- And at the bottom.
	cursorX, cursorY = 200, 60
	GameTooltip.__scripts.OnUpdate(GameTooltip)
	local _, _, _, _, fy = GameTooltip:GetPoint(1)
	check(fy == 60 + 22 + 120, "and flips upward at the bottom edge (" .. tostring(fy) .. ")")

	-- A tooltip nobody marked is left exactly where its owner put it.
	GameTooltip.aetherFollow = nil
	GameTooltip:ClearAllPoints()
	GameTooltip.__scripts.OnUpdate(GameTooltip)
	check(#GameTooltip.__points == 0,
		"and an unmarked tooltip is not moved at all - the follow flag is decided"
		.. " once per tooltip, not per frame")

	cursorX, cursorY = 500, 400
	UIParent:SetSize(oldW, oldH)
end)

section("tooltips: the anchor corner comes from where the frame SITS", function()
	local T = A:GetModule("tooltips")

	-- Not from the point string saved beside it. Movers re-anchors every drag to
	-- BOTTOMLEFT of UIParent and saves what it set, so that string reads
	-- BOTTOMRIGHT until the first drag and BOTTOMLEFT forever after - never a TOP
	-- variant, whatever the player actually did with the frame. A tooltip grows
	-- away from the corner it is pinned by, so believing it means one parked near
	-- the top of the screen grows off it.
	UIParent:SetSize(1000, 600)
	UIParent.__scale = 1

	T.anchor:SetGeom({ cx = 100, cy = 500 })      -- top-left quadrant
	GameTooltip_SetDefaultAnchor(GameTooltip, UIParent)
	check(GameTooltip:GetPoint(1) == "TOPLEFT",
		"parked top-left, the tooltip presents its TOPLEFT and grows down-right")

	T.anchor:SetGeom({ cx = 900, cy = 80 })       -- bottom-right, the default
	GameTooltip_SetDefaultAnchor(GameTooltip, UIParent)
	check(GameTooltip:GetPoint(1) == "BOTTOMRIGHT", "and bottom-right, the other way")

	-- Saved anchor data says BOTTOMLEFT; the frame is bottom-RIGHT. The screen
	-- wins, which is the whole point.
	A.db.profile.anchors.tooltip = { point = "BOTTOMLEFT", relPoint = "BOTTOMLEFT", x = 0, y = 0 }
	GameTooltip_SetDefaultAnchor(GameTooltip, UIParent)
	check(GameTooltip:GetPoint(1) == "BOTTOMRIGHT",
		"even when the saved point string disagrees")
	A.db.profile.anchors.tooltip = nil

	T.anchor:SetGeom(nil)
end)

section("tooltips: adopting frames whose names cannot be known in advance", function()
	local T = A:GetModule("tooltips")

	-- LibExtraTip - how Informant, Enchantrix and BeanCounter reach a tooltip -
	-- names its frames from its own version string:
	--     LIBSTRING = LIBNAME.."_"..MAJOR.."_"..MINOR      LibExtraTip.lua:63
	--     CreateFrame("GameTooltip", LIBSTRING.."Tooltip"..n, ...)          :1112
	-- so they carry a version number and cannot be in a static list.
	local lx = _G.__makeTooltip("LibExtraTip_1_400Tooltip1")
	check(not T.skinned[lx], "a LibExtraTip frame starts unskinned")
	local n = T:Sweep()
	check(n >= 1 and T.skinned[lx],
		"and the sweep adopts it (" .. tostring(n) .. " new)")
	check(lx.aetherCard ~= nil, "with a card of its own, so Auctioneer's extra tip"
		.. " is not a stone box glued under a glass one")
	check(T:Sweep() == 0, "and sweeping again adopts nothing twice")

	check(T:Register(GameTooltip) == false, "registering an adopted frame is a no-op")

	-- An anonymous frame has no global line strings to find. It must decline to
	-- decorate rather than nil-index its way through the unit handler.
	local anon = CreateFrame("Frame", nil, UIParent)
	anon.__hasScript = {}
	T:Register(anon)
	check(pcall(T.OnUnit, T, anon), "a nameless tooltip does not throw the unit handler")

	check(pcall(T.Diagnose, T), "and /aether tooltips reports without erroring")
end)

section("tooltips: a template this cannot parse costs a badge, not a line", function()
	local T = A:GetModule("tooltips")
	local real = _G.UNIT_LEVEL_TEMPLATE

	-- A positional placeholder - which some locales use - is a shape the pattern
	-- builder does not know. The dangerous outcome is not "no badge": it is a
	-- pattern left with one trailing capture, which matches the WHOLE line, hands
	-- back nil as the remainder, and writes an empty string over the text.
	_G.UNIT_LEVEL_TEMPLATE = "Level %1$d"
	check(T.LevelPattern() == nil, "an unparseable template yields no pattern at all")
	check(T.ParseLevelLine("Level 20 Humanoid", false) == nil,
		"so nothing parses, and nothing is rewritten")

	_G.UNIT_LEVEL_TEMPLATE = "Stufe %d"
	check(select(2, T.ParseLevelLine("Stufe 20 Humanoid", false)) == "Humanoid",
		"and the pattern re-derives when the client's template is not English")

	_G.UNIT_LEVEL_TEMPLATE = real
	check(T.LevelPattern() ~= nil, "back to the real one")
end)

section("tooltips: the guild line", function()
	local u = _G.__units.mouseover
	local was, wasGuild, wasClass = u.isPlayer, u.guild, u.classification
	u.isPlayer, u.guild, u.classification = true, "Samophlange", nil
	u.class = "Shaman"

	GameTooltip:SetUnit("mouseover")
	local fs = _G.GameTooltipTextLeft2
	check(fs:GetText() == "<Samophlange>", "the client writes the guild on its own line")
	local r, g, b = fs:GetTextColor()
	local want = A.Palette.c.ttGuild
	check(math.abs(r - want[1]) < 0.001 and math.abs(b - want[3]) < 0.001,
		"and it takes the accent, matched on the <brackets> rather than on a line"
		.. " index - an unguilded player has no such line at all")

	u.isPlayer, u.guild, u.classification = was, wasGuild, wasClass
end)

print("== tooltips: turning it off gives Blizzard's back ==")
do
	local T = A:GetModule("tooltips")
	A:SetModuleEnabled("tooltips", false)
	check(GameTooltip.NineSlice:IsShown(),
		"disabling restores the client's own border - a hook that cannot be"
		.. " removed still has to be able to become a no-op")
	check(not GameTooltip.aetherCard:IsShown(), "and hides the card")

	-- The parts that are easy to forget, because leaving them is not visible the
	-- way a leftover card would be. "Off" has to mean the client's tooltip, not a
	-- slightly haunted one.
	local bar = _G.GameTooltipStatusBar
	check(bar:GetHeight() == 8, "the health bar goes back to Blizzard's 8px")
	check(not bar.lockColor, "and stops refusing the client's own colour")
	check(not bar.aetherValue:IsShown(), "and our readout goes with it")
	local path = _G.GameTooltipText:GetFont()
	check(path and not path:find("Outfit"),
		"and the client's own tooltip face comes back (" .. tostring(path) .. ")")

	A:SetModuleEnabled("tooltips", true)
	check(T.enabled, "and it comes back")
	check(not GameTooltip.NineSlice:IsShown(),
		"with the stone border off again - re-enabling has to redo what disabling"
		.. " undid, or off-then-on is a third state neither of them describes")
	local back = _G.GameTooltipText:GetFont()
	check(back and back:find("Outfit"), "and Outfit back")
	check(_G.GameTooltipStatusBar:GetHeight() == 7, "and the hairline back")
end

print("== greeting: which build is this, without being asked ==")
do
	local said = A.Errors:Capture(function()
		A.__greeted = nil
		A:Greet()
	end)
	check(said:find(A.version, 1, true) ~= nil,
		"login says which build this is (" .. A.version .. ") - the point is a"
		.. " player can report it without being asked first")
	check(said:find("/aether help", 1, true) ~= nil,
		"and points at /aether HELP for the command list - bare /aether opens"
		.. " the settings panel, so sending people there 'for commands' sends"
		.. " them somewhere that lists none")
	-- And it is a real command. A greeting that names one which does nothing is
	-- worse than no greeting: it is the first thing a new player types.
	local helped = A.Errors:Capture(function()
		SlashCmdList["AETHERUI"]("help")
	end)
	check(helped:find("/aether", 1, true) ~= nil,
		"and /aether help actually lists the commands")

	local lines = 0
	for _ in said:gmatch("[^\n]+") do lines = lines + 1 end
	check(lines <= 2,
		"in two lines, not a banner (" .. lines .. ") - a greeting long enough"
		.. " to scroll the chat frame is one people turn off")

	-- AND IT SAYS WHERE TO ASK. Somebody who has just installed this has no
	-- idea where to go when something looks wrong, and the greeting is the
	-- one moment they are certainly reading. On the commands line rather
	-- than a third of its own, because two lines is the whole budget - and
	-- the check above is what says so.
	check(said:find("discord.gg/drveoj", 1, true) ~= nil,
		"the greeting says where to get support")
	-- RAW, not through Errors:Capture. That one strips colour codes on the way
	-- out - they are for a chat frame, not for a paste into a bug report - so
	-- asking IT whether something is highlighted always answers no.
	local raw = {}
	local realPrint = A.Print
	A.Print = function(_, msg) raw[#raw + 1] = tostring(msg) end
	A.__greeted = nil
	A:Greet()
	A.Print = realPrint
	local rawText = table.concat(raw, " ")
	-- IN THE RESERVED GOLD, and the three commands beside it in the accent.
	-- It was the accent too, which made it read as a fourth slash command
	-- rather than as the one thing on the line you are meant to copy.
	local gold = A.Palette:Hex(A.Palette.c.semanticGold)
	check(rawText:find("|cff" .. gold .. "discord%.gg/drveoj|r") ~= nil,
		"with the address in the reserved gold - it is the part somebody has"
		.. " to copy, and in the accent it read as a fourth command (" .. gold
		.. ")")
	local accent = A.Palette:Hex(A.Palette.c.accent)
	check(gold ~= accent,
		"which is a different colour from the commands beside it, or it is not"
		.. " standing out from anything")

	-- Said once. Boot runs on ADDON_LOADED and again on PLAYER_LOGIN.
	local again = A.Errors:Capture(function() A:Greet() end)
	check(again == "", "and only once, however many times boot runs")

	local was = A.db.profile.greet
	A.db.profile.greet = false
	local quiet = A.Errors:Capture(function()
		A.__greeted = nil
		A:Greet()
	end)
	check(quiet == "", "off means silent")
	A.db.profile.greet = was
end

print("== errors: an error you cannot copy is an error you cannot send anybody ==")
do
	local Errors = A.Errors
	check(Errors ~= nil, "the catcher is loaded")

	-- Stand a handler of our own in first, the way BugSack or the client's own
	-- would be, and check we end up BEHIND it rather than on top of it.
	local seen = {}
	seterrorhandler(function(e) seen[#seen + 1] = tostring(e) end)

	Errors.installed = false
	for i = #Errors.log, 1, -1 do Errors.log[i] = nil end
	check(Errors:Install() == true, "it installs")

	local handler = geterrorhandler()
	handler("Interface/AddOns/Thing/Thing.lua:12: attempt to index a nil value")
	check(#Errors.log == 1, "an error is caught")
	check(#seen == 1,
		"AND PASSED ON to the handler that was already there - swallowing it"
		.. " would blind every other tool on the machine, which is worse than"
		.. " the problem this solves")

	-- A tick loop throws the same line every frame. Twelve copies of it is a
	-- box with one error in it and no room for the one before.
	handler("Interface/AddOns/Thing/Thing.lua:12: attempt to index a nil value")
	check(#Errors.log == 1 and Errors.log[1].count == 2,
		"the same error twice running is counted, not repeated (x"
		.. Errors.log[1].count .. ")")

	for i = 1, 40 do handler("distinct error " .. i) end
	check(#Errors.log <= 12, "and the list is capped (" .. #Errors.log .. ")")
	check(Errors.log[1].text == "distinct error 40",
		"newest first - the last thing that broke is the thing you came to read")

	-- The handler runs INSIDE the client's error path. Anything it raises comes
	-- straight back to it, and the client does not break that loop for you.
	local realInsert = table.insert
	table.insert = function() error("deliberate") end
	local ok = pcall(handler, "an error while we are already handling one")
	table.insert = realInsert
	check(ok,
		"and the catcher never raises out of the error path itself - it runs"
		.. " INSIDE the client's error handling, so anything it throws arrives"
		.. " back at the thing that threw it and the client does not break that"
		.. " loop for you")

	local text = Errors:Text()
	check(text:find("distinct error 40", 1, true) ~= nil,
		"the box carries the actual message, ready to select")

	-- A bug report without a version is a report about some build or other.
	check(text:find(A.version, 1, true) ~= nil,
		"and the version is at the top of it (" .. A.version .. ") - the first"
		.. " question about any report is which build it came from")

	-- /aether diag answers into the chat frame, the one place its answer cannot
	-- be selected.
	local grabbed = Errors:Capture(function()
		A:Print("|cff9d7bffcoloured|r line one")
		if DEFAULT_CHAT_FRAME then DEFAULT_CHAT_FRAME:AddMessage("line two") end
	end)
	check(grabbed:find("line one", 1, true) and grabbed:find("line two", 1, true),
		"chat output can be captured into the box - BOTH ways this addon writes"
		.. " a line, because diag uses one and everything else uses the other")
	check(grabbed:find("|cff", 1, true) == nil,
		"with the colour codes stripped: they are for a chat frame, not for a"
		.. " paste into a bug report")

	-- Whatever happens in there, chat has to work afterwards.
	local before = A.Print
	pcall(function() Errors:Capture(function() error("deliberate") end) end)
	check(A.Print == before,
		"and a capture that blows up still puts Print back - losing it would"
		.. " silence every message the addon makes for the rest of the session")

	Errors:ShowText("copy me")
	check(Errors.frame:IsShown() and Errors.frame.box:GetText() == "copy me",
		"and any text at all can be put in it")

	-- AND IT GIVES THE KEYBOARD BACK, however it is closed. The box takes focus
	-- on the way in so that Ctrl+A works the moment you look at it, and Escape
	-- was the only thing handing it back - closed by its own cross, or hidden
	-- by anything else, it kept the keyboard while invisible and every key went
	-- into a box nobody could see.
	check(Errors.frame.box:HasFocus(),
		"the box takes the keyboard when it opens, so a copy is one gesture")
	Errors.frame:Hide()
	check(not Errors.frame.box:HasFocus(),
		"and gives it back when it closes, whichever way it was closed")
	Errors:ShowText("copy me")

	-- IT SCROLLS, and it says so.
	--
	-- The box was anchored straight to the dialog, so a diag of eighty lines
	-- drew forty of them and the rest went outside it - selected by Ctrl+A and
	-- copied correctly, and invisible. Which is the worst way for this to fail:
	-- the report you paste is complete and the one you can read is not.
	do
		local f = Errors.frame
		check(f.box:GetParent() == f.scroll and f.scroll:GetScrollChild() == f.box,
			"the box is the scroll frame's child rather than anchored to the"
			.. " dialog, which is what puts the overflow inside something")
		check((f.box:GetWidth() or 0) > 0,
			"and has a width of its own - a scroll child is anchored to nothing,"
			.. " so a multiline box without one puts the report on a single line")

		check(not f.thumb:IsShown(),
			"a report that fits draws no rail - a control that cannot do"
			.. " anything is worse than no control")

		local long = {}
		for i = 1, 80 do long[i] = "line " .. i end
		Errors:ShowText(table.concat(long, "\n"))

		check(f.thumb:IsShown() and f.track:IsShown(),
			"one that does not gets one (" .. tostring(f.box:GetHeight())
			.. " of text in " .. tostring(f.scroll:GetHeight()) .. ")")
		check((f.thumb:GetHeight() or 0) < (f.scroll:GetHeight() or 0),
			"with a thumb shorter than the rail, which is what says how much"
			.. " more there is")
		check(f.scroll:GetVerticalScroll() == 0,
			"and it opens at the top rather than where the last report was left"
			.. " scrolled to")

		local topY = select(5, f.thumb:GetPoint(1))
		f.scroll:GetScript("OnMouseWheel")(f.scroll, -1)
		check((f.scroll:GetVerticalScroll() or 0) > 0, "the wheel moves it")
		check(select(5, f.thumb:GetPoint(1)) < topY,
			"and the thumb follows (" .. string.format("%.1f", topY) .. " -> "
			.. string.format("%.1f", select(5, f.thumb:GetPoint(1))) .. ")")
	end

	Errors.frame:Hide()

	-- Put the strict one back for whatever runs after this.
	seterrorhandler(function(e) fail("errorhandler: " .. tostring(e)) end)
	Errors.installed = false
end

section("ifec: the route table, against flights that were actually flown", function()
	local Route = A.IFEC and A.IFEC.Route
	check(Route ~= nil, "the route lookup loaded")
	check(A.IFEC_ROUTE_BUILD == "1.15.9.69109",
		"the table was generated from the client's own build (" ..
		tostring(A.IFEC_ROUTE_BUILD) .. ")")

	local legs = 0
	for _, row in pairs(A.IFEC_LEGS or {}) do
		for _ in pairs(row) do legs = legs + 1 end
	end
	check(legs > 250, "and carries the game's legs (" .. legs .. ")")

	-- NINE REAL FLIGHTS. Measured on this account and recorded to the second.
	-- These are the whole justification for the generated table: they are what
	-- the taxi speed was fitted against, and a change to the generator that
	-- moves any of them is a change that needs looking at.
	local FLOWN = {
		{ "Camp Taurajo, The Barrens",    "Crossroads, The Barrens",           79 },
		{ "Crossroads, The Barrens",      "Orgrimmar, Durotar",               141 },
		{ "Crossroads, The Barrens",      "Ratchet, The Barrens",              51 },
		{ "Crossroads, The Barrens",      "Splintertree Post, Ashenvale",     162 },
		{ "Orgrimmar, Durotar",           "Crossroads, The Barrens",          109 },
		{ "Ratchet, The Barrens",         "Crossroads, The Barrens",           68 },
		{ "Splintertree Post, Ashenvale", "Orgrimmar, Durotar",                95 },
		{ "Thunder Bluff, Mulgore",       "Crossroads, The Barrens",          158 },
		{ "Undercity, Tirisfal",          "The Sepulcher, Silverpine Forest", 106 },
	}

	local worst, worstLeg = 0, nil
	for _, f in ipairs(FLOWN) do
		local secs = Route:Leg(f[1], f[2])
		if not secs then
			fail("no leg for " .. f[1] .. " -> " .. f[2])
		else
			local err = math.abs(secs - f[3])
			if err > worst then worst, worstLeg = err, f[1] .. " -> " .. f[2] end
		end
	end
	check(worst < 1.5, "every flown leg is within a second and a half of what it took"
		.. " (worst " .. string.format("%.1f", worst) .. "s on " .. tostring(worstLeg) .. ")")

	-- DIRECTIONAL. The same two nodes take different times each way, so a table
	-- that stored one figure per pair would be half a minute out on one of them.
	local there = Route:Leg("Orgrimmar, Durotar", "Crossroads, The Barrens")
	local back  = Route:Leg("Crossroads, The Barrens", "Orgrimmar, Durotar")
	check(there and back and math.abs(there - back) > 25,
		"a leg is not the same in both directions (" .. string.format("%.0f", there)
		.. "s out, " .. string.format("%.0f", back) .. "s back)")

	-- A JOURNEY IS THE SUM OF ITS LEGS. The client loses and regains control
	-- once for a whole multi-hop trip, so this is the only way to know a
	-- two-legged flight - and the measured 209s says it is the right way.
	local total, breakdown, complete = Route:Journey({
		"Ratchet, The Barrens", "Crossroads, The Barrens", "Orgrimmar, Durotar" })
	check(complete and total and math.abs(total - 209) < 2,
		"Ratchet to Orgrimmar via Crossroads comes to what it took ("
		.. string.format("%.0f", total or 0) .. "s vs 209s measured)")
	check(#breakdown == 2, "reported as two legs")
	check(breakdown[1].at and math.abs(breakdown[1].at - 68) < 2,
		"with the boundary tick where the first leg ends ("
		.. string.format("%.0f", breakdown[1].at or 0) .. "s vs 68s measured)")

	-- An unknown leg does not sink the journey: the console still opens and
	-- still counts, it just cannot say when you land.
	local t2, b2, ok2 = Route:Journey({ "Orgrimmar, Durotar", "Nowhere At All" })
	check(t2 == nil and ok2 == false, "an unknown leg leaves the total unknown")
	check(b2 and #b2 == 1 and b2[1].seconds == nil, "and is reported rather than dropped")

	-- THE EIGHT TWO-PATH LEGS. Both factions reach these hubs by different
	-- routes and nothing in the data says which is ours, so the shipped figure
	-- is a mean and is marked as one.
	check(Route:IsFuzzy("Gadgetzan, Tanaris", "Cenarion Hold, Silithus"),
		"a leg with one path per faction is flagged")
	check(not Route:IsFuzzy("Ratchet, The Barrens", "Crossroads, The Barrens"),
		"and an ordinary one is not")

	-- Learning beats the table, which is what makes a fuzzy leg fixable.
	local before = Route:Leg("Gadgetzan, Tanaris", "Cenarion Hold, Silithus")
	check(Route:Learn({ "Gadgetzan, Tanaris", "Cenarion Hold, Silithus" }, 196),
		"a flight we timed is recorded")
	local after, source = Route:Leg("Gadgetzan, Tanaris", "Cenarion Hold, Silithus")
	check(after == 196 and source == "learned", "and beats the shipped figure ("
		.. string.format("%.0f", before) .. "s -> 196s)")

	-- A MULTI-HOP FLIGHT TEACHES NOTHING ABOUT ITS LEGS, because the boundaries
	-- are not observable - control is lost and regained once for the whole trip.
	check(not Route:Learn({ "A", "B", "C" }, 300),
		"a multi-hop flight is not learned from, having no visible boundaries")
	check(not Route:Learn({ "A", "B" }, 3),
		"and neither is a blip too short to have been a flight")

	local div = Route:Divergence()
	check(#div >= 1 and div[1].from == "Gadgetzan, Tanaris",
		"divergence reports what we measured against what shipped")
end)

section("ifec: boarding, flying and landing", function()
	local Taxi  = A.IFEC and A.IFEC.Taxi
	local Route = A.IFEC and A.IFEC.Route
	check(Taxi ~= nil, "flight detection loaded")

	local seen = {}
	Taxi:AddListener(function(event, flight) seen[#seen + 1] = { event, flight } end)
	Taxi:Start()

	local function flightMap(nodes, routes)
		_G.__taxi.nodes, _G.__taxi.routes = nodes, routes or {}
	end
	local function board(index)
		TakeTaxiNode(index)
		_G.__onTaxi = true
		fire("PLAYER_CONTROL_LOST")
		tick(0.4)                      -- the settle delay before UnitOnTaxi is trusted
	end
	local function land(after)
		tick(after or 1)               -- time in the air, so there is a duration to learn
		_G.__onTaxi = false
		fire("PLAYER_CONTROL_GAINED")
	end

	-- Ratchet to Crossroads: a real single-hop leg, 68s in the table and 68s on
	-- the stopwatch when it was flown.
	flightMap({
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	})

	-- A STUN IS NOT A FLIGHT. PLAYER_CONTROL_LOST fires for stuns, fear and
	-- mind control too, which is why Blizzard's own UIParent.lua asks
	-- UnitOnTaxi before believing it.
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)
	check(not Taxi:IsFlying(), "being stunned does not open the console")
	check(#seen == 0, "and nobody is told a flight began")

	-- THE JOURNEY IS READ AT BOOKING. GetNumRoutes and TaxiGetNodeSlot only
	-- answer while the flight map is open, and it is shut by takeoff.
	board(2)
	check(Taxi:IsFlying(), "boarding opens it")
	check(seen[1] and seen[1][1] == "board", "and the console is told")
	local f = seen[1][2]
	check(f.from == "Ratchet, The Barrens" and f.to == "Crossroads, The Barrens",
		"with the route read off the map before it closed")
	check(f.expected and math.abs(f.expected - 68) < 2,
		"and the duration from the table (" .. string.format("%.0f", f.expected or 0) .. "s)")

	-- UnitOnTaxi is not settled in the frame the event fires, so the check is
	-- retried. A mock that flipped the flag instantly would never show this.
	local elapsed, remaining, fraction = Taxi:Progress()
	check(elapsed and elapsed >= 0 and fraction and fraction >= 0,
		"progress is readable in the air")

	land(67)
	check(not Taxi:IsFlying(), "landing closes it")
	check(seen[2] and seen[2][1] == "land", "and the console is told that too")
	check(seen[2][2].learned == true, "a clean single-hop flight is learned from")
	check(math.abs(Route:Leg("Ratchet, The Barrens", "Crossroads, The Barrens") - 67.4) < 1,
		"and the measured time replaces the table's")

	-- AN EARLY LANDING DID NOT GO WHERE IT WAS BOOKED. Recording it against the
	-- booked destination would teach the table a duration for a trip nobody
	-- took. Prior art misses this.
	local before = Route:Leg("Ratchet, The Barrens", "Crossroads, The Barrens")
	board(2)
	TaxiRequestEarlyLanding()
	land(40)
	check(Route:Leg("Ratchet, The Barrens", "Crossroads, The Barrens") == before,
		"a flight cut short teaches the table nothing")

	-- A MULTI-HOP JOURNEY reads every node off the map, and is not learned from
	-- because control is lost and regained once for the whole trip.
	flightMap({
		{ name = "Ratchet, The Barrens",   kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
		{ name = "Orgrimmar, Durotar",     kind = "REACHABLE" },
	}, { [3] = { 2, 3 } })

	board(3)
	local m = seen[#seen][2]
	check(m.nodes and #m.nodes == 3, "a two-leg journey names all three nodes")
	check(m.expected and math.abs(m.expected - 209) < 2,
		"and totals what the flight really takes ("
		.. string.format("%.0f", m.expected or 0) .. "s vs 209s measured)")
	check(m.legs and #m.legs == 2 and m.legs[1].at and math.abs(m.legs[1].at - 68) < 2,
		"with a boundary tick at the stopover")
	land()

	-- A FLIGHT NOBODY SAW BOOKED is still a flight - a disconnect mid-air puts
	-- you back on the griffin with no booking to recover.
	_G.__onTaxi = true
	fire("PLAYER_ENTERING_WORLD")
	check(Taxi:IsFlying(), "logging in airborne opens the console")
	local d = seen[#seen][2]
	check(d.expected == nil and d.from == nil,
		"with no route and no estimate, rather than a wrong one")
	local e2 = Taxi:Progress()
	check(e2 ~= nil, "and the elapsed time still counts")
	land()

	Taxi:Stop()
	_G.__onTaxi = false
end)

section("ifec: the console, which is a flight timer when it is nothing else", function()
	local IF   = A:GetModule("ifec")
	local Taxi = A.IFEC and A.IFEC.Taxi
	check(IF ~= nil and IF.enabled, "the console module is on")

	Taxi:Start()
	_G.__taxi.nodes = {
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	}
	_G.__taxi.routes = {}

	-- The leg has been flown earlier in this file, so its duration is the
	-- learned one rather than the shipped one. Read it rather than assume.
	local LEG = A.IFEC.Route:Leg("Ratchet, The Barrens", "Crossroads, The Barrens")
	local function mmss(s)
		if s < 0 then s = 0 end
		return string.format("%d:%02d", math.floor(s / 60), math.floor(s % 60))
	end

	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)

	local f = IF.frame
	check(f ~= nil and f:IsShown(), "boarding opens it")
	-- NOT AN ARROW. Outfit has no U+2192 and renders the missing-glyph box for
	-- it, which is what shipped and what it looked like on screen.
	check(f.route:GetText() == "Ratchet, The Barrens  \194\187  Crossroads, The Barrens",
		"showing where you are going")
	check(f.route:GetText():find("\226\134\146", 1, true) == nil,
		"with a separator the font actually has")

	-- THE NUMERAL IS TIME REMAINING, not elapsed - it is what the design puts
	-- inside the ring, and it is the number a passenger actually wants.
	check(f.dial.value:GetText() == mmss(LEG),
		"with the time left in the dial (" .. tostring(f.dial.value:GetText()) .. ")")
	check(f.sub:GetText():find("elapsed 0:00", 1, true) ~= nil
		and f.sub:GetText():find("lands " .. mmss(LEG), 1, true) ~= nil,
		"and the line under it reading " .. tostring(f.sub:GetText()))

	-- The arc is a sheet of baked steps, so "how full is the ring" is which
	-- cell is showing. There is no empty frame - a flight that has not started
	-- hides the texture instead, and any progress at all shows the first step
	-- rather than leaving the ring dead for the first second.
	check(A.Media:DialArc(0) == nil and A.Media:DialArc(nil) == nil,
		"nothing at all before the flight starts")
	check(select(2, A.Media:DialArc(0.0001)) == 0,
		"and the first step the moment it does")

	tick(LEG / 2)
	IF:Refresh()
	check(f.dial.arc:IsShown(), "the ring fills as the flight goes on")
	local half = table.concat({ f.dial.arc:GetTexCoord() }, ",")
	check(f.dial.value:GetText() == mmss(LEG / 2),
		"and the numeral counts down (" .. tostring(f.dial.value:GetText()) .. ")")

	tick(LEG / 4)
	IF:Refresh()
	check(table.concat({ f.dial.arc:GetTexCoord() }, ",") ~= half,
		"moving to a later frame of the sheet as it goes")

	-- A FLIGHT THAT RUNS LONG counts to zero and stays there. Minus figures in
	-- the dial would read as a fault rather than as an estimate being out.
	tick(60)
	IF:Refresh()
	check(f.dial.value:GetText() == "0:00", "an overrunning flight sits at zero")

	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	check(not f:IsShown(), "landing closes it")

	-- WITH NO ROUTE THERE IS STILL A CONSOLE. The timer half must work with
	-- everything else absent, which includes not knowing where you are going.
	_G.__onTaxi = true
	fire("PLAYER_ENTERING_WORLD")
	IF:Refresh()
	check(f:IsShown(), "a flight nobody saw booked still opens it")
	check(f.sub:GetText():find("lands", 1, true) == nil,
		"with the landing clause dropped rather than shown as unknown")
	check(f.sub:GetText():find("elapsed", 1, true) ~= nil, "and the elapsed time still counting")
	check(not f.dial.arc:IsShown(), "and no ring, there being nothing to be a fraction of")

	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	Taxi:Stop()
end)

section("ifec: landing, at the scale of everything else, out of the way", function()
	local IF   = A:GetModule("ifec")
	local Taxi = A.IFEC.Taxi

	-- ZEN DRIVES THE SAME UIParent ALPHA and re-asserts it on its own ticker, so
	-- it is stood down for this block. Two writers is a real interaction - the
	-- console re-asserts in flight so it wins - but a test that raced it would
	-- be measuring which ticker ran last.
	local zenWas = A:GetModule("zen").enabled
	A:SetModuleEnabled("zen", false)
	UIParent:SetAlpha(1)

	Taxi:Start()
	_G.__taxi.nodes = {
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	}
	local function board()
		TakeTaxiNode(2)
		_G.__onTaxi = true
		fire("PLAYER_CONTROL_LOST")
		tick(0.4)
	end

	board()
	local f = IF.frame

	-- IT IS DRAWN AT THE PROFILE'S SCALE. Without this the console is the one
	-- thing on screen at 1.0 and reads enormous beside a HUD at 0.71.
	-- The profile's scale TIMES its own, the way the dock and the nameplates
	-- have theirs. The console is read once a minute from across the screen
	-- rather than glanced at constantly, so it sits smaller than the HUD.
	local cfg = A.Config:Module("ifec")
	check(math.abs(f:GetScale() - A.db.profile.scale * cfg.scale) < 0.0001,
		"the console is at the profile's scale times its own ("
		.. tostring(f:GetScale()) .. ")")
	check(cfg.scale < 1, "which is smaller (" .. tostring(cfg.scale) .. ")")

	-- THE INTERFACE GOES AWAY. One UIParent alpha, which is how Zen does it and
	-- covers addons we have never heard of.
	check(UIParent:GetAlpha() == 0, "the interface is hidden in flight")
	check(f:GetParent() == IF:Top() and IF:Top():GetParent() == nil,
		"and the console survives it, living under a holder outside UIParent")

	-- AND NOTHING UNDER IT MAY SPEAK. Alpha does not stop a frame taking the
	-- mouse: every buff, bag and action button is still sitting there at zero
	-- catching hovers, and the tooltip is deliberately moved OUT of UIParent so
	-- the console can be read - so the two together drew "Arcane Intellect, 24
	-- minutes remaining" over an empty sky, from a frame that was not on screen.
	local stranger = CreateFrame("Frame", nil, UIParent)
	-- From hidden, because a tooltip APPEARING is the event: Show() on one that
	-- is already up is not a transition and dispatches nothing, on the client or
	-- here. A check that skipped this would pass without the guard existing.
	GameTooltip:Hide()
	GameTooltip:SetOwner(stranger, "ANCHOR_RIGHT")
	GameTooltip:SetText("Arcane Intellect")
	GameTooltip:Show()
	check(not GameTooltip:IsShown(),
		"a frame hidden with the interface cannot raise a tooltip over it")

	-- OURS STILL CAN, which is the whole reason the tooltip was moved.
	GameTooltip:SetOwner(f, "ANCHOR_RIGHT")
	GameTooltip:SetText("Jump Off")
	GameTooltip:Show()
	check(GameTooltip:IsShown(),
		"while the console's own frames are still read normally")
	GameTooltip:Hide()

	-- LANDING. UnitOnTaxi is still true in the frame control comes back - the
	-- same lag as on the way out - so requiring it false and giving up left the
	-- console up for the rest of the session. This is that bug.
	fire("PLAYER_CONTROL_GAINED")
	check(Taxi:IsFlying(), "control returning while still aboard is not a landing yet")
	_G.__onTaxi = false
	tick(0.4)
	check(not Taxi:IsFlying(), "but it lands the moment the client agrees")
	check(not f:IsShown(), "and the console closes")
	check(UIParent:GetAlpha() == 1, "and the interface comes back")

	-- IF THE FLAG NEVER CLEARS, land anyway. Control coming back is the
	-- authority; UnitOnTaxi only says how soon to believe it. A console that
	-- waits forever for a flag is worse than one that closes a moment early.
	board()
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4) tick(0.4) tick(0.4) tick(0.4) tick(0.4)
	check(not Taxi:IsFlying(), "a flag that never clears still lands")
	check(UIParent:GetAlpha() == 1, "with the interface restored")
	_G.__onTaxi = false

	-- THE BACKSTOP. If control coming back is missed altogether - a disconnect,
	-- a loading screen eating the event - anything saying we are off the taxi
	-- ends the flight rather than stranding the console for the session.
	board()
	check(Taxi:IsFlying(), "boarding again")
	_G.__onTaxi = false
	tick(0.2)
	check(not Taxi:IsFlying(), "losing the landing event entirely still lands")
	check(UIParent:GetAlpha() == 1, "and still gives the interface back")

	-- A HIDDEN INTERFACE THAT STAYS HIDDEN is the worst thing this could do, so
	-- the recovery is driven directly rather than through the event: what
	-- matters is that holding the interface down while not flying is always
	-- recoverable. It is wired to PLAYER_ENTERING_WORLD as well as to landing.
	IF._hidUI = true
	IF._uiAlpha = 1
	UIParent:SetAlpha(0)
	check(IF:Recover(), "a restore that never happened is recoverable")
	check(UIParent:GetAlpha() == 1, "and the interface comes back")

	-- But not mid-flight: that would undo the hiding on every loading screen.
	board()
	check(not IF:Recover(), "while actually flying it leaves the interface alone")
	check(UIParent:GetAlpha() == 0, "which stays hidden")
	_G.__onTaxi = false
	tick(0.4)

	Taxi:Stop()
	IF:HideInterface(false)
	A:SetModuleEnabled("zen", zenWas)
end)

section("ifec: cut to its contents, and the map you still want", function()
	local IF   = A:GetModule("ifec")
	local Taxi = A.IFEC.Taxi
	local MM   = A:GetModule("minimap")

	local zenWas = A:GetModule("zen").enabled
	A:SetModuleEnabled("zen", false)
	UIParent:SetAlpha(1)
	Taxi:Start()

	local function fly(nodes, routes)
		_G.__taxi.nodes, _G.__taxi.routes = nodes, routes or {}
		TakeTaxiNode(#nodes)
		_G.__onTaxi = true
		fire("PLAYER_CONTROL_LOST")
		tick(0.4)
	end
	local function land()
		_G.__onTaxi = false
		fire("PLAYER_CONTROL_GAINED")
		tick(0.4)
	end

	-- THE DESIGN'S 560 IS A CEILING, not a width. It is a 1920-wide screen's
	-- 560, and on a smaller one at minimum scale it is most of a third of the
	-- screen - for a route whose names are short and mostly empty capsule.
	fly({
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	})
	local f = IF.frame
	local short = f:GetWidth()
	check(short <= 560, "the capsule never exceeds the design's width (" .. short .. ")")
	check(short >= 240, "nor shrinks below something readable")
	land()

	fly({
		{ name = "Marshal's Refuge, Un'Goro Crater", kind = "CURRENT" },
		{ name = "Thunder Bluff, Mulgore",           kind = "REACHABLE" },
	})
	check(f:GetWidth() > short,
		"a longer route gets a longer capsule (" .. f:GetWidth() .. " vs " .. short .. ")")
	land()

	-- JUMP OFF IS FOR MULTI-LEG JOURNEYS ONLY. Early landing puts you down at
	-- the NEXT flight master, which on a single-hop flight is where you were
	-- going anyway.
	fly({
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	})
	check(IF.jump == nil or not IF.jump:IsShown(),
		"a single-hop flight offers no way to jump off")
	land()

	fly({
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
		{ name = "Orgrimmar, Durotar",      kind = "REACHABLE" },
	}, { [3] = { 2, 3 } })
	check(IF.jump ~= nil and IF.jump:IsShown(), "a two-leg journey offers one")
	check(IF.jump:GetParent() == MM.frame, "hung off the minimap, where the concept puts it")

	-- UNDER THE ZONE PILL, NOT ON IT. The pill is already anchored to the map's
	-- bottom edge, so anchoring to the map put the two in the same place and
	-- the button landed on top of "In flight".
	local point, rel = IF.jump:GetPoint()
	check(point == "TOP" and rel == MM.pill,
		"below the zone pill rather than on top of it")

	-- ALPHA DOES NOT STOP A FRAME TAKING THE MOUSE. The whole interface is
	-- sitting there at zero alpha still catching clicks, and this button was
	-- underneath it - clicking it did nothing at all in game.
	check(IF.jump:GetFrameStrata() == "FULLSCREEN_DIALOG",
		"and above the interface we just hid, or the click never reaches it")
	check(IF.frame:GetParent() == IF:Top(), "as is the console, for the same reason")

	check(IF.jump.label:GetText() == "Jump Off", "reading Jump Off")

	-- NOT WHITE. It sits just under the pill's clock, and two white readouts
	-- stacked read as one block of text - the colour is what says they are
	-- different things.
	check(IF.jump.label:GetTextColor() == A.Palette.c.accent[1],
		"in accent rather than white, so it does not compete with the clock")

	-- ITS OWN GLYPH. The chevron means "this opens" everywhere else in the
	-- interface, so borrowing it here would promise a window.
	check(IF.jump.glyph:GetTexture() == A.Media.icons.file,
		"with a mark of its own rather than the chevron")

	-- The tooltip says what the thing DOES, not what it is called again.
	IF.jump:GetScript("OnEnter")(IF.jump)
	check(GameTooltip:GetText() == "Jump Off", "with a tooltip before it is used")
	IF.jump:GetScript("OnLeave")(IF.jump)

	local before = _G.__taxi.earlyLandings
	IF.jump:GetScript("OnClick")(IF.jump)
	check(_G.__taxi.earlyLandings == before + 1, "and clicking it asks to land early")

	-- ASKING CANNOT BE TAKEN BACK - the client has no "actually, carry on" - so
	-- the control becomes a readout rather than staying a button that lies.
	check(IF.jump.label:GetText() == "Exit requested", "after which it says so")
	check(IF.jump.label:GetTextColor() == A.Palette.c.textDim[1],
		"and dims, being a readout rather than a control")
	IF.jump:GetScript("OnClick")(IF.jump)
	check(_G.__taxi.earlyLandings == before + 1, "and asking twice asks once")

	-- THE MAP STAYS. Alpha multiplies down the parent chain, so a child of a
	-- frame at zero cannot be given an alpha - it has to leave the chain.
	check(UIParent:GetAlpha() == 0, "the interface is hidden")
	-- INTO A HOLDER, NOT INTO NIL. SetParent(nil) on a live frame left the
	-- subtree half-alive: the map drew, its clock stopped, and nothing under it
	-- took the mouse - no clicks and no tooltips on the button below it.
	check(MM.frame:GetParent() == IF:Top(),
		"but the map has moved into our own holder, out of UIParent's alpha")

	-- AND THE PILL WITH IT. The pill is the map's sibling, not its child - both
	-- set profile.scale themselves, so a child would take it twice - so moving
	-- the map left the pill behind in UIParent, where it faded to nothing a
	-- moment after appearing.
	check(MM.pill:GetParent() == IF:Top(),
		"and the pill with it, being its sibling rather than its child")

	-- AND THE TOOLTIP. It is a child of UIParent like everything else, so with
	-- the interface at zero it was being shown perfectly and drawn at nothing:
	-- the button took the hover and produced no tooltip at all.
	check(GameTooltip:GetParent() == IF:Top(),
		"and the tooltip, or hovering anything of ours produces nothing visible")

	-- The button has already been clicked by this point in the block, so the
	-- tooltip should be saying what it says AFTER asking.
	IF.jump:GetScript("OnEnter")(IF.jump)
	check(GameTooltip:IsShown(), "so the jump-off button raises one")
	check((GameTooltip:GetText() or "") == "Exit requested",
		"which follows the button's state rather than naming it once ("
		.. tostring(GameTooltip:GetText()) .. ")")
	IF.jump:GetScript("OnLeave")(IF.jump)
	check(IF:Top():GetParent() == nil, "which is itself parentless, being created that way")

	-- And the pill says so, the way it says "In combat".
	MM:UpdateZone()
	check(MM.pill.zone:GetText() == "In flight", "with the pill reading In flight")

	-- THE CLOCK STAYS, exactly as it does in combat. It is set outside the
	-- branches for that reason, and a state that cleared it would be the odd
	-- one out.
	check(MM.pill.clock:GetText() ~= nil and MM.pill.clock:GetText() ~= "",
		"and the clock still in it (" .. tostring(MM.pill.clock:GetText()) .. ")")

	-- The dot is a state light, not a fixed red one: red says you are being
	-- attacked, which a griffin is not.
	local dr = MM.pill.dot:GetVertexColor()
	check(dr == A.Palette.c.accent[1], "its light in accent rather than combat red")

	-- THE FADER MUST NOT TAKE IT AWAY. A flight is the most idle you ever are -
	-- no combat, no target, no cursor, nothing to cast - so every test the
	-- fader makes said "gone" and it faded the map out from under the one thing
	-- worth watching. The pill showed for a second and vanished.
	local hadDelay = A.db.profile.fader.delay
	A.db.profile.fader.delay = 1
	for i = 1, 40 do tick(0.1) end
	check(A.Fader.state == "awake",
		"a flight keeps the HUD awake, being idle by every other measure ("
		.. tostring(A.Fader.state) .. ")")
	A.db.profile.fader.delay = hadDelay


	land()
	check(MM.frame:GetParent() == UIParent, "and the map goes back afterwards")
	check(MM.pill:GetParent() == UIParent, "and so does the pill")
	check(IF.jump == nil or not IF.jump:IsShown(), "with the jump-off control put away")
	MM:UpdateZone()
	check(MM.pill.zone:GetText() ~= "In flight", "and the pill back to the zone")

	Taxi:Stop()
	IF:HideInterface(false)
	A:SetModuleEnabled("zen", zenWas)
end)

section("ifec: registering content packs, several at once", function()
	local R = A.IFEC and A.IFEC.Registry
	check(R ~= nil, "the registry loaded")

	local function pack(id, season, api, items)
		return { packId = id, seasonIndex = season, apiVersion = api or 1,
		         displayName = id, items = items }
	end
	local function ep(id, title, file)
		return { id = id, type = "podcast", title = title, totalDuration = 60,
		         segments = { { file = file or ("audio\\" .. id .. ".ogg"), duration = 60 } } }
	end

	R:Reset()

	-- THE HANDSHAKE WORKS BOTH WAYS ROUND. Load order is not guaranteed, so a
	-- pack that loaded first leaves its manifest in a global for us to collect
	-- and one that loads later calls straight in. A pack that only worked one
	-- way round would vanish depending on how the client felt that session.
	check(type(_G.AetherUI_IFEC) == "table" and type(_G.AetherUI_IFEC.Register) == "function",
		"the register function is published for packs that load after us")

	_G.AetherUI_IFEC_Pending = { pack("EarlyBird", 1, 1, { ep("e1", "Early One") }) }
	check(R:Drain() == 1, "and a pack that loaded before us is collected from the pending table")
	check(_G.AetherUI_IFEC_Pending == nil, "which is cleared once drained")
	check(R:Drain() == 0, "so draining again finds nothing rather than doubling up")

	check(_G.AetherUI_IFEC.Register(pack("LateBird", 2, 1, { ep("l1", "Late One") })),
		"a pack registering through the published function is taken")

	-- A CLASH IS REPORTED, NEVER SILENTLY OVERWRITTEN. packId is the addon
	-- folder name, so two of them means two copies installed or somebody has
	-- borrowed a name; either way the player wants telling.
	local ok = R:Register(pack("EarlyBird", 9, 1, { ep("x", "Impostor") }))
	check(ok == false, "a second pack under a registered name is refused")
	check(R.packs["EarlyBird"].items[1].title == "Early One", "the first one is untouched")

	-- MIXED API VERSIONS ARE NORMAL and refusal is per-pack, never
	-- all-or-nothing: one season built against a version we cannot serve must
	-- not take the others down with it.
	check(R:Register(pack("FromTheFuture", 3, 99, { ep("f", "Too New") })) == false,
		"a pack built for a newer console is refused")
	check(R:Register(pack("Ancient", 4, 0, { ep("a", "Too Old") })) == false,
		"and one built for an older one")
	check(R:Register(pack("StillFine", 5, 1, { ep("s", "Fine") })), "while the rest still register")

	-- A BROKEN PACK IS SOMEBODY ELSE'S DATA. It must be refused rather than
	-- half-carried: a browse list with a nameless row in it reads as our bug.
	check(R:Register({ packId = "Malformed", apiVersion = 1, items = "not a table" }) == false,
		"a manifest whose items are not a list is refused")
	check(R:Register(pack("Empty", 6, 1, {})) == false, "and one with no items")
	check(R:Register(pack("Nameless", 7, 1, { { id = "x", type = "podcast" } })) == false,
		"and one whose only item has no title or segments")
	check(R:Register(nil) == false and R:Register("nonsense") == false,
		"and something that is not a manifest at all")

	-- A BULLETIN IS PAGES. It carries no audio and no segments, so the only
	-- thing that makes one openable is having something to open - and a row in
	-- the library that does nothing when clicked is our bug, not the pack's.
	check(R:Register(pack("Pageless", 8, 1, {
		{ id = "g", type = "gossip", masthead = "ogler", title = "Spotted" },
	})) == false, "a bulletin with no pages is refused")
	check(R:Register(pack("Numbered", 9, 1, {
		{ id = "g", type = "gossip", masthead = "ogler", title = "Spotted",
		  pages = { 3 } },
	})) == false, "and one whose pages are not paths")

	-- An overlap that is not a number is compared against zero on every boundary
	-- of every piece, which for three-second chunks is an error a second and a
	-- half for as long as the track runs.
	check(R:Register(pack("Overlapped", 10, 1, {
		{ id = "x", type = "music", title = "Wrong", totalDuration = 6,
		  overlap = "lots",
		  segments = { { file = "a.ogg", duration = 3 } } },
	})) == false, "and an item whose overlap is not a number")

	local failures = R:Failures()
	check(#failures == 11, "every refusal is recorded for the settings readout (" .. #failures .. ")")
	check(failures[1].packId == "EarlyBird"
		and failures[1].reason:find("already registered", 1, true) ~= nil,
		"in words a settings page can print: " .. failures[1].reason)

	-- ORDERING MUST NOT DEPEND ON REGISTRATION ORDER, or the browse list
	-- reshuffles between sessions for no visible reason. seasonIndex decides.
	local order = R:Sorted()
	check(table.concat(order, ",") == "EarlyBird,LateBird,StillFine",
		"packs sort by season, not by arrival (" .. table.concat(order, ",") .. ")")

	R:Reset()
	R:Register(pack("Zed", 2, 1, { ep("z", "Zed One") }))
	R:Register(pack("Alpha", 1, 1, { ep("a", "Alpha One") }))
	check(table.concat(R:Sorted(), ",") == "Alpha,Zed",
		"and registering them backwards gives the same order")

	-- COMPOSITE KEYS. Two packs built independently will eventually ship the
	-- same item id, and only packId:itemId is unique.
	R:Reset()
	R:Register(pack("S01", 1, 1, { ep("e01", "Season One, One", "s1e1.ogg") }))
	R:Register(pack("S02", 2, 1, { ep("e01", "Season Two, One", "s2e1.ogg") }))
	local cat = R:Catalogue()
	check(#cat == 2, "two packs using the same item id both survive")
	check(cat[1].key == "S01:e01" and cat[2].key == "S02:e01",
		"keyed by pack and item together")

	-- DEDUPLICATION on the resolved file: the same track legitimately appears
	-- in two packs, and showing it twice under two headings reads as a bug.
	R:Reset()
	R:Register(pack("Ambient", 1, 1, { ep("t1", "Rainfall", "shared\\rain.ogg") }))
	R:Register(pack("BestOf", 2, 1, {
		ep("t9", "Rainfall (again)", "shared\\rain.ogg"),
		ep("t8", "Something Else", "other.ogg"),
	}))
	cat = R:Catalogue()
	check(#cat == 2, "a track in two packs is carried once (" .. #cat .. " entries)")
	check(cat[1].title == "Rainfall", "and the earlier season keeps it")

	-- BUT NEVER WITHIN ONE PACK. An author who opens two of their own items on
	-- the same file has done so deliberately - an episode whose first chapter
	-- is the same ambient bed the pack also offers on its own is a real shape,
	-- and it is what the dev pack is. Dropping the second was a pack quietly
	-- serving fewer items than it declared, with nothing anywhere saying so.
	R:Reset()
	R:Register(pack("Own", 1, 1, {
		ep("show", "The Show", "bed.ogg"),
		ep("bed",  "The Bed",  "bed.ogg"),
	}))
	cat = R:Catalogue()
	check(#cat == 2, "a pack reusing its own audio keeps both items ("
		.. #cat .. " of 2)")

	-- AN ARTIST IS OPTIONAL BUT NOT UNTYPED. A song is named by two things and
	-- the title alone is half of it, so it is carried - but a number here would
	-- reach the console as "3" beside a song name and read as our bug rather
	-- than the pack's, so it is refused at the door with everything else.
	R:Reset()
	R:Register(pack("Tunes", 1, 1, {
		{ id = "t1", type = "music", title = "Big Drum Deep Water",
		  artist = "The Mudfoot Kings", totalDuration = 60,
		  segments = { { file = "big.ogg", duration = 60 } } },
		{ id = "t2", type = "music", title = "Untyped", artist = 3,
		  totalDuration = 60, segments = { { file = "num.ogg", duration = 60 } } },
	}))
	cat = R:Catalogue()
	check(#cat == 1, "an item whose artist is not a string is refused ("
		.. #cat .. " of 1 kept)")
	check(cat[1].artist == "The Mudfoot Kings",
		"and a real one is carried onto the item (" .. tostring(cat[1].artist) .. ")")

	R:Reset()
end)

section("ifec: what is in season, and what fills a flight", function()
	local R, C = A.IFEC.Registry, A.IFEC.Content
	check(C ~= nil, "content selection loaded")

	local function item(id, kind, mins, from, until_)
		return { id = id, type = kind, title = id, totalDuration = mins * 60,
		         activeFrom = from, activeUntil = until_,
		         segments = { { file = id .. ".ogg", duration = mins * 60 } } }
	end
	local function pack(id, season, items)
		return { packId = id, seasonIndex = season, apiVersion = 1, items = items }
	end

	local cfg = A.Config:Module("ifec")
	cfg.progress = {}
	R:Reset()

	-- NO PACKS IS DORMANT, and so is every other way of getting there. The
	-- console asks one question and gets one answer.
	check(C:IsDormant(), "with nothing installed the console is dormant")

	R:Register(pack("Expired", 1, { item("old", "podcast", 10, "2026-01-01", "2026-02-01") }))
	check(C:IsDormant(), "and with only an expired season, still dormant")
	check(#R:Failures() == 0, "though nothing failed to register - it is in date, not in error")

	-- THE WINDOW IS READ ON EVERY ASKING, never cached. A player logged in
	-- across a season boundary gets the new content on their next flight
	-- rather than having to relog for it.
	R:Register(pack("S02", 2, { item("e1", "podcast", 10, "2026-09-01", "2026-10-01") }))
	check(C:IsDormant(), "a season that has not opened yet is not in season")
	_G.__today = "20260915"
	check(not C:IsDormant(), "and the same question the next day says it is")
	check(#C:Available() == 1, "with exactly the item whose window is open")
	_G.__today = "20261015"
	check(C:IsDormant(), "and dormant again once it closes")

	-- No bounds at all is evergreen, which is a real state the settings page
	-- has a word for.
	R:Register(pack("Evergreen", 3, { item("amb", "music", 1) }))
	check(not C:IsDormant(), "an item with no dates is evergreen")

	-- THE PROGRAMME. Resume first, then unplayed newest-season-first, then
	-- music as filler - and it crosses packs, because music is a different
	-- pack from a podcast and a queue that could not cross would fall silent
	-- with flight remaining.
	_G.__today = "20260915"
	R:Reset()
	cfg.progress = {}
	R:Register(pack("Music", 1, { item("rain", "music", 1), item("wind", "music", 1) }))
	R:Register(pack("S01", 2, { item("old1", "podcast", 2) }))
	R:Register(pack("S03", 3, { item("new1", "podcast", 2), item("new2", "podcast", 2) }))

	local queue = C:Programme(600)
	check(#queue > 0, "a programme is built for a ten-minute flight")
	check(queue[1].packId == "S03", "the newest season goes first ("
		.. tostring(queue[1].packId) .. ":" .. tostring(queue[1].id) .. ")")

	local kinds = {}
	for _, q in ipairs(queue) do kinds[#kinds + 1] = q.type end
	check(kinds[#kinds] == "music", "and music fills the end of it ("
		.. table.concat(kinds, ",") .. ")")

	-- A PART-PLAYED EPISODE GREETS YOU. Half-finished beats brand new.
	C:Remember("S01:old1", 3, false)
	queue = C:Programme(600)
	check(queue[1].key == "S01:old1", "something part-played comes first next time ("
		.. tostring(queue[1].key) .. ")")

	-- A MAGAZINE YOU ARE PART WAY THROUGH IS NOT A PROGRAMME ITEM.
	--
	-- Reader:Remember writes the PAGE you are on through the same
	-- Content:Remember a played segment goes through, so three pages into a
	-- magazine looks exactly like a part-heard episode - and the resume rule,
	-- written as "anything that is not music", put it at the head of the
	-- programme. Everything downstream steps past a bulletin correctly, so it
	-- never made a sound; it sat in the playlist saying it was about to play.
	-- A REAL MAGAZINE, which is PAGES rather than segments: the registry
	-- refuses gossip without any, so an item built like an episode would
	-- never reach the programme and the check could not fail.
	R:Register(pack("Mags", 4, { { id = "rag", type = "gossip",
		title = "The Ogler", pages = { "page1.tga", "page2.tga",
		"page3.tga", "page4.tga" } } }))
	C:Remember("Mags:rag", 3, false)
	queue = C:Programme(600)
	local sawMag = false
	for _, q in ipairs(queue) do if q.type == "gossip" then sawMag = true end end
	check(not sawMag, "a part-read magazine stays out of the programme")
	
	-- ...and an episode you are part way through still leads it, which is the
	-- thing the rule was there for.
	queue = C:Programme(600)
	check(queue[1].key == "S01:old1",
		"and a part-played episode still does (" .. tostring(queue[1].key)
		.. ")")
	
	-- A finished one is not offered again as though it were new.
	C:Remember("S03:new1", 9, true)
	queue = C:Programme(600)
	local sawFinished = false
	for _, q in ipairs(queue) do if q.key == "S03:new1" then sawFinished = true end end
	check(not sawFinished, "and a finished one is not queued as unplayed")

	-- THE PLAYER'S OWN PICKS ARE NEVER OVERRIDDEN and never dropped, even if
	-- they overrun - a queue that quietly removes what somebody asked for is
	-- worse than one that runs long.
	queue = C:Programme(60, { "S03:new2" })
	check(queue[1].key == "S03:new2", "a picked item leads the programme")
	local _, filled = C:Programme(30, { "S03:new2" })
	check(filled > 30, "and is kept even when it overruns the flight ("
		.. string.format("%.0f", filled) .. "s of 30s)")

	-- PROGRESS IS PACK-SCOPED, so uninstalling one season leaves another's
	-- alone, and state for a pack we no longer know is ignored rather than
	-- deleted - a season that expires and returns picks up where it was.
	C:Remember("Gone:whatever", 4, false)
	R:Reset()
	R:Register(pack("Music", 1, { item("rain", "music", 1) }))
	check(C:Programme(120) ~= nil, "a programme still builds with a stale id in the store")
	check(C:Progress("Gone:whatever") ~= nil, "and the stale progress is kept, not purged")
	check(C:Progress("S01:old1") ~= nil, "as is progress for a season not currently installed")

	-- MUSIC ROTATES, LONGEST AGO FIRST. Taken in catalogue order it was the same
	-- opening track on every single flight, which is a season of eleven
	-- behaving like a season of three.
	R:Reset()
	cfg.progress, cfg.playCount = {}, nil
	R:Register(pack("Tunes", 1, {
		item("one", "music", 3), item("two", "music", 3), item("three", "music", 3),
	}))

	queue = C:Programme(360)
	check(queue[1].id == "one" and queue[2].id == "two",
		"with nothing heard yet the pack's own order stands")

	C:Remember("Tunes:one", 1, true)
	C:Remember("Tunes:two", 1, true)
	queue = C:Programme(360)
	check(queue[1].id == "three", "the one never heard leads the next flight ("
		.. tostring(queue[1].id) .. ")")
	check(queue[2].id == "one", "then the one heard longest ago ("
		.. tostring(queue[2].id) .. ")")

	-- A COUNTER, NOT JUST A DATE. Everything heard on one afternoon carries the
	-- same date, and that is exactly the tie the rotation has to break.
	check((C:Progress("Tunes:two").seq or 0) > (C:Progress("Tunes:one").seq or 0),
		"and the order within a single day is still known")

	-- THE DEV PACK SITS AT SEASON ZERO, and between two never-heard tracks it is
	-- the newest season first - so once there is real content the filler is real
	-- content, and the test season is what you get after it has run out.
	R:Reset()
	cfg.progress, cfg.playCount = {}, nil
	R:Register(pack("Dev", 0, { item("test_bed", "music", 3) }))
	R:Register(pack("Season", 1, { item("real_song", "music", 3) }))
	queue = C:Programme(360)
	check(queue[1].id == "real_song", "a real season is reached for before the dev pack ("
		.. tostring(queue[1].id) .. ")")
	check(queue[2].id == "test_bed", "which still fills when the real one has run out")

	-- AMBIENT SHUFFLE IS MUSIC, not everything over again. It is the complete
	-- state's one-press default, and its job is to fill the rest of the flight
	-- rather than to start an episode nobody asked for.
	R:Reset()
	cfg.progress, cfg.playCount = {}, nil
	R:Register(pack("Mixed", 1, {
		item("talk", "podcast", 3), item("tune", "music", 3),
	}))
	local shuffle = C:MusicQueue()
	check(#shuffle == 1 and shuffle[1].id == "tune",
		"the ambient shuffle is music only (" .. #shuffle .. " item(s))")
	check(#C:Everything() == 2,
		"though the whole catalogue is still reachable (" .. #C:Everything() .. ")")

	-- ONE MORE, OR NOTHING. What the transport asks for when the queue runs out.
	check((C:NextAfter({}) or {}).id ~= nil, "with nothing queued there is a next thing")
	check(C:NextAfter(C:Everything()) == nil, "and with all of it queued there is not")

	R:Reset()
	cfg.progress, cfg.playCount = {}, nil
	_G.__today = "20260815"
end)

section("ifec: playing a programme across a flight", function()
	local R, C, P = A.IFEC.Registry, A.IFEC.Content, A.IFEC.Playback
	check(P ~= nil, "playback loaded")

	local cfg = A.Config:Module("ifec")
	cfg.progress = {}
	R:Reset()
	_G.__musicMuted = false

	-- Sixty-second segments, which is what makes the chaining testable: the
	-- boundaries are what drift, so an item has to have several.
	local function ep(id, title, n)
		local segs = {}
		for i = 1, n do
			segs[#segs + 1] = { file = id .. "_" .. i .. ".ogg", duration = 60 }
		end
		return { id = id, type = "podcast", title = title,
		         totalDuration = 60 * n, segments = segs }
	end
	R:Register({ packId = "S00", apiVersion = 1, seasonIndex = 0, items = {
		ep("e01", "Episode One", 3),
		ep("e02", "Episode Two", 2),
		{ id = "amb", type = "music", title = "Ambient", totalDuration = 60,
		  segments = { { file = "amb.ogg", duration = 60 } } },
	} })

	local cat = R:Catalogue()
	local queue = { cat[1], cat[2], cat[3] }

	local heard = {}
	P:AddListener(function(event, item) heard[#heard + 1] = event end)

	-- THE GAME'S OWN MUSIC IS SILENCED for the flight. Playing on the Music
	-- channel puts the programme OVER the zone music rather than in place of
	-- it, and switching that channel off would take our audio with it - so the
	-- game's music goes off and the programme plays somewhere else.
	_G.__cvars.Sound_EnableMusic = "1"
	check(P:Start(queue), "a programme starts")
	check(P.state == "playing", "and is playing")
	check(_G.__cvars.Sound_EnableMusic == "0",
		"with the game's own music switched off rather than played over")
	check(_G.__lastSound == "e01_1.ogg", "the first segment of the first item")
	check(_G.__soundsPlaying() == 1, "one thing at a time")

	-- CHAINED WITHOUT A CALLBACK. This client gives no playback-finished event
	-- for a file path, so the end of a segment is predicted from the duration
	-- the manifest baked in - which is why tooling probes them.
	tick(60)
	check(_G.__lastSound == "e01_2.ogg", "the next segment follows on its own ("
		.. tostring(_G.__lastSound) .. ")")
	check(_G.__soundsPlaying() == 1, "with the last one stopped, not left running")

	-- POSITION SAVED AT EVERY BOUNDARY, not at landing. A disconnect mid-flight
	-- is exactly when somebody wants their place kept and is the one moment no
	-- landing handler ever runs.
	local p = C:Progress("S00:e01")
	check(p and p.segment == 1, "the boundary is written down as it passes")
	check(not p.complete, "and not marked finished part way through")

	-- AUTOPLAY-NEXT. The brief calls this a functional requirement rather than
	-- polish: a flight outlasts an episode, and silence over the Barrens is the
	-- failure this exists to prevent.
	tick(60) tick(60)
	check(_G.__lastSound == "e02_1.ogg",
		"the programme moves to the next item by itself (" .. tostring(_G.__lastSound) .. ")")
	check(C:Progress("S00:e01").complete, "with the one it finished marked finished")

	-- RESUME WHERE IT WAS LEFT. The stored index is the last segment COMPLETED,
	-- so the next one is where to start.
	P:Stop()
	check(_G.__soundsPlaying() == 0, "stopping stops the sound")
	C:Remember("S00:e02", 1, false)
	P:Start({ cat[2] })
	check(_G.__lastSound == "e02_2.ogg",
		"a part-heard item resumes at the segment after the last one finished ("
		.. tostring(_G.__lastSound) .. ")")

	-- PAUSE keeps the place. There is no seek on this client, so resuming
	-- restarts the segment rather than dropping into the middle of it.
	check(P:Pause(), "it pauses")
	check(_G.__soundsPlaying() == 0, "with nothing left playing")
	check(P.state == "paused", "and says so")
	check(P:Resume() and P.state == "playing", "and picks up again")

	-- A TIMER THAT WAS CANCELLED MUST NOT FIRE. Skipping forward while a
	-- segment is playing leaves its "next one starts now" scheduled, and
	-- without cancelling it the skipped-to item is talked over a moment later.
	P:Stop()
	P:Start(queue)
	P:Next()
	local afterSkip = _G.__lastSound
	tick(60)
	check(_G.__soundsPlaying() == 1,
		"skipping does not leave the old segment's timer to start a second track")

	-- ONE TIMER IS THE WHOLE CHAIN, so there is a backstop behind it. Without a
	-- playback-finished event a lost timer means the programme stops dead and
	-- goes on saying "playing" - which is indistinguishable, from the outside,
	-- from a segment that simply did not start.
	P:Stop()
	P:Start(queue)
	check(_G.__lastSound == "e01_1.ogg", "a programme starts again")
	P.timer:Cancel()                           -- the timer, lost
	P.timer = nil
	tick(60)
	check(_G.__lastSound == "e01_1.ogg", "with its timer gone nothing follows on")
	tick(3)
	-- RECOVERED BY WHOEVER OWNS THE POLL, which is the fact worth checking now
	-- that there are two surfaces: on the ground it is the mini-player's own
	-- tick, in flight it is the console's region, and Poll refuses to fire twice
	-- for one segment precisely so the two cannot both take it. Asserting Poll
	-- answers true HERE meant asserting nobody else had already done the job.
	check(_G.__lastSound == "e01_2.ogg",
		"but the lost boundary is picked up anyway ("
		.. tostring(_G.__lastSound) .. ")")
	check(not P:Poll(), "and it does not fire twice for the same boundary")

	-- A CHUNKED TRACK, which is the only way to get a pause out of this client.
	-- A handle supports exactly one verb - stop - and stopping is destructive,
	-- so pause is synthesised from the chaining the console already does for
	-- chaptered episodes: cut the audio into three-second pieces and stop-and-
	-- remember costs at most one piece.
	R:Reset()
	cfg.progress = {}
	local chunks = {}
	for i = 1, 8 do
		chunks[i] = { file = "chunk_" .. i .. ".ogg", duration = 3 }
	end
	R:Register({ packId = "S02", apiVersion = 1, seasonIndex = 2, items = {
		{ id = "cut", type = "music", title = "Chunked", totalDuration = 24,
		  overlap = 0.25, segments = chunks },
	} })
	local cut = R:Catalogue()[1]

	P:Stop()
	P:Start({ cut })
	tick(3) tick(3)
	check(_G.__lastSound == "chunk_3.ogg",
		"the pieces chain like any other segments (" .. tostring(_G.__lastSound) .. ")")
	check(math.abs(P:Elapsed() - 6) < 0.2,
		"and the clock reads the whole track, not the piece ("
		.. string.format("%.1f", P:Elapsed()) .. ")")

	-- THE OUTGOING PIECE IS LEFT TO RUN OUT. Stopping it to start the next one
	-- is a hard cut mid-sample, which is the loudest kind of step there is and
	-- was half the click. Its tail carries a fade of its own and the incoming
	-- piece fades up through it, so for a quarter of a second there are two.
	check(_G.__soundsPlaying() == 2,
		"a crossfaded boundary leaves the outgoing piece playing under the"
		.. " incoming one (" .. _G.__soundsPlaying() .. ")")

	-- BOUNDED AT TWO. An hour of three-second pieces must not accumulate twelve
	-- hundred handles nobody ever silenced.
	tick(3) tick(3) tick(3)
	check(_G.__soundsPlaying() == 2,
		"and never more than two, however many boundaries go by ("
		.. _G.__soundsPlaying() .. ")")

	-- AND EVERYTHING THAT MEANS SILENCE REACHES BOTH. A single handle field
	-- would have leaked the one it had just overwritten.
	check(P:Pause(), "pausing")
	check(_G.__soundsPlaying() == 0,
		"silences both of them (" .. _G.__soundsPlaying() .. ")")
	check(P:Resume(), "and it resumes")
	check(_G.__soundsPlaying() == 1, "on one piece again")

	-- PAUSE COSTS AT MOST ONE PIECE. Resume restarts the piece it stopped in,
	-- because there is no seek - which is exactly why the pieces are short.
	local was = _G.__lastSound
	tick(1)
	check(P:Pause(), "it pauses")
	check(_G.__soundsPlaying() == 0, "with the channel silent")
	check(P:Resume(), "and resumes")
	check(_G.__lastSound == was,
		"from the piece it stopped in, losing a second of it at worst ("
		.. tostring(_G.__lastSound) .. ")")

	-- AND A SONG STILL STARTS FROM THE TOP. Sixty pieces instead of one means a
	-- stop halfway writes a real position, and without this a track would pick
	-- up two minutes in because that is where you landed last week - and would
	-- be dragged to the front of every programme until somebody finished it.
	P:Stop()
	check((C:Progress("S02:cut") or {}).segment > 0, "stopping writes where it got to")
	P:Start({ cut })
	check(_G.__lastSound == "chunk_1.ogg",
		"but a song starts again from the beginning ("
		.. tostring(_G.__lastSound) .. ")")

	-- AND IT IS NOT DRAGGED TO THE FRONT of the next programme either. The
	-- resume list exists so a half-finished EPISODE greets you; a song stopped
	-- at the two-minute mark qualifying for it means that song leads every
	-- flight until somebody sits through the end of it.
	R:Register({ packId = "S03", apiVersion = 1, seasonIndex = 3, items = {
		ep("fresh", "Something Unplayed", 2),
	} })
	-- Stopped part way IN, so there is a real position written down. Stopping on
	-- the first piece records nothing to be dragged forward by.
	tick(3) tick(3)
	P:Stop()
	local queue2 = C:Programme(600)
	check(queue2[1] and queue2[1].key == "S03:fresh",
		"an unplayed episode still leads (" .. tostring(queue2[1] and queue2[1].key) .. ")")
	check(C:Progress("S02:cut") ~= nil and (C:Progress("S02:cut").segment or 0) > 0,
		"with the part-played song still recorded as part-played")
	for i, q in ipairs(queue2) do
		if q.key == "S02:cut" then
			check(i > 1, "and sitting where the filler goes, not at the front (" .. i .. ")")
		end
	end

	P:Stop()
	R:Reset()
	cfg.progress = {}
	R:Register({ packId = "S00", apiVersion = 1, seasonIndex = 0, items = {
		ep("e01", "Episode One", 3),
		ep("e02", "Episode Two", 2),
		{ id = "amb", type = "music", title = "Ambient", totalDuration = 60,
		  segments = { { file = "amb.ogg", duration = 60 } } },
	} })
	cat = R:Catalogue()
	queue = { cat[1], cat[2], cat[3] }

	-- MUTED IS NOT SILENCE. willPlay comes back nil when the channel is off,
	-- and the difference between saying so and playing nothing is the
	-- difference between a console that explains itself and one that looks
	-- broken.
	P:Stop()
	_G.__musicMuted = true
	check(not P:Start(queue), "with the music channel muted, nothing starts")
	check(P.state == "muted", "and the state says why rather than 'playing'")
	_G.__musicMuted = false

	-- GOSSIP IS READ, NOT PLAYED. It occupies no time on the channel, so the
	-- programme steps past it rather than sitting in silence for its duration.
	R:Reset()
	R:Register({ packId = "S01", apiVersion = 1, seasonIndex = 1, items = {
		{ id = "news", type = "gossip", masthead = "ogler", title = "Spotted",
		  pages = { "mag\\page-01", "mag\\page-02" } },
		ep("e09", "After The News", 1),
	} })
	local c2 = R:Catalogue()
	P:Stop()
	P:Start({ c2[1], c2[2] })
	check(_G.__lastSound == "e09_1.ogg",
		"a gossip item does not hold the channel (" .. tostring(_G.__lastSound) .. ")")

	-- THE END OF THE PROGRAMME with flight remaining is the state the whole of
	-- v2 is designed around, so it is announced rather than simply stopping.
	P:Stop()
	heard = {}
	P:Start({ c2[2] })
	tick(60)
	local sawExhausted = false
	for _, e in ipairs(heard) do if e == "exhausted" then sawExhausted = true end end
	check(sawExhausted, "running out of programme is announced, not just silence")

	-- AND THE CHANNEL GOES QUIET WITH IT. Running off the end left the last
	-- track sounding while the state said exhausted, the clock read zero and the
	-- button showed play - a console insisting nothing was playing over the
	-- sound of something playing. Skipping past the last item was the fast way
	-- to see it and is how it was found.
	P:Stop()
	P:Start({ c2[2] })
	check(_G.__soundsPlaying() == 1, "an item is playing")
	P:Next()
	check(P.state == "exhausted", "skipping past the last item ends the programme")
	check(_G.__soundsPlaying() == 0,
		"and silences the channel rather than leaving it running ("
		.. _G.__soundsPlaying() .. " still going)")
	check(P.item == nil, "with nothing left to call the current item")

	-- A PROGRAMME COVERS THE FLIGHT, it is not everything there is: a short hop
	-- is filled by ONE track, so "next" had nowhere to go on most flights and
	-- ended the programme instead. Whoever built the queue is asked for more.
	P:Stop()
	local asked = 0
	P.refill = function()
		asked = asked + 1
		return asked == 1 and c2[2] or nil
	end
	P:Start({ c2[2] })
	P:Next()
	check(asked == 1, "the end of the queue asks for one more")
	check(P.state == "playing", "and plays it rather than ending (" .. P.state .. ")")
	P:Next()
	check(P.state == "exhausted", "and ends once there is genuinely nothing left")
	P.refill = nil

	-- EVERY OTHER STATE STILL HAS A PLAY BUTTON. Toggle handled two of the five
	-- and did nothing at all in the rest, so the transport went dead the moment
	-- anything went wrong - a file that would not play, a skip off the end, the
	-- client killing the sound while the window was in the background.
	check(P:Toggle(), "play restarts a programme that has run out")
	check(P.state == "playing", "which is playing again (" .. P.state .. ")")
	check(P:Toggle() and P.state == "paused", "and pauses from there as usual")
	check(P:Toggle() and P.state == "playing", "and back")

	-- AND THE GAME GETS ITS SOUND SETTINGS BACK. A silenced game is the worst
	-- thing this could leave behind: nothing on screen would say why. Put back
	-- on landing, and again on any world load that finds us holding them.
	P:Stop()
	check(_G.__cvars.Sound_EnableMusic == "1", "and the game's music comes back")

	-- THE BACKGROUND SETTING IS HELD TOO. Without it the client kills every
	-- sounding handle when the window loses focus and starts none of them again,
	-- and there is no focus event to recover from - so an alt-tab mid-flight
	-- came back to a programme that was silent with the clock still counting.
	_G.__cvars.Sound_EnableSoundWhenGameIsInBG = "0"
	P:Start({ c2[2] })
	check(_G.__cvars.Sound_EnableSoundWhenGameIsInBG == "1",
		"sound in the background is held on for the flight")
	P:Stop()
	check(_G.__cvars.Sound_EnableSoundWhenGameIsInBG == "0",
		"and handed back exactly as it was, not left on")
	check(_G.__badCVarWrites == 0,
		"and every name written is one the client has (" .. _G.__badCVarWrites .. " bad)")

	P:Start({ c2[2] })
	P.state = "stopped"                        -- a flight that ended unseen
	check(P:Recover(), "a setting still held with nothing playing is recoverable")
	check(_G.__cvars.Sound_EnableMusic == "1", "and recovering hands it back")

	-- A RELOAD IS NOT A STOP. Reloading throws away every Lua table in the addon
	-- - the sound handle with them - and does NOT touch the client's sound
	-- engine, so the track carried straight on with nothing left alive that knew
	-- how to stop it, and the next thing played played OVER it.
	P:Stop()
	_G.__cvars.Sound_EnableMusic = "1"
	P:Start({ c2[2] })
	check(_G.__soundsPlaying() == 1, "something is playing when the reload comes")
	fire("PLAYER_LOGOUT")
	check(_G.__soundsPlaying() == 0,
		"logging out or reloading silences it (" .. _G.__soundsPlaying() .. " left)")
	check(_G.__cvars.Sound_EnableMusic == "1",
		"and hands the sound settings back on the way past")
	check(cfg.held == nil or cfg.held.Sound_EnableMusic == nil,
		"with nothing left written down, so the next login has nothing to undo")

	-- A CLIENT THAT DIED ON THE GRIFFIN. What is held is written to the save
	-- file, so the next login can undo it - `_took` was a field on a live table,
	-- which made the one case this most needed to cover the one case it did
	-- nothing for: the game stayed silent, permanently, with nothing saying why.
	P:Stop()
	P:Start({ c2[2] })
	check(cfg.held and cfg.held.Sound_EnableMusic == "1",
		"what was taken is written down, not only remembered")
	P.state, P._took = "stopped", nil          -- the session that never came back
	_G.__cvars.Sound_EnableMusic = "0"
	check(_G.__soundsPlaying() == 1, "with its audio still going and nothing"
		.. " left alive that knows the handle")
	check(P:Recover(), "a fresh session still finds the settings it is holding")
	check(_G.__cvars.Sound_EnableMusic == "1", "and puts them back")

	-- AND CLEARS THE GHOST. The handle died with the session, so the channel
	-- enable is the only lever left: off stops what is on it, and it goes
	-- straight back on. Best effort, and only on the path that already knows
	-- something was left behind.
	check(_G.__soundsPlaying() == 0, "and silences what the last session left"
		.. " playing (" .. _G.__soundsPlaying() .. " left)")
	check(_G.__cvars.Sound_EnableAmbience == "1",
		"with the channel handed straight back on")

	P:Stop()
	cfg.progress = {}
	cfg.held = nil
	R:Reset()
end)

section("ifec: the player region, on the flight's own axis", function()
	local R, C, P = A.IFEC.Registry, A.IFEC.Content, A.IFEC.Playback
	local PL, Taxi, IF = A.IFEC.Player, A.IFEC.Taxi, A:GetModule("ifec")
	check(PL ~= nil, "the player region loaded")

	local zenWas = A:GetModule("zen").enabled
	A:SetModuleEnabled("zen", false)
	UIParent:SetAlpha(1)

	local cfg = A.Config:Module("ifec")
	cfg.progress = {}
	R:Reset()
	_G.__musicMuted = false
	Taxi:Start()

	local function fly()
		_G.__taxi.nodes = {
			{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
			{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
		}
		_G.__taxi.routes = {}
		TakeTaxiNode(2)
		_G.__onTaxi = true
		fire("PLAYER_CONTROL_LOST")
		tick(0.4)
	end
	local function land()
		_G.__onTaxi = false
		fire("PLAYER_CONTROL_GAINED")
		tick(0.4)
	end

	-- DORMANT IS ABSENT, not empty. With nothing installed the console lays out
	-- as though the player region had never existed.
	fly()
	check(not IF:HasRegion(), "with no content the console carries no player region")
	land()

	R:Register({ packId = "S00", apiVersion = 1, seasonIndex = 0, items = {
		{ id = "e1", type = "podcast", title = "Episode One", totalDuration = 30,
		  segments = { { file = "e1a.ogg", duration = 15 }, { file = "e1b.ogg", duration = 15 } } },
		{ id = "e2", type = "podcast", title = "Episode Two", totalDuration = 20,
		  segments = { { file = "e2.ogg", duration = 20 } } },
		-- LONGER THAN WHAT IS LEFT OF THE FLIGHT, deliberately. A programme is
		-- filled until it COVERS the flight, so the last item almost always
		-- overshoots - and that overshoot is what used to draw out of the side
		-- of the window. The ordinary case is the awkward one.
		{ id = "amb", type = "music", title = "Ambient", totalDuration = 120,
		  segments = { { file = "amb.ogg", duration = 120 } } },
	} })

	fly()
	check(IF:HasRegion(), "with content it appears, between flights and with no reload")
	local f = PL.frame
	check(f ~= nil and f:IsShown(), "and is shown")

	-- THE TWO BARS SHARE AN AXIS. That is the whole reason they are stacked: a
	-- landing line across both means the same instant on each.
	check(f.flight:GetWidth() == f.programme:GetWidth(),
		"the flight bar and the programme bar are the same width")
	check(math.abs(f.flight:XFor(34) - f.programme:XFor(34)) < 0.01,
		"so the same second is the same pixel on both")

	check(f.now.title:GetText() == "Episode One",
		"the now-playing row names what is playing (" .. tostring(f.now.title:GetText()) .. ")")
	-- AND NOT WHAT FOLLOWS IT. That is UP NEXT's job, four rows down, with a
	-- duration and a channel mark this line has no room for - and saying it here
	-- as well ran the row under the landing label on any real route.
	check(f.now.meta:GetText():find("then", 1, true) == nil,
		"and does not also name what follows (" .. tostring(f.now.meta:GetText()) .. ")")

	-- UP NEXT is what is COMING, so it starts after the thing playing rather
	-- than including it.
	check(f.rows[1]:IsShown() and f.rows[1].title:GetText() == "Episode Two",
		"up next starts after the current item (" .. tostring(f.rows[1].title:GetText()) .. ")")

	-- QUEUEING ANOTHER TRACK MAKES THE REGION TALLER, and the console has to
	-- be told. The row count IS the height - UP NEXT grows a row per queued
	-- item up to its cap - and the console keeps whatever height it was handed
	-- at AttachRegion, re-asserting it on every lay-out.
	--
	-- So drawing a row without saying so drew it into a frame that was still
	-- the old size, and it came out underneath the console. Reported from the
	-- game as picking an extra song and then folding the player away and
	-- bringing it back, which is the point it becomes impossible to miss.
	do
		-- A TRACK THAT IS NOT IN THE PROGRAMME. A programme is built to COVER the
		-- flight, so on this fixture it already holds everything installed - and a
		-- check that can find nothing to add is a check that quietly does nothing.
		R:Register({ packId = "S02", apiVersion = 1, seasonIndex = 2, items = {
			{ id = "spare", type = "music", title = "Spare Track",
				totalDuration = 60,
				segments = { { file = "spare.ogg", duration = 60 } } },
		} })

		local before = IF.frame.regionHeight
		local rowsBefore = 0
		for _, row in ipairs(f.rows) do
			if row:IsShown() then rowsBefore = rowsBefore + 1 end
		end

		-- Through the library, which is how a player picks one.
		local Lib = A.IFEC.Library
		local extra = nil
		for _, item in ipairs(A.IFEC.Content:Available() or {}) do
			local queued = false
			for _, q in ipairs(P.queue or {}) do
				if q.key == item.key then queued = true end
			end
			if not queued and item.type ~= "gossip" then extra = item end
		end

		check(extra ~= nil, "there is a track to add that is not already queued")
		if extra and Lib then
			Lib:Toggle(extra)
			local rowsAfter = 0
			for _, row in ipairs(f.rows) do
				if row:IsShown() then rowsAfter = rowsAfter + 1 end
			end
			check(rowsAfter > rowsBefore,
				"queueing another track draws another row into UP NEXT (" ..
				rowsBefore .. " to " .. rowsAfter .. ")")
			check(IF.frame.regionHeight > before,
				"and the console is told the region got taller (" ..
				tostring(before) .. " to " .. tostring(IF.frame.regionHeight) .. ")")
			check(math.abs(IF.frame.regionHeight - PL:Height()) < 0.01,
				"which is exactly what the region says it wants (" ..
				tostring(IF.frame.regionHeight) .. " vs " .. tostring(PL:Height())
				.. ")")

			-- AND FOLDING IT AWAY AND BACK KEEPS THAT, which is the sequence in
			-- the report: Lay re-asserts the STORED height, so a stale one shows
			-- up the moment the player is put away and brought back.
			IF:SetCollapsed(true)
			IF:SetCollapsed(false)
			check(math.abs(f:GetHeight() - PL:Height()) < 0.01,
				"and folding the player away and back leaves it the same height (" ..
				string.format("%.0f vs %.0f", f:GetHeight(), PL:Height()) .. ")")
			check(f.rows[rowsAfter]:GetBottom() >= f:GetBottom() - 0.5,
				"with the last row inside the frame rather than under it (" ..
				string.format("%.0f vs %.0f", f.rows[rowsAfter]:GetBottom(),
				f:GetBottom()) .. ")")
		end
	end
	-- IT COUNTS DOWN ON ITS OWN. Everything painted here is a countdown, and
	-- the only thing repainting it was a playback event - which happens once a
	-- minute at best. So the region sat frozen on whatever the last boundary
	-- said, and a segment that had in fact moved on looked like one that had
	-- stopped.
	local wasLanding, wasLeft = f.landingLabel:GetText(), f.now.meta:GetText()
	tick(3)
	check(f.landingLabel:GetText() ~= wasLanding,
		"the landing countdown moves between playback events ("
		.. tostring(wasLanding) .. " -> " .. tostring(f.landingLabel:GetText()) .. ")")
	check(f.now.meta:GetText() ~= wasLeft,
		"and so does the time left on what is playing ("
		.. tostring(f.now.meta:GetText()) .. ")")

	-- The transport says what pressing it will DO, not what is happening.
	check(f.transport.toggle.glyph:GetTexture() == A.Media.icons.file,
		"the transport is drawn from the shared sheet")
	P:Pause()
	PL:Paint()
	check(P.state == "paused", "pausing pauses")

	-- LANDING IS AN INSTANT ON BOTH BARS, drawn once.
	local _, _, _, lx = f.landing:GetPoint()
	check(lx ~= nil, "the landing line is placed along the axis")

	-- AND ABOVE THEM. A bar is a child frame and each piece is a child of that,
	-- so a mark drawn on the region itself sorts underneath all of it however
	-- high its draw layer. The landing line only ever showed because it fell
	-- exactly where the flight bar's one piece ended.
	check(f.marks:GetFrameLevel() > f.programme:GetFrameLevel(),
		"the landing line is drawn over the bars, not under them")

	-- ONE AXIS, LONG ENOUGH FOR BOTH. A programme is filled until it COVERS the
	-- flight, so it overshoots by up to one item. Against an axis of the
	-- flight's own length that overshoot ran out of the side of the window -
	-- and landing was always the far right edge, which is a border, not a mark.
	local queued = 0
	for _, item in ipairs(PL.queue or {}) do queued = queued + (item.duration or 0) end
	check(queued > (Taxi.flight.expected or 0),
		"this programme runs longer than its flight (" .. queued .. "s of "
		.. tostring(Taxi.flight.expected) .. "s), which is the case that overflowed")
	-- MEASURED ON THE PIECES, not with XFor. XFor clamps to the bar, so it can
	-- never report an overrun; the pieces are what actually drew past the edge.
	local far = 0
	for _, part in ipairs(f.programme.parts) do
		if part:IsShown() then
			local _, _, _, x = part:GetPoint()
			far = math.max(far, (x or 0) + (part:GetWidth() or 0))
		end
	end
	check(far > 0 and far <= f.programme:GetWidth() + 0.01,
		"and the whole of it still lands inside the bar (" .. far .. " of "
		.. f.programme:GetWidth() .. ")")
	check(f.flight:XFor(Taxi.flight.expected) < f.flight:GetWidth() - 1,
		"with landing marked short of the end, where it can be seen")

	check(f.fills:GetText():find("programme fills", 1, true) ~= nil,
		"and the headline says how much of the flight is filled ("
		.. tostring(f.fills:GetText()) .. ")")

	check(#(f.legs or {}) == 0 or not f.legs[1]:IsShown(),
		"a single-hop flight has no stopover to mark")
	land()

	-- THE BRASS TICKS. A leg boundary is an INSTANT, so it is drawn over the
	-- flight bar rather than being a piece of it - and over, not under: the bar
	-- is a child frame and each piece is a child of that.
	_G.__taxi.nodes = {
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
		{ name = "Orgrimmar, Durotar",      kind = "REACHABLE" },
	}
	_G.__taxi.routes = { [3] = { 2, 3 } }
	TakeTaxiNode(3)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)

	check(f.legs and f.legs[1] and f.legs[1]:IsShown(),
		"a two-leg journey marks the stopover on the flight bar")
	check(not (f.legs[2] and f.legs[2]:IsShown()),
		"and only the stopover - the last boundary is landing, which is drawn"
		.. " already and would be saying it twice")

	-- THE TICK IS WHERE THE LEG ENDS, which is only worth drawing because the
	-- route table stores single hops and a journey is the sum of them.
	local _, _, _, tx = f.legs[1]:GetPoint()
	local want = f.flight:XFor(Taxi.flight.legs[1].at)
	check(math.abs((tx or 0) - want) < 0.01,
		"at the second the first leg ends (" .. tostring(tx) .. " vs " .. want .. ")")

	-- AND IT FOLLOWS THE BAR. The tick is placed in PIXELS off the bar's
	-- width, and the bar does change width - it settles about forty units
	-- narrower as the console opens, which was measured rather than guessed.
	-- Nothing repainted the ticks when it did, so the boundary between two
	-- legs sat wherever the bar used to end: a mark claiming the stopover is
	-- somewhere it is not.
	local wide = f.flight:GetWidth()
	f.flight:SetWidth(wide * 0.75)
	local _, _, _, moved = f.legs[1]:GetPoint()
	local wantNarrow = f.flight:XFor(Taxi.flight.legs[1].at)
	check(math.abs((moved or 0) - wantNarrow) < 0.01,
		"and moves with the bar when it is resized under it (" ..
		tostring(moved) .. " vs " .. wantNarrow .. ")")
	f.flight:SetWidth(wide)

	-- THE REGION GOES WITH THE FLIGHT. Landing takes it away and stops the
	-- audio; nothing is left playing over somebody who has control back.
	land()
	check(not IF:HasRegion(), "landing takes the region away")
	check(_G.__soundsPlaying() == 0, "and stops the audio")

	-- SKIPPING HAS SOMEWHERE TO GO. A programme is filled until it COVERS the
	-- flight, which on a short hop is a single item - so "next" ran off the end
	-- of a one-item queue and ended the programme, which is a skip button that
	-- stops the music. It asks for more instead.
	R:Reset()
	cfg.progress = {}
	R:Register({ packId = "S00", apiVersion = 1, seasonIndex = 0, items = {
		{ id = "long", type = "music", title = "The Long One", totalDuration = 600,
		  segments = { { file = "long.ogg", duration = 600 } } },
		{ id = "other", type = "music", title = "The Other One", totalDuration = 600,
		  segments = { { file = "other.ogg", duration = 600 } } },
	} })

	fly()
	check(#(PL.queue or {}) == 1, "one long track covers this flight on its own ("
		.. #(PL.queue or {}) .. " queued)")

	-- WHAT AN ITEM ACTUALLY GOT. Skip twenty seconds in and the track occupied
	-- twenty seconds, not the ten minutes it was going to - and this bar is a
	-- timeline, so drawn at full length everything after it sat in the wrong
	-- place and the headline announced a queue filling 6:30 of a 4:09 flight.
	tick(20)
	local before = f.fills:GetText()
	f.transport.next:GetScript("OnClick")(f.transport.next)
	check(P:Spent(1, PL.queue[1]) < 60, "a skipped item is measured by what it played ("
		.. string.format("%.0f", P:Spent(1, PL.queue[1])) .. "s of 600s)")
	check(f.fills:GetText() ~= before, "so the headline moves when you skip ("
		.. tostring(before) .. " -> " .. tostring(f.fills:GetText()) .. ")")

	check(#(PL.queue or {}) == 2, "skipping past it pulls another out of the season")

	-- MEASURED ON THE PIECES, which is what actually drew wrong. Both items are
	-- ten minutes long, so at full length they are the same width; the one that
	-- got twenty seconds has to be a sliver beside the one that is playing.
	local w1 = f.programme.parts[1]:GetWidth() or 0
	local w2 = f.programme.parts[2]:GetWidth() or 0
	check(w1 < w2 / 4, "and the skipped item is drawn at what it played, not what"
		.. " it was going to (" .. string.format("%.0f", w1) .. " vs "
		.. string.format("%.0f", w2) .. ")")
	check(P.state == "playing" and _G.__lastSound == "other.ogg",
		"and plays it (" .. P.state .. ", " .. tostring(_G.__lastSound) .. ")")
	check(not PL.complete, "so the programme has not ended")

	-- AND WHEN THERE GENUINELY IS NOTHING LEFT, the complete state - which was
	-- built, and then never shown by anything. A programme that ran out left the
	-- last item's row on screen still counting down a track that had stopped.
	local tall = f:GetHeight()
	f.transport.next:GetScript("OnClick")(f.transport.next)
	check(PL.complete, "running out for real ends the programme")
	check(f.done:IsShown(), "the complete line is shown")
	check(f.chips[1]:IsShown() and f.chips[1].label:GetText() == "Ambient shuffle",
		"with the default action first ("
		.. tostring(f.chips[1].label:GetText()) .. ")")
	check(f.chips[1].__aetherSelected and not f.chips[3].__aetherSelected,
		"drawn filled, the way a selected tab is, and only that one")
	check(f.chips[2].label:GetText():find("Replay", 1, true) ~= nil,
		"replay names what it would replay (" .. tostring(f.chips[2].label:GetText()) .. ")")
	check(not f.now:IsShown() and not f.transport:IsShown(),
		"and everything belonging to a running programme is put away")
	check(not f.rows[1]:IsShown(), "up next included")

	-- A DIFFERENT HEIGHT, so the console has to be told rather than only
	-- repainted: one line and three chips floating in a panel four times too
	-- tall is what painting alone gave.
	check(f:GetHeight() < tall, "the region shrinks to fit it ("
		.. f:GetHeight() .. " from " .. tall .. ")")

	-- THE DEFAULT ACTION, ONE PRESS. Never dump the player into dead silence
	-- over the Barrens is the design's phrase for the whole state.
	f.chips[1]:GetScript("OnClick")(f.chips[1])
	check(not PL.complete, "the ambient shuffle starts the music again")
	check(P.state == "playing", "and it is playing (" .. P.state .. ")")
	check(f.now:IsShown() and f.done:IsShown() == false,
		"with the running programme back and the complete line gone")
	check(f:GetHeight() > tall - 1, "and the region grown back to fit it")

	land()

	-- A SKIP SHORTENS THE PROGRAMME as well as advancing it: the track that was
	-- going to fill the journey filled twenty seconds, and what covered the
	-- flight now stops short of it. Left alone, one skip emptied UP NEXT and the
	-- console showed a heading with nothing under it while a track was playing.
	R:Reset()
	cfg.progress = {}
	local many = {}
	for i = 1, 5 do
		many[i] = { id = "t" .. i, type = "music", title = "Track " .. i,
			totalDuration = 60, segments = { { file = "t" .. i .. ".ogg", duration = 60 } } }
	end
	R:Register({ packId = "S00", apiVersion = 1, seasonIndex = 0, items = many })

	fly()
	-- A LONG FLIGHT, STATED rather than inferred. The estimate comes from route
	-- data and from what earlier flights actually took, so a check that depends
	-- on it silently changes meaning when either of those does.
	Taxi.flight.expected = 200
	PL:TopUp()
	PL:Paint()

	local covered = #(PL.queue or {})
	check(covered >= 3, "a programme of short tracks is filled to cover the flight ("
		.. covered .. " queued)")
	check(f.upNextLabel:IsShown() and f.rows[1]:IsShown(), "so there is an up next")

	tick(5)
	f.transport.next:GetScript("OnClick")(f.transport.next)
	check(#(PL.queue or {}) > covered,
		"skipping tops the queue back up to covering the flight ("
		.. #(PL.queue or {}) .. " from " .. covered .. ")")
	check(f.rows[1]:IsShown(), "so up next still has something in it")
	check(f.rows[1].title:GetText() ~= (Playback and Playback.item or {}).title,
		"and it is not the thing that is playing")

	-- A HEADING WITH NOTHING UNDER IT reads as a list that failed to load.
	local was = PL.queue
	PL.queue = { was[PL.at] }
	PL.at = 1
	PL:Paint()
	check(not f.upNextLabel:IsShown(),
		"with genuinely nothing next, the heading goes too")
	PL.queue = was

	land()

	-- THE LIBRARY. A slide-out on the side of the console, because there are
	-- three kinds of content and the transport can only say "not this one".
	R:Reset()
	cfg.progress = {}
	R:Register({ packId = "S01", apiVersion = 1, seasonIndex = 1, displayName = "Season One",
		items = {
			{ id = "m1", type = "music", title = "Big Drum Deep Water",
			  artist = "The Mudfoot Kings", totalDuration = 60,
			  segments = { { file = "m1.ogg", duration = 60 } } },
			{ id = "m2", type = "music", title = "Blood and Thunder",
			  totalDuration = 60, segments = { { file = "m2.ogg", duration = 60 } } },
			{ id = "p1", type = "podcast", title = "The Gadgeteer",
			  totalDuration = 60, segments = { { file = "p1.ogg", duration = 60 } } },
		} })

	fly()
	local LB = A.IFEC.Library
	check(LB ~= nil, "the library loaded")
	check(IF.frame.library:IsShown(), "and the console carries the control that opens it")
	check(not LB:IsOpen(), "shut to begin with")

	IF.frame.library:GetScript("OnClick")(IF.frame.library)
	check(LB:IsOpen(), "the control opens it")
	local lib = LB.frame

	-- A CHILD OF THE CONSOLE, not a window of its own. The interface is at zero
	-- alpha for the whole flight, so anything under UIParent is drawn at
	-- nothing - and anything merely anchored to the console would have to be
	-- moved, scaled and hidden alongside it forever.
	check(lib:GetParent() == IF.frame, "as a child of the console, not a window")

	-- EVERYTHING IN SEASON, under its season.
	local listed, heads = 0, 0
	for _, row in ipairs(lib.rows) do if row:IsShown() then listed = listed + 1 end end
	for _, h in ipairs(lib.headings) do if h:IsShown() then heads = heads + 1 end end
	check(listed == 3, "every item in season is listed (" .. listed .. " of 3)")
	check(heads == 1, "under one heading for the pack it came from (" .. heads .. ")")
	check(lib.headings[1].text:GetText() == "SEASON ONE",
		"named after the pack (" .. tostring(lib.headings[1].text:GetText()) .. ")")

	-- The artist belongs to the title here: there is no second line, and the
	-- title alone is half a name.
	local sawArtist = false
	for _, row in ipairs(lib.rows) do
		if row:IsShown() and row.title:GetText():find("Mudfoot", 1, true) then
			sawArtist = true
		end
	end
	check(sawArtist, "with the artist beside the title")

	-- CLICKING QUEUES IT, and says so.
	local target
	for _, row in ipairs(lib.rows) do
		if row:IsShown() and not row.__aetherSelected then target = row break end
	end
	check(target ~= nil, "something in the list is not already queued")
	local wasLen = #PL.queue
	target:GetScript("OnClick")(target)
	check(#PL.queue == wasLen + 1, "clicking it adds it to the programme ("
		.. #PL.queue .. " from " .. wasLen .. ")")
	check(target.__aetherSelected, "and the row is drawn as the selected thing it now is")
	check(target.meta:GetText() == "queued", "saying so in words ("
		.. tostring(target.meta:GetText()) .. ")")
	check(P.picked[target.item.key], "recorded as the player's own pick")
	-- KEYED ON OUR OWN SET, never written onto the item: the registry hands the
	-- same table to everybody, so a flag set here outlives the flight.
	check(target.item.picked == nil, "and nothing is written onto the registry's item")

	-- AND CLICKING AGAIN TAKES IT BACK OUT.
	target:GetScript("OnClick")(target)
	check(#PL.queue == wasLen, "clicking again removes it (" .. #PL.queue .. ")")
	check(not P.picked[target.item.key], "and it is no longer a pick")

	-- NO ROW IS EVER DEAD. A click means "take it out" on something still to
	-- come and "again" on everything else - what is playing, and what has been
	-- played or skipped past. The queue keeps its history so the programme bar
	-- can draw a timeline, which is what left a skipped track drawn filled and
	-- refusing to be clicked: a toggle stuck on with no way to clear it.
	local playing
	for _, row in ipairs(lib.rows) do
		if row:IsShown() and row.meta:GetText() == "playing" then playing = row end
	end
	check(playing ~= nil, "the row that is playing says so")
	local held = #P.queue
	playing:GetScript("OnClick")(playing)
	check(#P.queue == held + 1, "and clicking it queues it again rather than"
		.. " doing nothing (" .. #P.queue .. " from " .. held .. ")")
	check(P.queue[#P.queue].key == playing.item.key, "at the end, not over the top"
		.. " of what is sounding")
	playing:GetScript("OnClick")(playing)
	check(#P.queue == held, "and clicking once more takes that repeat back out")

	-- A SKIPPED TRACK IS CLICKABLE AGAIN, which is the bug this rule exists for.
	local first = P.queue[1]
	P:Next()
	LB:Paint()
	local skipped
	for _, row in ipairs(lib.rows) do
		if row:IsShown() and row.item.key == first.key then skipped = row end
	end
	check(skipped ~= nil, "the skipped track is still in the list")
	check(not skipped.__aetherSelected,
		"no longer drawn as something coming up, because it is not")
	local before = #P.queue
	skipped:GetScript("OnClick")(skipped)
	check(#P.queue == before + 1, "and clicking it queues it again ("
		.. #P.queue .. " from " .. before .. ")")
	skipped:GetScript("OnClick")(skipped)
	check(#P.queue == before, "and again to take it back out")

	-- THE FILTERS say only what is true: three channels are declared and two are
	-- installed, so gossip has no tab.
	check(lib.tabs[1]:IsShown() and lib.tabs[2]:IsShown() and lib.tabs[3]:IsShown(),
		"a season of two channels gets All and one tab each")
	check(not lib.tabs[4]:IsShown(), "and no tab for the channel nobody shipped")

	lib.tabs[3]:GetScript("OnClick")(lib.tabs[3])       -- music
	local musicOnly = 0
	for _, row in ipairs(lib.rows) do
		if row:IsShown() then musicOnly = musicOnly + 1 end
	end
	check(musicOnly == 2, "filtering to one channel shows only that one ("
		.. musicOnly .. " of 2)")
	check(lib.tabs[3].__aetherSelected, "with its tab filled, the way a selected tab is")
	lib.tabs[1]:GetScript("OnClick")(lib.tabs[1])       -- back to all

	-- IT GOES WITH THE FLIGHT. A drawer left open over the world after landing
	-- is a window nothing on screen explains.
	land()
	check(not LB:IsOpen(), "landing shuts the drawer")

	Taxi:Stop()
	IF:HideInterface(false)
	R:Reset()
	cfg.progress = {}
	A:SetModuleEnabled("zen", zenWas)
end)

section("nifec: the mini-player, on the ground", function()
	local R, C, P = A.IFEC.Registry, A.IFEC.Content, A.IFEC.Playback
	local M, LB   = A.IFEC.Mini, A.IFEC.Library
	local TBm     = A:GetModule("toolbox")
	local IF      = A:GetModule("ifec")
	check(M ~= nil, "the mini-player loaded")

	local cfg = A.Config:Module("ifec")
	cfg.progress = {}
	R:Reset()
	P:Stop()
	_G.__musicMuted = false

	UIParent:SetSize(1365, 768)
	A.db.profile.scale = 0.71
	TBm:SetDock("LEFT")
	TBm:SetOpen(true, true)

	-- DORMANT IS ABSENT, not empty - the same answer the console gives, because
	-- it is the same question. A NOW PLAYING heading over a player with nothing
	-- to play is a section you go looking for and find broken.
	TBm:LayoutContent()
	check(not TBm:HasPlayer(), "with no content installed there is no player")
	check(not TBm.rail.play:IsShown(), "and no transport on the rail")
	check(not (TBm.content.now and TBm.content.now:IsShown()),
		"and no section at the foot of the drawer")

	local season = { packId = "S01", apiVersion = 1, seasonIndex = 1,
		displayName = "Season One", items = {
			{ id = "m1", type = "music", title = "Big Drum Deep Water",
			  artist = "The Mudfoot Kings", totalDuration = 60,
			  segments = { { file = "m1.ogg", duration = 60 } } },
			{ id = "m2", type = "music", title = "Blood and Thunder",
			  totalDuration = 60, segments = { { file = "m2.ogg", duration = 60 } } },
			{ id = "p1", type = "podcast", title = "The Gadgeteer",
			  totalDuration = 60, segments = { { file = "p1.ogg", duration = 60 } } },
			{ id = "g1", type = "gossip", masthead = "ogler",
			  title = "The Orgrimmar Ogler - Issue 37",
			  pages = { "ogler_037\\page-01", "ogler_037\\page-02",
			            "ogler_037\\page-03" } },
		} }
	R:Register(season)

	TBm:Layout()
	TBm:LayoutContent()
	check(TBm:HasPlayer(), "installing a season gives the Toolbox a player")
	check(TBm.rail.play:IsShown(), "with a transport on the rail, reachable"
		.. " with the drawer shut")
	local mini = TBm.content.now
	check(mini ~= nil and mini:IsShown(), "and a section at the foot of the drawer")

	-- IT FITS. The drawer cuts its lists to fit rather than growing, and a new
	-- fixed-cost section at the bottom is exactly the thing that pushes them
	-- through the floor - which is the one failure this file keeps having.
	check(TBm._contentHeight <= TBm.panel:GetHeight() + 0.5,
		"and the whole drawer still fits inside the panel ("
		.. string.format("%.0f", TBm._contentHeight) .. " of "
		.. string.format("%.0f", TBm.panel:GetHeight()) .. ")")

	-- AND IT FITS AT EVERY SCALE AND EVERY DOCK. The vertical panel clamps to a
	-- proportion of the screen, so at scale 1.0 it is a third shorter than at
	-- the design's 0.71 - and a fixed-cost section added at the bottom is
	-- exactly what pushes the lists that give way through the floor. The flat
	-- panel is the other shape: a sixth column, on a drawer whose short axis is
	-- the one the section has to fit in.
	for _, sc in ipairs({ 0.71, 1 }) do
		for _, edge in ipairs({ "LEFT", "RIGHT", "TOP", "BOTTOM" }) do
			A.db.profile.scale = sc
			TBm:SetDock(edge)
			TBm:SetOpen(true, true)
			TBm:RefreshWidgets(); TBm:RefreshTiles()
			TBm:RefreshAddons(); TBm:RefreshMicro()
			check(TBm._contentHeight <= TBm.panel:GetHeight() + 0.5,
				("at scale %s docked %s the drawer with a player still fits (%.0f of %.0f)")
				:format(sc, edge, TBm._contentHeight, TBm.panel:GetHeight()))
		end
	end
	A.db.profile.scale = 0.71
	TBm:SetDock("LEFT")
	TBm:SetOpen(true, true)
	TBm:LayoutContent()
	mini = TBm.content.now

	-- SILENCE HAS SOMETHING TO SAY. A blank line where a title goes reads as a
	-- player that failed rather than one that is waiting to be told.
	M:Paint()
	check(mini.title:GetText() == "Nothing playing",
		"with nothing playing it says so (" .. tostring(mini.title:GetText()) .. ")")
	check(mini.meta:GetText():find("play", 1, true) ~= nil,
		"and what pressing play will do (" .. tostring(mini.meta:GetText()) .. ")")

	-- PLAY MEANS PLAY FROM A STANDING START. On the ground there is no
	-- programme yet, and a play button that does nothing on the first press is
	-- a broken one.
	mini.toggle:GetScript("OnClick")(mini.toggle)
	check(P:IsPlaying(), "pressing play with nothing queued starts the music")
	check(#(P.queue or {}) > 0 and P.item ~= nil, "off a queue it built itself")

	-- THE AMBIENT SHUFFLE IS MUSIC. Pressing play should not start an episode
	-- nobody asked for.
	local anyTalk = false
	for _, q in ipairs(P.queue) do if q.type ~= "music" then anyTalk = true end end
	check(not anyTalk, "and it is music, not whatever came first in the season")

	M:Paint()
	check(mini.title:GetText() == P.item.title,
		"the region names what is playing (" .. tostring(mini.title:GetText()) .. ")")
	if P.item.artist then
		check(mini.meta:GetText():find(P.item.artist, 1, true) ~= nil,
			"with the artist on it (" .. tostring(mini.meta:GetText()) .. ")")
	end

	-- THE RAIL CHIP IS THE SAME TRANSPORT, and the only thing on screen saying
	-- anything is playing at all with the drawer shut.
	TBm.rail.play:GetScript("OnClick")(TBm.rail.play)
	check(P.state == "paused", "the rail chip pauses it (" .. P.state .. ")")
	TBm.rail.play:GetScript("OnClick")(TBm.rail.play)
	check(P.state == "playing", "and starts it again")

	-- THE RAIL, IN ORDER. The two settled controls sit at the far end together:
	-- the way to the options, and the way to stop the music.
	do
		-- CHECKED ON THE ANCHORS, which is what the layout actually decides. The
		-- chain has to be built from what is SHOWING: anchored to a hidden frame
		-- the envelope keeps the geometry that frame would have had, so a season
		-- nobody installed leaves an icon's worth of hole in the rail.
		local _, playRel = TBm.rail.play:GetPoint()
		local _, mailRel = TBm.rail.mail:GetPoint()
		check(playRel == TBm.rail.gear,
			"the transport sits immediately above the gear")
		check(mailRel == TBm.rail.play, "with the envelope above it")

		R:Reset()
		TBm:Layout()
		local _, bare = TBm.rail.mail:GetPoint()
		check(not TBm.rail.play:IsShown() and bare == TBm.rail.gear,
			"and with no content the envelope closes the gap rather than"
			.. " anchoring to a chip that is not there")
		R:Register(season)
		TBm:Layout()
		TBm:LayoutContent()
	end

	-- GOSSIP IS READ, NOT PLAYED. It has no audio and no duration, so it has no
	-- place in a running order - it used to be queued and stepped straight past,
	-- which put a bulletin in UP NEXT as something about to happen.
	do
		local full = C:Everything()
		local sawGossip = false
		for _, q in ipairs(full) do if q.type == "gossip" then sawGossip = true end end
		check(not sawGossip, "no programme ever contains a bulletin")
		check(P:Pick({ key = "S01:g1", type = "gossip" }) == nil,
			"and it cannot be picked into one")
	end

	-- ONE LIBRARY, TWO HOSTS. It hangs off whatever opened it, or it is drawn at
	-- zero alpha in flight and off the bottom of the screen on the ground.
	mini.library:GetScript("OnClick")(mini.library)
	check(LB:IsOpen(), "the mini-player opens the library")
	check(LB.frame:GetParent() == mini,
		"hung off the mini-player, not off the console")

	-- Clicking a row queues into the SAME programme the console would use.
	local row
	for _, r in ipairs(LB.frame.rows) do
		if r:IsShown() and not r.__aetherSelected then row = r break end
	end
	check(row ~= nil, "the list has something not already queued")
	local was = #P.queue
	row:GetScript("OnClick")(row)
	check(#P.queue == was + 1, "and clicking it queues into the running programme")

	-- AND THE TOOLTIP COMES UP IN FRONT. It is a shared object anything can
	-- reparent and this addon does exactly that - the console moves it out of
	-- UIParent for a flight so it can be read over a hidden interface. Left
	-- somewhere else it draws under the chat log, which is where it was found.
	do
		local chip = TBm.rail.play
		GameTooltip:Hide()
		GameTooltip:SetFrameStrata("BACKGROUND")     -- as something else left it
		chip:GetScript("OnEnter")(chip)
		check(GameTooltip:IsShown(), "hovering the chip raises a tooltip")
		check(GameTooltip:GetFrameStrata() == "TOOLTIP",
			"in front of everything, whatever it was left at ("
			.. tostring(GameTooltip:GetFrameStrata()) .. ")")
		chip:GetScript("OnLeave")(chip)
		check(not GameTooltip:IsShown(), "and goes again")
	end

	-- THE REST OF THE TRANSPORT, ON A RIGHT-CLICK. The chip is one icon wide and
	-- the whole point of it is not opening the drawer, so the three controls
	-- that do not fit go on a menu rather than nowhere.
	do
		local chip = TBm.rail.play
		A.Widgets.CloseMenu()
		chip:GetScript("OnClick")(chip, "RightButton")
		local menu = A.Widgets.MenuFrame()
		check(menu and menu:IsShown(), "right-clicking the chip opens a menu")
		local words = {}
		for i = 1, 3 do words[i] = menu.items[i].text:GetText() end
		check(table.concat(words, ",") == "Stop,Previous,Next",
			"with stop, previous and next on it (" .. table.concat(words, ",") .. ")")

		-- AND LEFT-CLICK STILL PLAYS. A button that grew a menu and lost its
		-- press is a worse button.
		A.Widgets.CloseMenu()
		local was = P.state
		chip:GetScript("OnClick")(chip, "LeftButton")
		check(P.state ~= was, "and left-clicking still works the transport ("
			.. was .. " -> " .. P.state .. ")")
		if not P:IsPlaying() then chip:GetScript("OnClick")(chip, "LeftButton") end

		-- STOP STOPS.
		chip:GetScript("OnClick")(chip, "RightButton")
		menu = A.Widgets.MenuFrame()
		menu.items[1]:GetScript("OnClick")(menu.items[1])
		check(P.state == "stopped", "stop stops it (" .. P.state .. ")")
		check(_G.__soundsPlaying() == 0, "and silences the channel")

		-- DISABLED RATHER THAN ABSENT with nothing to do: a menu that changes
		-- shape between openings is one you cannot learn.
		chip:GetScript("OnClick")(chip, "RightButton")
		menu = A.Widgets.MenuFrame()
		check(menu.items[1].action == nil, "with nothing playing, stop is dead")
		check(menu.items[1]:IsShown(), "and still on the menu, not missing from it")
		A.Widgets.CloseMenu()

		mini.toggle:GetScript("OnClick")(mini.toggle)
	end

	-- AND IT OPENS AWAY FROM THE DRAWER'S OWN BODY. "Beside the host" is only
	-- right while the host sits at a screen edge with open screen next to it.
	-- Docked ACROSS THE TOP the mini-player is one column of a wide strip, and
	-- beside it is the middle of that strip - the list opened over the settings
	-- tiles it had just come out from under.
	do
		local want = { LEFT = "BOTTOMLEFT", RIGHT = "BOTTOMRIGHT",
		               TOP = "TOPRIGHT", BOTTOM = "BOTTOMRIGHT" }
		local rel  = { LEFT = "BOTTOMRIGHT", RIGHT = "BOTTOMLEFT",
		               TOP = "BOTTOMRIGHT", BOTTOM = "TOPRIGHT" }
		for _, edge in ipairs({ "LEFT", "RIGHT", "TOP", "BOTTOM" }) do
			TBm:SetDock(edge)
			TBm:SetOpen(true, true)
			TBm:LayoutContent()
			LB:SetOpen(true, TBm.content.now)

			local p1, relTo, p2 = LB.frame:GetPoint(1)
			check(p1 == want[edge] and p2 == rel[edge] and relTo == TBm.content.now,
				("docked %s the list opens %s of the player (%s to %s)")
				:format(edge, edge == "TOP" and "below" or
					(edge == "BOTTOM" and "above" or "beside"), p1, p2))
			check(LB.frame:GetNumPoints() == 1,
				"anchored once, not left spanned between the last corner and this one")
		end

		TBm:SetDock("LEFT")
		TBm:SetOpen(true, true)
		TBm:LayoutContent()
		mini = TBm.content.now
		LB:SetOpen(true, mini)
	end

	-- THE LIBRARY GOES WITH THE DRAWER. It hangs off the mini-player at the foot
	-- of the panel and slides away with it - but off the RIGHT of that, so a
	-- panel a full width off screen left the list sitting just inside the edge
	-- with nothing behind it.
	do
		check(LB:IsOpen(), "the library is open")
		TBm:SetOpen(false, true)
		check(not LB:IsOpen(), "closing the drawer shuts the list with it")
		TBm:SetOpen(true, true)
		LB:SetOpen(true, mini)
	end

	-- A READING FILL, not the control-surface one: a column of titles read over
	-- whatever the world is doing behind it, which is the argument the quest log
	-- and the chat log already make.
	do
		local want = A.Palette:ReadingFill()[4] or 1
		local plain = (A.Palette.c.glassStrong or A.Palette.c.glass)[4] or 1
		local got = (LB.frame._fillColor or {})[4] or 0
		check(math.abs(got - want) < 0.001,
			("the list is at the readable opacity (%.2f of %.2f)"):format(got, want))
		-- The two have to DIFFER, or this passes on a profile where the boost is
		-- zero and proves only that a number equals itself.
		check(math.abs(want - plain) > 0.001,
			("and that is deeper than a control surface (%.2f against %.2f)")
			:format(want, plain))

		-- AND SO IS THE PAPER. The page is opaque, but the margin around it and
		-- the strip under it are not, and a border you can see the world through
		-- is a page that looks like it is floating.
		local RDb = A.IFEC.Reader
		RDb:Build()
		local paper = (RDb.frame._fillColor or {})[4] or 0
		check(math.abs(paper - want) < 0.001,
			("the paper is too (%.2f of %.2f)"):format(paper, want))
	end

	-- THE MAGAZINE OPENS, it does not queue. You read the paper while the music
	-- carries on, which is the whole point of it having no duration.
	do
		local RD = A.IFEC.Reader
		check(RD ~= nil, "the reader loaded")

		local gossip
		for _, r in ipairs(LB.frame.rows) do
			if r:IsShown() and r.item.type == "gossip" then gossip = r end
		end
		check(gossip ~= nil, "the bulletin is in the list with everything else")
		check(gossip.meta:GetText() == "3 pages", "unread, saying how long it is ("
			.. tostring(gossip.meta:GetText()) .. ")")
		check(not gossip.__aetherSelected,
			"and never drawn as something cued, because it cannot be")

		local held = #P.queue
		local wasPlaying = P.item and P.item.key
		gossip:GetScript("OnClick")(gossip)
		check(RD:IsOpen(), "clicking it opens the paper")
		check(#P.queue == held, "and queues nothing (" .. #P.queue .. ")")
		check(P.item and P.item.key == wasPlaying,
			"with the music carrying on underneath it")
		-- NOT HUNG OFF THE LIST, unlike the drawer itself. A page is authored at
		-- 1024 and wants the screen; beside the Toolbox it would be mostly off
		-- the edge of it. Outside UIParent too, so it survives the interface
		-- being hidden at altitude.
		check(RD.frame:GetParent() == IF:Top(),
			"the paper is its own window, outside the interface it has to survive")
		-- MEASURED IN PHYSICAL PIXELS, at both ends. The window is under a
		-- parentless holder so that it survives the interface being hidden,
		-- which means it does NOT share UIParent's scale - so asking UIParent
		-- how big the screen is and then drawing that many units HERE is asking
		-- one ruler and cutting with another. It hung off the top of the screen.
		--
		-- Swept rather than checked once, because the two directions fail at
		-- different scales and a single scale is a coin toss between them.
		local function px(frame)
			local sc = frame:GetEffectiveScale() or 1
			return (frame:GetWidth() or 0) * sc, (frame:GetHeight() or 0) * sc
		end
		local uiWas = UIParent:GetScale() or 1
		local profWas = A.db.profile.scale
		for _, uiScale in ipairs({ 0.53, 0.64, 1, 1.875 }) do
			for _, prof in ipairs({ 0.71, 1 }) do
				UIParent:SetScale(uiScale)
				A.db.profile.scale = prof
				RD:Size()
				local w, h = px(RD.frame)
				local sw, sh = px(UIParent)
				check(w <= sw and h <= sh,
					("at UI scale %s and profile %s the page fits (%.0fx%.0f of %.0fx%.0f)")
					:format(uiScale, prof, w, h, sw, sh))
			end
		end

		-- IT FOLLOWS THE GLOBAL SCALE, like every window of ours.
		UIParent:SetScale(1)
		A.db.profile.scale = 0.71
		RD:Size()
		check(math.abs((RD.frame:GetScale() or 1) - 0.71) < 0.001,
			"the paper is at the profile's scale like everything else ("
			.. tostring(RD.frame:GetScale()) .. ")")

		-- AND ACTUAL SIZE STILL MEANS ACTUAL SIZE. The window shrinks with the
		-- profile, so a page of 1024 units is 727 pixels at 0.71 - a "1:1" that
		-- is nothing of the kind. Zoomed, the art lands one texel to one pixel.
		RD:SetZoomed(true)
		local pw = px(RD.frame.sheet)
		check(math.abs(pw - 1024) < 1.5,
			"and zoomed, one texel is one pixel whatever the scale ("
			.. string.format("%.0f", pw) .. " of 1024)")
		RD:SetZoomed(false)
		A.db.profile.scale = profWas

		-- BUILT AROUND THE PAGE, not around the screen. The first version asked
		-- how much room there was and took all of it, which on a tall monitor is
		-- a magazine filling the monitor. The page is authored at a known size,
		-- so that is the number to start from and the screen only says no.
		--
		-- The rule of thumb: the whole window - page, margin and the strip under
		-- it - fits vertically on a 1080 screen with the interface still around
		-- it. Checked at the top of the scale range as well as the default,
		-- because a setting that can be turned up past the screen is one that
		-- puts the pager off the bottom of it.
		UIParent:SetSize(1920, 1080)
		UIParent:SetScale(1)
		A.db.profile.scale = 1
		for _, rs in ipairs({ 0.7, 1 }) do
			cfg.readerScale = rs
			RD:Size()
			local _, hh = px(RD.frame)
			check(hh <= 1080,
				("at magazine size %s the window fits a 1080 screen (%.0f tall)")
				:format(rs, hh))
		end

		-- CHECKED AWAY FROM THE DEFAULT. At 0.7 the setting and the built-in
		-- fraction are the same number, so a reader that ignored the setting
		-- entirely would draw exactly the right size and prove nothing.
		for _, rs in ipairs({ 0.5, 0.7, 0.85 }) do
			cfg.readerScale = rs
			RD:Size()
			check(math.abs((RD.frame.sheet:GetWidth() or 0) - 1024 * rs) < 1,
				("the page is drawn at the fraction asked for, not at whatever"
				.. " fits (%s -> %.0f, wanted %.0f)"):format(
					rs, RD.frame.sheet:GetWidth() or 0, 1024 * rs))
		end
		cfg.readerScale = 0.7
		RD:Size()
		UIParent:SetSize(1365, 768)
		UIParent:SetScale(uiWas)
		A.db.profile.scale = profWas
		RD:Size()

		-- EVERY CONTROL IN THE STRIP IS LINE ART. The close was a typed
		-- multiplication sign, and whether a font has U+00D7 is the font's
		-- business - the weight it landed in drew the notdef box and then the
		-- digits of the escape, on screen, next to the magnifier.
		for _, b in ipairs({ RD.frame.prev, RD.frame.next,
		                     RD.frame.zoom, RD.frame.close }) do
			check(b.glyph ~= nil and b.glyph:GetTexture() == A.Media.icons.file,
				"the reader's controls all come off the shared sheet")
		end
		-- WHAT THE WINDOW IS, not what is in it. It used to caption itself with
		-- the issue's own title, which every page already carries in letters an
		-- inch high - our chrome talking over the thing it is showing.
		--
		-- AND IT FOLLOWS THE MODE, because the rest of the console does. This is
		-- the ground, so it is the Not-In-Flight one.
		check(RD.frame.title:GetText() == "N.I.F.E.C. MEDIA READER",
			"on the ground the window is the N.I.F.E.C. reader ("
			.. tostring(RD.frame.title:GetText()) .. ")")
		check(RD.frame.title:GetText() ~= gossip.item.title,
			"and not what is in it - the page has its own masthead")

		-- A PAGE IS AN IMAGE. The reader has no opinion about what is on one.
		check(RD.frame.sheet.page:GetTexture() == gossip.item.pages[1],
			"open at the first page (" .. tostring(RD.frame.sheet.page:GetTexture()) .. ")")
		check(RD.frame.pager:GetText() == "1 / 3", "and says which one ("
			.. tostring(RD.frame.pager:GetText()) .. ")")

		RD:Turn(1)
		check(RD.frame.sheet.page:GetTexture() == gossip.item.pages[2],
			"turning goes to the next page")
		-- A MAGAZINE IS NOT A LOOP. Turning past the back cover onto the front
		-- again is a thing no paper does, and it is how you lose your place.
		RD:Turn(-1) RD:Turn(-1) RD:Turn(-1)
		check(RD.frame.pager:GetText() == "1 / 3", "and stops at the front cover")
		RD:Turn(9)
		check(RD.frame.pager:GetText() == "3 / 3", "and at the back one")

		-- WHERE YOU GOT TO, in the same field an episode keeps its segment in.
		LB:Paint()
		for _, r in ipairs(LB.frame.rows) do
			if r:IsShown() and r.item.type == "gossip" then gossip = r end
		end
		check(gossip.meta:GetText() == "read",
			"reaching the back page marks it read ("
			.. tostring(gossip.meta:GetText()) .. ")")

		-- A FINISHED MAGAZINE STARTS AGAIN, or it is one you cannot re-read.
		RD:Close()
		RD:Open(gossip.item)
		check(RD.frame.pager:GetText() == "1 / 3",
			"and reopening a finished one starts at the front")

		-- Part way through, it picks up where it was left - the same rule the
		-- programme follows for a half-heard episode.
		RD:Turn(1)
		RD:Close()
		RD:Open(gossip.item)
		check(RD.frame.pager:GetText() == "2 / 3",
			"while a half-read one opens where it was left ("
			.. tostring(RD.frame.pager:GetText()) .. ")")

		LB:Paint()
		for _, r in ipairs(LB.frame.rows) do
			if r:IsShown() and r.item.type == "gossip" then gossip = r end
		end
		check(gossip.meta:GetText() == "page 2 of 3",
			"and the list says how far in you are ("
			.. tostring(gossip.meta:GetText()) .. ")")

		-- THE PAPER STAYS when the list goes. It came out of that list but it is
		-- a window of its own, and reading a magazine with the Toolbox shut and
		-- the music carrying on is the whole reason it takes no time.
		LB:Close()
		check(RD:IsOpen(), "shutting the list leaves the paper open")
		RD:Close()
		LB:SetOpen(true, mini)
	end

	-- BOARDING TAKES OVER. There is only ever one thing playing: the console
	-- builds a programme shaped like the journey and the mini-player becomes a
	-- view onto it rather than a second player.
	--
	-- AND IT DOES NOT START AGAIN. Boarding used to build a programme and Start
	-- it, which cut off whatever was already sounding to play something else - a
	-- track stopped mid-bar to be replaced by a track. The flight is a length to
	-- fill, not a reason to begin again.
	LB:Close()
	local boardingWith = P.item and P.item.key
	-- COUNTED FROM EVER-STARTED, not from the last file name. Restarting a track
	-- plays the SAME file, so a check on the name passes whether the console
	-- adopted what was sounding or stopped it and began it again from the top.
	local startsBefore = 0
	for _ in pairs(_G.__sounds) do startsBefore = startsBefore + 1 end
	check(boardingWith ~= nil, "something is playing as the griffin arrives")
	A.IFEC.Taxi:Start()
	_G.__taxi.nodes = {
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	}
	_G.__taxi.routes = {}
	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)

	check(IF:HasRegion(), "boarding hangs the console's own region")

	-- AND THE READER FOLLOWS THE MODE. Aboard a griffin the same window is the
	-- IN-flight console's, which is the one place the joke would not have run.
	do
		local RD = A.IFEC.Reader
		local bulletin
		for _, item in ipairs(C:Available()) do
			if item.type == "gossip" then bulletin = item end
		end
		check(bulletin ~= nil, "there is a bulletin to open in the air")
		RD:Open(bulletin)
		check(RD.frame.title:GetText() == "I.F.E.C. MEDIA READER",
			"in the air the same window is the I.F.E.C. reader ("
			.. tostring(RD.frame.title:GetText()) .. ")")
		RD:Close()
	end
	check(_G.__soundsPlaying() <= 1,
		"and there is still only one thing playing ("
		.. _G.__soundsPlaying() .. ")")
	check(A.IFEC.Player.queue ~= nil and P.queue == A.IFEC.Player.queue,
		"off one queue, which the console now owns")
	check(P.item and P.item.key == boardingWith,
		"and the track that was already playing is still the one playing ("
		.. tostring(P.item and P.item.title) .. ")")
	check(P.queue[1] and P.queue[1].key == boardingWith,
		"leading the programme rather than queued behind it")
	local startsAfter = 0
	for _ in pairs(_G.__sounds) do startsAfter = startsAfter + 1 end
	check(startsAfter == startsBefore,
		"with nothing restarted - the track carries on rather than being cut off"
		.. " mid-bar and begun again (" .. startsAfter .. " vs " .. startsBefore .. ")")

	-- AND THE PROGRAMME IS BUILT AROUND IT. What is left of the running track
	-- counts towards the journey, so only the remainder has to be covered -
	-- ignoring it queues a flight's worth of music on top of a track that is
	-- already playing most of the first minute of it.
	do
		local want = A.IFEC.Taxi.flight.expected or 0
		local total = 0
		for _, item in ipairs(P.queue) do total = total + (item.duration or 0) end
		local withoutLast = total - (P.queue[#P.queue].duration or 0)
		check(total >= want, ("the programme still covers the flight (%ds of %ds)")
			:format(total, want))
		check(withoutLast < want,
			("and is no longer than it has to be - one item less falls short"
			.. " (%ds of %ds)"):format(withoutLast, want))
	end

	-- LANDING IS NOT ALWAYS A STOP. Off, the programme goes with the flight;
	-- on, the same queue simply carries on into the mini-player, which is
	-- already a view onto it.
	cfg.playOn = true
	check(P:IsPlaying(), "a programme is running as the flight ends")
	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4)
	check(P:IsPlaying(), "with 'keep playing' on, landing does not stop it")
	check(not IF:HasRegion(), "though the console's own region goes with the flight")
	check(_G.__soundsPlaying() == 1, "and the audio carries on (" ..
		_G.__soundsPlaying() .. ")")
	M:Paint()
	check(mini.title:GetText() == (P.item and P.item.title),
		"with the mini-player describing it now (" .. tostring(mini.title:GetText()) .. ")")

	-- AND OFF IS THE DEFAULT, because audio still going after the player has
	-- control back is the worst failure this feature has.
	cfg.playOn = false
	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)
	check(P:IsPlaying(), "boarding again")
	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4)
	check(not P:IsPlaying(), "with it off, landing stops the programme")
	check(_G.__soundsPlaying() == 0, "and silences the channel")

	-- THE TILE SWITCHES THE PLAYER, NOT THE TIMER. A player who never wants a
	-- programme on a griffin still wants to know when the griffin lands.
	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4)

	cfg.player = false
	-- COUNTED FROM EVER-STARTED, not from still-playing. A programme that begins
	-- and is stopped a second later by the tick that notices is silence by the
	-- time anybody asks, and an audible blip on every takeoff.
	local startedBefore = 0
	for _ in pairs(_G.__sounds) do startedBefore = startedBefore + 1 end

	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)
	check(A.IFEC.Taxi:IsFlying(), "with the player switched off the flight is still tracked")
	check(IF.frame:IsShown(), "and the console still opens")
	check(not IF:HasRegion(), "but hangs no programme under it")

	local startedAfter = 0
	for _ in pairs(_G.__sounds) do startedAfter = startedAfter + 1 end
	check(startedAfter == startedBefore,
		"and nothing was ever started, not started and hushed ("
		.. startedAfter .. " vs " .. startedBefore .. ")")

	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4)
	cfg.player = true

	-- AND THE TILE CAN BE PRESSED MID-FLIGHT. It is a tile on a drawer that
	-- opens over a griffin, so "takes effect next flight" is not good enough for
	-- switching it OFF - the programme it would leave running is the thing you
	-- just said you did not want.
	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)
	check(IF:HasRegion() and _G.__soundsPlaying() == 1, "a programme is running")

	cfg.player = false
	tick(1)
	check(not IF:HasRegion(), "switching it off mid-flight takes the region away")
	check(_G.__soundsPlaying() == 0, "and stops the audio with it")
	check(A.IFEC.Taxi:IsFlying(), "while the flight carries on being tracked")

	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4)
	cfg.player = true

	-- AND THE MINI-PLAYER IS NOT IN FLIGHT, so the setting is none of its
	-- business: it is the one surface that has nothing to do with a griffin.
	cfg.player = false
	TBm:LayoutContent()
	check(TBm:HasPlayer(), "the mini-player is unaffected - it is not in flight")
	cfg.player = true

	A.IFEC.Taxi:Stop()
	P:Stop()
	TBm:SetOpen(false, true)
	R:Reset()
	cfg.progress = {}
end)

section("ifec: the console takes a region, and gives it back", function()
	local IF   = A:GetModule("ifec")
	local Taxi = A.IFEC.Taxi

	Taxi:Start()
	_G.__taxi.nodes = {
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	}
	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)

	local f = IF.frame
	local bare = f:GetHeight()
	check(f.capsule:IsShown() and not f.panel:IsShown(),
		"with nothing to play it is a capsule")
	check(not f.hairline:IsShown(), "and there is no rule under the header")
	check(not IF:HasRegion(), "and it knows it carries nothing")

	-- THE ONLY GEOMETRY THAT CHANGES IS THE CORNER. Same width, same header,
	-- same dial - the design is explicit that these are two forms of one thing
	-- rather than two things.
	-- NO CHEVRON WITH NOTHING TO FOLD. A control that does nothing is bad
	-- enough; this one would also say the console had a hidden half, which is
	-- the opposite of "nothing reads as missing".
	check(not f.chevron:IsShown(), "and no fold control, there being nothing to fold")

	local region = CreateFrame("Frame", nil, UIParent)
	region:SetSize(560, 120)
	check(IF:AttachRegion(region, 120), "something can be hung under the header")
	check(f.chevron:IsShown(), "which brings the fold control with it")
	check(f.panel:IsShown() and not f.capsule:IsShown(), "which makes it a panel")
	check(f.hairline:IsShown(), "with the rule showing")
	check(f:GetHeight() == bare + 120, "and the frame grown by exactly the region ("
		.. f:GetHeight() .. " from " .. bare .. ")")
	check(f.route:GetText():find("Ratchet", 1, true) ~= nil,
		"the header is untouched by the change")

	-- THE HEADER STAYS AT THE TOP. Everything in it hangs off the vertical
	-- centre of what it is parented to, which is right while that is the
	-- capsule and catastrophic the moment a region makes the frame four times
	-- taller: the dial, the route and the fold control all slid down to the
	-- middle of the panel and drew across the player region.
	check(f.head ~= nil and f.head:GetHeight() == bare,
		"the header is a strip of its own, the capsule's height")
	check(f.dial:GetParent() == f.head and f.route:GetParent() == f.head
		and f.chevron:GetParent() == f.head,
		"and the dial, the route and the fold control hang off it, not the frame")
	local hp = f.head.__points[1]
	check(hp[1] == "TOPLEFT" and hp[2] == f and hp[3] == "TOPLEFT" and hp[5] == 0,
		"pinned to the top, so both forms lay the header out identically")

	-- A PANEL HAS A WIDER FLOOR THAN A CAPSULE. Fit used to bail out the moment
	-- a region was attached, so a panel kept whatever the capsule happened to be
	-- when the region arrived - and the region attaches BEFORE the route is
	-- painted, so the first flight of a session got the bare minimum and the
	-- now-playing row drew over its own transport.
	check(f:GetWidth() >= 400,
		"and a panel is at least as wide as the player region needs ("
		.. f:GetWidth() .. ")")

	-- FOLDING IS NOT THE SAME AS HAVING NOTHING. Both look like the capsule, but
	-- one is "there is nothing to play" and the other is "you put it away" - and
	-- the difference is whether there is a control to bring it back.
	check(IF:SetCollapsed(true), "the fold control folds it")
	check(f.capsule:IsShown() and not f.panel:IsShown(), "back to a capsule")
	check(f:GetHeight() == bare, "at the capsule's height")
	check(f.chevron:IsShown(), "with the control still there to unfold it")
	check(IF:HasRegion(), "and the region still attached, just put away")
	check(IF:SetCollapsed(false), "and it unfolds again")
	check(f.panel:IsShown() and f:GetHeight() == bare + 120, "to the panel it was")

	check(IF:DetachRegion(), "and it goes back")
	check(f.capsule:IsShown() and not f.panel:IsShown(), "to a capsule")
	check(f:GetHeight() == bare, "at its old height")
	check(not region:IsShown(), "with the region put away rather than left behind")
	check(not f.chevron:IsShown(), "and the fold control gone with the thing it folded")
	check(not IF:SetCollapsed(true), "which cannot be folded when there is nothing to fold")

	-- No /reload between the two: the player region can appear between one
	-- flight and the next, and a form change that needed a reload would mean
	-- installing a season did nothing until you relogged.
	IF:AttachRegion(region, 80)
	IF:DetachRegion()
	IF:AttachRegion(region, 80)
	check(f:GetHeight() == bare + 80 and f.panel:IsShown(),
		"and back and forth as often as you like")
	IF:DetachRegion()

	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	Taxi:Stop()
end)

-- LAST IN THE FILE, and it has to be. Spawning a plate takes a frame out
-- of the mock's pool, and the recycling checks above are about a plate
-- being handed out FRESH the first time - so a section that spawns one
-- earlier quietly spends the case they exist to make.
section("party controls: the marks go on your target", function()
	local PF = A:GetModule("partyframes")
	A:SetModuleEnabled("partyframes", true)
	-- An earlier section takes the target away entirely, and a party control
	-- that acts on your target has nothing to act on without one.
	_G.__units.target = _G.__units.target or {
		exists = true, name = "Savannah Prowler", level = 16,
		creature = "Beast", hp = 640, hpMax = 1000, reaction = 2,
		power = 0, powerMax = 0, powerType = 0, powerToken = "MANA",
	}
	local p = PF:BuildPanel()
	check(p ~= nil, "the controls panel builds")
	check(#p.wells == 8, "eight marks (" .. #p.wells .. ")")
	check(p.clear ~= nil, "and a Clear that is not a ninth mark")

	-- EVERY WELL WEARS ITS MARK. The wells came up empty on screen while every
	-- other check about them passed, because nothing here had ever asked what
	-- was actually in one - the grid was checked for what it DID, never for
	-- what it showed.
	local blank = 0
	for i, b in ipairs(p.wells) do
		if not b.icon or not tostring(b.icon.__tex):find("RaidTargetingIcons", 1, true) then
			blank = blank + 1
		end
	end
	check(blank == 0, "each well shows its mark (" .. blank .. " blank)")

	-- AND ITS OWN CELL out of the sheet. A texture given the file and no
	-- texcoord draws all eight marks at once.
	local seen, clash = {}, nil
	for i, b in ipairs(p.wells) do
		local l, r, t2, b2 = b.icon:GetTexCoord()
		local key = string.format("%.3f,%.3f,%.3f,%.3f", l, r, t2, b2)
		if seen[key] then clash = i .. " and " .. seen[key] end
		seen[key] = i
	end
	check(not clash, "and its own cell out of the sheet (" .. tostring(clash) .. ")")

	-- AT THE PROFILE'S SCALE, and AT A SCREEN EDGE. A panel floating in the
	-- middle is not a dock: half the shape the brief describes is the thing
	-- being drawn out of the side of the screen rather than dropped on it.
	local wasScale = A.db.profile.scale
	A.db.profile.scale = 0.6
	PF:RefreshPanel()
	check(math.abs(p:GetScale() - 0.6) < 0.001,
		"the panel is drawn at the profile's scale (" .. p:GetScale() .. ")")
	A.db.profile.scale = wasScale
	PF:RefreshPanel()

	check(PF:PanelEdge() == "LEFT", "docked left by default")

	-- BOTH HANG OFF THE SCREEN EDGE, and the handle RIDES the panel's outer
	-- edge as it comes out - clamped so that shut it stops flush at the screen
	-- rather than going off it with the panel.
	--
	-- It used to be the other way round: the handle stayed put and the panel
	-- was anchored out of it, which is how Blizzard's own party dock behaves.
	-- The Toolbox drawer and the bags drawer both CARRY their handle, and
	-- three docks in one interface disagreeing about that is the kind of thing
	-- you notice without being able to name.
	check(PF.handle ~= nil, "there is a dock handle")
	PF:SetPanelOpen(false, true)
	local _, hrel, hat, hx = PF.handle:GetPoint()
	check(hrel == UIParent and hat == "LEFT",
		"the handle is flush to the screen edge (" .. tostring(hat) .. ")")
	check(hx == 0,
		"and shut it stops AT it rather than a bite past it, because there is"
		.. " no panel left to join to (" .. tostring(hx) .. ")")
	local _, prel, pat = p:GetPoint()
	check(prel == UIParent and pat == "LEFT",
		"the panel hangs off the same edge rather than off the handle")
	check(not p:IsShown(),
		"and shut, it is properly away rather than a live frame parked past"
		.. " the edge")

	-- OPEN, THE HANDLE HAS TRAVELLED a panel's width less its own bite.
	PF:SetPanelOpen(true, true)
	local _, _, _, hxOpen = PF.handle:GetPoint()
	check(math.abs(hxOpen - (p:GetWidth() - 8)) < 0.01,
		"open, it has moved out with the panel and bitten into it by its own"
		.. " corner (" .. string.format("%.1f", hxOpen) .. " for a panel " ..
		string.format("%.0f", p:GetWidth()) .. " across)")

	-- AND IT SLIDES, per frame, the way the other two do.
	PF:SetPanelOpen(false, true)
	PF:TogglePanel()
	local drive = p:GetScript("OnUpdate")
	check(drive ~= nil, "opening installs a per-frame driver on the panel")
	drive(p, 0.05)
	drive(p, 0.05)
	local mid = PF._travel
	check(mid > 0 and mid < 1,
		"mid-slide the panel is part way out (" ..
		string.format("%.2f", mid) .. ")")
	PF:TogglePanel()
	p:GetScript("OnUpdate")(p, 0.05)
	check(PF._travel < mid and PF._travel > 0,
		"reversing carries on from where it had got to rather than snapping"
		.. " back or queueing (" .. string.format("%.2f", mid) .. " -> " ..
		string.format("%.2f", PF._travel) .. ")")
	for _ = 1, 20 do
		local fn = p:GetScript("OnUpdate")
		if not fn then break end
		fn(p, 0.05)
	end
	check(PF._travel == 0,
		"and it arrives exactly rather than creeping toward zero for ever (" ..
		tostring(PF._travel) .. ")")
	check(p:GetScript("OnUpdate") == nil and not p:IsShown(),
		"the driver comes off and the panel goes properly away")

	-- AND THE PARTY STACK MOVES ONCE, not sixty times. Re-anchoring it is a
	-- PROTECTED call - the stack carries secure children - and it is refused
	-- outright in combat, so doing it on every frame of a slide is sixty
	-- chances to be refused where one would do. It shifts on the INTENT, at
	-- the start, so the party moves out of the way as the panel comes out
	-- rather than after it has arrived.
	local realAnchor = PF.AnchorStack
	local anchored = 0
	PF.AnchorStack = function(self)
		anchored = anchored + 1
		return realAnchor(self)
	end
	PF:TogglePanel()
	for _ = 1, 20 do
		local fn = p:GetScript("OnUpdate")
		if not fn then break end
		fn(p, 0.05)
	end
	PF.AnchorStack = realAnchor
	check(anchored == 1,
		"one re-anchor for the whole slide (" .. anchored .. ")")
	PF:SetPanelOpen(false, true)

	check(PF:SetPanelEdge("RIGHT"), "it can be moved to another edge")
	local _, _, hat2 = PF.handle:GetPoint()
	check(hat2 == "RIGHT", "and the handle goes there (" .. tostring(hat2) .. ")")
	check(not PF:SetPanelEdge("MIDDLE"),
		"and a corner that is not an edge is refused rather than obeyed")
	PF:SetPanelEdge("LEFT")

	-- A QUARTER ALONG, NOT THE MIDDLE. The Toolbox rail lives at the middle of
	-- its edge and both default to LEFT, so a handle centred there lands on top
	-- of it - which is exactly what it did. The client puts its own party dock
	-- about a quarter down, which is where a player already looks and is clear
	-- of the rail by construction rather than by collision-detection.
	check(PF:PanelSlot() == 1, "the handle takes the first slot by default")
	local _, _, _, _, dy = PF.handle:GetPoint()
	check(dy and dy > 0,
		"which is up from the middle of a side edge, not on it (" ..
		tostring(dy) .. ")")
	local TB = A:GetModule("toolbox")
	if TB and TB.rail and TB.rail:IsShown() then
		local _, _, _, _, ry = TB.rail:GetPoint()
		check(math.abs(dy - (ry or 0)) > 40,
			"and clear of the Toolbox rail on the same edge (" ..
			tostring(dy) .. " vs " .. tostring(ry) .. ")")
	end

	check(PF:SetPanelSlot(2), "there is a second slot per edge")
	local _, _, _, _, dy2 = PF.handle:GetPoint()
	check(dy2 and dy2 < 0,
		"three quarters along, on the other side of the middle (" ..
		tostring(dy2) .. ")")
	check(not PF:SetPanelSlot(3),
		"and a third slot is refused rather than invented")
	PF:SetPanelSlot(1)

	-- MEASURED IN THE HANDLE'S OWN UNITS. SetPoint offsets are in the
	-- anchored frame's coordinate space, and this frame runs at the profile
	-- scale - so a quarter of the screen expressed in UIParent pixels lands
	-- at a third of the way down at 0.71, and off a small screen entirely.
	--
	-- The scale has to MOVE for this to say anything: at 1 the conversion is
	-- the identity and a check that never leaves the default passes with the
	-- bug in it. That is how this one got through the first time.
	local wasScale = A.db.profile.scale
	local _, _, _, _, atOne = PF.handle:GetPoint()
	A.db.profile.scale = 0.5
	PF:AnchorPanel()
	local _, _, _, _, atHalf = PF.handle:GetPoint()
	-- The offset scales by exactly the ratio of the two scales: the same
	-- quarter of the screen, counted in smaller units.
	local want = atOne * ((wasScale or 1) / 0.5)
	check(atHalf and atOne and math.abs(atHalf - want) < 1,
		"the offset is in the handle's own units, so it grows as the frame"
		.. " shrinks (" .. string.format("%.0f -> %.0f, wanted %.0f",
		atOne, atHalf, want) .. ")")
	A.db.profile.scale = wasScale
	PF:AnchorPanel()
	-- IT LOOKS MOVABLE WHEN IT IS. Every other frame wears an accent wash in
	-- placement mode; this one is not a Movers frame - it docks to an edge
	-- rather than sitting at a point - so it gets no handle of its own, and
	-- without this it was the one thing on an unlocked screen giving no sign
	-- it could be moved at all.
	local hh = PF.handle
	A.Movers:Lock()
	check(not hh.tag:IsShown(), "locked, the dock wears no placement label")
	check(hh._fillToken ~= nil,
		"and is coloured by token, so a restyle reaches it (" ..
		tostring(hh._fillToken) .. ")")

	A.Movers:Unlock()
	check(hh.tag:IsShown(),
		"unlocked, it says what it is - beside the tab, because a word laid"
		.. " over a 34-unit strip is a word laid across something narrower"
		.. " than itself")
	local fill = hh._fillColor
	local acc = A.Palette.c.accent
	check(fill and math.abs(fill[1] - acc[1]) < 0.01
		and math.abs(fill[2] - acc[2]) < 0.01
		and math.abs(fill[3] - acc[3]) < 0.01,
		"and wears the same accent wash as everything else you can move")

	-- AND A RESTYLE MID-PLACEMENT does not wash it back to ordinary glass.
	-- ApplySkin is the obvious thing to call on a skin change and it is the
	-- wrong one here: it would put the ordinary rim back while the frames are
	-- still unlocked, leaving the dock the only fixed-looking thing on screen
	-- again the moment somebody changed skin mid-placement.
	PF:OnSkinChanged()
	local after = hh._fillColor
	check(after and math.abs(after[1] - A.Palette.c.accent[1]) < 0.01,
		"and keeps it through a restyle, rather than reverting to plain glass")
	A.Movers:Lock()
	check(hh._fillToken ~= nil, "and takes the skin back when you lock again")
	-- DRAG IT TO ANOTHER EDGE, the way the Toolbox rail re-docks. Same gate -
	-- the frames have to be unlocked - so there is no second gesture to learn.
	--
	-- Eight targets: four edges with two slots each. The preview is the handle
	-- itself moving, which for a tab this size is a clearer answer than a ghost
	-- rectangle saying where it would go.
	local h = PF.handle
	local function dragTo(x, y)
		-- __setCursor, not a global of my own: the mock keeps the cursor in a
		-- file-local, so setting __cursorX moved nothing and the drag read 500,400
		-- every time - which is the middle of the screen and therefore LEFT.
		__setCursor(x * (UIParent:GetEffectiveScale() or 1),
			y * (UIParent:GetEffectiveScale() or 1))
		h:GetScript("OnDragStart")(h)
		local up = h:GetScript("OnUpdate")
		if up then up(h, 0) end
		h:GetScript("OnDragStop")(h)
	end

	local W0, H0 = UIParent:GetWidth(), UIParent:GetHeight()
	A.Movers.unlocked = true

	-- Hard right, low down: the RIGHT edge, second slot.
	dragTo(W0 - 10, H0 * 0.2)
	check(PF:PanelEdge() == "RIGHT" and PF:PanelSlot() == 2,
		"dragged to the bottom of the right-hand side it docks there (" ..
		PF:PanelEdge() .. " " .. PF:PanelSlot() .. ")")

	-- BY FRACTION OF THE SCREEN, not by pixels. The middle of the left side of
	-- a wide monitor is nearer the top and bottom edges in raw pixels than it
	-- is to the left one, and answering TOP there is nonsense a player would
	-- report as the drag being broken.
	dragTo(10, H0 * 0.5)
	check(PF:PanelEdge() == "LEFT",
		"and hard against the left side it is LEFT, whatever the pixel counts"
		.. " say (" .. PF:PanelEdge() .. ")")

	dragTo(W0 * 0.5, H0 - 10)
	check(PF:PanelEdge() == "TOP" and PF:PanelSlot() == 2,
		"the top edge has two slots of its own (" .. PF:PanelEdge() .. " " ..
		PF:PanelSlot() .. ")")
	dragTo(W0 * 0.2, H0 - 10)
	check(PF:PanelSlot() == 1,
		"and the left half of it is the first")

	-- LOCKED FRAMES ARE LOCKED. The same gate the rail uses, and the one that
	-- stops a stray click on a crowded screen re-docking it.
	PF:SetPanelEdge("LEFT")
	PF:SetPanelSlot(1)
	A.Movers.unlocked = false
	dragTo(W0 - 10, H0 * 0.2)
	check(PF:PanelEdge() == "LEFT",
		"locked, dragging it does nothing at all (" .. PF:PanelEdge() .. ")")

	-- AND NOT IN A FIGHT. Re-docking moves the party stack, which carries
	-- secure children - the drag is dropped rather than finished.
	A.Movers.unlocked = true
	_G.__inCombat = true
	local blocked = _G.__blocked
	dragTo(W0 - 10, H0 * 0.2)
	check(PF:PanelEdge() == "LEFT" and _G.__blocked == blocked,
		"and mid-fight it is refused rather than half-finished (" ..
		PF:PanelEdge() .. ", " .. (_G.__blocked - blocked) .. " refused)")
	_G.__inCombat = false

	-- AND A FIGHT STARTING MID-DRAG, which is the case the guard in the update
	-- loop exists for - the one above never reaches it, because the drag is
	-- refused at the start. The button can still be down when the pull
	-- happens, and finishing then would move the stack, which carries secure
	-- children.
	PF:SetPanelEdge("LEFT")
	PF:SetPanelSlot(1)
	h:GetScript("OnDragStart")(h)
	_G.__inCombat = true
	local mid = _G.__blocked
	__setCursor((W0 - 10) * (UIParent:GetEffectiveScale() or 1),
		(H0 * 0.2) * (UIParent:GetEffectiveScale() or 1))
	local up = h:GetScript("OnUpdate")
	if up then up(h, 0) end
	h:GetScript("OnDragStop")(h)
	check(PF:PanelEdge() == "LEFT" and _G.__blocked == mid,
		"a fight starting mid-drag drops it rather than finishing it (" ..
		PF:PanelEdge() .. ", " .. (_G.__blocked - mid) .. " refused)")
	_G.__inCombat = false

	A.Movers.unlocked = false
	PF:SetPanelEdge("LEFT")
	PF:SetPanelSlot(1)
	-- THE ARROW TURNS ROUND. Open, the click retreats the drawer to its own
	-- edge; shut, it emerges away from it - the same rule the Toolbox rail
	-- follows, from the same function.
	p:Hide()
	PF:LayoutHandle()
	local shut = PF.handle.chev.__rotation
	PF:TogglePanel()
	local open = PF.handle.chev.__rotation
	check(shut ~= nil and open ~= nil and shut ~= open,
		"the handle's arrow faces the other way with the drawer open (" ..
		tostring(shut) .. " -> " .. tostring(open) .. ")")
	PF:TogglePanel()

	-- NOT IN A GROUP, NOT ON SCREEN. A dock to party controls with nobody in
	-- the party is a tab that does nothing, permanently, on the edge of every
	-- screen - and this addon already has one thing living there.
	local keep = {}
	for _, u in ipairs({ "party1", "party2", "party3", "party4" }) do
		keep[u] = _G.__units[u].exists
		_G.__units[u].exists = false
	end
	PF:LayoutHandle()
	check(not PF.handle:IsShown(), "alone, there is no handle at all")
	for u, was in pairs(keep) do _G.__units[u].exists = was end
	PF:LayoutHandle()
	check(PF.handle:IsShown(), "and it is back the moment you group up")

	-- THE MARK GOES ON YOUR TARGET, which the brief never says and which
	-- decides how the whole grid behaves: SetRaidTarget takes a unit and the
	-- unit is always "target". So with nothing targeted every well is inert,
	-- and a well that looks pressable and does nothing is the worse of the two.
	_G.__units.target.exists = false
	PF:RefreshPanel()
	local before = _G.__partyCalls.marks
	p.wells[1]:GetScript("OnClick")(p.wells[1])
	check(_G.__partyCalls.marks == before,
		"with no target, pressing a mark asks the client for nothing")
	check(p.wells[1]:GetAlpha() < 1,
		"and the grid says so rather than looking ready (" ..
		tostring(p.wells[1]:GetAlpha()) .. ")")

	_G.__units.target.exists = true
	PF:RefreshPanel()

	-- HIGHEST INDEX FIRST - skull, cross, square, moon, triangle, diamond,
	-- circle, star. Blizzard's own grid has read that way since the marks
	-- existed and everybody reaches for the skull in the top-left without
	-- looking; laying them out 1 to 8 puts the star there and every mark you
	-- set is the wrong one until you slow down and read the grid.
	check(p.wells[1].index == 8,
		"the skull is the first well, as it is in the client's own grid (" ..
		tostring(p.wells[1].index) .. ")")
	check(p.wells[8].index == 1, "and the star is the last")

	p.wells[1]:GetScript("OnClick")(p.wells[1])
	check(GetRaidTargetIndex("target") == 8,
		"pressing a well sets the mark it SHOWS (" ..
		tostring(GetRaidTargetIndex("target")) .. ")")
	check(p.wells[1].__on == true,
		"and the ring lands on that same well - the grid is laid out"
		.. " backwards to the indices, so comparing the slot rings the"
		.. " wrong one")
	check(p.wells[8].__on == false, "and only that one")

	-- CLEAR IS INDEX 0, not a missing argument. SetRaidTarget with nothing
	-- passed leaves the mark exactly where it was.
	p.clear:GetScript("OnClick")(p.clear)
	check(GetRaidTargetIndex("target") == nil,
		"Clear takes it off (" .. tostring(GetRaidTargetIndex("target")) .. ")")
end)

section("party: the stack rides the dock until you move it", function()
	local PF = A:GetModule("partyframes")
	PF:BuildPanel()

	-- WHERE A PLAYER EXPECTS TO FIND IT. The client's own party frames come off
	-- the left edge with the controls, and somebody installing this should find
	-- their party where they left it rather than somewhere new they now have to
	-- tidy up.
	A.db.profile.anchors.party = nil
	PF.panel:Hide()
	PF:AnchorStack()
	local _, rel = PF.stack:GetPoint()
	check(rel == PF.handle,
		"unplaced and shut, the stack hangs off the dock handle")
	check(not PF:StackIsPlaced(), "and counts as unplaced")

	-- AND A RESTORE LEAVES IT THERE. Movers positions every frame it knows
	-- about from the saved anchor or the default, and unlocking the frames
	-- runs the lot - so without the onPlaced hook handing the stack back, one
	-- /aether unlock would snap it off the dock and it would never return.
	A.Movers:Restore("party")
	local _, relAfter = PF.stack:GetPoint()
	check(relAfter == PF.handle,
		"and a Movers restore hands it straight back to the dock")

	-- AND IT SHIFTS WHEN THE DRAWER OPENS, the way the client's own party
	-- frames do: off the handle while the controls are shut, off the panel
	-- while they are open, so opening them pushes the party out of the way
	-- rather than drawing over it.
	PF:TogglePanel()
	check(PF.panel:IsShown(), "the controls open")
	local _, relOpen = PF.stack:GetPoint()
	check(relOpen == PF.panel,
		"and the stack shifts out to hang off the panel instead")
	PF:TogglePanel()
	local _, relShut = PF.stack:GetPoint()
	check(relShut == PF.handle,
		"and comes back to the handle when they shut")

	-- IT RIDES THE DOCK TO ANOTHER EDGE, which is what makes it attached rather
	-- than merely placed near it.
	PF:SetPanelEdge("RIGHT")
	local at = PF.stack:GetPoint()
	check(at == "TOPRIGHT",
		"docking the panel right takes the stack with it (" .. tostring(at) .. ")")
	PF:SetPanelEdge("LEFT")

	-- DRAG IT ONCE AND IT IS YOURS. Movers writes an anchor and that is the
	-- answer from then on - including when the panel moves.
	A.db.profile.anchors.party = { point = "CENTER", relPoint = "CENTER", x = 0, y = 0 }
	check(PF:StackIsPlaced(), "a dragged stack counts as placed")
	check(PF:AnchorStack() == false,
		"and the dock stops moving it")
	-- AND MOVERS PUTS IT WHERE YOU LEFT IT, not where the dock is. onPlaced
	-- runs after every restore and hands the stack back to the dock only when
	-- nobody has placed it - without that, unlocking the frames would snap a
	-- stack you had positioned straight back onto the panel.
	A.Movers:Restore("party")
	local _, relPlaced = PF.stack:GetPoint()
	check(relPlaced ~= PF.panel,
		"and a restore leaves it where you put it, not back on the dock")

	-- AND YOU CAN HAND IT BACK.
	PF:ResetStack()
	check(not PF:StackIsPlaced(), "/aether party reset drops the anchor")
	local _, relReset = PF.stack:GetPoint()
	check(relReset == PF.handle or relReset == PF.panel,
		"and puts it back on the dock")
end)
section("party controls: what a member may press", function()
	local PF = A:GetModule("partyframes")
	local p = PF.panel
	local calls = _G.__partyCalls
	_G.__units.target = _G.__units.target
		or { exists = true, hp = 1, hpMax = 1 }

	-- HIDDEN, NOT DIMMED. The client gates ready-check itself, but simply
	-- IGNORES a role poll or a convert from a member - no error, nothing said -
	-- and a button that does nothing without saying so is a button you keep
	-- pressing. So they are gone for a member and the panel is shorter.
	_G.__units.player.leader = false
	PF:RefreshPanel()
	local shortH = p:GetHeight()
	local hidden, visible = 0, 0
	for _, b in ipairs(p.rows) do
		if b:IsShown() then visible = visible + 1 else hidden = hidden + 1 end
	end
	check(hidden == 3 and visible == 1,
		"a member sees one row of four (" .. visible .. " shown, " .. hidden ..
		" hidden)")
	check(p.rows[2]:IsShown(),
		"and the one left is Countdown - the client does not gate that one")

	_G.__units.player.leader = true
	PF:RefreshPanel()
	check(p:GetHeight() > shortH,
		"the panel is taller for a leader (" .. p:GetHeight() .. " from " ..
		shortH .. ")")

	-- Each row calls the client, and the RIGHT call.
	calls.ready, calls.countdown, calls.roles, calls.raid = 0, 0, 0, 0
	p.rows[1]:GetScript("OnClick")(p.rows[1])
	check(calls.ready == 1, "Ready Check reaches C_PartyInfo.DoReadyCheck")
	p.rows[3]:GetScript("OnClick")(p.rows[3])
	check(calls.roles == 1, "Role Check reaches InitiateRolePoll")

	-- THE CONFIRMING CONVERT. A raid cannot be turned back into a party, and
	-- the client has a call that asks first - using the other one is a group
	-- somebody has changed for everybody by mis-clicking a row.
	p.rows[4]:GetScript("OnClick")(p.rows[4])
	check(calls.raid == 1, "Convert to Raid reaches the client")
	check((calls.confirmedCold or 0) == 0,
		"through the call this client actually has - ConfirmConvertToRaid"
		.. " reads like an ask-first version and is not one; called cold it"
		.. " does nothing at all, which is what the button did")

	-- The countdown carries its own number, and the client's cap rather than
	-- one of ours: DoCountdown refuses anything longer and says nothing.
	p.rows[2].seconds = 10
	p.rows[2]:GetScript("OnClick")(p.rows[2])
	check(calls.countdown == 1 and calls.seconds == 10,
		"Countdown runs for the number on its picker (" ..
		tostring(calls.seconds) .. ")")
	p.rows[2].seconds = 9999
	p.rows[2]:GetScript("OnClick")(p.rows[2])
	check(calls.seconds <= 60,
		"and never longer than the client will take (" ..
		tostring(calls.seconds) .. ")")
	p.rows[2].seconds = 10

	PF.panel:Hide()
end)
section("party: a diagnostic that answers the question", function()
	local PF = A:GetModule("partyframes")
	A:SetModuleEnabled("partyframes", true)
	_G.__raidTargets.party1 = 3
	fire("RAID_TARGET_UPDATE")

	-- THREE ROUNDS WENT BY GUESSING why a raid mark was not on screen. Every
	-- answer is a one-liner from the client and none of them can be read from
	-- outside the game, so the report puts what the client SAYS next to what we
	-- actually drew - and the two disagreeing is the whole diagnosis.
	local lines = {}
	local ok, err = pcall(A.PartyDiag, function(fmt, ...)
		lines[#lines + 1] = string.format(fmt, ...)
	end)
	check(ok, "/aether party reports without erroring (" .. tostring(err) .. ")")

	local all = table.concat(lines, "\n")
	check(all:find("party1", 1, true) ~= nil, "with a row per member")
	check(all:find("PartyFrame", 1, true) ~= nil,
		"and what became of the client's own frames")
	check(all:find("mark", 1, true) ~= nil,
		"and says which decorators are actually drawn")

	-- The player is a different frame in a different module, and leaving it out
	-- is how you spend a round asking about the wrong one.
	check(all:find("player", 1, true) ~= nil, "your own capsule included")

	_G.__raidTargets.party1 = nil
	fire("RAID_TARGET_UPDATE")
end)

section("party controls: the last person leaves and they go too", function()
	local PF = A:GetModule("partyframes")

	-- THE ROSTER PUT BACK EXACTLY AS IT WAS FOUND. Blocks above this one
	-- leave members standing, and blocks below expect them - a section that
	-- empties the party and walks away takes forty other checks with it.
	local UNITS = { "party1", "party2", "party3", "party4" }
	local was = {}
	for _, u in ipairs(UNITS) do was[u] = _G.__units[u].exists end

	-- THE HANDLE IS THE ONLY THING THAT SHUTS THE PANEL, and LayoutHandle
	-- takes it off screen the moment the group empties. So the controls, left
	-- open, became a window with nothing to close it - sitting in the middle of
	-- the screen for the rest of the session. Reported from the game: uninvite
	-- the last member with the controls up.
	for _, u in ipairs(UNITS) do _G.__units[u].exists = false end
	_G.__units.party1.exists = true
	_G.__units.party2.exists = true
	fire("GROUP_ROSTER_UPDATE")
	PF:SetPanelOpen(true, true)
	check(PF:PanelOpen() and PF.panel:IsShown() and PF.handle:IsShown(),
		"with a party, the controls open and the handle is there to shut them")

	-- One leaves, and nothing has changed: there is still somebody to mark.
	_G.__units.party2.exists = false
	fire("GROUP_ROSTER_UPDATE")
	check(PF:PanelOpen() and PF.panel:IsShown(),
		"one member leaving leaves them open - there is still a party")

	-- And the last one does.
	_G.__units.party1.exists = false
	fire("GROUP_ROSTER_UPDATE")
	check(GetNumGroupMembers() == 0 and not PF.handle:IsShown(),
		"the handle goes when the group empties (" ..
		GetNumGroupMembers() .. " left)")
	check(not PF:PanelOpen() and not PF.panel:IsShown(),
		"and the controls go with it, rather than being left with no way to "
		.. "shut them")

	-- AND THEY COME BACK. Shutting them on the way out must not be a one-way
	-- door: the next invite has to be able to open them again.
	_G.__units.party1.exists = true
	fire("GROUP_ROSTER_UPDATE")
	PF:SetPanelOpen(true, true)
	check(PF:PanelOpen() and PF.panel:IsShown(),
		"and a new party opens them again")
	PF:SetPanelOpen(false, true)

	for _, u in ipairs(UNITS) do _G.__units[u].exists = was[u] end
	fire("GROUP_ROSTER_UPDATE")
end)


section("nameplates: a pet's title is not every boar's title", function()
	local NP = A:GetModule("nameplates")

	-- THE BUG, EXACTLY. Dismiss a hunter's Dire Mottled Boar, target a wild
	-- Dire Mottled Boar, and the plate reads "<Ifindu's Pet>" - because the
	-- scanned title was filed under the creature's NAME, and those two share a
	-- name to the letter.
	--
	-- The GUID is what tells them apart: a pet is type Pet, a mob is type
	-- Creature, and both carry an id that is per creature KIND - so the cache
	-- still answers once for every Beverage Merchant in the world.
	__spawnPlate("nameplate7", {
		exists = true, name = "Dire Mottled Boar", level = 10, reaction = 4,
		hp = 300, hpMax = 420, creature = "Beast",
		guidType = "Pet", title = "Ifindu's Pet",
	})
	local pet = NP.byUnit.nameplate7
	check(pet ~= nil, "the pet's plate is up")
	check(pet and pet.guild and pet.guild:GetText() and
		pet.guild:GetText():find("Ifindu", 1, true) ~= nil,
		"and it says whose pet it is (" ..
		tostring(pet and pet.guild and pet.guild:GetText()) .. ")")
	__despawnPlate("nameplate7")

	-- Now the wild one. Same name, same species, no owner.
	-- NEUTRAL, like the one in the report. A hostile mob is drawn as a plate
	-- and has no subtitle line at all, so it could not show the bug however
	-- badly the cache behaved - which is exactly what the first version of
	-- this check did, and it passed against every mutation.
	--
	-- Reaction 4 and a title is what puts a unit in the NAME form, which is
	-- the form that has somewhere to print one.
	__spawnPlate("nameplate8", {
		exists = true, name = "Dire Mottled Boar", level = 10, reaction = 4,
		hp = 300, hpMax = 420, creature = "Beast",
	})
	local wild = NP.byUnit.nameplate8
	check(wild ~= nil, "the wild one's plate is up")
	local sub = wild and wild.guild and wild.guild:IsShown()
		and wild.guild:GetText() or nil
	check(sub == nil or sub:find("Ifindu", 1, true) == nil,
		"and it does NOT inherit the pet's owner (" .. tostring(sub) .. ")")
	__despawnPlate("nameplate8")

	-- AND TWO HUNTERS WITH THE SAME SPECIES. A pet's title is its OWNER'S
	-- name, so the creature id is the wrong key for one even against another
	-- pet - both boars are the same creature and the answers differ. Per
	-- spawn is the only key that is true for a pet.
	__spawnPlate("nameplate7", {
		exists = true, name = "Dire Mottled Boar", level = 10, reaction = 4,
		hp = 300, hpMax = 420, creature = "Beast",
		guidType = "Pet", title = "Grimtusk's Pet",
	})
	local other = NP.byUnit.nameplate7
	local osub = other and other.guild and other.guild:GetText() or nil
	check(osub and osub:find("Grimtusk", 1, true) ~= nil,
		"another hunter's boar says ITS owner, not the first one's (" ..
		tostring(osub) .. ")")
	__despawnPlate("nameplate7")

	-- AND THE CACHE STILL DOES ITS JOB. Two of the same creature, different
	-- spawns: scanned once between them. Keying by spawn would be correct
	-- and useless - every mob in the zone rescanned on every plate, which
	-- looks identical on screen and is the reason this cache exists.
	_G.__titleScans = 0
	__spawnPlate("nameplate6", {
		exists = true, name = "Beverage Merchant", level = 30, reaction = 4,
		hp = 800, hpMax = 800, creature = "Humanoid", title = "Drink Vendor",
	})
	__despawnPlate("nameplate6")
	__spawnPlate("nameplate6", {
		exists = true, name = "Beverage Merchant", level = 30, reaction = 4,
		hp = 800, hpMax = 800, creature = "Humanoid", title = "Drink Vendor",
	})
	check(_G.__titleScans == 1,
		"two of the same merchant are scanned once between them (" ..
		tostring(_G.__titleScans) .. " scans)")
	__despawnPlate("nameplate6")
end)
section("decorators: a mark on a mob is a mark on its nameplate", function()
	local NP = A:GetModule("nameplates")

	-- THERE WAS NO MARK AT ALL. Put a skull on something and the plate over its
	-- head said nothing about it, which is the one moment a marked mob is worth
	-- marking.
	-- Its own token. Spawning nameplate1 here would hand the plate-recycling
	-- checks below a frame that already exists, and spend the one case they
	-- are about.
	__spawnPlate("nameplate9", {
		exists = true, name = "Kolkar Marauder", level = 18, reaction = 2,
		hp = 900, hpMax = 1000,
	})
	local f = NP.byUnit.nameplate9
	check(f ~= nil, "a plate is up")
	check(f and f.mark ~= nil, "and it has a raid mark")
	check(f and not f.mark:IsShown(),
		"hidden on something nobody has marked")

	-- RAID_TARGET_UPDATE CARRIES NO UNIT. One event for every mark in the group
	-- at once, so a handler waiting to be told which plate would never run - and
	-- a plate would keep wearing a skull that had moved to somebody else.
	_G.__raidTargets.nameplate9 = 8
	fire("RAID_TARGET_UPDATE")
	check(f and f.mark:IsShown(), "and there the moment somebody does")
	check(f and tostring(f.mark.__tex):find("RaidTargetingIcons", 1, true) ~= nil,
		"in the client's own art (" .. tostring(f and f.mark.__tex) .. ")")
	local l, r = f.mark:GetTexCoord()
	check(not (l == 0 and r == 1),
		"with one cell picked out of it, not all eight marks at once")

	_G.__raidTargets.nameplate9 = nil
	fire("RAID_TARGET_UPDATE")
	check(f and not f.mark:IsShown(), "and gone when the mark is cleared")
	__despawnPlate("nameplate9")
end)


section("threat: the probe reads the client rather than the plan", function()
	-- PHASE 0 OF PLAN-Threat.md, and its whole job is evidence: everything in
	-- that document says UnitDetailedThreatSituation answers on this client,
	-- and nothing in it has SEEN it answer. What is checked here is the READOUT
	-- - that it asks the right questions of the right tokens and survives every
	-- shape of nothing the API can hand back - because the readout is the thing
	-- a wrong answer has to travel through.
	local shown = nil
	local realShow = A.Errors.ShowText
	A.Errors.ShowText = function(_, text) shown = text return end
	local run = SlashCmdList["AETHERUI"]

	-- OUT OF COMBAT IS THE NORMAL CASE, and it is the one that returns
	-- NOTHING - not zero. The design's quiet-by-default rule and the API's
	-- empty return are the same fact, so a probe that cannot survive the empty
	-- case cannot report the ordinary one.
	_G.__units.player.inCombat = false
	wipe(_G.__threat)
	shown = nil
	run("threat probe")
	check(shown ~= nil, "the probe answers out of combat rather than throwing")
	check(shown and shown:find("UnitDetailedThreatSituation=function", 1, true),
		"and says which of the three threat calls the client actually has")
	check(shown and shown:find("nothing back", 1, true),
		"reporting nothing as NOTHING, which is not the same as zero")

	-- AND HOW MANY VALUES CAME BACK WITH IT. "Returned five nils" and
	-- "returned nothing at all" wear the same face at the call site and are
	-- different faults: the first is a unit that is not on this mob's table,
	-- which is normal, and the second is a function that is present and not
	-- wired, which is the whole feature missing. The first live probe could
	-- not tell them apart and that is exactly the question it was run to
	-- answer.
	-- ON THE DATA LINE, not anywhere in the readout. Written as a bare search
	-- for "rets=0" this passed while the count was replaced with a question
	-- mark, because the paragraph explaining how to READ the count says
	-- "rets=0" twice. A check that matches its own narration is a check that
	-- cannot fail.
	check(shown and shown:find("nothing back  rets=0", 1, true),
		"and says how many values the call actually returned")
	check(shown and shown:find("simple=", 1, true),
		"with the simple call beside the detailed one, to place where the"
		.. " wiring stops")

	-- AND WHETHER THE SERVER HAS EVER SENT A THREAT TABLE, counted from load
	-- rather than asked for now - a readout taken after the fight cannot ask.
	-- UNIT_THREAT_LIST_UPDATE is what NKThreat registers and it is the
	-- decisive signal: no firings during a fight and the API is a stub here,
	-- whatever the calls answer.
	check(shown and shown:find("UNIT_THREAT_LIST_UPDATE fired", 1, true),
		"and how many times the server has sent a threat table since login")
	check(shown and shown:find("never, so far", 1, true),
		"saying plainly when the answer is never")

	-- NOT DRIVEN FROM HERE, and worth saying why. `fire` delivers an event to
	-- the shared pump frame only; the client delivers it to EVERY frame that
	-- registered for it, and this mock records the registration and then
	-- dispatches to one frame. So a module with a listener of its own is deaf
	-- in here and looks correct - which is a real gap, not a small one, and
	-- it is its own piece of work: widening the dispatch wakes handlers across
	-- the suite that have never run once.
	--
	-- Recorded rather than fixed in passing. Until then the counter is checked
	-- by its presence and its wording, and the number itself is only ever read
	-- off a live client.

	-- AND IT ASKS ABOUT THE MOB, not about the unit. Threat is per unit PER
	-- MOB and the mob has to be a unit TOKEN - the generated docs call that
	-- argument mobGUID and then type it UnitToken. A probe that asked
	-- UnitDetailedThreatSituation("player") alone would answer for nothing.
	_G.__units.player.inCombat = true
	_G.__threat.target = {
		player = { false, 1, 84.0, 92.0, 4210 },
		party1 = { true, 3, 100.0, 100.0, 5010 },
	}
	shown = nil
	run("threat probe")
	check(shown and shown:find("scaled=84.0", 1, true),
		"in combat it reports the scaled percentage, which is the ring's fill")
	check(shown and shown:find("tanking=true", 1, true)
		and shown:find("status=3", 1, true),
		"and who is holding it, which is the tank's whole state")

	-- A UNIT THE MOB HAS NEVER HEARD OF still has to read as nothing, in the
	-- same readout as one it has. Both cases in one pull is the normal case in
	-- a group.
	check(shown and shown:find("nothing back", 1, true),
		"with the rest of the group reading nothing in the same breath")

	-- ROLE, WHICH IS THE OTHER HALF OF WHAT THE PROBE IS FOR. Classic Era's
	-- roles are opt-in, so UnitGroupRolesAssigned answers NONE for most people
	-- - and PLAN-Threat.md 2 turns on whether that is what a real party says.
	check(shown and shown:find("assigned role:", 1, true),
		"and it prints what the client says the player's role is")

	-- IT MUST NOT THROW ON A CLIENT WITHOUT THE API. This is the branch the
	-- whole plan is hedging: if the call is missing, the module needs
	-- combat-log inference instead, and the probe is how we would find out.
	local real = _G.UnitDetailedThreatSituation
	_G.UnitDetailedThreatSituation = nil
	shown = nil
	run("threat probe")
	check(shown and shown:find("NO THREAT API ON THIS CLIENT", 1, true),
		"and it says so plainly when the call is not there at all")
	_G.UnitDetailedThreatSituation = real

	_G.__units.player.inCombat = false
	wipe(_G.__threat)
	A.Errors.ShowText = realShow
end)

section("threat: one place decides which tier a unit is in", function()
	local TH = A:GetModule("threat")
	check(TH ~= nil and TH.enabled, "the threat engine is on")
	if not TH then return end

	local TIER = TH.TIER
	-- KEYED BY THE MOB'S GUID, because the aliases are the point: "target",
	-- "pettarget" and "party1target" are three tokens for one boar, and a
	-- fixture keyed on the token answers for the player and for nobody else -
	-- which reads as a whole group of empty rings, i.e. as the design being
	-- quiet.
	local function table_(rows)
		wipe(_G.__threat)
		_G.__threat[UnitGUID("target")] = rows
	end
	local function tier(unit)
		local r = TH:For(unit)
		return r and r.tier or TIER.NONE, r and r.reason or nil, r
	end

	local savedRole = A.Config:Module("threat").role
	local savedPet = _G.__units.pet.exists
	local savedAuras = _G.__auras.player.HELPFUL
	local STANCE = { { "Defensive Stance", 132341, 0, nil, 0, nil, "player", true } }
	_G.__units.player.inCombat = true
	_G.__units.target.inCombat = true

	-- OUT OF COMBAT IS NOTHING AT ALL, whatever the table says. 16b, and it is
	-- also the cheapest gate there is: the client answers nothing out of combat
	-- anyway, so this saves the asking.
	_G.__units.player.inCombat = false
	table_({ player = { true, 3, 100.0, 100.0, 5000 },
		party1 = { false, 0, 40.0, 52.0, 2000 } })
	TH:Poll()
	check(select(1, tier("player")) == TIER.NONE,
		"out of combat there is no threat state at all")
	_G.__units.player.inCombat = true

	-- SOLO, NOBODY ELSE ON THE TABLE: still nothing. 16c is explicit - solo you
	-- ARE the tank of whatever is hitting you, so a mob on you is the normal
	-- state of the world. The threat UI exists only when there is somebody to
	-- lose aggro TO, and this is the rule most likely to be dropped by
	-- accident, because every other rule here would happily draw.
	_G.__units.pet.exists = false
	table_({ player = { true, 3, 100.0, 100.0, 5000 } })
	TH:Poll()
	check(select(1, tier("player")) == TIER.NONE,
		"solo with nobody to lose it to, holding aggro shows nothing")
	_G.__units.pet.exists = savedPet

	-- BELOW THE FLOOR, YOUR OWN RING IS STILL THERE - and this is a departure
	-- from 16b, which says a DPS below 70% shows nothing at all.
	--
	-- It is right for everybody else and wrong for you. A gauge that appears
	-- when you are already in trouble is a report: you cannot pace something
	-- you cannot see, and pacing it is the whole job. Reported from the game -
	-- "there isn't any real indication until I'm basically at 75% and in danger
	-- of pulling aggro. You're telling me what's happened, not what's going to
	-- happen."
	table_({ player = { false, 0, 40.0, 52.0, 2000 },
		party1 = { true, 3, 100.0, 100.0, 5000 },
		party4 = { false, 0, 40.0, 52.0, 2000 } })
	TH:Poll()
	local t0, why0, r0 = tier("player")
	check(t0 == TIER.RING and why0 == "building",
		"a DPS at 40% watches their own ring build (" .. tostring(t0) .. "/"
		.. tostring(why0) .. ")")
	check(r0 and math.abs(r0.fill - 0.40) < 0.01,
		"filled to where they actually are (" .. tostring(r0 and r0.fill) .. ")")

	-- AND NOBODY ELSE'S IS. 16b's quiet rule holds for the rest of the party:
	-- four rings climbing is a wall of arithmetic and none of it is yours to
	-- act on.
	-- party4, in the SAME fixture: party2 is assigned TANK in the mock, and
	-- swapping who is holding to make the point would be swapping the thing the
	-- module now infers a role from - so the two readings would not be of the
	-- same moment.
	check(select(1, tier("party4")) == TIER.NONE,
		"while a party member at the same 40% still shows nothing at all")

	-- PAST THE FLOOR THE CAPSULE STARTS TALKING. 16c: this fires BEFORE the
	-- flip, which is what makes it a warning rather than a report.
	table_({ player = { false, 0, 84.0, 109.2, 4200 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	TH:Poll()
	local t, why, r = tier("player")
	check(t == TIER.WARN and why == "high",
		"past 70% a DPS is warned, not merely ringed (" .. tostring(t) .. "/"
		.. tostring(why) .. ")")
	check(r and math.abs(r.fill - 0.84) < 0.01,
		"with the ring filled from the scaled percentage, which is the design's"
		.. " threat over pull threshold (" .. tostring(r and r.fill) .. ")")

	-- AND THE MODIFIER THE SERVER USED comes back with it, from raw over
	-- scaled: 109.2/84 is 1.3, the ranged threshold. The point is that we did
	-- not measure it. NKThreat gets the same number by probing a per-class
	-- spell's range through the spellbook, with an item-range fallback and a
	-- half-second cache per GUID - and measuring only ever tells you where you
	-- were standing when you asked, where this is what the server decided.
	check(r and r.mod and math.abs(r.mod - 1.3) < 0.01,
		"and the aggro modifier read off raw/scaled rather than measured ("
		.. tostring(r and r.mod) .. ")")

	-- AND IT WARNS ON WHERE YOU ARE GOING, not only where you are.
	--
	-- 16c calls 70% "before the flip". It is not, quite: a cast already in the
	-- air lands after the warning does, so at 70% and climbing you are being
	-- told about something already decided. Climbing at fifteen a second from
	-- fifty is past the floor before the next one finishes.
	TH.__trend = nil
	table_({ player = { false, 0, 20.0, 26.0, 1000 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	TH:Poll()
	check(select(1, tier("player")) == TIER.RING,
		"twenty per cent and standing still is ambient")

	-- THE TABLE FIRST, THEN THE CLOCK. The module polls on its own ticker, so
	-- ticking with the old numbers still in place feeds it a second sample
	-- saying "no change" - and the rate this is trying to measure is diluted
	-- to nothing by the very act of letting time pass.
	for _, at in ipairs({ 40.0, 58.0 }) do
		table_({ player = { false, 0, at, at * 1.3, at * 50 },
			party1 = { true, 3, 100.0, 100.0, 5000 } })
		tick(1)
	end
	local tp, wp, rp = tier("player")
	check(rp and rp.rate and rp.rate > 3,
		"a climb is measured (" .. string.format("%.1f", rp and rp.rate or 0)
		.. " per second)")
	check(tp == TIER.WARN and wp == "high",
		"and past half way, climbing fast, is warned - because the next cast"
		.. " takes it (" .. tostring(tp) .. "/" .. tostring(wp) .. ")")

	-- AND STOPPING CANCELS IT. "Over 50% and rising" is two conditions, and
	-- this is the one that was missing: the rate attacks fast and releases
	-- slow, so a share that has stopped climbing carries a decaying rate for a
	-- second or two - and a projection off that warns about something already
	-- over. At or under the threshold and falling is not high threat.
	table_({ player = { false, 0, 56.0, 72.8, 2700 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	tick(1)
	local td, wd, rd = tier("player")
	check(td == TIER.RING,
		"and fifty-six per cent FALLING is a ring again, however fast it was"
		.. " climbing a second ago (" .. tostring(td) .. "/" .. tostring(wd)
		.. ", rate still " .. string.format("%.1f", rd and rd.rate or 0) .. ")")

	-- AND A SPIKE IS BELIEVED AT ONCE. This is what "snappier" meant: averaging
	-- an increase is what made the warning late, so the rate attacks fast and
	-- releases slow. One sample of a hard climb is enough - waiting for the
	-- average to catch up is waiting for the thing you were warning about.
	TH.__trend = nil
	table_({ player = { false, 0, 35.0, 45.5, 1700 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	tick(1)
	check(select(1, tier("player")) == TIER.RING,
		"a third of the way, standing still, is ambient")
	table_({ player = { false, 0, 55.0, 71.5, 2700 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	tick(1)
	local ts, ws, rs = tier("player")
	check(ts == TIER.WARN and ws == "high",
		"and twenty points in one second warns on the FIRST sample rather than"
		.. " waiting for an average (" .. tostring(ts) .. "/" .. tostring(ws)
		.. " at " .. string.format("%.0f", rs and rs.scaled or 0) .. "%)")

	-- AND NOT AT THE PULL. Early in a fight the holder's threat is small, so
	-- everybody's share of it moves fast: a projection on its own is
	-- arithmetically right and no use at all. Reported from the game as
	-- high-threat warnings at eight per cent.
	--
	-- TWO GUARDS, AND EACH IS THE WHOLE OF ONE CASE.
	--
	-- The window first: two points to eight in a FIFTH of a second is thirty
	-- per second, and three seconds of that projects to ninety-eight. That is
	-- the eight-per-cent warning exactly, and it is a rounding error wearing a
	-- rate's clothes.
	TH.__trend = nil
	table_({ player = { false, 0, 2.0, 2.6, 60 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	tick(1)
	table_({ player = { false, 0, 8.0, 10.4, 240 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	tick(0.2)
	local te, we, re = tier("player")
	check(te == TIER.RING,
		"eight per cent is a ring and nothing else, whatever a fifth of a"
		.. " second says about where it is heading (" .. tostring(te) .. "/"
		.. tostring(we) .. ", projected to " ..
		string.format("%.0f", re and re.ahead or 0) .. "%)")

	-- And the same fault ABOVE the near floor, where that guard cannot save it:
	-- four points in a fifth of a second is twenty per second, which projects
	-- forty per cent past where it is. The two guards answer different halves
	-- of this and the near floor hides the window's half, so it has to be
	-- isolated or it is untested.
	TH.__trend = nil
	for _ = 1, 2 do
		table_({ player = { false, 0, 56.0, 72.8, 2700 },
			party1 = { true, 3, 100.0, 100.0, 5000 } })
		tick(1)
	end
	table_({ player = { false, 0, 60.0, 78.0, 2900 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	tick(0.2)
	local tq, wq, rq = tier("player")
	check(tq == TIER.RING,
		"and sixty per cent, four points on from a fifth of a second ago, is"
		.. " still a ring - that is a rounding error, not a climb (" ..
		tostring(tq) .. "/" .. tostring(wq) .. ", rate " ..
		string.format("%.1f", rq and rq.rate or 0) .. ")")

	-- AND THE BOUNDARY ITSELF. Forty-five climbing hard projects well past the
	-- threshold and is still only a ring: "it should be over 50% and rising",
	-- and forty-five is not over fifty however fast it is moving. Without a
	-- case between the old floor and this one, moving the number back changes
	-- nothing that anybody can see.
	TH.__trend = nil
	table_({ player = { false, 0, 25.0, 32.5, 1200 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	tick(1)
	table_({ player = { false, 0, 45.0, 58.5, 2200 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	tick(1)
	local tb, wb, rb = tier("player")
	check(tb == TIER.RING,
		"forty-five per cent climbing at twenty a second is still a ring (" ..
		tostring(tb) .. "/" .. tostring(wb) .. ", projected to " ..
		string.format("%.0f", rb and rb.ahead or 0) .. "%)")

	-- And the near floor: a climb measured over a proper window, fast
	-- enough to project well past the threshold, but still nowhere near it.
	-- Arithmetically a warning and no use at all - there is nothing to do about
	-- a number that far out but read it.
	TH.__trend = nil
	table_({ player = { false, 0, 5.0, 6.5, 200 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	tick(1)
	table_({ player = { false, 0, 30.0, 39.0, 1400 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	tick(1)
	local tn, wn, rn = tier("player")
	check(tn == TIER.RING,
		"and thirty per cent climbing at twenty-five a second is still only a"
		.. " ring - near enough to matter is half the floor, not a projection"
		.. " on its own (" .. tostring(tn) .. "/" .. tostring(wn) ..
		", projected to " .. string.format("%.0f", rn and rn.ahead or 0)
		.. "%)")

	-- AND A RATE IS NOT CARRIED ACROSS TARGETS, which would be a rate measured
	-- against a different denominator.
	TH.__trend = nil

	-- AND WHEN IT FLIPS. A non-tank holding aggro is the failure state.
	table_({ player = { true, 3, 100.0, 100.0, 5200 },
		party1 = { false, 1, 96.0, 124.8, 4900 } })
	TH:Poll()
	t, why = tier("player")
	check(t == TIER.FAIL and why == "aggro",
		"a DPS holding aggro is the failure tier (" .. tostring(t) .. "/"
		.. tostring(why) .. ")")

	-- THE PET COUNTS AS YOUR TANK. 16c, and it is the case the live probe
	-- caught: a voidwalker holding a boar at 100% with the warlock on
	-- 6.2%. The good state, and the design draws the accent ring on the PET.
	table_({ pet = { true, 3, 100.0, 255.0, 4700 },
		player = { false, 0, 6.2, 8.0, 400 } })
	TH:Poll()
	t, why = tier("pet")
	check(t == TIER.RING and why == "holding",
		"a pet holding securely gets the ambient ring (" .. tostring(t) .. "/"
		.. tostring(why) .. ")")
	local pt, pw = tier("player")
	check(pt == TIER.RING and pw == "building",
		"and its owner, well under the floor, watches their own build rather"
		.. " than waiting to be told (" .. tostring(pt) .. "/" ..
		tostring(pw) .. ")")

	-- AND WHEN IT BREAKS OFF THE PET ONTO YOU the alarm is on YOUR frame and
	-- only there. The pet losing it and you gaining it are one event, and two
	-- alarms for one event is one alarm too many.
	table_({ pet = { false, 0, 60.0, 78.0, 3000 },
		player = { true, 3, 100.0, 100.0, 5000 } })
	TH:Poll()
	check(select(1, tier("player")) == TIER.FAIL,
		"a mob coming off the pet alarms on your frame")
	check(select(1, tier("pet")) == TIER.NONE,
		"and not on the pet's as well - bad news is reported once")

	-- A TANK IS THE SAME SIGNAL READ THE OTHER WAY UP.
	A.Config:Module("threat").role = "tank"
	table_({ player = { true, 3, 100.0, 100.0, 5000 },
		party1 = { false, 0, 20.0, 26.0, 1000 } })
	TH:Poll()
	t, why = tier("player")
	check(t == TIER.RING and why == "holding",
		"a tank holding securely is ambient and stays ambient (" .. tostring(t)
		.. "/" .. tostring(why) .. ")")

	-- LOSING GRIP FIRES ON THE LEAD, NOT ON `status`. The runner-up at 95% of
	-- the tank's threat is the act-now window; status is still 3 here and does
	-- not turn 2 until they are past a hundred per cent, by which time the
	-- window has closed and a warning has become a report.
	table_({ player = { true, 3, 100.0, 100.0, 5000 },
		party1 = { false, 0, 95.0, 123.5, 4750 } })
	TH:Poll()
	t, why = tier("player")
	check(t == TIER.WARN and why == "losing",
		"a tank whose runner-up is past 90% is warned while status still says"
		.. " secure (" .. tostring(t) .. "/" .. tostring(why) .. ")")

	-- AND NOT AT THE PULL. Reported from the game: a pet showing LOSING AGGRO
	-- before a single cast had gone out. Nobody behind you is not a dead heat -
	-- the lead figure is meaningless with no runner-up, and taken at face value
	-- it reads as somebody breathing down your neck.
	--
	-- Read off the challenger's own rawPercentage now, which IS their threat
	-- against the holder's, so 16a's "someone is past 90% of your threat" is
	-- the rule verbatim rather than derived from anything.
	table_({ player = { true, 3, 100.0, 100.0, 5000 },
		party1 = { false, 0, 0.0, 0.0, 0 } })
	TH:Poll()
	local tz, wz = tier("player")
	check(tz == TIER.RING and wz == "holding",
		"a holder with nobody behind them is not warned they are losing it ("
		.. tostring(tz) .. "/" .. tostring(wz) .. ")")

	-- AND THE PLATE SAYS THE SAME, one surface along. A plate is a mob we hold
	-- no records for, so the lead is its only route and it needs the same
	-- guard - the fault was in two places and only one of them was reported.
	do
		_G.__units.target.inCombat = true
		__spawnPlate("nameplate8", { exists = true, name = "Kolkar Drudge",
			level = 17, reaction = 2, hp = 400, hpMax = 900, inCombat = true })
		_G.__threat[UnitGUID("nameplate8")] = {
			player = { true, 3, 100.0, 100.0, 3000 },
		}
		TH:Poll()
		check(TH:Plate("nameplate8") == nil,
			"and a tank's plate is not gold at the pull either")
		__despawnPlate("nameplate8")
	end

	table_({ player = { false, 1, 90.0, 117.0, 4500 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	TH:Poll()
	t, why = tier("player")
	check(t == TIER.FAIL and why == "lost",
		"and a tank who has lost it is the failure tier (" .. tostring(t) .. "/"
		.. tostring(why) .. ")")
	A.Config:Module("threat").role = savedRole

	-- ROLE, WHICH IS THE WHOLE THING INVERTED. Classic Era's roles are opt-in
	-- and say NONE for almost everybody - the live probe said NONE - so taken
	-- literally a warrior tanking correctly gets the DPS treatment: red, a
	-- screen flash and a ping, every pull, for doing their job.
	-- AND THE CLIENT SAYS DAMAGER, not NONE, for somebody in a group who never
	-- answered a poll - that is what a screenshot of a real party showed, and it
	-- is why this mock says so. The threat probe read NONE, but that was solo.
	-- Both are true and the group one is the dangerous one: take DAMAGER at face
	-- value and every real tank gets the DPS treatment.
	check(UnitGroupRolesAssigned("player") == "DAMAGER",
		"the client calls an unset player a DAMAGER once they are in a group")
	check(TH:RoleOf("player") == "damage",
		"which with no stance and no override is the right answer anyway")

	_G.__auras.player.HELPFUL = STANCE
	check(TH:RoleOf("player") == "tank",
		"but a stance beats it - an assignment nobody made must not outrank a"
		.. " stance somebody chose")

	A.Config:Module("threat").role = "damage"
	check(TH:RoleOf("player") == "damage",
		"with the override beating the inference, because inference is a guess"
		.. " and the player is not")
	A.Config:Module("threat").role = savedRole
	_G.__auras.player.HELPFUL = savedAuras

	check(TH:RoleOf("pet") == "tank", "and a pet is always the tank")

	-- AND WHOEVER HAS BEEN HOLDING THE FIGHT IS THE TANK, whatever anybody has
	-- or has not set. This is the third source and on this client the most
	-- useful one: roles are opt-in and almost nobody sets them, a stance
	-- answers it for three classes, and this answers it for all of them from
	-- the only thing that actually matters - who the mob has been attacking.
	--
	-- Reported from the game: "it's not really clear who is tanking or has
	-- aggro if the role hasn't been selected."
	do
		TH.__held, TH.__tank, TH.__trend = nil, nil, nil
		A.Config:Module("threat").role = savedRole

		-- AT THE PULL, THE HOLDER IS PRESUMED TO BE DOING THEIR JOB. Nothing
		-- has flipped yet, and the alternative is a red alarm on the tank for
		-- the first seconds of every fight.
		table_({ party1 = { true, 3, 100.0, 100.0, 5000 },
			player = { false, 0, 20.0, 26.0, 1000 } })
		TH:Poll()
		check(TH:RoleOf("party1") == "tank",
			"the first holder is taken to be the tank straight away")
		check(select(1, tier("party1")) == TIER.RING,
			"so they read as a role doing its job, not as a failure")

		-- A STEAL IS NOT A PROMOTION. Two seconds of holding it does not make
		-- a DPS the tank - if it did, the theft would come up in the calm
		-- accent and the whole feature would invert at the moment it matters.
		for _ = 1, 5 do tick(1) end        -- party1 settles as the tank
		check(TH.__tank == "party1", "and a few seconds of it settles the title")

		table_({ player = { true, 3, 100.0, 100.0, 5200 },
			party1 = { false, 1, 96.0, 124.8, 4900 } })
		tick(1)
		check(TH.__tank == "party1",
			"which a moment's theft does not take away (" ..
			tostring(TH.__tank) .. ")")
		local tt, tw = tier("player")
		check(tt == TIER.FAIL and tw == "aggro",
			"so the thief is alarmed rather than congratulated (" ..
			tostring(tt) .. "/" .. tostring(tw) .. ")")
		check(select(1, tier("party1")) == TIER.FAIL,
			"and the tank is told they have lost it")

		-- AND A REAL HANDOVER DOES CHANGE IT, once it has lasted.
		for _ = 1, 8 do tick(1) end
		check(TH.__tank == "player",
			"while holding it for long enough does make it yours (" ..
			tostring(TH.__tank) .. ")")
		-- Comfortably, so the reading is the plain one: holding it with the
		-- runner-up at 94% of your threat is a tank LOSING GRIP, which is a
		-- true answer to a different question.
		table_({ player = { true, 3, 100.0, 100.0, 5200 },
			party1 = { false, 0, 30.0, 39.0, 1500 } })
		tick(1)
		local ht, hw = tier("player")
		check(ht == TIER.RING and hw == "holding",
			"and then it reads as the job rather than the failure (" ..
			tostring(ht) .. "/" .. tostring(hw) .. ")")

		TH.__held, TH.__tank, TH.__trend = nil, nil, nil
		wipe(_G.__threat)
		TH:Poll()
	end

	-- NOTHING IS NOT ZERO. A unit the mob has never heard of has no record at
	-- all; coerced to zero it would be a DPS sitting at the bottom of the
	-- ring's travel, and the ring would be on for the whole fight.
	table_({ party1 = { true, 3, 100.0, 100.0, 5000 },
		party2 = { false, 0, 80.0, 104.0, 4000 } })
	TH:Poll()
	check(TH:For("player") == nil,
		"a unit that is not on the table has no state, rather than a zero one")

	-- AND A SUBSCRIBER HEARS ABOUT CHANGES, not about ticks. The fill is a
	-- float that trembles every pass; announcing that is announcing every pass.
	local heard = 0
	local fn = TH:Subscribe(function() heard = heard + 1 end)
	table_({ player = { false, 0, 84.0, 109.2, 4200 },
		party1 = { true, 3, 100.0, 100.0, 5000 } })
	TH:Poll()
	local first = heard
	TH:Poll()
	TH:Poll()
	check(first > 0, "a watcher is told when a unit's state changes")
	check(heard == first,
		"and not told again while nothing moves (" .. heard .. " after " ..
		first .. ")")
	TH:Unsubscribe(fn)

	-- ------------------------------------------------------------------
	-- and what it draws
	-- ------------------------------------------------------------------

	-- AND THE ENGINE ACTUALLY DRIVES IT. Everything above tests the decision
	-- and everything below tests the drawing; this is the one check that they
	-- are joined, which is the join a refactor breaks silently.
	do
		local uf2 = A:GetModule("unitframes")
		local pframe, pdisc
		for _, f in ipairs((uf2 and uf2.frames) or {}) do
			if f.unit == "player" then pframe, pdisc = f, f.orb or f.pip end
		end
		if pdisc then
			_G.__units.player.inCombat = true
			_G.__units.target.inCombat = true
			table_({ player = { false, 0, 84.0, 109.2, 4200 },
				party1 = { true, 3, 100.0, 100.0, 5000 } })
			TH:Poll()
			local lit = pdisc.__aetherThreatRing
			check(lit ~= nil and lit:IsShown(),
				"a poll that finds you at 84% puts a ring on your own frame")
			local gold = A.Palette.c.semanticGold
			local rr = lit and select(1, lit.arc:GetVertexColor())
			check(rr and math.abs(rr - gold[1]) < 0.01,
				"in the gold that means the state is about to flip (" ..
				tostring(rr) .. ")")

			-- THE HOLDER SHOWS A FULL RING whatever the arithmetic says. 16b is
			-- explicit, and it matters because the scaled percentage stops
			-- being a fraction of anything useful once you are the one being
			-- hit: the API reports 100 and the design wants the ring closed.
			table_({ player = { true, 3, 100.0, 100.0, 5200 },
				party1 = { false, 1, 96.0, 124.8, 4900 } })
			TH:Poll()
			-- AND THE GLOW SEPARATES THE TWO AMBIENT STATES. A tank holding
			-- securely and a DPS watching their own build share a tier and a
			-- colour - both are "my role is doing its job" - but 16a gives the
			-- halo to the one that is an achievement. On a bar you are simply
			-- pacing it would say something it does not mean.
			table_({ player = { false, 0, 40.0, 52.0, 2000 },
				party1 = { true, 3, 100.0, 100.0, 5000 } })
			TH:Poll()
			check(lit:IsShown() and not lit.glow:IsShown(),
				"your own ring builds without the halo")
			A.Config:Module("threat").role = "tank"
			table_({ player = { true, 3, 100.0, 100.0, 5000 },
				party1 = { false, 0, 20.0, 26.0, 1000 } })
			TH:Poll()
			-- Past any warning still serving its minimum: the gauge is held
			-- with the message now, so a reading taken during one is a reading
			-- of the moment that raised it.
			tick(4)
			check(lit:IsShown() and lit.glow:IsShown(),
				"and a tank holding securely gets it")

			-- AND A SHIELD ON WHOEVER IS ACTUALLY HOLDING IT, which is the
			-- thing that was most missing: "it's not clear who currently has
			-- aggro. The gauge is not definitive." It stopped being definitive
			-- the moment your own ring became continuous - a lit ring no longer
			-- means "this one has it", it means "this one is a unit" - so the
			-- holder is now said outright, in the disc's fourth free corner
			-- beside the crown, the raid mark and the role glyph.
			check(lit.held ~= nil and lit.held:IsShown(),
				"and a mark saying outright that this is the one holding it")
			A.Config:Module("threat").role = savedRole
			table_({ player = { false, 0, 40.0, 52.0, 2000 },
				party1 = { true, 3, 100.0, 100.0, 5000 } })
			TH:Poll()
			tick(4)
			check(not lit.held:IsShown(),
				"and gone from anybody who is not")
			A.Config:Module("threat").role = "tank"
			table_({ player = { true, 3, 100.0, 100.0, 5000 },
				party1 = { false, 0, 20.0, 26.0, 1000 } })
			TH:Poll()
			A.Config:Module("threat").role = savedRole

			-- A HOLDER'S RING IS THE HEADROOM LEFT, and it is the exact
			-- complement of the closest challenger's. A challenger's ring is
			-- their share of the PULL THRESHOLD - at 1 they take it - so what
			-- is left of the holder's is precisely how much room there is
			-- before somebody does.
			local challenger = TH:For("party1")
			check(challenger and lit.fill
				and math.abs(lit.fill + math.min(1, challenger.scaled / 100) - 1)
					< 0.01,
				"the holder's ring and the challenger's sum to one (" ..
				string.format("%.2f", lit.fill or -1) .. " + " ..
				string.format("%.2f", challenger and challenger.scaled / 100 or -1)
				.. ")")

			-- AND BEING CAUGHT DRAINS IT. Two readings of one fight, moving
			-- against each other: the holder used to sit at a flat full,
			-- because the server reports whoever is holding at a scaled 100 by
			-- definition - so as somebody climbed toward them, nothing on their
			-- capsule moved at all. Reported from the game: "when I'm gaining
			-- 40% aggro on my gauge, they should be missing 40% on theirs."
			A.Config:Module("threat").role = "tank"
			table_({ player = { true, 3, 100.0, 100.0, 5200 },
				party1 = { false, 1, 96.0, 124.8, 4900 } })
			TH:Poll()
			tick(4)
			local drained = lit.fill
			check(drained and drained < 0.3 and drained > 0,
				"and a runner-up on your heels drains it toward empty (" ..
				string.format("%.2f", drained or -1) .. ")")

			-- AND THE REDRAW NOTICES. A holder's scaled percentage is 100 by
			-- definition and never moves; only their LEAD does. Deciding
			-- whether anything has changed by comparing shares said "nothing"
			-- for the whole of a tank losing their lead - so the one gauge with
			-- something to say was the one that never redrew. Both readings
			-- here are the same tier and the same share; only the ring differs.
			A.Config:Module("threat").role = "tank"
			table_({ player = { true, 3, 100.0, 100.0, 5600 },
				party1 = { false, 0, 60.0, 78.0, 4000 } })
			TH:Poll()
			tick(4)
			local wide = lit.fill
			table_({ player = { true, 3, 100.0, 100.0, 4800 },
				party1 = { false, 0, 80.0, 104.0, 4000 } })
			TH:Poll()
			check(wide and lit.fill and lit.fill < wide - 0.1,
				"a lead closing redraws the holder's ring, though their share"
				.. " of the table has not moved at all (" ..
				string.format("%.2f", wide or -1) .. " -> " ..
				string.format("%.2f", lit.fill or -1) .. ")")

			-- NEVER QUITE NOTHING. A ring that vanishes at the moment it
			-- matters most reads as the module having given up rather than as
			-- a lead having gone.
			-- A DEAD HEAT: the challenger is AT the threshold, so the
			-- complement is exactly nothing. Ninety-nine leaves a hundredth
			-- behind and cannot show whether the floor is doing anything.
			table_({ player = { true, 3, 100.0, 100.0, 5000 },
				party1 = { false, 1, 100.0, 130.0, 5000 } })
			TH:Poll()
			tick(4)
			check((lit.fill or 0) > 0,
				"without ever going out entirely (" ..
				string.format("%.2f", lit.fill or -1) .. ")")

			-- AND THE TWO ARE COMPLEMENTARY at the moment of a steal: one ring
			-- closes as the other opens.
			A.Config:Module("threat").role = savedRole
			TH.__tank, TH.__held = nil, nil
			table_({ player = { false, 0, 96.0, 124.8, 4900 },
				party1 = { true, 3, 100.0, 100.0, 5200 } })
			TH:Poll()
			local mine = TH:For("player")
			local theirs = TH:For("party1")
			check(mine and theirs and mine.fill > 0.9 and theirs.fill < 0.1,
				"about to take it: yours nearly closed, theirs nearly open (" ..
				string.format("%.2f", mine and mine.fill or -1) .. " vs " ..
				string.format("%.2f", theirs and theirs.fill or -1) .. ")")

			-- AND THE REPORTED CASE, exactly. A warlock at 52% of the pull
			-- threshold with the pet holding: the pet used to read 96% under a
			-- lead-based mapping, because 52% of the threshold is already two
			-- thirds of the pet's threat and half again the runner-up counted
			-- as secure. "I have 60% threat but the pet shows 100% still."
			table_({ pet = { true, 3, 100.0, 255.0, 5000 },
				player = { false, 0, 52.0, 67.6, 3380 } })
			TH:Poll()
			local heldBy = TH:For("pet")
			check(heldBy and math.abs(heldBy.fill - 0.48) < 0.02,
				"a pet holding against a warlock on 52% reads 48%, not 96% (" ..
				string.format("%.2f", heldBy and heldBy.fill or -1) .. ")")

			A.Config:Module("threat").role = "tank"
			table_({ player = { true, 3, 100.0, 100.0, 5000 },
				party1 = { false, 0, 20.0, 26.0, 1000 } })
			TH:Poll()
			tick(4)
			A.Config:Module("threat").role = savedRole

			-- AND IT IS HELD WITH THE MESSAGE. The chip stays up for its
			-- minimum after the state resolves; the gauge used to carry on
			-- tracking, so the capsule said two things about two different
			-- moments - a chip reading AGGRO - ON YOU beside a gauge already
			-- back at two pips.
			-- FORCED TO DAMAGE, and the observed tank forgotten: by this point
			-- the player has been holding the fixture for several passes, so
			-- the module has correctly decided they ARE the tank - and a tank
			-- holding is no warning at all, which leaves nothing to hold.
			A.Config:Module("threat").role = "damage"
			TH.__tank, TH.__held = nil, nil
			table_({ player = { true, 3, 100.0, 100.0, 5200 },
				party1 = { false, 1, 96.0, 124.8, 4900 } })
			TH:Poll()
			table_({})
			lit.__aetherFading = nil
			TH:Poll()
			check(lit:IsShown() and (lit.__aetherWant or 0) == 1,
				"the gauge is held while the warning it belongs to is")

			-- AND THEN IT ACTUALLY GOES. This used to read
			-- `__aetherWant == 0`, which asks whether the ring was TOLD to go -
			-- a different and much easier question. It was told, and nothing
			-- ever stepped it: the clear path set the target and returned
			-- without starting the fade, so the ring sat at full alpha round
			-- the pip for the rest of the session. Reported from a screenshot,
			-- not from here.
			tick(4)
			check((lit.__aetherWant or 0) == 0,
				"and the message's time being up asks the ring to go with it")
			A.Config:Module("threat").role = savedRole
			-- DRIVEN BY THE WIDGET, which is the half that was missing: the
			-- clear path set the target and returned without starting the
			-- fade, so the ring sat at full alpha round the pip for the rest of
			-- the session. Cleared first, because the flag is set by a fade
			-- that started earlier in this block and nothing in here runs the
			-- OnUpdate that would clear it - so read as it stood, it was true
			-- whatever the code did.
			check(lit.__aetherFading == true,
				"and the widget starts the fade itself rather than waiting for"
				.. " somebody to remember to")
			local spin = 0
			while A.Widgets.StepFade(lit, 0.05) and spin < 40 do
				spin = spin + 1
			end
			check(not lit:IsShown() and spin < 40,
				"and it is gone by the end of it (" .. spin .. " steps)")
			_G.__units.player.inCombat = false
			_G.__units.target.inCombat = false
		end
	end

	-- ------------------------------------------------------------------
	-- and the capsule starts talking, which is tiers two and three
	-- ------------------------------------------------------------------
	do
		local uf3 = A:GetModule("unitframes")
		local pframe
		for _, f in ipairs((uf3 and uf3.frames) or {}) do
			if f.unit == "player" then pframe = f end
		end
		if pframe then
			_G.__units.player.inCombat = true
			_G.__units.target.inCombat = true

			-- TIER 1 SAYS NOTHING BEYOND THE RING. Good news never escalates,
			-- and the ambient tier is the one a tank sits in all fight.
			A.Config:Module("threat").role = "tank"
			table_({ player = { true, 3, 100.0, 100.0, 5000 },
				party1 = { false, 0, 20.0, 26.0, 1000 } })
			TH:Poll()
			local al = pframe.__aetherAlarm
			check(al ~= nil, "the capsule gets an alarm to hang tiers on")
			-- Past any minimum still being served from the tier checks above:
			-- an alarm holds itself up for a few seconds whatever the state
			-- does, so "nothing is showing" is only a fair question once that
			-- has expired.
			tick(4)
			check(al and (al.spec == nil),
				"and the ambient tier hangs nothing on it")

			-- TIER 2 IS THE ACT-NOW WINDOW, and it says which problem it is.
			table_({ player = { true, 3, 100.0, 100.0, 5000 },
				party1 = { false, 0, 95.0, 123.5, 4750 } })
			TH:Poll()
			check(al.spec ~= nil and al.wash:IsShown(),
				"a warning washes the capsule")

			-- LAID OVER THE READOUT, not instead of it. The design's capsule
			-- has no readout at its right end where ours does, so that is the
			-- one thing the chip covers - and the health and power are drawn as
			-- BARS anyway, so the number is the least of what that corner says.
			-- Nothing is hidden: the moment it clears, the capsule is what it
			-- was.
			local point, anchoredTo = al.chip:GetPoint(1)
			check(anchoredTo == (pframe.sub or pframe.class or pframe.hpText),
				"the chip is aligned to the line beside the name it lies on")

			-- AND ON A PARTY CAPSULE TOO, which calls that line something else.
			-- The unit frames call it `sub` and the party capsules call it
			-- `class`; asking only for `sub` fell through to the readout, which
			-- on a party capsule is out past the bars - so the chip hung off
			-- the end of the frame entirely. Checked only on the unit frame, it
			-- looked right.
			local pfm = A:GetModule("partyframes")
			local mate2
			for _, f in ipairs((pfm and pfm.frames) or {}) do
				if f.unit == "party1" and f:IsShown() then mate2 = f end
			end
			if mate2 then
				table_({ party1 = { false, 0, 84.0, 109.2, 4200 },
					party2 = { true, 3, 100.0, 100.0, 5000 } })
				TH:Poll()
				local mal2 = mate2.__aetherAlarm
				-- NOT `mal2 and mal2.chip:GetPoint(1)`. An `and` keeps ONE
				-- value, so the second return - the frame it is anchored to -
				-- comes back nil and the check fails whatever the code did.
				-- Fourth time this exact trap has been fallen into in this
				-- file; it wears a different hat each time.
				local mto = nil
				if mal2 then mto = select(2, mal2.chip:GetPoint(1)) end
				check(mto == mate2.class,
					"including on a party capsule, which calls it `class`")
			end
			check(point == "LEFT" or point == "RIGHT",
				"by its near edge, so it grows away from the name into the"
				.. " empty half rather than back across it (" ..
				tostring(point) .. ")")
			check((pframe.sub or pframe.hpText):IsShown(),
				"which is still there underneath it - over, not instead of")
			check(al.chip:GetFrameLevel() > pframe.glass:GetFrameLevel(),
				"and above the capsule's contents, or it would interject from"
				.. " underneath them (" .. tostring(al.chip:GetFrameLevel())
				.. " on " .. tostring(pframe.glass:GetFrameLevel()) .. ")")
			check(al.chip:IsShown()
				and (al.chip.text:GetText() or ""):find("L O S I N G", 1, true),
				"and names the problem in the design's own words (" ..
				tostring(al.chip.text:GetText()) .. ")")
			check(al.spec.period == A.Widgets.PULSE_WARN,
				"pulsing at the warning tier's 1.2s (" ..
				tostring(al.spec.period) .. ")")

			-- LETTER-SPACED, because the design tracks it and the client has no
			-- letter-spacing - the spacing goes into the string, through the
			-- same helper the section headings use.
			check((al.chip.text:GetText() or ""):find("L O S", 1, true) ~= nil,
				"tracked the way the design draws it")

			-- AND THE ROLE CHANGES THE WORDS, not the treatment. Red means "the
			-- mob is where it should not be" for YOUR role, both ways round.
			A.Config:Module("threat").role = "damage"
			table_({ player = { true, 3, 100.0, 100.0, 5200 },
				party1 = { false, 1, 96.0, 124.8, 4900 } })
			TH:Poll()
			check((al.chip.text:GetText() or ""):find("O N   Y O U", 1, true),
				"a DPS holding it is told so in theirs (" ..
				tostring(al.chip.text:GetText()) .. ")")
			check(al.spec.period == A.Widgets.PULSE_FAIL,
				"and the failure tier pulses faster (" ..
				tostring(al.spec.period) .. ")")

			-- THE LIVE FIGURE, ON YOUR OWN FRAME ONLY. 16c puts it on the
			-- player's warning chip; four of them across a party is a row of
			-- arithmetic nobody reads in the second they have.
			table_({ player = { false, 0, 84.0, 109.2, 4200 },
				party1 = { true, 3, 100.0, 100.0, 5000 } })
			TH:Poll()
			check((al.chip.text:GetText() or ""):find("8 4 %%") ~= nil,
				"your own warning carries the live percentage (" ..
				tostring(al.chip.text:GetText()) .. ")")

			-- AND NOBODY ELSE'S DOES. Checked on a party capsule, because a
			-- check that only ever reads the player's frame cannot tell "on
			-- your own frame" from "on every frame" - and that is exactly the
			-- distinction 16c draws.
			local pf3 = A:GetModule("partyframes")
			local mate
			for _, f in ipairs((pf3 and pf3.frames) or {}) do
				if f.unit == "party1" and f:IsShown() then mate = f end
			end
			if mate then
				table_({ party1 = { false, 0, 84.0, 109.2, 4200 },
					party2 = { true, 3, 100.0, 100.0, 5000 } })
				TH:Poll()
				local mal = mate.__aetherAlarm
				local said = mal and mal.chip.text:GetText() or ""
				check(said:find("H I G H", 1, true) ~= nil,
					"a party member is warned in the same words (" .. said .. ")")
				check(said:find("%%") == nil,
					"and without the arithmetic - four live figures across a"
					.. " party is a row nobody reads in the second they have ("
					.. said .. ")")

				-- And put the player back where the rest of this block expects
				-- them: a check that leaves the fixture somewhere else is a
				-- check that breaks the next one for a reason nobody can see.
				table_({ player = { false, 0, 84.0, 109.2, 4200 },
					party1 = { true, 3, 100.0, 100.0, 5000 } })
				TH:Poll()
			end

			-- THE PULSE MOVES, and it moves on the shared ticker rather than on
			-- a frame script nothing here can drive.
			local before = select(4, al.wash._edgeColor and
				unpack(al.wash._edgeColor)) or 0
			local e1 = al.wash._edgeColor and al.wash._edgeColor[1]
			tick(0.3)
			local e2 = al.wash._edgeColor and al.wash._edgeColor[1]
			check(e1 and e2 and math.abs(e1 - e2) > 0.001,
				"the capsule pulses (" .. tostring(e1) .. " -> " ..
				tostring(e2) .. ")")
			local _ = before

			-- RINGS ONLY DROPS THE CHIP AND KEEPS THE BORDER. That is what the
			-- setting says it does.
			A.Config:Module("threat").display = "rings"
			TH:Draw("player", TH:For("player"))
			check(al.spec ~= nil and al.spec.label == nil,
				"rings-only keeps the wash and drops the words")
			A.Config:Module("threat").display = "full"

			-- AND IT STAYS LONG ENOUGH TO BE READ. 16c clears it within 500ms
			-- of the state resolving and says nothing about a floor; in
			-- practice the state does not linger - you cross the threshold and
			-- drop back - and the chip flashed up and was gone before the eye
			-- had been drawn to it. You could tell something had happened and
			-- had no idea what.
			table_({})
			TH:Poll()
			check(al.spec ~= nil and al.wash:IsShown(),
				"the state resolving does not take the warning off the screen"
				.. " immediately")
			check(al.pending == true, "it is on its way out, and waiting")
			tick(0.5)
			check(al.spec ~= nil,
				"still up half a second later, where the handoff would have"
				.. " had it gone")

			-- AND THEN IT GOES.
			tick(4)
			check(al.spec == nil and (al.wash.__aetherWant or 0) == 0
				and (al.chip.__aetherWant or 0) == 0,
				"and off once it has had its time")

			-- A STATE THAT COMES BACK DURING THE WAIT KEEPS IT UP, rather than
			-- clearing on the old timer and flashing up again a moment later.
			table_({ player = { true, 3, 100.0, 100.0, 5200 },
				party1 = { false, 1, 96.0, 124.8, 4900 } })
			TH:Poll()
			table_({})
			TH:Poll()
			check(al.pending == true, "a resolved state starts the wait")
			table_({ player = { true, 3, 100.0, 100.0, 5200 },
				party1 = { false, 1, 96.0, 124.8, 4900 } })
			TH:Poll()
			check(al.pending == nil and al.spec ~= nil,
				"and it coming back cancels it rather than restarting the"
				.. " whole thing")
			table_({})
			TH:Poll()
			tick(4)

			A.Config:Module("threat").role = savedRole
			_G.__units.player.inCombat = false
			_G.__units.target.inCombat = false
		end
	end

	-- ------------------------------------------------------------------
	-- and the screen, which is yours alone
	-- ------------------------------------------------------------------
	do
		_G.__units.player.inCombat = true
		_G.__units.target.inCombat = true
		A.Config:Module("threat").role = "damage"
		A.Config:Module("threat").alarms = true
		TH.__lastAlarm = nil
		_G.__playedSound = nil

		-- Below the failure tier, nothing. The flash is for the moment you lose
		-- it, not for the moment you are worried about losing it.
		table_({ player = { false, 0, 84.0, 109.2, 4200 },
			party1 = { true, 3, 100.0, 100.0, 5000 } })
		TH:Poll()
		check(_G.__playedSound == nil,
			"a warning does not touch the screen or the speakers")

		-- AND THEN IT FLIPS.
		table_({ player = { true, 3, 100.0, 100.0, 5200 },
			party1 = { false, 1, 96.0, 124.8, 4900 } })
		TH:Poll()
		check(_G.__playedSound == _G.SOUNDKIT.RAID_WARNING,
			"taking it rings, in the client's own alert rather than an asset"
			.. " of ours (" .. tostring(_G.__playedSound) .. ")")
		local flash = A.Widgets.__flash
		check(flash ~= nil and flash:IsShown(), "and flashes the screen edge")
		check(flash and flash:GetFrameStrata() == "FULLSCREEN_DIALOG",
			"over everything, because it is the thing you must not miss")

		-- TWO BEATS AND GONE. 16c says a brief two-beat pulse; a flash that
		-- stayed up would be a red screen for the rest of the fight.
		local peaks, last, rising = 0, flash:GetAlpha(), false
		local guard = 0
		while A.Widgets.StepScreenFlash(0.05) and guard < 100 do
			local a = flash:GetAlpha()
			if a > last and not rising then rising = true end
			if a < last and rising then peaks = peaks + 1 rising = false end
			last = a
			guard = guard + 1
		end
		check(peaks == 2, "twice, and no more (" .. peaks .. " beats)")
		check(not flash:IsShown(), "and then it is gone")

		-- ONCE EVERY SIX SECONDS. A chaotic pull flips this state over and
		-- over, and an alarm that can strobe is an alarm people switch off.
		_G.__playedSound = nil
		table_({ player = { false, 0, 40.0, 52.0, 2000 },
			party1 = { true, 3, 100.0, 100.0, 5000 } })
		TH:Poll()
		table_({ player = { true, 3, 100.0, 100.0, 5200 },
			party1 = { false, 1, 96.0, 124.8, 4900 } })
		TH:Poll()
		check(_G.__playedSound == nil,
			"losing it again a moment later is silent")

		-- AND STILL SILENT AFTER THE LIMIT HAS EXPIRED, while the state has not
		-- changed. This is what the rising edge is for, and it is invisible
		-- behind the rate limit until the clock passes it: fired from "is it
		-- true" rather than "did it just become true", holding aggro for seven
		-- seconds alarms twice for one event.
		_G.__playedSound = nil
		tick(7)
		TH:Poll()
		check(_G.__playedSound == nil,
			"and still silent once the limit expires, because nothing new has"
			.. " happened")

		-- AND THE TOGGLE TURNS IT OFF WITHOUT TURNING OFF THE RINGS. It is a
		-- setting of its own for exactly that reason.
		A.Config:Module("threat").alarms = false
		TH.__lastAlarm = nil
		_G.__playedSound = nil
		table_({ player = { false, 0, 40.0, 52.0, 2000 },
			party1 = { true, 3, 100.0, 100.0, 5000 } })
		TH:Poll()
		table_({ player = { true, 3, 100.0, 100.0, 5200 },
			party1 = { false, 1, 96.0, 124.8, 4900 } })
		TH:Poll()
		check(_G.__playedSound == nil, "switched off, it stays quiet")
		check(select(1, tier("player")) == TIER.FAIL,
			"while the capsule still says what happened")
		A.Config:Module("threat").alarms = true

		A.Config:Module("threat").role = savedRole
		TH.__lastAlarm = nil
		_G.__units.player.inCombat = false
		_G.__units.target.inCombat = false
	end

	-- ------------------------------------------------------------------
	-- 16d: which of these is about to come at me
	-- ------------------------------------------------------------------
	do
		local np2 = A:GetModule("nameplates")
		_G.__units.player.inCombat = true
		A.Config:Module("threat").role = "damage"

		__spawnPlate("nameplate9", { exists = true, name = "Kolkar Marauder",
			level = 18, reaction = 2, hp = 500, hpMax = 900, inCombat = true })
		_G.__threat[UnitGUID("nameplate9")] = {
			player = { false, 0, 20.0, 26.0, 900 },
			party1 = { true, 3, 100.0, 100.0, 4500 },
		}
		TH:Poll()
		check(TH:Plate("nameplate9") == nil,
			"a mob on its proper target keeps the client's own border - quiet")

		-- RISING ON ITS TABLE: the plate to act on.
		_G.__threat[UnitGUID("nameplate9")].player = { false, 0, 78.0, 101.4, 3500 }
		TH:Poll()
		local pc = TH:Plate("nameplate9")
		check(pc ~= nil and math.abs(pc[1] - A.Palette.c.semanticGold[1]) < 0.3,
			"past 70% on its table it goes gold")

		-- AND COMING AT THE WRONG PERSON.
		_G.__threat[UnitGUID("nameplate9")].player = { true, 3, 100.0, 100.0, 5000 }
		_G.__threat[UnitGUID("nameplate9")].party1 = { false, 1, 90.0, 117.0, 4500 }
		TH:Poll()
		local rc, floor = TH:Plate("nameplate9")
		check(rc ~= nil and rc[1] > rc[3],
			"and red when it is on somebody it should not be on")

		-- EVERY ENGAGED PLATE CARRIES ITS COLOUR, targeted or not. The deck
		-- dims everything that is not your target; 16d says the disposition
		-- shows regardless, so it sets a floor the deck may raise and not go
		-- under.
		check(floor and floor > 0.5,
			"carried whether you are looking at it or not (" ..
			tostring(floor) .. ")")

		-- AND IT PULSES, at the plates' own rate and no faster. A screen of
		-- plates beating at the capsule's 0.8s is a strobe.
		-- READ ON THE GREEN CHANNEL, not the red. A pulse is brightness, and
		-- brightness on a colour already at 1 in a channel is clamped there -
		-- the red alarm brightens by washing toward white, which is what a
		-- brightness ramp does and is also the right read. Watching the channel
		-- that cannot move is watching nothing.
		local was = TH:Plate("nameplate9")[2]
		TH.__pulseAt = (TH.__pulseAt or 0) + A.Widgets.PULSE_WARN / 2
		check(math.abs(TH:Plate("nameplate9")[2] - was) > 0.001,
			"pulsing on the way (" .. tostring(was) .. " -> " ..
			tostring(TH:Plate("nameplate9")[2]) .. ")")

		-- AND THE PLATE ACTUALLY WEARS IT. Everything above reads the module's
		-- answer; this reads the frame. They are joined by one line in the
		-- deck's own paint, and a check that never looks at the plate cannot
		-- tell whether that line is there.
		local plate = np2 and np2.byUnit and np2.byUnit.nameplate9
		if plate then
			np2:RepaintThreat(nil)
			local worn = plate.__edgeColor or (plate._edgeColor)
			local want = TH:Plate("nameplate9")
			check(worn and want and math.abs(worn[1] - want[1]) < 0.02
				and math.abs(worn[2] - want[2]) < 0.02,
				"the plate wears the disposition rather than its reaction ("
				.. string.format("%.2f/%.2f", worn and worn[1] or -1,
					worn and worn[2] or -1) .. " vs " ..
				string.format("%.2f/%.2f", want[1], want[2]) .. ")")
			check(plate.__rimColor ~= nil or plate._rimColor ~= nil,
				"and glows with it whether it is your target or not")
		end

		-- BORDER AND GLOW ONLY. No ring, no chip, no size change: the plate
		-- answers a different question from the capsule and 16d is explicit.
		check(TH.plates["nameplate9"] ~= nil
			and TH.plates["nameplate9"].colour ~= nil,
			"the disposition is a colour and nothing else")

		-- OUT OF COMBAT, THE DEFAULT BORDER.
		_G.__units.player.inCombat = false
		TH:Poll()
		check(TH:Plate("nameplate9") == nil,
			"and out of combat every plate goes back to the client's own")

		__despawnPlate("nameplate9")
		wipe(_G.__threat)
		A.Config:Module("threat").role = savedRole
	end

	-- ONE MECHANISM FOR A GAUGE THAT FILLS ROUND A DISC. Classic has no conic
	-- gradient and no arc primitive, so this is a sheet of baked steps - and it
	-- is the flight console's sheet at a different band width rather than a
	-- second dial invented beside the first.
	local sheet = A.Media.dialSheet
	check(sheet and sheet.steps == 64 and sheet.cols == 8,
		"the dial sheet is shared geometry rather than one per caller")
	check(A.Media.dial.threat and A.Media.dial.threat.arc
		and A.Media.dial.ifec and A.Media.dial.ifec.arc,
		"with a family per band width, both off the same layout")
	local ifecFile = A.Media:DialArc(0.5, "ifec")
	local threatFile = A.Media:DialArc(0.5, "threat")
	check(ifecFile ~= threatFile and threatFile ~= nil,
		"and asking for one gets that one, not the other (" ..
		tostring(threatFile) .. ")")
	check(A.Media.dial.threat.track == nil,
		"the threat ring has no track behind it - below the floor 16b draws"
		.. " nothing, and a track would be a faint ring round every pip all"
		.. " fight")

	-- AND THE STEP IS PICKED FROM THE FILL. Frame i is (i+1)/64 of a turn, so
	-- there is no empty frame and a fill under the first step has nothing to
	-- draw - which is the same answer as hiding it.
	local _, l1 = A.Media:DialArc(0.05, "threat")
	local _, l2 = A.Media:DialArc(0.90, "threat")
	check(l1 ~= l2, "the sheet steps with the fill (" .. tostring(l1) .. " vs "
		.. tostring(l2) .. ")")
	check(A.Media:DialArc(0, "threat") == nil,
		"and nothing at all below the first step")

	-- THE RING GOES ON THE DISC EVERYBODY ALREADY WATCHES. 16b reuses the pip
	-- rather than adding an element, and that is what makes one ring work at
	-- the party capsule's size and the player frame's.
	local pf = A:GetModule("partyframes")
	local uf = A:GetModule("unitframes")
	local function discOf(unit)
		for _, mod in ipairs({ uf, pf }) do
			for _, f in ipairs((mod and mod.frames) or {}) do
				if f.unit == unit then return f, f.orb or f.pip end
			end
		end
	end
	local host, disc = discOf("player")
	check(disc ~= nil, "the player frame has a disc to hang it on")

	if disc then
		local ring = A.Widgets.ThreatRing(host, disc)
		check(ring ~= nil, "and a ring is built on it")
		check(A.Widgets.ThreatRing(host, disc) == ring,
			"once, however often we come past - the frames rebuild on a skin"
			.. " change and a ring per call would stack")

		-- 16b's proportions, as a RATIO: 44 outer on a 38 pip, and the same
		-- ring has to sit round the player frame's larger orb. Written as two
		-- fixed sizes it would be right on one frame and wrong on the other.
		local box = ring:GetWidth()
		local want = disc:GetWidth() * (A.Widgets.RING_OUTER
			/ A.Widgets.RING_DISC) / sheet.ring
		-- WITHIN A PIXEL, because the box is snapped: 44/38 of a 38 pip over
		-- the 0.875 inset is 50.3 units, and a frame centred on another at a
		-- fractional size puts its edges on half pixels - which is a ring a
		-- pixel up and left of the disc it should be concentric with.
		local step = A:PxIn(ring)
		check(math.abs(box - want) <= step * 2,
			"sized from the disc rather than fixed, so it scales with it ("
			.. string.format("%.1f", box) .. " vs " ..
			string.format("%.1f", want) .. ")")
		check(math.abs(box / (step * 2) - math.floor(box / (step * 2) + 0.5))
			< 0.01,
			"and on an even number of physical pixels, so its centre is a"
			.. " pixel rather than half of one (" ..
			string.format("%.3f", box / step) .. " px)")

		-- UNDER THE DECORATORS AND OVER THE DISC. The crown, the raid mark, the
		-- PvP flag and the role glyph ride the disc's corners on a layer two
		-- levels up, and 16b says they keep their positions ON TOP.
		check(ring:GetFrameLevel() > disc:GetFrameLevel()
			and ring:GetFrameLevel() < disc:GetFrameLevel() + 2,
			"drawn over the disc and under the decorators (" ..
			tostring(ring:GetFrameLevel()) .. " on " ..
			tostring(disc:GetFrameLevel()) .. ")")

		-- AND IT IS OFF UNTIL THERE IS SOMETHING TO SAY.
		A.Widgets.SetThreatRing(ring, nil, nil, false)
		ring:SetAlpha(0) ring:Hide()
		check(not ring:IsShown(), "and hidden when there is nothing to show")

		-- COLOUR IS THE TIER, WHICH IS THE ROLE ALREADY READ. Calm accent is
		-- one state only - a role doing its job - and it is the only one that
		-- carries the steady glow. Gold and red both mean act now.
		local c = A.Palette.c
		A.Widgets.SetThreatRing(ring, 1, c.accent, true)
		check(ring:IsShown() and ring.glow:IsShown(),
			"the ambient tier is the one state with a steady glow")
		A.Widgets.SetThreatRing(ring, 0.84, c.semanticGold, false)
		check(ring:IsShown() and not ring.glow:IsShown(),
			"and a warning has none - motion and light both mean act now, and"
			.. " saying it twice says it less")

		-- FADED, NOT CUT. 16b gives it 300ms on combat end, and the ring drives
		-- that itself rather than off the shared ticker: the ticker runs at a
		-- tenth of a second, which is three steps across the whole fade.
		ring:SetAlpha(1)
		A.Widgets.SetThreatRing(ring, nil, nil, false)
		check(ring:IsShown() and ring:GetAlpha() > 0.9,
			"asked to go, it is still up on the same frame")
		-- STEPPED FROM HERE, not from the frame's own OnUpdate. `tick` drives
		-- the shared pump and nothing else, so a fade written into a SetScript
		-- is a fade the suite cannot watch - which is exactly why the step is
		-- a function and the script is one line calling it.
		A.Widgets.StepFade(ring, 0.1)
		local mid = ring:GetAlpha()
		check(mid < 0.9 and mid > 0.05,
			"part way out a tenth of a second later (" ..
			string.format("%.2f", mid) .. ")")
		local guard = 0
		while A.Widgets.StepFade(ring, 0.05) and guard < 40 do
			guard = guard + 1
		end
		check(not ring:IsShown() and guard < 40,
			"and gone by the end of the fade, in about three tenths (" ..
			guard .. " steps of 0.05)")
	end

	wipe(_G.__threat)
	_G.__units.player.inCombat = false
	_G.__units.target.inCombat = false
	TH:Poll()
end)

print("== phrases: every word we wrote, where a translator can reach it ==")
do
	-- THE PHRASE LIST AND THE SOURCE HAVE TO AGREE.
	--
	-- Locale/enUS.lua is the English and is EDITED rather than generated:
	-- correcting a sentence there moves no key, so no translation of it is
	-- orphaned by the fix. What that costs is this check - a key the source
	-- asks for and the file has not got draws its own path, which nobody
	-- reading it in English would ever see.
	local missing, seen, count = {}, {}, 0
	for _, path in ipairs(FILES) do
		-- Locale.lua is where the table is BUILT and the locale files are where
		-- it is filled; neither asks it for anything.
		if not path:find("Locale", 1, true) then
			local fh = io.open(path, "rb")
			if fh then
				local text = fh:read("*a") or ""
				fh:close()
				-- AND ONLY WHERE `L` IS THE PHRASE TABLE. Core/Launchers.lua
				-- calls its own module table L and writes L.RawSetPoint into
				-- it, which has the shape of a phrase and is not one. Every
				-- file that asks for a phrase declares the table on one line,
				-- and there is a check below that says so.
				if not text:find("\nlocal L = A%.L") then text = "" end
				for key in text:gmatch("[^%w_]L%.([%w_]+[%w_%.]*)") do
					if not seen[key] then
						seen[key] = true
						count = count + 1
						-- Walked rather than indexed, because the table is
						-- nested for reading and flat underneath.
						local node = A.L
						for part in key:gmatch("[^%.]+") do
							if type(node) ~= "table" then break end
							node = node[part]
						end
						if type(node) ~= "string" then
							missing[#missing + 1] = key
						end
					end
				end
			end
		end
	end
	table.sort(missing)

	check(#missing == 0,
		"every phrase the source asks for is in Locale/enUS.lua (" ..
		(#missing > 0 and
		table.concat(missing, ", ", 1, math.min(#missing, 4))
		or count .. " phrases") .. ")")

	-- AND EVERY KEY IN IT CAN ACTUALLY BE REACHED.
	--
	-- Locale/enUS.lua is EDITED BY HAND, which is the whole point of naming
	-- the keys - and a hand-edited key is a key somebody can mistype. A path
	-- is read as `L.a.b.c`, so every part of it has to be a Lua identifier: a
	-- doubled dot, a leading digit, a space, and the phrase is unreachable
	-- from the source no matter how right the English beside it looks.
	do
		local bad = {}
		for key in pairs(A.Phrases("enUS")) do
			-- PART BY PART, because a Lua pattern cannot repeat a group: the
			-- one-liner for this reads as if it works and matches nothing.
			local ok, parts = true, 0
			for part in key:gmatch("[^%.]+") do
				parts = parts + 1
				if not part:match("^[%a_][%w_]*$") then ok = false end
			end
			-- A doubled or trailing dot leaves a gap gmatch walks straight
			-- past, so the pieces are counted against the dots.
			local _, dots = key:gsub("%.", "")
			if parts ~= dots + 1 then ok = false end
			if not ok then bad[#bad + 1] = key end
		end
		table.sort(bad)
		check(#bad == 0,
			"and every key in it is a path the source can reach (" ..
			(#bad > 0 and table.concat(bad, ", ", 1, math.min(#bad, 4))
			or "all of them") .. ")")
	end

	-- AND NOTHING IN IT IS EMPTY. A phrase edited down to nothing draws
	-- nothing, which is a label somebody has to notice is absent - the same
	-- failure the fallback exists to prevent, arrived at from the other side.
	do
		local empty = {}
		for key, text in pairs(A.Phrases("enUS")) do
			if type(text) ~= "string" or text == "" then
				empty[#empty + 1] = key
			end
		end
		table.sort(empty)
		check(#empty == 0,
			"and none of them is empty (" .. (#empty > 0 and
			table.concat(empty, ", ", 1, math.min(#empty, 4)) or "none") .. ")")
	end

	-- AND NOTHING IN THE LIST IS DEAD WEIGHT. A phrase nobody asks for is a
	-- phrase somebody is being asked to translate for nothing.
	do
		local orphans = {}
		for key in pairs(A.Phrases("enUS")) do
			if not seen[key] then orphans[#orphans + 1] = key end
		end
		table.sort(orphans)
		check(#orphans == 0,
			"and nothing in it is asked for by nobody (" .. (#orphans > 0 and
			table.concat(orphans, ", ", 1, math.min(#orphans, 4))
			or "no orphans") .. ")")
	end

	-- TWO LAYERS, AND THE ORDER OF THEM.
	--
	-- The player's language sits on English, so a phrase nobody has
	-- translated yet draws correctly rather than blank - a language that is
	-- half done is half done rather than half missing. This is the whole
	-- reason enUS ships in every zip and is not merely the import file.
	do
		local EN, LOC = A.Phrases("enUS"), A.Phrases("deDE")
		EN["checks.two_layers.both"] = "in both"
		EN["checks.two_layers.english_only"] = "English only"
		LOC["checks.two_layers.both"] = "in beiden"

		check(A.L.checks.two_layers.both == "in beiden",
			"a translated phrase wins over the English (" ..
			tostring(A.L.checks.two_layers.both) .. ")")
		check(A.L.checks.two_layers.english_only == "English only",
			"and one nobody has translated falls through to the English (" ..
			tostring(A.L.checks.two_layers.english_only) .. ")")

		-- AND A KEY IN NEITHER DRAWS ITS OWN PATH, loudly. That is a coding
		-- mistake rather than a translation gap: nil reaches SetText and draws
		-- nothing at all, which is a label somebody has to notice is absent.
		check(tostring(A.L.checks.two_layers.nobody_wrote_this) ==
			"checks.two_layers.nobody_wrote_this",
			"and a key in neither draws its own path rather than nothing (" ..
			tostring(A.L.checks.two_layers.nobody_wrote_this) .. ")")
		check(("" .. A.L.checks.two_layers.nobody_wrote_this):find("nobody_wrote"),
			"which survives being concatenated, since that is how half of them "
			.. "reach a frame")

		EN["checks.two_layers.both"] = nil
		EN["checks.two_layers.english_only"] = nil
		LOC["checks.two_layers.both"] = nil
	end

	-- AND A TRANSLATION WITH THE WRONG PLACEHOLDERS DOES NOT TAKE THE ADDON
	-- DOWN WITH IT. These are submitted by volunteers on a website, not
	-- reviewed here, so `%d` where the English had `%s` has to land on the
	-- one phrase and nowhere else.
	check(A.F("Step %d of %d", 3, 9) == "Step 3 of 9", "A.F formats a phrase")
	do
		-- What a bad translation looks like: a %d asked to eat a table.
		local ok, out = pcall(A.F, "Schritt %d von %d %d", 3, 9)
		check(ok and out ~= nil,
			"and a translation with the wrong placeholders in it draws the "
			.. "format string rather than throwing (" .. tostring(out) .. ")")
	end
end


print("== glyphs: nothing drawn that the font has not got ==")
do
	-- ARROWS ARE TEXTURES HERE, NEVER CHARACTERS.
	--
	-- The interface font carries Latin-1 and the punctuation this addon
	-- already draws - the em dash and the middle dot both come out right - but
	-- it has no arrows. A design deck that writes "Toolbox -> Layout" with a
	-- real arrow character produces a hollow box in game, which is what the
	-- onboarding finish card shipped as.
	--
	-- Every arrow this addon draws is Media.texture.chevron for exactly that
	-- reason. This is the guard that stops the next one arriving as text: the
	-- fault is invisible in every check that reads a string back, because the
	-- string is perfectly correct - it is the FONT that cannot draw it.
	local ARROWS = {
		"\226\134\144", "\226\134\145", "\226\134\146", "\226\134\147",
		"\226\135\144", "\226\135\146", "\226\150\182", "\226\150\184",
	}

	local offenders = {}
	for _, path in ipairs(FILES) do
		local fh = io.open(path, "rb")
		if fh then
			local text = fh:read("*a") or ""
			fh:close()
			for _, arrow in ipairs(ARROWS) do
				local at = text:find(arrow, 1, true)
				if at then
					-- The line, so the report says where rather than merely that.
					local line = 1
					for _ in text:sub(1, at):gmatch("\n") do line = line + 1 end
					offenders[#offenders + 1] = path .. ":" .. line
				end
			end
		end
	end
	table.sort(offenders)

	check(#offenders == 0,
		"no file draws an arrow as a character - they are textures, because "
		.. "the font has none (" .. (#offenders > 0 and
		table.concat(offenders, ", ") or "clean") .. ")")
end

print("== ifec: the row says what is true when you open the drawer ==")
do
	-- THE ROW WAS PAINTED ONCE AND NEVER AGAIN.
	--
	-- The mini paints itself on a playback event and on its own ticker, and the
	-- ticker only runs while something is playing. With nothing ever played the
	-- row kept whatever it said the first time it was drawn - which is at login,
	-- and can be BEFORE the registry has drained the packs that loaded before
	-- us. It then read "No content installed" for the whole session, over a
	-- season that was installed and played the moment you pressed the button.
	local M, R, P = A.IFEC.Mini, A.IFEC.Registry, A.IFEC.Playback
	local TB = A:GetModule("toolbox")
	local was = { packs = R.packs, order = R.order,
		failed = R.failed, dirty = R.dirty }
	local wasOpen = TB:IsOpen()

	-- PAINTED EMPTY FIRST, which is the state the bug was frozen in.
	R.packs, R.order, R.failed, R.dirty = {}, {}, {}, true
	P.item = nil
	M:Paint()
	check((M.frame.meta:GetText() or ""):find("installed", 1, true) ~= nil,
		"with nothing registered the row says nothing is installed (" ..
		tostring(M.frame.meta:GetText()) .. ")")

	-- THEN THE PACK ARRIVES, the way a drain after the drawer was built does.
	-- Nothing plays, so nothing repaints it of its own accord.
	R:Register({
		packId = "LatePack", apiVersion = 1, seasonIndex = 1,
		items = { {
			id = "m", type = "music", title = "Big Drum Deep Water",
			artist = "The Mudfoot Kings", totalDuration = 210,
			segments = { { file = "a.ogg", duration = 210 } },
		} },
	})
	check((M.frame.meta:GetText() or ""):find("installed", 1, true) ~= nil,
		"and registering a pack does not repaint it by itself")

	-- OPENING THE DRAWER DOES. Here rather than on a login event, because
	-- here has no ordering to get wrong: it runs on every layout, so the row
	-- is right the moment anybody can see it.
	TB:SetOpen(true, true)
	check(M.frame.meta:GetText() == "Press play for the season's music",
		"opening the drawer repaints it against what is actually installed (" ..
		tostring(M.frame.meta:GetText()) .. ")")
	check(M.frame.title:GetText() == "Nothing playing",
		"and nothing playing is what it says, because that is what is true (" ..
		tostring(M.frame.title:GetText()) .. ")")

	TB:SetOpen(wasOpen, true)
	R.packs, R.order, R.failed, R.dirty =
		was.packs, was.order, was.failed, was.dirty
end


print("== ifec: which kind of nothing ==")
do
	-- THREE CAUSES, THREE ANSWERS.
	--
	-- IsDormant collapses them into one, which is right for LAYOUT - the
	-- region is absent either way - and wrong for a MESSAGE. "No content
	-- installed" printed while a pack sits in the addon list, ticked and using
	-- memory, sends somebody looking for a file they already have. Reported
	-- from the game against 0.31.0.
	local C, R = A.IFEC.Content, A.IFEC.Registry
	local was = { packs = R.packs, order = R.order,
		failed = R.failed, dirty = R.dirty }

	-- NOTHING AT ALL, which is the one the old message always said.
	R.packs, R.order, R.failed, R.dirty = {}, {}, {}, true
	check(C:DormantReason() == "No content installed",
		"with no packs at all it says nothing is installed (" ..
		C:DormantReason() .. ")")

	-- REFUSED, which is a fault rather than a state and is the only one of
	-- the three with somewhere to go and read more.
	R:Register({ packId = "Broken", apiVersion = 99, items = {} })
	check(C:DormantReason():find("refused", 1, true) ~= nil,
		"a refused pack is not the same thing as an absent one (" ..
		C:DormantReason() .. ")")

	-- INSTALLED, REGISTERED, AND OUT OF SEASON. The third cause, and the one
	-- nobody would ever guess from "no content installed".
	R.packs, R.order, R.failed, R.dirty = {}, {}, {}, true
	R:Register({
		packId = "Yule", apiVersion = 1, seasonIndex = 1,
		items = { {
			id = "carol", type = "music", title = "Winter Veil Reel",
			totalDuration = 90,
			segments = { { file = "w.ogg", duration = 90 } },
			-- A window that has certainly closed, so this does not start
			-- passing or failing with the calendar.
			activeFrom = "2001-12-01", activeUntil = "2001-12-31",
		} },
	})
	check(#R:Catalogue() == 1 and C:IsDormant(),
		"a pack out of season is installed and dormant at the same time")
	check(C:DormantReason():find("season", 1, true) ~= nil,
		"and says so, rather than saying it is missing (" ..
		C:DormantReason() .. ")")

	R.packs, R.order, R.failed, R.dirty =
		was.packs, was.order, was.failed, was.dirty
end


print("== onboarding: the tour IS the setup ==")
do
	local OB = A:GetModule("onboard")
	-- BY KEY, NOT BY NUMBER. Everything below used to address its stop by
	-- index, and inserting the zen stop at four moved five of them - which
	-- showed up as ten failures in three unrelated features. A stop's key is
	-- the thing that does not move when the running order changes.
	local function At(key)
		for i, stop in ipairs(OB.stops) do
			if stop.key == key then return i end
		end
		error("no stop keyed " .. tostring(key), 2)
	end
	check(OB ~= nil, "the tour loaded")
	A.db.char.onboard = {}

	-- EIGHT STOPS, THREE THAT SET AND FIVE THAT SHOW. A first run that asked
	-- eight questions would be a form and one that asked none would be a
	-- slideshow; the split is the design.
	check(#OB.stops == 9, "there are nine stops (" .. #OB.stops .. ")")
	local sets, shows = 0, 0
	for _, stop in ipairs(OB.stops) do
		if stop.kind == "set" then sets = sets + 1 else shows = shows + 1 end
		check(stop.name and stop.head and stop.body and stop.target,
			"\"" .. tostring(stop.key) .. "\" has a name, a headline, a body and "
			.. "something to point at")
	end
	-- FOUR THAT SET AND FIVE THAT SHOW. The deck drew eight and did not have
	-- zen in it; the split is the design, and zen belongs on the setting side
	-- because the one real decision about it is whether you want it at all.
	check(sets == 4 and shows == 5,
		"four of them set something and five show something (" .. sets .. ", "
		.. shows .. ")")

	-- THE WELCOME CARD COMES FIRST, not stop 1. Somebody who has just
	-- installed this has no idea what it is, and dropping them straight into
	-- "pick a palette" answers a question they have not been asked.
	OB:Start()
	check(OB.card and OB.card:IsShown(),
		"starting shows the welcome card")
	check(not (OB.callout and OB.callout:IsShown()),
		"and not a stop yet")
	check(OB.scrim and OB.scrim:IsShown(),
		"over a dimmed world")

	-- AND IT INTRODUCES ITSELF BY NAME. The kicker line said "AETHER UI" in
	-- small caps, which is the wordmark spelled out by a font that is not the
	-- wordmark. The mark goes here and the kicker goes away - both, or the card
	-- carries the same three syllables twice, once as art and once as type.
	check(OB.card.logo and OB.card.logo:IsShown()
		and OB.card.logo:GetTexture() == A.Media.texture.logo,
		"the welcome card wears the mark")
	check(not OB.card.kicker:IsShown(),
		"instead of the kicker line, not as well as it")

	-- AT THE ART'S OWN ASPECT, and the art is a band inside a bigger canvas -
	-- so the crop and the shape have to agree. Sized from the canvas instead,
	-- the box is a fifth taller than the ink and the headline sits adrift.
	local _, _, top, bottom = OB.card.logo:GetTexCoord()
	check(top and bottom and math.abs((bottom - top)
		- (A.Media.logoCoord[4] - A.Media.logoCoord[3])) < 0.001,
		"cropped to the ink rather than the whole canvas")
	check(math.abs(OB.card.logo:GetWidth() / OB.card.logo:GetHeight()
		- A.Media.logoAspect) < 0.02,
		"and drawn at the ink's aspect, not squashed to fit ("
		.. string.format("%.2f vs %.2f",
			OB.card.logo:GetWidth() / OB.card.logo:GetHeight(),
			A.Media.logoAspect) .. ")")

	-- THE HEADLINE HANGS OFF WHICHEVER TOP IS SHOWING. Anchored to the kicker
	-- at build time it would hang off a hidden font string on this card, which
	-- keeps the geometry it would have had - an empty line's worth of hole
	-- between the mark and the words.
	do
		local rel = select(2, OB.card.head:GetPoint(1))
		check(rel == OB.card.logo,
			"and the headline hangs off the mark, not off the hidden kicker")
	end

	-- SKIP IS ON THE CARD AND ON EVERY STOP. The deck pins it to the bottom
	-- of the screen throughout, because a tour you cannot leave is a modal
	-- dialog with better manners.
	OB.card.go:GetScript("OnClick")(OB.card.go)
	check(OB.index == 1 and OB.callout:IsShown(),
		"taking the tour opens stop 1 (" .. tostring(OB.index) .. ")")
	check(OB.skip and OB.skip:IsShown(),
		"with the way out pinned to the screen, not buried in the callout")
	check(not OB.card:IsShown(),
		"and the welcome card gone - never both at once")

	-- WRITTEN THE MOMENT IT IS REACHED. A player who alt-F4s on stop 5 comes
	-- back to stop 5, which is only true if the number is on disk before they
	-- do it rather than at the end.
	OB:Next()
	OB:Next()
	check(A.db.char.onboard.stopIndex == 3,
		"the stop reached is written down as it is reached (" ..
		tostring(A.db.char.onboard.stopIndex) .. ")")

	-- BACK ALWAYS WORKS, and never off the front. Back restores nothing -
	-- every value was written the moment it was touched - so it only re-shows
	-- the callout you were looking at.
	OB:Back()
	check(OB.index == 2, "back goes back (" .. tostring(OB.index) .. ")")
	OB:Back()
	OB:Back()
	check(OB.index == 1,
		"and stops at the first stop rather than walking off the front (" ..
		tostring(OB.index) .. ")")

	-- WHAT IS LIFTED IS PUT BACK.
	--
	-- The spotlight raises a real frame's strata so it stands out of the
	-- scrim. Half of what this tour points at is secure and cannot be
	-- reparented at all, which is why it is done by strata - and a frame whose
	-- strata was raised and never restored draws over the player's dialogs for
	-- the rest of the session.
	do
		local pf = _G.AetherUIPlayerFrame
		if pf then
			-- Sampled with the tour DOWN. Stop 1 points at this very frame, so
			-- reading its strata part way through the tour reads the lift.
			OB:Teardown()
			local was = pf:GetFrameStrata()
			OB:Go(1)
			check(pf:GetFrameStrata() == "FULLSCREEN",
				"the stop lifts its element out of the dim (" ..
				tostring(pf:GetFrameStrata()) .. ")")
			OB:Go(2)
			check(pf:GetFrameStrata() == was,
				"and the next stop puts it back where it found it (" ..
				tostring(pf:GetFrameStrata()) .. " against " .. tostring(was) .. ")")
			OB:Go(1)
			OB:Teardown()
			check(pf:GetFrameStrata() == was,
				"and so does leaving - a frame left raised draws over every dialog "
				.. "the player opens for the rest of the session")
		end
	end

	-- THE CALLOUT STAYS ON THE SCREEN.
	--
	-- Anchoring its LEFT to the element's RIGHT centres it vertically on the
	-- element - so an element near the top of the screen puts most of the
	-- callout above the top of the screen. The first build showed nothing but
	-- its footer, on a player frame docked to the top right.
	do
		local probe = CreateFrame("Frame", nil, UIParent)
		probe:SetSize(200, 60)

		-- PLACED WITH SetGeom, which is the mock's door for "this frame is
		-- actually here": GetCenter answers a fixed 500, 300 otherwise, and a
		-- check that moved the probe with SetPoint passed on all five corners
		-- while measuring the same one five times.
		local wasW, wasH = UIParent:GetWidth(), UIParent:GetHeight()
		UIParent:SetSize(1920, 1080)
		local sw, sh = 1920, 1080

		local corners = {
			{ "top left", 120, 1040 }, { "top right", 1800, 1040 },
			{ "bottom left", 120, 40 }, { "bottom right", 1800, 40 },
			{ "middle", 960, 540 },
		}

		-- Its own stop, so this does not depend on where a real HUD element
		-- happens to be sitting when the suite runs.
		local was = OB.stops[1].target
		OB.stops[1].target = function() return probe end

		-- READ OFF THE SUM, not off the frame. Asking the callout where it
		-- ended up means resolving an anchor chain, and the harness answers that
		-- with a fixed 500, 300 for every frame that has not been placed with
		-- SetGeom - which is why the first version of this check passed on all
		-- five corners while measuring the same one five times. PlaceCallout
		-- records what it computed; that is the thing that was wrong.
		for _, spot in ipairs(corners) do
			probe:SetGeom({ cx = spot[2], cy = spot[3] })
			OB:Go(1)

			local at = OB.callout.__aetherAt
			local inside = at and at.x - at.w / 2 >= -1
				and at.x + at.w / 2 <= at.sw + 1
				and at.y - at.h / 2 >= -1 and at.y + at.h / 2 <= at.sh + 1
			check(inside,
				"an element at the " .. spot[1] .. " keeps the whole callout on "
				.. "screen (" .. (at and string.format(
				"%.0f..%.0f x %.0f..%.0f in %.0fx%.0f", at.x - at.w / 2,
				at.x + at.w / 2, at.y - at.h / 2, at.y + at.h / 2, at.sw, at.sh)
				or "nowhere") .. ")")
		end

		-- AND IT IS BESIDE THE ELEMENT, not merely somewhere legal. A callout
		-- clamped to the middle of the screen is on screen and useless.
		probe:SetGeom({ cx = 400, cy = 540 })
		OB:Go(1)
		check(OB.callout.__aetherAt.onRight
			and OB.callout.__aetherAt.x > 400,
			"and an element left of centre puts it on the element's right (" ..
			string.format("%.0f", OB.callout.__aetherAt.x) .. ")")

		probe:SetGeom({ cx = 1500, cy = 540 })
		OB:Go(1)
		check(not OB.callout.__aetherAt.onRight
			and OB.callout.__aetherAt.x < 1500,
			"and one right of centre puts it on the left (" ..
			string.format("%.0f", OB.callout.__aetherAt.x) .. ")")

		-- AND THE ARROW FOLLOWS THE ELEMENT rather than the callout's middle.
		-- Once the callout has been pushed back onto the screen the two are no
		-- longer level, and an arrow left in the centre points at nothing.
		--
		-- A SMALL PUSH, so the offset is one the arrow can actually travel.
		probe:SetGeom({ cx = 300, cy = 950 })
		OB:Go(1)
		do
			local at = OB.callout.__aetherAt
			check(at.y < 950,
				"an element near the top pushes the callout down to fit (" ..
				string.format("%.0f from %.0f", at.y, 950) .. ")")
			check(OB.callout.arrow:IsShown() and at.dy
				and math.abs((at.y + at.dy) - 950) < 6,
				"and the arrow is offset back up to stay level with it (" ..
				string.format("%.0f + %.0f", at.y, at.dy or 0) .. ")")

			-- AND WRITTEN IN THE ARROW'S OWN UNITS. `dy` is a pixel figure like
			-- everything else in the sum, and the arrow is a child of a callout
			-- drawn at the profile's scale - so it goes through the same
			-- division the callout's own anchor does. Nothing above can see
			-- that: `at.dy` is the pixel figure, and it is right either way.
			do
				local _, _, _, _, ay = OB.callout.arrow:GetPoint(1)
				check(math.abs((ay or 0) * at.scale - at.dy) < 1,
					"and the arrow's offset is in its own units too (" ..
					string.format("%.1f x %.2f vs %.1f", ay or 0, at.scale, at.dy)
					.. ")")
			end
		end

		-- AND PAST THE ARROW'S OWN REACH, THERE IS NO ARROW.
		--
		-- It can only travel as far as its own edge, so an element further above
		-- the callout than half the callout's height leaves it parked in the top
		-- corner pointing at nothing in particular. That is the same failure the
		-- sideways guard exists to prevent, arrived at down the other axis - and
		-- it only started happening when the skip line moved to the top and the
		-- callout got a ceiling to stay under.
		probe:SetGeom({ cx = 300, cy = 1040 })
		OB:Go(1)
		do
			local at = OB.callout.__aetherAt
			check(1040 - at.y > at.h / 2,
				"an element at the very top ends up further away than the arrow can "
				.. "reach (" .. string.format("%.0f past %.0f", 1040 - at.y, at.h / 2)
				.. ")")
			check(not OB.callout.arrow:IsShown(),
				"and then there is no arrow at all, rather than one on the edge "
				.. "pointing at empty screen")
		end

		-- AND ALL OF IT AT THE PROFILE'S SCALE, like everything else this addon
	-- draws.
	--
	-- The scrim is PARENTLESS - it has to be, to dim a world that UIParent is
	-- part of - so it has nothing to inherit a scale from and the whole tour
	-- sat at 1.0 while the HUD it was pointing at sat at 0.71. A callout half
	-- again the size of the unit frame it describes, and this file's own header
	-- claimed otherwise from the day it was written.
	--
	-- MOVED BEFORE IT IS ASKED, which is the only way this can be checked at
	-- all: a default profile sits at one and so does an unscaled frame, so an
	-- assertion made at the default passes either way.
	do
		local wasScale = A.db.profile.scale
		for _, scale in ipairs({ 0.71, 1.0, 1.25 }) do
			A.db.profile.scale = scale
			OB:OnConfigChanged()
			OB:Go(1)

			check(math.abs((OB.scrim:GetScale() or 0) - scale) < 0.001,
				"the tour draws at the profile's scale (" .. scale .. " -> " ..
				tostring(OB.scrim:GetScale()) .. ")")
			check(math.abs((OB.callout:GetEffectiveScale() or 0) - scale) < 0.001,
				"and the callout with it, being a child of the scrim")

			-- AND THE BUILDER DOES IT TOO, not only the config hook. Both apply
			-- it, and a check that always asks after a config change cannot tell
			-- which of the two is carrying it - removing the builder's call left
			-- every assertion above passing.
			OB:Teardown()
			OB.scrim, OB.callout, OB.ring, OB.skip, OB.card = nil, nil, nil, nil, nil
			OB:Go(1)
			check(math.abs((OB.scrim:GetScale() or 0) - scale) < 0.001,
				"and a scrim built from scratch arrives at that scale (" ..
				tostring(OB.scrim:GetScale()) .. ")")

			-- AND THE PLACEMENT ARITHMETIC SURVIVES IT. The clamps are worked out
			-- in screen pixels and written back in the callout's own units; get
			-- the division wrong and the panel lands 1/scale from where it was
			-- measured to go, which at 1.25 is off the screen entirely.
			probe:SetGeom({ cx = 300, cy = 1040 })
			OB:Go(1)
			local at = OB.callout.__aetherAt

			-- THE RECORDED SIZE IS IN PIXELS, which is the conversion everything
			-- else here is built on. Left in the callout's own units the whole
			-- sum stays SELF-CONSISTENT and lands the panel in the wrong place,
			-- so nothing downstream can see it - this is the one assertion that
			-- compares the record against the frame.
			check(math.abs(at.w - (OB.callout:GetWidth() or 0) * scale) < 1
				and math.abs(at.h - (OB.callout:GetHeight() or 0) * scale) < 1,
				"and its size was measured in pixels, not in its own units (" ..
				string.format("%.0fx%.0f vs %.0fx%.0f", at.w, at.h,
				(OB.callout:GetWidth() or 0) * scale,
				(OB.callout:GetHeight() or 0) * scale) .. ")")

			check(at.x - at.w / 2 >= -1 and at.x + at.w / 2 <= at.sw + 1
				and at.y - at.h / 2 >= -1 and at.y + at.h / 2 <= at.sh + 1,
				"and the whole callout is still on the screen at " .. scale .. " (" ..
				string.format("%.0f..%.0f x %.0f..%.0f in %.0fx%.0f",
				at.x - at.w / 2, at.x + at.w / 2, at.y - at.h / 2,
				at.y + at.h / 2, at.sw, at.sh) .. ")")

			-- THE OFFSET THAT WAS ACTUALLY WRITTEN, against the pixel figure it
			-- came from. This is the division itself, and nothing else here can
			-- see it: the record is in pixels and the anchor is not.
			local _, _, _, ox, oy = OB.callout:GetPoint(1)
			check(math.abs((ox or 0) * at.scale - at.x) < 1
				and math.abs((oy or 0) * at.scale - at.y) < 1,
				"and its anchor is written in its OWN units, not in pixels (" ..
				string.format("%.0f,%.0f x %.2f vs %.0f,%.0f",
				ox or 0, oy or 0, at.scale, at.x, at.y) .. ")")

			-- AND THE SKIP LINE'S BAND SCALES WITH EVERYTHING ELSE. It is a
			-- child of the same scrim, so its own numbers are in the same units
			-- the callout's are - and left unscaled the ceiling is too generous
			-- below 1.0 and too mean above it, which is the direction that puts
			-- the footer back through the line. Checked HERE rather than beside
			-- the other overlap assertions, because those run at one scale.
			do
				local skip = OB.skip
				local _, _, _, _, sTop = skip:GetPoint(1)
				local floor = at.sh + ((sTop or 0) - skip:GetHeight()) * at.scale
				check(at.y + at.h / 2 <= floor,
					"and the callout is clear of the skip line at " .. scale ..
					" (top " .. string.format("%.0f under %.0f",
					at.y + at.h / 2, floor) .. ")")
			end
		end
		A.db.profile.scale = wasScale
		OB:OnConfigChanged()
	end

	-- AND THE SKIP LINE IS NEVER UNDER THE CALLOUT.
		--
		-- Reported from the game: Back, the progress dots and the skip line all
		-- in the same twenty pixels. The line is pinned and the
		-- callout moves, so the two were always going to meet somewhere - they
		-- are kept apart by the ceiling in PlaceCallout rather than by luck.
		do
			local skip = OB.skip
			local point, _, relPoint, _, sTop = skip:GetPoint(1)
			-- ACROSS THE TOP, which is where Joe asked for it and is also the
			-- emptier half of a dimmed screen: everything the tour points at
			-- lives below the middle. Asserted rather than merely measured
			-- against, because the overlap checks below read the line's own
			-- anchor - move it back to the bottom and the yardstick moves with
			-- it, and every one of them passes.
			check(point == "TOP" and relPoint == "TOP" and (sTop or 0) < 0,
				"the skip line hangs from the top of the screen (" ..
				tostring(point) .. " " .. tostring(sTop) .. ")")
			for _, spot in ipairs({ { 300, 1040 }, { 1500, 1040 }, { 960, 1070 },
				{ 300, 20 }, { 960, 540 } }) do
				probe:SetGeom({ cx = spot[1], cy = spot[2] })
				OB:Go(1)
				local at = OB.callout.__aetherAt
				-- The line hangs from the top by a negative offset; its underside is
				-- that far down from the top of the screen.
				--
				-- IN PIXELS, because `at` is. The line's own numbers are in its own
				-- units and the tour is drawn at the profile's scale, so comparing
				-- the two directly made the floor 1/scale too low and every one of
				-- these passed without meaning anything.
				local floor = at.sh + (sTop - skip:GetHeight()) * at.scale
				check(at.y + at.h / 2 <= floor,
					"a stop at " .. spot[1] .. "," .. spot[2] ..
					" keeps the callout clear of the skip line (top " ..
					string.format("%.0f under %.0f", at.y + at.h / 2, floor) .. ")")
			end
		end


		UIParent:SetSize(wasW, wasH)
		OB.stops[1].target = was
	end

	-- AND A CONTROL THAT IS NOT A BUTTON IS NOT ASKED TO FORGET A CLICK.
	--
	-- The client throws on SetScript for a script the widget type has not got,
	-- for CLEARING one as much as for setting one - and stop 3's box is a plain
	-- Frame with four tabs on it. The tidy-up between stops nilled OnClick on
	-- everything it was holding, and every check in this file passed.
	do
		OB:Go(3)
		local ok, err = pcall(function() OB:Go(1) end)
		check(ok,
			"leaving stop 3 does not throw on the way out (" ..
			tostring(err) .. ")")
	end

	-- THE THREE CONTROLS WRITE STRAIGHT INTO THE SYSTEM THAT OWNS THEM.
	--
	-- No staging and no Apply at the end: the palette into the profile, the
	-- layout into the anchors, the edge into the character's Toolbox record.
	-- Which is the whole reason quitting half way through costs nothing - and
	-- a tour that held its answers until the last card would lose every one of
	-- them to a disconnect.
	do
		local slot = OB.callout.slot

		-- Stop 1: four swatches, and tapping one recolours the whole interface.
		A.db.profile.skin = "midnight"
		A:Restyle()
		OB:Go(1)
		local swatches = slot.__aetherKids and slot.__aetherKids.palette or {}
		check(#swatches == 4,
			"stop 1 offers the four palettes (" .. #swatches .. ")")

		-- THE SWATCH IS THAT PALETTE'S OWN ACCENT, not the one in use. Four
		-- cards drawn in the current skin's accent would make the choice
		-- invisible, which is the one thing this stop cannot do.
		local seen = {}
		for _, card in ipairs(swatches) do
			local r, g, b = card.dot:GetVertexColor()
			seen[string.format("%.2f %.2f %.2f", r or 0, g or 0, b or 0)] = true
		end
		local shades = 0
		for _ in pairs(seen) do shades = shades + 1 end
		check(shades == 4,
			"each drawn in its OWN accent rather than the one in use (" ..
			shades .. " colours)")

		-- AND TAPPING ONE GOES THROUGH THE SAME DOOR the options panel uses. A
		-- palette applied any other way is one half the interface has not heard
		-- about, and this stop must not preview something the player will not get.
		swatches[2]:GetScript("OnClick")(swatches[2])
		check(A.Palette.current == A.Palette.order[2],
			"tapping a swatch recolours the whole interface on the spot (" ..
			tostring(A.Palette.current) .. ")")
		check(A.db.profile.skin == A.Palette.order[2],
			"and writes it into the profile, not into the tour")

		-- THE TOUR REPAINTS WITH EVERYTHING ELSE. The callout, the ring and the
		-- dots are drawn in the accent that just changed; a tour left Midnight
		-- while the HUD went Dawn would be the one thing on screen contradicting
		-- its own copy.
		do
			local r, g, b = OB.callout.kicker:GetTextColor()
			local a = A.Palette.c.accent
			check(math.abs((r or 0) - a[1]) < 0.02
				and math.abs((g or 0) - a[2]) < 0.02,
				"and the callout is repainted with it (" ..
				string.format("%.2f %.2f %.2f", r or 0, g or 0, b or 0) .. ")")
		end
		A.db.profile.skin = "midnight"
		A:Restyle()

		-- Stop 2: three arrangements, and tapping one moves the real frames.
		OB:Go(2)
		local cards = slot.__aetherKids and slot.__aetherKids.layout or {}
		check(#cards == #A.Presets.order,
			"stop 2 offers every shipped arrangement (" .. #cards .. ")")

		-- A WIREFRAME DRAWN FROM THE ARRANGEMENT ITSELF, not three hand-drawn
		-- thumbnails. The anchors are already fractions of the screen - that is
		-- what makes them portable - so a thumbnail cannot drift away from what
		-- the card actually does.
		--
		-- AND FOUR MARKS AT MOST, NOT ELEVEN. The first version drew every
		-- anchor a preset names - six bars, the party frame, the pet, the
		-- tooltip - which in a box the size of a postage stamp is a texture
		-- rather than a layout. Reported as "this image is a mess".
		for i, key in ipairs(A.Presets.order) do
			local preset = A.Presets.list[key]
			local shown = 0
			for _, m in ipairs(cards[i].box.marks or {}) do
				if m:IsShown() then shown = shown + 1 end
			end

			-- The player, the target, and the bars this preset SWITCHES ON. A
			-- preset that leaves bar 5 off has no business drawing it, and the
			-- anchors table carries a position for it either way.
			local want = 0
			if preset.anchors.player then want = want + 1 end
			if preset.anchors.target then want = want + 1 end
			for id, on in pairs(preset.bars or {}) do
				if on and preset.anchors["bar" .. id] then want = want + 1 end
			end

			check(shown == want and shown > 1 and shown <= 4,
				"\"" .. key .. "\" draws its unit frames and the bars it switches "
				.. "on, and nothing else (" .. shown .. " of a wanted " .. want ..
				")")
		end

		cards[2]:GetScript("OnClick")(cards[2])
		check(A.Presets:Current() == A.Presets.order[2],
			"and tapping one moves the real frames on the spot (" ..
			tostring(A.Presets:Current()) .. ")")

		-- Stop 3: four edges, and tapping one docks the drawer.
		OB:Go(3)
		local edges = slot.__aetherKids and slot.__aetherKids.toolbox or {}
		check(#edges == 5,
			"stop 3 offers a box with four edges on it (" .. #edges .. ")")
		edges[4]:GetScript("OnClick")(edges[4])
		check(A.db.char.toolbox.docked == "RIGHT",
			"and tapping one docks the drawer there (" ..
			tostring(A.db.char.toolbox.docked) .. ")")
		local TB = A:GetModule("toolbox")
		if TB.SetDock then TB:SetDock("LEFT") end

		-- AND EACH CONTROL HAS ITS OWN FRAMES.
		--
		-- The three share one slot, and their frames are not interchangeable: with
		-- one pool by index the fourth palette swatch and the first layout card
		-- are the same frame, and the layout card looks for a wireframe box a
		-- swatch has not got. Which is how this failed the first time it was run.
		check(slot.__aetherKids.palette[1] ~= slot.__aetherKids.layout[1],
			"a swatch and a layout card are never the same frame")

		-- AND NOTHING FROM THE LAST STOP IS STILL LIVE. A control left over is a
		-- control that still works - and stop 3's box would still be recolouring
		-- the interface.
		local live = 0
		for _, card in ipairs(slot.__aetherKids.palette) do
			if card:IsShown() then live = live + 1 end
		end
		check(live == 0,
			"and stop 1's swatches are down while stop 3 is up (" .. live .. ")")
	end

	-- STOP 4 SETS HOW LONG BEFORE THE HUD GOES QUIET.
	--
	-- The fourth thing you decide, and the only real decision about zen is
	-- whether you want it at all - which is why "never" is on the same row as
	-- the three timings rather than hidden in the options tree.
	do
		OB:Go(At("zen"))
		local cards = OB.callout.slot.__aetherKids.zen or {}
		check(#cards == 4,
			"the zen stop offers three timings and never (" .. #cards .. ")")

		-- STRAIGHT INTO THE PROFILE, and the fader with it: zen is stage two of
		-- one feature, so a delay chosen with the idle fade switched off is a
		-- delay for something that can never happen.
		A.db.profile.fader.enabled = false
		cards[3]:GetScript("OnClick")(cards[3])
		check(A.db.profile.modules.zen.delay == 300,
			"tapping 5 min writes the delay (" ..
			tostring(A.db.profile.modules.zen.delay) .. ")")
		check(A.db.profile.fader.enabled == true,
			"and switches the idle fade back on, or nothing would ever fade OUT")
		check((A:GetModule("zen") or {}).enabled == true,
			"and the module is on")

		-- NEVER IS THE MODULE BEING OFF rather than a fourth delay. A timer that
		-- never elapses is a ticker running for ever to do nothing.
		cards[4]:GetScript("OnClick")(cards[4])
		check((A:GetModule("zen") or {}).enabled == false,
			"never switches the whole thing off")

		-- AND THE CHOSEN CARD IS READ BACK OUT OF THE SYSTEM rather than out of
		-- anything the tour remembered. If the card and the HUD ever disagree,
		-- the card is the one that is wrong.
		OB:Go(At("zen"))
		local litLabel
		for _, card in ipairs(OB.callout.slot.__aetherKids.zen) do
			local r = select(1, card.label:GetTextColor())
			local lit = math.abs(r - A.Palette.c.text[1]) < 0.01
			if lit then litLabel = card.label:GetText() end
		end
		check(litLabel == "never",
			"with the module off, never is the one lit (" ..
			tostring(litLabel) .. ")")

		-- Back the way it was found, or six later checks are looking at a HUD
		-- with no idle fade in it.
		A:SetModuleEnabled("zen", true)
		A.db.profile.modules.zen.delay = 60
	end

	-- AND WHAT EACH STOP POINTS AT, IT CAN ACTUALLY FIND.
	--
	-- The stop table check above asks whether `target` EXISTS, which is a
	-- different and much easier question than whether it returns a frame - and
	-- THREE of the eight were returning nil. Stop 4 called an AB:Bar(id) that
	-- has never existed, stop 5 asked the tracker for a QT.frame it calls
	-- QT.panel, and stop 8 looked for the console's mini on the module rather
	-- than on A.IFEC. All three shipped, and all three lit nothing at all.
	--
	-- TWO STOPS ARE ALLOWED NIL, and they are named here rather than shrugged
	-- at. Both have the same reason: their subject is the whole HUD, so the
	-- scrim stays down and a ring round any single frame would be pointing at
	-- the wrong thing. Layout moves everything; zen makes everything go away.
	--
	-- A NEW NAME ON THIS LIST IS A DECISION, which is the point of listing them:
	-- a stop that quietly resolves to nil is a stop that lights nothing, and
	-- three of them shipped that way.
	local MAY_POINT_AT_NOTHING = { layout = true, zen = true }
	for i, stop in ipairs(OB.stops) do
		OB:Go(i)
		local at = stop.target()
		if MAY_POINT_AT_NOTHING[stop.key] then
			check(at == nil,
				"\"" .. stop.key .. "\" deliberately points at nothing - its "
				.. "subject is the whole HUD")
		else
			check(at ~= nil and at.GetObjectType ~= nil,
				"\"" .. stop.key .. "\" finds the thing it points at (" ..
				tostring(at) .. ")")
		end
	end

	-- THE FIVE THAT SHOW.
	--
	-- A SHOW stop asks for nothing and carries one behaviour instead. The two
	-- rules that make that a demonstration rather than decoration are that it
	-- actually draws, and that it plays ONCE - and the third, which is the one
	-- that costs the player something when it is wrong, is that whatever it
	-- changed out in the world goes back.
	local function drive(slot, ticks)
		-- Ten seconds in tenths by default, which is longer than the longest of
		-- the five. Stops the moment the demo takes its own script off, so a
		-- demo that never finishes is a loop that runs out rather than one that
		-- passes.
		for _ = 1, (ticks or 100) do
			local step = slot:GetScript("OnUpdate")
			if not step then return end
			step(slot, 0.1)
		end
	end

	for i, stop in ipairs(OB.stops) do
		if stop.kind == "show" then
			OB:Go(i)
			local slot = OB.callout.slot
			local live = 0
			for _, pool in pairs(slot.__aetherKids or {}) do
				for _, f in ipairs(pool) do
					if f:IsShown() then live = live + 1 end
				end
			end
			check(live > 0 and (slot:GetHeight() or 0) > 1,
				"\"" .. stop.key .. "\" draws a demo rather than an empty slot (" ..
				live .. " parts, " .. math.floor(slot:GetHeight() or 0) .. " tall)")

			drive(slot)
			check(slot:GetScript("OnUpdate") == nil,
				"\"" .. stop.key .. "\" plays once and stops")
		end
	end

	-- THE PLAYER'S OWN SPELLS, on the bars stop. The sentence beside it reads
	-- "your spells, undecorated", and a row of invented squares would be
	-- decorating them.
	do
		OB:Go(At("bars"))
		local tiles = OB.callout.slot.__aetherKids["bars.tile"] or {}
		check(#tiles == 4, "the bars stop draws four slots (" .. #tiles .. ")")
		local mine = GetActionTexture and GetActionTexture(1)
		check(mine ~= nil and tiles[1] and tiles[1].icon:GetTexture() == mine,
			"carrying the icon that is actually in the player's first slot (" ..
			tostring(mine) .. ")")

		-- AND A REAL Cooldown FRAME ON THE SECOND ONE, swiping a real duration.
		-- The whole claim being made is that the cooldown draws ON the icon, so a
		-- rectangle drawn to look like one would be arguing the opposite.
		local cd = tiles[2] and tiles[2].cd
		check(cd ~= nil and cd:IsShown() and cd.__cd ~= nil and cd.__cd[2] > 0,
			"the second is on cooldown, through a Cooldown frame (" ..
			tostring(cd and cd.__cd and cd.__cd[2]) .. "s)")
		check((tiles[2].cdText:GetText() or "") ~= "",
			"with the countdown drawn on the icon (" ..
			tostring(tiles[2].cdText:GetText()) .. ")")
	end

	-- AND THE CONSOLE STOP SHOWS THE CONTENT THAT IS ACTUALLY INSTALLED.
	--
	-- The first version of this demo drew a made-up flight from Booty Bay to
	-- Ironforge with three invented legs on it. It was a picture of the feature
	-- rather than the feature, which is what Joe said the moment he saw it - and
	-- the check beside it counted ONE part and passed, because the pill was
	-- drawn. What is on the pill is the whole question here.
	--
	-- ITS OWN PACK, registered here and taken away again. The demo reads the
	-- real library, so a check that hoped the suite had left something in the
	-- registry is a check that passes or fails on the order of the file.
	do
		local R = A.IFEC.Registry
		local was = { packs = R.packs, order = R.order,
			failed = R.failed, dirty = R.dirty }
		R.packs, R.order, R.failed, R.dirty = {}, {}, {}, true

		-- ONE OF EACH CHANNEL, because the three colours on the bar are the
		-- claim: a programme is music AND stories AND the rag, not a playlist.
		check(R:Register({
			packId = "TourPack", apiVersion = 1, seasonIndex = 1,
			items = {
				{ id = "m", type = "music", title = "Big Drum Deep Water",
					artist = "The Mudfoot Kings", totalDuration = 210,
					segments = { { file = "a.ogg", duration = 210 } } },
				{ id = "p", type = "podcast", title = "The Gadgeteer",
					totalDuration = 600,
					segments = { { file = "b.ogg", duration = 600 } } },
				{ id = "g", type = "gossip", masthead = "ogler",
					title = "The Orgrimmar Ogler", pages = { "p1" } },
			},
		}) == true, "the tour's own content pack registers")

		OB:Go(At("ifec"))
		local pill = (OB.callout.slot.__aetherKids["ifec.pill"] or {})[1]
		check(pill ~= nil and (pill.bar:GetWidth() or 0) > 40,
			"the programme bar has a width to fill (" ..
			tostring(pill and math.floor(pill.bar:GetWidth() or 0)) .. ")")

		-- THE FIRST THING A FLIGHT WOULD REALLY GET, named on the pill. Not the
		-- first thing the registry happens to hold - the programme builder's own
		-- first pick, which is the one the console would play.
		local want = A.IFEC.Content:Everything()[1]
		check(want ~= nil and pill.title:GetText() == want.title,
			"and names the first thing the console would really play (" ..
			tostring(pill.title:GetText()) .. ")")

		-- AND COUNTS WHAT IS ABOARD in the library's own three words, because a
		-- filter tab reading Stories beside a count reading podcasts is the same
		-- thing under two names.
		local said = pill.sub:GetText() or ""
		for _, word in ipairs({ "Stories", "Music", "Gossip" }) do
			check(said:find(word, 1, true) ~= nil,
				"and counts the " .. word .. " that are aboard (" .. said .. ")")
		end

		-- THE BAR IS THE PROGRAMME, and the programme is what will PLAY. The
		-- first version of this check asked for all three channels on it and was
		-- wrong about the feature rather than about the code: a programme is built
		-- to COVER a flight, so it is assembled out of things that take time, and
		-- the rag takes none - it is read, not played. It is counted on the line
		-- above and it is not on the bar, which is the distinction the console
		-- itself makes.
		drive(OB.callout.slot)
		local playable = 0
		for _, item in ipairs(A.IFEC.Content:Everything()) do
			if A.IFEC.Content:Length(item) > 0 then playable = playable + 1 end
		end
		local lit = 0
		for _, part in ipairs(pill.bar.parts or {}) do
			if part:IsShown() then lit = lit + 1 end
		end
		check(playable >= 2 and lit == playable,
			"and fills with one leg per playable item by the end (" .. lit ..
			" of " .. playable .. ")")

		-- AND THE RAG IS COUNTED WITHOUT BEING PLAYED, which is the whole of the
		-- distinction above and the part a reader would otherwise get wrong.
		local aboard, played = 0, 0
		for _, item in ipairs(A.IFEC.Content:Available()) do
			if item.type == "gossip" then aboard = aboard + 1 end
		end
		for _, item in ipairs(A.IFEC.Content:Everything()) do
			if item.type == "gossip" then played = played + 1 end
		end
		check(aboard > 0 and played == 0
			and (pill.sub:GetText() or ""):find("Gossip", 1, true) ~= nil,
			"the rag is aboard and counted, and not on the programme (" ..
			aboard .. " aboard, " .. played .. " playing)")

		-- AND WITH NOTHING INSTALLED IT SAYS SO, rather than drawing an empty
		-- groove and a blank line. A clone of this repository is exactly this
		-- case: the cut music is derived and untracked, so it has the magazines
		-- and silence.
		R.packs, R.order, R.dirty = {}, {}, true
		OB:Go(At("threat"))
		OB:Go(At("ifec"))
		check((pill.title:GetText() or ""):find("Nothing", 1, true) ~= nil,
			"nothing installed is a state the pill has words for (" ..
			tostring(pill.title:GetText()) .. ")")
		check(pill.sub:GetText() == A.IFEC.Content:DormantReason(),
			"and says WHICH kind of nothing - refused, absent or out of season (" ..
			tostring(pill.sub:GetText()) .. ")")

		R.packs, R.order, R.failed, R.dirty =
			was.packs, was.order, was.failed, was.dirty
	end

	-- AND WHAT A DEMO CHANGES OUT IN THE WORLD, IT PUTS BACK.
	--
	-- Three of the five touch something real - the tracker folds, the bag panel
	-- opens, the player's frame wears a warning - and each of those is a change
	-- the player did not ask for. A tour that folded somebody's tracker and then
	-- took a disconnect is a tour that cost them their tracker.
	do
		local QT = A:GetModule("questtracker")
		local BG = A:GetModule("bags")

		QT:SetCollapsed(false)
		OB:Go(At("quests"))
		-- To the end, because the fold is the second half of the demo.
		drive(OB.callout.slot)
		check(QT.collapsed == true,
			"the quest tracker stop folds the REAL tracker")
		OB:Go(At("bags"))
		check(QT.collapsed == false,
			"and unfolds it on the way out")

		-- TO WHAT IT WAS, not to open. Somebody who keeps their tracker folded
		-- should get it back folded.
		QT:SetCollapsed(true)
		OB:Go(At("quests"))
		drive(OB.callout.slot)
		OB:Go(At("bags"))
		check(QT.collapsed == true,
			"restored to what it was, rather than to open")

		-- THE BAG PANEL OPENS FOR REAL, and the spotlight lifts the panel itself
		-- - which is the reason it is opened BEFORE the target is resolved. Opened
		-- after, it would sit under the scrim with no ring on it, and the one
		-- thing on screen you could not see would be the thing being described.
		local bags = BG.frames and BG.frames.bags
		check(bags ~= nil and bags:IsShown(),
			"the bags stop opens the REAL bag panel")
		check(OB.lifted ~= nil and OB.lifted.frame == bags,
			"and the spotlight lifts that panel out of the scrim")
		OB:Go(At("threat"))
		check(not bags:IsShown(),
			"and shuts it again on the way out")

		-- UNLESS IT WAS ALREADY OPEN, in which case it is the player's window and
		-- stays theirs.
		BG:Show()
		OB:Go(At("bags"))
		OB:Go(At("threat"))
		check(bags:IsShown(),
			"a panel that was already open is left open")
		BG:Hide()
	end

	-- AND THE THREAT STOP PUTS A REAL WARNING ON THE REAL FRAME.
	--
	-- Through Threat's own Preview, which builds the record: Draw is public and
	-- so is TIER, so onboarding COULD assemble one itself - and then two files
	-- would know what a threat record is, one of them by copy.
	do
		local uf3 = A:GetModule("unitframes")
		local pdisc
		for _, f in ipairs((uf3 and uf3.frames) or {}) do
			if f.unit == "player" then pdisc = f.orb or f.pip end
		end
		if pdisc then
			OB:Go(At("threat"))
			local ring = pdisc.__aetherThreatRing
			check(ring ~= nil and ring:IsShown() and (ring.fill or 0) > 0.5,
				"the threat stop warns on the player's own frame (" ..
				tostring(ring and ring.fill) .. ")")
			local gold = A.Palette.c.semanticGold
			local rr = ring and select(1, ring.arc:GetVertexColor())
			check(rr ~= nil and math.abs(rr - gold[1]) < 0.01,
				"in the gold that means act now (" .. tostring(rr) .. ")")

			-- AND IT COMES OFF. Left standing, a gold ring on a frame that is not
			-- in a fight is a warning about nothing for the rest of the session.
			OB:Go(At("ifec"))
			check((ring.fill or 0) == 0 or not ring:IsShown(),
				"and comes off the frame on the way out (" ..
				tostring(ring.fill) .. ")")
		end
	end

	-- AND A FIGHT MID-DEMO PUTS IT BACK TOO. Every other way out of a stop
	-- goes through Teardown, and combat is the one that arrives unasked.
	--
	-- ON THE BAG PANEL RATHER THAN THE TRACKER, and the first draft had it the
	-- other way round: the tracker has a combat rule OF ITS OWN, so the same
	-- event that tells the tour to put the fold back tells the tracker to fold.
	-- Both are right and the check was a race between two handlers - it passed
	-- and failed on alternate runs, which is worse than either.
	do
		local BG = A:GetModule("bags")
		OB:Go(At("bags"))
		local bags = BG.frames and BG.frames.bags
		check(bags ~= nil and bags:IsShown(), "stop 6 has the panel open")
		_G.__inCombat = true
		fire("PLAYER_REGEN_DISABLED")
		check(bags ~= nil and not bags:IsShown(),
			"a fight starting mid-demo shuts the panel with everything else")
		_G.__inCombat = false
		fire("PLAYER_REGEN_ENABLED")
		-- The resume reopens it, because it is stop 6 that it resumes to.
		OB:Teardown()
		BG:Hide()
	end

	-- A FIGHT TAKES IT DOWN INSTANTLY, and puts it back afterwards.
	--
	-- Not paused - dropped. A scrim over the world and a panel over your
	-- action bars are the two things you least want when a mob opens on you.
	OB:Go(At("bars"))
	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	check(not OB.scrim:IsShown() and not OB.callout:IsShown(),
		"combat drops the scrim and the callout on the spot")
	check(OB.lifted == nil,
		"and leaves nothing raised")

	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(OB.index == At("bars") and OB.callout:IsShown(),
		"and it comes back to the stop it was on when the fight ended (" ..
		tostring(OB.index) .. ")")

	-- AND STARTING IT TAKES DOWN WHATEVER IT WOULD OPEN BEHIND.
	--
	-- The tour dims the world and points at real frames, so a window still
	-- open over the top is a window over the thing being pointed at - and it
	-- is most often started FROM one, by the button on the options panel's own
	-- First run page. Reported from the game: the panel stayed up and the tour
	-- opened behind it.
	--
	-- The Ace config libraries are not loaded in here, so Options:Close is a
	-- no-op and asserting on it would prove nothing. A dialog is stood in its
	-- place instead: what is being checked is the WIRING - that Start reaches
	-- for the panel at all - which is the half that was missing.
	do
		local wasReg, wasDlg = A.Options.registered, A.Options.dialog
		local closed = nil
		A.Options.registered = true
		A.Options.dialog = { Close = function(_, app) closed = app end }

		local TB = A:GetModule("toolbox")
		TB:SetOpen(true, true)
		OB:Teardown()
		OB:Start()

		check(closed ~= nil,
			"starting the tour closes the options panel it was started from (" ..
			tostring(closed) .. ")")
		check(not TB:IsOpen(),
			"and the Toolbox drawer, which would otherwise cover the HUD the "
			.. "tour is describing")
		check(OB.card and OB.card:IsShown(),
			"and the welcome card is up, in front of nothing")

		A.Options.registered, A.Options.dialog = wasReg, wasDlg
		OB:Teardown()
	end

	-- AND IT WILL NOT START MID-FIGHT. Everything above is why.
	OB:Teardown()
	_G.__inCombat = true
	check(OB:Start() == false, "the tour refuses to start in combat")
	check(not OB.scrim:IsShown(),
		"and nothing goes up when it refuses")
	_G.__inCombat = false

	-- SKIPPING IS FINISHING. It keeps the defaults, marks the character, and
	-- never asks again - an addon that keeps asking is one you uninstall.
	OB:Start()
	OB.card.go:GetScript("OnClick")(OB.card.go)
	OB:Skip()
	check(OB:Completed(), "skipping marks the character done")
	check(not OB.scrim:IsShown() and not OB.callout:IsShown()
		and not OB.skip:IsShown(),
		"and takes the whole thing down with it")
	check(A.db.char.onboard.stopIndex == nil,
		"with nothing left to resume (" ..
		tostring(A.db.char.onboard.stopIndex) .. ")")

	-- AND THE FINISH CARD RECAPS WHAT YOU ACTUALLY CHOSE, read back out of the
	-- systems that own it rather than out of anything the tour remembered. If
	-- the recap and the HUD ever disagree, the recap is the one that is wrong.
	OB:Start()
	OB:Go(At("ifec"))
	OB:Next()
	check(OB.card:IsShown() and not OB.callout:IsShown(),
		"past the last stop is the finish card")
	do
		local said = OB.card.lines[1]:GetText() or ""
		local skin = A.Palette.skins[A.Palette.current]
		check(said:find(skin.label, 1, true) ~= nil,
			"which names the palette that is actually on (" .. said .. ")")
	end
	OB.card.go:GetScript("OnClick")(OB.card.go)
	check(OB:Completed(), "and Done marks the character done")

	A.db.char.onboard = {}
end

print("== onboarding: the first run, the resume and the alt ==")
do
	local OB = A:GetModule("onboard")
	local function At(key)
		for i, stop in ipairs(OB.stops) do
			if stop.key == key then return i end
		end
	end

	-- The character record, and the whole saved file it sits in.
	local me = A.db.keys.char
	local function fresh()
		OB:Teardown()
		OB.__arrived = nil
		OB.__pendingLogin = nil
		A.db.sv.char[me] = { onboard = {} }
		A.db.char = A.db.sv.char[me]
	end

	-- NOTHING STARTED THE TOUR AT ALL until this. Eight stops, a welcome
	-- card and a finish card were built over three builds and the only door
	-- into any of it was a slash command.
	fresh()
	fire("PLAYER_ENTERING_WORLD")
	check(not (OB.card and OB.card:IsShown()),
		"nothing opens on the loading screen itself - the frames are built and "
		.. "not yet put back where they were saved")
	_G.__drainTimers(2)
	check(OB.card and OB.card:IsShown(),
		"a beat later, a fresh character gets the welcome card")

	-- ONCE. This event arrives after EVERY loading screen, and a tour that
	-- reopened on the far side of a zone line is the thing this whole file
	-- is written to avoid.
	OB:Teardown()
	fire("PLAYER_ENTERING_WORLD")
	_G.__drainTimers(2)
	check(not OB.card:IsShown(),
		"and never again in the same session, however many zone lines")

	-- AND NEVER FOR SOMEBODY WHO HAS ANSWERED. Finishing and skipping both
	-- set this, and it is the promise that makes a first-run tour tolerable.
	fresh()
	A.db.char.onboard.completed = true
	fire("PLAYER_ENTERING_WORLD")
	_G.__drainTimers(2)
	check(not OB.card:IsShown() and not (OB.toast and OB.toast:IsShown()),
		"a character that has finished or skipped is not asked again, ever")

	-- HALF WAY THROUGH IS ONE QUIET TOAST, not the tour reopening over
	-- whatever they logged in to do.
	fresh()
	A.db.char.onboard.stopIndex = At("bags")
	fire("PLAYER_ENTERING_WORLD")
	_G.__drainTimers(2)
	check(OB.toast and OB.toast:IsShown() and not OB.card:IsShown(),
		"a half-finished character gets a toast rather than the tour")
	do
		local left = OB.COUNT - At("bags") + 1
		check(OB.toast.label:GetText() ==
			("Finish setup? %d stops left"):format(left),
			"which counts what is left, including the one they were on (" ..
			tostring(OB.toast.label:GetText()) .. ")")
	end

	-- AND IT RESUMES WHERE THEY WERE.
	OB.toast:GetScript("OnClick")(OB.toast)
	check(OB.index == At("bags") and OB.callout:IsShown()
		and not OB.toast:IsShown(),
		"clicking it picks the tour up on the stop they left (" ..
		tostring(OB.index) .. ")")

	-- DISMISSING IS SKIPPING, which is the design's own rule and the only
	-- reading that makes this a single toast rather than a nag: a dismiss
	-- that merely closed the window would be answered by another one at the
	-- next login, for ever.
	fresh()
	A.db.char.onboard.stopIndex = 3
	OB:ShowResume(3)
	OB.toast.close:GetScript("OnClick")(OB.toast.close)
	check(OB:Completed() and not OB.toast:IsShown(),
		"dismissing it marks the character done - there is never a second one")

	-- A FIGHT HOLDS IT rather than dropping it. A scrim over the world is
	-- the last thing you want when a mob opens on you at the flight point.
	fresh()
	_G.__inCombat = true
	fire("PLAYER_ENTERING_WORLD")
	_G.__drainTimers(2)
	check(not OB.card:IsShown() and OB.__pendingLogin == true,
		"arriving in combat holds the first run rather than dropping it")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	_G.__drainTimers(2)
	check(OB.card:IsShown(),
		"and the end of the fight is when it opens")

	-- AND A FILM HOLDS IT TOO.
	--
	-- THE ONE THAT ACTUALLY HAPPENS. A brand new character watches the intro
	-- movie before it can do anything at all, and the tour opened underneath
	-- it: MovieFrame hides WorldFrame for the duration, so the scrim was
	-- dimming a world that was not being drawn and the welcome card was behind
	-- a full-screen video. Reported from the game against 0.34.0 - which is to
	-- say, on the very first thing the feature was built for.
	--
	-- BOTH KINDS, because they are different frames and only one of them is
	-- the intro: MovieFrame plays the pre-rendered films, CinematicFrame the
	-- ones the engine acts out. A tour that waited for one would open over
	-- the other.
	for _, film in ipairs({ { "MovieFrame", "STOP_MOVIE" },
		{ "CinematicFrame", "CINEMATIC_STOP" } }) do
		local frame, stop = _G[film[1]], film[2]
		fresh()
		frame:Show()
		fire("PLAYER_ENTERING_WORLD")
		_G.__drainTimers(2)
		check(not OB.card:IsShown() and OB.__pendingLogin == true,
			"arriving while " .. film[1] .. " is up holds the first run")

		-- SKIPPING THE FILM IS THE SAME EVENT, so there is nothing extra to
		-- listen for: whether you watched it or pressed escape, this is what
		-- the client fires.
		frame:Hide()
		fire(stop)
		_G.__drainTimers(2)
		check(OB.card:IsShown(),
			"and " .. stop .. " is when it opens - watched or skipped, it is the "
			.. "same event")
	end

	-- AND THE HOLD SURVIVES A SECOND REASON. Whichever gate lifts last is
	-- the one that delivers it: a film that ends while a fight is on must not
	-- open the tour over the fight.
	fresh()
	_G.MovieFrame:Show()
	_G.__inCombat = true
	fire("PLAYER_ENTERING_WORLD")
	_G.__drainTimers(2)
	_G.MovieFrame:Hide()
	fire("STOP_MOVIE")
	_G.__drainTimers(2)
	check(not OB.card:IsShown() and OB.__pendingLogin == true,
		"a film ending mid-fight does not open the tour over the fight")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	_G.__drainTimers(2)
	check(OB.card:IsShown(),
		"and the last gate to lift is the one that delivers it")

	-- THE ALT OFFER.
	--
	-- A fresh character on an account already set up is being asked four
	-- questions it has answered. What there is to COPY is one thing and that
	-- is not a shortcoming: the palette, the layout and the scale live in the
	-- profile and this addon opens on the shared one, so an alt already has
	-- them - which is the whole reason the offer makes sense at all.
	do
		fresh()
		A.db.sv.char["Padreamuerto - Nek'Rosh"] = {
			onboard = { completed = true, completedAt = 100 },
			toolbox = { docked = "RIGHT" },
		}
		A.db.sv.char["Olderalt - Nek'Rosh"] = {
			onboard = { completed = true, completedAt = 50 },
			toolbox = { docked = "TOP" },
		}

		local key, who = OB:Others()
		check(who == "Padreamuerto",
			"the offer names the character who finished MOST recently, not the "
			.. "one that sorts first (" .. tostring(who) .. ")")

		OB:Go(1)
		check(OB.callout.offer:IsShown()
			and OB.callout.offer.label:GetText() == "Use Padreamuerto's setup",
			"and stop 1 carries it (" ..
			tostring(OB.callout.offer.label:GetText()) .. ")")

		-- PAST THE QUESTIONS, computed rather than written down. The deck says
		-- "jumps to stop 4", which was true while three stops set something and
		-- stopped being true the moment zen made it four.
		local TB = A:GetModule("toolbox")
		TB:SetDock("LEFT")
		OB.callout.offer:GetScript("OnClick")(OB.callout.offer)
		check(A.db.char.toolbox.docked == "RIGHT",
			"taking it copies the one thing that IS per character - the Toolbox "
			.. "edge (" .. tostring(A.db.char.toolbox.docked) .. ")")
		check(OB.index == OB:FirstShow() and OB.stops[OB.index].kind == "show",
			"and lands on the first stop that only shows something, past every "
			.. "question (" .. tostring(OB.index) .. ")")

		-- AND ON THE FIRST CHARACTER OF ALL, THERE IS NO OFFER. Nobody to
		-- borrow from is not an empty button, it is no button.
		A.db.sv.char["Padreamuerto - Nek'Rosh"] = nil
		A.db.sv.char["Olderalt - Nek'Rosh"] = nil
		OB:Go(1)
		check(not OB.callout.offer:IsShown(),
			"with nobody to borrow from there is no offer at all")
		check(OB:Others() == nil,
			"and nothing to name")
	end

	fresh()
	OB:Teardown()
end


print("")
if #FAIL == 0 then
	print("ALL CHECKS PASSED")
else
	print(#FAIL .. " FAILURE(S):")
	for _, m in ipairs(FAIL) do print("  - " .. m) end
	os.exit(1)
end
